        /// <summary>settings.xml value as a space-free log token, or "?" when absent.
        /// Used to record the display mode next to the capture self-test, so a "black"
        /// result is immediately explained rather than looking like a bug.</summary>
        private static string SettingsXmlRaw(string section, string key)
        {
            string raw;
            if (!SettingsXmlDb.TryRaw(section, key, out raw) || string.IsNullOrEmpty(raw))
                return "?";
            return raw.Replace(' ', '_');
        }
