        private long autoCollisionLastTicks = 0;
        private const long AUTO_COLLISION_COOLDOWN_TICKS = 10000000; // 1 s

        // iter-39 L2: marker damage-settling window. A marker fires on the FIRST
        // damaged frame, but the impact keeps accruing for ~1 s and the cooldown
        // above suppresses exactly those follow-up frames — so the header number is
        // the smallest one the event will ever produce. These accumulate the true
        // cost and publish it as EVENT marker-settle.
        private int markerSettleSeq = 0;
        private long markerSettleStartTicks = 0;
        private long markerSettleStartFrame = 0;
