        /// <summary>
        /// Shared budget across the split announce channels. Returns false when the
        /// utterance must be dropped, and logs the drop so a too-loose debounce is
        /// visible in the next session rather than merely audible to the driver.
        /// </summary>
        private bool CueBudgetAllows(string site)
        {
            long now = DateTime.Now.Ticks;
            if (now - cueBudgetWindowTicks > 100000000L) // 10 s
            {
                cueBudgetWindowTicks = now;
                cueBudgetCount = 0;
            }
            if (cueBudgetCount < CUE_BUDGET_PER_10S)
            {
                cueBudgetCount++;
                return true;
            }
            if (driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT cue-budget-drop:"
                    + " site=" + site + " inWindow=" + cueBudgetCount);
            return false;
        }

