        /// <summary>
        /// A stopped lead vehicle close ahead = red light / traffic queue, not a
        /// wedge. Used only to VETO arming, never to trigger anything.
        /// </summary>
        private bool InTrafficQueue()
        {
            if (navAssistDistCenter >= 8f || navAssistDistCenter >= 900f) return false;
            if (navAssistTypeCenter != "vehicle") return false;
            Vehicle lead = navAssistVehicleCenter;
            return lead != null && lead.Exists() && lead.Speed < 1f;
        }

        // ---- iter-41 Stage 4: damageDrawdownV2 ----
