        /// or, under damageDrawdownV2, by cumulative drawdown. Single funnel so all
        /// consumers agree. Both stamps are WALL clock; do not pass ModClock ticks.
        /// </summary>
        private bool DamageActiveRecently(long nowWall, long window)
        {
            if (lastBodyDropTicks > 0 && nowWall - lastBodyDropTicks < window) return true;
            return getSetting("damageDrawdownV2") == 1
                && lastDrawdownTicks > 0 && nowWall - lastDrawdownTicks < window;
        }
