        // iter-39 L1: single funnel for SET_CONTROL_VALUE_NEXT_FRAME (0xE8A25867FBA3B05E).
        // Every control write in the mod goes through here so the return value is
        // captured. Do NOT call the native directly.
        private bool WriteControlValue(int control, float value)
        {
            value = ApplyControlDeadzone(control, value);
            bool ok = Function.Call<bool>((Hash)0xE8A25867FBA3B05E, 0, control, value);
            if (driveLogger != null && driveLogger.IsRunning)
            {
                if (controlWriteLog.Length > 0) controlWriteLog.Append(',');
                controlWriteLog.Append(control).Append(':').Append(ok ? '1' : '0');
            }
            return ok;
        }

