            // iter-46 1-3 dEval/dFire deltas exist to catch.
            "roadFactsV2", "nodePropsV2", "kerbGeometryV2", "engineStuckTelemetryV2",
            "nodeQueryArgsV2", "laneWidthV2", "nodeHazardV2", "pullOverAssist",
            "engineStuckArmV2", "tempActionV2", "driveSequenceV2", "steerBiasV2",
            "gunfireAttribV2",
            // ---- iter-51 ----
            // Raises the shared speedzone brake request, so it writes a control and
            // belongs in the census. polyDistrustV2 scales the cross-track steering
            // term, so it does too.
            "roadSpeedGovernorV2", "polyDistrustV2",
        };
        private Dictionary<string, int> gateSnapshot = null;

        // ---- iter-46 1-9: HOW TO READ A `reach` COUNT ----
        // The census printed eval:N for every gate with no indication of the
        // DENOMINATOR, so `creepClearV2 eval:57453` (per frame) and
        // `accStandstillV2 eval:36` (per ACC standstill episode) looked like the
        // same kind of number and were compared as if they were. Declare it.
        private static readonly Dictionary<string, string> GATE_UNITS =
            new Dictionary<string, string>
        {
            { "shapeTestV2", "cast" }, { "accStandstillRelease", "episode" },
            { "steerFreezeAtStop", "frame" }, { "distressFloor", "frame" },
            { "actuationV2", "frame" }, { "watchdogV2", "frame" },
            { "brakePhysicsAssist", "frame" }, { "reverseV2", "episode" },
            { "brakeDeadzoneV2", "write" }, { "graceArbitrationV2", "episode" },
            { "recoverySuspendV2", "episode" }, { "recoveryTargetV2", "search" },
            { "stuckLadderV2", "eval" }, { "roadModelV2", "scan" },
            { "creepClearV2", "frame" }, { "accStandstillV2", "episode" },
            { "assistVoiceV2", "cue" }, { "throttleAuthorityV2", "frame" },
            { "damageDrawdownV2", "frame" }, { "stuckArmHysteresisV2", "eval" },
            { "offroadBrakeV2", "frame" }, { "skewGateV2", "scan" },
            { "handbrakeBandV2", "frame" }, { "nodeStreamGuardV2", "query" },
            { "actuationFeedbackV2", "frame" }, { "wheelStateV2", "frame" },
            { "roadBoundaryV2", "scan" }, { "groundNormalV2", "scan" },
            { "junctionDirectionsV2", "scan" }, { "vehicleGeometryV2", "call" },
            { "intoxDriveImpair", "frame" }, { "intoxBlackoutDrive", "frame" },
            // iter-49. The denominators differ by more than a factor of a
            // thousand across this batch, which is precisely why they are
            // declared: roadFactsV2 is sampled once per detection scan, while
            // pullOverAssist can only be reached once per press.
            { "roadFactsV2", "scan" }, { "nodePropsV2", "scan" },
            { "kerbGeometryV2", "scan" }, { "engineStuckTelemetryV2", "scan" },
            { "nodeQueryArgsV2", "query" }, { "laneWidthV2", "vertex" },
            { "nodeHazardV2", "scan" }, { "pullOverAssist", "request" },
            { "engineStuckArmV2", "eval" }, { "tempActionV2", "rung" },
            { "driveSequenceV2", "task" }, { "steerBiasV2", "write" },
            { "gunfireAttribV2", "frame" },
            // iter-51: reached once per detection scan (wherever the road-facts
            // sampler runs), fires only when it actually raises the brake request.
            { "roadSpeedGovernorV2", "scan" },
            // Reached on every Stanley evaluation that has an engine road reading;
            // fires only when the divergence actually reduced the cross-track term.
            { "polyDistrustV2", "frame" },
        };

        private static string GateUnit(string id)
        {
            string u;
            return GATE_UNITS.TryGetValue(id, out u) ? u : "?";
        }

        // ---- iter-46 1-2: ONE MANIFEST, DRIVEN BY GATE_SETTINGS ----
        //
        // There were FIVE hand-written per-iteration emitters (pinfix-gates,
        // iter40-gates, iter41-gates, iter42-gates, iter43-gates) and every new
        // iteration added a sixth. iter-44 and iter-45 never got one, so
        // intoxDriveImpair/intoxBlackoutDrive were provable only by their ABSENCE
        // from the census — in the session named after them. Meanwhile
        // triage-log.py maintained two more lists by hand
        // (TRACKED_GATE_SETTINGS 17, GATE_EXPECTED_EVENTS 20) against the mod's
        // 32, and all three had drifted apart.
        //
        // GATE_SETTINGS is now the single source of truth for the mod AND the
        // tool: the manifest names every gate it contains, so triage can derive
        // its lists from the log instead of duplicating them. A gate added later
        // cannot escape the ledger.
        private void WriteGateManifest()
        {
            if (driveLogger == null || !driveLogger.IsRunning) return;
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            sb.Append("[F").Append(driveLogFrameCount).Append("] EVENT gate-manifest:");
            sb.Append(" n=").Append(GATE_SETTINGS.Length);
            // Pure name=value, so the existing `(\w+)=(\S+)` parse in
            // triage-log.py's gate_state_at_start works unchanged. Units ride on
            // the census line, where the counts they qualify actually appear.
            for (int i = 0; i < GATE_SETTINGS.Length; i++)
                sb.Append(' ').Append(GATE_SETTINGS[i]).Append('=')
                  .Append(getSetting(GATE_SETTINGS[i]));
            driveLogger.Write(sb.ToString());
        }

        /// <summary>Where this experiment began — one per epoch, so segments are comparable.</summary>
        private void WriteTestAnchor(string why)
        {
            if (driveLogger == null || !driveLogger.IsRunning) return;
            Vehicle v = Game.Player.Character.IsInVehicle()
                ? Game.Player.Character.CurrentVehicle : null;
            GTA.Math.Vector3 p = v != null ? v.Position : Game.Player.Character.Position;
            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT test-anchor:"
                + " why=" + why
                + " pos=" + FmtV(p)
                + " heading=" + (v != null ? v.Heading : Game.Player.Character.Heading).ToString("F1")
                + " street=" + World.GetStreetName(p)
                + " model=" + (v != null ? v.DisplayName : "onfoot")
                + " bh=" + (v != null ? v.BodyHealth.ToString("F0") : "-")
                + " eh=" + (v != null ? v.EngineHealth.ToString("F0") : "-"));
        }

        private void CheckGateToggles()
        {
            if (driveLogger == null || !driveLogger.IsRunning) return;
            if (gateSnapshot == null)
            {
                gateSnapshot = new Dictionary<string, int>();
                for (int i = 0; i < GATE_SETTINGS.Length; i++)
                    gateSnapshot[GATE_SETTINGS[i]] = getSetting(GATE_SETTINGS[i]);
                return; // startup state is already on the gates lines
            }
            bool changed = false;
            for (int i = 0; i < GATE_SETTINGS.Length; i++)
            {
                string id = GATE_SETTINGS[i];
                int now = getSetting(id);
                int was;
                if (!gateSnapshot.TryGetValue(id, out was)) was = -1;
                if (now == was) continue;
                gateSnapshot[id] = now;
                changed = true;
                Vehicle v = Game.Player.Character.IsInVehicle()
                    ? Game.Player.Character.CurrentVehicle : null;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT gate-toggle:"
                    + " name=" + id
                    + " from=" + was
                    + " to=" + now
                    + " src=menu"
                    + " pos=" + FmtV(v != null ? v.Position : Game.Player.Character.Position)
                    + " street=" + World.GetStreetName(
                        v != null ? v.Position : Game.Player.Character.Position)
                    + " model=" + (v != null ? v.DisplayName : "onfoot")
                    + " spd=" + (v != null ? v.Speed.ToString("F1") : "0.0"));
            }
            if (changed)
            {
                WriteTestAnchor("gate-toggle");
                WriteGateManifest();
            }
        }

        // ---- iter-41 Stage 0.3: GATE CENSUS ----
        // reach = the gate's own condition was evaluated with the setting ON.
        // fire  = the guarded action actually executed.
        // "reach 0" (never got there) and "reach N / fire 0" (got there, declined)
        // are DIFFERENT bugs, and until now they were indistinguishable in the log.
        private readonly Dictionary<string, int> gateReach = new Dictionary<string, int>();
        private readonly Dictionary<string, int> gateFire = new Dictionary<string, int>();
        // iter-46 1-4/1-5: some gates' guarded action is a VETO — the gate fires by
        // REFUSING. creepClearV2's counter sat on the creepNoCast branch, so
        // `fire:1909` read as "the creep ran 1909 times" and meant the exact
        // opposite; stuckArmHysteresisV2's sat on the `else` of a budget hit.
        // Count vetoes separately so the census cannot be read backwards.
        private readonly Dictionary<string, int> gateVeto = new Dictionary<string, int>();
        // iter-46 1-3: previous census values, for per-interval deltas.
        private readonly Dictionary<string, int> gateReachPrev = new Dictionary<string, int>();
        private readonly Dictionary<string, int> gateFirePrev = new Dictionary<string, int>();
        // iter-46 1-10: when each gate was first seen ON, so a gate that is ON and
        // has never been reached can say so instead of being silently absent.
        private readonly Dictionary<string, long> gateOnSinceTicks = new Dictionary<string, long>();
        private readonly HashSet<string> gateQuietReported = new HashSet<string>();
        private long lastGateCensusTicks = 0;

        private void GateReach(string id)
        {
            int n;
            gateReach[id] = gateReach.TryGetValue(id, out n) ? n + 1 : 1;
        }

        private void GateFire(string id)
        {
            int n;
            gateFire[id] = gateFire.TryGetValue(id, out n) ? n + 1 : 1;
        }

        /// <summary>The gate was reached and DECLINED to act. Not a fire.</summary>
        private void GateVeto(string id)
        {
            int n;
            gateVeto[id] = gateVeto.TryGetValue(id, out n) ? n + 1 : 1;
        }

        private void WriteGateCensus()
        {
            if (driveLogger == null || !driveLogger.IsRunning) return;
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            sb.Append("[F").Append(driveLogFrameCount).Append("] EVENT gate-census:");
            for (int i = 0; i < GATE_SETTINGS.Length; i++)
            {
                string id = GATE_SETTINGS[i];
                int on = getSetting(id);
                if (on != 1)
                {
                    gateOnSinceTicks.Remove(id);
                    continue;               // an OFF gate needs no evidence
                }
                if (!gateOnSinceTicks.ContainsKey(id))
                    gateOnSinceTicks[id] = ModClock.Ticks; // ModClock pair
                int r, f, v, rp, fp;
                gateReach.TryGetValue(id, out r);
                gateFire.TryGetValue(id, out f);
                gateVeto.TryGetValue(id, out v);
                gateReachPrev.TryGetValue(id, out rp);
                gateFirePrev.TryGetValue(id, out fp);
                gateReachPrev[id] = r;
                gateFirePrev[id] = f;
                sb.Append(' ').Append(id).Append("=on/eval:").Append(r).Append("/fire:").Append(f);
                if (v > 0) sb.Append("/veto:").Append(v);
                // iter-46 1-3: DELTAS SINCE THE LAST CENSUS. Cumulative totals hide a
                // gate that dies mid-session: on 07-31 junctionDirectionsV2's fire
                // count froze at 4048 from ~F28000 while eval climbed 8668->21595, and
                // skewGateV2's froze at 140 on 08-01 — both printed ACTIVE because the
                // digest only ever read the LAST census line. A zero dFire beside a
                // large dEval names it on one line, without differencing a series.
                sb.Append("/dEval:").Append(r - rp).Append("/dFire:").Append(f - fp);
                // iter-46 1-9: the denominator. eval:57453 (per frame) and eval:36
                // (per episode) are not the same kind of number.
                sb.Append('/').Append(GateUnit(id));

                // iter-46 1-10: A GATE THAT CANNOT SAY WHY IT IS QUIET IS NOT
                // INSTRUMENTED. 12 of 32 gates censused eval:0/fire:0 on 07-31 —
                // including actuationV2, which runs every single frame — and the
                // digest rendered that as "SILENT — never reached", indistinguishable
                // from a genuinely unreachable gate. Once a gate has been ON for a
                // minute with zero evaluations, say so explicitly, once. Modelled on
                // the gen-dir-skip idiom, which is why junctionDirectionsV2's silence
                // was the one silence in the log that could actually be explained.
                if (r == 0 && !gateQuietReported.Contains(id)
                    && ModClock.Ticks - gateOnSinceTicks[id] > 600000000L) // 60 s, ModClock pair
                {
                    gateQuietReported.Add(id);
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT gate-quiet:"
                        + " name=" + id
                        + " unit=" + GateUnit(id)
                        + " onForMs=" + ((ModClock.Ticks - gateOnSinceTicks[id]) / 10000)
                        + " why=no-GateReach-call-site"
                        + " note=uninstrumented-not-unreached");
                }
            }
            driveLogger.Write(sb.ToString());
        }

        private void HoldThrottle(int site)
        {
            Function.Call(Hash.DISABLE_CONTROL_ACTION, 0, 71, true); // VEH_ACCELERATE
            thrHoldSitesThisFrame |= site;
        }

        // ---- iter-41 Stage 0.7: IMMOBILE UNDER THROTTLE ----
        // The driver is asking to move and the car is not moving. On 07-28 this
        // happened four times for 28.3 s total and produced no event of any kind —
        // the session's dominant behaviour was reconstructable only from raw FRAME
        // blocks. Deliberately silent: Stage 2 owns the speech.
        private bool immobileUnderThrottleActive = false;
        private long immobileSinceTicks = 0;          // wall clock
        private long immobileLastBeatTicks = 0;
        private float immobileStartBh = 0f;
        private float immobileStartEh = 0f;
        private const long IMMOBILE_ARM_TICKS = 30000000L;   // 3 s
        private const long IMMOBILE_BEAT_TICKS = 50000000L;  // 5 s
        // ---- iter-43 B3: this detector now OWNS the stranded-driver cue ----
        // Stage 2b's cue lives on the throttle-hold ledger, which is scoped to a
        // single hold EPISODE. During the 07-31 strand ACC released and re-held
        // roughly twice a second, so no episode ever reached the 700 ms bar and
        // only 102 of 6,531 holds were ever spoken. The driver sat for 32 s in
        // silence. This detector is the right owner because it survives that
        // churn: it measures "asking to go and not moving", not "one hold".
        private long immobileLastSpokenTicks = 0;
        private const long IMMOBILE_RESPEAK_TICKS = 120000000L;  // 12 s

        private void UpdateImmobileUnderThrottle(long nowWall, Vehicle veh)
        {
            bool logging = driveLogger != null && driveLogger.IsRunning;
            bool asking = veh != null && lastPlayerThrottleRaw >= 0.9f && veh.Speed < 2.0f;
            if (!asking)
            {
                if (immobileUnderThrottleActive && logging)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT immobile-under-throttle:"
                        + " phase=end"
                        + " ms=" + ((nowWall - immobileSinceTicks) / 10000L)
                        + " navC=" + FmtF(navAssistDistCenter)
                        + " navCt=" + (navAssistTypeCenter ?? "none")
                        + " owner=" + ComputeBrakeOwner()
                        + " thrSites=" + ThrHoldSiteNames(thrHoldSitesThisFrame)
                        + " bhDelta=" + (veh != null
                            ? (veh.BodyHealth - immobileStartBh).ToString("F1") : "-")
                        + " ehDelta=" + (veh != null
                            ? (veh.EngineHealth - immobileStartEh).ToString("F1") : "-")
                        + " mode=" + currentDriveMode
                        + " spd=" + (veh != null ? veh.Speed.ToString("F1") : "-"));
                immobileUnderThrottleActive = false;
                immobileSinceTicks = 0;
                return;
            }
            if (immobileSinceTicks == 0)
            {
                immobileSinceTicks = nowWall;
                immobileStartBh = veh.BodyHealth;
                immobileStartEh = veh.EngineHealth;
                return;
            }
            long heldMs = (nowWall - immobileSinceTicks) / 10000L;
            if (!immobileUnderThrottleActive)
            {
                if (nowWall - immobileSinceTicks < IMMOBILE_ARM_TICKS) return;
                immobileUnderThrottleActive = true;
                immobileLastBeatTicks = nowWall;
                if (logging)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT immobile-under-throttle:"
                        + " phase=start"
                        + " ms=" + heldMs
                        + " navC=" + FmtF(navAssistDistCenter)
                        + " navCt=" + (navAssistTypeCenter ?? "none")
                        + " owner=" + ComputeBrakeOwner()
                        + " thrSites=" + ThrHoldSiteNames(thrHoldSitesThisFrame)
                        + " ctrlT=" + Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71).ToString("F2")
                        + " mode=" + currentDriveMode
                        + " spd=" + veh.Speed.ToString("F1"));
                return;
            }
            if (nowWall - immobileLastBeatTicks >= IMMOBILE_BEAT_TICKS)
            {
                immobileLastBeatTicks = nowWall;
                if (logging)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT immobile-under-throttle:"
                        + " phase=hold"
                        + " ms=" + heldMs
                        + " navC=" + FmtF(navAssistDistCenter)
                        + " navCt=" + (navAssistTypeCenter ?? "none")
                        + " owner=" + ComputeBrakeOwner()
                        + " thrSites=" + ThrHoldSiteNames(thrHoldSitesThisFrame)
                        + " bhDelta=" + (veh.BodyHealth - immobileStartBh).ToString("F1")
                        + " mode=" + currentDriveMode
                        + " spd=" + veh.Speed.ToString("F1"));
            }
            SpeakImmobileReason(nowWall, heldMs);
        }

        /// <summary>
        /// iter-43 B3: tell a blind driver why flooring the pedal is doing nothing.
        /// Called only while immobile-under-throttle is armed (>=3 s of asking to go
        /// below 2 m/s), so it cannot fire on a normal stop. Speech.Info, never
        /// Critical, so it can never delay a threat cue.
        /// </summary>
        private void SpeakImmobileReason(long nowWall, long heldMs)
        {
            if (getSetting("assistVoiceV2") != 1) return;
            if (nowWall - immobileLastSpokenTicks < IMMOBILE_RESPEAK_TICKS) return;
            GateReach("assistVoiceV2");
            if (!CueBudgetAllows("immobile")) return;
            string o = ComputeBrakeOwner();
            bool leadVeh = navAssistTypeCenter == "vehicle";
            string line;
            if (leadVeh && navAssistDistCenter < 8f)
                // The 07-31 case: a stationary car in the lane, held as a "queue".
                // Naming it is what lets the driver decide to steer around.
                line = "Stopped behind a vehicle that is not moving.";
            else if (o == "reverse" || o == "recovery")
                line = "Backing out. Pedal held.";
            else if (o == "emergency" || o == "handbrake")
                line = "Braking for an obstacle. Pedal held.";
            else if (navAssistDistCenter < 3f)
                line = "Blocked ahead. Pedal held.";
            else
                line = "Not moving. Pedal held.";
            // After a long strand, say how long — it is the difference between
            // "the mod is thinking" and "the mod is stuck".
            if (heldMs >= 15000L) line += " " + (heldMs / 1000L) + " seconds.";
            Speech.Info(line);
            immobileLastSpokenTicks = nowWall;
            GateFire("assistVoiceV2");
        }

        private static string ThrHoldSiteNames(int mask)
        {
            if (mask == 0) return "-";
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            if ((mask & THR_SITE_MAIN) != 0) sb.Append("main,");
            if ((mask & THR_SITE_GIVEUP) != 0) sb.Append("giveup,");
            if ((mask & THR_SITE_GRACE) != 0) sb.Append("grace,");
            if ((mask & THR_SITE_WATCHDOG) != 0) sb.Append("watchdog,");
            if ((mask & THR_SITE_LOCKOUT) != 0) sb.Append("lockout,");
            if ((mask & THR_SITE_HANDBRAKE) != 0) sb.Append("handbrake,");
            if ((mask & THR_SITE_REVERSE) != 0) sb.Append("reverse,");
            if (sb.Length > 0) sb.Length -= 1;
            return sb.ToString();
        }

        // iter-41 Stage 0.1: hoisted out of LogDriveAssistFrame so the ledger and
        // the FRAME line report the SAME owner. Previously this chain existed only
        // inside the logger, so nothing else in the mod could name the owner.
        private string ComputeBrakeOwner()
        {
            return emergencyBrakeActive            ? "emergency"
                 : alignmentEngageReverse          ? "reverse"
                 : cachedHandbrakeMagnitude > 0.05f ? "handbrake"
                 : recoveryBrakeRequest > 0.05f    ? "recovery"
                 : (junctionBrakeRequest > 0.05f
                    && junctionBrakeRequest + 0.001f >= curveBrakeRequest) ? "junction"
                 : (speedZoneBrakeRequest > 0.05f
                    && speedZoneBrakeRequest + 0.001f >= curveBrakeRequest) ? "speedzone"
                 // iter-49 A4: give way rides the same curveBrakeRequest channel as
                 // junction and speedzone, so without its own rung it would print
                 // as owner=curve — the exact invisibility iter-33 fixed for
                 // lane-depart.
                 : (giveWayBrakeRequest > 0.05f
                    && giveWayBrakeRequest + 0.001f >= curveBrakeRequest) ? "giveway"
                 : (lastLaneDepartBrakeReq > 0.05f
                    && lastLaneDepartBrakeReq + 0.001f >= curveBrakeRequest) ? "lanedepart"
                 : curveBrakeRequest > 0.05f       ? "curve"
                 : accBrakeOut > 0.05f             ? "acc"
                 : rampedBrakeInput > 0.05f        ? "ramped"
                 : "none";
        }

        // Which term of brakeIntervening actually took the pedal. "A hold with no
        // named reason" is itself a finding: on 07-28 owner=none on 1,485 held frames.
        private string ThrottleHoldReason()
        {
            if (emergencyBrakeActive) return "emergency";
            if (brakeArmed) return "armed";
            if (rampedBrakeInput > 0.05f) return "ramped";
            if (lastLiveBrakeTarget > 0.05f) return "liveTarget";
            if (cachedHandbrakeMagnitude > 0.1f || alignmentEngageReverse
                || stuckAutodriveEngaged) return "takeover";
            return "other";
        }

        /// <summary>
        /// Opens/extends/closes a throttle-hold episode. Called at the top of
        /// ApplyCachedSteeringInputs so every disable site of the PREVIOUS frame has
        /// run. Emits edge events only — tens of lines per session, not 11,785.
        /// </summary>
        private void UpdateThrottleHoldLedger(long nowWall, Vehicle veh)
        {
            int sites = thrHoldSitesPrevFrame;
            float spd = veh != null ? veh.Speed : 0f;
            float thr = lastPlayerThrottleRaw;
            bool logging = driveLogger != null && driveLogger.IsRunning;
            if (sites != 0)
            {
                if (thrHoldSinceTicks == 0)
                {
                    thrHoldSinceTicks = nowWall;
                    thrHoldFrames = 0;
                    thrHoldSitesUnion = 0;
                    thrHoldPeakThrP = 0f;
                    thrHoldMaxSpd = 0f;
                    thrHoldV0 = spd;
                    thrHoldSpoken = false;
                    thrHoldFramesAtThrP90 = 0;
                    thrHoldFramesSpdGt5 = 0;
                    thrHoldOwner = ComputeBrakeOwner();
                    thrHoldReason = ThrottleHoldReason();
                    if (logging)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT throttle-hold-start:"
                            + " site=" + ThrHoldSiteNames(sites)
                            + " owner=" + thrHoldOwner
                            + " reason=" + thrHoldReason
                            + " thrP=" + thr.ToString("F2")
                            + " spd=" + spd.ToString("F1")
                            + " navC=" + FmtF(navAssistDistCenter)
                            + " navCt=" + (navAssistTypeCenter ?? "none")
                            + " ttc=" + FmtF(threatTimeToCollision));
                }
                thrHoldFrames++;
                thrHoldSitesUnion |= sites;
                if (thr > thrHoldPeakThrP) thrHoldPeakThrP = thr;
                if (spd > thrHoldMaxSpd) thrHoldMaxSpd = spd;
                if (thr >= 0.9f) thrHoldFramesAtThrP90++;
                if (spd > 5f) thrHoldFramesSpdGt5++;

                // ---- iter-41 Stage 2b: TELL THE DRIVER WHY THE PEDAL IS DEAD ----
                // The core UX defect is not that the mod holds the pedal — usually it
                // is right to. It is that a blind driver gets NO signal that it
                // happened. Requires the driver to actually be asking to go
                // (thr >= 0.6 sustained), so this cannot fire in a red-light queue.
                // Speech.Info, never Critical, so it can never delay a threat cue.
                long holdMs = (nowWall - thrHoldSinceTicks) / 10000L;
                if (getSetting("assistVoiceV2") == 1 && !thrHoldSpoken
                    && holdMs >= 700L && thrHoldPeakThrP >= 0.6f
                    && !takeoverDebouncedState   // "Assist driving" already covers this
                    && nowWall - lastPedalHeldCueTicks > 60000000L) // 6 s
                {
                    GateReach("assistVoiceV2");
                    if (CueBudgetAllows("pedal-held"))
                    {
                        string o = thrHoldOwner ?? "";
                        string line =
                              (o == "emergency" || o == "handbrake" || o == "ramped"
                               || o == "recovery" || o == "reverse")
                                ? "Braking. Pedal held."
                            : (o == "lanedepart") ? "Holding speed. Off the line."
                            : (o == "curve") ? "Holding speed for the curve."
                            : (o == "junction" || o == "speedzone") ? "Holding speed."
                            : (o == "acc") ? "Holding behind traffic."
                            : "Pedal held.";
                        Speech.Info(line);
                        lastPedalHeldCueTicks = nowWall;
                        thrHoldSpoken = true;
                        GateFire("assistVoiceV2");
                    }
                }
            }
            else if (thrHoldSinceTicks != 0)
            {
                long ms = (nowWall - thrHoldSinceTicks) / 10000L;
                thrHoldCumMs += ms;
                if (logging)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT throttle-hold-end:"
                        + " ms=" + ms
                        + " frames=" + thrHoldFrames
                        + " sites=" + ThrHoldSiteNames(thrHoldSitesUnion)
                        + " owner=" + (thrHoldOwner ?? "-")
                        + " reason=" + (thrHoldReason ?? "-")
                        + " peakThrP=" + thrHoldPeakThrP.ToString("F2")
                        + " spd0=" + thrHoldV0.ToString("F1")
                        + " spdEnd=" + spd.ToString("F1")
                        + " maxSpd=" + thrHoldMaxSpd.ToString("F1")
                        + " dv=" + (spd - thrHoldV0).ToString("F1")
                        + " spoken=" + thrHoldSpoken
                        + " framesAtThrP90=" + thrHoldFramesAtThrP90
                        + " framesSpdGt5=" + thrHoldFramesSpdGt5
                        + " cumMs=" + thrHoldCumMs);
                thrHoldSinceTicks = 0;
            }
        }

        // iter-40 brakeDeadzoneV2. The injected brake control has a hard dead zone:
        // the engine normalises the written value before physics reads it, so a
        // commanded 0.20 delivers NOTHING and a commanded 0.35 delivers 0.13.
        //
        // Measured over the whole 07-28 session on frames where rampedBrake was
        // unchanged from the previous frame (which removes the one-frame write lag),
        // suspended=False, handbrake clear — commanded vs GET_CONTROL_NORMAL(0,72):
        //
        //   cmd  0.10  0.20  0.25  0.30  0.35  0.40  0.60
        //   got  0.000 0.000 0.000 0.060 0.130 0.200 0.470
        //
        // which fits delivered = max(0, (cmd - 0.25) / 0.75) to within +/-0.02 across
        // 10..353 samples per bucket. Inverting it makes a commanded value mean what
        // it says. This matters most for exactly the commands that were silently
        // doing nothing: LANE_DEPART_BRAKE_CAP = 0.35 was delivering 0.13, and the
        // whole 0 -> 0.25 rise of every brake ramp was inert.
        //
        // Only control 72 is compensated. Steering (59) is measured monotonic and
        // strong already (0.5 command -> 24 deg/s), throttle (71) is only ever
        // written as 0 for the lockout, and the handbrake (76) is effectively a
        // boolean at the values the mod uses.
        private const float BRAKE_CONTROL_DEADZONE = 0.25f;

        // Cached per tick. WriteControlValue is the hottest path in the mod (several
        // calls per frame at 60 fps) and getSetting is an unindexed linear scan over
        // the whole settings list — it must not be called from here.
        private bool brakeDeadzoneV2Cached = false;

        // iter-51: same reason — the FRAME writer wants to know whether the second
        // steering channel is live without an O(n) settings scan per logged frame.
        private bool steerBiasV2Cached = false;
        // iter-51: read by the telemetry sampler so it can share the control law's
        // steering denominator WITHOUT calling VehicleGeometryOn(), which would
        // credit a behaviour gate's reach counter for a pure measurement.
        private bool geometryV2Cached = false;

        private float ApplyControlDeadzone(int control, float value)
        {
            if (control != 72) return value;
            if (!brakeDeadzoneV2Cached) return value;
            // iter-46 1-1: unit=write — every brake control write passes through here,
            // which is why the gate's eval:0/fire:0 was so obviously an artifact: the
            // same session logged 134 brake-episodes. reach = a brake write while the
            // gate is on; fire = the dead-zone actually rescaled the value.
            GateReach("brakeDeadzoneV2");
            // A genuine zero must stay zero — releasing the brake must release it.
            if (value <= 0.001f) return value;
            if (value >= 1f) return 1f;
            GateFire("brakeDeadzoneV2");
            return BRAKE_CONTROL_DEADZONE + value * (1f - BRAKE_CONTROL_DEADZONE);
        }

        // True when the first-contact emergency-brake path latched a max-brake request.
        // Read by ApplyCachedSteeringInputs to force cachedBrakeMagnitude = 1.0 until
        // the obstacle leaves the critical zone.
        private bool emergencyBrakeActive = false;

        // Cached closest brake-relevant threat position & detection timestamp. Used by
        // ApplyCachedSteeringInputs to recompute TTC every frame against the live
        // vehicle speed/position (between the ~50 ms full re-scans), so player input
        // changes and threat motion are reflected in real time.
        private GTA.Math.Vector3 cachedBrakeThreatPos = GTA.Math.Vector3.Zero;
        private GTA.Math.Vector3 cachedBrakeThreatVel = GTA.Math.Vector3.Zero;
        private long cachedBrakeThreatStamp = 0;
        // First-seen tracking for the cached brake threat. The Stamp field is
        // refreshed every frame the scan reconfirms the threat — useless for
        // staleness when the cache is being continuously re-confirmed by a curb
        // or roadside feature. FirstSeenStamp captures when the threat was
        // initially noticed (only reset when the cache actually clears) plus the
        // player position at that moment, so we can detect the F4137-style
        // "stuck against same spot, cache never clears" pattern.
        private long cachedBrakeThreatFirstSeenStamp = 0;
        private GTA.Math.Vector3 cachedBrakeThreatFirstSeenPlayerPos = GTA.Math.Vector3.Zero;
        // Iter-11 Patch I: 3-frame distance history for the drove-past
        // confirmation. The legacy single-frame fwdDot<=0.15 predicate fires
        // on momentary heading swings during evasion — F5650 in
        // driveassist-2026-05-27-171958 cleared the cache 26 times in 1 sec
        // before the -84.8 health impact. We now require BOTH fwdDot<=0.15
        // AND distance-to-threat rose by >0.5 m across the last 3 frames.
        // The history is reset when the cache clears, on teleport-reset,
        // and when a new threat replaces a different one.
        private float[] cachedBrakeDistHistory = new float[3];
        private int cachedBrakeDistIdx = 0;
        private bool cachedBrakeDistHistoryValid = false;
        // Same for the closest steer-relevant threat.
        private GTA.Math.Vector3 cachedSteerThreatPos = GTA.Math.Vector3.Zero;
        private GTA.Math.Vector3 cachedSteerThreatVel = GTA.Math.Vector3.Zero;
        private long cachedSteerThreatStamp = 0;
        // How long a cached threat remains "trusted" (5 detection cycles ~ 250 ms).
        // Beyond this we don't try to recompute — wait for the next full scan.
        private const long THREAT_CACHE_VALID_TICKS = 2500000; // 250 ms
        // Iter-11 Patch J: speed-scaled cache validity. A 250 ms-old threat
        // position is 4 m off at 16 m/s and 6 m off at 25 m/s — exactly the
        // F2894 (-102.6 health) error magnitude. Floor at 800000 ticks (80 ms)
        // so we never starve under the next full scan's latency. Used at the
        // hasLiveBrakeThreat staleness check in ApplyCachedSteeringInputs.
        private const long THREAT_CACHE_VALID_TICKS_MIN = 800000; // 80 ms floor
        private long ThreatCacheValidTicksForSpeed(float speedMs)
        {
            // At 8 m/s -> 2,500,000 (unchanged 250 ms).
            // At 16 m/s -> 1,250,000 (125 ms).
            // At 25 m/s -> 800,000 (80 ms floor).
            float scale = 8f / Math.Max(8f, speedMs);
            long scaled = (long)(THREAT_CACHE_VALID_TICKS * scale);
            return Math.Max(THREAT_CACHE_VALID_TICKS_MIN, scaled);
        }

        // Brake input ramps toward target at this rate (per second). 5.0 means a full
        // 0 → 1 transition takes 200 ms — fast enough for emergencies, smooth enough
        // not to feel like a slam.
        private const float BRAKE_RAMP_RATE = 5.0f;
        // Iter-11 Patch M: asymmetric urgent-up ramp rate. The default 5.0/sec
        // (0->1 in 200 ms) is the right comfort shape for routine brakes but
        // 200 ms is too long when liveBrakeTarget jumps from 0 to high
        // magnitude at highway speed — driveassist-2026-05-27-171958 F3542
        // (-83.2 health) impact happened with rampedBrake=0.341 because the
        // ramp was still climbing from 0. URGENT path: when the target leaps
        // ahead of the ramp by >0.3 AND speed > 10 m/s, ramp up at 12/sec
        // (0->1 in 83 ms). Down-ramp stays at the comfort rate so brake
        // release isn't grabby.
        private const float BRAKE_RAMP_RATE_URGENT = 12.0f;

        // Lane-keeping state. lastRoadCorrection is the previous frame's raw road
        // steer output; we use it to rate-limit changes so a noisy lookahead point
        // can't whip the wheel back and forth ("drives in circles" complaint).
        private float lastRoadCorrection = 0f;
        // Below this pursuit angle (degrees) the lane-keeping system contributes ZERO
        // steering. This deadband is the single biggest fix for the oscillation bug:
        // on a straight road, suspension/road-node noise produces ~1° heading jitter,
        // and the previous proportional-only controller chased that noise into
        // ever-growing corrections.
        private const float LANE_DEADBAND_DEGREES = 2.0f;
        // Lateral deadband (metres): tolerate small cross-track drift before nudging.
        private const float LANE_LATERAL_DEADBAND_METERS = 0.75f;
        // Max change in lane-keeping correction per second. Smaller = smoother, less
        // oscillation, but slower response to genuine curves. 1.5 is enough to track
        // a normal city corner taken at moderate speed.
        private const float LANE_CORRECTION_RATE = 1.5f;
        // Lane width assumption used by IsObstacleInTravelLane when MapDb returns
        // no road match. Overridden by per-road-type values from LANE_PRESETS.
        private const float LANE_DEFAULT_WIDTH = 3.5f;

        // Road-type-aware lane-keeping presets. Looser on highways (where wheel
        // jitter is amplified by speed and a strict deadband would feel grabby),
        // tighter in alleys (where the car is centimetres from walls and any drift
        // is meaningful). The "surface" / unknown fallback matches the legacy
        // constants above so behaviour is unchanged when MapDb is empty.
        private struct LanePreset { public float deadbandDeg, lateralM, rate, widthM; }
        private static LanePreset GetLanePreset(string roadType)
        {
            switch (roadType)
            {
                case "freeway":
                    return new LanePreset { deadbandDeg = 3.5f, lateralM = 1.5f,  rate = 0.9f, widthM = 4.0f };
                case "highway":
                    return new LanePreset { deadbandDeg = 3.0f, lateralM = 1.2f,  rate = 1.0f, widthM = 3.8f };
                case "alley":
                    return new LanePreset { deadbandDeg = 1.5f, lateralM = 0.4f,  rate = 2.0f, widthM = 2.5f };
                default: // surface, unknown
                    return new LanePreset {
                        deadbandDeg = LANE_DEADBAND_DEGREES,
                        lateralM    = LANE_LATERAL_DEADBAND_METERS,
                        rate        = LANE_CORRECTION_RATE,
                        widthM      = LANE_DEFAULT_WIDTH,
                    };
            }
        }
        private bool wasObstacleInBrakeZone = false; // Track latched emergency-brake critical-zone state (release-hysteresis gated)
        private int criticalZoneArmFrames = 0;        // Consecutive enter-frames; arm only after CRITICAL_ARM_FRAMES

