                            + "iter-23: K1:eject-groundtruth K2:poly-hold K3:water-fp K4:suspend-resume; "
                            + "iter-24: L1:curve-uncap L2:curve-lookahead L3:junction-slow "
                            + "R1:recovery-brakefirst R2:recovery-flip-reject U1:grace-lowspeed-brake "
