                // ============================================
                // AUTO-NAVIGATION START (NumPad Multiply)
                // Starts auto-drive, aircraft autopilot, or auto-walk
                // depending on whether player is in vehicle, aircraft, or on foot
                // ============================================
                if (e.KeyCode == Keys.Multiply && !keyState[15])
                {
                    keyState[15] = true;
                    bool autonavWasActiveAtKey = isAutodriving; // iter-35 L3

                    if (isAutodriving)
                    {
                        // Cancel any active auto-navigation
                        isAutodriving = false; autodriveSequenceActive = false;
                        autodriveWanderMode = false;
                        autodrivePhase = AutodrivePhase.Cruise; // reset hybrid final-approach machine
                        autodriveVehicleHandle = 0;
                        flightChainToWaypoint = false;
                        heliTaxiActive = false;
                        heliTaxiPhase = 0;
                        planeLandingStartTicks = 0;
                        planeLandingAttempts = 0;
                        planeGoAroundCooldownUntil = 0;
                        planeStallSinceTicks = 0;
                        // Clear tasks on whoever is driving (Butler, NPC pilot, or player) —
                        // without the NPC-pilot case, cancelling an AI-piloted flight left
                        // the pilot still flying his mission.
                        if (guardDriverActive && IsButlerValid())
                            bodyguards[0].Task.ClearAllImmediately();
                        else if (requestedFlightPilot != null && requestedFlightPilot.Exists()
                                 && !requestedFlightPilot.IsDead)
                            requestedFlightPilot.Task.ClearAllImmediately();
                        else
                            Game.Player.Character.Task.ClearAll();
                        if (autonavMode == "fly")
                            Speech.Ambient("Autopilot disengaged. You have control.");
                        else if (autonavMode == "walk")
                            Speech.Ambient("Auto-walk cancelled. You have control.");
                        else
                            Speech.Ambient("Auto-drive cancelled. You have control.");
                        // iter-35 L3: the Multiply handler spoke but never logged —
                        // a session with zero autodrive-phase events couldn't
                        // distinguish "never used" from "cancelled during Cruise".
                        if (driveLogger != null && driveLogger.IsRunning)
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT autonav:"
                                + " action=cancel mode=" + autonavMode);
                        autonavMode = "drive";
                    }
                    else if (Game.Player.Character.IsInVehicle())
                    {
                        Vehicle veh = Game.Player.Character.CurrentVehicle;
                        Ped driver = (guardDriverActive && bodyguards.Count > 0 && bodyguards[0] != null && bodyguards[0].IsAlive) ? bodyguards[0] : Game.Player.Character;
                        int vehClass = Function.Call<int>(Hash.GET_VEHICLE_CLASS, veh);

                        // Check if waypoint exists
                        bool hasWaypoint = Function.Call<bool>(Hash.IS_WAYPOINT_ACTIVE);

                        // vehClass 15 = Helicopters, 16 = Planes
                        if (vehClass == 15 || vehClass == 16)
                        {
                            // ============================================
                            // AIRCRAFT AUTOPILOT
                            // ============================================
                            autonavMode = "fly";
                            bool isHeli = (vehClass == 15);

                            if (hasWaypoint)
                            {
                                int waypointBlipHandle = Function.Call<int>(Hash.GET_FIRST_BLIP_INFO_ID, 8);
                                GTA.Math.Vector3 waypointPos = Function.Call<GTA.Math.Vector3>(Hash.GET_BLIP_INFO_ID_COORD, waypointBlipHandle);

                                // Set target altitude above ground level
                                float groundZ = World.GetGroundHeight(new GTA.Math.Vector2(waypointPos.X, waypointPos.Y));
                                if (groundZ > 0)
                                    waypointPos.Z = groundZ + autopilotAltitude;
                                else
                                    waypointPos.Z = autopilotAltitude;

                                autodriveDestination = waypointPos;

                                GTA.Math.Vector3 playerPos = Game.Player.Character.Position;
                                autodriveStartDistance = World.GetDistance(playerPos, waypointPos);

                                if (isHeli)
                                {
                                    // TASK_HELI_MISSION: ped, vehicle, targetVeh(0), targetPed(0), x, y, z, missionType, speed, radius, heading, maxAlt, minAlt, slowDownDist, behaviorFlags
                                    // MissionType 4 = go to coord
                                    Function.Call(Hash.TASK_HELI_MISSION,
                                        driver, veh, 0, 0,
                                        waypointPos.X, waypointPos.Y, waypointPos.Z,
                                        4,                    // mission type: go to coord
                                        autodriveSpeed,       // cruise speed
                                        20f,                  // target radius
                                        -1f,                  // heading (-1 = any)
                                        (int)(waypointPos.Z + 100), // max altitude
                                        (int)(waypointPos.Z - 50),  // min altitude
                                        -1f,                  // slow down distance
                                        0);                   // behavior flags
                                }
                                else
                                {
                                    // Plane — initialize phase machine and let ReissueFlightMission
                                    // pick the right mission (Takeoff/Cruise/Landing).
                                    planePhase = veh.IsOnAllWheels ? PlanePhase.Takeoff : PlanePhase.Cruise;
                                    planeLandingRunwayIndex = FindNearestRunwayIndex(waypointPos);
                                    autodriveDestination = waypointPos;
                                    ReissueFlightMission();
                                }

                                isAutodriving = true;
                                autodriveWanderMode = false;
                                autodriveVehicleHandle = veh.Handle;
                                planeLandingStartTicks = 0;
                                planeLandingAttempts = 0;
                                planeGoAroundCooldownUntil = 0;
                                planeStallSinceTicks = 0;
                                autodriveCheckTicks = DateTime.Now.Ticks;

                                int speedMph = (int)Math.Round(autodriveSpeed * 2.23694);
                                string acType = isHeli ? "Helicopter" : "Plane";
                                string phaseStr = "";
                                if (!isHeli)
                                {
                                    if (planePhase == PlanePhase.Takeoff) phaseStr = " Taking off.";
                                    if (planeLandingRunwayIndex >= 0)
                                        phaseStr += " Will land at " + RUNWAYS[planeLandingRunwayIndex].name + ".";
                                }
                                // Water-destination guard: warn up front so an over-water
                                // waypoint doesn't surprise the player at the far end.
                                if (IsOverWater(waypointPos))
                                {
                                    if (isHeli)
                                        phaseStr += " Waypoint is over water. Helicopter will hover there; use Land near shore.";
                                    else if (planeLandingRunwayIndex >= 0)
                                        phaseStr += " Waypoint is over water. Landing at " + RUNWAYS[planeLandingRunwayIndex].name + " instead.";
                                }
                                Speech.Ambient(acType + " autopilot engaged. Flying to waypoint at " + speedMph + " mph. " + (int)autodriveStartDistance + " meters. Altitude: " + (int)autopilotAltitude + " meters." + phaseStr);
                            }
                            else
                            {
                                // No waypoint - circle/cruise in current area
                                GTA.Math.Vector3 currentPos = Game.Player.Character.Position;
                                float currentAlt = currentPos.Z;
                                if (currentAlt < autopilotAltitude)
                                    currentAlt = autopilotAltitude;

                                autodriveDestination = new GTA.Math.Vector3(currentPos.X, currentPos.Y, currentAlt);

                                if (isHeli)
                                {
                                    // Hover in place for helicopters
                                    Function.Call(Hash.TASK_HELI_MISSION,
                                        driver, veh, 0, 0,
                                        currentPos.X, currentPos.Y, currentAlt,
                                        4, autodriveSpeed, 50f, -1f,
                                        (int)(currentAlt + 100), (int)(currentAlt - 50),
                                        -1f, 0);
                                }
                                else
                                {
                                    // Plane circling — no waypoint means no landing target.
                                    planePhase = veh.IsOnAllWheels ? PlanePhase.Takeoff : PlanePhase.Cruise;
                                    planeLandingRunwayIndex = -1;
                                    autodriveDestination = new GTA.Math.Vector3(currentPos.X, currentPos.Y, currentAlt);
                                    ReissueFlightMission();
                                }

                                isAutodriving = true;
                                autodriveWanderMode = true;
                                autodriveVehicleHandle = veh.Handle;
                                planeLandingStartTicks = 0;
                                planeLandingAttempts = 0;
                                planeGoAroundCooldownUntil = 0;
                                planeStallSinceTicks = 0;
                                autodriveCheckTicks = DateTime.Now.Ticks;

                                int speedMph = (int)Math.Round(autodriveSpeed * 2.23694);
                                string acType = isHeli ? "Helicopter hovering" : "Plane circling";
                                Speech.Ambient(acType + " at " + speedMph + " mph. Set a waypoint for a destination.");
                            }
                        }
                        else
                        {
                            // ============================================
                            // GROUND VEHICLE AUTO-DRIVE (existing behavior)
                            // ============================================
                            autonavMode = "drive";
                            int drivingStyle = GetDrivingStyleFromFlags();

                            // Set driver ability for better AI driving
                            Function.Call(Hash.SET_DRIVER_ABILITY, driver, 1.0f);
                            Function.Call(Hash.SET_DRIVER_AGGRESSIVENESS, driver, 0.5f);

                            if (hasWaypoint)
                            {
                                // WAYPOINT MODE - Drive to waypoint
                                int waypointBlipHandle = Function.Call<int>(Hash.GET_FIRST_BLIP_INFO_ID, 8);
                                GTA.Math.Vector3 waypointPos = Function.Call<GTA.Math.Vector3>(Hash.GET_BLIP_INFO_ID_COORD, waypointBlipHandle);

                                // Get ground Z at waypoint for proper height
                                float groundZ = World.GetGroundHeight(new GTA.Math.Vector2(waypointPos.X, waypointPos.Y));
                                if (groundZ > 0) waypointPos.Z = groundZ;

                                autodriveDestination = waypointPos;

                                // Calculate distance
                                GTA.Math.Vector3 playerPos = Game.Player.Character.Position;
                                autodriveStartDistance = World.GetDistance(playerPos, waypointPos);

                                // iter-49 C4: with driveSequenceV2 on, queue the drive
                                // AND the park as one engine-owned sequence the way
                                // taxiservice.c does, and let the phase machine stand
                                // down unless the sequence stalls. Off, this is the
                                // unchanged single longrange task.
                                if (getSetting("driveSequenceV2") == 1)
                                {
                                    IssueDriveThenPark(driver, veh, waypointPos,
                                        DestinationParkHeading(waypointPos, veh.Heading),
                                        autodriveSpeed, AUTODRIVE_PARK_RADIUS, "autodrive");
                                    autodriveSequenceActive = true;
                                    autodriveSequenceStallTicks = 0;
                                }
                                else
                                {
                                    autodriveSequenceActive = false;
                                    // Use TASK_VEHICLE_DRIVE_TO_COORD_LONGRANGE for long distances
                                    Function.Call(Hash.TASK_VEHICLE_DRIVE_TO_COORD_LONGRANGE,
                                        driver, veh,
                                        waypointPos.X, waypointPos.Y, waypointPos.Z,
                                        autodriveSpeed, drivingStyle, 20f); // 20m stop distance
                                }

                                isAutodriving = true;
                                autodriveWanderMode = false;
                                autodrivePhase = AutodrivePhase.Cruise; // start the hybrid final-approach machine fresh
                                autodriveOvershootRearmUsed = false;
                                autodriveVehicleHandle = veh.Handle;
                                autodriveCheckTicks = DateTime.Now.Ticks;

                                int speedMph = (int)Math.Round(autodriveSpeed * 2.23694);
                                string steerAssistMsg = getSetting("steeringAssist") > 0 ? " Steering assist disabled." : "";
                                Speech.Ambient("Auto-driving to waypoint at " + speedMph + " mph. " + (int)autodriveStartDistance + " meters." + steerAssistMsg);
                            }
                            else
                            {
                                // WANDER MODE - Drive randomly
                                try
                                {
                                    Function.Call(Hash.TASK_VEHICLE_DRIVE_WANDER,
                                        driver, veh,
                                        autodriveSpeed, drivingStyle);

                                    isAutodriving = true;
                                    autodriveWanderMode = true;
                                    autodriveVehicleHandle = veh.Handle;
                                    autodriveCheckTicks = DateTime.Now.Ticks;

                                    int speedMph = (int)Math.Round(autodriveSpeed * 2.23694);
                                    string steerAssistMsg = getSetting("steeringAssist") > 0 ? " Steering assist disabled." : "";
                                    Speech.Ambient("Wandering at " + speedMph + " mph." + steerAssistMsg);
                                }
                                catch (Exception ex)
                                {
                                    Speech.Ambient("Wander error: " + ex.Message);
                                }
                            }
                        }
                    }
                    else
                    {
                        // ============================================
                        // ON-FOOT AUTO-WALK
                        // ============================================
                        autonavMode = "walk";
                        Ped player = Game.Player.Character;
                        bool hasWaypoint = Function.Call<bool>(Hash.IS_WAYPOINT_ACTIVE);

                        if (hasWaypoint)
                        {
                            int waypointBlipHandle = Function.Call<int>(Hash.GET_FIRST_BLIP_INFO_ID, 8);
                            GTA.Math.Vector3 waypointPos = Function.Call<GTA.Math.Vector3>(Hash.GET_BLIP_INFO_ID_COORD, waypointBlipHandle);

                            // Get ground Z at waypoint
                            float groundZ = World.GetGroundHeight(new GTA.Math.Vector2(waypointPos.X, waypointPos.Y));
                            if (groundZ > 0) waypointPos.Z = groundZ;

                            autodriveDestination = waypointPos;

                            GTA.Math.Vector3 playerPos = player.Position;
                            autodriveStartDistance = World.GetDistance(playerPos, waypointPos);

                            // TASK_GO_TO_COORD_ANY_MEANS: ped, x, y, z, speed, p5, p6, walkingStyle, p8
                            // Speed: 1.0 = walk, 2.0 = jog/run
                            float walkSpeed = Math.Min(autodriveSpeed, 4f); // Cap walk speed to reasonable limit (4 m/s = fast run)
                            Function.Call(Hash.TASK_GO_TO_COORD_ANY_MEANS,
                                player,
                                waypointPos.X, waypointPos.Y, waypointPos.Z,
                                walkSpeed,
                                0, 0, 0, 0f);

                            isAutodriving = true;
                            autodriveWanderMode = false;
                            autodriveVehicleHandle = 0;
                            autodriveCheckTicks = DateTime.Now.Ticks;

                            Speech.Ambient("Auto-walking to waypoint. " + (int)autodriveStartDistance + " meters.");
                        }
                        else
                        {
                            // Wander on foot
                            Function.Call(Hash.TASK_WANDER_STANDARD,
                                player, 10f, 0);

                            isAutodriving = true;
                            autodriveWanderMode = true;
                            autodriveVehicleHandle = 0;
                            autodriveCheckTicks = DateTime.Now.Ticks;

                            Speech.Ambient("Wandering on foot.");
                        }
                    }

                    // iter-35 L3: start-side autonav log (cancel logs in its own
                    // branch where the pre-reset mode is still known).
                    if (isAutodriving && !autonavWasActiveAtKey
                        && driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT autonav:"
                            + " action=start mode=" + autonavMode
                            + " wander=" + autodriveWanderMode
                            + " dest=" + (autodriveWanderMode ? "-" : FmtV(autodriveDestination)));
                }

            }
        }

        private void onKeyUp(object sender, KeyEventArgs e)
        {
            try { onKeyUpCore(sender, e); }
            catch (Exception ex) { ReportSubsystemError("keyup", ex); }
        }

        private void onKeyUpCore(object sender, KeyEventArgs e)
        {
            if (!e.Control)
            {
                shifting = false;
            }
            if (e.KeyCode == Keys.NumPad0 && keyState[0])
                keyState[0] = false;
            if (e.KeyCode == Keys.NumPad1 && keyState[1])
                keyState[1] = false;
            if (e.KeyCode == Keys.NumPad2 && keyState[2])
                keyState[2] = false;
            if (e.KeyCode == Keys.NumPad3 && keyState[3])
                keyState[3] = false;
            if (e.KeyCode == Keys.NumPad4 && keyState[4])
                keyState[4] = false;
            if (e.KeyCode == Keys.NumPad5 && keyState[5])
                keyState[5] = false;
            if (e.KeyCode == Keys.NumPad6 && keyState[6])
                keyState[6] = false;
            if (e.KeyCode == Keys.NumPad7 && keyState[7])
                keyState[7] = false;
            if (e.KeyCode == Keys.NumPad8 && keyState[8])
                keyState[8] = false;
            if (e.KeyCode == Keys.NumPad9 && keyState[9])
                keyState[9] = false;
            if (e.KeyCode == Keys.Decimal && keyState[10])
                keyState[10] = false;
            if (e.KeyCode == Keys.Add && keyState[11])
                keyState[11] = false;
            if (e.KeyCode == Keys.Subtract && keyState[12])
                keyState[12] = false;
            if (e.KeyCode == Keys.Left && keyState[13])
                keyState[13] = false;
            if (e.KeyCode == Keys.Right && keyState[14])
                keyState[14] = false;
            if (e.KeyCode == Keys.Multiply && keyState[15])
                keyState[15] = false;
            if (e.KeyCode == Keys.Up && keyState[16])
                keyState[16] = false;
            if (e.KeyCode == Keys.Down && keyState[17])
                keyState[17] = false;
            if (e.KeyCode == Keys.NumPad0 && keyState[19])
                keyState[19] = false;
            if (e.KeyCode == Keys.F1 && keyState[18])
                keyState[18] = false;
            if (e.KeyCode == Keys.Escape && keyState[21])
            {
                keyState[21] = false;
                // End the Esc-open hold-off 150 ms after the opening press is
                // released; later fresh Esc presses close the menu normally.
                // B6: floor it at 350 ms after open — a very quick tap released
                // before the frontend starts reading controls otherwise let the
                // CANCEL leak and self-close the menu (~25% of reader1.2 opens).
                if (mrEscHoldoff)
                {
                    DateTime floor = mrLastFrontendOpenAt.AddMilliseconds(350);
                    DateTime grace = DateTime.Now.AddMilliseconds(150);
                    mrEscHoldoffEnd = grace > floor ? grace : floor;
                }
            }
            // iter-37: nav query key release — a short press either completes a
            // double-tap (fire What's Ahead now) or arms the single-tap window
            // (Around Me fires from NavQueryTick when the window expires).
            if (e.KeyCode == Keys.Divide && keyState[20])
            {
                keyState[20] = false;
                navQueryKeyIsDown = false;
                if (!navQueryHoldFired)
                {
                    long nowTicks = DateTime.Now.Ticks;
                    if (navQueryPendingTapTicks != 0
                        && nowTicks - navQueryPendingTapTicks < NAV_QUERY_DOUBLETAP_TICKS)
                    {
                        navQueryPendingTapTicks = 0;
                        DoWhatsAhead();
                    }
                    else
                    {
                        navQueryPendingTapTicks = nowTicks;
                    }
                }
            }


        }


        private double calculate_x_y_angle(double x1, double y1, double x2, double y2, double deg)
        {
            double x = x1 - x2;
            double y = y2 - y1;
            double rad = 0;
            if (x == 0 || y == 0)
            {
                rad = Math.Atan(0);
            }
            else
            {
                rad = Math.Atan(y / x);
            }
            double arctan = rad / Math.PI * 180;
            double fdeg = 0;
            if (x > 0)
            {
                fdeg = 90 - arctan;
            }
            else if (x < 0)
            {
                fdeg = 270 - arctan;
            }
            if (x == 0)
            {
                if (y > 0)
                {
                    fdeg = 0;
                }
                else if (y < 0)
                {
                    fdeg = 180;
                }
            }
            fdeg -= deg;
            if (fdeg < 0)
            {
                fdeg += 360;
            }
            fdeg = Math.Floor(fdeg);
            return fdeg;
        }

        // INPUT CONVENTION (iter-37 N12): counterclockwise compass degrees, the
        // GTA heading convention — 0 = north, 90 = WEST, 180 = south, 270 = east.
        // Game.Player.Character.Heading and calculate_x_y_angle are already in
        // this convention; a clockwise atan2(dx,dy) bearing must be fed as
        // atan2(-dx,dy). The constant names below (north/northeast/...) are the
        // clockwise labels and do NOT match the strings returned — trust the
        // returned strings, they are verified against the in-game compass.
        private string getDir(double facing)
        {
            // Center each 22.5° slice on its named direction (was edge-aligned,
            // biasing every readout a half-slice counterclockwise).
            facing = (facing + 11.25) % 360.0;
            if (facing < 0) facing += 360.0;
            if (facing >= north && facing < northnortheast)
            {
                return "north";
            }
            if (facing >= northnortheast && facing < northeast)
            {
                return "north-northwest";
            }

            if (facing >= northeast && facing < eastnortheast)
            {
                return "northwest";
            }
            if (facing >= eastnortheast && facing < east)
            {
                return "west-northwest";
            }

            if (facing >= east && facing < eastsoutheast)
            {
                return "west";
            }
            if (facing >= eastsoutheast && facing < southeast)
            {
                return "west-southwest";
            }

            if (facing >= southeast && facing < southsoutheast)
            {
                return "southwest";
            }
            if (facing >= southsoutheast && facing < south)
            {
                return "south-southwest";
            }
            if (facing >= south && facing < southsouthwest)
            {
                return "south";
            }
            if (facing >= southsouthwest && facing < southwest)
            {
                return "south-southeast";
            }
            if (facing >= southwest && facing < westsouthwest)
            {
                return "southeast";
            }
            if (facing >= westsouthwest && facing < west)
            {
                return "east-southeast";
            }
            if (facing >= west && facing < westnorthwest)
            {
                return "east";
            }
            if (facing >= westnorthwest && facing < northwest)
            {
                return "east-northeast";
            }
            if (facing >= northwest && facing < northnorthwest)
            {
                return "northeast";
            }
            if (facing >= northnorthwest)
            {
                return "north-northeast";
            }
            return "";

        }

        private double fixHeading(double heading)
        {
            double new_heading = 0;

            if (heading <= 180)
            {
                new_heading = heading + 180;
            }
            else if (heading > 180)
            {
                new_heading = heading - 180;
            }

            return new_heading;
        }

        private double GetAngleOfLineBetweenTwoPoints(GTA.Math.Vector3 p1, GTA.Math.Vector3 p2)
        {
            double xDiff = p2.X - p1.X;
            double yDiff = p2.Y - p1.Y;
            return Math.Atan2(yDiff, xDiff) * (180 / Math.PI) + 180;
        }

        // Same counterclockwise input convention as getDir (raw GTA heading).
        // iter-37 N12: slices centered on the 8 compass points (was edge-aligned).
        private int headingSlice(double heading)
        {
            heading = (heading + 22.5) % 360.0;
            if (heading < 0) heading += 360.0;

            if (heading >= 0 && heading < 45)
                return 0;
            if (heading >= 45 && heading < 90)
                return 1;
            if (heading >= 90 && heading < 135)
                return 2;
            if (heading >= 135 && heading < 180)
                return 3;
            if (heading >= 180 && heading < 225)
                return 4;
            if (heading >= 225 && heading < 270)
                return 5;
            if (heading >= 270 && heading < 315)
                return 6;
            if (heading >= 315)
                return 7;
            return -1;
        }

        private string headingSliceName(double heading)
        {
            if (headingSlice(heading) == 0)
                return ("north");
            if (headingSlice(heading) == 1)
                return ("northwest");
            if (headingSlice(heading) == 2)
                return ("west");
            if (headingSlice(heading) == 3)
                return ("southwest");
            if (headingSlice(heading) == 4)
                return ("south");
            if (headingSlice(heading) == 5)
                return ("southeast");
            if (headingSlice(heading) == 6)
                return ("east");
            if (headingSlice(heading) == 7)
                return ("northeast");
            return "None";

        }

        public string listToString(List<Result> results, string prependedText = "")
        {
            string text = prependedText;
            string vertical = "";

            Result[] r = results.ToArray();
            Array.Sort(r);
            foreach (Result i in r)
            {
                if (i.zDistance != 0)
                {
                    if (i.zDistance > 0)
                    {
                        vertical = " " + Math.Abs(i.zDistance) + " meters above , ";
                    }
                    else
                    {
                        vertical = " " + Math.Abs(i.zDistance) + " meters below, ";
                    }


                }
                text = text + i.xyDistance + " meters " + i.direction + ", " + vertical + i.name + ". ";
            }
            return (text);

        }

        private void speakMenu()
        {
            string result = mainMenu[mainMenuIndex];
            if (mainMenuIndex == 0)
                result = result + locations[locationMenuIndex].name;
            if (mainMenuIndex == 1)
                result = result + spawns[spawnMenuIndex].name;
            if (mainMenuIndex == 2)
                result = result + GetFunMenuText(funMenuIndex);
            // Auto-Drive menu - flag-based
            if (mainMenuIndex == 3)
            {
                if (isAutodriving)
                {
                    string modeStr;
                    if (autonavMode == "fly")
                        modeStr = autodriveWanderMode ? "hovering" : "flying to waypoint";
                    else if (autonavMode == "walk")
                        modeStr = autodriveWanderMode ? "wandering on foot" : "walking to waypoint";
                    else
                        modeStr = autodriveWanderMode ? "wandering" : "driving to waypoint";
                    if (autodriveFlagMenuIndex == 35)
                        result = result + "Refresh Driving Task. Currently " + modeStr + ". Press NumPad 2 to refresh.";
                    else
                        result = result + "Currently " + modeStr + ". NumPad Multiply to cancel.";
                }
                else
                {
                    int speedMph = (int)Math.Round(autodriveSpeed * 2.23694);
                    if (autodriveFlagMenuIndex == 32)
                    {
                        result = result + "Land. Select to land the helicopter. Speed: " + speedMph + " mph. Flight altitude: " + (int)autopilotAltitude + " meters.";
                    }
                    else if (autodriveFlagMenuIndex == 33)
                    {
                        result = result + "Park at Nearest Safe Spot. Select to park and end driving. Speed: " + speedMph + " mph.";
                    }
                    else if (autodriveFlagMenuIndex == 34)
                    {
                        result = result + "Hitch to Nearest Trailer. Select to attach the nearest trailer within 20 meters.";
                    }
                    else if (autodriveFlagMenuIndex == 35)
                    {
                        result = result + "Refresh Driving Task. Select to re-issue the active driving or flight task.";
                    }
                    else if (autodriveFlagMenuIndex == 36)
                    {
                        result = result + "Pull Over to Kerb. Select to stop at the kerb on your own side of the road, without crossing oncoming traffic.";
                    }
                    else
                    {
                    // Show current flag and state, plus speed
                    string flagState = autodriveFlags[autodriveFlagMenuIndex] ? "ON" : "OFF";
                    result = result + "Flag " + (autodriveFlagMenuIndex + 1) + " of 37: " + autodriveFlagNames[autodriveFlagMenuIndex] + ", " + flagState + ". Speed: " + speedMph + " mph. Flight altitude: " + (int)autopilotAltitude + " meters. NumPad Multiply to start. Left/Right arrows adjust speed. Up/Down arrows adjust flight altitude. Works in vehicles, aircraft, and on foot.";
                    }
                }
            }
            // Settings menu — shares FormatSettingValue with SpeakCurrentSetting
            // so multi-value settings announce their value here too.
            if (mainMenuIndex == 4)
            {
                result = result + FormatSettingValue(settingsMenu[settingsMenuIndex]);
            }
            // Bodyguard menu
            if (mainMenuIndex == 5)
            {
                result = result + GetBodyguardMenuText(bodyguardMenuIndex);
            }
            // Status menu
            if (mainMenuIndex == 6)
            {
                result = result + "Item " + (statusMenuIndex + 1) + " of " + STATUS_MENU_ITEM_COUNT + ". " + GetStatusMenuText(statusMenuIndex);
                if (statusMonitoredItems.Contains(statusMenuIndex))
                    result += " Monitoring.";
                if (statusMonitoredItems.Count > 0)
                    result += " " + statusMonitoredItems.Count + " item" + (statusMonitoredItems.Count > 1 ? "s" : "") + " monitored.";
            }
            // Request Plane Flight menu
            if (mainMenuIndex == 7)
            {
                result = result + GetFlightMenuText(planeFlightMenuIndex);
            }
            // Eat, drink, smoke menu
            if (mainMenuIndex == 8)
            {
                result = result + "Item " + (consumeMenuIndex + 1) + " of " + CONSUMABLES.Length
                    + ". " + GetConsumeMenuText(consumeMenuIndex);
            }
            // World Directory (iter-52)
            if (mainMenuIndex == 9)
            {
                // Rebuild on ENTRY only. Rebuilding on every arrow press would re-sort
                // the list under the user's finger as they walk, so the row they were
                // about to select moves somewhere else.
                if (lastSpokenMainMenuIndex != 9 || worldDirectory.Count == 0)
                {
                    worldMenuIndex = 0;
                    RebuildWorldDirectory();
                }
                result = result + "Item " + (worldMenuIndex + 1) + " of " + worldDirectory.Count
                    + ". " + GetWorldMenuText(worldMenuIndex);
            }
            // Events and Services (iter-52)
            if (mainMenuIndex == 10)
            {
                if (eventsMenuIndex >= EventsMenuCount()) eventsMenuIndex = 0;
                result = result + "Item " + (eventsMenuIndex + 1) + " of " + EventsMenuCount()
                    + ". " + GetEventsMenuText(eventsMenuIndex);
            }

            lastSpokenMainMenuIndex = mainMenuIndex;
            Speech.Info(result);

        }

        // iter-52: which top-level menu speakMenu last announced, so a menu can tell
        // "the user just arrived here" from "the user is arrowing inside me".
        private int lastSpokenMainMenuIndex = -1;

        // iter-37: single source of truth for first-run setting defaults —
        // used for BOTH a fresh settings file and keys missing from an
        // existing file (the two hand-maintained lists this replaces had
        // drifted apart).
        private static readonly HashSet<string> defaultOnSettings = new HashSet<string>
        {
            "announceHeadings", "announceZones", "altitudeIndicator", "announceTime",
            "targetPitchIndicator", "speed", "turnByTurnNavigation", "autoResumeCreep",
            "stuckDamageArm", "standoffThreat", "reverseRearV2", "laneStability",
            // overhaul "pin fix" batch — default ON (active fixes), each revertible in-game
            "shapeTestV2", "accStandstillRelease", "steerFreezeAtStop", "distressFloor",
            // iter-39 Stage 1/3 — default ON, revertible in-game. actuationV2 is the
            // fix for the mod nullifying its own brake/steer writes; watchdogV2 stops
            // the blind-player watchdog from cancelling the recovery that armed it.
            // brakePhysicsAssist stays OFF: it is the fallback physics path, only
            // needed if the control channel still under-delivers once un-disabled.
            "actuationV2", "watchdogV2",
            // iter-40 — default ON, each revertible in-game so a bad group can be
            // isolated without a rebuild. These address what actuationV2 exposed:
            // once the commands became real, the mod's own self-conflicting
            // commands started physically pinning and damaging the car.
            "reverseV2", "brakeDeadzoneV2", "graceArbitrationV2",
            "recoverySuspendV2", "recoveryTargetV2", "stuckLadderV2", "roadModelV2",
            // ---- iter-43: promoted on 07-31 field evidence ----
            // These four fired thousands of times across 53.2 driving minutes and
            // 19 vehicles with no failure attributable to them in the epoch table.
            // Deliberately NOT promoted: stuckArmHysteresisV2 (its traffic-queue
            // veto is implicated in the 32 s strand — revisit after B1 is tested),
            // accStandstillV2 (the ACC limit cycle — revisit after B2),
            // assistVoiceV2 (165 suppressed hardbrake cues need review),
            // damageDrawdownV2 (no attributable benefit yet) and handbrakeBandV2
            // (UNTESTED: 0 fires — never once exercised).
            //
            // iter-52: this list used to name graceArbitrationV2 here too, which was a
            // straight contradiction — it is default-ON four lines above and has been
            // since iter-40, so it cannot be a gate "deliberately not promoted". What
            // the 07-31 evidence actually said about it is that it is UNDER-EXERCISED
            // (0.9 min of exposure), not unpromoted. It stays ON; the claim is fixed
            // rather than the default, because flipping a shipped default on the
            // strength of a mis-worded comment would be a behaviour change with no
            // evidence behind it.
            "creepClearV2", "throttleAuthorityV2", "skewGateV2", "offroadBrakeV2",
            // nodeStreamGuardV2 fired 0 times in 5171 evaluations, which for this
            // gate is the PASS condition: it means no path-node streaming gap was
            // hit. It is a guard against a real bug class and costs nothing when
            // the nodes are loaded.
            "nodeStreamGuardV2",
            // iter-37: the scanner is the mod's core navigation aid — on by default.
            "navigationAssist", "shapeCasting",
            // Menu Reader v1: spoken pause menu + phone is why blind users
            // install the mod — on by default. Esc opens the readable unpaused
            // menu; P remains the vanilla paused menu.
            "pauseMenuReader",
            // iter-44: the two SAFETY defaults for the new features. The safety
            // watchdog is what guarantees a rioter that somehow turns on the
            // player is ejected, and intoxVisuals is cosmetic-only (it can never
            // affect the audible state machine), so both are ON. Every gate that
            // changes behaviour ships OFF — see the ids[] block.
            "unrestSafetyWatchdog", "intoxVisuals",
            // iter-45: the vanilla drunk/stoned audio treatment. ON because it is
            // the whole point of the feature — but unlike intoxVisuals it is NOT
            // cosmetic for this audience (it muffles engine note, traffic and
            // sirens), so it gets its own switch rather than riding on intoxEnabled.
            "intoxAudio",
            // iter-49: NOTHING from the vanilla-script batch is listed here. All
            // thirteen ship OFF, including the four telemetry-only ones — a
            // sampler still costs native calls and log budget, which is the same
            // reason iter-42 gated actuationFeedbackV2/wheelStateV2 rather than
            // letting them run free.
            // iter-50: the three menu-reader v1.5 switches ARE on by default. They
            // are not experiments on the driving model — they are the reason the
            // settings menu is operable at all without sight, and each only adds
            // information to a row that used to say nothing. phoneRowTextV2 is
            // absent deliberately: it reads unconfirmed script-global offsets.
            "menuReaderValueLive", "menuReaderPosition", "menuReaderBindLearn",
        };

        private int DefaultForSetting(string id)
        {
            if (defaultOnSettings.Contains(id)) return 1;
            if (id == "detectionRadius") return 1;      // 25 m
            if (id == "navAssistVerbosity") return 2;   // Nearest Obstacle
            if (id == "navAssistFootRange") return 1;   // 8 m
            if (id == "unrestNarration") return 1;      // Brief
            // iter-51: 1 = Normal, i.e. the exact ladder every previous iteration
            // ran. A new setting whose default changed behaviour would make the
            // 08-11 baseline uncomparable.
            if (id == "unrestPace") return 1;
            return 0;
        }

        void setupSettings(int attempt = 0)
        {
            Dictionary<string, int> dictionary = new Dictionary<string, int>();
            string json;
            // iter-37: navAssistBeeps replaced by navAssistVerbosity (values
            // 0=Off 1=Alerts-Only 2=Nearest-Obstacle 3=All-Zones) + the new
            // navAssistFootRange. Nav-assist ids sit adjacent so a blind user
            // arrows through them as a group. Old navAssistBeeps values are
            // migrated below, then the key drops out of the menu (and of the
            // json on the next save).
            string[] ids = { "announceHeadings", "announceZones", "announceTime", "altitudeIndicator", "targetPitchIndicator", "navigationAssist", "navAssistVerbosity", "navAssistFootRange", "shapeCasting", "pickupDetection", "coverDetection", "waterHazardDetection", "vehicleHealthFeedback", "staminaFeedback", "interactableDetection", "trafficAwareness", "wantedLevelDetails", "slopeTerrainFeedback", "turnByTurnNavigation", "serviceProximity", "detectionRadius", "radioOff", "warpInsideVehicle", "onscreen", "speed", "godMode", "policeIgnore", "vehicleGodMode", "amphibiousMode", "infiniteAmmo", "neverWanted", "superJump", "runFaster", "swimFaster", "exsplosiveAmmo", "fireAmmo", "explosiveMelee", "aimAutolock", "steeringAssist", "roadTeleport", "waypointDriveAssist", "hapticFeedback", "adaptiveCruise", "bodyguardAutoRespawn", "driveAssistDebugLog", "menuDebugLog", "pauseMenuReader", "butlerValet", "autoResumeCreep", "laneOffsetPolyline", "junctionAssist", "wrongWayAlert", "restrictionAwareWalk", "stuckDamageArm", "standoffThreat", "reverseRearV2", "laneStability", "shapeTestV2", "accStandstillRelease", "steerFreezeAtStop", "distressFloor", "actuationV2", "watchdogV2", "brakePhysicsAssist", "reverseV2", "brakeDeadzoneV2", "graceArbitrationV2", "recoverySuspendV2", "recoveryTargetV2", "stuckLadderV2", "roadModelV2",
                // iter-41. NOT in defaultOnSettings: every one ships OFF and is
                // turned on individually in-game, one per epoch, so a session's
                // result is attributable to exactly one change. iter-40 shipped
                // seven gates ON at once and five produced no evidence at all.
                "creepClearV2", "accStandstillV2", "assistVoiceV2", "throttleAuthorityV2", "damageDrawdownV2", "stuckArmHysteresisV2", "offroadBrakeV2", "skewGateV2", "handbrakeBandV2",
                // iter-42. Same discipline: ships OFF, enabled one per session.
                // actuationFeedbackV2/wheelStateV2 are pure telemetry — they change
                // no behavior, so they are the one safe pair to run together.
                "nodeStreamGuardV2", "actuationFeedbackV2", "wheelStateV2",
                // B1/B2 are DARK: they sample and log, and feed no control path,
                // so they are also safe to run alongside the telemetry pair.
                "roadBoundaryV2", "groundNormalV2",
                // C2/C3 is the one iter-42 gate with a user-facing effect (turn
                // announcements), so it gets its own session.
                "junctionDirectionsV2",
                // iter-43: per-vehicle geometry (wheelbase, steering lock, rear
                // overhang, brake distances). Changes the control law, so it gets
                // its own session and ships OFF.
                "vehicleGeometryV2",
                // iter-44: Civil Unrest + consumables/intoxication. unrestScope is
                // 0-3, unrestNarration is 0-2, the rest are booleans. Weapon
                // handouts ship OFF so the first riot session tests the
                // relationship/aggression mechanism with no weapon confound.
                // intoxDriveImpair/intoxBlackoutDrive alter driving, so they are in
                // GATE_SETTINGS and ship OFF, one per session per iter-41 discipline.
                "unrestScope", "unrestMelee", "unrestFirearms", "unrestNarration", "unrestSafetyWatchdog",
                // iter-48: the escalation overhaul. Kept adjacent to the iter-44 run so
                // the whole riot cluster is arrowed through as one group. Every one
                // ships OFF and is enabled in its own session per the iter-41
                // one-gate-per-epoch discipline; none writes a player control, so none
                // belongs in GATE_SETTINGS (they would census eval:0/fire:0 forever).
                "unrestEscalation", "unrestBrutality", "unrestAmbience",
                "unrestPolice", "unrestTraffic", "unrestFires",
                // iter-51: how fast the stage ladder runs. Defaults to 1 (Normal),
                // i.e. the exact original timings, so existing installs are unchanged.
                "unrestPace",
                "intoxEnabled", "intoxVisuals", "intoxDriveImpair", "intoxBlackoutDrive",
                // iter-45: intoxAudio drives SET_AUDIO_SPECIAL_EFFECT_MODE. It writes
                // no control, so it stays OUT of GATE_SETTINGS — it would census
                // eval:0/fire:0 forever and pollute the drive-assist gate table.
                // intoxVanillaOnly stands this mod's whole presentation layer down
                // and hands drunkenness back to the game's own drunk_controller.
                "intoxAudio", "intoxVanillaOnly",
                // ---- iter-49: the vanilla-script batch, ALL OFF ----
                // Ordered so a blind user arrowing through them meets the four
                // measurement switches first (they change nothing you can feel),
                // then the road model, then the things that move the car.
                "roadFactsV2", "nodePropsV2", "kerbGeometryV2", "engineStuckTelemetryV2",
                "nodeQueryArgsV2", "laneWidthV2", "nodeHazardV2", "pullOverAssist",
                "engineStuckArmV2", "tempActionV2", "driveSequenceV2", "steerBiasV2",
                "gunfireAttribV2",
                // ---- iter-51: drive-assist ----
                // Both ship OFF and are enabled one per session, same discipline.
                "roadSpeedGovernorV2", "polyDistrustV2",
                // ---- iter-50: Menu Reader v1.5 ----
                // Kept adjacent to pauseMenuReader's cluster in spirit but appended
                // here so no existing index shifts. The first three ship ON: they
                // are the feature, and each one only ever ADDS information to a row
                // that was previously silent, so the failure mode of a bad one is
                // "too talkative", not "wrong". phoneRowTextV2 ships OFF because it
                // walks script globals whose page offset is not yet confirmed on
                // this build — it logs its probe first and gets flipped on once a
                // session says the offsets are right.
                "menuReaderValueLive", "menuReaderPosition", "menuReaderBindLearn",
                "phoneRowTextV2",
                // ---- iter-52: world data (tools/build-worlddata.py -> WorldDataDb) ----
                // Everything harvested from Rockstar's own decompiled scripts. All ship
                // OFF per the iter-41 one-gate-per-epoch discipline. None writes a
                // vehicle control, so none belongs in GATE_SETTINGS — they would
                // census eval:0/fire:0 forever and pollute the drive-assist gate table
                // (same call iter-44 made for intoxAudio).
                //
                // worldDataDb is pure telemetry: it only makes the DB census get
                // logged, so it is safe to run alongside anything.
                "worldDataDb",
                // Both read-only and independent of each other, so they are the one
                // pair in this batch that is safe to enable in the same session.
                "collectibleNav", "placesDirectory",
                // Speech / text enrichment only; also safe together.
                "restrictedAreaWarn", "interactionCatalogue",
                // randomEventAlerts only READS the active-event global and suppresses,
                // so it is safe anywhere. emergencyDispatch SPAWNS units, so it gets
                // its own session.
                // (A randomEventDirector gate was planned here and dropped — see the
                // "Why there is no start this random event command" note in the EVENTS
                // AND SERVICES region. It could not have worked.)
                "randomEventAlerts", "emergencyDispatch",
                // ---- iter-52: failure snapshots ----
                // Instrumentation, not gameplay. All four are nested under
                // driveAssistDebugLog: no log, no snapshots.
                "snapshotAllFailures", "snapshotGeometry", "snapshotImage",
                "snapshotPreroll" };
            System.IO.StreamWriter fileOut;

            if (!System.IO.Directory.Exists(@Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments) + "/Rockstar Games/GTA V/ModSettings"))
                System.IO.Directory.CreateDirectory(@Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments) + "/Rockstar Games/GTA V/ModSettings");

            if (!System.IO.File.Exists(@Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments) + "/Rockstar Games/GTA V/ModSettings/gta11ySettings.json"))
            {
                fileOut = new System.IO.StreamWriter(@Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments) + "/Rockstar Games/GTA V/ModSettings/gta11ySettings.json");

                foreach (string i in ids)
                {
                    // iter-37: fresh-file and missing-key defaults now come from
                    // ONE table (DefaultForSetting) — the two lists had silently
                    // diverged (targetPitchIndicator/speed were ON only in the
                    // missing-key path, so fresh installs got them OFF).
                    dictionary.Add(i, DefaultForSetting(i));
                }

                json = JsonConvert.SerializeObject(dictionary, Formatting.Indented);
                fileOut.Write(json);
                fileOut.Close();
            }
            dictionary.Clear();
            System.IO.StreamReader fileIn = new System.IO.StreamReader(@Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments) + "/Rockstar Games/GTA V/ModSettings/gta11ySettings.json");
            json = fileIn.ReadToEnd();
            fileIn.Close();
            try
            {
                dictionary = JsonConvert.DeserializeObject<Dictionary<string, int>>(json);
            }
            catch
            {
                // Corrupt JSON. Delete and retry a bounded number of times; if it keeps
                // failing (e.g. disk full / AV locking the file) fall back to an in-memory
                // empty dict so the defaults below still populate — never recurse without
                // limit (the old code could stack-overflow on persistent corruption).
                if (attempt < 2)
                {
                    try { System.IO.File.Delete(@Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments) + "/Rockstar Games/GTA V/ModSettings/gta11ySettings.json"); } catch { }
                    setupSettings(attempt + 1);
                    return;
                }
                dictionary = new Dictionary<string, int>();
            }
            // Guard against a null dictionary (deserialize returned null for "null"/empty
            // content) so the population loop below can't NullReference and re-trigger.
            if (dictionary == null) dictionary = new Dictionary<string, int>();

            // iter-37: one-time migration navAssistBeeps -> navAssistVerbosity.
            // Intent-preserving: beeps ON -> All Zones (keep everything audible);
            // beeps OFF -> Alerts Only (the ambient layer was muted on purpose).
            // The old key stays in the dictionary for this read but is not in
            // ids[], so it drops out of the menu now and out of the json on the
            // next save.
            if (!dictionary.ContainsKey("navAssistVerbosity") && dictionary.ContainsKey("navAssistBeeps"))
            {
                dictionary["navAssistVerbosity"] = dictionary["navAssistBeeps"] == 1 ? 3 : 1;
                navMigrationNoticePending = true;
            }
            try
            {
                settingsMenu.Clear();
                foreach (string i in ids)
                {
                    if (dictionary.ContainsKey(i))
                    {
                        settingsMenu.Add(new Setting(i, idToName(i), dictionary[i]));
                    }
                    else
                    {
                        settingsMenu.Add(new Setting(i, idToName(i), DefaultForSetting(i)));
                    }
                }


            }
            catch
            {
                // Unexpected failure populating settingsMenu. Bounded retry, then give up
                // rather than recursing forever (settingsMenu keeps whatever was added;
                // getSetting falls back to -1/off for anything missing).
                if (attempt < 2)
                {
                    try { System.IO.File.Delete(@Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments) + "/Rockstar Games/GTA V/ModSettings/gta11ySettings.json"); } catch { }
                    setupSettings(attempt + 1);
                }
            }

            // ---- vehicleaihandlinginfo.meta loader (iter-8) ----
            // Drive-assist consults this for per-class curve target speeds and
            // brake-lookahead distances. See VehicleAIHandling.cs for details.
            try
            {
                string modSettingsFolder = @Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments)
                    + "/Rockstar Games/GTA V/ModSettings";
                string modDllFolder = System.IO.Path.GetDirectoryName(
                    System.Reflection.Assembly.GetExecutingAssembly().Location);
                VehicleAIHandlingRegistry.LoadOrFallback(modDllFolder, modSettingsFolder);
            }
            catch
            {
                // Non-fatal: GetForVehicle() will lazy-init the hardcoded
                // fallback if the loader didn't get a chance to run.
            }
        }

        void saveSettings()
        {
            Dictionary<string, int> dictionary = new Dictionary<string, int>();
            foreach (Setting i in settingsMenu)
            {
                dictionary.Add(i.id, i.value);
            }
            // The old CreateDirectory call had literal " / " spacing in the path,
            // so it could never create the intended folder — if ModSettings was
            // missing, the StreamWriter below threw out of the settings menu.
            try
            {
                string dir = System.IO.Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),
                    "Rockstar Games", "GTA V", "ModSettings");
                System.IO.Directory.CreateDirectory(dir);
                using (var fileOut = new System.IO.StreamWriter(System.IO.Path.Combine(dir, "gta11ySettings.json")))
                    fileOut.Write(JsonConvert.SerializeObject(dictionary, Formatting.Indented));
            }
            catch (Exception)
            {
                Speech.Info("Warning: settings could not be saved.");
            }
        }

        // ============================================
        // AIM AUTOLOCK HELPER METHODS
        // ============================================

        /// <summary>
        /// Announces the locked target via Tolk screen reader
        /// </summary>
        private void AnnounceAutolockTarget(Entity target)
        {
            if (target == null) return;
            string announcement = "";

            if (target.EntityType == EntityType.Ped)
            {
                Ped ped = (Ped)target;
                int pedType = Function.Call<int>(Hash.GET_PED_TYPE, ped);
                string pedTypeName = GetPedTypeName(pedType);
                announcement = pedTypeName + ", targeting " + PED_TARGET_PARTS[autolockPartIndex].name;
            }
            else if (target.EntityType == EntityType.Vehicle)
            {
                Vehicle vehicle = (Vehicle)target;
                string vehName = vehicle.LocalizedName;
                if (string.IsNullOrEmpty(vehName) || vehName == "NULL")
                    vehName = vehicle.DisplayName;

                int occupantCount = 0;
                if (vehicle.Driver != null && vehicle.Driver.IsAlive) occupantCount++;
                for (int seat = 0; seat < vehicle.PassengerCapacity; seat++)
                {
                    Ped passenger = vehicle.GetPedOnSeat((VehicleSeat)seat);
                    if (passenger != null && passenger.IsAlive) occupantCount++;
                }

                string occupantStr = occupantCount > 0
                    ? " with " + occupantCount + " occupant" + (occupantCount > 1 ? "s" : "")
                    : " (empty)";
                announcement = vehName + occupantStr + ", targeting " + VEHICLE_TARGET_PARTS[autolockPartIndex].name;
            }

            if (!string.IsNullOrEmpty(announcement))
            {
                // Tell the player up front if the auto-selected part is occluded, so they
                // know a shot may not connect until they cycle to a clear part.
                if (!IsPartVisible(autolockPartIndex)) announcement += " (obscured)";
                Speech.Critical(announcement);
            }
        }

        /// <summary>
        /// Converts GTA ped type ID to human-readable name
        /// </summary>
        private string GetPedTypeName(int pedType)
        {
            // GTA V ePedType, as returned by PED::GET_PED_TYPE. The previous mapping was
            // mostly wrong (e.g. 27 was labelled "Bodyguard" but is actually SWAT, 21 was
            // "Security guard" but is FIREMAN, and civilians/gangs were off), so threats
            // were announced with the wrong identity. Gang variants span 7..18.
            if (pedType >= 7 && pedType <= 18) return "Gang member";
            switch (pedType)
            {
                case 0: case 1: case 2: case 3: return "Player";
                case 4: return "Male civilian";
                case 5: return "Female civilian";
                case 6: return "Cop";
                case 19: return "Drug dealer";
                case 20: return "Paramedic";
                case 21: return "Firefighter";
                case 22: return "Criminal";
                case 23: return "Homeless person";
                case 24: return "Prostitute";
                case 25: return "Special";
                case 26: return "Mission character";
                case 27: return "SWAT";
                case 28: return "Animal";
                case 29: return "Army";
                default: return "Unknown";
            }
        }

        /// <summary>
        /// Updates camera/aim to track the current target part
        /// </summary>
        /// <param name="instantSnap">If true, instantly snap to target instead of smooth lerp</param>
        private void UpdateAutolockAim(bool instantSnap = false)
        {
            if (autolockTarget == null || autolockTarget.IsDead) return;

            GTA.Math.Vector3 targetPos = GetTargetPartPosition();
            if (targetPos == GTA.Math.Vector3.Zero) return;

            GTA.Math.Vector3 camPos = GTA.GameplayCamera.Position;
            GTA.Math.Vector3 direction = GTA.Math.Vector3.Normalize(targetPos - camPos);

            float targetHeading = (float)(Math.Atan2(direction.X, direction.Y) * (180.0 / Math.PI));
            float targetPitch = (float)(Math.Asin(direction.Z) * (180.0 / Math.PI));

            float currentHeading = GTA.GameplayCamera.RelativeHeading;
            float currentPitch = GTA.GameplayCamera.RelativePitch;

            float headingDelta = targetHeading - Game.Player.Character.Heading - currentHeading;
            float pitchDelta = targetPitch - currentPitch;

            while (headingDelta > 180) headingDelta -= 360;
            while (headingDelta < -180) headingDelta += 360;

            // Use instant snap (1.0) when re-acquiring target, smooth lerp during normal tracking
            // Frame-rate independent: ~10 units per second tracking speed
            float lerpFactor = instantSnap ? 1.0f : Math.Min(1.0f, 10.0f * deltaTime);
            float adjustedHeading = currentHeading + (headingDelta * lerpFactor);
            float adjustedPitch = Math.Max(-70f, Math.Min(70f, currentPitch + (pitchDelta * lerpFactor)));

            Function.Call(Hash.SET_GAMEPLAY_CAM_RELATIVE_HEADING, adjustedHeading);
            Function.Call(Hash.SET_GAMEPLAY_CAM_RELATIVE_PITCH, adjustedPitch, 1f);
        }

        /// <summary>
        /// Gets the world position of the currently selected target part
        /// </summary>
        private GTA.Math.Vector3 GetTargetPartPosition()
        {
            if (autolockTarget == null) return GTA.Math.Vector3.Zero;

            try
            {
                if (autolockTarget.EntityType == EntityType.Ped)
                {
                    Ped ped = (Ped)autolockTarget;
                    int boneId = PED_TARGET_PARTS[autolockPartIndex].boneId;
                    GTA.Math.Vector3 bonePos = Function.Call<GTA.Math.Vector3>(
                        Hash.GET_PED_BONE_COORDS, ped, boneId, 0f, 0f, 0f);
                    return bonePos != GTA.Math.Vector3.Zero ? bonePos : ped.Position;
                }
                else if (autolockTarget.EntityType == EntityType.Vehicle)
                {
                    Vehicle vehicle = (Vehicle)autolockTarget;
                    string boneName = VEHICLE_TARGET_PARTS[autolockPartIndex].bone;
                    int boneIndex = Function.Call<int>(Hash.GET_ENTITY_BONE_INDEX_BY_NAME, vehicle, boneName);

                    if (boneIndex != -1)
                    {
                        GTA.Math.Vector3 bonePos = Function.Call<GTA.Math.Vector3>(
                            Hash.GET_WORLD_POSITION_OF_ENTITY_BONE, vehicle, boneIndex);
                        if (bonePos != GTA.Math.Vector3.Zero) return bonePos;
                    }
                    return vehicle.Position;
                }
            }
            catch { }

            // Bone lookup failed; fall back to entity position, guarding against the
            // rare case where the target was freed between the null check at the top
            // of the function and the catch fall-through.
            if (autolockTarget == null || !autolockTarget.Exists()) return GTA.Math.Vector3.Zero;
            return autolockTarget.Position;
        }

        /// <summary>
        /// Gets the position of a specific part index for visibility checking
        /// </summary>
        private GTA.Math.Vector3 GetPartPositionByIndex(int partIndex)
        {
            if (autolockTarget == null) return GTA.Math.Vector3.Zero;

            try
            {
                if (autolockTarget.EntityType == EntityType.Ped)
                {
                    Ped ped = (Ped)autolockTarget;
                    int boneId = PED_TARGET_PARTS[partIndex].boneId;
                    GTA.Math.Vector3 bonePos = Function.Call<GTA.Math.Vector3>(
                        Hash.GET_PED_BONE_COORDS, ped, boneId, 0f, 0f, 0f);
                    return bonePos != GTA.Math.Vector3.Zero ? bonePos : ped.Position;
                }
                else if (autolockTarget.EntityType == EntityType.Vehicle)
                {
                    Vehicle vehicle = (Vehicle)autolockTarget;
                    string boneName = VEHICLE_TARGET_PARTS[partIndex].bone;
                    int boneIndex = Function.Call<int>(Hash.GET_ENTITY_BONE_INDEX_BY_NAME, vehicle, boneName);

                    if (boneIndex != -1)
                    {
                        GTA.Math.Vector3 bonePos = Function.Call<GTA.Math.Vector3>(
                            Hash.GET_WORLD_POSITION_OF_ENTITY_BONE, vehicle, boneIndex);
                        if (bonePos != GTA.Math.Vector3.Zero) return bonePos;
                    }
                    return vehicle.Position;
                }
            }
            catch { }

            // Bone lookup failed; fall back to entity position, guarding against the
            // rare case where the target was freed between the null check at the top
            // of the function and the catch fall-through.
            if (autolockTarget == null || !autolockTarget.Exists()) return GTA.Math.Vector3.Zero;
            return autolockTarget.Position;
        }

        /// <summary>
        /// Checks if a specific target part is visible from the player's position using raycast
        /// Returns true if there's a clear line of sight to the part
        /// </summary>
        private bool IsPartVisible(int partIndex)
        {
            if (autolockTarget == null) return false;

            GTA.Math.Vector3 partPos = GetPartPositionByIndex(partIndex);
            if (partPos == GTA.Math.Vector3.Zero) return false;

            // Use camera position as origin (where bullets come from when aiming)
            GTA.Math.Vector3 camPos = GTA.GameplayCamera.Position;

            // Perform raycast from camera to target part. Include peds and objects in
            // addition to map+vehicles so an NPC or prop standing between the camera and
            // the target correctly counts as occlusion (previously only world/vehicles
            // blocked, so a part behind a bystander read as "visible" and bullets missed).
            RaycastResult ray = World.Raycast(camPos, partPos,
                IntersectFlags.Map | IntersectFlags.Vehicles | IntersectFlags.Peds | IntersectFlags.Objects,
                Game.Player.Character);

            if (ray.DidHit)
            {
                // Check if the ray hit the target entity itself or something blocking it
                if (ray.HitEntity != null && ray.HitEntity == autolockTarget)
                {
                    // Hit the target - check if we hit close to the part we're aiming at
                    float hitDistance = camPos.DistanceTo(ray.HitPosition);
                    float partDistance = camPos.DistanceTo(partPos);

                    // If the hit position is close to the part position, part is visible.
                    // Tolerance tightened 2.5 -> 1.0 m: bones sit a little under the
                    // surface, but 2.5 m was wide enough that a far-side part on a ~2 m
                    // wide car (the ray hits the near body panel) still read as visible,
                    // so the lock tracked an occluded part. 1.0 m accepts near-surface
                    // bones while rejecting parts on the opposite side of the hull.
                    if (ray.HitPosition.DistanceTo(partPos) < 1.0f)
                    {
                        return true;
                    }

                    // If we hit the target but not near the part, the part is on the other side
                    // (e.g., trying to hit left wheel from right side - ray hits the right side first)
                    return false;
                }
                else
                {
                    // Hit something else blocking the view (world geometry, another vehicle)
                    return false;
                }
            }

            // No hit means clear line of sight (shouldn't happen often)
            return true;
        }

        /// <summary>
        /// Finds the next visible part index, skipping non-visible parts
        /// Returns -1 if no visible parts found
        /// </summary>
        private int FindNextVisiblePart(int startIndex, int direction)
        {
            if (autolockTarget == null) return -1;

            int maxParts = autolockTarget.EntityType == EntityType.Ped
                ? PED_TARGET_PARTS.Length
                : VEHICLE_TARGET_PARTS.Length;

            // Try each part starting from the given index
            for (int i = 0; i < maxParts; i++)
            {
                int checkIndex = (startIndex + (direction * i) + maxParts) % maxParts;
                if (IsPartVisible(checkIndex))
                {
                    return checkIndex;
                }
            }

            // No visible part found. Return -1 so a caller can decide (announce
            // "obscured" / fall back to center of mass) rather than silently locking
            // onto a part that may be hidden. (Currently unused — the live cycling and
            // acquisition paths inline their own search — kept correct for future use.)
            return -1;
        }

        /// <summary>
        /// Handles right stick input for cycling through target parts
        /// Skips parts that are not visible from the player's position (e.g., gas tank on opposite side)
        /// </summary>
        private void HandlePartCycling()
        {
            if (autolockTarget == null) return;
            if (DateTime.Now.Ticks - autolockPartCycleTicks < 2000000) return; // 200ms debounce

            // Use GET_DISABLED_CONTROL_NORMAL since we disabled the control action
            // This still reads the input value even though default game action is suppressed
            float rightStickX = Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 220);

            int maxParts = autolockTarget.EntityType == EntityType.Ped
                ? PED_TARGET_PARTS.Length
                : VEHICLE_TARGET_PARTS.Length;

            bool changed = false;
            int direction = 0;
            int originalIndex = autolockPartIndex;

            if (rightStickX < -0.5f && !autolockPartCycleLeft)
            {
                autolockPartCycleLeft = true;
                direction = -1;
                changed = true;
            }
            else if (rightStickX >= -0.5f)
            {
                autolockPartCycleLeft = false;
            }

            if (rightStickX > 0.5f && !autolockPartCycleRight)
            {
                autolockPartCycleRight = true;
                direction = 1;
                changed = true;
            }
            else if (rightStickX <= 0.5f)
            {
                autolockPartCycleRight = false;
            }

            if (changed && direction != 0)
            {
                autolockPartCycleTicks = DateTime.Now.Ticks;

                // Find the next visible part in the given direction
                // Start from the next part in that direction
                int startIndex = (autolockPartIndex + direction + maxParts) % maxParts;
                int foundIndex = -1;

                // Search through all parts to find the next visible one
                for (int i = 0; i < maxParts; i++)
                {
                    int checkIndex = (startIndex + (direction * i) + maxParts) % maxParts;
                    if (IsPartVisible(checkIndex))
                    {
                        foundIndex = checkIndex;
                        break;
                    }
                }

                // If no visible part found, stay on current or fallback to center
                if (foundIndex == -1)
                {
                    // Play a lower "blocked" beep to indicate no other parts visible
                    outPartCycle.Stop();
                    partCycleBeep.Frequency = 300;
                    var blockedSample = partCycleBeep.Take(TimeSpan.FromSeconds(0.1));
                    outPartCycle.Init(blockedSample);
                    outPartCycle.Play();
                    Speech.Info("No other visible parts");
                    return;
                }

                // Update to the new visible part
                autolockPartIndex = foundIndex;

                outPartCycle.Stop();
                partCycleBeep.Frequency = 600 + (autolockPartIndex * 80);
                var sample = partCycleBeep.Take(TimeSpan.FromSeconds(0.05));
                outPartCycle.Init(sample);
                outPartCycle.Play();

                string partName = autolockTarget.EntityType == EntityType.Ped
                    ? PED_TARGET_PARTS[autolockPartIndex].name
                    : VEHICLE_TARGET_PARTS[autolockPartIndex].name;
                Speech.Info(partName);
            }
        }

        // ============================================
        // SMART STEERING ASSISTS HELPER METHODS
        // ============================================

        /// <summary>
        /// Main processing method for steering assist - scans for threats and applies corrections
        /// </summary>
        // ============================================
        // STEERING ASSIST v3 GATING HELPERS
        // ============================================

        /// <summary>
        /// Half-width of the player vehicle, used for the brake-threat lateral cone.
        /// Approximated from the existing collision-radius accessor (which scales
        /// with vehicle class), so a bus has a wider cone than a motorcycle.
        /// </summary>
        // iter-18 A4: real half-extents from the model's bounding box, cached per
        // model hash. GET_MODEL_DIMENSIONS is a pure read on a loaded vehicle
        // model; degenerate results fall back to the legacy class-based
        // approximation at the call sites.
        private GTA.Math.Vector3 GetVehicleHalfDims(Vehicle veh)
        {
            int modelHash = veh.Model.Hash;
            GTA.Math.Vector3 half;
            if (vehicleHalfDimsCache.TryGetValue(modelHash, out half)) return half;
            OutputArgument oDimMin = new OutputArgument();
            OutputArgument oDimMax = new OutputArgument();
            Function.Call(Hash.GET_MODEL_DIMENSIONS, modelHash, oDimMin, oDimMax);
            GTA.Math.Vector3 dimMin = oDimMin.GetResult<GTA.Math.Vector3>();
            GTA.Math.Vector3 dimMax = oDimMax.GetResult<GTA.Math.Vector3>();
            half = new GTA.Math.Vector3(
                Math.Abs(dimMax.X - dimMin.X) * 0.5f,
                Math.Abs(dimMax.Y - dimMin.Y) * 0.5f,
                Math.Abs(dimMax.Z - dimMin.Z) * 0.5f);
            vehicleHalfDimsCache[modelHash] = half;
            return half;
        }

        // ================== iter-43 A: PER-VEHICLE GEOMETRY ==================
        // Every lateral and braking constant in this file was tuned on a sedan.
        // The 07-31 tester drove 19 vehicles from a 3.6 m Dilettante to a 9.9 m
        // Flatbed and reported that large trucks would not turn tightly enough,
        // would not stop in time, wedged more, and wandered in lane — all four.
        //
        // Everything needed to fix that was ALREADY being measured and thrown
        // away: GetVehicleHalfDims() caches true model extents, and
        // handlingSteerLockDeg / handlingMass are read from HandlingData every
        // vehicle change (handlingMass was assigned and never read by anything).
        // These helpers are the single funnel so the steering law, the clearance
        // checks and the brake distances cannot drift apart again.
        //
        // Gated on vehicleGeometryV2 — OFF by default, one gate per session.
        private const float GEOM_WHEELBASE_MIN = 2.0f;
        private const float GEOM_WHEELBASE_MAX = 7.0f;
        private const float GEOM_AXLE_FRACTION = 0.6f;   // matches the Stanley reference point
        private const float GEOM_MASS_REFERENCE = 1700f; // ~a GTA V sedan
        private const float GEOM_BRAKE_SCALE_MAX = 2.0f;

        private bool VehicleGeometryOn()
        {
            // iter-46 1-1: this is the single chokepoint every geometry consumer
            // passes through (wheelbase feedforward, steer-limit cap, rear-overhang
            // clamp, brake distances), so instrumenting it here covers them all.
            // On 07-31 the gate was toggled ON at F2190 and ran for 96% of the
            // session while the digest reported it "off" with eval:0/fire:0 —
            // wrong on both columns at once, for a gate that is actively scaling
            // the steering law (:32489 divides by its steer limit).
            bool on = getSetting("vehicleGeometryV2") == 1;
            if (on) GateReach("vehicleGeometryV2");
            return on;
        }

        /// <summary>
        /// Effective wheelbase (m). Pure pursuit's required steer angle for a given
        /// path curvature scales LINEARLY with wheelbase, so a fixed 2.8 m sedan
        /// value hands a 9.9 m flatbed roughly half the feedforward it needs and it
        /// runs wide on every bend. Falls back to the legacy constant on a
        /// degenerate model read.
        /// </summary>
        private float GetVehicleWheelbase(Vehicle veh)
        {
            if (veh == null || !VehicleGeometryOn()) return PURE_PURSUIT_WHEELBASE;
            try
            {
                float halfLen = GetVehicleHalfDims(veh).Y;
                if (halfLen < 1.0f || halfLen > 8.0f) return PURE_PURSUIT_WHEELBASE;
                float wb = halfLen * 2f * GEOM_AXLE_FRACTION;
                if (wb < GEOM_WHEELBASE_MIN) wb = GEOM_WHEELBASE_MIN;
                else if (wb > GEOM_WHEELBASE_MAX) wb = GEOM_WHEELBASE_MAX;
                return wb;
            }
            catch { return PURE_PURSUIT_WHEELBASE; }
        }

        /// <summary>
        /// iter-51: the effective steering lock in DEGREES, which is not always the
        /// one handling.meta reports.
        ///
        /// SHVDN's HandlingData.SteeringLock reads a hardcoded MemoryAddress+0x80,
        /// while Vehicle.SteeringAngle resolves its offset by runtime pattern scan.
        /// When those two disagree the ACHIEVED angle is the trustworthy side, and
        /// on 08-11 they disagreed badly: TEZERACT reported lockDeg=19.0 and reached
        /// 40.1 deg. Everything normalised against 19 deg on that car was wrong by
        /// a factor of two — the achieved side pegged at its clamp while the command
        /// still read below 1.0, so the two numbers on one FRAME line were not even
        /// on the same axis.
        ///
        /// Only ever trusts an observation that EXCEEDS the report (a car cannot
        /// steer further than its lock, so a larger observation falsifies the
        /// report; a smaller one just means nobody turned hard yet).
        /// </summary>
        private float EffectiveSteerLockDeg()
        {
            float reported = handlingSteerLockDeg;
            if (observedSteerLockDeg > 1f
                && (reported <= 1f || observedSteerLockDeg > reported * LOCK_OVERRIDE_MARGIN))
                return observedSteerLockDeg;
            return reported;
        }

        /// <summary>
        /// iter-51: THE steering denominator — the single value both the commanded
        /// and the achieved normalisation divide by, so that `liveSteer` and
        /// `steerAch` on one log line describe the same axis.
        ///
        /// Pure: takes the gate state as an argument instead of calling
        /// VehicleGeometryOn(), because that helper increments the gate's reach
        /// counter and the telemetry sampler must not inflate a behaviour gate's
        /// census.
        ///
        /// Still capped at the legacy PURE_PURSUIT_DELTA_MAX, so an observed lock
        /// can only ever move the limit back UP toward the 35 deg default that the
        /// gate-off path already uses — never past it. That bound is what makes it
        /// safe to feed an observation into the control law mid-drive.
        /// </summary>
        private float SteerNormLimitRad(bool geometryOn)
        {
            if (!geometryOn) return PURE_PURSUIT_DELTA_MAX;
            float lockDeg = EffectiveSteerLockDeg();
            if (lockDeg <= 1f) return PURE_PURSUIT_DELTA_MAX;
            return Math.Min(PURE_PURSUIT_DELTA_MAX, lockDeg * (float)Math.PI / 180f);
        }

        /// <summary>
        /// Steering limit (radians) this vehicle can physically reach. Commanding
        /// the fixed 0.61 rad (~35 deg) cap into a vehicle whose real lock is
        /// 19 deg — as the 07-31 actuation-divergence lines report — just saturates
        /// the command and makes commanded-vs-achieved meaningless. Never widens
        /// the limit beyond the legacy cap, only narrows it to what exists.
        /// </summary>
        private float GetVehicleSteerLimitRad()
        {
            return SteerNormLimitRad(VehicleGeometryOn());
        }

        /// <summary>
        /// Multiplier on every brake/threat distance, from the vehicle's mass and
        /// its front overhang. A loaded truck needs materially more room than the
        /// fixed BRAKE_DIST_* constants allow. Clamped to [1,2] so this can only
        /// ever ask to brake EARLIER than the sedan tune, never later.
        /// </summary>
        private float VehicleBrakeScale(Vehicle veh)
        {
            if (veh == null || !VehicleGeometryOn()) return 1f;
            float scale = 1f;
            try
            {
                if (handlingMass > 100f)
                {
                    // sqrt, not linear: stopping distance grows with mass but the
                    // brakes scale with it too, so linear badly over-brakes.
                    scale = (float)Math.Sqrt(handlingMass / GEOM_MASS_REFERENCE);
                }
                float halfLen = GetVehicleHalfDims(veh).Y;
                if (halfLen >= 1.0f && halfLen <= 8.0f)
                {
                    // Front overhang beyond the sedan reference (~2.4 m half-length)
                    // is bumper that arrives at the obstacle before the sensor origin.
                    float overhang = Math.Max(0f, halfLen - 2.4f);
                    scale += overhang * 0.15f;
                }
            }
            catch { return 1f; }
            if (scale < 1f) scale = 1f;
            else if (scale > GEOM_BRAKE_SCALE_MAX) scale = GEOM_BRAKE_SCALE_MAX;
            return scale;
        }

        /// <summary>
        /// True half-length (m) for clearance work, WITHOUT the legacy 4.0 m clamp
        /// that told the reverse model a 9.9 m flatbed was a 8 m vehicle and backed
        /// it into things. Keeps the 1.0 m floor and an 8.0 m ceiling as sanity.
        /// </summary>
        private float GetVehicleHalfLengthForClearance(Vehicle veh)
        {
            float cap = VehicleGeometryOn() ? 8.0f : 4.0f;
            try
            {
                return Math.Min(cap, Math.Max(1.0f, GetVehicleHalfDims(veh).Y));
            }
            catch { return Math.Min(cap, 3.0f); }
        }

        private float GetVehicleHalfWidth(Vehicle veh)
        {
            // iter-18 A4: use the model's true half-width (a bike reads ~0.4 m, a
            // dump truck ~1.4 m) instead of the class-based approximation, so the
            // brake cone matches the body that actually has to fit. The clamp
            // guards against degenerate model reads; the legacy class formula is
            // the fallback outside it.
            float w = GetVehicleHalfDims(veh).X;
            if (w >= 0.30f && w <= 1.80f) return w;
            return Math.Max(0.6f, GetVehicleCollisionRadius(veh) * 0.42f);
        }

        /// <summary>
        /// Checks whether an obstacle sits inside the player's forward "brake cone"
        /// — i.e. its lateral offset (in vehicle frame) is within ±(half-width + 0.5 m).
        /// Adjacent-lane parked cars fail this and so are excluded from brake triggers
        /// while still appearing to side-clearance / steering logic.
        /// </summary>
        private bool IsInBrakeCone(Vehicle playerVeh, GTA.Math.Vector3 obstaclePos)
        {
            GTA.Math.Vector3 toObs = obstaclePos - playerVeh.Position;
            GTA.Math.Vector3 fwd = isReversing ? -playerVeh.ForwardVector : playerVeh.ForwardVector;
            GTA.Math.Vector3 right = isReversing ? -playerVeh.RightVector : playerVeh.RightVector;
            if (GTA.Math.Vector3.Dot(fwd, toObs) <= 0f) return false; // not ahead
            float lateral = Math.Abs(GTA.Math.Vector3.Dot(right, toObs));
            return lateral <= GetVehicleHalfWidth(playerVeh) + 0.5f;
        }

        /// <summary>
        /// Entity-age + monotonic-drop gate for entity-derived brake threats. Returns
        /// true if this entity has been visible long enough AND its TTC has been
        /// dropping for the required number of cycles. Single-frame spikes from
        /// stream-in or normal jitter fail this check.
        /// </summary>
        private bool BrakeThreatPassesEntityGates(int handle, float ttc, long nowTicks, bool isPedestrian, float playerSpeedMs)
        {
            // Track first-seen time.
            if (!entityFirstSeenTicks.ContainsKey(handle))
            {
                entityFirstSeenTicks[handle] = nowTicks;
                entityLastTtc[handle] = ttc;
                entityMonotonicCount[handle] = 0;
                // First sighting is silent — too noisy to log every new
                // entity passing the cone gate; would flood the log in
                // any traffic situation.
                return false;
            }

            long ageMs = (nowTicks - entityFirstSeenTicks[handle]) / 10000;
            if (nowTicks - entityFirstSeenTicks[handle] < ENTITY_AGE_MIN_TICKS)
            {
                LogBrakeReject(handle, "age-too-young ageMs=" + ageMs + " needed="
                    + (ENTITY_AGE_MIN_TICKS / 10000), nowTicks);
                return false;
            }

            // Iter-9 Patch B: high-speed imminent-threat bypass. The 3-frame
            // monotonic-drop gate adds ~150 ms latency. At 30 m/s closing on
            // a stopped lead vehicle, that's 4.5 m of distance lost before
            // brake arms (markers F1591, F9672, F9785, F8350 in driveassist-
            // 2026-05-25-180748 are this scenario). When the player is
            // already at meaningful speed AND TTC is below 1.0 s, the
            // monotonic streak isn't worth waiting for — arm now. The
            // entity-age floor (100 ms, above) still protects against
            // stream-in false positives.
            if (ttc < 1.0f && ttc > 0f && playerSpeedMs > 8f)
            {
                // Still update the streak fields so we don't double-count if
                // monotonic logic later sees this entity.
                float prevTtc = entityLastTtc.ContainsKey(handle) ? entityLastTtc[handle] : ttc;
                entityLastTtc[handle] = ttc;
                if (entityMonotonicCount.ContainsKey(handle))
                    entityMonotonicCount[handle] = Math.Max(entityMonotonicCount[handle], BRAKE_MONOTONIC_FRAMES);
                else
                    entityMonotonicCount[handle] = BRAKE_MONOTONIC_FRAMES;
                return true;
            }

            // iter-14 Patch Z: low-speed-inclusive emergency bypass. The
            // high-speed bypass above only fires at playerSpeedMs > 8, so the
            // urban pedestrian hits in driveassist-2026-05-29-131428 (AUTO #10
            // -39.1, #8 -25.7) slipped through: a ped stepping in at TTC ~0.09 s
            // while the car rolled at 2-7 m/s was filtered by the monotonic gate
            // (a momentary ttc-rising zeroed the streak — log F5484), so it never
            // became the closest brake threat and the imminent override never saw
            // it. Anything genuinely sub-0.4 s ahead must arm NOW regardless of
            // trend or speed. The entity-age floor (100 ms, above) still guards
            // stream-in spikes, the cone/forward pre-gate is enforced by callers,
            // and the BRAKE_MIN_USEFUL_DIST (1 m) floor is still applied
            // downstream at the hasBrakeThreat selection.
            if (ttc > 0f && ttc < EMERGENCY_BRAKE_TTC)
            {
                float prevTtc = entityLastTtc.ContainsKey(handle) ? entityLastTtc[handle] : ttc;
                entityLastTtc[handle] = ttc;
                if (entityMonotonicCount.ContainsKey(handle))
                    entityMonotonicCount[handle] = Math.Max(entityMonotonicCount[handle], BRAKE_MONOTONIC_FRAMES);
                else
                    entityMonotonicCount[handle] = BRAKE_MONOTONIC_FRAMES;
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] EVENT brake-emergency: entity=" + handle
                        + " ttc=" + ttc.ToString("F2") + " prev=" + prevTtc.ToString("F2")
                        + " ped=" + isPedestrian);
                return true;
            }

            // iter-36 B2: STANDOFF bypass. A head-on pusher holding a constant gap
            // has constant TTC — the monotonic gate rejected entity 357994 for
            // ~40 s at Dorset (streak count=0) until a single 980-pt kill hit
            // (07-04 death #2). The two bypasses above can't see it either: no
            // own-speed (>8 m/s gate) and no sub-0.4 s TTC ever forms at zero
            // closing rate. "Someone moving into my stationary car" is physically
            // disjoint from the parallax/ground-graze false positives the
            // monotonic filter exists to reject (those involve own motion): arm
            // when own speed < 2 m/s, the entity is < 6 m ahead, and its velocity
            // component toward us exceeds 0.5 m/s. Entity-age floor still applies.
            if (getSetting("standoffThreat") == 1 && playerSpeedMs < 2f)
            {
                Entity standoffEnt = Entity.FromHandle(handle);
                Vehicle standoffPv = Game.Player.Character.IsInVehicle()
                    ? Game.Player.Character.CurrentVehicle : null;
                if (standoffEnt != null && standoffEnt.Exists() && standoffPv != null)
                {
                    GTA.Math.Vector3 toEnt = standoffEnt.Position - standoffPv.Position;
                    float entDist = toEnt.Length();
                    float closing = entDist > 0.01f
                        ? GTA.Math.Vector3.Dot(standoffEnt.Velocity, -(toEnt / entDist))
                        : 0f;
                    if (entDist < 6f
                        && GTA.Math.Vector3.Dot(standoffPv.ForwardVector, toEnt) > 0f
                        && closing > 0.5f)
                    {
                        entityLastTtc[handle] = ttc;
                        entityMonotonicCount[handle] = Math.Max(
                            entityMonotonicCount.ContainsKey(handle) ? entityMonotonicCount[handle] : 0,
                            BRAKE_MONOTONIC_FRAMES);
                        if (driveLogger != null && driveLogger.IsRunning
                            && nowTicks - lastBrakeStandoffLogTicks > 10000000L)
                        {
                            lastBrakeStandoffLogTicks = nowTicks;
                            driveLogger.Write("[F" + driveLogFrameCount
                                + "] EVENT brake-standoff: ent=" + handle
                                + " dist=" + entDist.ToString("F1")
                                + " closing=" + closing.ToString("F1")
                                + " ownSpd=" + playerSpeedMs.ToString("F1")
                                + " ped=" + isPedestrian);
                        }
                        return true;
                    }
                }
            }

            // Monotonic-drop count: increment if TTC dropped from last seen sample.
            // Vehicles use symmetric thresholds (+/-0.04 s) — that's the Bug E
            // fix from the prior iteration which stopped stale traffic from
            // randomly tripping brake.
            // Pedestrians use a slightly asymmetric pair (drop 0.025 / reset
            // 0.05): driveassist-2026-05-25-111452 showed visible peds at
            // 5-12 m failing to trip brake because the symmetric 0.04 gate
            // was too conservative for slow-streaming-in peds whose TTC
            // samples are noisy on first acquisition. Peds move at 1-2 m/s,
            // so an asymmetric threshold here can't generate phantom approach
            // trends (their actual TTC trend on approach is monotonically
            // strong).
            float dropThresh  = isPedestrian ? 0.025f : 0.04f;
            float resetThresh = isPedestrian ? 0.05f  : 0.04f;
            float prev = entityLastTtc.ContainsKey(handle) ? entityLastTtc[handle] : ttc;
            int count = entityMonotonicCount.ContainsKey(handle) ? entityMonotonicCount[handle] : 0;
            bool resetByRise = ttc > prev + resetThresh;
            if (ttc < prev - dropThresh) count++;
            else if (resetByRise) count = 0;
            entityLastTtc[handle] = ttc;
            entityMonotonicCount[handle] = count;

            bool passed = count >= BRAKE_MONOTONIC_FRAMES;
            if (!passed)
            {
                // Distinguish "TTC rising — entity moving away" from
                // "monotonic streak still building." Both are valid reasons
                // brake didn't arm; logging the distinction lets us spot a
                // gate misconfiguration in the next log.
                if (resetByRise)
                    LogBrakeReject(handle, "ttc-rising prev=" + prev.ToString("F2")
                        + " curr=" + ttc.ToString("F2"), nowTicks);
                else
                    LogBrakeReject(handle, "monotonic-streak count=" + count
                        + " needed=" + BRAKE_MONOTONIC_FRAMES
                        + " ttc=" + ttc.ToString("F2"), nowTicks);
            }
            return passed;
        }

        // Iter-9 Patch H: throttled log emission for brake-gate rejections.
        // Callers of BrakeThreatPassesEntityGates have already gated the
        // entity on "forward + in cone + ttc better than current best", so
        // anything that reaches this function is a serious candidate; that's
        // why a "didn't pass" outcome warrants logging. 1 s per-entity cooldown
        // prevents sustained tailing from spamming.
        private void LogBrakeReject(int handle, string reason, long nowTicks)
        {
            if (driveLogger == null || !driveLogger.IsRunning) return;
            long last;
            if (entityLastRejectLogTicks.TryGetValue(handle, out last)
                && nowTicks - last < BRAKE_REJECT_LOG_COOLDOWN_TICKS) return;
            entityLastRejectLogTicks[handle] = nowTicks;
            driveLogger.Write("[F" + driveLogFrameCount
                + "] EVENT brake-reject: entity=" + handle + " reason=" + reason);
        }

        /// <summary>
        /// Prunes stale per-entity tracking dictionaries so they don't grow without
        /// bound. Called periodically from ProcessSteeringAssist.
        /// </summary>
        private void PruneEntityTracking(long nowTicks)
        {
            if (nowTicks - entityTrackingLastPrune < 50000000) return; // 5 s
            entityTrackingLastPrune = nowTicks;
            const long STALE_TICKS = 30000000; // 3 s
            var stale = new List<int>();
            foreach (var kv in entityFirstSeenTicks)
                if (nowTicks - kv.Value > STALE_TICKS) stale.Add(kv.Key);
            foreach (int h in stale)
            {
                entityFirstSeenTicks.Remove(h);
                entityLastTtc.Remove(h);
                entityMonotonicCount.Remove(h);
                entityLastRejectLogTicks.Remove(h);
            }
            var staleLatch = new List<int>();
            foreach (var kv in adjacentLatchUntilTicks)
                if (nowTicks > kv.Value) staleLatch.Add(kv.Key);
            foreach (int h in staleLatch) adjacentLatchUntilTicks.Remove(h);
        }

        /// <summary>
        /// Refreshes the adjacent-vehicle latch by scanning nearby vehicles. A
        /// vehicle whose position falls inside the player's "shoulder band"
        /// (±ADJACENT_LATERAL_BAND lateral, -ADJACENT_LONG_BACK..+ADJACENT_LONG_FRONT
        /// longitudinal) is recorded with a latch expiry of now + ADJACENT_LATCH_TICKS.
        /// CalculateLateralAvoidance consults the latch to suppress steering
        /// toward adjacent vehicles, eliminating side-brushing.
        /// </summary>
        private void UpdateAdjacentLatch(Vehicle playerVeh, Vehicle[] nearbyVehs, long nowTicks)
        {
            adjacentLatchedLeft = false;
            adjacentLatchedRight = false;
            GTA.Math.Vector3 playerPos = playerVeh.Position;
            GTA.Math.Vector3 fwd = isReversing ? -playerVeh.ForwardVector : playerVeh.ForwardVector;
            GTA.Math.Vector3 right = isReversing ? -playerVeh.RightVector : playerVeh.RightVector;

            foreach (Vehicle veh in nearbyVehs)
            {
                if (veh == null || veh == playerVeh) continue;
                GTA.Math.Vector3 toVeh = veh.Position - playerPos;
                float longComp = GTA.Math.Vector3.Dot(fwd, toVeh);
                float latComp = GTA.Math.Vector3.Dot(right, toVeh);
                bool inBand = longComp > -ADJACENT_LONG_BACK
                              && longComp < ADJACENT_LONG_FRONT
                              && Math.Abs(latComp) < ADJACENT_LATERAL_BAND;
                int h = veh.Handle;
                if (inBand)
                {
                    adjacentLatchUntilTicks[h] = nowTicks + ADJACENT_LATCH_TICKS;
                    if (latComp > 0) adjacentLatchedRight = true;
                    else adjacentLatchedLeft = true;
                }
                else if (adjacentLatchUntilTicks.ContainsKey(h)
                         && nowTicks <= adjacentLatchUntilTicks[h])
                {
                    // Still latched from prior pass — clear only when truly separated.
                    if (Math.Abs(latComp) < ADJACENT_CLEAR_LATERAL)
                    {
                        if (latComp > 0) adjacentLatchedRight = true;
                        else adjacentLatchedLeft = true;
                    }
                    else
                    {
                        adjacentLatchUntilTicks.Remove(h);
                    }
                }
            }
        }

        private void ProcessSteeringAssist(Vehicle playerVeh, bool isFullMode)
        {
            driveAssistFrameTicks = DateTime.Now.Ticks; // stable reference for all history queries this frame
            GTA.Math.Vector3 playerPos = playerVeh.Position;
            GTA.Math.Vector3 forwardVec = playerVeh.ForwardVector;
            GTA.Math.Vector3 rightVec = playerVeh.RightVector;
            float vehicleSpeed = playerVeh.Speed;

            // ============================================
            // VEHICLE TYPE CHECK - Skip aircraft and boats
            // Drive assist only makes sense for land vehicles
            // ============================================
            if (playerVeh.IsAircraft || playerVeh.IsBoat)
            {
                steeringAssistActive = false;
                return;
            }

            // ============================================
            // REVERSE DRIVING DETECTION
            // Check if player is driving backwards based on velocity vs forward vector
            // ============================================
            GTA.Math.Vector3 velocity = playerVeh.Velocity;
            if (velocity.Length() > 1f)
            {
                float dotVelForward = GTA.Math.Vector3.Dot(GTA.Math.Vector3.Normalize(velocity), forwardVec);
                isReversing = dotVelForward < -0.3f; // Moving backward if velocity opposes forward vector
            }
            else
            {
                isReversing = false;
            }

            // ============================================
            // HILL/INCLINE COMPENSATION
            // Use a flattened forward vector for ground-based calculations
            // ============================================
            GTA.Math.Vector3 flatForward = new GTA.Math.Vector3(forwardVec.X, forwardVec.Y, 0);
            if (flatForward.Length() > 0.1f)
            {
                flatForward = GTA.Math.Vector3.Normalize(flatForward);
            }
            else
            {
                flatForward = forwardVec; // Fallback if nearly vertical (unlikely for cars)
            }

            // ============================================
            // WAYPOINT-AWARE DRIVE ASSIST
            // Updates cached waypoint direction for road node preference
            // Uses both waypoint and mission blip positions
            // ============================================
            if (getSetting("waypointDriveAssist") == 1)
            {
                // Update waypoint info periodically (every 500ms)
                if (DateTime.Now.Ticks - waypointUpdateTicks > 5000000)
                {
                    waypointUpdateTicks = DateTime.Now.Ticks;
                    UpdateWaypointDirection(playerPos);
                }
            }
            else
            {
                hasActiveWaypoint = false;
            }

            // ============================================
            // PATH POLYLINE — single source of truth for "where the AI would
            // drive next." Built once per detection tick from GPS route /
            // static graph / native nearest-node, in that priority. All
            // downstream gates (NPC corridor filter, Stanley lane keep) use
            // this polyline; replaces the noisy single-node sampling that
            // caused the side-to-side drift.
            // ============================================
            BuildPathPolyline(playerVeh);

            // iter-49 A1/A2: the engine's own lane counts, road edge and node
            // hazard flags. Same dark-launch contract as the iter-42 pair —
            // sampled and logged, consumed by nothing until validated. Runs
            // BEFORE the junction detector so the hazard walk and the third
            // junction source read this scan's flags rather than last scan's,
            // and AFTER BuildPathPolyline so the polyline-divergence cross-check
            // measures against the lead segment we are actually steering on.
            SampleEngineRoadModel(playerVeh, flatForward);
            // iter-49 A4: map-wide traffic-light / give-way / dead-end walk. Feeds
            // UpdateJunctionApproach's third arming source, so it must precede it.
            UpdateNodeHazards(playerVeh);
            // iter-49 B3: the Assistive-mode Pull Over governor.
            UpdatePullOverGovernor(playerVeh);

            // iter-32: road-graph enrichment detectors. All run every scan for
            // telemetry; control/speech output is individually setting-gated
            // inside each (dark-launch pattern, same as laneOffsetPolyline).
            UpdateJunctionApproach(playerVeh);
            UpdateWrongWayDetector(playerVeh);
            UpdateSpeedZoneGovernor(playerVeh);
            // iter-51: strictly AFTER the node-category governor, which zeroes the
            // shared request at its top and may early-return before setting it.
            // This one only ever raises it.
            UpdateRoadClassGovernor(playerVeh);
            // iter-42 B1/B2: measured carriageway + ground grade/camber. Same
            // dark-launch pattern — sampled here, logged in the road: line, and
            // consumed by NOTHING until a session validates the readings. The
            // curve-brake gravity term is deliberately deferred until grade has
            // been cross-checked against the A3 wheel-contact plane fit.
            SampleRoadGeometry(playerVeh, flatForward);
            // iter-49 B1: kerb geometry, and which kerb is on our side.
            SampleKerbGeometry(playerVeh);
            // iter-49 C1: the engine's four stuck timers. Sampled in BOTH modes —
            // UpdateStuckRecovery only runs in Full, and a detector observed solely
            // where the mod already acts cannot show what the mod is missing.
            SampleEngineStuck(playerVeh);
            // iter-49 D: is the damage we are about to attribute to driving
            // actually gunfire? Ungated sampling — the fields go on the marker
            // header either way; only the veto and the cue are gated.
            SampleUnderFire(playerVeh);

            // iter-18 A3: entity detection range. The old hard 40 m cap
            // (10 + min(v/30,1)*30) is ~1.3 s of headway at 30 m/s — less than
            // reaction + brake ramp + stopping distance, so a stopped lead vehicle
            // on the highway entered the scan too late to brake for. Use the same
            // per-class meta brake-lookahead the geometry rays and nav scanner
            // already use, clamped 15-120 m.
            var entityScanAi = VehicleAIHandlingRegistry.GetForVehicle(playerVeh);
            // iter-35 P4: TTC floor on top of the meta curve. The fast-car profile
            // yields only ~48-55 m at 22.7 m/s (2.1 s) — 07-03 #1 cached a static
            // prop 2.06 s pre-impact and hit it at 51 mph. 3.5 s of headway minimum.
            float detectionRange = Math.Min(120f, Math.Max(15f,
                Math.Max(entityScanAi.BrakeLookaheadForSpeed(vehicleSpeed) * 1.3f,
                         vehicleSpeed * 3.5f)));

            // ============================================
            // SEPARATED THREAT DETECTION:
            // - steerTTC: Used for steering avoidance (includes front AND side threats)
            // - brakeTTC: Used ONLY for braking (ONLY front/ahead threats)
            // This prevents side obstacles from triggering braking, which was limiting speed
            // ============================================
            float closestSteerTTC = float.MaxValue;  // For steering decisions (all directions)
            float closestBrakeTTC = float.MaxValue;  // For braking decisions (ONLY ahead)
            float closestBrakeDistance = float.MaxValue; // Distance to closest brake threat
            string closestDir = "none";
            string closestType = "none";
            int avoidDirection = 0;
            GTA.Math.Vector3 closestSteerThreatPos = GTA.Math.Vector3.Zero; // Position of closest steer threat
            GTA.Math.Vector3 closestSteerThreatVel = GTA.Math.Vector3.Zero; // Velocity (Zero = static)
            GTA.Math.Vector3 closestBrakeThreatPos = GTA.Math.Vector3.Zero; // Position of closest brake threat
            GTA.Math.Vector3 closestBrakeThreatVel = GTA.Math.Vector3.Zero;
            string closestBrakeType = "none"; // Type of closest brake threat

            // Scan nearby peds
            Ped[] nearbyPeds = World.GetNearbyPeds(playerPos, detectionRange);
            foreach (Ped ped in nearbyPeds)
            {
                if (ped == Game.Player.Character || ped.IsDead) continue;

                // Path-corridor filter: keep peds whose position is within
                // NPC_PATH_CORRIDOR_M of the upcoming polyline. Replaces the
                // old IsPositionOnRoad gate which was unreliable (especially
                // in parking lots and on the curb) and missed stationary peds
                // standing in our travel path. Moving peds (speed > 0.5) skip
                // the gate entirely — they may step into the path next frame.
                if (ped.Speed < 0.5f && !IsInPathCorridor(ped.Position, NPC_PATH_CORRIDOR_M)) continue;

                float ttc = CalculateTTC(playerVeh, ped.Position, ped.Velocity);
                string dir = GetThreatDirection(playerVeh, ped.Position);
                float dist = (ped.Position - playerPos).Length(); // iter-18 D3: managed math, no native round-trip

                // Update steering TTC (all directions)
                if (ttc < closestSteerTTC)
                {
                    closestSteerTTC = ttc;
                    closestType = "pedestrian";
                    closestDir = dir;
                    avoidDirection = GetAvoidDirection(playerVeh, ped.Position);
                    closestSteerThreatPos = ped.Position;
                    closestSteerThreatVel = ped.Velocity;
                }

                // Update braking TTC ONLY for threats ahead AND inside the brake cone
                // AND visibility-aged (kills spawn-in false TTC) AND monotonic-dropping.
                if (dir == "ahead" && ttc < closestBrakeTTC
                    && IsInBrakeCone(playerVeh, ped.Position)
                    && BrakeThreatPassesEntityGates(ped.Handle, ttc, DateTime.Now.Ticks, isPedestrian: true, playerSpeedMs: vehicleSpeed))
                {
                    closestBrakeTTC = ttc;
                    closestBrakeDistance = dist;
                    closestBrakeType = "pedestrian";
                    closestBrakeThreatPos = ped.Position;
                    closestBrakeThreatVel = ped.Velocity;
                }
            }

            // Scan nearby vehicles
            Vehicle[] nearbyVehs = World.GetNearbyVehicles(playerPos, detectionRange);
            long gateNow = DateTime.Now.Ticks;
            PruneEntityTracking(gateNow);
            UpdateAdjacentLatch(playerVeh, nearbyVehs, gateNow);
            foreach (Vehicle veh in nearbyVehs)
            {
                if (veh == playerVeh) continue;

                // Path-corridor filter: stationary vehicles outside the
                // upcoming polyline corridor are ignored (parked cars on the
                // shoulder). Moving vehicles always register since they may
                // turn into our path. Replaces the IsObstacleInTravelLane
                // cone heuristic — the polyline tracks curves, the cone did
                // not.
                if (veh.Speed < 0.5f && !IsInPathCorridor(veh.Position, NPC_PATH_CORRIDOR_M)) continue;

                float ttc = CalculateTTC(playerVeh, veh.Position, veh.Velocity);
                string dir = GetThreatDirection(playerVeh, veh.Position);
                float dist = (veh.Position - playerPos).Length(); // iter-18 D3: managed math, no native round-trip

                // Update steering TTC (all directions)
                if (ttc < closestSteerTTC)
                {
                    closestSteerTTC = ttc;
                    closestType = "vehicle";
                    closestDir = dir;
                    avoidDirection = GetAvoidDirection(playerVeh, veh.Position);
                    closestSteerThreatPos = veh.Position;
                    closestSteerThreatVel = veh.Velocity;
                }

                // Update braking TTC ONLY for threats ahead AND inside the brake cone
                // AND that have been visible long enough AND whose TTC is dropping.
                // Together these gates kill the "sudden brake out of nowhere" complaint.
                if (dir == "ahead" && ttc < closestBrakeTTC
                    && IsInBrakeCone(playerVeh, veh.Position)
                    && BrakeThreatPassesEntityGates(veh.Handle, ttc, gateNow, isPedestrian: false, playerSpeedMs: vehicleSpeed))
                {
                    closestBrakeTTC = ttc;
                    closestBrakeDistance = dist;
                    closestBrakeType = "vehicle";
                    closestBrakeThreatPos = veh.Position;
                    closestBrakeThreatVel = veh.Velocity;
                }
            }

            // ============================================
            // MULTI-RAYCAST FOR WORLD GEOMETRY
            // Uses flattened forward vector for hill compensation
            // Multiple rays provide better coverage for obstacles
            // Direction depends on whether we're reversing
            // ============================================
            GTA.Math.Vector3 startPos = playerPos + new GTA.Math.Vector3(0, 0, 0.5f);
            // Obstacle look-ahead: iter-8 derives this from GTA V's own AI
            // handling table for the current vehicle class instead of the
            // older class-agnostic `vehicleSpeed * 3.5f` formula. The meta's
            // BrakeLookaheadForSpeed blends MinBrakeDistance->MaxBrakeDistance
            // by speed/MaxSpeedAtBrakeDistance — a truck gets longer ray
            // range than a sports car at the same speed. 1.3x margin so the
            // brake has time to ramp up rather than firing at the last
            // possible moment. Same 15-150 m clamp as before for safety.
            var rayAi = VehicleAIHandlingRegistry.GetForVehicle(playerVeh);
            // iter-35 P4: same 3.5 s TTC floor as the entity scan (see comment there).
            float rayRange = Math.Min(150f, Math.Max(15f,
                Math.Max(rayAi.BrakeLookaheadForSpeed(vehicleSpeed) * 1.3f,
                         vehicleSpeed * 3.5f)));

            // Use the direction we're actually traveling
            GTA.Math.Vector3 travelDir = isReversing ? -flatForward : flatForward;
            GTA.Math.Vector3 travelRight = isReversing ? -rightVec : rightVec;

            // iter-20 H5: model-true cast origin. Start the drive-assist casts at
            // the LEADING bumper (forward or rear per travel direction) with a
            // height derived from the model instead of the geometric center at a
            // fixed +0.5 Z — center origins were silently costing half a
            // car-length of effective sensing range. Own vehicle is excluded from
            // every cast, so self-hits cannot occur. Distances downstream become
            // bumper-true (re-check MIN_BRAKE_DISTANCE semantics in the next log).
            GTA.Math.Vector3 castHalfDims = GetVehicleHalfDims(playerVeh);
            float castZ = Math.Min(1.0f, Math.Max(0.4f, castHalfDims.Z * 0.6f));
            startPos = playerPos
                + travelDir * Math.Min(4.0f, Math.Max(0f, castHalfDims.Y * 0.85f))
                + new GTA.Math.Vector3(0, 0, castZ - 0.5f);

            // Cast a fan of 5 rays. The inner 3 (±0,±17°) feed STEERING and BRAKE
            // sources; the outer 2 (±35°) feed STEERING ONLY. Wider rays catch
            // glancing-angle rails/walls without producing the phantom-brake
            // problem (city walls in the periphery would otherwise constantly
            // brake the car).
            float[] rayOffsets = { 0f, -0.3f, 0.3f, -0.7f, 0.7f };
            bool[] rayBrakeEligible = { true, true, true, false, false };
            float closestRayDist = float.MaxValue;
            float closestBrakeEligibleRayDist = float.MaxValue;
            GTA.Math.Vector3 closestRayHitPos = GTA.Math.Vector3.Zero;
            GTA.Math.Vector3 closestBrakeEligibleRayHitPos = GTA.Math.Vector3.Zero;
            int bestAvoidDir = 0;
            // Nearest hit on each side of the fan — used to tell whether a
            // swerve actually has anywhere to go (see brake promotion below).
            float leftRayHitDist = float.MaxValue;
            float rightRayHitDist = float.MaxValue;

            for (int rIdx = 0; rIdx < rayOffsets.Length; rIdx++)
            {
                float offset = rayOffsets[rIdx];
                GTA.Math.Vector3 rayDir = GTA.Math.Vector3.Normalize(travelDir + travelRight * offset);
                RaycastResult ray = World.Raycast(startPos, startPos + (rayDir * rayRange),
                    IntersectFlags.Map | IntersectFlags.Objects, playerVeh);

                if (!ray.DidHit) continue;
                // GROUND-Z FILTER: skip hits that look like road/ground (mostly
                // vertical normal). Threshold 0.85 — only surfaces tilted up to
                // ~32 deg count as ground. Old 0.7 (~45 deg) was rejecting
                // sloped guardrails and embankment walls as "ground".
                if (Math.Abs(ray.SurfaceNormal.Z) > 0.85f) continue;

                float dist = (ray.HitPosition - startPos).Length(); // iter-18 D3

                if (dist < closestRayDist)
                {
                    closestRayDist = dist;
                    closestRayHitPos = ray.HitPosition;
                    if (offset < 0) bestAvoidDir = 1;
                    else if (offset > 0) bestAvoidDir = -1;
                    else bestAvoidDir = GetClearerSide(playerVeh, rayRange);
                }
                if (offset < 0f) { if (dist < leftRayHitDist) leftRayHitDist = dist; }
                else if (offset > 0f) { if (dist < rightRayHitDist) rightRayHitDist = dist; }
                if (rayBrakeEligible[rIdx] && dist < closestBrakeEligibleRayDist)
                {
                    closestBrakeEligibleRayDist = dist;
                    closestBrakeEligibleRayHitPos = ray.HitPosition;
                }
            }

            // VOLUMETRIC CAPSULE SWEEP — the 5-ray fan has angular gaps that grow
            // with distance (at 80m the +/-17deg rays are ~24m apart laterally),
            // easily wide enough to miss a guardrail end-cap or a single pillar.
            // The capsule fills those gaps with a continuous swept volume.
            // Always brake-eligible: if it volumetrically clears, the car
            // physically cannot fit past.
            GTA.Math.Vector3 capsuleHitPos, capsuleHitNorm;
            float capsuleDist = PerformShapeCast(startPos, travelDir, travelRight,
                rayRange, IntersectFlags.Map | IntersectFlags.Objects, playerVeh,
                out capsuleHitPos, out capsuleHitNorm, vehicleSpeed,
                GetVehicleHalfWidth(playerVeh) + 0.2f);
            // iter-18 A8: overhead gate. At highway speed the capsule radius reaches
            // 2.5 m from a start point only 0.5 m up, so the swept volume tops out
            // ~3 m — overhead signage / canopy territory. A hit more than 2 m above
            // the vehicle origin is something we drive UNDER, not into. (Mirrors the
            // static-wall cast's relZ ceiling.)
            float capsuleRelZ = capsuleDist > 0f
                ? capsuleHitPos.Z - playerVeh.Position.Z : 0f;
            if (capsuleDist > 0f && Math.Abs(capsuleHitNorm.Z) <= 0.85f
                && capsuleRelZ <= 2.0f)
            {
                if (capsuleDist < closestRayDist)
                {
                    closestRayDist = capsuleDist;
                    closestRayHitPos = capsuleHitPos;
                    // Lateral side from hit normal — sign of dot with travelRight
                    // gives the side the wall is on; we want to steer AWAY from it.
                    float capLat = GTA.Math.Vector3.Dot(travelRight, capsuleHitNorm);
                    if (capLat > 0.1f) bestAvoidDir = -1;
                    else if (capLat < -0.1f) bestAvoidDir = 1;
                    else bestAvoidDir = GetClearerSide(playerVeh, rayRange);
                }
                if (capsuleDist < closestBrakeEligibleRayDist)
                {
                    closestBrakeEligibleRayDist = capsuleDist;
                    closestBrakeEligibleRayHitPos = capsuleHitPos;
                }
            }

            // STEERING source: any of the 5 rays (wide fan).
            if (closestRayDist < rayRange)
            {
                float ttc = closestRayDist / Math.Max(vehicleSpeed, 1f);
                if (ttc < closestSteerTTC)
                {
                    closestSteerTTC = ttc;
                    closestType = "obstacle";
                    closestDir = "ahead";
                    avoidDirection = bestAvoidDir;
                    closestSteerThreatPos = closestRayHitPos;
                    closestSteerThreatVel = GTA.Math.Vector3.Zero;
                }
            }
            // BRAKE source: only inner-fan rays, gated by the NARROW brake cone.
            // Wide-angle hits never produce brake — they only produce steering.
            if (closestBrakeEligibleRayDist < rayRange)
            {
                float ttc = closestBrakeEligibleRayDist / Math.Max(vehicleSpeed, 1f);
                if (ttc < closestBrakeTTC && IsInBrakeCone(playerVeh, closestBrakeEligibleRayHitPos))
                {
                    closestBrakeTTC = ttc;
                    closestBrakeDistance = closestBrakeEligibleRayDist;
                    closestBrakeType = "obstacle";
                    closestBrakeThreatPos = closestBrakeEligibleRayHitPos;
                    closestBrakeThreatVel = GTA.Math.Vector3.Zero;
                }
            }
            // FORWARD-OBSTACLE BRAKE PROMOTION: a wide-fan obstacle normally
            // produces a swerve only. But if BOTH sides of the fan are blocked
            // the swerve has nowhere to go and the car plows straight in (debug
            // log F3578: obstacle ahead, zero brake, hit at 38 mph). When the
            // swerve is blocked, escalate the obstacle to a brake threat.
            bool swerveBlocked = leftRayHitDist < rayRange && rightRayHitDist < rayRange;
            if (closestRayDist < rayRange && swerveBlocked)
            {
                float ttc = closestRayDist / Math.Max(vehicleSpeed, 1f);
                if (ttc < closestBrakeTTC)
                {
                    closestBrakeTTC = ttc;
                    closestBrakeDistance = closestRayDist;
                    closestBrakeType = "obstacle";
                    closestBrakeThreatPos = closestRayHitPos;
                    closestBrakeThreatVel = GTA.Math.Vector3.Zero;
                }
            }

            // STATIC-WALL CAST — Map-only, wider radius, longer range. Static
            // geometry never moves, so we can plan ~5 s ahead vs the ~3.5 s used
            // for traffic. Splitting flags also stops small objects (parked
            // cars, hydrants) from masking a wall 30 m behind them. Brake-only:
            // a static wall ahead with no closer dynamic threat means brake
            // straight, don't swerve into traffic.
            GTA.Math.Vector3 staticHitPos, staticHitNorm;
            float staticRange, staticRadius;
            float staticDist = PerformStaticWallCast(startPos, travelDir,
                vehicleSpeed, playerVeh,
                out staticHitPos, out staticHitNorm,
                out staticRange, out staticRadius);
            // Tightened 2026-05-25:
            //  - normalZ filter 0.85 -> 0.60. Old threshold accepted surfaces only
            //    32° off horizontal (sloped curbs, embankment toes). 0.60 keeps
            //    only surfaces >=53° from horizontal — true walls, signs, building
            //    faces. Sloped curbs at normalZ 0.7-0.85 are no longer "walls".
            //  - IsInBrakeCone gate: the swept capsule has lateral radius up to
            //    2.2 m, so it can hit geometry outside the actual driving lane.
            //    Require the hit point to be in our forward corridor (same gate
            //    used by the nav-assist center brake source) before promoting to
            //    a brake threat. Surface-normal "wall faces us" head-on still
            //    bypasses this check below.
            // Iter-9 Patch D: elevation-aware static-wall gate.
            // The original `staticHitNorm.Z <= 0.60` filter correctly accepts
            // vertical walls but REJECTS the top surface of a curb / step /
            // low platform — those have normalZ ≈ 1.0 yet the car can't drive
            // through them. Driveassist-2026-05-25-180748 F7970/F8030/F8056
            // (3 collisions, same location, all logged as STATIC-REJECTED
            // dist=0.7 normalZ=1.00) is exactly this pattern.
            //
            // Add a parallel acceptance gate based on HIT ELEVATION relative
            // to the vehicle chassis: anything 0.3 m–2.0 m above the chassis
            // is at bumper-to-roof height and unswervable regardless of
            // surface orientation. Below 0.3 m we still reject (road surface,
            // manhole, low rumble strip). Above 2.0 m we still reject
            // (overpass, overhead sign — we drive under those).
            float staticRelZ = staticDist > 0f
                ? staticHitPos.Z - playerVeh.Position.Z : 0f;
            bool staticIsVerticalSurface = Math.Abs(staticHitNorm.Z) <= 0.60f;
            bool staticIsBumperHeightHit = staticRelZ >= 0.30f && staticRelZ <= 2.0f;
            bool staticHitValid = staticDist > 0f
                && (staticIsVerticalSurface || staticIsBumperHeightHit);
            if (staticHitValid)
            {
                // Wall facing us head-on? swerve-clearance check.
                bool staticWallFacesUs = false;
                GTA.Math.Vector3 sn = staticHitNorm; sn.Z = 0f;
                GTA.Math.Vector3 sfwd = playerVeh.ForwardVector; sfwd.Z = 0f;
                if (sn.LengthSquared() > 0.0001f && sfwd.LengthSquared() > 0.0001f)
                {
                    sn.Normalize(); sfwd.Normalize();
                    staticWallFacesUs = GTA.Math.Vector3.Dot(sn, -sfwd) > WALL_NORMAL_FACE_DOT;
                }
                bool staticInCone = IsInBrakeCone(playerVeh, staticHitPos);
                // Head-on bypass is only safe at short range. The capsule sweep
                // has lateral radius up to 2.2 m and runs out to v*3.5 (>100 m
                // at highway speed), so a building corner 20-30 m off-axis can
                // still register a "head-on" normal — promoting it to a brake
                // threat caused the wall-collision cluster in the
                // driveassist-2026-05-25-103730 audit. Beyond STATIC_HEADON_RANGE
                // require the in-cone gate to also pass; below it the head-on
                // bypass still wins because we're close enough that an
                // imminent dead-ahead wall is a true emergency.
                const float STATIC_HEADON_RANGE = 8f;
                if (!staticInCone && !(staticWallFacesUs && staticDist <= STATIC_HEADON_RANGE))
                    staticHitValid = false;
            }
            // iter-28 B-2: ground-graze corroboration. A below-bumper static hit is
            // normally the road (correctly rejected). But in the grind regime (slow +
            // close) a real low prop reads the same — if a known prop/vehicle entity
            // sits within ~1.5 m of the rejected hit, promote it to a real obstacle so
            // the brake can act. Bounded to slow+close so the GetNearbyProps probe
            // stays out of the hot path. 014616/024041 ground into low props that were
            // STATIC-REJECTED reason=below-bumper.
            if (!staticHitValid && staticDist > 0.2f && staticDist < 4f
                && staticRelZ < 0.30f && vehicleSpeed < 3f)
            {
                foreach (Prop pr in World.GetNearbyProps(staticHitPos, 1.5f))
                {
                    if (pr == null || !pr.Exists()) continue;
                    staticHitValid = true;
                    // iter-35 L5: 1 s throttle + suppressed count — 07-03 emitted
                    // 137 of 149 of these inside one 12 s window.
                    groundGrazeSuppressed++;
                    if (driveLogger != null && driveLogger.IsRunning
                        && DateTime.Now.Ticks - lastGroundGrazeLogTicks > 10000000L)
                    {
                        lastGroundGrazeLogTicks = DateTime.Now.Ticks;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT groundgraze-promote:"
                            + " dist=" + staticDist.ToString("F1")
                            + " hitPos=" + FmtV(staticHitPos)
                            + " prop=" + pr.Model.Hash
                            + " count=" + groundGrazeSuppressed);
                        groundGrazeSuppressed = 0;
                    }
                    break;
                }
            }
            if (staticHitValid)
            {
                float staticTtc = staticDist / Math.Max(vehicleSpeed, 1f);
                // Defer to closer non-map threats; only act if we beat the
                // current brake threat.
                if (staticTtc < closestBrakeTTC)
                {
                    closestBrakeTTC = staticTtc;
                    closestBrakeDistance = staticDist;
                    closestBrakeType = "wall";
                    closestBrakeThreatPos = staticHitPos;
                    closestBrakeThreatVel = GTA.Math.Vector3.Zero;
                }
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] shapecast: STATIC dist=" + staticDist.ToString("F1")
                        + " range=" + staticRange.ToString("F0")
                        + " radius=" + staticRadius.ToString("F1")
                        + " normalZ=" + staticHitNorm.Z.ToString("F2")
                        + " relZ=" + staticRelZ.ToString("F2")
                        + " lift=" + Math.Max(0f, (staticRadius + CAST_BOTTOM_CLEARANCE_M) - 0.5f).ToString("F2"));
            }
            else if (staticDist > 0f)
            {
                // iter-27 L4: enrich rejected static hits so a hit we reject and THEN
                // drive into is one grep away. hitPos lets the analyst match the
                // rejection to a prop in the snapshot's nearby-obstacles; reason names
                // the gate that dropped it. 014616 #1/#2 crushed into props that showed
                // up here as normalZ≈1.0 below-bumper ground-graze rejections.
                // iter-28 L: de-flooded. The per-hit line was 28% of the 024041 log
                // (3,847 lines, all reason=below-bumper). Tally a reason breakdown for
                // the ~10 s summary, and keep a per-hit line ONLY when the reject is
                // within braking range (the genuinely dangerous ground-graze, 014616 #2).
                // iter-36 B5: branch no longer logger-gated — the low-obstacle cache
                // below is a BEHAVIOR input (blockedAhead/strandedHold) and must
                // populate with logging off. All writes below stay logger-guarded.
                bool rejLogging = driveLogger != null && driveLogger.IsRunning;
                string rejReason = staticRelZ < 0.30f ? "below-bumper"
                    : staticRelZ > 2.0f ? "above-overhead" : "out-of-cone";
                // iter-36 B5: a close below-bumper hit while (nearly) stopped is the
                // sub-bumper wedge signature — cache it for blockedAhead/strandedHold
                // corroboration (stuck machinery only; the brake path never reads it).
                if (rejReason == "below-bumper" && staticDist < 4f && vehicleSpeed < 2f)
                {
                    cachedLowObstaclePos = staticHitPos;
                    cachedLowObstacleStamp = DateTime.Now.Ticks;
                    if (rejLogging
                        && DateTime.Now.Ticks - lastLowObstacleLogTicks > 100000000L) // 10 s
                    {
                        lastLowObstacleLogTicks = DateTime.Now.Ticks;
                        driveLogger.Write("[F" + driveLogFrameCount
                            + "] EVENT low-obstacle-cache: dist=" + staticDist.ToString("F1")
                            + " relZ=" + staticRelZ.ToString("F2")
                            + " normalZ=" + staticHitNorm.Z.ToString("F2")
                            + " hitPos=" + FmtV(staticHitPos));
                    }
                }
                if (!rejLogging)
                {
                    // counters/summary are logging telemetry only — don't let them
                    // accumulate across a logging-off stretch and skew the first
                    // summary after logging starts.
                    staticRejectCount = 0;
                    staticRejectBelowBumper = 0;
                    staticRejectOutOfCone = 0;
                    staticRejectAboveOverhead = 0;
                    lastStaticRejectSummaryTicks = DateTime.Now.Ticks;
                }
                else
                {
                staticRejectCount++;
                if (rejReason == "below-bumper") staticRejectBelowBumper++;
                else if (rejReason == "above-overhead") staticRejectAboveOverhead++;
                else staticRejectOutOfCone++;
                // iter-29 C3: per-hit line only for actionable near hits (out-of-cone /
                // overhead within braking range). below-bumper ground-graze (~99% of
                // rejects, the 1482-line flood) is counted in the summary only.
                if (staticDist < BRAKE_MIN_USEFUL_DIST && rejReason != "below-bumper")
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] shapecast: STATIC-REJECTED dist=" + staticDist.ToString("F1")
                        + " normalZ=" + staticHitNorm.Z.ToString("F2")
                        + " relZ=" + staticRelZ.ToString("F2")
                        + " reason=" + rejReason
                        + " hitPos=" + FmtV(staticHitPos)
                        + " lift=" + Math.Max(0f, (staticRadius + CAST_BOTTOM_CLEARANCE_M) - 0.5f).ToString("F2"));
                long srNow = DateTime.Now.Ticks;
                if (srNow - lastStaticRejectSummaryTicks > 100000000L) // ~10 s
                {
                    lastStaticRejectSummaryTicks = srNow;
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] EVENT static-reject-summary: count=" + staticRejectCount
                        + " belowBumper=" + staticRejectBelowBumper
                        + " outOfCone=" + staticRejectOutOfCone
                        + " aboveOverhead=" + staticRejectAboveOverhead);
                    staticRejectCount = 0;
                    staticRejectBelowBumper = 0;
                    staticRejectOutOfCone = 0;
                    staticRejectAboveOverhead = 0;
                }
                }
            }

            // ============================================
            // INTEGRATE NAV ASSIST DATA WITH ENTITY REFERENCES
            // Uses actual entity velocities for more accurate TTC calculation
            // Center: affects both steering and braking
            // Sides: affect ONLY steering, NOT braking
            // ============================================
            float navAssistMaxRange = detectionRange;

            // Center obstacle from nav assist (affects BOTH steering and braking)
            if (navAssistDistCenter < navAssistMaxRange && navAssistTypeCenter != "none")
            {
                float ttc;

                // Surface-normal classification of the center hit: if the wall
                // faces us nearly head-on a swerve cannot clear it, so escalate
                // to braking and suppress the steer nudge. An angled surface
                // keeps normal steering and only breaks ties below.
                bool wallFacesUs = false;
                int normalAvoidDir = 0;
                if (navAssistNormalCenter != GTA.Math.Vector3.Zero)
                {
                    GTA.Math.Vector3 wn = navAssistNormalCenter; wn.Z = 0f;
                    GTA.Math.Vector3 wfwd = playerVeh.ForwardVector; wfwd.Z = 0f;
                    if (wn.LengthSquared() > 0.0001f && wfwd.LengthSquared() > 0.0001f)
                    {
                        wn.Normalize();
                        wfwd.Normalize();
                        wallFacesUs = GTA.Math.Vector3.Dot(wn, -wfwd) > WALL_NORMAL_FACE_DOT;
                        float wlat = GTA.Math.Vector3.Dot(playerVeh.RightVector, navAssistNormalCenter);
                        normalAvoidDir = wlat > 0.1f ? 1 : (wlat < -0.1f ? -1 : 0);
                    }
                }
                // Strong rumble the instant a head-on wall is newly detected.
                if (wallFacesUs && !rumbleWallArmed) TriggerRumble(0.9f, 200);
                rumbleWallArmed = wallFacesUs;

                // Use actual entity velocity if available for more accurate TTC
                if (navAssistVehicleCenter != null && navAssistVehicleCenter.Exists())
                {
                    ttc = CalculateTTC(playerVeh, navAssistVehicleCenter.Position, navAssistVehicleCenter.Velocity);
                }
                else if (navAssistPedCenter != null && navAssistPedCenter.Exists())
                {
                    ttc = CalculateTTC(playerVeh, navAssistPedCenter.Position, navAssistPedCenter.Velocity);
                }
                else
                {
                    // World geometry - use simple distance/speed calculation
                    ttc = navAssistDistCenter / Math.Max(vehicleSpeed, 1f);
                }

                if (ttc < closestSteerTTC)
                {
                    closestSteerTTC = ttc;
                    closestType = navAssistTypeCenter == "ped" ? "pedestrian" :
                                  navAssistTypeCenter == "vehicle" ? "vehicle" : "obstacle";
                    closestDir = "ahead";
                    // Use nav assist side data to determine clearer direction
                    if (navAssistDistLeft > navAssistDistRight + 2f)
                        avoidDirection = -1; // Left is clearer
                    else if (navAssistDistRight > navAssistDistLeft + 2f)
                        avoidDirection = 1; // Right is clearer
                    else
                        avoidDirection = GetClearerSide(playerVeh, rayRange);
                    // Flat wall ahead: no swerve can clear it, brake instead.
                    // Angled surface with an ambiguous side pick: lean toward
                    // the side the surface normal points away from.
                    if (wallFacesUs)
                        avoidDirection = 0;
                    else if (avoidDirection == 0 && normalAvoidDir != 0)
                        avoidDirection = normalAvoidDir;
                    // Track threat position from nav assist entities
                    if (navAssistVehicleCenter != null && navAssistVehicleCenter.Exists())
                        closestSteerThreatPos = navAssistVehicleCenter.Position;
                    else if (navAssistPedCenter != null && navAssistPedCenter.Exists())
                        closestSteerThreatPos = navAssistPedCenter.Position;
                    else
                        closestSteerThreatPos = playerPos + playerVeh.ForwardVector * navAssistDistCenter;
                }
                // Apply gates to nav-assist center brake source. Lateral cone is
                // checked against the threat position (entity or projected forward).
                GTA.Math.Vector3 navCenterPos =
                    (navAssistVehicleCenter != null && navAssistVehicleCenter.Exists())
                    ? navAssistVehicleCenter.Position
                    : (navAssistPedCenter != null && navAssistPedCenter.Exists())
                        ? navAssistPedCenter.Position
                        : playerPos + playerVeh.ForwardVector * navAssistDistCenter;
                int navCenterHandle = (navAssistVehicleCenter != null && navAssistVehicleCenter.Exists())
                    ? navAssistVehicleCenter.Handle
                    : (navAssistPedCenter != null && navAssistPedCenter.Exists())
                        ? navAssistPedCenter.Handle
                        : 0;
                // A head-on wall is promoted to a brake threat even if the
                // lateral cone check is marginal — a swerve would just plow in.
                bool navCenterIsPed = navAssistPedCenter != null && navAssistPedCenter.Exists();
                bool navCenterBrakeOk = ttc < closestBrakeTTC
                                        && (IsInBrakeCone(playerVeh, navCenterPos) || wallFacesUs)
                                        && (navCenterHandle == 0
                                            || BrakeThreatPassesEntityGates(navCenterHandle, ttc, DateTime.Now.Ticks, navCenterIsPed, vehicleSpeed));
                if (navCenterBrakeOk)
                {
                    closestBrakeTTC = ttc;
                    closestBrakeDistance = navAssistDistCenter;
                    closestBrakeType = navAssistTypeCenter == "ped" ? "pedestrian" :
                                      navAssistTypeCenter == "vehicle" ? "vehicle" : "obstacle";
                    if (navAssistVehicleCenter != null && navAssistVehicleCenter.Exists())
                    {
                        closestBrakeThreatPos = navAssistVehicleCenter.Position;
                        closestBrakeThreatVel = navAssistVehicleCenter.Velocity;
                    }
                    else if (navAssistPedCenter != null && navAssistPedCenter.Exists())
                    {
                        closestBrakeThreatPos = navAssistPedCenter.Position;
                        closestBrakeThreatVel = navAssistPedCenter.Velocity;
                    }
                    else
                    {
                        closestBrakeThreatPos = playerPos + playerVeh.ForwardVector * navAssistDistCenter;
                        closestBrakeThreatVel = GTA.Math.Vector3.Zero;
                    }
                }
            }
            else
            {
                // No center obstacle this scan — clear the wall rumble latch so
                // the next wall encounter rumbles fresh.
                rumbleWallArmed = false;
            }

            // Left obstacle from nav assist - ONLY affects steering (steer right to avoid)
            // Does NOT contribute to braking - side obstacles shouldn't slow the car
            if (navAssistDistLeft < navAssistMaxRange * 0.5f && navAssistTypeLeft != "none")
            {
                float ttc;

                // Use actual entity velocity if available
                if (navAssistVehicleLeft != null && navAssistVehicleLeft.Exists())
                {
                    ttc = CalculateTTC(playerVeh, navAssistVehicleLeft.Position, navAssistVehicleLeft.Velocity);
                }
                else if (navAssistPedLeft != null && navAssistPedLeft.Exists())
                {
                    ttc = CalculateTTC(playerVeh, navAssistPedLeft.Position, navAssistPedLeft.Velocity);
                }
                else
                {
                    ttc = navAssistDistLeft / Math.Max(vehicleSpeed * 0.5f, 1f);
                }

                if (ttc < closestSteerTTC)
                {
                    closestSteerTTC = ttc;
                    closestType = navAssistTypeLeft == "ped" ? "pedestrian" :
                                  navAssistTypeLeft == "vehicle" ? "vehicle" : "obstacle";
                    closestDir = "left";
                    avoidDirection = 1; // Steer right to avoid left obstacle
                    if (navAssistVehicleLeft != null && navAssistVehicleLeft.Exists())
                    {
                        closestSteerThreatPos = navAssistVehicleLeft.Position;
                        closestSteerThreatVel = navAssistVehicleLeft.Velocity;
                    }
                    else if (navAssistPedLeft != null && navAssistPedLeft.Exists())
                    {
                        closestSteerThreatPos = navAssistPedLeft.Position;
                        closestSteerThreatVel = navAssistPedLeft.Velocity;
                    }
                    else
                    {
                        closestSteerThreatPos = playerPos - playerVeh.RightVector * navAssistDistLeft;
                        closestSteerThreatVel = GTA.Math.Vector3.Zero;
                    }
                }
                // Iter-9 Patch A: lateral entities can ALSO be brake threats
                // when they're inside our forward lane corridor. The center
                // cone misses lane-mate vehicles that are 1-2 m off-axis;
                // driveassist-2026-05-25-180748 markers F758/F1240/F2606/
                // F8673 are all this exact scenario (L or R sees a vehicle
                // at 10-20 m, C=none, player collides within 1 s).
                Entity leftEnt = (Entity)navAssistVehicleLeft ?? (Entity)navAssistPedLeft;
                if (leftEnt != null && leftEnt.Exists())
                {
                    GTA.Math.Vector3 toLE = leftEnt.Position - playerPos;
                    float lFwd = GTA.Math.Vector3.Dot(playerVeh.ForwardVector, toLE);
                    float lLat = Math.Abs(GTA.Math.Vector3.Dot(playerVeh.RightVector, toLE));
                    float lDist = toLE.Length();
                    if (lFwd > 0.3f && lLat < 2.5f && lDist < 12f && ttc < closestBrakeTTC)
                    {
                        bool lIsPed = navAssistPedLeft != null && navAssistPedLeft.Exists();
                        if (BrakeThreatPassesEntityGates(leftEnt.Handle, ttc, DateTime.Now.Ticks, lIsPed, vehicleSpeed))
                        {
                            closestBrakeTTC = ttc;
                            closestBrakeDistance = lDist;
                            closestBrakeType = lIsPed ? "pedestrian" : "vehicle";
                            closestBrakeThreatPos = leftEnt.Position;
                            closestBrakeThreatVel = navAssistVehicleLeft != null && navAssistVehicleLeft.Exists()
                                ? navAssistVehicleLeft.Velocity
                                : (navAssistPedLeft != null && navAssistPedLeft.Exists()
                                    ? navAssistPedLeft.Velocity
                                    : GTA.Math.Vector3.Zero);
                        }
                    }
                }
            }

            // Right obstacle from nav assist - ONLY affects steering (steer left to avoid)
            // Does NOT contribute to braking
            if (navAssistDistRight < navAssistMaxRange * 0.5f && navAssistTypeRight != "none")
            {
                float ttc;

                // Use actual entity velocity if available
                if (navAssistVehicleRight != null && navAssistVehicleRight.Exists())
                {
                    ttc = CalculateTTC(playerVeh, navAssistVehicleRight.Position, navAssistVehicleRight.Velocity);
                }
                else if (navAssistPedRight != null && navAssistPedRight.Exists())
                {
                    ttc = CalculateTTC(playerVeh, navAssistPedRight.Position, navAssistPedRight.Velocity);
                }
                else
                {
                    ttc = navAssistDistRight / Math.Max(vehicleSpeed * 0.5f, 1f);
                }

                if (ttc < closestSteerTTC)
                {
                    closestSteerTTC = ttc;
                    closestType = navAssistTypeRight == "ped" ? "pedestrian" :
                                  navAssistTypeRight == "vehicle" ? "vehicle" : "obstacle";
                    closestDir = "right";
                    avoidDirection = -1; // Steer left to avoid right obstacle
                    if (navAssistVehicleRight != null && navAssistVehicleRight.Exists())
                    {
                        closestSteerThreatPos = navAssistVehicleRight.Position;
                        closestSteerThreatVel = navAssistVehicleRight.Velocity;
                    }
                    else if (navAssistPedRight != null && navAssistPedRight.Exists())
                    {
                        closestSteerThreatPos = navAssistPedRight.Position;
                        closestSteerThreatVel = navAssistPedRight.Velocity;
                    }
                    else
                    {
                        closestSteerThreatPos = playerPos + playerVeh.RightVector * navAssistDistRight;
                        closestSteerThreatVel = GTA.Math.Vector3.Zero;
                    }
                }
                // Iter-9 Patch A: mirror of the Left block — promote
                // lateral-detected entities in the forward lane corridor to
                // brake threats.
                Entity rightEnt = (Entity)navAssistVehicleRight ?? (Entity)navAssistPedRight;
                if (rightEnt != null && rightEnt.Exists())
                {
                    GTA.Math.Vector3 toRE = rightEnt.Position - playerPos;
                    float rFwd = GTA.Math.Vector3.Dot(playerVeh.ForwardVector, toRE);
                    float rLat = Math.Abs(GTA.Math.Vector3.Dot(playerVeh.RightVector, toRE));
                    float rDist = toRE.Length();
                    if (rFwd > 0.3f && rLat < 2.5f && rDist < 12f && ttc < closestBrakeTTC)
                    {
                        bool rIsPed = navAssistPedRight != null && navAssistPedRight.Exists();
                        if (BrakeThreatPassesEntityGates(rightEnt.Handle, ttc, DateTime.Now.Ticks, rIsPed, vehicleSpeed))
                        {
                            closestBrakeTTC = ttc;
                            closestBrakeDistance = rDist;
                            closestBrakeType = rIsPed ? "pedestrian" : "vehicle";
                            closestBrakeThreatPos = rightEnt.Position;
                            closestBrakeThreatVel = navAssistVehicleRight != null && navAssistVehicleRight.Exists()
                                ? navAssistVehicleRight.Velocity
                                : (navAssistPedRight != null && navAssistPedRight.Exists()
                                    ? navAssistPedRight.Velocity
                                    : GTA.Math.Vector3.Zero);
                        }
                    }
                }
            }

            // ---- iter-22 J3: WATER-AHEAD GUARD ----
            // The casts only see map geometry; the Alamo Sea read as open space
            // and the car drove straight in at 26 m/s (184335 session end). Probe
            // 2 points along the VELOCITY direction at ~1 s and ~2 s of travel
            // with GET_WATER_HEIGHT; water near/above car level = stop. Brake-only
            // response (no surprise swerve for a blind driver) lives in
            // ApplyCachedSteeringInputs next to the skew-emergency.
            waterAheadDetected = false;
            waterAheadDist = -1f;
            if (vehicleSpeed > 8f)
            {
                GTA.Math.Vector3 waterVelDir = playerVeh.Velocity;
                waterVelDir.Z = 0f;
                if (waterVelDir.LengthSquared() > 1f)
                {
                    waterVelDir.Normalize();
                    // iter-23 K3: BOTH probes must agree, or a single hit must be
                    // at a point that is NOT a road. The 192838 session's two
                    // false alarms were shoreline roads ~1 m above lake level
                    // where one probe clipped the water on a curve. Height test
                    // tightened to carZ-1.
                    int waterHitCount = 0;
                    bool anyOffRoadHit = false;
                    float firstHitDist = -1f, firstHitWz = 0f;
                    for (int wp = 1; wp <= 2; wp++)
                    {
                        float probeDist = Math.Min(50f, Math.Max(8f, vehicleSpeed * wp));
                        GTA.Math.Vector3 waterProbe = playerPos + waterVelDir * probeDist;
                        OutputArgument oWaterZ = new OutputArgument();
                        // GET_WATER_HEIGHT: 0xF6829842C06AE524
                        bool hasWater = Function.Call<bool>((Hash)0xF6829842C06AE524,
                            waterProbe.X, waterProbe.Y, waterProbe.Z, oWaterZ);
                        if (!hasWater) continue;
                        float waterZ = oWaterZ.GetResult<float>();
                        // Bridges stay quiet: their deck is far ABOVE the water
                        // surface, so waterZ << car Z.
                        if (waterZ <= playerPos.Z - 1f) continue;
                        waterHitCount++;
                        if (firstHitDist < 0f) { firstHitDist = probeDist; firstHitWz = waterZ; }
                        if (!IsPositionOnRoad(waterProbe)) anyOffRoadHit = true;
                    }
                    if (waterHitCount == 2 || (waterHitCount == 1 && anyOffRoadHit))
                    {
                        waterAheadDetected = true;
                        waterAheadDist = firstHitDist;
                        if (DateTime.Now.Ticks - lastWaterSpeechTicks > 50000000)
                        {
                            lastWaterSpeechTicks = DateTime.Now.Ticks;
                            Speech.Critical("Water ahead!");
                        }
                        if (driveLogger != null && driveLogger.IsRunning
                            && DateTime.Now.Ticks - lastWaterLogTicks > 20000000)
                        {
                            lastWaterLogTicks = DateTime.Now.Ticks;
                            driveLogger.Write("[F" + driveLogFrameCount
                                + "] EVENT water-ahead: dist=" + firstHitDist.ToString("F0")
                                + " wz=" + firstHitWz.ToString("F1")
                                + " carZ=" + playerPos.Z.ToString("F1")
                                + " hits=" + waterHitCount
                                + " offRoad=" + anyOffRoadHit);
                        }
                    }
                }
            }

            // Store for reference - use steer TTC for general threat tracking
            threatTimeToCollision = closestSteerTTC;
            threatDirection = closestDir;
            threatType = closestType;
            closestThreatPosition = closestSteerThreatPos;
            closestBrakeObstacleType = closestBrakeType;

            // ---- iter-18 C1/A6 step 1: brake-threat physics telemetry ----
            // aReq = closing^2 / 2*gap is the required-deceleration AEB criterion
            // the plan proposes as the future brake arbiter; tCpa/cpaMiss is the
            // predicted closest-point-of-approach time and miss distance. Logged on
            // the apply-assist EVENT line for at least one session so the offline
            // pass can compare them against the TTC-ladder decisions BEFORE any
            // gate switches over. No control path reads these fields.
            lastBrakeAReq = 0f;
            lastBrakeTcpa = -1f;
            lastBrakeCpaMiss = -1f;
            lastBrakeGapBumper = -1f; // iter-20 H5
            if (closestBrakeThreatPos != GTA.Math.Vector3.Zero)
            {
                GTA.Math.Vector3 brRelPos = closestBrakeThreatPos - playerPos;
                GTA.Math.Vector3 brRelVel = closestBrakeThreatVel - playerVeh.Velocity;
                float brGap = brRelPos.Length();
                // iter-20 H5: bumper-true gap (center gap minus own half-length),
                // log-only — stages the future aReq arbiter on honest distances.
                // iter-43 A3: the 4.0 m clamp understated a 9.9 m truck's overhang
                // by ~1 m, so the "bumper-true" gap was not bumper-true on exactly
                // the vehicles that need it most.
                lastBrakeGapBumper = Math.Max(0f,
                    brGap - GetVehicleHalfLengthForClearance(playerVeh));
                if (brGap > 0.01f)
                {
                    float brClosing = -GTA.Math.Vector3.Dot(brRelPos * (1f / brGap), brRelVel);
                    if (brClosing > 0.1f)
                        lastBrakeAReq = (brClosing * brClosing)
                            / (2f * Math.Max(brGap - 1.0f, 0.5f));
                    float brRelVelSq = brRelVel.LengthSquared();
                    if (brRelVelSq > 0.01f)
                    {
                        float brTcpa = -GTA.Math.Vector3.Dot(brRelPos, brRelVel) / brRelVelSq;
                        if (brTcpa > 0f && brTcpa < 10f)
                        {
                            lastBrakeTcpa = brTcpa;
                            lastBrakeCpaMiss = (brRelPos + brRelVel * brTcpa).Length();
                        }
                    }
                }
            }

            // Hand off live position/velocity to ApplyCachedSteeringInputs so it can
            // recompute brake/steer urgency every frame between full scans. The stamp
            // is checked for staleness so we don't act on data older than 250 ms.
            long nowStamp = DateTime.Now.Ticks;
            // iter-16 FIX 3: refuse to re-cache a brake point we just released at this
            // locus while still stopped — otherwise the next scan re-grabs it and the
            // ~3 s re-infestation cycle re-traps the player. Treated as "no threat".
            if (closestBrakeThreatPos != GTA.Math.Vector3.Zero
                && !IsBrakeRejected(closestBrakeThreatPos, vehicleSpeed))
            {
                // Initialize FirstSeen the moment the cache transitions from
                // empty -> populated. Subsequent re-confirmations refresh Stamp
                // but leave FirstSeen alone, so the 3-second wedge-detect below
                // measures actual elapsed time, not refresh recency.
                if (cachedBrakeThreatStamp == 0)
                {
                    cachedBrakeThreatFirstSeenStamp = nowStamp;
                    cachedBrakeThreatFirstSeenPlayerPos = playerVeh.Position;
                }
                cachedBrakeThreatPos = closestBrakeThreatPos;
                cachedBrakeThreatVel = closestBrakeThreatVel;
                cachedBrakeThreatStamp = nowStamp;
            }
            else
            {
                cachedBrakeThreatPos = GTA.Math.Vector3.Zero;
                cachedBrakeThreatStamp = 0;
                cachedBrakeThreatFirstSeenStamp = 0;
                // Iter-11 Patch I: reset distance history when cache empties
                // so a future re-acquisition starts a fresh measurement.
                cachedBrakeDistHistoryValid = false;
                cachedBrakeDistIdx = 0;
            }
            if (closestSteerThreatPos != GTA.Math.Vector3.Zero)
            {
                cachedSteerThreatPos = closestSteerThreatPos;
                cachedSteerThreatVel = closestSteerThreatVel;
                cachedSteerThreatStamp = nowStamp;
            }
            else
            {
                cachedSteerThreatPos = GTA.Math.Vector3.Zero;
            }

            // EARLY-CLEAR (2026-05-25 fix for Loop 2 + Loop 3). The C3 rescan
            // below only fires when the vehicle is stopped AND the cache is
            // stale AND emergencyBrakeActive is set. That gate misses two
            // common cases the failure-log analysis surfaced:
            //   (a) Drove past: the vehicle has moved beyond the cached
            //       threat position (forward-dot is now <= 0) or the threat
            //       has drifted laterally out of the brake cone as the road
            //       curves. The cache is referring to something physically
            //       behind/beside the car — clear it so the next scan can
            //       pick a fresh forward threat instead.
            //   (b) Long-wedged: the threat was first seen >3 s ago and the
            //       vehicle has moved <1 m since. Every refresh is the same
            //       roadside feature; the C3 staleness check never fires
            //       because Stamp keeps being refreshed. FirstSeenStamp
            //       captures the original detection time, decoupling from
            //       the refresh-driven Stamp.
            // Both clears also drop emergencyBrakeActive and
            // wasObstacleInBrakeZone so Loop 3 (Mechanism A keeping
            // emergency brake latched via critical-zone test) releases too.
            if (cachedBrakeThreatStamp > 0 && cachedBrakeThreatPos != GTA.Math.Vector3.Zero)
            {
                GTA.Math.Vector3 toCached = cachedBrakeThreatPos - playerVeh.Position;
                bool clearReasonPast = false;
                bool clearReasonWedged = false;

                // Iter-11 Patch I: update the 3-frame distance ring for the
                // drove-past confirmation. Sample the current distance every
                // tick the cache is non-zero; when a new threat replaces a
                // moved one (>3 m position delta from prior sample), reset
                // the ring so the rising-distance test isn't fooled by the
                // change of identity.
                float curDist = toCached.Length();
                if (cachedBrakeDistHistoryValid)
                {
                    float prevDist = cachedBrakeDistHistory[cachedBrakeDistIdx];
                    if (Math.Abs(curDist - prevDist) > 3f)
                    {
                        // Probable cache identity change — reset history.
                        cachedBrakeDistHistoryValid = false;
                        cachedBrakeDistIdx = 0;
                    }
                }
                cachedBrakeDistHistory[cachedBrakeDistIdx] = curDist;
                cachedBrakeDistIdx = (cachedBrakeDistIdx + 1) % 3;
                if (!cachedBrakeDistHistoryValid && cachedBrakeDistIdx == 0)
                    cachedBrakeDistHistoryValid = true;

                if (toCached.LengthSquared() > 0.0001f)
                {
                    GTA.Math.Vector3 toCachedN = GTA.Math.Vector3.Normalize(toCached);
                    GTA.Math.Vector3 vfwd = isReversing ? -playerVeh.ForwardVector : playerVeh.ForwardVector;
                    float fwdDot = GTA.Math.Vector3.Dot(vfwd, toCachedN);
                    // Iter-11 Patch I: drove-past also requires the distance
                    // to have risen by >0.5 m across the 3-frame ring. A
                    // momentary heading swing during evasion (fwdDot dipping
                    // below 0.15 for one frame) no longer wipes the cache;
                    // the threat must actually be receding for at least
                    // 50 ms (3 frames at ~60 fps) of measured motion.
                    bool distRising = false;
                    if (cachedBrakeDistHistoryValid)
                    {
                        float oldest = cachedBrakeDistHistory[cachedBrakeDistIdx];
                        if (curDist - oldest > 0.5f) distRising = true;
                    }
                    if (fwdDot <= 0.15f && distRising) clearReasonPast = true;
                }
                if (!clearReasonPast && cachedBrakeThreatFirstSeenStamp > 0)
                {
                    long firstSeenAgeMs = (DateTime.Now.Ticks - cachedBrakeThreatFirstSeenStamp) / 10000;
                    float playerMoved = (playerVeh.Position - cachedBrakeThreatFirstSeenPlayerPos).Length();
                    if (firstSeenAgeMs > 3000 && playerMoved < 1f)
                        clearReasonWedged = true;
                    // Creeping-under-brake gate: the original 3s+<1m window
                    // misses the dominant failure pattern in
                    // driveassist-2026-05-25-103730 — car creeps at 2-3 m/s
                    // under a latched emergency brake (so playerMoved exceeds
                    // 1 m well before 3 s, and the original gate never fires)
                    // while the cached threat XYZ stays pinned ahead of us.
                    // Once the threat has persisted >1.2 s while we're still
                    // slow AND emergencyBrakeActive is latched AND the same
                    // XYZ is still right in front (<6 m), it's almost
                    // certainly a phantom or unreachable feature — clear it
                    // and let the next scan re-evaluate.
                    else if (firstSeenAgeMs > 1200
                        && emergencyBrakeActive
                        && vehicleSpeed < 2.0f
                        && toCached.Length() < 6f)
                        clearReasonWedged = true;
                }
                if (clearReasonPast || clearReasonWedged)
                {
                    // iter-16 FIX 3: a long-wedged clear means this point keeps
                    // re-trapping us — remember it so the next scan can't re-cache it
                    // while we are stopped. drove-past is legit progress, so no locus.
                    if (clearReasonWedged)
                    {
                        brakeRejectLocus = cachedBrakeThreatPos;
                        brakeRejectUntilTicks = DateTime.Now.Ticks + BRAKE_REJECT_WINDOW_TICKS;
                    }
                    cachedBrakeThreatPos = GTA.Math.Vector3.Zero;
                    cachedBrakeThreatStamp = 0;
                    cachedBrakeThreatFirstSeenStamp = 0;
                    emergencyBrakeActive = false;
                    wasObstacleInBrakeZone = false;
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount
                            + "] EVENT brake-cache-early-clear: "
                            + (clearReasonPast ? "drove-past" : "long-wedged"));
                    RecordDriveDecision("brake-cache-early-clear: "
                        + (clearReasonPast ? "drove-past" : "long-wedged"));
                }
            }

            // STALE BRAKE-THREAT RE-SCAN (C3 fix). When the cached brake threat
            // is >1 s old AND the vehicle has been stopped for >1 s AND
            // emergencyBrakeActive is stuck on, we are almost certainly acting
            // on stale obstacle data — the audit found 20% of failures in this
            // gridlock state. Force-clear the cache so this frame can re-pick
            // (or so the next scan can find a fresh threat or none at all).
            // 500 ms cooldown prevents re-trigger thrash.
            long rescanNow = DateTime.Now.Ticks;
            long brakeAgeMs = cachedBrakeThreatStamp > 0
                ? (rescanNow - cachedBrakeThreatStamp) / 10000 : 0;
            // Staleness threshold scales DOWN with speed: a 1 s old threat
            // position is already 30 m off at 67 mph. Floored at 200 ms so
            // city-speed noise doesn't constantly rescan. (Combined with the
            // gridlock check below this only fires when stopped, so the scaling
            // is mostly defensive for code paths that may grow into this check.)
            int staleThresholdMs = Math.Max(200,
                Math.Min(STALE_THREAT_AGE_MS, STALE_THREAT_AGE_MS - (int)(vehicleSpeed * 20f)));
            bool brakeStale     = brakeAgeMs > staleThresholdMs;
            bool brakeGridlock  = VehicleStoppedForLastMs(GRIDLOCK_SPEED_MS, GRIDLOCK_STOPPED_MS)
                                  && HistorySpansAtLeastMs(GRIDLOCK_STOPPED_MS);
            bool rescanCooldown = (rescanNow - lastForcedRescanTicks)
                                  > FORCED_RESCAN_COOLDOWN_TICKS;
            if (brakeStale && brakeGridlock && rescanCooldown && emergencyBrakeActive)
            {
                cachedBrakeThreatPos   = GTA.Math.Vector3.Zero;
                cachedBrakeThreatStamp = 0;
                cachedBrakeThreatFirstSeenStamp = 0;
                emergencyBrakeActive   = false;
                wasObstacleInBrakeZone = false;
                lastForcedRescanTicks  = rescanNow;
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] EVENT stale-threat-rescan: ageMs=" + brakeAgeMs
                        + " stoppedMs>=" + GRIDLOCK_STOPPED_MS);
                RecordDriveDecision("stale-threat-rescan: forced clear ageMs=" + brakeAgeMs);
            }

            // ============================================
            // DRIVE MODE STATE MACHINE — alignment is a STRICT FALLBACK.
            // Lane-keep runs first. Only when GetLaneCenterGuidance reports
            // isOnValidRoad=false do we look for a recovery node. This protects
            // the common case (correctly aligned on a road) from spurious
            // alignment-mode triggers that capped throttle.
            // ============================================
            bool sameVehicle = (playerVeh.Handle == lastDriveAssistVehicleHandle);
            // Teleport detection: same vehicle handle but position has jumped.
            // BIG_Z_CHANGE in the log is the same signal we want to react to.
            // Skip the check on the first frame (lastDriveAssistVehiclePosValid)
            // and when the vehicle just changed (handled below).
            bool teleported = false;
            if (sameVehicle && lastDriveAssistVehiclePosValid)
            {
                GTA.Math.Vector3 dp = playerVeh.Position - lastDriveAssistVehiclePos;
                float planar = (float)Math.Sqrt(dp.X * dp.X + dp.Y * dp.Y);
                if (planar > TELEPORT_JUMP_M)
                {
                    teleported = true;
                    // iter-29 C4: log the teleport delta so post-teleport health drops
                    // (032924 #6's -159.5 was a stuck-vehicle warp into a ped) are
                    // attributable, not mistaken for an assist driving error.
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT teleport-jump:"
                            + " from=" + FmtV(lastDriveAssistVehiclePos)
                            + " to=" + FmtV(playerVeh.Position)
                            + " jumpDist=" + planar.ToString("F1")
                            + " speed=" + playerVeh.Speed.ToString("F1"));
                        SnapshotFailure("TELEPORT-JUMP", null);
                }
            }
            lastDriveAssistVehiclePos = playerVeh.Position;
            lastDriveAssistVehiclePosValid = true;

            if (!sameVehicle || teleported)
            {
                lastDriveAssistVehicleHandle = playerVeh.Handle;
                vehicleEntryTicks = DateTime.Now.Ticks;
                // Reset alignment state so prior vehicle / location can't bleed in.
                currentDriveMode = DriveMode.LaneKeeping;
                alignmentEngageReverse = false;
                // Drop rolling history — prior snapshots are stale.
                historyHead = 0;
                historyCount = 0;
                lastModeChangeTicks = DateTime.Now.Ticks;
                // Reset lane-snap memory; prior location was likely a
                // different lane / road class.
                lastLaneIndex = int.MinValue;
                // iter-21 I2: damping history is location-specific.
                prevStanleyLatErrorTicks = 0;
                // Reset persistent-skew tracker.
                persistentSkewStartTicks = 0;
                hardLateralFailStreak = 0; // iter-22 J1
                // TELEPORT-ONLY EXTRA RESETS. The vehicle-change path above
                // already covered the per-vehicle state. Teleports need to
                // additionally clear the cached threat data and path polyline
                // because the OLD location's obstacles / road tangent would
                // otherwise drive 1-2 frames of wrong steering / braking at
                // the NEW location.
                if (teleported)
                {
                    ResetForTeleport("planar-jump");
                }
            }

            // Lane-keep first. Sets isOnValidRoad as a side effect.
            float leadVehicleSteer = 0f;
            roadSteerCorrection = GetLaneCenterGuidance(playerVeh);
            bool laneKeepOk = isOnValidRoad;

            // ---- PRE-EMPTIVE CURVE BRAKING ----
            // Runs after GetLaneCenterGuidance so lastClosestPolySeg is fresh.
            // Full mode brakes before a sharp bend; Assisted mode only cues.
            float curveBrake = ComputeCurveBrake(playerVeh);
            // iter-29 A: LANE-DEPARTURE-AT-SPEED BRAKE. On a curve the capped Stanley
            // (STANLEY_CTE_CAP_M=4 / CROSS_MAX=0.35) cannot drag a growing lateral error
            // back, and the off-road eject doesn't fire until the car is already off the
            // edge (032924 #1: accelerated 15.8->17.2 m/s, lat -7.25 -> off-road, onRoad
            // the whole time). Brake when the error is large AND GROWING at speed so the
            // car slows to where the controller can hold the lane. Brake-only (steer caps
            // untouched, so no weave regression); gated on error GROWING so it ignores the
            // normal ~2.6 m steady right-lane offset.
            float laneDepartBrake = 0f;
            {
                float ldAbsLat = Math.Abs(lastLaneLateralError);
                long ldNow = DateTime.Now.Ticks;
                float ldDt = laneDepartPrevTicks > 0 ? (ldNow - laneDepartPrevTicks) / 10000000f : 0f;
                float ldRate = (ldDt > 0.02f && ldDt < 0.5f) ? (ldAbsLat - laneDepartPrevAbsLat) / ldDt : 0f;
                laneDepartPrevAbsLat = ldAbsLat;
                laneDepartPrevTicks = ldNow;
                // iter-30 P4: also fire on a SUSTAINED large error, not only a growing one.
                // The ldRate>0.5 gate missed steady drift — a car riding ~5 m off the lane at
                // speed sat there without the departure brake ever engaging (iter-29 lead-up).
                bool sustainedDepart = ldAbsLat > LANE_DEPART_LAT_M + 1.0f;
                bool departing = isFullMode && isOnValidRoad
                    && vehicleSpeed > LANE_DEPART_MIN_SPEED
                    && ldAbsLat > LANE_DEPART_LAT_M && (ldRate > LANE_DEPART_RATE || sustainedDepart);
                if (departing) laneDepartStreak++; else laneDepartStreak = 0;
                // iter-39 Stage 1D: the lane-departure brake rides on the polyline's
                // lateral error, and the polyline is a HINT that is routinely ~7 m
                // out (07-23: 13 offroad-risk events at |lat| 6.8-8.8 on a road whose
                // half-width is 5.3, across many different nodes). The distrust flag
                // already exists for exactly this and every OTHER consumer honours
                // it — but the departure brake did not, so it held brake=0.99 for
                // 3+ seconds on a straight, centred car. Once actuationV2 makes that
                // brake real, a distrusted lane model must not be allowed to stamp
                // on the pedal at speed.
                bool ldDistrusted = actuationV2Enabled
                    && DateTime.Now.Ticks < polylineDistrustUntilTicks;
                if (laneDepartStreak >= LANE_DEPART_FRAMES && !ldDistrusted)
                {
                    laneDepartBrake = Math.Min(CURVE_BRAKE_HARD_MAX,
                        0.4f + 0.15f * (ldAbsLat - LANE_DEPART_LAT_M));
                    // iter-31: a FAST departure at speed needs more brake sooner. In 034850
                    // #5 the car was already 5.8 m off and climbing 3.8 m/s at 19 m/s, yet
                    // only got a 0.75 floor — it reached 12.8 m off before the brake maxed.
                    // Add a lateral-rate term so a rapid departure brakes harder up front
                    // (conservative: only when the error is genuinely running away).
                    if (ldRate > 2f)
                        laneDepartBrake = Math.Min(CURVE_BRAKE_HARD_MAX,
                            laneDepartBrake + 0.2f * (ldRate - 2f));
                    // iter-39 Stage 1D: hard cap. Lane departure is a NUDGE — "you
                    // are drifting off the line" — not a stop. It was 34.8% of all
                    // heavy (>= 0.5) brake demand on 07-23, second only to the
                    // ramped term, and it was reaching CURVE_BRAKE_HARD_MAX. With
                    // the brake channel dead that cost nothing; with actuationV2 it
                    // would be the dominant braking event of an average drive.
                    // iter-40 brakeDeadzoneV2: re-derive the cap in DELIVERED units.
                    // Two things changed. (a) A commanded 0.35 used to deliver 0.13;
                    // it now delivers 0.35, so the same number is ~2.7x the real
                    // brake it was. (b) A flat cap is wrong for a runaway departure:
                    // on 07-28 incident 02 the error was growing at 7.0 m/s at
                    // 26.5 m/s and the only brake opposing it was pinned at 0.35
                    // (0.13 delivered) — the car went 4.1 m to 14.7 m off the line
                    // and hit a prop. A slow drift is still a nudge; a departure
                    // this fast is a genuine stop. Scale the ceiling with the rate.
                    // poly-distrust already hard-disables this brake upstream, so
                    // the scaled value can only apply to a trusted lane reference.
                    if (actuationV2Enabled)
                    {
                        float ldCap = LANE_DEPART_BRAKE_CAP;
                        if (getSetting("brakeDeadzoneV2") == 1 && ldRate > 3f)
                            ldCap = Math.Min(LANE_DEPART_BRAKE_CAP_MAX,
                                LANE_DEPART_BRAKE_CAP + 0.10f * (ldRate - 3f));
                        laneDepartBrake = Math.Min(ldCap, laneDepartBrake);
                    }
                    if (driveLogger != null && driveLogger.IsRunning
                        && ldNow - lastLaneDepartLogTicks > 5000000)
                    {
                        lastLaneDepartLogTicks = ldNow;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lane-depart-brake:"
                            + " lat=" + lastLaneLateralError.ToString("F1")
                            + " latRate=" + ldRate.ToString("F1")
                            + " speed=" + vehicleSpeed.ToString("F1")
                            + " brake=" + laneDepartBrake.ToString("F2"));
                    }
                }
            }
            if (isFullMode)
            {
                // iter-19 G2: no comfort braking during the watchdog grace window.
                // iter-29 A: the lane-departure brake rides alongside the curve brake.
                curveBrakeRequest = InWatchdogGrace() ? 0f : Math.Max(curveBrake, laneDepartBrake);
                // iter-33: keep the lane-depart term visible for owner= attribution.
                lastLaneDepartBrakeReq = InWatchdogGrace() ? 0f : laneDepartBrake;
            }
            else
            {
                curveBrakeRequest = 0f;
                lastLaneDepartBrakeReq = 0f;
                if (curveBrake > 0.05f
                    && DateTime.Now.Ticks - lastCurveCueTicks > 30000000)
                {
                    TriggerRumble(0.4f, 150);
                    Speech.Ambient("Curve ahead");
                    lastCurveCueTicks = DateTime.Now.Ticks;
                }
            }

            // ---- ADAPTIVE CRUISE CONTROL ----
            // Updates accThrottleOut / accBrakeOut for ApplyCachedSteeringInputs.
            ComputeACC(playerVeh, isFullMode);

            // EARLY SKEW DETECTION: ComputeStanleySteer reports isOnValidRoad
            // whenever a polyline exists, even while the car is badly rotated
            // off the road tangent. Stanley keeps demanding full correction but
            // the car keeps skewing. Treat a sustained large heading error as a
            // lane-keep failure so recovery engages BEFORE the polyline
            // collapses at ~75 deg skew and the car is hopelessly sideways.
            // iter-17 Fix 1b + Fix 2: run the gate on the windowed look-ahead skew (not the
            // closest-segment roadHeadingDelta) AND require real lateral departure, so a
            // junction dogleg phantom (high close-skew, benign look-ahead, centered car) no
            // longer trips recovery. The 55-deg severe path below stays lateral-free so a
            // genuine in-place spin-out still ejects instantly.
            // ---- iter-41 Stage 6c skewGateV2: SKEW-SCALED LATERAL GATE ----
            // 07-28 F14860: closeSkew=54.0 aheadSkew=37.5 lat=2.43 at 21.6 m/s. The
            // angular half of the test passed (37.5 > 30) and the lateral half missed
            // by 0.07 m, so nothing armed; 18 frames later the car lost 2.2 m/s in a
            // single frame and took damage, with NO event of any kind emitted.
            // The flatter the car's angle to the lane, the more lateral error we
            // should tolerate — the steeper it is, the less. Floored at 1.5 m so this
            // can never become the iter-23 eject storm (224 ejects in one session).
            float effLatGate = LANEFAIL_LATERAL_GATE_M;
            if (getSetting("skewGateV2") == 1)
            {
                GateReach("skewGateV2");
                float over = (Math.Abs(lastLookaheadHeadingDelta) - LANEKEEP_SKEW_FAIL_ANGLE) / 30f;
                if (over < 0f) over = 0f;
                if (over > 1f) over = 1f;
                effLatGate = Math.Max(LANEFAIL_LATERAL_GATE_MIN_M,
                                      LANEFAIL_LATERAL_GATE_M * (1f - 0.5f * over));
            }
            bool laterallyOff = Math.Abs(lastLaneLateralError) > effLatGate;
            if (getSetting("skewGateV2") == 1 && laterallyOff
                && Math.Abs(lastLaneLateralError) <= LANEFAIL_LATERAL_GATE_M)
                GateFire("skewGateV2");   // only the cases the old gate would have missed
            bool lookaheadSkewFail = Math.Abs(lastLookaheadHeadingDelta) > LANEKEEP_SKEW_FAIL_ANGLE;
            if (laneKeepOk && lookaheadSkewFail && laterallyOff)
                skewFailureStreak++;
            else
                skewFailureStreak = 0;
            if (skewFailureStreak >= LANEKEEP_SKEW_FAIL_FRAMES)
                laneKeepOk = false;
            // iter-22 J1: HARD LATERAL EJECT — no skew requirement. Off-road-
            // parallel departures (skew~0) must still reach recovery; the capped
            // controller (iter-21 I1) cannot drag a 15 m departure back alone.
            // Hysteresis: streak only resets once back within 4 m.
            if (Math.Abs(lastLaneLateralError) > LANEFAIL_LATERAL_HARD_M)
                hardLateralFailStreak++;
            else if (Math.Abs(lastLaneLateralError) < 4f)
                hardLateralFailStreak = 0;
            if (hardLateralFailStreak >= LANEFAIL_LATERAL_HARD_FRAMES)
            {
                // iter-23 K1 + iter-25 M4: GROUND-TRUTH GATE, hardened for rural roads.
                // A >6 m polyline error with the car physically ON a road means the
                // POLYLINE is wrong (snap to a parallel road/trail), not the car —
                // 192838 turned that into 224 ejects and made off-roading WORSE. iter-23
                // gated the eject on the native IS_POINT_ON_ROAD alone, but that native
                // reads FALSE on Sandy Shores dirt roads while the car is driving fine
                // (06-18: 83 ejects, 0 poly-distrust, EVERY one with the mod's own
                // onValidRoad=True) — and that eject storm is what kicks off the wedge
                // thrash. So eject only when MULTIPLE signals agree the car is genuinely
                // off-road: the native says off-road AND (the mod hasn't tracked it on a
                // plausible lane recently, OR it has been far from any node a sustained
                // time, OR the lateral error is gross). Otherwise distrust the polyline
                // briefly (K2 StabilizePolyline then holds the last good one). Genuine
                // departures (Alamo-Sea class) still eject via gross-lateral / sustained.
                long k1Now = ModClock.Ticks; // ModClock pair with offRoadStartTicks (stamped in CheckRoadTeleport)
                bool nativeOffRoad = !IsPositionOnRoad(playerVeh.Position);
                bool recentlyPlausiblyOnRoad = WasOnValidRoadForLastMs(POLY_GROUNDTRUTH_MS);
                bool sustainedOffRoad = offRoadStartTicks > 0
                    && (k1Now - offRoadStartTicks) > OFFROAD_CONFIRM_TICKS;
                // iter-40 roadModelV2: the gross-departure escape hatch fired too late.
                // On 07-28 incident 02 the car ran from 4.1 m to 14.7 m off the line at
                // 26.5 m/s and poly-distrust kept laneKeepOk=true the whole way, because
                // 14.7 never reached the 16 m hard threshold — the mod was still
                // treating its own lane model as merely "suspect" while the car was
                // most of a carriageway off the road. Past ~12 m the polyline is not
                // worth defending: whichever of the two is wrong, the car needs
                // recovery, not lane-keeping.
                float grossDepartM = getSetting("roadModelV2") == 1
                    ? LANEFAIL_LATERAL_EJECT_SOFT_M : LANEFAIL_LATERAL_EJECT_HARD_M;
                bool grossDeparture = Math.Abs(lastLaneLateralError) > grossDepartM;
                bool genuinelyOffRoad = nativeOffRoad
                    && (!recentlyPlausiblyOnRoad || sustainedOffRoad || grossDeparture);
                if (genuinelyOffRoad)
                {
                    laneKeepOk = false;
                    if (driveLogger != null && driveLogger.IsRunning
                        && DateTime.Now.Ticks - lastLateralEjectLogTicks > 10000000)
                    {
                        lastLateralEjectLogTicks = DateTime.Now.Ticks;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lateral-eject:"
                            + " lat=" + lastLaneLateralError.ToString("F1")
                            + " speed=" + vehicleSpeed.ToString("F1")
                            + " why=" + (grossDeparture ? "gross" : sustainedOffRoad ? "sustained" : "offroad")
                            + " recentOnRd=" + recentlyPlausiblyOnRoad);
                    }
                }
                else
                {
                    polylineDistrustUntilTicks = DateTime.Now.Ticks + POLY_DISTRUST_TICKS;
                    if (driveLogger != null && driveLogger.IsRunning
                        && DateTime.Now.Ticks - lastPolyDistrustLogTicks > 10000000)
                    {
                        lastPolyDistrustLogTicks = DateTime.Now.Ticks;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT poly-distrust:"
                            + " lat=" + lastLaneLateralError.ToString("F1")
                            + " headingDelta=" + roadHeadingDelta.ToString("F1")
                            + " speed=" + vehicleSpeed.ToString("F1")
                            + " nativeOff=" + nativeOffRoad);
                    }
                }
            }
            // iter-28 P1: genuinely-stuck / grinding OFF-ROAD escalation, INDEPENDENT
            // of the |lat|-gated K1 block above. 024041 #8 ground off-road at small
            // |lat| (so that block never ran) and #6/#7 sat stopped off-road ~90 s
            // while poly-distrust kept laneKeepOk=true. poly-distrust must keep
            // vetoing a MOVING dirt-road car (native wrongly off-road), but never one
            // that is stopped OR taking damage off-road — force the eject so recovery
            // (and its M3 give-up) engages instead of grinding indefinitely.
            {
                long offNow = DateTime.Now.Ticks;
                bool nativeOff2 = !IsPositionOnRoad(playerVeh.Position);
                if (nativeOff2 && vehicleSpeed < STUCK_OFFROAD_SPEED)
                {
                    if (lowSpeedOffRoadStartTicks == 0) lowSpeedOffRoadStartTicks = offNow;
                }
                else lowSpeedOffRoadStartTicks = 0;
                bool stuckOffRoad = lowSpeedOffRoadStartTicks > 0
                    && (offNow - lowSpeedOffRoadStartTicks) > STUCK_OFFROAD_TICKS;
                bool grindingOffRoad = nativeOff2 && lastBodyDropTicks > 0
                    && (offNow - lastBodyDropTicks) < GRIND_RECENT_TICKS;
                if (laneKeepOk && (stuckOffRoad || grindingOffRoad))
                {
                    laneKeepOk = false;
                    if (driveLogger != null && driveLogger.IsRunning
                        && offNow - lastLateralEjectLogTicks > 10000000)
                    {
                        lastLateralEjectLogTicks = offNow;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lateral-eject:"
                            + " lat=" + lastLaneLateralError.ToString("F1")
                            + " speed=" + vehicleSpeed.ToString("F1")
                            + " why=" + (stuckOffRoad ? "stuck-offroad" : "grind-offroad")
                            + " recentOnRd=" + WasOnValidRoadForLastMs(POLY_GROUNDTRUTH_MS));
                    }
                }
            }
            // iter-33 B2: SUSTAINED-LATERAL escalation + directional cue. In the
            // 07-02 session the car rode a drivable dirt strip 9-12 m off Joshua
            // Road for minutes: laneKeepFailStreak stayed 0 (a polyline existed),
            // K1 above was vetoed by flickering native ground truth, and P1 needs
            // nativeOff too — so recovery NEVER armed while the lane-depart brake
            // pinned the car and the blind driver got no explanation. Two
            // additions, both gated on a 5 s sustained large error so the iter-23
            // dirt-road false-eject storm cannot return:
            //  (1) a directional speech cue telling the driver WHICH WAY the road
            //      is (lastLaneLateralError > 0 = path right of car => steer right);
            //  (2) recovery arm, but ONLY when the car is also genuinely pinned —
            //      near-stopped, or brake-pinned under player throttle — never on
            //      a healthy cruise (a dirt road the graph can't see stays exempt).
            {
                long latNow = DateTime.Now.Ticks;
                if (isFullMode && Math.Abs(lastLaneLateralError) > LATERAL_DEPART_CUE_LAT_M)
                {
                    if (sustainedLatDepartStartTicks == 0) sustainedLatDepartStartTicks = latNow;
                }
                else sustainedLatDepartStartTicks = 0;
                bool sustainedLatDepart = sustainedLatDepartStartTicks > 0
                    && (latNow - sustainedLatDepartStartTicks) / 10000 > LATERAL_DEPART_FAIL_MS;
                if (sustainedLatDepart)
                {
                    if (latNow - lastOffLineCueTicks > 80000000) // 8 s between cues
                    {
                        lastOffLineCueTicks = latNow;
                        Speech.Ambient(lastLaneLateralError > 0
                            ? "Off the road line. Steer right."
                            : "Off the road line. Steer left.");
                    }
                    bool pinnedSlow = vehicleSpeed < 3f;
                    bool brakePinned = laneDepartStreak >= LANE_DEPART_FRAMES
                        && lastPlayerThrottleRaw > 0.5f
                        && vehicleSpeed < LANE_DEPART_MIN_SPEED;
                    if (laneKeepOk && (pinnedSlow || brakePinned))
                    {
                        laneKeepOk = false;
                        if (driveLogger != null && driveLogger.IsRunning
                            && latNow - lastLateralEjectLogTicks > 10000000)
                        {
                            lastLateralEjectLogTicks = latNow;
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lateral-eject:"
                                + " lat=" + lastLaneLateralError.ToString("F1")
                                + " speed=" + vehicleSpeed.ToString("F1")
                                + " why=" + (pinnedSlow ? "sustained-lat-slow" : "sustained-lat-brakepin")
                                + " recentOnRd=" + WasOnValidRoadForLastMs(POLY_GROUNDTRUTH_MS));
                        }
                    }
                }
            }
            // Diagnostic: the closest-segment skew WOULD have failed but the look-ahead /
            // lateral gate spared it (the junction-phantom catch). Throttled to ~1/s.
            if (laneKeepOk && Math.Abs(roadHeadingDelta) > LANEKEEP_SKEW_FAIL_ANGLE
                && !(lookaheadSkewFail && laterallyOff)
                && driveLogger != null && driveLogger.IsRunning
                && (DateTime.Now.Ticks - lastSuppressLogTicks) > 10000000)
            {
                lastSuppressLogTicks = DateTime.Now.Ticks;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lookahead-suppress:"
                    + " effLatGate=" + effLatGate.ToString("F2")   // iter-41 Stage 6c: see a near-miss
                    + " closeSkew=" + roadHeadingDelta.ToString("F1")
                    + " aheadSkew=" + lastLookaheadHeadingDelta.ToString("F1")
                    + " lat=" + lastLaneLateralError.ToString("F2")
                    + " speed=" + playerVeh.Speed.ToString("F2"));
            }
            // Iter-10 Patch B: SEVERE-SKEW INSTANT EJECT. The 6-frame streak
            // above is the right gate for moderate skew (~30°), but at 55°+
            // the car is essentially sideways — there's no flicker scenario
            // where one frame at that angle should be excused as transient
            // noise. Force laneKeepOk=false on the very first frame and
            // pre-load the streak so a subsequent OK flicker can't reset it
            // back to LaneKeeping immediately.
            const float LANEKEEP_SKEW_SEVERE_ANGLE = 55f;
            if (Math.Abs(lastLookaheadHeadingDelta) > LANEKEEP_SKEW_SEVERE_ANGLE)
            {
                laneKeepOk = false;
                if (skewFailureStreak < LANEKEEP_SKEW_FAIL_FRAMES)
                    skewFailureStreak = LANEKEEP_SKEW_FAIL_FRAMES;
            }

            // PERSISTENT-SKEW ESCALATION. Track how long we've been pinned in
            // a heavily-skewed state outside LaneKeeping. Once past the bypass
            // threshold, allow the rate-clamped steering to release in one
            // frame. Past the righten threshold, snap the vehicle upright on
            // the road. Comfort doesn't matter when we're 50+ deg off-axis.
            bool inSkewedRecovery = currentDriveMode != DriveMode.LaneKeeping
                && Math.Abs(roadHeadingDelta) > PERSISTENT_SKEW_ANGLE;
            long skewNow = ModClock.Ticks; // pause-proof: persistent-skew duration (pairs with persistentSkewStartTicks)
            bypassSteerRateClampThisFrame = false;
            if (inSkewedRecovery)
            {
                if (persistentSkewStartTicks == 0) persistentSkewStartTicks = skewNow;
                long skewMs = (skewNow - persistentSkewStartTicks) / 10000;
                if (skewMs >= PERSISTENT_SKEW_BYPASS_MS)
                    bypassSteerRateClampThisFrame = true;
                if (skewMs >= PERSISTENT_SKEW_RIGHT_MS
                    && playerVeh.Speed < PERSISTENT_SKEW_RIGHT_SPEED
                    && (skewNow - lastSkewRighteningTicks) > SKEW_RIGHTEN_COOLDOWN_TICKS)
                {
                    Function.Call(Hash.SET_VEHICLE_ON_GROUND_PROPERLY, playerVeh, 5.0f);
                    lastSkewRighteningTicks = skewNow;
                    persistentSkewStartTicks = 0;
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount
                            + "] EVENT persistent-skew-righten: skewMs=" + skewMs
                            + " angle=" + roadHeadingDelta.ToString("F1"));
                    RecordDriveDecision("persistent-skew-righten: skewMs=" + skewMs);
                }
            }
            else
            {
                persistentSkewStartTicks = 0;
            }

            // Hysteresis on lane-keep failure (C2 fix). The OLD logic zeroed
            // the streak on a single OK frame, which let the system bounce
            // LaneKeeping <-> AligningHeading every ~60 frames (audit observed
            // streaks climbing to 46+ and failures clustering at the bounce).
            // NEW: decay the streak by 3 on each OK frame (asymmetric — a clean
            // frame in a noisy run is strong positive evidence) but bump by 1
            // on bad frames. Cap so it can't run away. Combined with the
            // sustained-evidence gates below, mode flips now require buffered
            // evidence in BOTH directions.
            // 2026-05-25 fix: prior `--` decay caused the streak to ceiling at
            // 20 and never drop back below LANEKEEP_FAILURE_HYSTERESIS once
            // saturated — every failure event in driveassist-2026-05-25-012227
            // shows laneKeepFailStreak=20.
            if (laneKeepOk && laneKeepFailureStreak > 0) laneKeepFailureStreak -= 3;
            else if (!laneKeepOk)
            {
                laneKeepFailureStreak++;
                lastStreakIncrementTicks = DateTime.Now.Ticks;
            }
            // Wall-clock decay: if the streak hasn't been incremented in the
            // last STREAK_TIME_DECAY_MS, drop it by 1 regardless of laneKeepOk.
            // Stops Mechanism D's "streak stuck at cap" pattern from chaotic
            // detection windows where laneKeepOk flickers True/False.
            if (laneKeepFailureStreak > 0 && lastStreakIncrementTicks > 0
                && (DateTime.Now.Ticks - lastStreakIncrementTicks) / 10000 > STREAK_TIME_DECAY_MS)
            {
                laneKeepFailureStreak--;
                // Slide the timestamp forward so the next decay step needs
                // another full STREAK_TIME_DECAY_MS to elapse.
                lastStreakIncrementTicks = DateTime.Now.Ticks;
            }
            if (laneKeepFailureStreak < 0) laneKeepFailureStreak = 0;
            if (laneKeepFailureStreak > LANEKEEP_FAILURE_STREAK_CAP)
                laneKeepFailureStreak = LANEKEEP_FAILURE_STREAK_CAP;

            // Sustained-evidence gates polled from the rolling history. Fall
            // back to legacy behavior in the first ~200 ms after start /
            // vehicle change (HistorySpansAtLeastMs returns false there).
            long modeNowTicks = DateTime.Now.Ticks;
            long msSinceModeChange = (modeNowTicks - lastModeChangeTicks) / 10000;
            bool transitionLocked = lastModeChangeTicks > 0
                && msSinceModeChange < MODE_CHANGE_HYSTERESIS_MS
                && HistorySpansAtLeastMs(MODE_CHANGE_HYSTERESIS_MS);

            bool useLaneKeep;
            if (transitionLocked)
            {
                // Recently flipped — hold whatever mode we're in. Prevents the
                // sub-second ping-pong the audit identified.
                useLaneKeep = (currentDriveMode == DriveMode.LaneKeeping);
            }
            else if (currentDriveMode == DriveMode.LaneKeeping)
            {
                // STAY in LaneKeeping unless sustained failure. Legacy
                // hysteresis still applies as a fallback for the warmup window.
                // Sustained failure = <20% OK frames in confirm window. The
                // prior "zero OK frames allowed" rule was too strict — a single
                // noisy OK frame in the middle of a clear failure stretch would
                // veto recovery for another full ALIGN_CONFIRM_MS.
                bool sustainedFailure =
                    HistorySpansAtLeastMs(ALIGN_CONFIRM_MS) &&
                    FractionLaneKeepOkInLastMs(ALIGN_CONFIRM_MS) < ALIGN_OK_FRACTION_MAX;
                bool legacyFallback = !HistorySpansAtLeastMs(ALIGN_CONFIRM_MS)
                    && laneKeepFailureStreak >= LANEKEEP_FAILURE_HYSTERESIS;
                // Iter-10 Patch A: SATURATED-STREAK EJECT. If
                // laneKeepFailureStreak has hit its cap (20), we've already
                // registered 20 distinct failure events — overwhelming
                // evidence the car isn't actually lane-keeping. The cap must
                // not be a stable resting state. Force the mode out of
                // LaneKeeping regardless of momentary laneKeepOk flickers.
                // driveassist-2026-05-25-231603 F5397 was 30 seconds in
                // mode=LaneKeeping with failStreak=20 and skewAngle=70.5° —
                // exactly the limbo this gate fixes.
                bool streakSaturated = laneKeepFailureStreak >= LANEKEEP_FAILURE_STREAK_CAP;
                useLaneKeep = (laneKeepOk && !streakSaturated)
                    || !(sustainedFailure || legacyFallback || streakSaturated);
            }
            else
            {
                // RETURN to LaneKeeping ONLY on sustained success — never on a
                // single OK frame (that's what caused the oscillation).
                // iter-17 Backstop A: also require the car to be genuinely realigned (low
                // look-ahead skew), not merely sitting over a road node. WasOnValidRoadForLastMs
                // is skew-blind, so at 99 deg over a junction node it returned true and
                // ping-ponged RecoveringToRoad<->LaneKeeping (021734 F3010-F3556).
                useLaneKeep = WasOnValidRoadForLastMs(LANEKEEP_CONFIRM_MS)
                    && Math.Abs(lastLookaheadHeadingDelta) < RECOVERY_EXIT_SKEW_MAX;
            }

            // iter-19 G2: during the watchdog grace window the player is sovereign —
            // force LaneKeeping regardless of laneKeepOk. The branch below tears
            // down every recovery latch (incl. alignmentEngageReverse), which is
            // exactly what kills the 204938 reverse-pulse re-arm. Failure streaks
            // keep accumulating, so a still-stuck car re-enters recovery on the
            // first scan after grace expires (or via the stuck-arm grace cancel).
            if (InWatchdogGrace()) useLaneKeep = true;

            DriveMode prevMode = currentDriveMode;

            if (useLaneKeep)
            {
                // Entering LaneKeeping is the canonical "we're OK" event. Reset
                // the failure streak so a saturated cap (20) from a prior
                // recovery cycle doesn't keep us pinned in the legacy-fallback
                // sustained-failure branch on the very next bad frame.
                if (currentDriveMode != DriveMode.LaneKeeping)
                    laneKeepFailureStreak = 0;
                currentDriveMode = DriveMode.LaneKeeping;
                // Re-flag as on-road so downstream gates pass even during a brief
                // detection blip — we keep applying the LAST valid road correction
                // (held by smoothedRoadCorrection from prior cycles).
                isOnValidRoad = true;
                leadVehicleSteer = GetLeadVehicleGuidance(playerVeh);
                if (hasLeadVehicle)
                {
                    // 55% lead vehicle (lateral lane position) + 45% road heading.
                    roadSteerCorrection = roadSteerCorrection * 0.45f + leadVehicleSteer * 0.55f;
                }
                hasRecoveryTarget = false;
                recoveryTargetLatched = false;
                recoveryBrakeRequest = 0f;
                recoveryUturnDir = 0;
                alignmentEngageReverse = false;
                // Clear residual recovery fields so they don't appear in the
                // logs (or feed any future code path) with values from a
                // recovery target the player drove away from minutes ago.
                // Analysis cluster 10 showed recoveryDist=2.6 logged while
                // the player was 510 m from the target.
                recoveryTargetPos = GTA.Math.Vector3.Zero;
                recoveryTargetHeading = 0f;
                recoveryTargetDistance = 999f;
                recoveryHeadingDelta = 0f;
                offroadModeStartTicks = 0; // back on the road; clear timeout
            }
            else
            {
                // Off-road / wrong-way timeout: if we've been stuck in
                // recovery for >3 s, force the lane-keep failure streak back
                // to threshold so FindBestRecoveryNode below re-resolves
                // against the latest vehicle state. Prevents the "stuck
                // forever" failure when a transient recovery target became
                // stale.
                long now = DateTime.Now.Ticks;
                bool timeoutReResolve = false;
                if (offroadModeStartTicks == 0) offroadModeStartTicks = now;
                else if (now - offroadModeStartTicks > OFFROAD_TIMEOUT_TICKS)
                {
                    laneKeepFailureStreak = LANEKEEP_FAILURE_HYSTERESIS;
                    offroadModeStartTicks = now; // re-arm so we re-check in another 3 s
                    timeoutReResolve = true;     // drop the latch so we re-pick
                }

                // LATCHED RECOVERY TARGET: pick a node ONCE when recovery
                // begins and keep pursuing the SAME node. Re-resolving every
                // tick made the car chase a moving "nearest node" and orbit it
                // forever (the ~1900-frame stuck loop in the debug log).
                bool needNewTarget = !recoveryTargetLatched || timeoutReResolve;
                bool targetV2 = getSetting("recoveryTargetV2") == 1;
                string reResolveReason = timeoutReResolve ? "timeout" : "unlatched";
                if (recoveryTargetLatched && !timeoutReResolve)
                {
                    // Refresh distance / heading error against the SAME node as
                    // the car moves.
                    recoveryTargetDistance = (recoveryTargetPos - playerVeh.Position).Length(); // iter-18 D3
                    float hd = recoveryTargetHeading - playerVeh.Heading;
                    while (hd > 180f) hd -= 360f;
                    while (hd < -180f) hd += 360f;
                    recoveryHeadingDelta = hd;
                    hasRecoveryTarget = true;
                    // The car wandered well clear of the latched node — it is
                    // no longer a useful target, so re-resolve.
                    if (recoveryTargetDistance > RECOVERY_TARGET_ABANDON)
                    {
                        needNewTarget = true;
                        reResolveReason = "abandon-dist";
                    }
                    // ---- iter-40 recoveryTargetV2 ----
                    // The 60 m abandon threshold is far too loose to catch the actual
                    // failure. On 07-28 EVERY recovery-search in the session reported
                    // targetBlocked=True, the target never moved from (-196.5,3743.8),
                    // and the car's distance to it climbed monotonically
                    // 16.8 -> 20.1 -> 23.4 -> 26.6 -> 29.8 -> 30.7 -> 34.4 -> 39.9 m.
                    // It never hit 60, so the latch held the whole time and recovery
                    // steered toward a blocked point it was moving away from.
                    //
                    // targetBlocked was already being COMPUTED here — but only to be
                    // written to the log. Act on it.
                    else if (targetV2)
                    {
                        // iter-46 1-1: unit=search — one recovery-target evaluation.
                        // 07-31 logged 269 recovery-search events against a census of
                        // eval:0/fire:0. fire is set below, on an actual re-resolve.
                        GateReach("recoveryTargetV2");
                        bool blockedNow = closestThreatPosition != GTA.Math.Vector3.Zero
                            && playerVeh.Position.DistanceTo(closestThreatPosition) < recoveryTargetDistance;
                        // Receding: the target is getting further away across two
                        // consecutive checks by a margin above measurement noise.
                        bool receding = recoveryTargetPrevDist > 0f
                            && recoveryTargetDistance > recoveryTargetPrevDist + RECOVERY_RECEDE_EPS_M;
                        if (receding) recoveryTargetRecedeStreak++;
                        else if (recoveryTargetDistance < recoveryTargetPrevDist) recoveryTargetRecedeStreak = 0;
                        recoveryTargetPrevDist = recoveryTargetDistance;

                        bool cooledDown = now - recoveryTargetReResolveTicks
                            > RECOVERY_RERESOLVE_MIN_TICKS;
                        if (cooledDown && blockedNow)
                        {
                            needNewTarget = true;
                            reResolveReason = "blocked";
                        }
                        else if (cooledDown && recoveryTargetRecedeStreak >= RECOVERY_RECEDE_STREAK)
                        {
                            needNewTarget = true;
                            reResolveReason = "receding";
                        }
                        if (needNewTarget)
                        {
                            GateFire("recoveryTargetV2");
                            recoveryTargetReResolveTicks = now;
                            recoveryTargetRecedeStreak = 0;
                            recoveryTargetPrevDist = 0f;
                        }
                    }
                }
                else if (targetV2)
                {
                    recoveryTargetPrevDist = 0f;
                    recoveryTargetRecedeStreak = 0;
                }

                if (needNewTarget)
                {
                    // Lane-keep failed — look for ANY recovery node.
                    hasRecoveryTarget = FindBestRecoveryNode(playerVeh,
                        out recoveryTargetPos, out recoveryTargetHeading,
                        out recoveryTargetDistance, out recoveryHeadingDelta);
                    recoveryTargetLatched = hasRecoveryTarget;

                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT recovery-search:"
                            + " found=" + hasRecoveryTarget
                            + " targetPos=" + FmtV(recoveryTargetPos)
                            + " vehHeading=" + playerVeh.Heading.ToString("F1")
                            + " targetHeading=" + recoveryTargetHeading.ToString("F1")
                            + " dist=" + recoveryTargetDistance.ToString("F1")
                            + " headingDelta=" + recoveryHeadingDelta.ToString("F1")
                            + " flipAvoided=" + (Math.Abs(recoveryHeadingDelta) <= RECOVERY_FLIP_ANGLE)
                            + " perpBand=" + (Math.Abs(recoveryHeadingDelta) > RECOVERY_PERP_REJECT_ANGLE
                                              && Math.Abs(recoveryHeadingDelta) < RECOVERY_FLIP_ANGLE)
                            // iter-27 L5: is the path to the chosen recovery node clear, or did
                            // we pick a target routed through a known obstacle? 014616 #1 chose a
                            // recovery node while a prop sat 4.8 m dead ahead and steered into it.
                            + " fwdClear=" + (navAssistDistCenter >= 999f ? "nocast" : navAssistDistCenter.ToString("F1")) // iter-29 C5: no-data vs clear
                            + " obstDist=" + (closestThreatPosition != GTA.Math.Vector3.Zero
                                  ? playerVeh.Position.DistanceTo(closestThreatPosition).ToString("F1") : "-")
                            + " targetBlocked=" + (closestThreatPosition != GTA.Math.Vector3.Zero
                                  && playerVeh.Position.DistanceTo(closestThreatPosition) < recoveryTargetDistance)
                            + " speedFlipReject=" + lastRecoverySpeedFlipReject // iter-24 R2
                            + " why=" + reResolveReason); // iter-40: which rule forced this search
                    RecordDriveDecision("recovery-search: found=" + hasRecoveryTarget
                        + " dist=" + recoveryTargetDistance.ToString("F1"));
                }

                if (hasRecoveryTarget)
                {
                    // Mode hysteresis: enter RecoveringToRoad past the engage
                    // distance, but once recovering stay there until the target
                    // is comfortably closer than the disengage distance. The
                    // gap kills the flip-flop the log showed at the 8 m line.
                    bool wantRecover = currentDriveMode == DriveMode.RecoveringToRoad
                        ? recoveryTargetDistance > RECOVERY_DISTANCE_DISENGAGE
                        : recoveryTargetDistance > RECOVERY_DISTANCE_ENGAGE;
                    currentDriveMode = wantRecover
                        ? DriveMode.RecoveringToRoad
                        : DriveMode.AligningHeading;
                }
                else
                {
                    // No nodes at all — leave the assist passive.
                    currentDriveMode = DriveMode.LaneKeeping;
                    recoveryTargetLatched = false;
                    recoveryBrakeRequest = 0f;
                    recoveryUturnDir = 0;
                    alignmentEngageReverse = false;
                }

                if (currentDriveMode != DriveMode.LaneKeeping)
                {
                    GetAlignmentRecoverySteer(playerVeh, recoveryTargetPos, recoveryTargetHeading,
                        recoveryTargetDistance, recoveryHeadingDelta,
                        out roadSteerCorrection, out alignmentEngageReverse,
                        out recoveryBrakeRequest);
                    isOnValidRoad = true;            // Downstream code expects a guidance source.
                    roadHeadingDelta = recoveryHeadingDelta;
                    hasLeadVehicle = false;

                    // iter-29 B: REVERSE-STRAIGHT-OUT when boxed off-road. 032924: every
                    // recovery target was targetBlocked (obstDist 2-11 m) and often
                    // perpendicular (~89 deg), so recovery flip-cycled into a wall instead
                    // of backing out the (known-clear) way it came. When genuinely off-road
                    // at low speed with the target blocked OR perpendicular AND the rear is
                    // clear, command a straight reverse (reuses alignmentEngageReverse + the
                    // M1/M2 reverse handling). If the rear is also blocked, the existing M3
                    // give-up still fires.
                    bool recovTargetBlocked = closestThreatPosition != GTA.Math.Vector3.Zero
                        && playerVeh.Position.DistanceTo(closestThreatPosition) < recoveryTargetDistance;
                    bool recovPerp = Math.Abs(recoveryHeadingDelta) > RECOVERY_PERP_REJECT_ANGLE;
                    // iter-40 recoveryTargetV2: honour a rear slope the ground filter
                    // discarded. Without this the 999 sentinel reads as clear and the
                    // mod commits a blind driver to a reverse it has no data for.
                    bool rearClear = navAssistDistBehind >= REVERSE_REAR_MIN_CLEAR_STUCK
                        && (getSetting("recoveryTargetV2") != 1
                            || navAssistBehindGroundDist >= REVERSE_REAR_MIN_CLEAR_STUCK);
                    // iter-30: only reverse straight out when roughly aligned with the lane
                    // axis. In iter-29 #3 the car backed straight at ~50 deg skew and drove
                    // lat -27 -> -36 (further off-road). If it's badly skewed/perpendicular,
                    // straight-back doesn't return it to the lane — fall through to steered
                    // recovery / the M3 give-up instead.
                    if (!alignmentEngageReverse && vehicleSpeed < 4f
                        && !IsPositionOnRoad(playerVeh.Position)
                        && Math.Abs(vehicleSkewAngle) < REVERSE_OUT_ALIGN_MAX_DEG
                        && (recovTargetBlocked || recovPerp) && rearClear)
                    {
                        alignmentEngageReverse = true;
                        roadSteerCorrection = 0f;       // straight back
                        recoveryBrakeRequest = 0f;      // don't brake against the reverse (M1)
                        if (driveLogger != null && driveLogger.IsRunning
                            && DateTime.Now.Ticks - lastReverseOutLogTicks > 10000000)
                        {
                            lastReverseOutLogTicks = DateTime.Now.Ticks;
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT recovery-reverse-out:"
                                + " headingDelta=" + recoveryHeadingDelta.ToString("F1")
                                + " targetBlocked=" + recovTargetBlocked
                                + " rearClear=" + navAssistDistBehind.ToString("F1")
                                // iter-40: distinguish "nothing behind" from "we
                                // discarded what was behind as ground".
                                + " rearSlope=" + (navAssistBehindGroundDist < 900f
                                    ? navAssistBehindGroundDist.ToString("F1") : "none")
                                + " speed=" + vehicleSpeed.ToString("F1"));
                        }
                    }

                    // iter-35 P5: reverse-out FLANK guard. 07-03 #9 lost -33.8 in one
                    // frame reversing with steer while the right flank had 2.29 m of
                    // world — the plan validated rear + target but never the sides
                    // the rotating body sweeps through. Tight flank = back straight
                    // out instead. (True arc-sweep clearance is the A7 escalation if
                    // this cheap check proves insufficient.)
                    if (alignmentEngageReverse && Math.Abs(roadSteerCorrection) > 0.2f)
                    {
                        float flankHalfW = GetVehicleHalfDims(playerVeh).X;
                        if (Math.Min(navAssistDistLeft, navAssistDistRight) < flankHalfW + 1.0f)
                        {
                            if (driveLogger != null && driveLogger.IsRunning
                                && DateTime.Now.Ticks - lastFlankClampLogTicks > 10000000)
                            {
                                lastFlankClampLogTicks = DateTime.Now.Ticks;
                                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT reverse-flank-clamp:"
                                    + " steer=" + roadSteerCorrection.ToString("F2")
                                    + " left=" + navAssistDistLeft.ToString("F1")
                                    + " right=" + navAssistDistRight.ToString("F1")
                                    + " halfW=" + flankHalfW.ToString("F1"));
                            }
                            roadSteerCorrection = 0f;
                        }
                    }

                    // iter-24 R1: BRAKE-FIRST AT SPEED. Steering toward a recovery
                    // node (often a U-turn target) while still fast makes a high-
                    // speed overshoot worse — hold the wheel straight and brake hard
                    // until the car is slow enough to actually turn. Normal recovery
                    // steer resumes below the gate. Not applied to a commanded reverse
                    // (that only engages at low speed and is intentionally a U-turn).
                    if (vehicleSpeed > RECOVERY_BRAKE_FIRST_SPEED && !alignmentEngageReverse)
                    {
                        roadSteerCorrection = 0f;
                        recoveryBrakeRequest = 1.0f;
                    }

                    // Iter-9 Patch E: dense-traffic-aware pause. F3527 in
                    // driveassist-2026-05-25-180748 collided at 0.46 m/s
                    // while recovery was steering it through a parking-lot-
                    // density cluster. Pause-mode: count nearby vehicles
                    // within RECOVERY_PAUSE_BLOCK_R (10 m); if >=2 AND the
                    // car has been stalled <2 m/s for RECOVERY_PAUSE_STALL_MS,
                    // hold a brake (RECOVERY_PAUSE_BRAKE) and zero the
                    // recovery steer so the car doesn't fight to push
                    // through traffic. Resume when no vehicle within
                    // RECOVERY_PAUSE_CLOSE_R for RECOVERY_PAUSE_RESUME_MS.
                    long nowEPause = DateTime.Now.Ticks;
                    int nearbyBlockCount = 0;
                    int nearbyCloseCount = 0;
                    foreach (Vehicle nv in World.GetNearbyVehicles(playerVeh.Position,
                        RECOVERY_PAUSE_BLOCK_R + 0.1f))
                    {
                        if (nv == null || !nv.Exists()) continue;
                        if (nv.Handle == playerVeh.Handle) continue;
                        float nd = playerVeh.Position.DistanceTo(nv.Position);
                        if (nd <= RECOVERY_PAUSE_BLOCK_R) nearbyBlockCount++;
                        if (nd <= RECOVERY_PAUSE_CLOSE_R) nearbyCloseCount++;
                    }
                    bool stalled = vehicleSpeed < 2f
                        && VehicleStoppedForLastMs(2f, RECOVERY_PAUSE_STALL_MS);
                    bool blockedEnough = nearbyBlockCount >= RECOVERY_PAUSE_BLOCK_COUNT;

                    if (nearbyCloseCount == 0) recoveryLastClearTicks = nowEPause;

                    // Enter pause if blocked AND stalled, or stay paused until
                    // the resume gate (clear for RECOVERY_PAUSE_RESUME_MS) is
                    // met. recoveryLastClearTicks is updated whenever the
                    // close-band is empty; the resume comparison reads it.
                    bool wasPaused = recoveryPausedSinceTicks > 0;
                    bool stayPaused = wasPaused
                        && (nowEPause - recoveryLastClearTicks) < RECOVERY_PAUSE_RESUME_MS * 10000;
                    // Iter-11 Patch L: 8-second hard timeout escape hatch.
                    // driveassist-2026-05-27-171958 showed 48 pause/resume
                    // events but at least 5 PLAYER markers stuck in pause
                    // for 10+ seconds because the jam blockers never moved.
                    // The resume gate (close-band empty for 500 ms) cannot
                    // fire in a true traffic jam. Force-resume after 8 s of
                    // continuous pause so the recovery steer + brake pipeline
                    // can at least try to nudge through. The existing
                    // UpdateStuckRecovery escalation will take over if the
                    // nudge doesn't make progress.
                    const long RECOVERY_PAUSE_HARD_TIMEOUT_TICKS = 80000000L; // 8 s
                    // iter-40 recoveryTargetV2: waiting politely is the wrong instinct
                    // when the car is stopped IN a travel lane. On 07-28 this paused
                    // recovery with the car parked across a live La Puerta Fwy lane
                    // (F18997, nearbyVehicles=2, speed=0.41) and a Vigero closing at
                    // 14.9 m/s put 396 engine points into it moments later. Nearby
                    // traffic there is a reason to clear the lane FASTER, not to sit
                    // still. Keep the polite pause for off-road and parking-lot cases.
                    long pauseTimeoutTicks = RECOVERY_PAUSE_HARD_TIMEOUT_TICKS;
                    if (getSetting("recoveryTargetV2") == 1 && nearbyBlockCount > 0)
                    {
                        bool inTravelLane = false;
                        try { inTravelLane = IsPositionOnRoad(playerVeh.Position); }
                        catch { inTravelLane = false; }
                        if (inTravelLane)
                            pauseTimeoutTicks = RECOVERY_PAUSE_ONROAD_TIMEOUT_TICKS;
                    }
                    bool hardTimeout = wasPaused
                        && (nowEPause - recoveryPausedSinceTicks) > pauseTimeoutTicks;
                    // iter-34 CRIT-3: a pause is a polite wait — never hold it while
                    // the wedged car is actively losing body health (07-03 detonation
                    // ran recovery-paused cycles while the engine cooked).
                    bool nowPaused = ((blockedEnough && stalled) || stayPaused) && !hardTimeout
                        && !DamageWhileWedged(vehicleSpeed);

                    if (nowPaused)
                    {
                        if (!wasPaused)
                        {
                            recoveryPausedSinceTicks = nowEPause;
                            if (driveLogger != null && driveLogger.IsRunning)
                                driveLogger.Write("[F" + driveLogFrameCount
                                    + "] EVENT recovery-paused: nearbyVehicles=" + nearbyBlockCount
                                    + " speed=" + vehicleSpeed.ToString("F2"));
                            RecordDriveDecision("recovery-paused: blockers=" + nearbyBlockCount);
                            recoveryPauseLogged = true;
                        }
                        // Override outputs: hold brake, drop the recovery
                        // steer so the wheel doesn't push toward the target
                        // through bodies.
                        if (recoveryBrakeRequest < RECOVERY_PAUSE_BRAKE)
                            recoveryBrakeRequest = RECOVERY_PAUSE_BRAKE;
                        roadSteerCorrection = 0f;
                    }
                    else if (wasPaused)
                    {
                        // Resume: either surroundings cleared, OR iter-11
                        // Patch L 8-second hard timeout fired. Log
                        // distinguishes the two so post-hoc analysis can
                        // count how often the timeout escape was needed.
                        if (driveLogger != null && driveLogger.IsRunning && recoveryPauseLogged)
                        {
                            if (hardTimeout)
                                driveLogger.Write("[F" + driveLogFrameCount
                                    + "] EVENT recovery-pause-timeout: pausedMs="
                                    + ((nowEPause - recoveryPausedSinceTicks) / 10000));
                            else
                                driveLogger.Write("[F" + driveLogFrameCount
                                    + "] EVENT recovery-resumed: clearMs="
                                    + ((nowEPause - recoveryLastClearTicks) / 10000));
                        }
                        RecordDriveDecision(hardTimeout ? "recovery-pause-timeout" : "recovery-resumed");
                        recoveryPausedSinceTicks = 0;
                        recoveryPauseLogged = false;
                    }
                }
                else
                {
                    recoveryBrakeRequest = 0f;
                    // Leaving recovery — clear the pause state too.
                    if (recoveryPausedSinceTicks > 0)
                    {
                        recoveryPausedSinceTicks = 0;
                        recoveryPauseLogged = false;
                    }
                }
            }

            // Stamp the mode-change time so the next-tick hysteresis gate can
            // measure how long ago we last flipped.
            if (currentDriveMode != prevMode)
                lastModeChangeTicks = DateTime.Now.Ticks;

            // Mode-transition announcements (rate-limited to 5 s).
            if (currentDriveMode != lastAnnouncedMode
                && DateTime.Now.Ticks - lastDriveModeAnnounceTicks > 50000000)
            {
                string modeMsg = null;
                if (currentDriveMode == DriveMode.RecoveringToRoad) modeMsg = "Off road, recovering";
                else if (currentDriveMode == DriveMode.AligningHeading) modeMsg = "Aligning to road";
                else if (lastAnnouncedMode != DriveMode.LaneKeeping) modeMsg = "Aligned";
                if (modeMsg != null) Speech.Info(modeMsg);
                lastDriveModeAnnounceTicks = DateTime.Now.Ticks;
                lastAnnouncedMode = currentDriveMode;
            }

            if (driveLogger != null && driveLogger.IsRunning && currentDriveMode != driveLogLastMode)
            {
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT mode-change: "
                    + driveLogLastMode + " -> " + currentDriveMode
                    + " laneKeepOk=" + laneKeepOk
                    + " failStreak=" + laneKeepFailureStreak
                    + " hasRecovery=" + hasRecoveryTarget
                    + " recoveryDist=" + recoveryTargetDistance.ToString("F1"));
                RecordDriveDecision("mode-change: " + driveLogLastMode + " -> " + currentDriveMode
                    + " failStreak=" + laneKeepFailureStreak);
                driveLogLastMode = currentDriveMode;
            }

            // STUCK RECOVERY: detect a recovery mode that is commanding the
            // car but making no physical progress, and escalate. Runs after
            // the mode block so it can override alignmentEngageReverse for the
            // reverse-out layer before ApplySteeringAssist consumes it.
            UpdateStuckRecovery(playerVeh, isFullMode);

            // ============================================
            // SPATIAL AWARENESS - Analyze front/back clearance for handbrake turn decisions
            // ============================================
            float frontClearance = navAssistDistCenter;
            float rearClearance = navAssistDistBehind;
            float leftClearance = navAssistDistLeft;
            float rightClearance = navAssistDistRight;

            // Calculate vehicle skew relative to road heading
            vehicleSkewAngle = roadHeadingDelta; // set by ComputeStanleySteer (via GetLaneCenterGuidance) this tick
            vehicleSkewStampTicks = DateTime.Now.Ticks; // iter-35 L6: freshness stamp — 07-03 #9 failClass skew disagreed with FRAME skew purely from staleness
            vehicleIsSkewed = Math.Abs(vehicleSkewAngle) > 25f; // More than 25 degrees off road heading

            // Determine if handbrake turn would help correct the situation
            // Conditions for handbrake turn assist:
            // 1. Vehicle is significantly skewed from road direction (>25°)
            // 2. There's an obstacle ahead within braking distance
            // 3. There's clearance on one side to turn into
            // 4. Speed is in the right range (5-20 m/s) - too fast is dangerous
            // 5. Not reversing (handbrake turns don't work well in reverse)
            bool needsHandbrakeTurn = false;
            float handbrakeSteerDir = 0f;

            // Only enable handbrake turns at moderate speeds (5-20 m/s / ~10-45 mph)
            // Too slow: regular steering works fine
            // Too fast: handbrake turn is dangerous and could cause rollover
            // iter-31: cap handbrake-turn speed at 10 m/s (was 20). Above ~10 m/s a
            // handbrake locks the rear wheels into a skid — it wrecked the -114 lane-
            // departure recovery in 034850 #5 (owner=handbrake, only ~3.5 m/s2 decel on
            // off-road ground and no steering authority left to drag the car back). Sharp
            // corrections at speed now use foot brake + steering; the handbrake turn is
            // reserved for genuine tight low-speed pivots.
            bool speedOkForHandbrake = vehicleSpeed > 5f && vehicleSpeed < HANDBRAKE_TURN_MAX_SPEED;

            if (isFullMode && speedOkForHandbrake && !isReversing)
            {
                // Check if we need to make a sharp correction
                // Scale the "blocked" threshold - at higher speeds, need more time to react
                float timeAhead = Math.Max(1.5f, vehicleSpeed / 15f); // 1.5s minimum, scales with speed
                bool frontBlocked = frontClearance < vehicleSpeed * timeAhead;
                bool needsSharpTurn = Math.Abs(roadSteerCorrection) > 0.6f || vehicleIsSkewed;

                // Also require sufficient clearance on the target side (at least 8m)
                float minClearanceForTurn = 8f;

                if (frontBlocked && needsSharpTurn)
                {
                    // Determine which way to turn based on road direction and clearance
                    if (roadSteerCorrection > 0.3f && rightClearance > leftClearance + 3f && rightClearance > minClearanceForTurn)
                    {
                        // Need to turn right and right side is clearer
                        needsHandbrakeTurn = true;
                        handbrakeSteerDir = 1f;
                    }
                    else if (roadSteerCorrection < -0.3f && leftClearance > rightClearance + 3f && leftClearance > minClearanceForTurn)
                    {
                        // Need to turn left and left side is clearer
                        needsHandbrakeTurn = true;
                        handbrakeSteerDir = -1f;
                    }
                    else if (vehicleIsSkewed)
                    {
                        // Vehicle is skewed - turn toward road heading
                        // If skew is positive (road is to our right), turn right
                        if (vehicleSkewAngle > 25f && rightClearance > minClearanceForTurn)
                        {
                            needsHandbrakeTurn = true;
                            handbrakeSteerDir = 1f;
                        }
                        else if (vehicleSkewAngle < -25f && leftClearance > minClearanceForTurn)
                        {
                            needsHandbrakeTurn = true;
                            handbrakeSteerDir = -1f;
                        }
                    }
                }
            }

            // Apply controls if threat detected
            float steerThreshold = isFullMode ? STEER_THRESHOLD_FULL : STEER_THRESHOLD_ASSIST;
            float brakeThreshold = isFullMode ? BRAKE_THRESHOLD_FULL : BRAKE_THRESHOLD_ASSIST;
            // iter-43 A4: the emergency-latch distance scales with the vehicle too —
            // a long truck's bumper reaches an obstacle well before a sedan's does
            // at the same centre-to-centre distance.
            float minBrakeDist = (isFullMode ? MIN_BRAKE_DISTANCE_FULL : MIN_BRAKE_DISTANCE)
                * VehicleBrakeScale(cachedGeometryVehicle);

            // LOW-SPEED TTC TIGHTENING: below ~5 mph, normal time-based thresholds
            // produce nuisance brakes because small absolute distances translate to
            // small TTCs. Require an imminent (≤0.3 s) TTC at creep speeds.
            if (vehicleSpeed < BRAKE_LOW_SPEED_CUTOFF)
            {
                brakeThreshold = Math.Min(brakeThreshold, BRAKE_LOW_SPEED_TTC);
            }

            // ============================================
            // NPC AI-STYLE SWERVE-VS-BRAKE DECISION SYSTEM
            // Based on vehicleaihandlinginfo.meta parameters:
            // - At high speed, prefer swerving (fSpeedForSwerving concept)
            // - Use per-obstacle-type distances (fSwerveDist / fBrakingDist)
            // - Consider angle to obstacle (fMinSteerAngleForBraking)
            // ============================================
            bool hasSteerThreat = false;
            bool hasBrakeThreat = false;

            if (closestSteerTTC < float.MaxValue || closestBrakeTTC < float.MaxValue)
            {
                // Get per-type distances
                float swerveDistForType = GetSwerveDistForType(closestType);
                float brakeDistForType = GetBrakeDistForType(closestBrakeType);

                // Speed-scale the distances (faster = need to react earlier)
                float speedScale = Math.Max(1.0f, vehicleSpeed / 10.0f);
                float effectiveSwerveRange = swerveDistForType * speedScale;
                float effectiveBrakeRange = brakeDistForType * speedScale;

                // Calculate angle to the obstacle for swerve-vs-brake decision
                float angleToObstacle = closestSteerThreatPos != GTA.Math.Vector3.Zero
                    ? GetAngleToObstacle(playerVeh, closestSteerThreatPos)
                    : 0f;

                if (vehicleSpeed > SPEED_FOR_SWERVING && angleToObstacle < MIN_STEER_ANGLE_FOR_BRAKING)
                {
                    // HIGH SPEED + obstacle roughly ahead: prefer swerving over braking
                    // Swerve range is larger than brake range, so we start steering earlier
                    float swerveTTC = effectiveSwerveRange / Math.Max(vehicleSpeed, 1f);
                    float brakeTTC = effectiveBrakeRange / Math.Max(vehicleSpeed, 1f);

                    hasSteerThreat = closestSteerTTC < Math.Max(steerThreshold, swerveTTC);
                    // Only brake if obstacle is very close and swerving alone won't work
                    hasBrakeThreat = closestBrakeTTC < Math.Min(brakeThreshold, brakeTTC)
                                    && closestBrakeDistance > BRAKE_MIN_USEFUL_DIST
                                    && closestBrakeTTC < 0.8f; // Very imminent
                }
                else
                {
                    // LOW SPEED or large angle: prefer braking
                    hasBrakeThreat = closestBrakeTTC < brakeThreshold && closestBrakeDistance > BRAKE_MIN_USEFUL_DIST;
                    hasSteerThreat = closestSteerTTC < steerThreshold;
                }

                // Always allow steering for very imminent threats regardless of preference
                if (closestSteerTTC < steerThreshold * 0.5f)
                    hasSteerThreat = true;
                // Always allow braking for very imminent threats regardless of preference
                if (closestBrakeTTC < 0.5f && closestBrakeDistance > BRAKE_MIN_USEFUL_DIST)
                    hasBrakeThreat = true;

                // Iter-11 Patch H: decouple brake from steer for forward-cone
                // threats. The high-speed branch above narrows the brake gate
                // to closestBrakeTTC < 0.8f when steering is preferred, which
                // is the structural cause of 14 (48%) of the player markers
                // in driveassist-2026-05-27-171958 — rear-end collisions at
                // skew 5-30° where the mod chose swerve over brake even
                // though the vehicle ahead was unavoidable. For a TRULY
                // forward threat (angle < 25°), brake and steer should both
                // engage in parallel — the brake pipeline (rampedBrakeInput)
                // and steer pipeline (combinedSteer) write distinct outputs,
                // so coexistence has no architectural conflict.
                if (angleToObstacle < 25f
                    && closestBrakeTTC < brakeThreshold
                    && closestBrakeDistance > BRAKE_MIN_USEFUL_DIST)
                {
                    hasBrakeThreat = true;
                }

                // iter-28 B-1: POINT-BLANK BRAKE LATCH. The BRAKE_MIN_USEFUL_DIST floor
                // was meant to drop stale/passed sub-1m threats, but it also disarmed
                // the brake the frame before impact (014616 #2/#9 + 024041 #2 took the
                // hit with brakeMag=0 right after brakeDist fell below the floor). If a
                // real threat is still CLOSING inside the floor while we're moving,
                // keep braking through the final metre; only "release" when ~stopped.
                bool pointBlank = closestBrakeDistance > 0.2f
                    && closestBrakeDistance <= BRAKE_MIN_USEFUL_DIST
                    && closestBrakeTTC < 1.0f;
                if (pointBlank && !hasBrakeThreat && vehicleSpeed > 2f)
                {
                    hasBrakeThreat = true; // latch through the final metre
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT brake-floor-latch:"
                            + " brakeDist=" + closestBrakeDistance.ToString("F2")
                            + " ttc=" + closestBrakeTTC.ToString("F2")
                            + " type=" + closestBrakeType
                            + " speed=" + vehicleSpeed.ToString("F1"));
                }
                else if (pointBlank && !hasBrakeThreat && vehicleSpeed > 1f
                    && driveLogger != null && driveLogger.IsRunning)
                {
                    // iter-29 C2: only log the release while still rolling (>1 m/s). The
                    // iter-28 speed gate was on the LATCH branch only, so the release
                    // spammed 182x at speed 0 while wedged. Below 1 m/s it's uninteresting.
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT brake-floor-release:"
                        + " brakeDist=" + closestBrakeDistance.ToString("F2")
                        + " min=" + BRAKE_MIN_USEFUL_DIST.ToString("F2")
                        + " ttc=" + closestBrakeTTC.ToString("F2")
                        + " type=" + closestBrakeType
                        + " speed=" + vehicleSpeed.ToString("F1"));
                }
            }

            // ============================================
            // FIRST-CONTACT EMERGENCY STOP (REWRITTEN)
            // Previous version multiplied vehicle.Velocity directly to simulate a hard
            // brake. That bypassed the game's brake physics and produced a sudden,
            // unphysical slowdown (the "jerky brake" complaint).
            //
            // Now: announce the emergency, set a flag so ApplyCachedSteeringInputs
            // ramps the brake control input up over a few frames at full magnitude
            // (cachedBrakeMagnitude = 1.0). The game's actual brake/ABS physics handle
            // the deceleration curve, which feels natural instead of teleporting speed.
            // ============================================
            // AVOID-DIRECTION HYSTERESIS. The per-scan threat priority can
            // ping-pong between two sources (e.g. ped-ahead vs wall-from-
            // static-cast) and flip avoidDirection sign on neighbouring
            // frames, yaw-oscillating the wheel. The previous gate compared
            // only against cachedAvoidDirection, so +1 -> 0 -> -1 published
            // -1 instantly because the intermediate 0 reset the cache. New
            // log driveassist-2026-05-25-111452 F478-F502 is exactly that
            // pattern.
            //
            // Now: track the most recent NON-ZERO published direction (with a
            // 500 ms memory window). Opposite-sign re-acquisition against
            // memory requires AVOID_DIR_FLIP_HOLD consecutive frames before
            // publishing — even when the immediately previous cached value
            // was zero. Clearing to 0 still publishes immediately because
            // zero is always safe.
            long avoidNow = DateTime.Now.Ticks;
            bool memoryStale = lastNonZeroAvoidDir == 0
                || (avoidNow - lastNonZeroAvoidDirTicks) > AVOID_DIR_MEMORY_TICKS;
            int publishedAvoidDir;
            if (avoidDirection == 0)
            {
                publishedAvoidDir = 0;
                proposedAvoidDirection = 0;
                avoidDirHoldFrames = 0;
            }
            else if (memoryStale || avoidDirection == lastNonZeroAvoidDir)
            {
                // No conflicting recent memory, or same sign as memory —
                // publish immediately.
                publishedAvoidDir = avoidDirection;
                proposedAvoidDirection = avoidDirection;
                avoidDirHoldFrames = 0;
            }
            else
            {
                // Opposite sign vs recent memory — require sustained evidence.
                if (avoidDirection == proposedAvoidDirection)
                    avoidDirHoldFrames++;
                else
                {
                    proposedAvoidDirection = avoidDirection;
                    avoidDirHoldFrames = 1;
                }
                publishedAvoidDir = avoidDirHoldFrames >= AVOID_DIR_FLIP_HOLD
                    ? avoidDirection
                    : (cachedAvoidDirection != 0 ? cachedAvoidDirection : lastNonZeroAvoidDir);
            }
            if (publishedAvoidDir != 0)
            {
                lastNonZeroAvoidDir = publishedAvoidDir;
                lastNonZeroAvoidDirTicks = avoidNow;
            }

            // Real release-distance hysteresis. The old single-threshold
            // gate (obstacleInCriticalZone = dist <= minBrakeDist) flips on/off
            // every frame when raycast distance jitters across the threshold,
            // re-firing the Tolk "Emergency brake!" line and re-latching
            // emergencyBrakeActive at the underlying scan cadence. Separate
            // ENTER and RELEASE distances stop that flip-flop:
            //   ENTER   = minBrakeDist            (3 m assist / 5 m full)
            //   RELEASE = minBrakeDist + 1.5 m    (4.5 m / 6.5 m)
            // wasObstacleInBrakeZone now tracks the latched zone state, not
            // just last-frame entry, so the release threshold is what unlatches
            // it. Also requires >= CRITICAL_ARM_FRAMES consecutive entry frames
            // before firing — a single noisy scan can't slam the brake.
            const float CRITICAL_RELEASE_MARGIN = 1.5f;
            const int CRITICAL_ARM_FRAMES = 2;
            float releaseDist = minBrakeDist + CRITICAL_RELEASE_MARGIN;
            bool obstacleEnter   = closestBrakeDistance <= minBrakeDist && closestBrakeDistance < 999f;
            bool obstacleRelease = closestBrakeDistance > releaseDist || closestBrakeDistance >= 999f;
            if (obstacleEnter) criticalZoneArmFrames++;
            else criticalZoneArmFrames = 0;
            bool obstacleInCriticalZone;
            if (wasObstacleInBrakeZone)
            {
                // Already latched — only unlatch when we cross the release band.
                obstacleInCriticalZone = !obstacleRelease;
            }
            else
            {
                // Not latched — arm only after N consecutive entry frames.
                obstacleInCriticalZone = obstacleEnter && criticalZoneArmFrames >= CRITICAL_ARM_FRAMES;
            }

            if (obstacleInCriticalZone && !wasObstacleInBrakeZone && !cachedIsBraking && vehicleSpeed > 1f)
            {
                emergencyBrakeActive = true;

                // Light steering nudge away from the obstacle (only in Full mode).
                // Use the hysteresis-gated direction so a flipping scan can't
                // yank the wheel the wrong way on first contact.
                if (publishedAvoidDir != 0 && isFullMode)
                {
                    smoothedSteerCorrection = publishedAvoidDir * 0.5f;
                }

                // iter-41 Stage 2a: own channel (was sharing one timestamp with three
                // other sites, which starved the 3 s hard-brake cue entirely).
                if (DateTime.Now.Ticks - lastEmergBrakeAnnounceTicks > 10000000)
                {
                    Speech.Critical("Emergency brake!");
                    lastEmergBrakeAnnounceTicks = DateTime.Now.Ticks;
                    lastThreatCueTicks = DateTime.Now.Ticks;
                lastAssistAnnounceTicks = DateTime.Now.Ticks;
                }
            }
            else if (!obstacleInCriticalZone)
            {
                emergencyBrakeActive = false;
            }

            // Update tracking for next frame
            wasObstacleInBrakeZone = obstacleInCriticalZone;

            bool hasThreat = hasSteerThreat || hasBrakeThreat;

            // Check if we need to auto-teleport back to road
            CheckRoadTeleport(playerVeh, isFullMode, closestSteerTTC);

            // Always activate if we have road guidance or a threat
            // iter-30 P2: also stay active whenever there is meaningful curve/skew brake
            // to apply at speed, even with a degenerate path and ~zero steer guidance. In
            // iter-29 #1 the path collapsed to 1 point, roadSteerCorrection went to ~0, the
            // gate FAILED, the assist deactivated and zeroed brakeArmed -> the brake
            // pipeline was skipped for several frames at 75 mph right before the bend. A
            // fast car with no forward guidance must brake, not coast.
            if (hasThreat
                || (isOnValidRoad && Math.Abs(roadSteerCorrection) > 0.05f)
                || needsHandbrakeTurn
                || currentDriveMode != DriveMode.LaneKeeping
                || (isFullMode && playerVeh.Speed > 15f && curveBrakeRequest > 0.05f))
            {
                steeringAssistActive = true;
                // Pass both steer and brake TTCs to the assist function.
                // publishedAvoidDir is the hysteresis-gated direction computed
                // just above the emergency-brake first-contact block.
                ApplySteeringAssist(playerVeh, closestSteerTTC, closestBrakeTTC, closestBrakeDistance, publishedAvoidDir, isFullMode, steerThreshold, brakeThreshold, hasSteerThreat, hasBrakeThreat, needsHandbrakeTurn, handbrakeSteerDir);
            }
            else if (steeringAssistActive)
            {
                steeringAssistActive = false;
                smoothedSteerCorrection = 0f;
                smoothedRoadCorrection = 0f;
                cachedHandbrakeMagnitude = 0f;
                previousFrameSteer = 0f;
                brakeArmed = false;
                try { outBrakeWarn.Stop(); } catch { }
                // Drop the rolling history so re-enable starts from fail-safe
                // (gates default to legacy behavior until 200 ms accumulates).
                historyHead  = 0;
                historyCount = 0;
            }

            // Record this tick's final state into the rolling-history ring.
            // Single canonical write site — every gate that polls the buffer
            // sees a consistent snapshot of the decisions we just made.
            PushDriveAssistSnapshot(playerVeh, closestSteerTTC, closestBrakeTTC,
                hasSteerThreat, hasBrakeThreat);

            // iter-19 G1: completion stamp — deliberately the LAST statement so an
            // early return or mid-scan exception leaves it stale and the apply-side
            // dead-man releases everything instead of enforcing dead data.
            // ModClock (pause-proof): a pause no longer looks like a dead scan
            // pipeline on resume. All readers compare against ModClock.Ticks.
            lastScanCompletedTicks = ModClock.Ticks;
        }

        /// <summary>
        /// Calculates time to collision based on relative velocity.
        /// Now handles stationary obstacles and uses vehicle size for collision radius.
        /// </summary>
        private float CalculateTTC(Vehicle playerVeh, GTA.Math.Vector3 targetPos, GTA.Math.Vector3 targetVel)
        {
            GTA.Math.Vector3 relPos = targetPos - playerVeh.Position;
            GTA.Math.Vector3 relVel = targetVel - playerVeh.Velocity;

            float distance = relPos.Length();
            if (distance < 0.1f) return 0.1f;

            // Calculate collision radius based on vehicle size
            float collisionRadius = GetVehicleCollisionRadius(playerVeh);

            float closingSpeed = -GTA.Math.Vector3.Dot(GTA.Math.Vector3.Normalize(relPos), relVel);

            // Handle stationary or slowly moving obstacles
            // Only consider them threats if they're DIRECTLY ahead (high dot product) and relatively close
            if (closingSpeed <= 0.5f)
            {
                // Check if obstacle is in our path (ahead or behind depending on direction)
                GTA.Math.Vector3 moveDir = isReversing ? -playerVeh.ForwardVector : playerVeh.ForwardVector;
                float dotToTarget = GTA.Math.Vector3.Dot(moveDir, GTA.Math.Vector3.Normalize(relPos));

                // Static obstacle ahead test. 0.85 ≈ 30° cone. The widened 0.6
                // cone fired for curbs and parked cars off to the side, causing
                // phantom brakes in dense traffic; static side hazards instead
                // feed the wider raycast fan (steering only).
                if (dotToTarget > 0.85f)
                {
                    // Use our own speed as closing speed for stationary obstacles
                    float ourSpeed = playerVeh.Speed;
                    if (ourSpeed > 1f)
                    {
                        closingSpeed = ourSpeed * dotToTarget;
                    }
                    else
                    {
                        // Very slow/stopped - only worry about VERY close stationary obstacles
                        if (distance < 5f) // Reduced from 15f to 5f
                        {
                            return distance / 3f; // Artificial TTC based on distance
                        }
                        return float.MaxValue;
                    }
                }
                else
                {
                    return float.MaxValue; // Not directly in our path
                }
            }

            if (distance < collisionRadius) return 0.1f;
            return (distance - collisionRadius) / closingSpeed;
        }

        /// <summary>
        /// Gets collision radius based on vehicle type.
        /// Larger vehicles need more clearance.
        /// </summary>
        private float GetVehicleCollisionRadius(Vehicle veh)
        {
            // Vehicle class lookup is a pure property read — no exceptions possible.
            switch (veh.ClassType)
            {
                case VehicleClass.Motorcycles:
                case VehicleClass.Cycles:
                    return BASE_COLLISION_RADIUS;
                case VehicleClass.Compacts:
                case VehicleClass.Coupes:
                    return BASE_COLLISION_RADIUS + 0.5f;
                case VehicleClass.Sedans:
                case VehicleClass.Sports:
                case VehicleClass.SportsClassics:
                case VehicleClass.Muscle:
                    return BASE_COLLISION_RADIUS + 1f;
                case VehicleClass.SUVs:
                case VehicleClass.OffRoad:
                case VehicleClass.Vans:
                    return BASE_COLLISION_RADIUS + 1.5f;
                case VehicleClass.Industrial:
                case VehicleClass.Commercial:
                case VehicleClass.Utility:
                    return BASE_COLLISION_RADIUS + 2.5f; // Trucks
                case VehicleClass.Super:
                    return BASE_COLLISION_RADIUS + 1f;   // Wide but low
                default:
                    return BASE_COLLISION_RADIUS + 1f;
            }
        }

        /// <summary>
        /// Determines the direction of a threat relative to the vehicle.
        /// Now properly handles "behind" direction and accounts for reverse driving.
        /// </summary>
        private string GetThreatDirection(Vehicle playerVeh, GTA.Math.Vector3 threatPos)
        {
            GTA.Math.Vector3 toThreat = GTA.Math.Vector3.Normalize(threatPos - playerVeh.Position);
            float dotForward = GTA.Math.Vector3.Dot(playerVeh.ForwardVector, toThreat);
            float dotRight = GTA.Math.Vector3.Dot(playerVeh.RightVector, toThreat);

            // Direction labels stay anchored to the vehicle (== camera) frame even when
            // reversing. The camera doesn't flip when you reverse in GTA V, and blind
            // users navigate by the audible direction — a threat on the physical right
            // side of the car must always be announced as "right" regardless of which
            // way the car is moving. Only the forward axis flips with travel direction
            // so the "ahead" label tracks the direction of motion.
            if (isReversing)
            {
                if (dotForward < -0.5f) return "ahead";   // Direction of travel
                if (dotForward > 0.5f) return "behind";   // Opposite of travel
                if (dotRight > 0.3f) return "right";
                if (dotRight < -0.3f) return "left";
                return "ahead";
            }
            else
            {
                if (dotForward > 0.5f) return "ahead";
                if (dotForward < -0.5f) return "behind";
                if (dotRight > 0.3f) return "right";
                if (dotRight < -0.3f) return "left";
                return "ahead";
            }
        }

        /// <summary>
        /// Determines which direction to steer to avoid a threat
        /// Returns: -1 for left, 0 for straight (brake only), 1 for right
        /// </summary>
        private int GetAvoidDirection(Vehicle playerVeh, GTA.Math.Vector3 threatPos)
        {
            GTA.Math.Vector3 toThreat = GTA.Math.Vector3.Normalize(threatPos - playerVeh.Position);
            float dotRight = GTA.Math.Vector3.Dot(playerVeh.RightVector, toThreat);

            if (dotRight > 0.2f) return -1;  // Threat on right, steer left
            if (dotRight < -0.2f) return 1;  // Threat on left, steer right
            return GetClearerSide(playerVeh, 15f);
        }

        /// <summary>
        /// Uses raycasts to determine which side has more clearance
        /// Returns: -1 for left clearer, 1 for right clearer, 0 for equal
        /// </summary>
        private int GetClearerSide(Vehicle playerVeh, float checkDist)
        {
            GTA.Math.Vector3 startPos = playerVeh.Position + new GTA.Math.Vector3(0, 0, 0.5f);
            GTA.Math.Vector3 forwardVec = playerVeh.ForwardVector;
            GTA.Math.Vector3 rightVec = playerVeh.RightVector;

            GTA.Math.Vector3 leftDir = GTA.Math.Vector3.Normalize(forwardVec - rightVec);
            GTA.Math.Vector3 rightDir = GTA.Math.Vector3.Normalize(forwardVec + rightVec);

            RaycastResult leftRay = World.Raycast(startPos, startPos + leftDir * checkDist,
                IntersectFlags.Everything, playerVeh);
            RaycastResult rightRay = World.Raycast(startPos, startPos + rightDir * checkDist,
                IntersectFlags.Everything, playerVeh);

            float leftClear = leftRay.DidHit ? (leftRay.HitPosition - startPos).Length() : checkDist;   // iter-18 D3
            float rightClear = rightRay.DidHit ? (rightRay.HitPosition - startPos).Length() : checkDist; // iter-18 D3

            if (leftClear > rightClear + 2f) return -1;
            if (rightClear > leftClear + 2f) return 1;
            return 0;
        }

        /// <summary>
        /// NPC AI-inspired lateral offset avoidance.
        /// Instead of binary left/right, calculates the proportional steering magnitude
        /// needed to clear an obstacle based on actual lateral clearance deficit.
        /// Returns -1.0 (full left) to 1.0 (full right), proportional to the offset needed.
        /// </summary>
        private float CalculateLateralAvoidance(Vehicle playerVeh, GTA.Math.Vector3 obstaclePos,
            string obstacleType, float obstacleDistance)
        {
            GTA.Math.Vector3 toObstacle = obstaclePos - playerVeh.Position;
            GTA.Math.Vector3 forward = isReversing ? -playerVeh.ForwardVector : playerVeh.ForwardVector;
            GTA.Math.Vector3 right = isReversing ? -playerVeh.RightVector : playerVeh.RightVector;

            // Calculate the obstacle's lateral position relative to our forward path
            float lateralPos = GTA.Math.Vector3.Dot(right, toObstacle);
            float forwardPos = GTA.Math.Vector3.Dot(forward, toObstacle);

            // If obstacle is behind us, ignore
            if (forwardPos < 0) return 0f;

            // Get the required clearance for this obstacle type (from vehicleaihandlinginfo.meta concepts)
            float requiredClearance = GetLateralClearanceForType(obstacleType)
                                    + GetVehicleCollisionRadius(playerVeh);

            // Calculate how much lateral offset we need. We add a bumper margin so
            // the controller starts nudging *before* clearance bottoms out — the old
            // `>=` cliff produced zero correction at exactly the threshold, which
            // is how the player ended up side-by-side touching mirrors.
            float currentClearance = Math.Abs(lateralPos);
            if (currentClearance > requiredClearance + LATERAL_AVOID_MARGIN)
            {
                return 0f;  // Comfortably clear — no correction needed
            }

            // Calculate the steering correction proportional to the deficit. Deficit
            // now ramps smoothly from `LATERAL_AVOID_MARGIN` outward to `requiredClearance`
            // inward, instead of jumping on/off at the threshold.
            float deficit = (requiredClearance + LATERAL_AVOID_MARGIN) - currentClearance;
            float maxDeficit = requiredClearance + LATERAL_AVOID_MARGIN;
            float urgency = Math.Min(1.0f, deficit / Math.Max(0.01f, maxDeficit));

            // Direction: steer away from obstacle
            float direction = lateralPos >= 0 ? -1f : 1f;

            // Scale by distance: closer obstacles need more urgent correction
            float distanceFactor = Math.Max(0.3f, 1.0f - (obstacleDistance / 30f));
            // Static obstacles (rails/walls) get a much stronger pull. They don't
            // move out of the way, and the user still reported side collisions
            // even with the 1.5× boost — going to 2.0× plus a higher minimum.
            if (obstacleType == "obstacle")
            {
                distanceFactor = Math.Max(0.7f, Math.Min(2.0f, distanceFactor * 2.0f));
            }

            // Verify the chosen side is actually clear
            int clearerSide = GetClearerSide(playerVeh, 15f);
            if (clearerSide != 0 && Math.Sign(direction) != clearerSide)
            {
                // The natural avoid direction is blocked -- use the clearer side instead
                direction = clearerSide;
                urgency *= 0.7f;  // Reduced magnitude since it's a less ideal path
            }

            // ADJACENT-VEHICLE SUPPRESSION MASK: don't steer toward a vehicle that
            // is (or recently was) in our shoulder band. Latch state was set by
            // UpdateAdjacentLatch during the current detection pass.
            if (direction > 0 && adjacentLatchedRight) return 0f; // Can't go right
            if (direction < 0 && adjacentLatchedLeft)  return 0f; // Can't go left

            return direction * urgency * distanceFactor;
        }

        /// <summary>
        /// Gets the lateral clearance distance for a given obstacle type.
        /// Based on vehicleaihandlinginfo.meta fAvoidanceDist parameters.
        /// </summary>
        private float GetLateralClearanceForType(string obstacleType)
        {
            switch (obstacleType)
            {
                case "vehicle": return AVOID_LATERAL_VEHICLE;
                case "pedestrian": return AVOID_LATERAL_PED;
                default: return AVOID_LATERAL_OBJECT;
            }
        }

        /// <summary>
        /// Gets the angle (in degrees) between the vehicle's travel direction and an obstacle.
        /// Used for the swerve-vs-brake decision system.
        /// </summary>
        private float GetAngleToObstacle(Vehicle playerVeh, GTA.Math.Vector3 obstaclePos)
        {
            GTA.Math.Vector3 toObstacle = GTA.Math.Vector3.Normalize(obstaclePos - playerVeh.Position);
            GTA.Math.Vector3 forward = isReversing ? -playerVeh.ForwardVector : playerVeh.ForwardVector;
            float dot = GTA.Math.Vector3.Dot(forward, toObstacle);
            return (float)(Math.Acos(Math.Max(-1f, Math.Min(1f, dot))) * (180.0 / Math.PI));
        }

        /// <summary>
        /// Gets the swerve initiation distance for a given obstacle type.
        /// Based on vehicleaihandlinginfo.meta fSwerveDist parameters.
        /// </summary>
        private float GetSwerveDistForType(string obstacleType)
        {
            switch (obstacleType)
            {
                case "vehicle": return SWERVE_DIST_VEHICLE;
                case "pedestrian": return SWERVE_DIST_PED;
                default: return SWERVE_DIST_OBJECT;
            }
        }

        /// <summary>
        /// Gets the braking initiation distance for a given obstacle type.
        /// Based on vehicleaihandlinginfo.meta fBrakingDist parameters.
        /// </summary>
        private float GetBrakeDistForType(string obstacleType)
        {
            // iter-43 A4: these were fixed regardless of what the player was
            // driving, so a heavy truck began braking at the same distance as a
            // hatchback. BASE_COLLISION_RADIUS already had a "+2.5 // Trucks"
            // bucket, so size-awareness was precedent here — braking just never
            // got it. VehicleBrakeScale can only ever brake EARLIER (clamped >=1).
            return GetBrakeDistForTypeRaw(obstacleType)
                * VehicleBrakeScale(cachedGeometryVehicle);
        }

        private float GetBrakeDistForTypeRaw(string obstacleType)
        {
            switch (obstacleType)
            {
                case "vehicle": return BRAKE_DIST_VEHICLE;
                case "pedestrian": return BRAKE_DIST_PED;
                default: return BRAKE_DIST_OBJECT;
            }
        }

        /// <summary>
        /// Checks if a position is on the road surface using the GTA V native IS_POINT_ON_ROAD.
        /// Used to filter out parked vehicles on shoulders/sidewalks.
        /// </summary>
        private bool IsPositionOnRoad(GTA.Math.Vector3 position)
        {
            // IS_POINT_ON_ROAD (0x125BF4ABFC536B09) is a pure read native — it can't fail
            // in normal execution. The previous try/catch defaulted to "true" on failure
            // (treat as threat), so removing it preserves identical observable behavior
            // when the native does return something sensible.
            return Function.Call<bool>((Hash)0x125BF4ABFC536B09,
                position.X, position.Y, position.Z, 0);
        }

        /// <summary>
        /// Iter-12 Patch Q: returns true if the position is on a named street.
        /// GET_STREET_NAME_AT_COORD writes a street-name hash and a crossing
        /// hash; the street-name hash is non-zero only on named roads (paved
        /// or dirt with a name). Pure off-road (open desert, fields, large
        /// parking lots, construction zones) all return streetHash=0. This
        /// complements IS_POINT_ON_ROAD which returns true for any nav-graph
        /// node including unnamed dirt nodes in Sandy Shores.
        /// </summary>
        private bool IsOnNamedStreet(GTA.Math.Vector3 position)
        {
            OutputArgument outStreet   = new OutputArgument();
            OutputArgument outCrossing = new OutputArgument();
            // GET_STREET_NAME_AT_COORD = 0x2EB41072B4C1E4C0
            Function.Call((Hash)0x2EB41072B4C1E4C0,
                position.X, position.Y, position.Z, outStreet, outCrossing);
            return outStreet.GetResult<uint>() != 0;
        }

        // ---- C1 (nodeStreamGuardV2): path-node streaming guard ----
        // Every GET_NTH_CLOSEST_VEHICLE_NODE_* call in this file returns FALSE when
        // the path-node grid for that area is not streamed in (after a teleport,
        // fast travel, or near the map edge). That is INDISTINGUISHABLE from "there
        // is no road here" — and the second reading is what the off-road/teleport
        // and polyline paths act on. This guard separates the two so a streaming
        // gap stops being silently misread as open desert.
        //
        // Cached: ARE_NODES_LOADED_FOR_AREA is cheap but it is consulted from four
        // call sites, some inside n=1..10 loops. One evaluation per ~250 ms per
        // coarse position is plenty — node streaming does not flicker at frame rate.
        private long nodeLoadCheckStamp = 0;
        private GTA.Math.Vector3 nodeLoadCheckPos = GTA.Math.Vector3.Zero;
        private bool nodeLoadCheckResult = true;
        private long lastNodesNotLoadedLogTicks = 0;
        /// <summary>C1: true when the last guarded node query was skipped because
        /// path nodes were not streamed. Distinct from "query ran and found
        /// nothing" — callers must NOT treat this as off-road.</summary>
        private bool lastNodeQueryNodesUnloaded = false;

        /// <summary>
        /// C1 (nodeStreamGuardV2): are vehicle path nodes streamed in around this
        /// position? Returns TRUE when the gate is off, so every call site keeps its
        /// pre-C1 behavior until the gate is switched on in-game.
        /// </summary>
        private bool ArePathNodesLoadedAt(GTA.Math.Vector3 pos, string site)
        {
            if (getSetting("nodeStreamGuardV2") != 1) return true;
            GateReach("nodeStreamGuardV2");

            long now = ModClock.Ticks;
            float dx = pos.X - nodeLoadCheckPos.X, dy = pos.Y - nodeLoadCheckPos.Y;
            if (nodeLoadCheckStamp != 0
                && now - nodeLoadCheckStamp < 2500000L      // 250 ms
                && dx * dx + dy * dy < 400f)                // and within 20 m
                return nodeLoadCheckResult;

            nodeLoadCheckStamp = now;
            nodeLoadCheckPos = pos;
            // ARE_NODES_LOADED_FOR_AREA = 0xF7B79A50B905A30D (x1,y1,x2,y2).
            // A 100 m box comfortably covers every node query in this file: the
            // widest is BuildPathPolylineRaw's PATH_POLYLINE_HOPS * 12 m probe.
            const float HALF = 50f;
            nodeLoadCheckResult = Function.Call<bool>((Hash)0xF7B79A50B905A30D,
                pos.X - HALF, pos.Y - HALF, pos.X + HALF, pos.Y + HALF);

            if (!nodeLoadCheckResult)
            {
                GateFire("nodeStreamGuardV2");
                // Ask the engine to stream them for the next frame. Best-effort —
                // this does not make the current query work, it shortens the gap.
                // REQUEST_PATH_NODES_IN_AREA_THIS_FRAME = 0x07FB139B592FA687
                Function.Call((Hash)0x07FB139B592FA687,
                    pos.X - HALF, pos.Y - HALF, pos.X + HALF, pos.Y + HALF);

                if (driveLogger != null && driveLogger.IsRunning
                    && now - lastNodesNotLoadedLogTicks > 20000000L) // 2 s
                {
                    lastNodesNotLoadedLogTicks = now;
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] EVENT nodes-not-loaded: site=" + site
                        + " pos=" + FmtV(pos));
                }
            }
            return nodeLoadCheckResult;
        }

        // ---- B1/B2 (roadBoundaryV2 / groundNormalV2): measured road geometry ----
        // Lateral targeting has always run on a LANE_WIDTH_M constant plus a
        // shoulder-extra from paths.xml, and the curve-brake chain has no gravity
        // term at all. The engine can report both directly. BOTH ARE DARK: sampled
        // and logged, consumed by nothing, until a session shows the readings are
        // sane. Promoting them before that would bet lane-keeping on an unvalidated
        // native.
        private bool  roadEdgeValid = false;
        private float roadEdgeLeftM = 0f, roadEdgeRightM = 0f, roadWidthMeasM = 0f;
        private bool  groundNormValid = false;
        private float groundGradeDeg = 0f;     // + = uphill along heading
        private float groundCamberDeg = 0f;    // + = ground rises to the right
        private bool  groundAheadValid = false;
        private float groundGradeAheadDeg = 0f;

        // ====================================================================
        // iter-49 A1/A2: THE ENGINE'S OWN ROAD MODEL
        // ====================================================================
        // Everything the lateral model knows about lane counts, road width and
        // junctions has come from an offline paths.xml/junctions.xml dump plus a
        // hand-picked LANE_WIDTH_M. The engine will answer all of it directly, at
        // any coordinate, with no shipped data — which is what taxiservice.c does
        // before it picks a drop-off point. Both samplers are DARK: they compute
        // and log, and nothing reads them, until a session says the readings are
        // sane. The iter-42 roadBoundaryV2/groundNormalV2 pair set that precedent
        // and it is the only reason those two could be trusted afterwards.

        // ---- eVehicleNodeProperties, from the engine's own enum ----
        private const int VNP_OFF_ROAD           = 1 << 0;
        private const int VNP_ON_PLAYERS_ROAD    = 1 << 1;
        private const int VNP_NO_BIG_VEHICLES    = 1 << 2;
        private const int VNP_SWITCHED_OFF       = 1 << 3;
        private const int VNP_TUNNEL_OR_INTERIOR = 1 << 4;
        private const int VNP_LEADS_TO_DEAD_END  = 1 << 5;
        private const int VNP_HIGHWAY            = 1 << 6;
        private const int VNP_JUNCTION           = 1 << 7;
        private const int VNP_TRAFFIC_LIGHT      = 1 << 8;
        private const int VNP_GIVE_WAY           = 1 << 9;
        private const int VNP_WATER              = 1 << 10;

        // ---- eGetClosestNodeFlags, ditto ----
        // The mod has passed 1 at every node-query site since the first iteration.
        // That is not "default": it explicitly opts INTO switched-off nodes —
        // driveways, service spurs, disabled paths — which is the most plausible
        // mechanical source of the parallel-arm snap iter-36 had to clamp.
        private const int GCNF_INCLUDE_SWITCHED_OFF_NODES = 1;
        private const int GCNF_IGNORE_SLIPLANES           = 4;
        private const int GCNF_IGNORE_SWITCHED_OFF_DEADENDS = 8;
        private const int GCNF_FAVOUR_FACING              = 512;
        // Path/lane sources want real, connected, traffic-bearing road.
        private const int NODEFLAGS_PATH = GCNF_IGNORE_SLIPLANES | GCNF_IGNORE_SWITCHED_OFF_DEADENDS;
        // Recovery targets deliberately keep the switched-off nodes: a driveway is
        // a perfectly good place to be pushed back onto when you are in a ditch.
        private const int NODEFLAGS_RECOVERY = GCNF_INCLUDE_SWITCHED_OFF_NODES;

        // R*'s own per-lane width, read off taxiservice.c's drop-off maths
        // (4.2 * laneCount, halved on a one-way). The mod's LANE_WIDTH_M is 5.3.
        private const float VANILLA_LANE_WIDTH_M = 4.2f;

        /// <summary>
        /// iter-49 A3. Picks the node-query flags for a DRIVE-ASSIST query. Off, it
        /// returns the legacy 1 this file has passed since the first iteration;
        /// on, the purpose-appropriate set. Counted so the census can show how
        /// often the correction actually changed the argument.
        /// </summary>
        private int NodeFlagsFor(int corrected)
        {
            GateReach("nodeQueryArgsV2");
            if (getSetting("nodeQueryArgsV2") != 1) return GCNF_INCLUDE_SWITCHED_OFF_NODES;
            if (corrected != GCNF_INCLUDE_SWITCHED_OFF_NODES) GateFire("nodeQueryArgsV2");
            return corrected;
        }

        /// <summary>
        /// iter-49 A3. nthClosest is documented 1-based and every vanilla call
        /// passes at least 1, but eleven sites in this file pass 0. It most likely
        /// clamps — "most likely" is not evidence, so the correction is gated.
        /// Deliberately NOT counted: the sites that pass 0 are butler/convoy spawn
        /// points, and letting them drive a drive-assist denominator is the same
        /// mistake the iter-44 comment warns about for the riot gates.
        /// </summary>
        private int NodeNth(int legacy)
        {
            return getSetting("nodeQueryArgsV2") == 1 ? Math.Max(1, legacy) : legacy;
        }

        /// <summary>
        /// iter-49 A3. taxiservice.c's Z fallback for when a node query bottoms out:
        /// the approximate floor height over a small box, which disambiguates a
        /// freeway deck from the surface street under it far better than the flat
        /// PATH_NODE_MAX_Z_DELTA window. Returns false when the engine has no
        /// answer, so callers keep their existing behaviour rather than adopting a 0.
        /// </summary>
        private bool TryGetApproxFloorZ(GTA.Math.Vector3 pos, out float floorZ)
        {
            floorZ = 0f;
            if (getSetting("nodeQueryArgsV2") != 1) return false;
            try
            {
                float z = Function.Call<float>(Hash.GET_APPROX_FLOOR_FOR_AREA,
                    pos.X - 2f, pos.Y - 2f, pos.X + 2f, pos.Y + 2f);
                // Vanilla treats <= 1.0 as "no answer" at this call site.
                if (z <= 1f) return false;
                floorZ = z;
                return true;
            }
            catch { return false; }
        }

        // A1 GET_CLOSEST_ROAD readings ("road facts").
        private bool  roadFactsValid = false;
        private int   rfLanesFwd = 0, rfLanesBwd = 0;
        private float rfMedianWidth = 0f;        // documented: gap BETWEEN the two lane groups
        private GTA.Math.Vector3 rfSrcNode = GTA.Math.Vector3.Zero;
        private GTA.Math.Vector3 rfTgtNode = GTA.Math.Vector3.Zero;
        private float rfPolyDivergenceM = -1f;   // how far the engine edge sits from our lead segment
        // The lane count the engine hands back from the node query itself, which
        // every one of the 14 call sites has allocated and thrown away.
        private int   rfNodeLanes = 0;
        private bool  rfNodeIdValid = false, rfNodeSwitchedOff = false, rfNodeGpsAllowed = false;
        private float rfTravelDistM = -1f;       // road-network distance to the waypoint
        private long  lastRoadFactsLogTicks = 0;
        private long  lastTravelDistTicks = 0;
        private long  lastLaneWidthDegradedTicks = 0;

        // A2 GET_VEHICLE_NODE_PROPERTIES readings.
        private bool  nodePropsValid = false;
        private int   npFlags = 0, npDensity = 0;
        private bool  nodePropsAheadValid = false;
        private int   npFlagsAhead = 0;
        private float npAheadDistM = -1f;        // how far ahead npFlagsAhead was sampled
        private long  lastNodePropsLogTicks = 0;

        /// <summary>Decode a node-property bitfield into the engine's own names, for
        /// the log. Unknown bits above the documented enum are surfaced as a raw
        /// remainder rather than dropped — a bit we cannot name is exactly the kind
        /// of thing a session should show us.</summary>
        private static string NodePropNames(int flags)
        {
            if (flags == 0) return "none";
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            if ((flags & VNP_OFF_ROAD) != 0) sb.Append("offroad|");
            if ((flags & VNP_ON_PLAYERS_ROAD) != 0) sb.Append("playersroad|");
            if ((flags & VNP_NO_BIG_VEHICLES) != 0) sb.Append("nobig|");
            if ((flags & VNP_SWITCHED_OFF) != 0) sb.Append("switchedoff|");
            if ((flags & VNP_TUNNEL_OR_INTERIOR) != 0) sb.Append("tunnel|");
            if ((flags & VNP_LEADS_TO_DEAD_END) != 0) sb.Append("deadend|");
            if ((flags & VNP_HIGHWAY) != 0) sb.Append("highway|");
            if ((flags & VNP_JUNCTION) != 0) sb.Append("junction|");
            if ((flags & VNP_TRAFFIC_LIGHT) != 0) sb.Append("trafficlight|");
            if ((flags & VNP_GIVE_WAY) != 0) sb.Append("giveway|");
            if ((flags & VNP_WATER) != 0) sb.Append("water|");
            int known = VNP_OFF_ROAD | VNP_ON_PLAYERS_ROAD | VNP_NO_BIG_VEHICLES
                | VNP_SWITCHED_OFF | VNP_TUNNEL_OR_INTERIOR | VNP_LEADS_TO_DEAD_END
                | VNP_HIGHWAY | VNP_JUNCTION | VNP_TRAFFIC_LIGHT | VNP_GIVE_WAY | VNP_WATER;
            int rest = flags & ~known;
            if (rest != 0) sb.Append("raw0x").Append(rest.ToString("X")).Append('|');
            if (sb.Length > 0) sb.Length--;   // trailing bar
            return sb.ToString();
        }

        /// <summary>
        /// A2: node density + property flags at a coord. Pure read, no side effects.
        /// GET_VEHICLE_NODE_PROPERTIES returns false when the node is not streamed
        /// in, which is a DIFFERENT answer from "flags are zero" — callers must not
        /// conflate them.
        /// </summary>
        private bool TryGetNodeProperties(GTA.Math.Vector3 pos, out int density, out int flags)
        {
            density = 0; flags = 0;
            try
            {
                OutputArgument oD = new OutputArgument();
                OutputArgument oF = new OutputArgument();
                bool ok = Function.Call<bool>(Hash.GET_VEHICLE_NODE_PROPERTIES,
                    pos.X, pos.Y, pos.Z, oD, oF);
                if (!ok) return false;
                density = oD.GetResult<int>();
                flags = oF.GetResult<int>();
                // Density is documented 0-15. Anything outside that is the SHVDN
                // OutputArgument garbage-read that produced ~30% farHits on the
                // shapecasts (iter-43 G3) — reject the whole sample rather than
                // let a garbage flags word drive a junction announcement.
                if (density < 0 || density > 15) return false;
                return true;
            }
            catch { return false; }
        }

        /// <summary>
        /// A1: the engine's own road edge at a coord — the two endpoints of a road
        /// segment plus its forward/backward lane split and the median gap between
        /// them. This is the runtime equivalent of the shipped NodeGraph link data,
        /// and R* calls it with (minEdgeLength 1.0, minLanes 1, onlyMajorRoads true).
        ///
        /// NOTE the `width` contract: it is the gap in the MIDDLE of the road
        /// between the forward and backward lane groups — a median, not a
        /// carriageway width. That is the same thing the iter-32 width study
        /// concluded about paths.xml, from the other direction.
        /// </summary>
        private bool TryGetClosestRoad(GTA.Math.Vector3 pos, bool majorOnly,
            out GTA.Math.Vector3 srcNode, out GTA.Math.Vector3 tgtNode,
            out int lanesFwd, out int lanesBwd, out float width)
        {
            srcNode = GTA.Math.Vector3.Zero; tgtNode = GTA.Math.Vector3.Zero;
            lanesFwd = 0; lanesBwd = 0; width = 0f;
            try
            {
                OutputArgument oSrc = new OutputArgument();
                OutputArgument oTgt = new OutputArgument();
                OutputArgument oLf = new OutputArgument();
                OutputArgument oLb = new OutputArgument();
                OutputArgument oW = new OutputArgument();
                bool ok = Function.Call<bool>(Hash.GET_CLOSEST_ROAD,
                    pos.X, pos.Y, pos.Z, 1f, 1, oSrc, oTgt, oLf, oLb, oW, majorOnly);
                if (!ok) return false;
                srcNode = oSrc.GetResult<GTA.Math.Vector3>();
                tgtNode = oTgt.GetResult<GTA.Math.Vector3>();
                lanesFwd = oLf.GetResult<int>();
                lanesBwd = oLb.GetResult<int>();
                width = oW.GetResult<float>();
                // Same garbage-read guard. A road with 0 lanes in both directions,
                // or 20 lanes, or a 200 m median, is a failed read — and a failed
                // read that reaches the lane-offset maths steers the car.
                if (lanesFwd < 0 || lanesBwd < 0 || lanesFwd + lanesBwd <= 0
                    || lanesFwd > 12 || lanesBwd > 12) return false;
                if (width < -1f || width > 60f) return false;
                return true;
            }
            catch { return false; }
        }

        /// <summary>
        /// iter-49 A1/A2 sampler. Runs inside the throttled scan next to the
        /// iter-42 dark pair. Writes only its own fields.
        /// </summary>
        private void SampleEngineRoadModel(Vehicle veh, GTA.Math.Vector3 flatFwd)
        {
            roadFactsValid = false;
            nodePropsValid = false;
            nodePropsAheadValid = false;
            rfPolyDivergenceM = -1f;
            rfNodeIdValid = false; rfNodeSwitchedOff = false; rfNodeGpsAllowed = false;
            rfNodeLanes = 0;
            if (veh == null || !veh.Exists()) return;
            GTA.Math.Vector3 p = veh.Position;

            bool wantFacts = getSetting("roadFactsV2") == 1;
            bool wantProps = getSetting("nodePropsV2") == 1;
            if (!wantFacts && !wantProps) return;

            // One streaming guard for both samplers: on a path-node gap every query
            // below returns false, and "the nodes are not here" must never be logged
            // as "there is no road here" (iter-42 C1).
            if (!ArePathNodesLoadedAt(p, "engineRoadModel")) return;

            if (wantFacts)
            {
                GateReach("roadFactsV2");
                GTA.Math.Vector3 src, tgt;
                int lf, lb; float w;
                if (TryGetClosestRoad(p, true, out src, out tgt, out lf, out lb, out w))
                {
                    rfSrcNode = src; rfTgtNode = tgt;
                    rfLanesFwd = lf; rfLanesBwd = lb; rfMedianWidth = w;
                    roadFactsValid = true;
                    GateFire("roadFactsV2");
                    // Cross-check 3: how far is the engine's own road edge from the
                    // lead segment we are steering against? A large number here IS
                    // the parallel-road snap, measured directly instead of inferred
                    // from a lat that jumped.
                    if (pathPolyline.Count >= 2)
                    {
                        GTA.Math.Vector3 mid = new GTA.Math.Vector3(
                            (src.X + tgt.X) * 0.5f, (src.Y + tgt.Y) * 0.5f, (src.Z + tgt.Z) * 0.5f);
                        rfPolyDivergenceM = DistToFirstSeg2D(mid, pathPolyline);
                    }
                }

                // The node-id chain R* runs before trusting any node, and the lane
                // count the mod already asks for and discards.
                try
                {
                    OutputArgument oPos = new OutputArgument();
                    OutputArgument oHd = new OutputArgument();
                    int nodeId = Function.Call<int>(Hash.GET_NTH_CLOSEST_VEHICLE_NODE_ID_WITH_HEADING,
                        p.X, p.Y, p.Z, 1, oPos, oHd, NODEFLAGS_PATH, 3.0f, 0f);
                    rfNodeIdValid = Function.Call<bool>(Hash.IS_VEHICLE_NODE_ID_VALID, nodeId);
                    if (rfNodeIdValid)
                    {
                        rfNodeSwitchedOff = Function.Call<bool>(Hash.GET_VEHICLE_NODE_IS_SWITCHED_OFF, nodeId);
                        rfNodeGpsAllowed = Function.Call<bool>(Hash.GET_VEHICLE_NODE_IS_GPS_ALLOWED, nodeId);
                    }
                }
                catch { rfNodeIdValid = false; }

                try
                {
                    OutputArgument oP = new OutputArgument();
                    OutputArgument oH = new OutputArgument();
                    OutputArgument oL = new OutputArgument();
                    if (Function.Call<bool>(Hash.GET_NTH_CLOSEST_VEHICLE_NODE_WITH_HEADING,
                            p.X, p.Y, p.Z, 1, oP, oH, oL, NODEFLAGS_PATH, 3.0f, 0f))
                        rfNodeLanes = oL.GetResult<int>();
                }
                catch { rfNodeLanes = 0; }

                // Road-network distance to the destination, at ~1 Hz. 100000.0 is the
                // documented failure sentinel (not all path nodes loaded), so it is
                // recorded as invalid rather than announced as a distance.
                if (cachedWaypointPos != GTA.Math.Vector3.Zero
                    && DateTime.Now.Ticks - lastTravelDistTicks > 10000000L)
                {
                    lastTravelDistTicks = DateTime.Now.Ticks;
                    try
                    {
                        float td = Function.Call<float>(Hash.CALCULATE_TRAVEL_DISTANCE_BETWEEN_POINTS,
                            p.X, p.Y, p.Z,
                            cachedWaypointPos.X, cachedWaypointPos.Y, cachedWaypointPos.Z);
                        rfTravelDistM = (td >= 99999f || td < 0f) ? -1f : td;
                    }
                    catch { rfTravelDistM = -1f; }
                }
            }

            if (wantProps)
            {
                GateReach("nodePropsV2");
                int d, f;
                if (TryGetNodeProperties(p, out d, out f))
                {
                    npDensity = d; npFlags = f;
                    nodePropsValid = true;
                    GateFire("nodePropsV2");
                }
                // Sample ahead too — a junction the car is standing on is not news,
                // a junction 40 m away is. Prefer the steering polyline so the probe
                // follows the road rather than the bonnet.
                GTA.Math.Vector3 ahead = (steerPolyline != null && steerPolyline.Count > 2)
                    ? steerPolyline[2] : p + flatFwd * 30f;
                npAheadDistM = Dist2D(p, ahead);
                int dA, fA;
                if (TryGetNodeProperties(ahead, out dA, out fA))
                {
                    npFlagsAhead = fA;
                    nodePropsAheadValid = true;
                }
            }

            LogEngineRoadModel(veh);
        }

        /// <summary>~1 Hz road-model telemetry. Two EVENT kinds rather than one so
        /// the triage tool can histogram lane counts separately from hazard flags,
        /// and so one gate being off does not blank the other's line.</summary>
        private void LogEngineRoadModel(Vehicle veh)
        {
            if (driveLogger == null || !driveLogger.IsRunning) return;
            long now = DateTime.Now.Ticks;

            if (getSetting("roadFactsV2") == 1 && now - lastRoadFactsLogTicks > 10000000L)
            {
                lastRoadFactsLogTicks = now;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT road-facts:"
                    + " ok=" + roadFactsValid
                    + " lanesFwd=" + rfLanesFwd
                    + " lanesBwd=" + rfLanesBwd
                    + " medianW=" + rfMedianWidth.ToString("F2")
                    + " nodeLanes=" + rfNodeLanes
                    + " nodeIdOk=" + rfNodeIdValid
                    + " switchedOff=" + rfNodeSwitchedOff
                    + " gpsAllowed=" + rfNodeGpsAllowed
                    // The shipped-graph counterpart, on the same line, so the
                    // agreement question is answerable without a join.
                    + " graphFwd=" + lastLaneOffsetFwd
                    + " graphBwd=" + lastLaneOffsetBwd
                    + " graphWidthExtra=" + lastLaneWidthExtraM
                    + " polyDiverge=" + rfPolyDivergenceM.ToString("F1")
                    + " travelDist=" + rfTravelDistM.ToString("F0")
                    + " straightDist=" + (cachedWaypointPos != GTA.Math.Vector3.Zero
                        ? Dist2D(veh.Position, cachedWaypointPos).ToString("F0") : "-")
                    + " src=" + FmtV(rfSrcNode)
                    + " tgt=" + FmtV(rfTgtNode)
                    + " spd=" + veh.Speed.ToString("F1"));
            }

            if (getSetting("nodePropsV2") == 1 && now - lastNodePropsLogTicks > 10000000L)
            {
                lastNodePropsLogTicks = now;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT node-props:"
                    + " ok=" + nodePropsValid
                    + " density=" + npDensity
                    + " flags=" + (nodePropsValid ? NodePropNames(npFlags) : "-")
                    + " aheadOk=" + nodePropsAheadValid
                    + " aheadDist=" + npAheadDistM.ToString("F0")
                    + " aheadFlags=" + (nodePropsAheadValid ? NodePropNames(npFlagsAhead) : "-")
                    // The three existing detectors this is meant to cross-check.
                    // Recording them on the SAME line is what makes the coverage
                    // gap a one-line read instead of a correlation exercise.
                    + " onRoadNative=" + IsPositionOnRoad(veh.Position)
                    + " junctionArmed=" + junctionArmed
                    + " junctionFromNode=" + junctionFromNode
                    + " junctionDist=" + junctionDistM.ToString("F0")
                    + " genDirDist=" + genDistToJunction.ToString("F0")
                    + " street=" + World.GetStreetName(veh.Position));
            }
        }

        // ====================================================================
        // iter-49 B1: KERB GEOMETRY (taxilauncher.c's correct-side picker)
        // ====================================================================
        // The mod has never had a concept of "which side of the road am I meant
        // to stop on". Recovery aims at the nearest node within 45 degrees, and
        // auto-drive parks on the destination coordinate whatever is there.
        // Vanilla solves this in about twenty lines: ask for BOTH kerbs, take the
        // perpendicular of the near one, dot it against the approach direction,
        // and if the sign is wrong use the other kerb and turn the heading round.
        //
        // The `side` parameter of GET_POSITION_BY_SIDE_OF_ROAD is UNDOCUMENTED.
        // R* passes 0, 1 and -1. All three are sampled and logged here so the
        // convention is settled from a session, the same way the eMenuPref shift
        // and the SteeringAngle sign were settled — not guessed.
        private bool  kerbValid = false;
        private GTA.Math.Vector3 kerbSide0 = GTA.Math.Vector3.Zero;
        private GTA.Math.Vector3 kerbSide1 = GTA.Math.Vector3.Zero;
        private GTA.Math.Vector3 kerbSideNeg = GTA.Math.Vector3.Zero;
        private bool  kerbSide0Ok = false, kerbSide1Ok = false, kerbSideNegOk = false;
        private GTA.Math.Vector3 kerbNear = GTA.Math.Vector3.Zero;  // the one on OUR side
        private float kerbNearHeading = 0f;
        private bool  kerbNearFlipped = false;   // true = we took the far kerb + 180 deg
        private float kerbNearDistM = -1f;
        private long  lastKerbLogTicks = 0;

        /// <summary>One side-of-road probe. Pure read.</summary>
        private bool TryPositionBySideOfRoad(GTA.Math.Vector3 pos, int side,
            out GTA.Math.Vector3 outPos)
        {
            outPos = GTA.Math.Vector3.Zero;
            try
            {
                OutputArgument o = new OutputArgument();
                bool ok = Function.Call<bool>(Hash.GET_POSITION_BY_SIDE_OF_ROAD,
                    pos.X, pos.Y, pos.Z, side, o);
                if (!ok) return false;
                outPos = o.GetResult<GTA.Math.Vector3>();
                // A kerb 80 m from its own road node is a failed read, not a kerb.
                if (Dist2D(pos, outPos) > 80f) return false;
                return outPos.LengthSquared() > 1f;
            }
            catch { return false; }
        }

        /// <summary>
        /// The vanilla picker, ported from taxilauncher.c. Given a road node and the
        /// direction we are ARRIVING from, returns the kerb point on our own side of
        /// the road plus the heading to sit at, so the car never has to cross the
        /// oncoming lane to stop. Returns false when the engine will not give us two
        /// kerbs and has no single-sided fallback either.
        /// </summary>
        private bool TryResolveNearKerb(GTA.Math.Vector3 nodePos, GTA.Math.Vector3 approachFrom,
            float roadHeading, out GTA.Math.Vector3 kerb, out float heading, out bool flipped)
        {
            kerb = GTA.Math.Vector3.Zero;
            heading = roadHeading;
            flipped = false;
            GTA.Math.Vector3 s0, s1;
            bool ok0 = TryPositionBySideOfRoad(nodePos, 0, out s0);
            bool ok1 = TryPositionBySideOfRoad(nodePos, 1, out s1);
            if (ok0 && ok1)
            {
                // perp = left-rotate of (side0 - node); its sign against the
                // approach vector says which kerb we reach without crossing.
                float ax = s0.X - nodePos.X, ay = s0.Y - nodePos.Y;
                float px = -ay, py = ax;
                float qx = approachFrom.X - nodePos.X, qy = approachFrom.Y - nodePos.Y;
                if (px * qx + py * qy < 0f)
                {
                    kerb = s0;
                }
                else
                {
                    kerb = s1;
                    heading = roadHeading + 180f;
                    flipped = true;
                }
                while (heading >= 360f) heading -= 360f;
                while (heading < 0f) heading += 360f;
                return true;
            }
            // Vanilla's own fallback: side -1 returns a single point with no choice.
            GTA.Math.Vector3 sN;
            if (TryPositionBySideOfRoad(nodePos, -1, out sN))
            {
                kerb = sN;
                return true;
            }
            return false;
        }

        /// <summary>
        /// iter-49 B1 sampler. Dark: computes the kerbs and the near-side choice
        /// every scan and logs them, consuming nothing. pullOverAssist is what
        /// turns this into behaviour, in its own session.
        /// </summary>
        private void SampleKerbGeometry(Vehicle veh)
        {
            kerbValid = false;
            kerbSide0Ok = kerbSide1Ok = kerbSideNegOk = false;
            kerbNearDistM = -1f;
            if (veh == null || !veh.Exists()) return;
            if (getSetting("kerbGeometryV2") != 1) return;
            GateReach("kerbGeometryV2");
            GTA.Math.Vector3 p = veh.Position;
            if (!ArePathNodesLoadedAt(p, "kerbGeometry")) return;

            // Anchor on a real node rather than the car: a kerb query from the
            // middle of a junction, or from a car half on the pavement, has no
            // defined answer.
            GTA.Math.Vector3 nodePos;
            float nodeHeading;
            if (!TryGetNodeWithHeading(p, 1, NODEFLAGS_PATH, out nodePos, out nodeHeading)) return;

            kerbSide0Ok = TryPositionBySideOfRoad(nodePos, 0, out kerbSide0);
            kerbSide1Ok = TryPositionBySideOfRoad(nodePos, 1, out kerbSide1);
            kerbSideNegOk = TryPositionBySideOfRoad(nodePos, -1, out kerbSideNeg);

            // "Approaching from" = behind the car, so the picker chooses the kerb
            // on the side we are already travelling along.
            GTA.Math.Vector3 approachFrom = p - veh.ForwardVector * 10f;
            GTA.Math.Vector3 k; float kh; bool flip;
            if (TryResolveNearKerb(nodePos, approachFrom, nodeHeading, out k, out kh, out flip))
            {
                kerbNear = k;
                kerbNearHeading = kh;
                kerbNearFlipped = flip;
                kerbNearDistM = Dist2D(p, k);
                kerbValid = true;
                GateFire("kerbGeometryV2");
            }

            if (driveLogger != null && driveLogger.IsRunning
                && DateTime.Now.Ticks - lastKerbLogTicks > 10000000L)
            {
                lastKerbLogTicks = DateTime.Now.Ticks;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT kerb:"
                    + " ok=" + kerbValid
                    + " node=" + FmtV(nodePos)
                    + " nodeHd=" + nodeHeading.ToString("F0")
                    + " vehHd=" + veh.Heading.ToString("F0")
                    + " s0ok=" + kerbSide0Ok + " s0=" + FmtV(kerbSide0)
                    + " s0d=" + (kerbSide0Ok ? Dist2D(nodePos, kerbSide0).ToString("F1") : "-")
                    + " s1ok=" + kerbSide1Ok + " s1=" + FmtV(kerbSide1)
                    + " s1d=" + (kerbSide1Ok ? Dist2D(nodePos, kerbSide1).ToString("F1") : "-")
                    + " sNok=" + kerbSideNegOk + " sN=" + FmtV(kerbSideNeg)
                    + " near=" + FmtV(kerbNear)
                    + " nearHd=" + kerbNearHeading.ToString("F0")
                    + " flipped=" + kerbNearFlipped
                    + " nearDist=" + kerbNearDistM.ToString("F1")
                    // The half-carriageway this implies, for the laneWidthV2
                    // cross-check against 4.2 m/lane and the shipped graph.
                    + " halfCarriageway=" + (kerbSide0Ok && kerbSide1Ok
                        ? (Dist2D(kerbSide0, kerbSide1) * 0.5f).ToString("F1") : "-")
                    + " lanesFwd=" + rfLanesFwd + " lanesBwd=" + rfLanesBwd);
            }
        }

        // ====================================================================
        // iter-49 C1/C2: THE ENGINE'S OWN STUCK DETECTOR
        // ====================================================================
        // UpdateStuckRecovery arms on hand-built heuristics — skew angle, planar
        // no-progress, blocked-ahead from cached threat positions, throttle intent.
        // Those took 20+ iterations to tune and still miss cases. The engine has
        // maintained four stuck timers the whole time and the mod has never read
        // one. taxiservice.c aborts its entire fare on:
        //
        //   IS_VEHICLE_STUCK_TIMER_UP(veh, 2, 30000) || (veh, 3, 30000)
        //   || (veh, 0, 7000) || (veh, 1, 7000)
        //
        // Two tiers: a fast pair at 7 s and a slow pair at 30 s. What the four
        // types actually MEAN is undocumented, so C1 samples all four at both
        // thresholds and logs them beside the mod's own verdict. One session tells
        // us both the type semantics and whether the engine beats the heuristics.
        private const int STUCK_TYPES = 4;
        private const int STUCK_MS_FAST = 7000;    // R*'s threshold for types 0/1
        private const int STUCK_MS_SLOW = 30000;   // R*'s threshold for types 2/3
        // A short probe too: R*'s numbers are tuned for abandoning a taxi fare, not
        // for helping a blind driver who is already wedged and pressing F1.
        private const int STUCK_MS_PROBE = 2500;
        private int  engineStuckMaskFast = 0;   // bit i = type i up at STUCK_MS_FAST
        private int  engineStuckMaskSlow = 0;
        private int  engineStuckMaskProbe = 0;
        private bool engineStuckValid = false;
        private long lastEngineStuckLogTicks = 0;
        private long engineStuckFirstSeenTicks = 0;

        /// <summary>Poll all four engine stuck timers at one threshold. Returns a
        /// bitmask so a single int carries which types fired.</summary>
        private int PollEngineStuckMask(Vehicle veh, int ms)
        {
            int mask = 0;
            try
            {
                for (int t = 0; t < STUCK_TYPES; t++)
                    if (Function.Call<bool>(Hash.IS_VEHICLE_STUCK_TIMER_UP, veh, t, ms))
                        mask |= 1 << t;
            }
            catch { return 0; }
            return mask;
        }

        /// <summary>
        /// iter-49 C1. Sampled from the scan so it covers Assistive mode too —
        /// UpdateStuckRecovery early-returns outside Full mode, and a detector that
        /// only observes the cases we already handle proves nothing.
        /// </summary>
        private void SampleEngineStuck(Vehicle veh)
        {
            engineStuckValid = false;
            engineStuckMaskFast = engineStuckMaskSlow = engineStuckMaskProbe = 0;
            if (veh == null || !veh.Exists()) return;
            if (getSetting("engineStuckTelemetryV2") != 1
                && getSetting("engineStuckArmV2") != 1) return;
            GateReach("engineStuckTelemetryV2");

            engineStuckMaskProbe = PollEngineStuckMask(veh, STUCK_MS_PROBE);
            engineStuckMaskFast = PollEngineStuckMask(veh, STUCK_MS_FAST);
            engineStuckMaskSlow = PollEngineStuckMask(veh, STUCK_MS_SLOW);
            engineStuckValid = true;
            if (engineStuckMaskProbe != 0)
            {
                GateFire("engineStuckTelemetryV2");
                if (engineStuckFirstSeenTicks == 0)
                    engineStuckFirstSeenTicks = DateTime.Now.Ticks;
            }
            else engineStuckFirstSeenTicks = 0;

            if (getSetting("engineStuckTelemetryV2") != 1) return;
            if (driveLogger == null || !driveLogger.IsRunning) return;
            // Emit whenever a mask CHANGES (a transition is the whole signal), and
            // otherwise at 1 Hz only while something is actually up — a clear
            // detector on a moving car is not worth a line every second.
            bool anythingUp = engineStuckMaskProbe != 0 || engineStuckMaskFast != 0
                || engineStuckMaskSlow != 0;
            bool changed = engineStuckMaskProbe != lastLoggedStuckProbeMask
                || engineStuckMaskFast != lastLoggedStuckFastMask
                || engineStuckMaskSlow != lastLoggedStuckSlowMask;
            if (!changed && (!anythingUp
                || DateTime.Now.Ticks - lastEngineStuckLogTicks < 10000000L)) return;
            lastEngineStuckLogTicks = DateTime.Now.Ticks;
            lastLoggedStuckProbeMask = engineStuckMaskProbe;
            lastLoggedStuckFastMask = engineStuckMaskFast;
            lastLoggedStuckSlowMask = engineStuckMaskSlow;
            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT engine-stuck:"
                + " probe" + STUCK_MS_PROBE + "=" + StuckMaskNames(engineStuckMaskProbe)
                + " fast" + STUCK_MS_FAST + "=" + StuckMaskNames(engineStuckMaskFast)
                + " slow" + STUCK_MS_SLOW + "=" + StuckMaskNames(engineStuckMaskSlow)
                // Everything needed to work out what the four types mean, on the
                // same line: a car on its roof, on its side and jammed against a
                // wall are separable from these.
                + " spd=" + veh.Speed.ToString("F2")
                + " trueSpd=" + trueSpeed.ToString("F2")
                + " upright=" + veh.IsUpright
                + " onAllWheels=" + Function.Call<bool>(Hash.IS_VEHICLE_ON_ALL_WHEELS, veh)
                + " roll=" + veh.Rotation.Y.ToString("F0")
                + " pitch=" + veh.Rotation.X.ToString("F0")
                // ...and the mod's own verdict, so "did the engine beat us" is a
                // one-line read rather than a correlation exercise.
                + " modMode=" + currentDriveMode
                + " modStalledMs=" + (stuckSinceTicks == 0 ? 0L
                    : (DateTime.Now.Ticks - stuckSinceTicks) / 10000L)
                + " autodriveStuck=" + stuckAutodriveEngaged
                + " pos=" + FmtV(veh.Position));
            SnapshotFailure("ENGINE-STUCK", null);
        }

        // iter-49 C5: last value written to SET_VEHICLE_STEER_BIAS, for the FRAME
        // line and the achieved-vs-commanded comparison.
        private float lastSteerBiasWritten = 0f;
        private long  lastSteerBiasLogTicks = 0;
        private long lastEngineStuckArmLogTicks = 0;
        private long lastGunfireVetoLogTicks = 0;
        private int lastLoggedStuckProbeMask = -1;
        private int lastLoggedStuckFastMask = -1;
        private int lastLoggedStuckSlowMask = -1;

        /// <summary>Render a stuck-type bitmask as type numbers. Deliberately NOT
        /// named roof/side/hungup/jammed: that mapping is folklore, and this batch
        /// exists to settle it from a session rather than inherit a guess.</summary>
        private static string StuckMaskNames(int mask)
        {
            if (mask == 0) return "-";
            System.Text.StringBuilder sb = new System.Text.StringBuilder();
            for (int t = 0; t < STUCK_TYPES; t++)
                if ((mask & (1 << t)) != 0) sb.Append('t').Append(t).Append(',');
            if (sb.Length > 0) sb.Length--;
            return sb.ToString();
        }

        /// <summary>
        /// Shared node query. Every caller in this file used to hand-roll the three
        /// OutputArguments and pass nodeFlags=1; this centralises the flags decision
        /// so the iter-49 A3 correction has one place to live.
        /// </summary>
        private bool TryGetNodeWithHeading(GTA.Math.Vector3 pos, int nthClosest, int nodeFlags,
            out GTA.Math.Vector3 nodePos, out float nodeHeading)
        {
            nodePos = GTA.Math.Vector3.Zero;
            nodeHeading = 0f;
            try
            {
                OutputArgument oP = new OutputArgument();
                OutputArgument oH = new OutputArgument();
                OutputArgument oL = new OutputArgument();
                if (!Function.Call<bool>(Hash.GET_NTH_CLOSEST_VEHICLE_NODE_WITH_HEADING,
                        pos.X, pos.Y, pos.Z, nthClosest, oP, oH, oL, nodeFlags, 3.0f, 0f))
                    return false;
                nodePos = oP.GetResult<GTA.Math.Vector3>();
                nodeHeading = oH.GetResult<float>();
                return true;
            }
            catch { return false; }
        }

        /// <summary>
        /// B2: ground height AND surface normal at a coord, in one synchronous call —
        /// no shape-test handle, no async result to poll, so it is safe inside the
        /// scan. GET_GROUND_Z_AND_NORMAL_FOR_3D_COORD = 0x8BDC7BFC57A81E76.
        /// </summary>
        private bool TryGetGroundZAndNormal(GTA.Math.Vector3 pos,
            out float groundZ, out GTA.Math.Vector3 normal)
        {
            groundZ = 0f;
            normal = GTA.Math.Vector3.Zero;
            OutputArgument oZ = new OutputArgument();
            OutputArgument oN = new OutputArgument();
            bool ok = Function.Call<bool>((Hash)0x8BDC7BFC57A81E76,
                pos.X, pos.Y, pos.Z, oZ, oN);
            if (!ok) return false;
            groundZ = oZ.GetResult<float>();
            normal = oN.GetResult<GTA.Math.Vector3>();
            // Same unit-length backstop CapsuleSweep uses: a real engine normal is
            // unit length, and a near-zero Z would make the slope division explode.
            float len = normal.Length();
            if (len < 0.9f || len > 1.1f || Math.Abs(normal.Z) < 0.1f) return false;
            return true;
        }

        /// <summary>
        /// Slope of a surface along a horizontal direction, in degrees. For a plane
        /// with unit normal n, dz/ds along unit horizontal d is -(n.d)/n.z.
        /// </summary>
        private static float SlopeDegAlong(GTA.Math.Vector3 normal, GTA.Math.Vector3 dir)
        {
            float s = -(normal.X * dir.X + normal.Y * dir.Y) / normal.Z;
            return (float)(Math.Atan(s) * 180.0 / Math.PI);
        }

        /// <summary>
        /// B1/B2: sample measured road geometry. Called from the throttled scan, not
        /// per frame. Writes only its own dark fields — touches no assist state.
        /// </summary>
        private void SampleRoadGeometry(Vehicle veh, GTA.Math.Vector3 flatFwd)
        {
            roadEdgeValid = false;
            groundNormValid = false;
            groundAheadValid = false;
            if (veh == null || !veh.Exists()) return;
            GTA.Math.Vector3 p = veh.Position;

            if (getSetting("roadBoundaryV2") == 1)
            {
                GateReach("roadBoundaryV2");
                // GET_ROAD_BOUNDARY_USING_HEADING = 0xA0F8A7517A273C05.
                // Probe perpendicular to travel in both directions; the two hits
                // bracket the carriageway the vehicle is actually on.
                float h = veh.Heading;
                GTA.Math.Vector3 eL, eR;
                bool okL = TryRoadBoundary(p, h + 90f, out eL);
                bool okR = TryRoadBoundary(p, h - 90f, out eR);
                if (okL && okR)
                {
                    roadEdgeLeftM = Dist2D(p, eL);
                    roadEdgeRightM = Dist2D(p, eR);
                    roadWidthMeasM = Dist2D(eL, eR);
                    // Reject obvious nonsense rather than logging it as data: this
                    // native's reliability is the open question B1 exists to answer,
                    // and an unbounded value would poison the digest's statistics.
                    if (roadWidthMeasM > 0.5f && roadWidthMeasM < 60f)
                    {
                        roadEdgeValid = true;
                        GateFire("roadBoundaryV2");
                    }
                }
            }

            if (getSetting("groundNormalV2") == 1)
            {
                GateReach("groundNormalV2");
                float gz;
                GTA.Math.Vector3 n;
                if (TryGetGroundZAndNormal(p, out gz, out n))
                {
                    groundGradeDeg = SlopeDegAlong(n, flatFwd);
                    groundCamberDeg = SlopeDegAlong(n, veh.RightVector);
                    groundNormValid = true;
                    GateFire("groundNormalV2");
                }
                // Lookahead: the grade the car is about to meet, which is what a
                // gravity brake term would need. Sample off the steering polyline
                // when there is one, else straight ahead.
                GTA.Math.Vector3 ahead = steerPolyline != null && steerPolyline.Count > 2
                    ? steerPolyline[2] : p + flatFwd * 25f;
                if (TryGetGroundZAndNormal(ahead, out gz, out n))
                {
                    groundGradeAheadDeg = SlopeDegAlong(n, flatFwd);
                    groundAheadValid = true;
                }
            }
        }

        private bool TryRoadBoundary(GTA.Math.Vector3 pos, float heading,
            out GTA.Math.Vector3 edge)
        {
            edge = GTA.Math.Vector3.Zero;
            while (heading >= 360f) heading -= 360f;
            while (heading < 0f) heading += 360f;
            OutputArgument o = new OutputArgument();
            bool ok = Function.Call<bool>((Hash)0xA0F8A7517A273C05,
                pos.X, pos.Y, pos.Z, heading, o);
            if (!ok) return false;
            edge = o.GetResult<GTA.Math.Vector3>();
            return true;
        }

        private static float Dist2D(GTA.Math.Vector3 a, GTA.Math.Vector3 b)
        {
            float dx = a.X - b.X, dy = a.Y - b.Y;
            return (float)Math.Sqrt(dx * dx + dy * dy);
        }

        // ---- A1/A3 (actuationFeedbackV2 / wheelStateV2): achieved-state readback ----
        // Until now this file logged only what was WRITTEN to the control channel
        // (ctrlB/ctrlT/ctrlHb + ctrlRet). Nothing read back what the car actually
        // did, which is why a whole class of "commanded but never actuated" bugs
        // stayed invisible for two dozen iterations.
        //
        // Every field below is a MEMORY-ADDRESS read — SHVDN resolves an offset
        // inside CVehicle rather than calling a native — so a game build with a
        // different layout can throw or return nonsense. Same discipline as the
        // actuationV2 Vehicle.BrakePower write: wrap everything, and carry an
        // explicit validity flag so "could not read" is never logged as 0.00.
        private int   handlingCacheHandle = 0;
        private float handlingSteerLockDeg = 0f;   // 0 = unknown
        private float handlingMass = 0f;
        // iter-51: the largest |achieved steering angle| this vehicle has actually
        // reached, and the fuse for the one-shot EVENT lock-override. Reset on every
        // vehicle change — it describes a vehicle, not a session.
        private float observedSteerLockDeg = 0f;
        private bool  lockOverrideLogged = false;
        private const float LOCK_OVERRIDE_MARGIN = 1.10f;  // 10% before we disbelieve the report
        private const float LOCK_OBSERVE_CEILING = 80f;    // deg; above this the read is garbage
        // iter-43 A4: the vehicle the geometry helpers describe. Kept warm by
        // RefreshHandlingCache so GetBrakeDistForType (which has no vehicle in
        // scope) can scale without a native call per obstacle.
        private Vehicle cachedGeometryVehicle = null;

        private bool  achValid = false;
        private float achSteerDeg = 0f;    // raw, as SHVDN reports it
        private float achSteerNorm = 0f;   // [-1,1] vs the lock; 0 when lock unknown
        private float achBrake = 0f, achThrottle = 0f;

        private bool  whlValid = false;
        private int   whlCount = 0, whlContactMask = 0;
        private float whlSlip = 0f;        // WheelSpeed - Speed: + spin, - lockup
        private float whlMinTyre = -1f;
        private bool  whlAnyBurst = false;
        private bool  whlPlaneValid = false;
        private float whlPitchDeg = 0f, whlCamberDeg = 0f;
        private long  lastWheelHeartbeatTicks = 0;
        private const float WHEEL_SLIP_REPORT_MS = 1.5f;

        /// <summary>
        /// iter-43 A: resolve HandlingData (per-MODEL, so cache per vehicle handle)
        /// and the derived per-vehicle geometry. Runs whenever the actuation
        /// telemetry OR the geometry control law needs it. Pure read.
        /// </summary>
        private void RefreshHandlingCache(Vehicle veh)
        {
            if (veh == null || !veh.Exists()) return;
            cachedGeometryVehicle = veh;
            if (veh.Handle == handlingCacheHandle) return;
            handlingCacheHandle = veh.Handle;
            handlingSteerLockDeg = 0f;
            handlingMass = 0f;
            // iter-51: a new vehicle has a new lock. Carrying the previous car's
            // observed maximum forward would be worse than having none.
            observedSteerLockDeg = 0f;
            lockOverrideLogged = false;
            try
            {
                HandlingData hd = veh.HandlingData;
                if (hd != null && hd.IsValid)
                {
                    // SteeringLock is stored in RADIANS (the game converts the
                    // degrees value from handling.meta at init); SteeringAngle
                    // is reported in DEGREES. Convert once, here, or the
                    // normalised value is out by a factor of ~57.
                    handlingSteerLockDeg = hd.SteeringLock * 180f / (float)Math.PI;
                    handlingMass = hd.Mass;
                }
            }
            catch { /* layout differs on some builds — normalisation degrades to raw */ }
        }

        /// <summary>
        /// iter-51: announce, once per vehicle, that the reported steering lock has
        /// been falsified by observation. This is the line that makes the TEZERACT
        /// case (reported 19.0, reached 40.1) legible in the digest instead of
        /// showing up as a mystery "LOCK SUSPECT" row with no cause.
        ///
        /// Fires on the crossing, not on every subsequent frame — the denominator
        /// changes exactly once, and triage needs to know which frame to segment on.
        /// </summary>
        private void MaybeLogLockOverride(Vehicle veh)
        {
            if (lockOverrideLogged) return;
            if (handlingSteerLockDeg <= 1f) return;
            if (observedSteerLockDeg <= handlingSteerLockDeg * LOCK_OVERRIDE_MARGIN) return;
            lockOverrideLogged = true;
            if (driveLogger == null || !driveLogger.IsRunning) return;
            try
            {
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lock-override:"
                    + " model=" + veh.DisplayName
                    + " reportedDeg=" + handlingSteerLockDeg.ToString("F1")
                    + " observedDeg=" + observedSteerLockDeg.ToString("F1")
                    + " ratio=" + (observedSteerLockDeg / handlingSteerLockDeg).ToString("F2")
                    + " limitDegNow=" + (SteerNormLimitRad(geometryV2Cached) * 180f / (float)Math.PI).ToString("F1")
                    + " geomGate=" + (geometryV2Cached ? 1 : 0));
            }
            catch { }
        }

        /// <summary>
        /// A1/A3: sample what the vehicle actually did this frame. Pure read — must
        /// never write a control, a task, or any assist state.
        /// </summary>
        private void SampleVehicleFeedback(Vehicle veh)
        {
            achValid = false; whlValid = false; whlPlaneValid = false;
            if (veh == null || !veh.Exists()) return;

            // iter-43 A: the handling cache feeds BOTH the actuation telemetry and
            // the vehicle-geometry control law, so it can no longer live inside the
            // telemetry gate — vehicleGeometryV2 would otherwise silently read a
            // zeroed steering lock and fall back to the sedan constants.
            RefreshHandlingCache(veh);

            if (getSetting("actuationFeedbackV2") == 1)
            {
                GateReach("actuationFeedbackV2");
                try
                {
                    // iter-43 C1: SIGN. Vehicle.SteeringAngle is positive in the
                    // OPPOSITE sense to the steer we command on control 59, so the
                    // raw reading is not comparable to liveSteer. The 07-31 log
                    // settles it beyond doubt: of 22,446 frames with |cmd|>0.3 and
                    // |ach|>0.05, 22,247 disagreed in sign and only 199 agreed, and
                    // the least-squares fit was achSteerNorm = -0.779 * liveSteer
                    // (the 0.779 is ordinary wheel lag, not an error). Negate here,
                    // once, so every downstream consumer — the divergence detector,
                    // the FRAME line and the digest — compares like with like.
                    // This resolves the "sign convention UNVERIFIED" note left by
                    // iter-42 A1.
                    achSteerDeg  = -veh.SteeringAngle;
                    achBrake     = veh.BrakePower;
                    achThrottle  = veh.ThrottlePower;

                    // iter-51: learn the vehicle's REAL lock from what it reaches.
                    // Ceiling-guarded so one garbage read cannot poison the
                    // denominator for the rest of the vehicle's life.
                    float absAchDeg = Math.Abs(achSteerDeg);
                    if (absAchDeg > observedSteerLockDeg && absAchDeg < LOCK_OBSERVE_CEILING)
                    {
                        observedSteerLockDeg = absAchDeg;
                        MaybeLogLockOverride(veh);
                    }

                    // iter-51: normalise against the SAME denominator the command
                    // uses (SteerNormLimitRad). Before this, commanded divided by
                    // min(0.61 rad, lockRad) while achieved divided by the raw
                    // reported lock with no cap — so on TEZERACT an identical
                    // physical angle read 1.84x larger on the achieved side and
                    // pegged at the clamp. The +-2 clamp stays: past this fix an
                    // over-range value means a real over-lock worth seeing, not a
                    // units mismatch.
                    float limitDeg = SteerNormLimitRad(geometryV2Cached) * 180f / (float)Math.PI;
                    achSteerNorm = limitDeg > 1f
                        ? Math.Max(-2f, Math.Min(2f, achSteerDeg / limitDeg))
                        : 0f;
                    achValid = true;
                    GateFire("actuationFeedbackV2");
                }
                catch { achValid = false; }
            }

            if (getSetting("wheelStateV2") == 1)
            {
                GateReach("wheelStateV2");
                try
                {
                    VehicleWheel[] ws = veh.Wheels.GetAllWheels();
                    if (ws != null && ws.Length > 0)
                    {
                        whlCount = ws.Length > 16 ? 16 : ws.Length;
                        whlContactMask = 0;
                        whlMinTyre = -1f;
                        whlAnyBurst = false;

                        GTA.Math.Vector3 vp = veh.Position;
                        GTA.Math.Vector3 fwd = veh.ForwardVector;
                        GTA.Math.Vector3 rgt = veh.RightVector;
                        // Least-squares slope of the contact-point cloud along the
                        // vehicle's own axes. Independent of wheel count and wheel
                        // ordering, which vary by model — so no index assumptions.
                        float sFF = 0f, sFZ = 0f, sRR = 0f, sRZ = 0f, sZ = 0f;
                        int contacts = 0;
                        float[] fOff = new float[whlCount];
                        float[] rOff = new float[whlCount];
                        float[] zOff = new float[whlCount];

                        for (int i = 0; i < whlCount; i++)
                        {
                            VehicleWheel w = ws[i];
                            bool touching = w.IsTouchingSurface;
                            if (touching) whlContactMask |= (1 << i);
                            if (w.IsBursted) whlAnyBurst = true;
                            float th = w.TireHealth;
                            if (whlMinTyre < 0f || th < whlMinTyre) whlMinTyre = th;

                            if (!touching) continue;
                            GTA.Math.Vector3 cp = w.LastContactPosition;
                            GTA.Math.Vector3 d = cp - vp;
                            fOff[contacts] = d.X * fwd.X + d.Y * fwd.Y + d.Z * fwd.Z;
                            rOff[contacts] = d.X * rgt.X + d.Y * rgt.Y + d.Z * rgt.Z;
                            zOff[contacts] = cp.Z;
                            sZ += cp.Z;
                            contacts++;
                        }

                        // Need >=3 contacts for a plane, and spread on each axis.
                        if (contacts >= 3)
                        {
                            float meanZ = sZ / contacts;
                            for (int i = 0; i < contacts; i++)
                            {
                                float dz = zOff[i] - meanZ;
                                sFF += fOff[i] * fOff[i]; sFZ += fOff[i] * dz;
                                sRR += rOff[i] * rOff[i]; sRZ += rOff[i] * dz;
                            }
                            if (sFF > 0.05f && sRR > 0.05f)
                            {
                                // +pitch = nose up, +camber = right side high.
                                whlPitchDeg  = (float)(Math.Atan(sFZ / sFF) * 180.0 / Math.PI);
                                whlCamberDeg = (float)(Math.Atan(sRZ / sRR) * 180.0 / Math.PI);
                                whlPlaneValid = true;
                            }
                        }

                        // + = wheels turning faster than the car is moving (spin,
                        // throttle achieving nothing); - = car outrunning its wheels
                        // (lockup/skid, more brake will not help and steer will not bite).
                        whlSlip = veh.WheelSpeed - veh.Speed;
                        whlValid = true;
                        GateFire("wheelStateV2");
                    }
                }
                catch { whlValid = false; }
            }

            DetectActuationDivergence();
        }

        // ---- A2 (actuationFeedbackV2): actuation-failure detector ----
        // The 2026-07-27 root cause — brake and steer writes nullified by the mod's
        // own DISABLE_CONTROL_ACTION — survived 24 iterations because nothing ever
        // compared the command against the result. This is that comparison, running
        // continuously. It is DIAGNOSTIC ONLY: it must never gate, suppress, or
        // substitute a control output, because a detector that acts on a false
        // positive would invent exactly the class of bug it exists to find.
        //
        // Thresholds are provisional until a first session calibrates them. They are
        // deliberately loose: the digest's frame-level divergence rows do not depend
        // on them, so an over- or under-tuned detector costs only log lines.
        private const float ACT_DIV_CMD_MIN = 0.30f;
        private const float ACT_DIV_ACH_MAX = 0.05f;
        // iter-43 C2: below this speed Vehicle.BrakePower is not an actuation
        // signal — a stopped car legitimately reads 0 under a full brake command.
        private const float ACT_DIV_MIN_SPEED = 3.0f;
        private const long  ACT_DIV_HOLD_TICKS = 2500000L;   // 250 ms
        private const long  ACT_DIV_COOLDOWN_TICKS = 50000000L; // 5 s per kind
        private long actDivBrakeSinceTicks = 0, actDivBrakeLastLogTicks = 0;
        private long actDivSteerSinceTicks = 0, actDivSteerLastLogTicks = 0;

        /// <summary>
        /// Which subsystem currently owns the brake. Extracted from the FRAME line
        /// (iter-27 L1) so the divergence detector names the same owner the frame
        /// log does — a second copy of this ladder would drift out of sync.
        /// </summary>
        private string BrakeOwnerName()
        {
            return emergencyBrakeActive            ? "emergency"
                 : alignmentEngageReverse          ? "reverse"
                 : cachedHandbrakeMagnitude > 0.05f ? "handbrake"
                 : recoveryBrakeRequest > 0.05f    ? "recovery"
                 : (junctionBrakeRequest > 0.05f
                    && junctionBrakeRequest + 0.001f >= curveBrakeRequest) ? "junction"
                 : (speedZoneBrakeRequest > 0.05f
                    && speedZoneBrakeRequest + 0.001f >= curveBrakeRequest) ? "speedzone"
                 // iter-49 A4: give way rides the same curveBrakeRequest channel as
                 // junction and speedzone, so without its own rung it would print
                 // as owner=curve — the exact invisibility iter-33 fixed for
                 // lane-depart.
                 : (giveWayBrakeRequest > 0.05f
                    && giveWayBrakeRequest + 0.001f >= curveBrakeRequest) ? "giveway"
                 // iter-33: lane-depart also flows through curveBrakeRequest;
                 // on 07-02 the session's dominant brake mode printed as
                 // owner=curve and was invisible in the owner field.
                 : (lastLaneDepartBrakeReq > 0.05f
                    && lastLaneDepartBrakeReq + 0.001f >= curveBrakeRequest) ? "lanedepart"
                 : curveBrakeRequest > 0.05f       ? "curve"
                 : accBrakeOut > 0.05f             ? "acc"
                 : rampedBrakeInput > 0.05f        ? "ramped"
                 : "none";
        }

        private void DetectActuationDivergence()
        {
            if (!achValid) { actDivBrakeSinceTicks = 0; actDivSteerSinceTicks = 0; return; }
            if (driveLogger == null || !driveLogger.IsRunning) return;
            long now = ModClock.Ticks;

            // BRAKE: the mod asked for meaningful brake and the vehicle's physics-side
            // brake never moved. Ignore the case where the wheels are off the ground —
            // that is a real inability to brake, not a lost command.
            //
            // iter-43 C2: SPEED-GATED. Vehicle.BrakePower reads ~0 whenever the car
            // is already stopped or creeping, so without this the detector fires on
            // ordinary standstill braking. Measured on 07-31: the "dead" rate was
            // 84.1% below 0.5 m/s and 76.7% below 2 m/s, but 0.8% above 5 m/s and
            // 0.6% above 10 m/s — the whole "52.9% of brake commands are dead"
            // headline was a readback artifact of a stationary car, not a lost
            // command. The brake channel is healthy (brake-episode aPeak median
            // 7.83 m/s2). Only a command ignored while the car is still MOVING is
            // evidence of anything, and mis-reading this is how three separate
            // iterations were sent chasing a phantom brake bug.
            float actDivSpeed = 0f;
            try
            {
                if (Game.Player.Character.IsInVehicle())
                    actDivSpeed = Game.Player.Character.CurrentVehicle.Speed;
            }
            catch { actDivSpeed = 0f; }
            bool brakeDead = rampedBrakeInput > ACT_DIV_CMD_MIN
                && achBrake < ACT_DIV_ACH_MAX
                && actDivSpeed > ACT_DIV_MIN_SPEED
                && !(whlValid && whlContactMask == 0);
            if (brakeDead)
            {
                if (actDivBrakeSinceTicks == 0) actDivBrakeSinceTicks = now;
                else if (now - actDivBrakeSinceTicks > ACT_DIV_HOLD_TICKS
                         && now - actDivBrakeLastLogTicks > ACT_DIV_COOLDOWN_TICKS)
                {
                    actDivBrakeLastLogTicks = now;
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] EVENT actuation-divergence: kind=brake"
                        + " cmd=" + rampedBrakeInput.ToString("F2")
                        + " ach=" + achBrake.ToString("F2")
                        + " heldMs=" + ((now - actDivBrakeSinceTicks) / 10000)
                        + " owner=" + BrakeOwnerName()
                        + " ctrlRet=" + (controlWriteLog.Length > 0 ? controlWriteLog.ToString() : "-")
                        + " wheels=" + (whlValid ? Convert.ToString(whlContactMask, 2) : "-")
                        + " spd=" + (Game.Player.Character.IsInVehicle()
                            ? Game.Player.Character.CurrentVehicle.Speed.ToString("F1") : "-"));
                }
            }
            else actDivBrakeSinceTicks = 0;

            // STEER: only meaningful once the lock is known, since without it
            // achSteerNorm is pinned at 0 and every frame would look like a failure.
            //
            // iter-46 0b-3: SPEED-GATED, for exactly the reason the brake branch
            // above was gated in iter-43 — and this is the THIRD time this class
            // of readback artifact has been mistaken for lost authority.
            // Vehicle.SteeringAngle reads 0.0 on a stationary car when nothing is
            // driving the throttle axis. Measured on 08-01: 0.0% "dead" on frames
            // where ctrlT was live, 75-99% where it was not. Session-wide by speed
            // band the rate is 68.9% below 2 m/s but 8.0% at 5-10 m/s, and 07-31
            // reads 10.2% in that same band — i.e. the "43.1% of steer commands
            // are not actuated" headline was produced entirely by a session that
            // spent nearly all its time stationary, not by a control fault.
            //
            // Note the high-speed end is ALSO not a control fault: GTA's own
            // steering assist scales usable lock down as speed rises, so a large
            // command legitimately yields <1 deg of wheel movement above ~10 m/s.
            // Only the 2-10 m/s band is evidence about the control channel.
            bool steerDead = handlingSteerLockDeg > 1f
                && Math.Abs(lastLiveSteer) > ACT_DIV_CMD_MIN
                && Math.Abs(achSteerNorm) < ACT_DIV_ACH_MAX
                && actDivSpeed > ACT_DIV_MIN_SPEED;
            if (steerDead)
            {
                if (actDivSteerSinceTicks == 0) actDivSteerSinceTicks = now;
                else if (now - actDivSteerSinceTicks > ACT_DIV_HOLD_TICKS
                         && now - actDivSteerLastLogTicks > ACT_DIV_COOLDOWN_TICKS)
                {
                    actDivSteerLastLogTicks = now;
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] EVENT actuation-divergence: kind=steer"
                        + " cmd=" + lastLiveSteer.ToString("F2")
                        + " ach=" + achSteerNorm.ToString("F3")
                        + " achDeg=" + achSteerDeg.ToString("F1")
                        + " lockDeg=" + handlingSteerLockDeg.ToString("F1")
                        // iter-51: the reported lock alone was not enough to read
                        // these lines. Carry the observed maximum and the
                        // denominator actually in use, so a "dead" steer caused by
                        // a wrong lock is distinguishable from a lost command.
                        + " lockObsDeg=" + observedSteerLockDeg.ToString("F1")
                        + " limitDeg=" + (SteerNormLimitRad(geometryV2Cached) * 180f / (float)Math.PI).ToString("F1")
                        + " heldMs=" + ((now - actDivSteerSinceTicks) / 10000)
                        + " written=" + lastSteerWritten);
                }
            }
            else actDivSteerSinceTicks = 0;
        }

        /// <summary>
        /// Checks if a stationary obstacle is actually in the vehicle's projected travel lane.
        /// Combines road context with lane-width analysis to filter false positives from
        /// parked cars on shoulders. Moving obstacles always pass this check.
        /// </summary>
        private bool IsObstacleInTravelLane(Vehicle playerVeh, GTA.Math.Vector3 obstaclePos,
            float obstacleSpeed)
        {
            // Moving obstacles are always relevant (active traffic)
            if (obstacleSpeed > 1.0f) return true;

            // For stationary obstacles, check if they're on the road
            if (!IsPositionOnRoad(obstaclePos)) return false;

            // Even if on road, check if the obstacle is in our projected path
            GTA.Math.Vector3 toObstacle = obstaclePos - playerVeh.Position;
            GTA.Math.Vector3 forward = isReversing ? -playerVeh.ForwardVector : playerVeh.ForwardVector;
            GTA.Math.Vector3 right = playerVeh.RightVector;

            float lateralOffset = Math.Abs(GTA.Math.Vector3.Dot(right, toObstacle));
            float forwardDist = GTA.Math.Vector3.Dot(forward, toObstacle);

            // Not ahead of us
            if (forwardDist < 0) return false;

            // Lane width is road-type-aware: a freeway lane is ~4m, a city street
            // ~3.5m, an alley ~2.5m. MapDb returns "unknown" outside classified
            // polygons and we fall back to the surface preset (3.5m, legacy value).
            float laneWidth = GetLanePreset(MapDb.GetRoadTypeAt(playerVeh.Position)).widthM
                              + GetVehicleCollisionRadius(playerVeh);
            return lateralOffset < laneWidth;
        }

        /// <summary>
        /// Finds the best vehicle ahead traveling in the same direction to follow.
        /// Following a lead vehicle provides natural lane keeping since traffic stays in-lane.
        /// Returns a lateral steering correction to match the lead vehicle's lane position.
        /// </summary>
        private float GetLeadVehicleGuidance(Vehicle playerVeh)
        {
            hasLeadVehicle = false;
            leadVehicle = null;
            leadVehicleLateralOffset = 0f;

            GTA.Math.Vector3 playerPos = playerVeh.Position;
            GTA.Math.Vector3 forwardVec = playerVeh.ForwardVector;
            float vehicleSpeed = playerVeh.Speed;
            float vehicleHeading = playerVeh.Heading;

            // Search range scales with speed AND vehicle class (iter-8). Was
            // a class-agnostic `vehicleSpeed * 3f`; now uses the meta brake-
            // lookahead formula so a truck (longer required following gap)
            // looks further ahead than a sports car at the same speed.
            // Same 15-60 m clamp preserves the existing ACC range envelope.
            var accAi = VehicleAIHandlingRegistry.GetForVehicle(playerVeh);
            float searchRange = Math.Max(15f, Math.Min(60f,
                accAi.BrakeLookaheadForSpeed(vehicleSpeed) * 1.3f));

            Vehicle[] nearbyVehicles = World.GetNearbyVehicles(playerPos, searchRange);
            if (nearbyVehicles == null || nearbyVehicles.Length == 0)
                return 0f;

            Vehicle bestLead = null;
            float bestScore = float.MaxValue; // Lower is better (closest suitable vehicle)

            foreach (Vehicle veh in nearbyVehicles)
            {
                if (veh == null || !veh.Exists() || veh == playerVeh)
                    continue;

                // Must be moving (not parked)
                if (veh.Speed < 2f)
                    continue;

                GTA.Math.Vector3 toVeh = veh.Position - playerPos;
                float distance = toVeh.Length();

                // Must be ahead of us
                float dotForward = GTA.Math.Vector3.Dot(forwardVec, GTA.Math.Vector3.Normalize(toVeh));
                if (dotForward < 0.7f) // Must be roughly ahead (within ~45 degrees)
                    continue;

                // Must be traveling in a similar direction (same lane direction)
                float headingDiff = veh.Heading - vehicleHeading;
                while (headingDiff > 180f) headingDiff -= 360f;
                while (headingDiff < -180f) headingDiff += 360f;
                if (Math.Abs(headingDiff) > 30f) // Must be within 30 degrees of our heading
                    continue;

                // Must not be too far to the side (within ~2 lanes)
                float lateralDist = Math.Abs(GTA.Math.Vector3.Dot(playerVeh.RightVector, toVeh));
                if (lateralDist > 8f) // More than ~2 lane widths away
                    continue;

                // Score: prefer closest vehicle that's directly ahead
                // Weight forward distance more than lateral distance
                float forwardDist = GTA.Math.Vector3.Dot(forwardVec, toVeh);
                float score = forwardDist + lateralDist * 2f; // Penalize lateral offset

                if (score < bestScore)
                {
                    bestScore = score;
                    bestLead = veh;
                }
            }

            if (bestLead == null)
                return 0f;

            // Found a lead vehicle - calculate lateral offset to match their position
            hasLeadVehicle = true;
            leadVehicle = bestLead;

            GTA.Math.Vector3 toLeadVeh = bestLead.Position - playerPos;
            float leadLateral = GTA.Math.Vector3.Dot(playerVeh.RightVector, toLeadVeh);
            leadVehicleLateralOffset = leadLateral;

            // Steer toward the lead vehicle's lateral position
            // Scale correction by how far off we are, gentle at small offsets
            float lateralCorrection = leadLateral / 6f; // Gentle: 6m offset = full correction
            lateralCorrection = Math.Max(-0.5f, Math.Min(0.5f, lateralCorrection)); // Cap at 0.5

            return lateralCorrection;
        }

        // (iter-18 B4) The pre-Stanley node-guidance implementations that lived here
        // — LaneCenterFromNode, GetRoadGuidance, GetWaypointAlignmentScore,
        // GetRoadCurveGuidance — had been dead code since the path-polyline
        // migration and were removed. NOTE for plan B1 step 2 (lane-offset
        // polyline): LaneCenterFromNode held the carriageway-offset + lane-snap
        // math (right-perp from node heading; K = ceil(lanes/2) per direction;
        // carriageCenter = node + right * K*laneWidth*0.5; snap to nearest lane
        // with LANE_CHANGE_HYSTERESIS_M hysteresis via lastLaneIndex). Recover the
        // full implementation from git history when implementing the offset — see
        // driveassist-improvement-plan-2026-06-09.md.

        // GetLaneCenterGuidance — Stanley lateral controller over the
        // prebuilt path polyline (see BuildPathPolyline).
        //
        // What changed (Path-Aware Drive Assist):
        //   - Source: pathPolyline is composed once per detection tick from
        //     GPS route / static node graph (67k+ shipped nodes) / live
        //     native, in priority order. Replaces the single noisy
        //     GET_NTH_CLOSEST_VEHICLE_NODE_FAVOUR_DIRECTION sample that
        //     caused side-to-side drift as the favoured node snapped between
        //     parallel lanes.
        //   - Controller: Stanley (Hoffmann et al., DARPA 2005).
        //     δ = -ψ_e + atan2(k·e, v+ε). Stable at low lookahead — pure
        //     pursuit oscillates here.
        //   - The body lives in ComputeStanleySteer; this wrapper exists so
        //     the rest of ProcessSteeringAssist's call site is unchanged.
        private float GetLaneCenterGuidance(Vehicle playerVeh)
        {
            float stanley = ComputeStanleySteer(playerVeh);
            lastRoadCorrection = stanley;
            return stanley;
        }

        /// <summary>
        /// Updates the cached waypoint direction for waypoint-aware drive assist.
        /// Gets the target position from either waypoint or mission blip.
        /// Calculates the heading direction TO the target for road node preference.
        /// </summary>
        private void UpdateWaypointDirection(GTA.Math.Vector3 playerPos)
        {
            GTA.Math.Vector3 targetPos = GTA.Math.Vector3.Zero;

            // Check for active waypoint first
            if (Function.Call<bool>(Hash.IS_WAYPOINT_ACTIVE))
            {
                int wpHandle = Function.Call<int>(Hash.GET_FIRST_BLIP_INFO_ID, 8); // 8 = waypoint blip
                if (Function.Call<bool>(Hash.DOES_BLIP_EXIST, wpHandle))
                {
                    targetPos = Function.Call<GTA.Math.Vector3>(Hash.GET_BLIP_INFO_ID_COORD, wpHandle);
                }
            }
            // Fall back to mission blip if no waypoint
            else if (missionTrackingActive && trackedBlipHandle != -1)
            {
                if (Function.Call<bool>(Hash.DOES_BLIP_EXIST, trackedBlipHandle))
                {
                    targetPos = Function.Call<GTA.Math.Vector3>(Hash.GET_BLIP_INFO_ID_COORD, trackedBlipHandle);
                }
            }

            if (targetPos != GTA.Math.Vector3.Zero)
            {
                cachedWaypointPos = targetPos;
                hasActiveWaypoint = true;

                // Calculate heading TO the waypoint (in degrees, matching GTA's heading system)
                // GTA V heading: 0=North, increases CLOCKWISE (90=East, 180=South, 270=West)
                float dx = targetPos.X - playerPos.X;
                float dy = targetPos.Y - playerPos.Y;

                // atan2(-dx, dy) gives angle from North, increasing clockwise
                // This matches GTA's vehicle heading system
                float angleRad = (float)Math.Atan2(-dx, dy);
                float angleDeg = angleRad * (180f / (float)Math.PI);

                // Normalize to 0-360
                if (angleDeg < 0) angleDeg += 360f;

                // GTA headings are actually counter-clockwise from what we calculated
                // So we need to flip it: heading = 360 - angle (or just negate and normalize)
                cachedWaypointHeading = (360f - angleDeg) % 360f;
            }
            else
            {
                hasActiveWaypoint = false;
            }
        }

        // (iter-18 B4) GetWaypointAlignmentScore + GetRoadCurveGuidance removed —
        // dead since the Stanley/path-polyline migration. NOTE: this leaves the
        // `waypointDriveAssist` setting with no behavioral consumer beyond
        // UpdateWaypointDirection keeping cachedWaypointPos/Heading warm; the plan
        // (B1/B4) proposes re-wiring waypoint preference into recovery-node /
        // polyline source selection rather than deleting the setting.

        /// <summary>
        /// Finds the nearest road node going the same direction as the vehicle.
        /// Returns the node position, heading, and distance. Returns false if no valid node found.
        /// </summary>
        private bool FindNearestSameDirectionRoadNode(Vehicle playerVeh, out GTA.Math.Vector3 nodePos, out float nodeHeading, out float distance)
        {
            nodePos = GTA.Math.Vector3.Zero;
            nodeHeading = 0f;
            distance = 999f;

            GTA.Math.Vector3 playerPos = playerVeh.Position;
            float vehicleHeading = playerVeh.Heading;

            // C1: a streaming gap makes every probe below return false. Report it
            // as "unknown" via the field rather than letting the caller read the
            // resulting false as "no road anywhere near".
            lastNodeQueryNodesUnloaded = false;
            if (!ArePathNodesLoadedAt(playerPos, "findNearestSameDir"))
            {
                lastNodeQueryNodesUnloaded = true;
                return false;
            }

            // Search in expanding radius for a valid node
            for (int nodeIndex = 1; nodeIndex <= 10; nodeIndex++)
            {
                OutputArgument outPos = new OutputArgument();
                OutputArgument outHeading = new OutputArgument();
                OutputArgument outLanes = new OutputArgument();

                // iter-49 A3: GCNF_FAVOUR_FACING is the engine doing in one call
                // what the loop below does by hand — walk out from the car and
                // reject anything more than 45 degrees off our heading. Keep the
                // switched-off nodes: this is a RECOVERY target, and a driveway is
                // a perfectly good place to be pushed back onto out of a ditch.
                bool foundNode = Function.Call<bool>(Hash.GET_NTH_CLOSEST_VEHICLE_NODE_WITH_HEADING,
                    playerPos.X, playerPos.Y, playerPos.Z, nodeIndex, outPos, outHeading, outLanes,
                    NodeFlagsFor(NODEFLAGS_RECOVERY | GCNF_FAVOUR_FACING), 3.0f, 0f);

                if (foundNode)
                {
                    GTA.Math.Vector3 testPos = outPos.GetResult<GTA.Math.Vector3>();
                    float testHeading = outHeading.GetResult<float>();

                    float headingDiff = testHeading - vehicleHeading;
                    while (headingDiff > 180f) headingDiff -= 360f;
                    while (headingDiff < -180f) headingDiff += 360f;

                    // Only accept nodes closely aligned with our direction (within 45 degrees)
                    if (Math.Abs(headingDiff) <= 45f)
                    {
                        // iter-49 A4: never recover INTO a dead end. Escaping a
                        // wedge only to be placed in a cul-de-sac is how the 07-31
                        // strand pattern starts — the ladder frees the car, the car
                        // drives 20 m, and there is nowhere to go. Keep looking; the
                        // loop still falls through to whatever the next node is, and
                        // a dead end is accepted rather than nothing if it is all
                        // that exists (the final candidate is never vetoed).
                        if (getSetting("nodeHazardV2") == 1 && nodeIndex < 10)
                        {
                            int dEnd, fEnd;
                            if (TryGetNodeProperties(testPos, out dEnd, out fEnd)
                                && (fEnd & VNP_LEADS_TO_DEAD_END) != 0)
                            {
                                if (driveLogger != null && driveLogger.IsRunning)
                                    driveLogger.Write("[F" + driveLogFrameCount
                                        + "] EVENT recovery-deadend-skip:"
                                        + " n=" + nodeIndex + " pos=" + FmtV(testPos));
                                continue;
                            }
                        }
                        nodePos = testPos;
                        nodeHeading = testHeading;
                        distance = World.GetDistance(playerPos, testPos);
                        return true;
                    }
                }
            }

            return false;
        }

        /// <summary>
        /// Teleports the vehicle to the nearest valid road node (same direction).
        /// Adds slight Z offset to prevent clipping through ground.
        /// </summary>
        private bool TeleportToNearestRoad(Vehicle playerVeh)
        {
            GTA.Math.Vector3 nodePos;
            float nodeHeading;
            float distance;

            if (FindNearestSameDirectionRoadNode(playerVeh, out nodePos, out nodeHeading, out distance))
            {
                // Add slight Z offset to prevent clipping (0.5m above road)
                GTA.Math.Vector3 teleportPos = new GTA.Math.Vector3(nodePos.X, nodePos.Y, nodePos.Z + 0.5f);

                // Teleport vehicle
                playerVeh.Position = teleportPos;
                playerVeh.Heading = nodeHeading;

                // Preserve some forward momentum but reduce speed
                float currentSpeed = playerVeh.Speed;
                float newSpeed = Math.Max(5f, currentSpeed * 0.5f); // At least 5 m/s, or half current speed
                playerVeh.Velocity = playerVeh.ForwardVector * newSpeed;

                // Reset tracking
                wasCloseToRoad = true;
                offRoadStartTicks = 0;
                lastValidRoadDistance = 0f;

                Speech.Info("Teleported to road");
                return true;
            }

            return false;
        }

        /// <summary>
        /// Finds the best road node to recover toward — no strict heading filter.
        /// Used for wrong-way spawn and off-road drift. Scores candidates by
        /// distance + alignment penalty (1 m ≈ 6° of heading penalty) so a near
        /// well-aligned node beats a far perfectly-aligned one, but a far well-
        /// aligned node beats a near opposite-direction one. Always returns
        /// something if any node is streamed in.
        /// </summary>
        private bool FindBestRecoveryNode(Vehicle playerVeh,
            out GTA.Math.Vector3 nodePos, out float nodeHeading,
            out float distance, out float headingDelta)
        {
            nodePos = GTA.Math.Vector3.Zero;
            nodeHeading = 0f;
            distance = 999f;
            headingDelta = 0f;
            lastRecoverySpeedFlipReject = false; // iter-24 R2

            GTA.Math.Vector3 playerPos = playerVeh.Position;
            float vehicleHeading = playerVeh.Heading;
            GTA.Math.Vector3 forwardVec = playerVeh.ForwardVector;
            float vehSpeedR2 = playerVeh.Speed;  // iter-24 R2: reject U-turn targets above the brake-first gate

            // PRIMARY: static node graph. The 67k-node dump has every node
            // regardless of streaming, so true off-road / fresh-spawn cases
            // always find something. The native version (below) sometimes
            // returns nothing in those cases because the surrounding region
            // hasn't streamed in yet.
            if (NodeGraph.IsLoaded)
            {
                // iter-32 R6: never recover toward a node the game's own AI
                // refuses to use (source-flagged Disabled / not-for-navigation).
                // With v1 data all ext flags are 0 and this excludes nothing.
                int nearIdx = NodeGraph.FindNearestNode(playerPos, STATIC_NODE_SEARCH_RADIUS,
                    NodeGraph.NodeFlags.None, NodeGraph.NodeFlags.None,
                    NodeGraph.ExtFlags.Disabled | NodeGraph.ExtFlags.DontUseForNav);
                if (nearIdx >= 0)
                {
                    GTA.Math.Vector3 p = NodeGraph.GetPosition(nearIdx);
                    // Derive a heading from the highest-forward-lane outgoing
                    // neighbour — that's the direction the AI would travel
                    // through this node.
                    float derivedHeading = vehicleHeading;
                    int lc = NodeGraph.GetLinkCount(nearIdx);
                    int bestFwdLanes = -1;
                    for (int j = 0; j < lc; j++)
                    {
                        int tgt; int fwd; int bwd;
                        NodeGraph.GetLink(nearIdx, j, out tgt, out fwd, out bwd);
                        if (fwd <= 0) continue; // one-way against this direction
                        if (fwd <= bestFwdLanes) continue;
                        GTA.Math.Vector3 tp = NodeGraph.GetPosition(tgt);
                        float dxn = tp.X - p.X, dyn = tp.Y - p.Y;
                        if (dxn * dxn + dyn * dyn < 0.01f) continue;
                        // GTA heading convention: 0 = north (+Y), increases
                        // counter-clockwise. atan2(-x, y) maps a world delta
                        // to that convention.
                        derivedHeading = (float)(Math.Atan2(-dxn, dyn) * 57.29578);
                        if (derivedHeading < 0) derivedHeading += 360f;
                        bestFwdLanes = fwd;
                    }
                    float d = (p - playerPos).Length(); // iter-18 D3
                    float hd = derivedHeading - vehicleHeading;
                    while (hd > 180f) hd -= 360f;
                    while (hd < -180f) hd += 360f;
                    // Z-GUARD: don't recover onto a stacked road deck. If the
                    // nearest static node is far in Z, fall through to the
                    // native scan (scored with a Z penalty) instead.
                    // iter-17 Fix 3: also reject a perpendicular cross-street node (the junction
                    // phantom). The PRIMARY static node had NO heading filter, so at a junction it
                    // returned a node whose derived heading is the cross street (021734: headingDelta
                    // 85-119 deg) and recovery chased it. Fall through to the scored FALLBACK scan
                    // instead; a genuine wrong-way node (>RECOVERY_FLIP_ANGLE) is still accepted.
                    bool perpReject = Math.Abs(hd) > RECOVERY_PERP_REJECT_ANGLE
                                      && Math.Abs(hd) < RECOVERY_FLIP_ANGLE;
                    // iter-24 R2: a U-turn target at speed is unreachable — fall
                    // through (the fallback scan will also reject it) so the car
                    // brakes straight instead of chasing it.
                    bool speedFlip = vehSpeedR2 > RECOVERY_BRAKE_FIRST_SPEED
                                     && Math.Abs(hd) > RECOVERY_FLIP_ANGLE;
                    if (speedFlip) lastRecoverySpeedFlipReject = true;
                    // iter-28 P2b: a >FLIP_ANGLE (U-turn) target is unreachable for a
                    // car at ANY speed — 024041 #3 spun in place into a wall chasing a
                    // 144.7° node at LOW speed (speedFlip only rejected it >12 m/s).
                    // Reject it regardless of speed; the scored FALLBACK (graduated
                    // flipPenalty) picks a reachable node or the car brakes straight.
                    bool flipReject = Math.Abs(hd) > RECOVERY_FLIP_ANGLE;
                    if (Math.Abs(p.Z - playerPos.Z) <= PATH_NODE_MAX_Z_DELTA * 2f
                        && !perpReject && !flipReject)
                    {
                        nodePos = p;
                        nodeHeading = derivedHeading;
                        distance = d;
                        headingDelta = hd;
                        return true;
                    }
                }
            }

            // FALLBACK: native scan. Omnidirectional — no 20 m forward bias
            // since that biased recovery away from spawns that point the
            // wrong way. Scoring still penalises heading mismatch.
            // C1: skip the scan outright on a streaming gap. Running it would
            // score zero candidates and report "no recovery node exists", which
            // is a much stronger (and wrong) claim than "cannot tell yet".
            if (!ArePathNodesLoadedAt(playerPos, "recoveryFallback"))
            {
                lastNodeQueryNodesUnloaded = true;
                return false;
            }
            float bestScore = float.MaxValue;
            bool found = false;
            for (int n = 1; n <= ALIGN_SCAN_NODE_COUNT; n++)
            {
                OutputArgument outP = new OutputArgument();
                OutputArgument outH = new OutputArgument();
                bool ok = Function.Call<bool>((Hash)0x45905BE8654AE067,
                    playerPos.X, playerPos.Y, playerPos.Z,
                    playerPos.X, playerPos.Y, playerPos.Z,
                    n, outP, outH, 1, 3.0f, 0f);
                if (!ok) continue;

                GTA.Math.Vector3 p = outP.GetResult<GTA.Math.Vector3>();
                float h = outH.GetResult<float>();
                float d = (p - playerPos).Length(); // iter-18 D3
                float hd = h - vehicleHeading;
                while (hd > 180f) hd -= 360f;
                while (hd < -180f) hd += 360f;

                // Z penalty strongly de-prioritises stacked-deck nodes without
                // hard-rejecting them (recovery must always find SOMETHING).
                // iter-13 Patch U: the old /6 heading weight let a 51 m node
                // pointing ~180 deg the wrong way win on distance alone (the
                // airport-freeway failure: car aimed NE, lane wanted SE, and
                // recovery still chased the far/flipped target). Weight heading
                // at full strength, add a hard de-prioritisation for near-180
                // flips, and penalise far targets — all soft (never reject) so a
                // recovery node is always found.
                float headPenalty = Math.Abs(hd);
                // iter-17 Fix 3: graduated penalty so a perpendicular cross-street node can't
                // win on proximity. Old gate only penalised >120 deg, letting 85-119 deg through.
                float flipPenalty = Math.Abs(hd) > RECOVERY_FLIP_ANGLE ? 200f
                                  : Math.Abs(hd) > RECOVERY_PERP_REJECT_ANGLE ? 120f : 0f;
                float farPenalty  = d > 30f ? (d - 30f) * 3f : 0f;
                float score = d + headPenalty + flipPenalty + farPenalty
                            + Math.Abs(p.Z - playerPos.Z) * 2f;
                if (score < bestScore)
                {
                    bestScore = score;
                    nodePos = p;
                    nodeHeading = h;
                    distance = d;
                    headingDelta = hd;
                    found = true;
                }
            }

            // iter-24 R2: at speed, reject a U-turn target outright — better to
            // brake straight (no target) than chase a node the car cannot reach.
            if (found && vehSpeedR2 > RECOVERY_BRAKE_FIRST_SPEED
                && Math.Abs(headingDelta) > RECOVERY_FLIP_ANGLE)
            {
                lastRecoverySpeedFlipReject = true;
                found = false;
            }

            return found;
        }

        /// <summary>
        /// Produces strong steering toward the recovery target. Three cases:
        ///   1. Off the node (distance > RECOVERY_DISTANCE_ENGAGE): pursuit toward
        ///      the node POSITION. If the node is behind us at low speed, engage
        ///      reverse.
        ///   2. At the node but skewed: pure heading correction toward node heading.
        ///   3. Faced wrong way at low speed: engage reverse + counter-steer.
        /// Also outputs a braking request so the car slows enough that a tight
        /// realignment turn is geometrically feasible instead of orbiting.
        /// </summary>
        private void GetAlignmentRecoverySteer(Vehicle playerVeh,
            GTA.Math.Vector3 nodePos, float nodeHeading,
            float distance, float headingDelta,
            out float steerOutput, out bool engageReverse, out float brakeOutput)
        {
            steerOutput = 0f;
            engageReverse = false;
            brakeOutput = 0f;

            float speed = playerVeh.Speed;
            GTA.Math.Vector3 toNode = nodePos - playerVeh.Position;
            float fwdC = GTA.Math.Vector3.Dot(playerVeh.ForwardVector, toNode);
            float rightC = GTA.Math.Vector3.Dot(playerVeh.RightVector, toNode);

            // Speed-based saturation: full authority below ALIGN_LOW_SPEED_SATURATE,
            // decays linearly to 0 at +15 m/s. You don't U-turn at highway speed.
            float lowSpeedKick = 1f - Math.Min(1f, Math.Max(0f,
                (speed - ALIGN_LOW_SPEED_SATURATE) / 15f));

            if (distance > RECOVERY_DISTANCE_ENGAGE)
            {
                // OFF-ROAD: pursue the node position.
                if (fwdC < 1f && speed < REVERSE_UTURN_SPEED)
                {
                    // Node is behind/abreast and we're stopped; reverse out.
                    // Sign inverts because reversing flips perceived steering.
                    engageReverse = true;
                    steerOutput = -Math.Sign(rightC);
                }
                else
                {
                    float alpha = (float)Math.Atan2(rightC, Math.Max(0.5f, fwdC));
                    steerOutput = Math.Max(-1f, Math.Min(1f, alpha / 0.9f));
                    steerOutput *= Math.Max(0.4f, lowSpeedKick + 0.4f);
                }
            }
            else
            {
                // ON ROAD but SKEWED: pure heading correction.
                // U-TURN DIRECTION LATCH: near +/-180 deg the sign of
                // headingDelta flips frame-to-frame as the angle wraps, so the
                // car wiggles instead of committing. Latch one direction for
                // the whole U-turn; release once roughly aligned (hysteresis).
                if (Math.Abs(headingDelta) > 150f)
                {
                    if (recoveryUturnDir == 0)
                        recoveryUturnDir = headingDelta >= 0f ? 1 : -1;
                }
                else if (Math.Abs(headingDelta) < 120f)
                {
                    recoveryUturnDir = 0;
                }
                int turnSign = recoveryUturnDir != 0
                    ? recoveryUturnDir
                    : (headingDelta >= 0f ? 1 : -1);

                if (Math.Abs(headingDelta) > REVERSE_UTURN_ANGLE && speed < REVERSE_UTURN_SPEED)
                {
                    // Facing wrong way, slow — reverse + counter-steer.
                    // Sign inverts when reversing: to rotate the nose right we
                    // input left while going backward.
                    engageReverse = true;
                    steerOutput = -turnSign;
                }
                else
                {
                    // Saturates at 30° delta — anything sharper steers at max.
                    float magnitude = Math.Min(1f, Math.Abs(headingDelta) / 30f);
                    steerOutput = turnSign * magnitude * Math.Max(0.6f, lowSpeedKick + 0.5f);
                }
            }

            // RECOVERY BRAKING: a large heading error cannot be turned out at
            // speed — the car just orbits the target (the stuck loop in the
            // debug log). Brake hard — proportional to heading error — to bring
            // the car down to U-turn speed. No lower speed floor: braking must
            // stay engaged all the way down to REVERSE_UTURN_SPEED or a 3-4 m/s
            // dead-band forms. The reverse U-turn manages its own speed, so skip
            // braking once it is engaged.
            if (!engageReverse && speed > REVERSE_UTURN_SPEED)
            {
                float headErrMag = Math.Min(1f, Math.Abs(headingDelta) / 90f);
                if (headErrMag > 0.3f)
                {
                    // ---- iter-40 brakeDeadzoneV2: GOVERN, DON'T STOP ----
                    // `headErrMag * (speed / 8f)` scales with ABSOLUTE speed, so it
                    // held near-full brake all the way down to REVERSE_UTURN_SPEED —
                    // the recovery braking against its own escape. Measured on 07-28
                    // in the (-533,-2254) trap: brake >= 0.3 on 52% of frames and the
                    // handbrake on 18%, while throttle was applied on 36%, with the
                    // car averaging 3.07 m/s. owner=recovery was the second-largest
                    // source of heavy brake demand in the whole session.
                    //
                    // The stated purpose is to reach a speed at which a tight turn is
                    // geometrically feasible. That is a governor: scale with the
                    // EXCESS over the target speed so it decays to zero on arrival
                    // instead of pinning the car. Capped below full authority — the
                    // emergency/threat brake stays the only thing that commands a
                    // real stop.
                    if (getSetting("brakeDeadzoneV2") == 1)
                    {
                        float excess = speed - REVERSE_UTURN_SPEED;
                        brakeOutput = Math.Min(RECOVERY_BRAKE_GOVERN_CAP,
                            headErrMag * (excess / 5f));
                    }
                    else
                    {
                        brakeOutput = Math.Min(1f, headErrMag * (speed / 8f));
                    }
                }
            }

            // UNINTENDED REVERSE: the car is rolling backward but this is not a
            // commanded reverse U-turn. Request a brake — ApplyCachedSteeringInputs
            // routes it to forward throttle (control 71), arresting the backward
            // roll and restoring forward travel toward the recovery target.
            if (isReversing && !engageReverse)
                brakeOutput = Math.Max(brakeOutput, 0.7f);

            // REVERSE-MOTION SIGN: the steer above assumes forward travel. When
            // the car is actually rolling backward (and this is not a commanded
            // reverse U-turn), the same input rotates the nose the wrong way —
            // the controller would fight the car. Invert to match real motion.
            if (isReversing && !engageReverse)
                steerOutput = -steerOutput;

            steerOutput = Math.Max(-1f, Math.Min(1f, steerOutput));
        }

        /// <summary>
        /// Checks road distance and handles auto-teleport logic.
        /// Should be called from ProcessSteeringAssist when drive assist is active.
        /// </summary>
        private void CheckRoadTeleport(Vehicle playerVeh, bool isFullMode, float threatTTC)
        {
            // Only works if setting is enabled and drive assist is on
            if (getSetting("roadTeleport") != 1) return;

            // Gradual recovery is engaged and a reachable target exists — give
            // it the full ROAD_TELEPORT_DELAY_TICKS window before teleporting.
            if (currentDriveMode == DriveMode.RecoveringToRoad
                && hasRecoveryTarget && recoveryTargetDistance < 50f)
            {
                return;
            }

            // ModClock (pause-proof): offRoadStartTicks / closeToRoadConfirmTicks /
            // lastTeleportTicks are all stamped and read from this method's clock
            // (plus the k1Now confirm and log sites, also ModClock) — a pause must
            // not count toward the 5 s off-road teleport timer.
            long now = ModClock.Ticks;

            // Enforce cooldown between teleports to prevent rapid-fire teleporting
            if ((now - lastTeleportTicks) < ROAD_TELEPORT_COOLDOWN_TICKS)
            {
                return;
            }

            GTA.Math.Vector3 nodePos;
            float nodeHeading;
            float currentRoadDistance;

            bool foundNode = FindNearestSameDirectionRoadNode(playerVeh, out nodePos, out nodeHeading, out currentRoadDistance);

            // C1: "path nodes are not streamed here" is not "there is no road
            // here". Before the guard, a streaming gap fell straight through to
            // the distance gates below with currentRoadDistance=999, accumulated
            // off-road time, and could teleport the car. Hold everything — including
            // the off-road accumulator — until the nodes arrive.
            if (lastNodeQueryNodesUnloaded)
            {
                offRoadStartTicks = 0;
                closeToRoadConfirmTicks = 0;
                return;
            }

            lastValidRoadDistance = foundNode ? currentRoadDistance : 999f;

            // Iter-12 Patch Q: surface-aware off-road override. The nav-node
            // distance above can be small even in pure desert because GTA V's
            // nav graph includes dirt-road nodes in Sandy Shores and other
            // off-road regions — the dirt node is physically on the sand, not
            // raised pavement, so its distance never exceeds roadFarThreshold.
            // driveassist-2026-05-27-182748 ran 10 minutes with extensive
            // off-road driving and ZERO offroad-timeout teleports as a
            // result.
            //
            // GET_STREET_NAME_AT_COORD returns streetHash=0 anywhere off a
            // named street (dirt or paved). Sustained streetHash=0 for
            // >OFF_NAMED_STREET_HYSTERESIS_MS forces currentRoadDistance to a
            // large value so the existing distance gates (conditions 2 and 3
            // below) fire correctly. Hysteresis avoids tripping in parking
            // lots and on momentary nav-mesh frames.
            bool onNamedStreet = IsOnNamedStreet(playerVeh.Position);
            if (onNamedStreet)
            {
                offNamedStreetSinceTicks = 0;
                offNamedStreetLogged = false;
            }
            else if (offNamedStreetSinceTicks == 0)
            {
                offNamedStreetSinceTicks = now;
            }
            bool sustainedOffNamedStreet = offNamedStreetSinceTicks > 0
                && (now - offNamedStreetSinceTicks) / 10000 > OFF_NAMED_STREET_HYSTERESIS_MS;
            if (sustainedOffNamedStreet)
            {
                // Force the downstream distance gates to see us as off-road.
                // 50 m is well above the largest roadFarThreshold (20 m at
                // max speed scale) so conditions 2 and 3 will trip cleanly.
                if (currentRoadDistance < 50f) currentRoadDistance = 50f;
                lastValidRoadDistance = 50f;
                if (!offNamedStreetLogged && driveLogger != null && driveLogger.IsRunning)
                {
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] EVENT off-named-street: sustainedMs="
                        + ((now - offNamedStreetSinceTicks) / 10000));
                    offNamedStreetLogged = true;
                }
            }

            // Scale thresholds based on vehicle speed - faster driving = more tolerance
            // At 15 m/s (~33 mph), add 50% to thresholds; at 30 m/s (~67 mph), add 100%
            float vehicleSpeed = playerVeh.Speed;
            float speedScale = 1f + Math.Min(vehicleSpeed / 30f, 1f); // 1.0 to 2.0 multiplier

            float roadCloseThreshold = ROAD_CLOSE_THRESHOLD_BASE * speedScale;
            float roadFarThreshold = ROAD_FAR_THRESHOLD_BASE * speedScale;

            // If no valid node found at all (heading filter rejected everything), don't teleport
            // This prevents teleporting on sharp curves where heading differs significantly
            if (!foundNode)
            {
                // Only teleport if we ALSO can't find ANY node (even with relaxed heading)
                // Try finding any node within 90 degrees as a sanity check
                bool anyNodeNearby = false;
                for (int i = 1; i <= 5; i++)
                {
                    OutputArgument outPos = new OutputArgument();
                    OutputArgument outHeading = new OutputArgument();
                    OutputArgument outLanes = new OutputArgument();

                    if (Function.Call<bool>(Hash.GET_NTH_CLOSEST_VEHICLE_NODE_WITH_HEADING,
                        playerVeh.Position.X, playerVeh.Position.Y, playerVeh.Position.Z,
                        i, outPos, outHeading, outLanes, 1, 3.0f, 0f))
                    {
                        float dist = World.GetDistance(playerVeh.Position, outPos.GetResult<GTA.Math.Vector3>());
                        if (dist < roadCloseThreshold * 1.5f)
                        {
                            anyNodeNearby = true;
                            break;
                        }
                    }
                }

                // If there's any road node nearby, we're probably on a curve - don't teleport.
                // Iter-10 Patch C: don't wipe the off-road accumulator on
                // every flicker into the close-band; require sustained
                // proximity. See OFFROAD_RESET_HYSTERESIS_MS.
                if (anyNodeNearby)
                {
                    if (closeToRoadConfirmTicks == 0)
                        closeToRoadConfirmTicks = now;
                    else if ((now - closeToRoadConfirmTicks) / 10000 > OFFROAD_RESET_HYSTERESIS_MS)
                    {
                        wasCloseToRoad = true;
                        offRoadStartTicks = 0;
                    }
                    return;
                }
                else
                {
                    // Genuinely not near any node — clear the confirm timer so
                    // a future flicker into the close-band has to re-accumulate.
                    closeToRoadConfirmTicks = 0;
                }
            }

            // Condition 1: Collision imminent AND far from road - teleport immediately
            // Only if threat is VERY imminent (< 0.3s) and we're genuinely far from road
            if (threatTTC < 0.3f && currentRoadDistance > roadFarThreshold * 1.5f)
            {
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT teleport: reason=collision-imminent"
                        + " threatTTC=" + threatTTC.ToString("F2")
                        + " roadDist=" + currentRoadDistance.ToString("F1"));
                RecordDriveDecision("teleport: reason=collision-imminent roadDist="
                    + currentRoadDistance.ToString("F1"));
                if (TeleportToNearestRoad(playerVeh))
                {
                    lastTeleportTicks = now;
                    ResetForTeleport("collision-imminent");
                }
                return;
            }

            // Condition 2: Extremely far from any valid road node (scaled by speed)
            if (currentRoadDistance > roadCloseThreshold * 1.5f)
            {
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT teleport: reason=far-from-road"
                        + " roadDist=" + currentRoadDistance.ToString("F1")
                        + " threshold=" + (roadCloseThreshold * 1.5f).ToString("F1"));
                RecordDriveDecision("teleport: reason=far-from-road roadDist="
                    + currentRoadDistance.ToString("F1"));
                if (TeleportToNearestRoad(playerVeh))
                {
                    lastTeleportTicks = now;
                    ResetForTeleport("far-from-road");
                }
                return;
            }

            // Condition 3: Moderately far from road for 5+ seconds
            if (currentRoadDistance > roadFarThreshold)
            {
                // Iter-10 Patch C: clear the close-to-road accumulator the
                // moment we're confirmed off-road — a future flicker back into
                // the close-band has to re-accumulate from zero before the
                // 5 s off-road timer resets.
                closeToRoadConfirmTicks = 0;
                if (wasCloseToRoad)
                {
                    // Just went off-road, start timer
                    offRoadStartTicks = now;
                    wasCloseToRoad = false;
                }
                else if (offRoadStartTicks > 0 && (now - offRoadStartTicks) > ROAD_TELEPORT_DELAY_TICKS)
                {
                    // Been off-road for 5+ seconds
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT teleport: reason=offroad-timeout"
                            + " roadDist=" + currentRoadDistance.ToString("F1")
                            + " offRoadMs=" + ((now - offRoadStartTicks) / 10000f).ToString("F0"));
                    RecordDriveDecision("teleport: reason=offroad-timeout roadDist="
                        + currentRoadDistance.ToString("F1"));
                    if (TeleportToNearestRoad(playerVeh))
                    {
                        lastTeleportTicks = now;
                        ResetForTeleport("offroad-timeout");
                    }
                    return;
                }
            }
            else
            {
                // Close to road - reset tracking only after sustained proximity
                // (iter-10 Patch C). A single frame of "close" no longer wipes
                // the 5 s off-road accumulator — a shoulder-clip during an
                // off-road drift used to spuriously reset and leave the car
                // stuck off-road for 30 s+ (driveassist-2026-05-25-231603 F5397).
                if (closeToRoadConfirmTicks == 0)
                    closeToRoadConfirmTicks = now;
                else if ((now - closeToRoadConfirmTicks) / 10000 > OFFROAD_RESET_HYSTERESIS_MS)
                {
                    wasCloseToRoad = true;
                    offRoadStartTicks = 0;
                }
            }
        }

        /// <summary>
        /// Four-layer stuck-recovery escalation. Runs from ProcessSteeringAssist
        /// (Full mode only). Detects a recovery/alignment mode that is steering
        /// the car but making no physical progress — the "wedged against an
        /// obstacle, ramming forever" failure — and escalates: upright the car,
        /// reverse it out, hand to auto-drive, finally teleport. Layers 3-4 run
        /// in MonitorStuckAutodrive because engaging auto-drive disables the
        /// assist (and therefore this method).
        /// </summary>
        private void UpdateStuckRecovery(Vehicle playerVeh, bool isFullMode)
        {
            // Autonomous get-unstuck maneuvers only make sense in Full mode,
            // where the assist already has full authority. In Assisted mode the
            // player still holds the wheel and can free the car themselves.
            // Layer 3+ is owned by MonitorStuckAutodrive once auto-drive is on.
            if (!isFullMode || playerVeh == null || stuckAutodriveEngaged)
            {
                // iter-36 P0-2: make the skip visible — a stationary car whose
                // stuck detector isn't even running was indistinguishable from
                // one whose gates all evaluated false. (A suspended/keep-alive
                // skip never reaches this method; that is logged at the gate.)
                if (driveLogger != null && driveLogger.IsRunning
                    && playerVeh != null && playerVeh.Speed < 1f
                    && DateTime.Now.Ticks - lastStuckSkipLogTicks > 50000000L)
                {
                    lastStuckSkipLogTicks = DateTime.Now.Ticks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-skip:"
                        + " reason=" + (!isFullMode ? "notFull" : "autodrive"));
                }
                return;
            }

            long now = DateTime.Now.Ticks;
            float speed = playerVeh.Speed;
            bool inRecovery = currentDriveMode != DriveMode.LaneKeeping;
            float skewMag = Math.Abs(roadHeadingDelta);

            // iter-13 Patch S: mode-agnostic no-progress arm. Independent of the
            // LaneKeeping<->Recovery oscillation that defeats the recovery-gated
            // detector below. Keys off physical reality: off-lane/skewed (or in
            // recovery) AND below the stall speed AND no real planar movement.
            // The anchor only resets on >3 m of actual travel, so flipping modes
            // can't restart the clock.
            bool offLaneOrSkewed = skewMag > NOPROGRESS_SKEW_ANGLE || inRecovery;

            // iter-14 Patch Y: square-on stall arm. A car stopped dead but well
            // aligned (low skew, LaneKeeping) with a prop right ahead is invisible
            // to offLaneOrSkewed — that was the wedge at (1255.9,3531.0) in
            // driveassist-2026-05-29-131428 (#3-6: 0.00 m/s, skew -2.4 deg, F1
            // pressed 4x in ~20 s, stuck-arm never fired). Arm it ONLY when the
            // player is actively trying to drive forward but can't, so a deliberate
            // stop (light, traffic, parking) is never disturbed. Releasing the
            // throttle before the 3 s timer elapses cancels it (else-branch below).
            GTA.Math.Vector3 stallPos = playerVeh.Position;
            // W2.4: bumper-true contact radius. Cached threat positions are entity
            // ORIGINS; a car pinning us sits ~my-half-length + their-half-length apart
            // origin-to-origin (~5 m), well outside the old flat 3.0/4.0 m gate.
            bool distressFloor = getSetting("distressFloor") == 1;
            float blkRadius = distressFloor
                ? GetVehicleHalfDims(playerVeh).Y + BLOCKED_CONTACT_MARGIN : 3.0f;
            float blkRadiusLow = distressFloor
                ? GetVehicleHalfDims(playerVeh).Y + BLOCKED_CONTACT_MARGIN : 4.0f;
            bool blockedAhead =
                (cachedSteerThreatPos != GTA.Math.Vector3.Zero
                    && PlanarDist(stallPos, cachedSteerThreatPos) < blkRadius
                    && GTA.Math.Vector3.Dot(playerVeh.ForwardVector, cachedSteerThreatPos - stallPos) > 0f)
                || (cachedBrakeThreatPos != GTA.Math.Vector3.Zero
                    && PlanarDist(stallPos, cachedBrakeThreatPos) < blkRadius
                    && GTA.Math.Vector3.Dot(playerVeh.ForwardVector, cachedBrakeThreatPos - stallPos) > 0f)
                // iter-36 B5: sub-bumper wedge corroboration — geometry the static
                // rejector (correctly) keeps out of the brake path still counts as
                // "blocked ahead" for the stuck machinery. 5 s freshness: the scan
                // may throttle while stopped.
                || (cachedLowObstaclePos != GTA.Math.Vector3.Zero
                    && (now - cachedLowObstacleStamp) < 50000000L
                    && PlanarDist(stallPos, cachedLowObstaclePos) < blkRadiusLow
                    && GTA.Math.Vector3.Dot(playerVeh.ForwardVector, cachedLowObstaclePos - stallPos) > 0f)
                // W2.4: the live nav-assist CENTER reading — at both iter-35 deaths it
                // read 3.2-4.8 m to the pinning car and was ignored. Bumper-true against
                // the actual lead entity's collision radius.
                || (distressFloor && navAssistVehicleCenter != null && navAssistVehicleCenter.Exists()
                    && navAssistDistCenter < GetVehicleHalfDims(playerVeh).Y
                        + GetVehicleCollisionRadius(navAssistVehicleCenter) + 1.5f);
            float fwdThrottle = Math.Max(
                Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71),
                Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 71));
            // iter-16 FIX 7: modest gate loosening (0.5 -> 0.25). RC-6 from the iter-16
            // log analysis corrected the prior read: `arming=blocked` already meant this
            // path FIRED (the player was holding >0.5 throttle), so the gate was not the
            // failure. FIX 1 also resolves the dead-pedal trap directly (throttle is freed
            // when stopped). We still require genuine player INTENT here — keeping a
            // deliberate hands-off stop (light/traffic/parking) from triggering recovery —
            // but accept a lighter press so a blind player nudging to escape still arms.
            // fwdThrottle reads GET_DISABLED_CONTROL_NORMAL, so intent registers even while
            // the throttle is locked. A full intent-free arm was rejected as re-introducing
            // false-recovery risk during a legitimate close stop.
            bool squareOnStall = blockedAhead && fwdThrottle > 0.25f;
            // iter-30 P5: assist THREAT-BRAKE PIN. The forward/emergency/handbrake threat-
            // brake can hold a stopped car against a STATIC prop indefinitely (iter-29
            // #4/#5/#6): on-road, aligned (skew~0), player not throttling -> neither
            // offLaneOrSkewed nor squareOnStall arms, so stuck-recovery never escalates and
            // the car grinds. Treat a low-speed brake-hold as arm-eligible when corroborated
            // by active grinding (body damage in the last ~3 s), an off-road position, or a
            // large lateral offset — so a red-light / stopped-traffic hold never false-arms.
            bool assistBrakeHold = (brakeArmed || emergencyBrakeActive || cachedHandbrakeMagnitude > 0.1f)
                && speed < STUCK_SPEED_THRESHOLD;
            bool pinCorroborated =
                   (lastBodyDropTicks > 0 && (now - lastBodyDropTicks) < STUCK_OFFROAD_TICKS)
                || offRoadStartTicks > 0
                || Math.Abs(lastLaneLateralError) > 4f;
            bool threatBrakePin = assistBrakeHold && pinCorroborated;
            // iter-36 B1: DAMAGE-GRIND ARM. Both 07-04 vehicle deaths sat at skew
            // 2-6 deg (offLaneOrSkewed dead), zero player throttle (squareOnStall
            // dead), held by ACC with no latched brake flag (threatBrakePin dead)
            // while an NPC ground the car to 0 over ~13-20 s. A stopped car losing
            // body health is never a legitimate red-light stop — the damage IS the
            // corroboration, no skew/lat/throttle gate applies.
            bool damageGrindArm = getSetting("stuckDamageArm") == 1
                && lastBodyDropTicks > 0
                && (now - lastBodyDropTicks) < STUCK_OFFROAD_TICKS
                && speed < STUCK_SPEED_THRESHOLD;
            // iter-49 D: bullets are not a wedge. This arm's whole premise is "a
            // stopped car losing body health is being ground against something" —
            // which is exactly wrong when the health is coming off because someone
            // is shooting at it. Running the escape ladder then makes it worse: it
            // pivots and reverses a car whose driver most likely wants to drive
            // away, and it does so while announcing "vehicle stuck".
            if (damageGrindArm && getSetting("gunfireAttribV2") == 1 && underFireNow)
            {
                GateReach("gunfireAttribV2");
                GateFire("gunfireAttribV2");
                damageGrindArm = false;
                if (driveLogger != null && driveLogger.IsRunning
                    && now - lastGunfireVetoLogTicks > 30000000L)
                {
                    lastGunfireVetoLogTicks = now;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT gunfire-arm-veto:"
                        + " proj=" + projectileNear
                        + " wanted=" + Game.Player.WantedLevel
                        + " spd=" + speed.ToString("F2")
                        + " pos=" + FmtV(playerVeh.Position));
                }
            }
            bool armEligible = offLaneOrSkewed || squareOnStall || threatBrakePin || damageGrindArm;

            bool noProgressArm = false;
            if (armEligible && speed < STUCK_SPEED_THRESHOLD)
            {
                // iter-36 B1: while the car is actively being damaged, 3 s of
                // patience is triple-digit health at NPC-grind rates — arm in ~1 s.
                long detectTicks = (damageGrindArm && !offLaneOrSkewed
                        && !squareOnStall && !threatBrakePin)
                    ? NOPROGRESS_DETECT_TICKS / 3 : NOPROGRESS_DETECT_TICKS;
                if (noProgressSinceTicks == 0)
                {
                    noProgressSinceTicks = now;
                    noProgressAnchorPos = playerVeh.Position;
                }
                else if (PlanarDist(playerVeh.Position, noProgressAnchorPos) > NOPROGRESS_MOVE_M)
                {
                    noProgressSinceTicks = now;      // genuine progress — restart the clock
                    noProgressAnchorPos = playerVeh.Position;
                }
                else if (now - noProgressSinceTicks > detectTicks)
                {
                    noProgressArm = true;
                }
            }
            else
            {
                // ---- iter-41 Stage 5a stuckArmHysteresisV2 ----
                // A single frame above STUCK_SPEED_THRESHOLD (0.7 m/s) used to erase
                // 3 s of accumulated evidence. During a creeping stall the speed
                // crosses 0.7 roughly once per second, so the clock could never
                // mature: 07-28 produced ONE stuck-eval in 33,094 frames, zero
                // stuck-arm, zero mode-change, and the whole recovery ladder — plus
                // four iter-40 gates that live inside it — went untested.
                //
                // armEligible is deliberately UNCHANGED: a red light must still be
                // unable to arm. Only the reset is made hysteretic.
                if (getSetting("stuckArmHysteresisV2") == 1 && noProgressSinceTicks != 0)
                {
                    GateReach("stuckArmHysteresisV2");
                    bool reallyMoving = speed >= STUCK_SPEED_THRESHOLD;
                    if (reallyMoving)
                    {
                        if (stuckArmClearSinceTicks == 0) stuckArmClearSinceTicks = now;
                    }
                    else stuckArmClearSinceTicks = 0;
                    bool clearedBySpeed = stuckArmClearSinceTicks != 0
                        && now - stuckArmClearSinceTicks >= STUCK_ARM_CLEAR_TICKS;
                    bool clearedByDistance =
                        PlanarDist(playerVeh.Position, noProgressAnchorPos) > NOPROGRESS_MOVE_M;
                    if (clearedBySpeed || clearedByDistance)
                    {
                        noProgressSinceTicks = 0;
                        stuckArmClearSinceTicks = 0;
                    }
                }
                else
                {
                    noProgressSinceTicks = 0;
                    stuckArmClearSinceTicks = 0;
                }
            }

            // ---- iter-41 Stage 5c: TRAFFIC-QUEUE VETO ----
            // Arming lets the mod reverse, pivot, handbrake-turn or autodrive. Doing
            // that in a queue with a blind passenger is worse than the damage it
            // prevents. The car in front ALSO being stopped is the queue signature;
            // a wedge has no such lead vehicle.
            bool inQueue = getSetting("stuckArmHysteresisV2") == 1 && InTrafficQueue();
            // iter-43 B1: track how long the "queue" has been continuously stalled
            // WHILE THE DRIVER IS ASKING TO GO. The throttle condition is what keeps
            // this off a genuine red light: a patient wait accrues nothing no matter
            // how long the light is, while the 07-31 strand (playerGo=1.00 for the
            // full 32 s) accrues from the first second. Reset the moment it stops
            // looking like a stalled queue, so stop-and-go traffic never matures.
            bool askingToGo = lastPlayerThrottleRaw >= 0.5f;
            if (inQueue && askingToGo)
            {
                if (queueVetoSinceTicks == 0) queueVetoSinceTicks = now;
            }
            else if (!inQueue) queueVetoSinceTicks = 0;
            bool queueVetoExpired = queueVetoSinceTicks != 0
                && now - queueVetoSinceTicks > QUEUE_VETO_MAX_TICKS;
            if (queueVetoExpired && driveLogger != null && driveLogger.IsRunning
                && now - lastQueueVetoExpiredLogTicks > 100000000L)
            {
                lastQueueVetoExpiredLogTicks = now;
                Vehicle qLead = navAssistVehicleCenter;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT queue-veto-expired:"
                    + " heldMs=" + ((now - queueVetoSinceTicks) / 10000L)
                    + " limitMs=" + (QUEUE_VETO_MAX_TICKS / 10000L)
                    + " navC=" + FmtF(navAssistDistCenter)
                    + " leadSpd=" + ((qLead != null && qLead.Exists())
                        ? qLead.Speed.ToString("F1") : "-")
                    + " spd=" + speed.ToString("F1"));
            }
            if (noProgressArm && inQueue && !queueVetoExpired)
            {
                noProgressArm = false;
                if (driveLogger != null && driveLogger.IsRunning
                    && now - lastQueueVetoLogTicks > 50000000L)
                {
                    lastQueueVetoLogTicks = now;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-arm-queue-veto:"
                        + " navC=" + FmtF(navAssistDistCenter)
                        + " navCt=" + (navAssistTypeCenter ?? "none")
                        + " heldMs=" + ((now - queueVetoSinceTicks) / 10000L)
                        + " spd=" + speed.ToString("F1"));
                }
            }
            // ---- iter-41 Stage 5d: SELF-LIMITING BUDGET ----
            // If this tune is wrong, it must fail safe IN GAME rather than needing a
            // mid-session rebuild.
            if (noProgressArm && getSetting("stuckArmHysteresisV2") == 1)
            {
                // iter-46 1-1/1-5: unit=eval — one no-progress arm evaluation with the
                // gate on. reach here (rather than per frame) is what makes the
                // fire/veto split below comparable against a real denominator.
                GateReach("stuckArmHysteresisV2");
                if (now - stuckArmBudgetWindowTicks > 600000000L) // 60 s
                {
                    stuckArmBudgetWindowTicks = now;
                    stuckArmBudgetCount = 0;
                }
                stuckArmBudgetCount++;
                if (stuckArmBudgetCount > STUCK_ARM_BUDGET_PER_MIN)
                {
                    // iter-46 1-5: the budget hit is the gate SUPPRESSING an arm —
                    // a veto, counted separately. The old code put GateFire on the
                    // `else` of this branch, so the census counted the gate NOT
                    // suppressing and `fire:20` read as 20 suppressions when it meant
                    // 20 non-suppressions.
                    GateVeto("stuckArmHysteresisV2");
                    noProgressArm = false;
                    if (driveLogger != null && driveLogger.IsRunning
                        && now - lastStuckBudgetLogTicks > 100000000L)
                    {
                        lastStuckBudgetLogTicks = now;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-arm-budget-hit:"
                            + " arms=" + stuckArmBudgetCount
                            + " budget=" + STUCK_ARM_BUDGET_PER_MIN
                            + " suppressedForMs=" + ((stuckArmBudgetWindowTicks + 600000000L - now) / 10000L));
                    }
                }
                else GateFire("stuckArmHysteresisV2");
            }

            // iter-19 G3: DISPLACEMENT ARM. The speed-gated arm above is defeated
            // by the assist's own reverse/crawl pulses cycling speed 0.5<->3.0
            // (204938/212048: net <2 m over 13-17 s, stuck-arm never fired). Net
            // planar displacement over a rolling window is pulse-proof. Gate =
            // assist actively commanding motion OR genuine player throttle intent
            // (fwdThrottle reads GET_DISABLED_CONTROL_NORMAL above, so intent
            // registers even while the throttle is locked). Deliberately does NOT
            // require blockedAhead — the ground-graze occlusion bug showed threat
            // caches can be empty exactly when wedged on unseen geometry. Hands-off
            // at a red light: gate false, window resets, cannot fire.
            bool displacementArm = false;
            bool assistCommanding = inRecovery || alignmentEngageReverse || pivotEscapeActive;
            if (assistCommanding || fwdThrottle > 0.25f)
            {
                if (dispArmSinceTicks == 0
                    || PlanarDist(playerVeh.Position, dispArmAnchorPos) > STUCK_DISP_MIN_M)
                {
                    dispArmSinceTicks = now; // (re)anchor: genuine progress
                    dispArmAnchorPos = playerVeh.Position;
                }
                else if (now - dispArmSinceTicks > (assistCommanding
                    ? STUCK_DISP_WINDOW_TICKS : STUCK_DISP_WINDOW_PLAYER_TICKS)) // iter-20 H1b
                {
                    displacementArm = true;
                }
            }
            else
            {
                dispArmSinceTicks = 0;
            }
            noProgressArm = noProgressArm || displacementArm;

            // ---- iter-49 C2 (engineStuckArmV2): the engine's own opinion ----
            // Every arm above is a heuristic this project spent 20+ iterations
            // tuning. The engine has maintained four stuck timers the whole time
            // and nothing has ever read one. taxiservice.c abandons a fare on the
            // fast pair at 7 s or the slow pair at 30 s; the probe threshold here
            // is shorter because a blind driver already pressing the throttle
            // against an obstacle should not wait seven seconds for help.
            //
            // ADDITIVE ONLY, and never a veto: an engine timer that fails to fire
            // must not be able to suppress an arm the heuristics got right. That
            // is the same rule the iter-43 queue-veto violated, and it cost a 32 s
            // strand.
            if (getSetting("engineStuckArmV2") == 1 && engineStuckValid)
            {
                GateReach("engineStuckArmV2");
                if (!noProgressArm && engineStuckMaskProbe != 0
                    && speed < STUCK_SPEED_THRESHOLD)
                {
                    noProgressArm = true;
                    GateFire("engineStuckArmV2");
                    if (driveLogger != null && driveLogger.IsRunning
                        && now - lastEngineStuckArmLogTicks > 30000000L)
                    {
                        lastEngineStuckArmLogTicks = now;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT engine-stuck-arm:"
                            + " types=" + StuckMaskNames(engineStuckMaskProbe)
                            + " fast=" + StuckMaskNames(engineStuckMaskFast)
                            + " spd=" + speed.ToString("F2")
                            + " skew=" + skewMag.ToString("F1")
                            + " layer=" + stuckLayer
                            + " pos=" + FmtV(playerVeh.Position));
                        SnapshotFailure("STUCK-ARM", null);
                    }
                }
            }

            // iter-36 B3: locus accrual DECOUPLED from the ladder. iter-35 accrued
            // only while stuckLayer>=1, and the freed-exit churn kept collapsing the
            // layer — session max cumMs 5,253 vs the 30,000 escalation threshold, so
            // layers 3/4 were unreachable in practice. The clock's contract is
            // "total time distressed at one spot never rewinds": accrue whenever the
            // car is near the locus, slow, and distressed (armed, arm-eligible, in
            // an abort-deadlock, or recently damaged) — regardless of layer, giveup
            // cooldowns, or mode churn. Runs before the giveup/wait/freed early
            // returns so no path starves it. Gaps >2 s simply don't accrue.
            bool locusDistressed = stuckLayer >= 1 || armEligible
                || reverseAbortDeadlockUntilTicks > now
                || (lastBodyDropTicks > 0 && (now - lastBodyDropTicks) < STUCK_OFFROAD_TICKS);
            if (stuckLocusValid && locusDistressed
                && speed < STUCK_SPEED_THRESHOLD
                && PlanarDist(playerVeh.Position, stuckLocusPos) < STUCK_LOCUS_RADIUS)
            {
                if (stuckLocusLastAccrualTicks > 0
                    && now - stuckLocusLastAccrualTicks < 20000000L)
                    stuckLocusCumTicks += now - stuckLocusLastAccrualTicks;
                stuckLocusLastAccrualTicks = now;
            }

            // iter-36 P0-2: stuck-eval HEARTBEAT. When the two vehicle deaths sat
            // at layer=0, nothing recorded WHICH arm gate evaluated false — that
            // reconstruction needed the arming source code. While slow for >3 s
            // and unarmed, emit every gate plus its inputs at 5 s cadence.
            if (speed < STUCK_SPEED_THRESHOLD)
            {
                if (stuckEvalLowSinceTicks == 0) stuckEvalLowSinceTicks = now;
                if (stuckLayer == 0 && !noProgressArm
                    && now - stuckEvalLowSinceTicks > 30000000L
                    && driveLogger != null && driveLogger.IsRunning
                    && now - lastStuckEvalLogTicks > 50000000L)
                {
                    lastStuckEvalLogTicks = now;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-eval:"
                        + " offLane=" + offLaneOrSkewed
                        + " squareOn=" + squareOnStall
                        + " pin=" + threatBrakePin
                        + " dmgArm=" + damageGrindArm
                        + " skew=" + roadHeadingDelta.ToString("F1")
                        + " blockedAhead=" + blockedAhead
                        + " lowObst=" + (cachedLowObstaclePos != GTA.Math.Vector3.Zero
                            && (now - cachedLowObstacleStamp) < 50000000L)
                        + " fwdThr=" + fwdThrottle.ToString("F2")
                        + " brakeArmed=" + brakeArmed
                        + " bodyDropAgoMs=" + (lastBodyDropTicks > 0 ? (now - lastBodyDropTicks) / 10000 : -1)
                        + " noProgMs=" + (noProgressSinceTicks > 0 ? (now - noProgressSinceTicks) / 10000 : 0)
                        + " dispMs=" + (dispArmSinceTicks > 0 ? (now - dispArmSinceTicks) / 10000 : 0)
                        + " locusCumMs=" + (stuckLocusCumTicks / 10000));
                }
            }
            else
            {
                stuckEvalLowSinceTicks = 0;
            }

            // ---- iter-25 M3: RECOVERY GIVE-UP ----
            // Track LaneKeeping<->recovery flips in a rolling window. Runs every call so
            // the LaneKeeping half of an oscillation can't reset the count (that is the
            // flaw R2 hit on the 06-18 ~90-frame flip-flop).
            bool involvesRecovery = currentDriveMode != DriveMode.LaneKeeping
                || recoveryGiveupLastMode != DriveMode.LaneKeeping;
            if (currentDriveMode != recoveryGiveupLastMode)
            {
                if (involvesRecovery)
                {
                    if (now - recoveryFlipWindowStart > RECOVERY_GIVEUP_FLIP_WINDOW_TICKS)
                    {
                        recoveryFlipWindowStart = now;
                        recoveryFlipCount = 0;
                        recoveryFlipAnchorPos = playerVeh.Position;
                    }
                    recoveryFlipCount++;
                }
                recoveryGiveupLastMode = currentDriveMode;
            }
            // Track no-net-progress while any recovery maneuver is engaged. The anchor
            // resets only on a genuine STUCK_FREED_DISTANCE move, so reverse/crawl pulses
            // (which the speed-gated timers can't see through) cannot keep it alive.
            bool recoveryEngaged = inRecovery || stuckLayer > 0
                || alignmentEngageReverse || pivotEscapeActive;
            if (recoveryEngaged)
            {
                if (recoveryGiveupSinceTicks == 0
                    || PlanarDist(playerVeh.Position, recoveryGiveupAnchorPos) > STUCK_FREED_DISTANCE)
                {
                    recoveryGiveupSinceTicks = now;
                    recoveryGiveupAnchorPos = playerVeh.Position;
                }
            }
            else
            {
                recoveryGiveupSinceTicks = 0;
            }
            // The flip-cycle trigger only counts if the thrashing made NO net progress
            // (a working recovery that briefly flickers modes while driving clear must
            // not be suspended) — measured from the flip-window anchor.
            bool flipCycle = recoveryFlipCount >= RECOVERY_GIVEUP_FLIPS
                && PlanarDist(playerVeh.Position, recoveryFlipAnchorPos) < STUCK_FREED_DISTANCE
                // iter-36 B3: time floor — iter-35 gave up with flips=4 heldMs=0,
                // i.e. before recovery had actually tried anything. A giveup
                // requires >=1.5 s of engaged recovery.
                && recoveryGiveupSinceTicks != 0
                && (now - recoveryGiveupSinceTicks) >= 15000000L;
            // iter-34 CRIT-3: while the car is stopped and actively taking damage the
            // 12 s no-progress window is a death sentence (07-03: detonated at ~8 s
            // wedged; giveup fired at 12 s). Shorten to 2.5 s so control returns to
            // the player while the car is still alive.
            long giveupWindow = DamageWhileWedged(speed)
                ? RECOVERY_GIVEUP_DAMAGE_TICKS : RECOVERY_GIVEUP_TICKS;
            bool recoveryStalledTooLong = recoveryEngaged && recoveryGiveupSinceTicks != 0
                && now - recoveryGiveupSinceTicks > giveupWindow;
            if (flipCycle || recoveryStalledTooLong)
            {
                long heldMs = recoveryGiveupSinceTicks != 0 ? (now - recoveryGiveupSinceTicks) / 10000 : 0;
                int flips = recoveryFlipCount;
                // Drop every recovery maneuver and return to plain LaneKeeping.
                ResetStuckRecovery();
                pivotEscapeActive = false;
                alignmentEngageReverse = false;
                currentDriveMode = DriveMode.LaneKeeping;
                recoveryGiveupSinceTicks = 0;
                recoveryFlipCount = 0;
                recoveryGiveupLastMode = DriveMode.LaneKeeping;
                // SUSPEND (not just grace): the situation has proven the assist cannot
                // free the car, so it must not immediately re-engage and re-trap. K4's
                // 20 s timeout-resume + the speed/toggle resume paths in onTick apply.
                // ---- iter-40 recoverySuspendV2: DO NOT HAND OVER INTO A HAZARD ----
                // On 07-28, 2 of 3 give-ups produced a collision marker INSIDE the
                // suspension window. At marker #6 the mod could see world geometry at
                // 2.50 m ahead and 2.01 m to the right, the car was doing 5.8 m/s, the
                // player was at full throttle — and the assist had gone silent.
                // Suspending is the right call for STEERING (we have proven we cannot
                // plan an escape) but never for the throttle lockout or the warning.
                bool suspendV2 = getSetting("recoverySuspendV2") == 1;
                float giveupFwdClear = navAssistDistCenter;
                bool giveupHazardClose = suspendV2
                    && giveupFwdClear < GIVEUP_HAZARD_CLEAR_M;
                assistSuspended = true;
                assistSuspendedSinceTicks = ModClock.Ticks; // ModClock pair: K4 auto-resume reads ModClock
                assistGraceUntilTicks = 0;
                assistResumeSpeedOkSinceTicks = 0;
                // Keep the throttle lockout asserted while an obstacle is close. The
                // control-71 lockout is the one intervention that has always worked,
                // and it is exactly what stops a blind driver flooring it into the
                // thing we just failed to escape. Bounded, so it can never strand.
                // iter-46 1-1: unit=episode — one recovery give-up handover. 07-31
                // logged 6 recovery-giveup, 6 assist-suspend and 1 giveup-hold-end
                // while this gate censused eval:0/fire:0.
                if (suspendV2) GateReach("recoverySuspendV2");
                if (giveupHazardClose)
                {
                    if (suspendV2) GateFire("recoverySuspendV2");
                    giveupThrottleHoldUntilTicks = ModClock.Ticks + GIVEUP_THROTTLE_HOLD_TICKS;
                    giveupHazardDist = giveupFwdClear;
                }
                if (now - lastRecoveryGiveupSpeechTicks > 100000000L) // 10 s debounce
                {
                    lastRecoveryGiveupSpeechTicks = now;
                    // iter-40: name the hazard and its side. "You have control" with no
                    // direction is useless to a blind driver pointed at a wall — the
                    // whole point of the handover is that they now need to steer.
                    if (suspendV2 && giveupHazardClose)
                        Speech.Critical("Drive assist can't free the car. You have control. "
                            + DescribeNearestHazard() + ".");
                    else
                        Speech.Critical("Drive assist can't free the car. You have control.");
                }
                if (driveLogger != null && driveLogger.IsRunning)
                {
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT recovery-giveup:"
                        + " reason=" + (flipCycle ? "flipcycle" : "noprogress")
                        + " flips=" + flips
                        + " heldMs=" + heldMs
                        + " fwdClear=" + (giveupFwdClear < 900f
                            ? giveupFwdClear.ToString("F1") : "none")
                        + " hazardClose=" + giveupHazardClose
                        + " pos=(" + playerVeh.Position.X.ToString("F1") + ","
                        + playerVeh.Position.Y.ToString("F1") + ")");
                    SnapshotFailure("RECOVERY-GIVEUP", null);
                    // iter-40 L8: the give-up path is the DOMINANT way the assist stops
                    // being responsible, and it never emitted a suspend event — 07-28
                    // had 3 suspensions and 0 assist-suspend lines, so the transition
                    // was invisible to triage.
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT assist-suspend:"
                        + " reason=giveup"
                        + " speed=" + playerVeh.Speed.ToString("F2")
                        + " trueSpd=" + trueSpeed.ToString("F2")
                        + " bh=" + playerVeh.BodyHealth.ToString("F0")
                        + " eh=" + playerVeh.EngineHealth.ToString("F0")
                        + " fwdClear=" + (giveupFwdClear < 900f
                            ? giveupFwdClear.ToString("F1") : "none")
                        + " throttleHeld=" + giveupHazardClose
                        + " pos=(" + playerVeh.Position.X.ToString("F1") + ","
                        + playerVeh.Position.Y.ToString("F1") + ")");
                }
                return;
            }

            // Already escalating: exit once the car has physically moved clear of
            // the wedge OR rotated back into alignment. While a pivot is running
            // we must NOT exit just because the mode briefly flipped to
            // LaneKeeping (that flip is the trap itself) — stay engaged until the
            // skew is actually resolved or the car has moved.
            if (stuckLayer > 0)
            {
                bool movedClear = PlanarDist(playerVeh.Position, stuckPosition)
                                    > STUCK_FREED_DISTANCE;
                // iter-17 Fix 4: a pivot that wandered the freed-distance but is still ~99 deg
                // skewed (021734 F4901 movedClear finalSkew=-99.4) must NOT be declared freed —
                // it re-fails next frame. Require real skew reduction for the PIVOT's movedClear
                // exit. Non-pivot layers keep the distance-only exit. The PIVOT_MAX_TICKS hard
                // cap still guarantees termination (hand to autodrive) if skew never improves.
                if (pivotEscapeActive && movedClear)
                {
                    bool skewImproved = skewMag < PIVOT_DONE_PROGRESS_ANGLE
                                     || skewMag < Math.Abs(pivotStartSkew) - PIVOT_SKEW_PROGRESS_MIN;
                    movedClear = skewImproved;
                }
                // iter-16 FIX 4: a square-on wedge is ~0 deg skew, so the old
                // alignedNow = skew<20 fired every cycle and "freed" a car that had not
                // moved a millimetre — the 3-frame reverse churn (185543 #6-8). Only
                // count it freed when it is ALSO no longer blocked ahead; an aligned-but-
                // blocked, non-moving car stays in recovery (reverse-out, then autodrive).
                // W2.4: a square-on wedge is ~0 deg skew, so alignedNow fired every
                // cycle and false-freed a car that had not moved (the layer-2 timer
                // could then never reach layer 3). Even with a now-bumper-true
                // blockedAhead, require physical evidence of freedom: real
                // displacement AND actual motion. Matches modeExitClear's discipline.
                bool alignedNow = skewMag < PIVOT_DONE_ANGLE && !blockedAhead
                    && (!distressFloor
                        || (PlanarDist(playerVeh.Position, stuckPosition) > 1.5f && speed > 1.0f));
                bool stillStuck = inRecovery || noProgressArm || pivotEscapeActive;
                // iter-36 B3: a bare mode-exit is NOT freed. A momentary flip to
                // LaneKeeping plus a >3 m twitch (which resets the no-progress
                // clock) collapsed the ladder long before STUCK_FREED_DISTANCE and
                // spoke a false "Vehicle freed." — only count a mode-exit when the
                // car is demonstrably driving away.
                bool modeExitClear = !stillStuck && speed > 3f
                    && PlanarDist(playerVeh.Position, stuckPosition) > 4f;
                if (movedClear || alignedNow || modeExitClear)
                {
                    if (pivotEscapeActive && driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT pivot-done:"
                            + " reason=" + (movedClear ? "movedClear" : alignedNow ? "aligned" : "modeExit")
                            + " startSkew=" + pivotStartSkew.ToString("F1")
                            + " finalSkew=" + roadHeadingDelta.ToString("F1")
                            + " elapsedMs=" + ((now - pivotStartTicks) / 10000));
                    Speech.Info("Vehicle freed.");
                    pivotEscapeActive = false;
                    ResetStuckRecovery();
                    return;
                }
            }
            else
            {
                // Not yet stuck — watch for a stall in a recovery mode OR the
                // mode-agnostic no-progress arm (Patch S). noProgressArm fires
                // on its own 3 s timer, so it can enter Layer 1 directly.
                if ((inRecovery && speed < STUCK_SPEED_THRESHOLD) || noProgressArm)
                {
                    if (stuckSinceTicks == 0)
                        stuckSinceTicks = now;
                    else if (now - stuckSinceTicks > STUCK_DETECT_TICKS || noProgressArm)
                    {
                        // ---- iter-20 H1: TRANSIENT-BLOCKER WAIT ----
                        // If the blockage is a ped/vehicle (things that clear by
                        // themselves), WAIT instead of reversing into live traffic
                        // (3 of 7 flags in the first iter-19 session were the
                        // Layer-2 reverse firing at crossings/jams). Escalate to
                        // the normal ladder only when the blocker has been static
                        // ~9 s, the 25 s cap expires, or it disappears while we
                        // still make no progress (falls through naturally).
                        // Uses existing scan caches — zero new World queries.
                        int waitPeds = (navAssistPedCenter != null && navAssistPedCenter.Exists()) ? 1 : 0;
                        int waitVehs = (navAssistVehicleCenter != null && navAssistVehicleCenter.Exists()) ? 1 : 0;
                        bool waitTypeDynamic = threatType == "pedestrian" || threatType == "vehicle"
                            || closestBrakeObstacleType == "pedestrian" || closestBrakeObstacleType == "vehicle";
                        // iter-34 CRIT-3: never wait politely while the car is being
                        // ground to death — the 07-03 detonation happened DURING
                        // stuck-wait cycles. Damage-while-wedged skips straight to
                        // the escalation ladder.
                        bool wedgeDamageBypass = DamageWhileWedged(speed);
                        if (wedgeDamageBypass && (waitPeds + waitVehs > 0 || waitTypeDynamic)
                            && driveLogger != null && driveLogger.IsRunning)
                            driveLogger.Write("[F" + driveLogFrameCount
                                + "] EVENT stuck-wait-bypass: reason=damage"
                                + " peds=" + waitPeds + " vehs=" + waitVehs);
                        if ((waitPeds + waitVehs > 0 || waitTypeDynamic) && !wedgeDamageBypass)
                        {
                            bool blockerMoving =
                                (waitPeds > 0 && navAssistPedCenter.Velocity.Length() > STUCK_WAIT_BLOCKER_SPEED)
                                || (waitVehs > 0 && navAssistVehicleCenter.Velocity.Length() > STUCK_WAIT_BLOCKER_SPEED);
                            if (stuckWaitSinceTicks == 0)
                            {
                                stuckWaitSinceTicks = now;
                                stuckWaitLastDynamicTicks = now; // optimistic: assume it can clear
                            }
                            if (blockerMoving) stuckWaitLastDynamicTicks = now;
                            if (now - lastStuckWaitCueTicks > STUCK_WAIT_CUE_COOLDOWN_TICKS)
                            {
                                lastStuckWaitCueTicks = now;
                                Speech.Info("Waiting for traffic.");
                            }
                            if (now - stuckWaitLastLogTicks > STUCK_WAIT_LOG_TICKS
                                && driveLogger != null && driveLogger.IsRunning)
                            {
                                stuckWaitLastLogTicks = now;
                                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-wait:"
                                    + " peds=" + waitPeds + " vehs=" + waitVehs
                                    + " moving=" + (blockerMoving ? 1 : 0)
                                    + " brakeType=" + closestBrakeObstacleType
                                    + " waitMs=" + ((now - stuckWaitSinceTicks) / 10000)
                                    + " staticMs=" + ((now - stuckWaitLastDynamicTicks) / 10000));
                            }
                            bool waitStaticTooLong = now - stuckWaitLastDynamicTicks > STUCK_WAIT_STATIC_TICKS;
                            bool waitHardCap = now - stuckWaitSinceTicks > STUCK_WAIT_MAX_TICKS;
                            if (!waitStaticTooLong && !waitHardCap)
                                return; // hold position; the existing brake machinery keeps the car stopped
                            if (driveLogger != null && driveLogger.IsRunning)
                                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-wait-escalate:"
                                    + " reason=" + (waitHardCap ? "timeout" : "static")
                                    + " waitMs=" + ((now - stuckWaitSinceTicks) / 10000)
                                    + " peds=" + waitPeds + " vehs=" + waitVehs);
                        }

                        // Enter Layer 1.
                        stuckLayer = 1;
                        stuckPosition = playerVeh.Position;
                        stuckLayerSinceTicks = now;
                        // iter-35 P3: anchor/refresh the cumulative locus clock.
                        // iter-36 P1-1: capture the reset cause BEFORE mutating —
                        // "cumMs=0" alone couldn't distinguish first-arm-here from
                        // moved-away from fast-clear all session.
                        string locusReset = "kept";
                        float locusDistPrev = -1f;
                        if (!stuckLocusValid) locusReset = "first";
                        else
                        {
                            locusDistPrev = PlanarDist(playerVeh.Position, stuckLocusPos);
                            if (locusDistPrev > STUCK_LOCUS_RADIUS) locusReset = "moved";
                        }
                        if (locusReset != "kept")
                        {
                            stuckLocusPos = playerVeh.Position;
                            stuckLocusCumTicks = 0;
                            stuckLocusValid = true;
                        }
                        stuckLocusLastAccrualTicks = now;
                        if (driveLogger != null && driveLogger.IsRunning)
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-locus:"
                                + " cumMs=" + (stuckLocusCumTicks / 10000)
                                + " reset=" + locusReset
                                + " distPrev=" + locusDistPrev.ToString("F1")
                                + " radius=" + STUCK_LOCUS_RADIUS.ToString("F0")
                                + " layer=" + stuckLayer
                                + " autodriveAtMs=" + (STUCK_LOCUS_AUTODRIVE_TICKS / 10000)
                                + " teleportAtMs=" + (STUCK_LOCUS_TELEPORT_TICKS / 10000)
                                + " pos=" + FmtV(stuckLocusPos));
                        // iter-19 G2: escalation outranks grace — the player has
                        // demonstrably failed to self-escape, hand authority back
                        // to the recovery machinery.
                        if (InWatchdogGrace())
                        {
                            assistGraceUntilTicks = 0;
                            if (driveLogger != null && driveLogger.IsRunning)
                                driveLogger.Write("[F" + driveLogFrameCount
                                    + "] EVENT grace-cancel: reason=stuck-arm");
                        }
                        if (driveLogger != null && driveLogger.IsRunning)
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-arm:"
                                + " mode=" + currentDriveMode
                                + " skew=" + roadHeadingDelta.ToString("F1")
                                + " speed=" + speed.ToString("F2")
                                + " arming=" + (displacementArm ? "displacement"
                                    : noProgressArm ? (offLaneOrSkewed ? "noprogress"
                                        : squareOnStall ? "blocked"
                                        : threatBrakePin ? "pin"
                                        : damageGrindArm ? "damage-grind" : "blocked") : "recovery")
                                + " noProgressMs=" + (noProgressSinceTicks > 0 ? (now - noProgressSinceTicks) / 10000 : 0)
                                + " dispMs=" + (dispArmSinceTicks > 0 ? (now - dispArmSinceTicks) / 10000 : 0));
                    }
                }
                else
                {
                    stuckSinceTicks = 0; // moving fine / not stalled
                    stuckWaitSinceTicks = 0; // iter-20 H1
                    stuckWaitLastDynamicTicks = 0;
                    // iter-35 P3: 10 s of sustained healthy driving clears the
                    // locus clock — the car genuinely escaped.
                    if (speed > 5f)
                    {
                        if (stuckLocusFastSinceTicks == 0) stuckLocusFastSinceTicks = now;
                        else if (stuckLocusValid && now - stuckLocusFastSinceTicks > 100000000L)
                        {
                            // iter-36 P1-1: the invalidation was silent — this is
                            // the event that explains every later cumMs=0.
                            if (driveLogger != null && driveLogger.IsRunning)
                                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-locus-clear:"
                                    + " reason=fast"
                                    + " cumMsLost=" + (stuckLocusCumTicks / 10000)
                                    + " pos=" + FmtV(stuckLocusPos));
                            stuckLocusValid = false;
                            stuckLocusCumTicks = 0;
                        }
                    }
                    else stuckLocusFastSinceTicks = 0;
                }
                if (stuckLayer == 0) return;
            }

            // iter-36 B3: locus accrual moved above the giveup block (decoupled
            // from the ladder) so giveup/wait/freed early-returns cannot starve it.

            // ---- LAYER 1: force the vehicle upright on all four wheels ----
            if (stuckLayer == 1)
            {
                if (!playerVeh.IsOnAllWheels)
                {
                    Function.Call(Hash.SET_VEHICLE_ON_GROUND_PROPERLY, playerVeh, 5.0f);
                    Speech.Info("Vehicle stuck. Righting vehicle.");
                }
                // iter-13 Patch T: when the car is skewed it needs to ROTATE, not
                // just back straight out (a straight reverse re-wedges at the same
                // angle — the Sandy Shores failure). Begin the pivot shuffle.
                if (skewMag > PIVOT_SKEW_ANGLE && speed < PIVOT_SPEED_GATE)
                {
                    pivotEscapeActive = true;
                    pivotPhaseForward = true;
                    pivotPhaseSinceTicks = now;
                    pivotStartTicks = now;
                    pivotStartSkew = roadHeadingDelta;  // iter-17 Fix 4: anchor skew for progress check
                    pivotPhaseCount = 0;                // iter-40: early no-progress abort
                    // Rotate the nose toward the target lane direction. Sign
                    // convention matches GetAlignmentRecoverySteer: a positive
                    // heading delta wants a positive (right) forward-steer input.
                    float pivotDelta = hasRecoveryTarget ? recoveryHeadingDelta : roadHeadingDelta;
                    pivotTurnSign = pivotDelta >= 0f ? 1 : -1;
                    Speech.Info("Drive assist stuck. Turning to align.");
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT pivot-begin:"
                            + " turnSign=" + pivotTurnSign
                            + " headingDelta=" + pivotDelta.ToString("F1"));
                }
                else
                {
                    Speech.Info("Drive assist stuck. Backing up.");
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-layer:"
                            + " layer=2 reason=reverse skew=" + roadHeadingDelta.ToString("F1"));
                        SnapshotFailure("STUCK-LAYER", null);
                }
                stuckLayer = 2;
                stuckLayerSinceTicks = now;
            }

            // iter-35 P3: cumulative escalation. The per-episode timers reset with
            // every giveup; the locus clock does not — after enough total time at
            // one spot, skip the ladder straight to auto-drive, then teleport.
            if (stuckLayer >= 1 && stuckLocusValid && !stuckAutodriveEngaged)
            {
                // ---- iter-40 stuckLadderV2: ROADWAY AUTO-REPOSITION ----
                // Sitting still in a live travel lane is the single most dangerous
                // state this mod can put a blind driver in, and the 30 s / 60 s
                // cumulative thresholds below are tuned for being wedged off-road
                // where waiting costs nothing. On 07-28 the mod teleported the car
                // onto La Puerta Fwy at ~90 degrees to the road, failed to establish
                // a lane, gave up twice, and held it stationary across a live lane
                // while traffic hit it: 467.5 damage, 57% of the session, and the
                // ladder never reached layer 3 or 4 at all.
                //
                // On a roadway, escalate on a much shorter clock. Getting OFF the
                // road is the objective; the normal ladder can resume once we are
                // somewhere it is safe to be slow.
                long escAutodriveTicks = STUCK_LOCUS_AUTODRIVE_TICKS;
                long escTeleportTicks = STUCK_LOCUS_TELEPORT_TICKS;
                bool onRoadway = false;
                if (getSetting("stuckLadderV2") == 1 && speed < 1.5f)
                {
                    // iter-46 1-1: unit=eval — one stuck-ladder escalation check.
                    // 07-31 logged 20 stuck-layer, 15 stuck-locus and 15 stuck-arm
                    // events while this gate censused eval:0/fire:0. fire = the
                    // roadway short-clock actually replaced the normal thresholds,
                    // which is the entire behaviour of the gate.
                    GateReach("stuckLadderV2");
                    try { onRoadway = IsPositionOnRoad(playerVeh.Position); }
                    catch { onRoadway = false; }
                    if (onRoadway)
                    {
                        GateFire("stuckLadderV2");
                        escAutodriveTicks = STUCK_ROADWAY_AUTODRIVE_TICKS;
                        escTeleportTicks = STUCK_ROADWAY_TELEPORT_TICKS;
                    }
                }
                if (stuckLocusCumTicks > escTeleportTicks)
                {
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-layer:"
                            + " layer=4 reason=" + (onRoadway ? "roadway-cum" : "locus-cum")
                            + " onRoadway=" + onRoadway
                            + " cumMs=" + (stuckLocusCumTicks / 10000)
                            + " thresholdMs=" + (escTeleportTicks / 10000));
                        SnapshotFailure("STUCK-LAYER", null);
                    // Announce BEFORE moving — a blind passenger must never be
                    // relocated without warning.
                    Speech.Critical(onRoadway
                        ? "Stopped in traffic. Moving off the road."
                        : "Still stuck here. Teleporting to nearest road.");
                    TeleportToNearestRoad(playerVeh);
                    ResetStuckRecovery();
                    stuckLocusValid = false;
                    stuckLocusCumTicks = 0;
                    return;
                }
                if (stuckLocusCumTicks > escAutodriveTicks)
                {
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-layer:"
                            + " layer=3 reason=" + (onRoadway ? "roadway-cum" : "locus-cum")
                            + " onRoadway=" + onRoadway
                            + " cumMs=" + (stuckLocusCumTicks / 10000)
                            + " thresholdMs=" + (escAutodriveTicks / 10000));
                        SnapshotFailure("STUCK-LAYER", null);
                    if (onRoadway)
                        Speech.Critical("Stopped in traffic. Driving clear.");
                    EngageStuckAutodrive(playerVeh);
                    return;
                }
            }

            // ---- LAYER 2: pivot-in-place (skewed) OR straight reverse-out ----
            if (stuckLayer == 2)
            {
                if (pivotEscapeActive)
                {
                    // 3-point shuffle through the existing recovery machinery.
                    // Forward bite: full lock toward the target (the recovery
                    // forward-crawl in ApplyCachedSteeringInputs propels it).
                    // Reverse bite: alignmentEngageReverse backs the car up; the
                    // OPPOSITE steer sign keeps rotating the nose the same way
                    // (reversing inverts perceived steering). Alternate phases on
                    // a timer until aligned or the hard cap.
                    if (now - pivotPhaseSinceTicks > PIVOT_PHASE_TICKS)
                    {
                        pivotPhaseForward = !pivotPhaseForward;
                        pivotPhaseSinceTicks = now;
                        pivotPhaseCount++;
                        if (driveLogger != null && driveLogger.IsRunning)
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT pivot-phase:"
                                + " phase=" + (pivotPhaseForward ? "forward" : "reverse")
                                + " skew=" + roadHeadingDelta.ToString("F1")
                                + " startSkew=" + pivotStartSkew.ToString("F1")
                                + " phaseN=" + pivotPhaseCount
                                + " elapsedMs=" + ((now - pivotStartTicks) / 10000));

                        // ---- iter-40 stuckLadderV2: ABORT A PIVOT THAT IS LOSING ----
                        // The pivot shuffles for a fixed PIVOT_MAX_TICKS (8 s) before
                        // the timeout below hands off. On 07-28 BOTH pivots ran the
                        // full 8 s and ended WORSE than they started — 71.0 -> 89.3
                        // and -47.2 -> -51.3 degrees — so the car spent 16 s of a
                        // 50 s trap rocking back and forth in a live lane, getting
                        // further from aligned, before anything else was tried.
                        // A few phases is enough to tell: if the skew has not come
                        // down by then, this maneuver is not the answer here.
                        if (getSetting("stuckLadderV2") == 1
                            && pivotPhaseCount >= PIVOT_PROGRESS_CHECK_PHASES
                            && skewMag > Math.Abs(pivotStartSkew) - PIVOT_EARLY_PROGRESS_MIN)
                        {
                            pivotEscapeActive = false;
                            if (driveLogger != null && driveLogger.IsRunning)
                                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT pivot-done:"
                                    + " reason=no-progress"
                                    + " startSkew=" + pivotStartSkew.ToString("F1")
                                    + " finalSkew=" + roadHeadingDelta.ToString("F1")
                                    + " phases=" + pivotPhaseCount
                                    + " elapsedMs=" + ((now - pivotStartTicks) / 10000));
                            EngageStuckAutodrive(playerVeh);
                            return;
                        }
                    }

                    // Force a recovery mode so the downstream steer uses recovery
                    // authority + the forward-crawl runs (both gate on
                    // currentDriveMode != LaneKeeping). Does not re-stamp
                    // lastModeChangeTicks (already stamped earlier this pass).
                    currentDriveMode = DriveMode.AligningHeading;
                    isOnValidRoad = true;
                    alignmentEngageReverse = !pivotPhaseForward;
                    roadSteerCorrection = pivotPhaseForward ? pivotTurnSign : -pivotTurnSign;

                    // ---- iter-49 C3: the same pivot, through the engine ----
                    // Everything above reaches the car as control writes. That
                    // channel is the one this project has repeatedly found to be
                    // lossy, and a pivot that does not actuate is 8 s of a blind
                    // driver sitting in a live lane. TA_HANDBRAKE_TURN_* is the
                    // engine's own version of exactly this manoeuvre and does not
                    // touch the control system at all. Issued for slightly longer
                    // than one phase so it spans the phase without outliving it.
                    // TryTempAction is idempotent per action, so re-issuing every
                    // scan within a phase does not restart the task.
                    int pivotTa = pivotPhaseForward
                        ? (pivotTurnSign > 0 ? TA_HANDBRAKE_TURN_RIGHT : TA_HANDBRAKE_TURN_LEFT)
                        // Reversing inverts perceived steering, so the reverse bite
                        // takes the OPPOSITE hand to keep rotating the same way —
                        // the same inversion roadSteerCorrection applies above.
                        : (pivotTurnSign > 0 ? TA_HANDBRAKE_TURN_LEFT : TA_HANDBRAKE_TURN_RIGHT);
                    if (!pivotPhaseForward)
                        TryTempAction(playerVeh, TA_GO_IN_REVERSE,
                            (int)(PIVOT_PHASE_TICKS / 10000L) + 250, "pivot-reverse");
                    else
                        TryTempAction(playerVeh, pivotTa,
                            (int)(PIVOT_PHASE_TICKS / 10000L) + 250, "pivot-turn");

                    if (now - pivotStartTicks > PIVOT_MAX_TICKS)
                    {
                        // Pivot couldn't align (boxed in on all sides) — hand off
                        // to the auto-drive wander as the last resort.
                        pivotEscapeActive = false;
                        if (driveLogger != null && driveLogger.IsRunning)
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT pivot-done:"
                                + " reason=timeout finalSkew=" + roadHeadingDelta.ToString("F1")
                                + " elapsedMs=" + ((now - pivotStartTicks) / 10000));
                        EngageStuckAutodrive(playerVeh);
                    }
                }
                else
                {
                    // Straight reverse-out (low-skew wedge). Reuse the alignment
                    // reverse machinery; higher layers handle a failed reverse.
                    alignmentEngageReverse = true;
                    roadSteerCorrection = 0f;
                    isOnValidRoad = true;
                    // iter-49 C3: reverseV2 backs out by injecting ForwardSpeed —
                    // it writes a velocity onto a car that may still be physically
                    // wedged, which is why it can look like it worked in the log
                    // and not have moved. TA_GO_IN_REVERSE asks the engine to drive
                    // the car backwards instead, wheels and all.
                    TryTempAction(playerVeh, TA_GO_IN_REVERSE,
                        (int)(STUCK_LAYER2_TICKS / 10000L), "layer2-reverse");

                    if (now - stuckLayerSinceTicks > STUCK_LAYER2_TICKS)
                    {
                        if (driveLogger != null && driveLogger.IsRunning)
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT stuck-layer:"
                                + " layer=3 reason=reverse-timeout");
                            SnapshotFailure("STUCK-LAYER", null);
                        EngageStuckAutodrive(playerVeh);
                    }
                }
            }
        }

        /// <summary>Planar (XY-only) distance — Z is ignored so a car climbing or
        /// dropping a slope while wedged still reads as "no progress".</summary>
        private static float PlanarDist(GTA.Math.Vector3 a, GTA.Math.Vector3 b)
        {
            float dx = a.X - b.X, dy = a.Y - b.Y;
            return (float)Math.Sqrt(dx * dx + dy * dy);
        }

        /// <summary>Layer 3 entry: engage the auto-drive wander task so the game
        /// AI drives the car out. Disables the assist (see the !isAutodriving
        /// gate in onTick); MonitorStuckAutodrive watches for recovery.</summary>
        private void EngageStuckAutodrive(Vehicle playerVeh)
        {
            Ped driver = (guardDriverActive && bodyguards.Count > 0
                            && bodyguards[0] != null && bodyguards[0].IsAlive)
                ? bodyguards[0] : Game.Player.Character;
            int drivingStyle = GetDrivingStyleFromFlags();
            Function.Call(Hash.SET_DRIVER_ABILITY, driver, 1.0f);
            Function.Call(Hash.SET_DRIVER_AGGRESSIVENESS, driver, 0.5f);
            Function.Call(Hash.TASK_VEHICLE_DRIVE_WANDER, driver, playerVeh,
                autodriveSpeed, drivingStyle);

            isAutodriving = true;
            autodriveWanderMode = true;
            autonavMode = "drive";
            autodriveVehicleHandle = playerVeh != null && playerVeh.Exists() ? playerVeh.Handle : 0;
            autodriveCheckTicks = DateTime.Now.Ticks;

            alignmentEngageReverse = false;
            stuckLayer = 3;
            stuckAutodriveEngaged = true;
            stuckLayerSinceTicks = DateTime.Now.Ticks;
            // stuckPosition stays anchored so MonitorStuckAutodrive can measure
            // progress against where the car was wedged.
            Speech.Info("Drive assist still stuck. Auto-drive taking over.");
        }

        /// <summary>Layers 3-4: runs every tick from onTick while a stuck-recovery
        /// auto-drive is engaged (the assist itself is disabled in that state).
        /// Hands control back when the car is on a road again, or teleports if
        /// auto-drive cannot make progress.</summary>
        private void MonitorStuckAutodrive()
        {
            // Player cancelled auto-drive (or it ended) — abandon the recovery.
            if (!isAutodriving) { ResetStuckRecovery(); return; }

            // Player left the vehicle — end the recovery auto-drive cleanly.
            Ped ply = Game.Player.Character;
            if (ply == null || !ply.IsInVehicle()) { DisengageStuckAutodrive(null); return; }
            Vehicle veh = ply.CurrentVehicle;
            if (veh == null || !veh.Exists()) { DisengageStuckAutodrive(null); return; }

            long now = DateTime.Now.Ticks;
            float movedDist = World.GetDistance(veh.Position, stuckPosition);

            // SUCCESS: auto-drive carried the car clear of the wedge and back
            // onto a road node — hand control back (the player's chosen assist
            // mode resumes automatically once isAutodriving clears).
            if (movedDist > STUCK_FREED_DISTANCE)
            {
                GTA.Math.Vector3 np; float nh, nd;
                if (FindNearestSameDirectionRoadNode(veh, out np, out nh, out nd) && nd < 8f)
                {
                    DisengageStuckAutodrive("Auto-drive ending. You have control.");
                    return;
                }
            }

            // LAYER 4: auto-drive made no real progress — teleport to the road.
            if (now - stuckLayerSinceTicks > STUCK_LAYER3_TICKS
                && movedDist < STUCK_FREED_DISTANCE)
            {
                Speech.Info("Auto-drive stuck. Teleporting to nearest road.");
                TeleportToNearestRoad(veh);
                DisengageStuckAutodrive("You have control.");
            }
        }

        /// <summary>Ends the stuck-recovery auto-drive and returns control.</summary>
        private void DisengageStuckAutodrive(string announce)
        {
            isAutodriving = false; autodriveSequenceActive = false;
            autodriveWanderMode = false;
            try { Game.Player.Character.Task.ClearAll(); } catch { }
            if (announce != null) Speech.Info(announce);
            ResetStuckRecovery();
        }

        /// <summary>Clears all stuck-recovery state so the machine can re-arm.
        /// iter-35 P3: deliberately does NOT touch the stuckLocus* fields — the
        /// cumulative per-location clock must survive giveup/reset cycles.</summary>
        private void ResetStuckRecovery()
        {
            stuckLayer = 0;
            stuckSinceTicks = 0;
            dispArmSinceTicks = 0; // iter-19 G3
            stuckWaitSinceTicks = 0; // iter-20 H1
            stuckWaitLastDynamicTicks = 0;
            stuckLayerSinceTicks = 0;
            stuckAutodriveEngaged = false;
            stuckPosition = GTA.Math.Vector3.Zero;
            pivotEscapeActive = false;
            noProgressSinceTicks = 0;
            // iter-49 C2: clear the engine's timers too. They keep accumulating
            // across a successful escape, so without this the very next scan after
            // a release reads "still stuck" and re-arms instantly — a recovery loop
            // that looks, from the log, exactly like a car that never got free.
            ClearEngineStuckTimers();
            // iter-49 C3: and drop any temp action still running, rather than
            // waiting out its duration. A TA_WAIT issued with a long timeout
            // outlives the recovery that asked for it.
            ClearTempAction("reset");
        }

        // ====================================================================
        // iter-49 C3 (tempActionV2): AN ACTUATOR THAT IS NOT THE CONTROL CHANNEL
        // ====================================================================
        // The single most expensive bug in this project's history was the mod
        // disabling the very controls it was writing to, so its brake and steer
        // commands were binned before they reached the car — 24 iterations of
        // tuning a control law that was never actuating. actuationV2 fixed the
        // specific cause; it did not change the fact that every rung of the
        // recovery ladder still goes through that one channel.
        //
        // TASK_VEHICLE_TEMP_ACTION does not. It is an engine-level task on the
        // driver, and vanilla uses it exactly where we use control writes:
        // taxiservice holds a cab with TA_WAIT at 1 000 000 ms and stops it with
        // TA_BRAKE_ACTION at 5 000 ms; re_bus_tours stops a coach the same way.
        //
        // HARD CONSTRAINT: a temp action is a task on the driver ped, so it takes
        // the wheel away from whoever is holding it. It is therefore restricted to
        // Full mode with a recovery already engaged. In Assistive mode the player
        // holds the wheel by definition and this must never fire.
        private const int TA_WAIT = 1;
        private const int TA_BRAKE_REVERSE = 3;
        private const int TA_HANDBRAKE_TURN_LEFT = 4;
        private const int TA_HANDBRAKE_TURN_RIGHT = 5;
        private const int TA_STRONG_BRAKE = 19;
        private const int TA_GO_IN_REVERSE = 22;
        private const int TA_BRAKE_ACTION = 24;
        private int  tempActionCurrent = 0;          // 0 = none
        private long tempActionUntilTicks = 0;       // ModClock
        private string tempActionSite = null;

        /// <summary>
        /// Issue a temp action, if and only if the mod legitimately owns the wheel.
        /// Returns true when the engine took it. Idempotent for a repeated request
        /// of the same action, so a per-scan caller does not restart the task every
        /// scan (which would reset its internal progress and pin the car).
        /// </summary>
        private bool TryTempAction(Vehicle veh, int action, int ms, string site)
        {
            if (getSetting("tempActionV2") != 1) return false;
            GateReach("tempActionV2");
            if (veh == null || !veh.Exists()) return false;
            // Full mode + engaged recovery only. Both conditions, every time.
            if (!cachedIsFullMode) { GateVeto("tempActionV2"); return false; }
            if (stuckLayer < 1 && !pivotEscapeActive) { GateVeto("tempActionV2"); return false; }
            Ped driver = veh.Driver;
            if (driver == null || !driver.Exists() || driver.IsDead)
            {
                GateVeto("tempActionV2");
                return false;
            }
            long now = ModClock.Ticks;
            if (tempActionCurrent == action && now < tempActionUntilTicks) return true;
            try
            {
                Function.Call(Hash.TASK_VEHICLE_TEMP_ACTION, driver, veh, action, ms);
            }
            catch { return false; }
            tempActionCurrent = action;
            tempActionUntilTicks = now + (long)ms * 10000L;
            tempActionSite = site;
            GateFire("tempActionV2");
            if (driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT temp-action:"
                    + " action=" + action + " ms=" + ms + " site=" + site
                    + " layer=" + stuckLayer
                    + " spd=" + veh.Speed.ToString("F2")
                    + " pos=" + FmtV(veh.Position));
            return true;
        }

        /// <summary>Cancel any running temp action. Called on every recovery exit —
        /// a task with a long duration outlives the reason it was issued, and a
        /// blind driver handed back a car that is still braking itself has been
        /// handed back nothing.</summary>
        private void ClearTempAction(string why)
        {
            if (tempActionCurrent == 0) return;
            int was = tempActionCurrent;
            tempActionCurrent = 0;
            tempActionUntilTicks = 0;
            tempActionSite = null;
            try
            {
                Ped p = Game.Player.Character;
                Vehicle v = (p != null && p.IsInVehicle()) ? p.CurrentVehicle : null;
                if (v != null && v.Exists() && v.Driver != null && v.Driver.Exists())
                    Function.Call(Hash.TASK_VEHICLE_TEMP_ACTION, v.Driver, v, 0 /* TA_NONE */, 1);
            }
            catch { }
            if (driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT temp-action-clear:"
                    + " was=" + was + " why=" + why);
        }

        // ====================================================================
        // iter-49 D (gunfireAttribV2): IS THIS DAMAGE A CRASH OR A GUNFIGHT?
        // ====================================================================
        // iter-46 0b-4 established that 932.1 of 07-31's 1552.0 "marked damage"
        // units were police gunfire, and that nothing in the log said so — the
        // analyst had to infer it from `wanted=`. Wanted level is a poor proxy:
        // it is non-zero for whole minutes during which nobody fires a shot, and
        // zero during a gang shootout.
        //
        // taxiservice.c abandons a fare on exactly this question, and uses the
        // two natives that answer it directly:
        //     IS_BULLET_IN_AREA(pos, 7f, false)
        //     IS_PROJECTILE_IN_AREA(min, max /* +/-15 m */, true)
        //
        // The FIELDS are ungated (measurement, iter-46 Stage 0b precedent). Only
        // the behaviour — standing the damage-driven recovery arm down, and
        // saying "you are being shot at" — sits behind the gate.
        private bool  underFireNow = false;
        private bool  projectileNear = false;
        private long  underFireSinceTicks = 0;      // ModClock, 0 = clear
        private long  underFireSampleTicks = 0;
        private long  underFireAnnounceTicks = 0;
        private const float BULLET_AREA_R = 7f;     // R*'s own radius
        private const float PROJECTILE_AREA_R = 15f;

        /// <summary>
        /// Sampled at ~4 Hz from the scan. Cheap, but not free, and the answer does
        /// not change meaningfully between frames.
        /// </summary>
        private void SampleUnderFire(Vehicle veh)
        {
            if (veh == null || !veh.Exists()) { underFireNow = false; return; }
            long now = ModClock.Ticks;
            if (now - underFireSampleTicks < 2500000L) return;   // 250 ms
            underFireSampleTicks = now;
            GTA.Math.Vector3 p = veh.Position;
            bool bullet = false, proj = false;
            try
            {
                bullet = Function.Call<bool>(Hash.IS_BULLET_IN_AREA,
                    p.X, p.Y, p.Z, BULLET_AREA_R, false);
                proj = Function.Call<bool>(Hash.IS_PROJECTILE_IN_AREA,
                    p.X - PROJECTILE_AREA_R, p.Y - PROJECTILE_AREA_R, p.Z - PROJECTILE_AREA_R,
                    p.X + PROJECTILE_AREA_R, p.Y + PROJECTILE_AREA_R, p.Z + PROJECTILE_AREA_R,
                    true);
            }
            catch { return; }
            projectileNear = proj;
            bool wasUnderFire = underFireNow;
            underFireNow = bullet || proj;
            if (underFireNow && underFireSinceTicks == 0) underFireSinceTicks = now;
            // Hold the "under fire" state for 3 s past the last detected round:
            // a burst is intermittent, and a flag that flickers off between shots
            // would let the damage arm fire in the gaps.
            else if (!underFireNow && underFireSinceTicks != 0
                && now - underFireSinceTicks > 30000000L)
                underFireSinceTicks = 0;
            if (!underFireNow && underFireSinceTicks != 0) underFireNow = true;

            if (underFireNow && !wasUnderFire && driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT under-fire:"
                    + " bullet=" + bullet + " proj=" + proj
                    + " wanted=" + Game.Player.WantedLevel
                    + " health=" + (int)veh.Health
                    + " pos=" + FmtV(p));

            // Speech is gated: this is the one part that changes what the player
            // experiences. Critical, because "your car is taking damage and it is
            // not a crash" is safety information for someone who cannot see it.
            if (getSetting("gunfireAttribV2") == 1 && underFireNow
                && now - underFireAnnounceTicks > 120000000L) // 12 s
            {
                underFireAnnounceTicks = now;
                Speech.Info("Taking fire.");
            }
        }

        /// <summary>iter-49 C2. RESET_VEHICLE_STUCK_TIMER for all four types.</summary>
        private void ClearEngineStuckTimers()
        {
            if (getSetting("engineStuckArmV2") != 1
                && getSetting("engineStuckTelemetryV2") != 1) return;
            Ped p = Game.Player.Character;
            if (p == null || !p.IsInVehicle()) return;
            Vehicle v = p.CurrentVehicle;
            if (v == null || !v.Exists()) return;
            try
            {
                for (int t = 0; t < STUCK_TYPES; t++)
                    Function.Call(Hash.RESET_VEHICLE_STUCK_TIMER, v, t);
            }
            catch { }
            engineStuckMaskProbe = engineStuckMaskFast = engineStuckMaskSlow = 0;
            engineStuckFirstSeenTicks = 0;
        }

        /// <summary>iter-16 FIX 3: is this candidate brake point inside an unexpired
        /// rejection locus while the car is essentially stopped? Used to refuse
        /// re-caching a point the watchdog or a long-wedged clear just released, so the
        /// blind player isn't re-trapped a few seconds later.</summary>
        private bool IsBrakeRejected(GTA.Math.Vector3 pos, float speed)
        {
            return brakeRejectUntilTicks > 0
                && DateTime.Now.Ticks < brakeRejectUntilTicks
                && speed < BRAKE_REJECT_SPEED
                && PlanarDist(pos, brakeRejectLocus) < BRAKE_REJECT_RADIUS;
        }

        /// <summary>iter-16 FIX 2: drop every brake/takeover latch, set a rejection
        /// locus, hand the wheel back to LaneKeeping, and tell the player. Called by the
        /// watchdog when the assist has held a stopped car too long.</summary>
        private void ForceReleaseAssistHold(Vehicle playerVeh)
        {
            // Locus at whatever we were braking for, so the next scan can't immediately
            // re-cache it and re-trap the (stopped) player.
            brakeRejectLocus = cachedBrakeThreatPos != GTA.Math.Vector3.Zero
                ? cachedBrakeThreatPos
                : playerVeh.Position + playerVeh.ForwardVector * 3f;
            brakeRejectUntilTicks = DateTime.Now.Ticks + BRAKE_REJECT_WINDOW_TICKS;

            emergencyBrakeActive = false;
            wasObstacleInBrakeZone = false;
            brakeArmed = false;
            rampedBrakeInput = 0f;
            cachedBrakeMagnitude = 0f;
            cachedBrakeThreatPos = GTA.Math.Vector3.Zero;
            cachedBrakeThreatStamp = 0;
            cachedBrakeThreatFirstSeenStamp = 0;
            closestBrakeObstacleType = "none"; // iter-35 L6: the type label survived release — 07-03 #2 snapshot said brakeObstacle=obstacle with dist=-1/age=-1
            alignmentEngageReverse = false;
            recoveryBrakeRequest = 0f;          // iter-17: clear recovery-brake hold so the watchdog can't re-arm
            curveBrakeRequest = 0f;             // iter-19 G1: 215409 — a stale curve-brake hold survived release
            cachedHandbrakeMagnitude = 0f;      // iter-19 G1: a handbrake hold also survived release
            // W2.2: the ACC comfort brake also survived release — a force-release on
            // an ACC-pinned car left accBrakeOut non-zero, so it re-locked the pedal
            // on the very next tick. Clear it and its PID state here too.
            accBrakeOut = 0f;
            accThrottleOut = 0f;
            accIntegral = 0f;
            accPrevError = 0f;
            accStandstillSinceTicks = 0;
            lastAccLeadHandle = 0;

            // Hand the wheel back: drop any stuck-recovery maneuver and return to
            // plain LaneKeeping so the recovery steer / forward-crawl stop driving
            // the car toward the thing we just released.
            DriveMode preReleaseMode = currentDriveMode; // iter-34 HIGH-4: mode before the forced reset
            if (stuckLayer > 0 || pivotEscapeActive || stuckAutodriveEngaged)
                ResetStuckRecovery();
            currentDriveMode = DriveMode.LaneKeeping;

            // iter-19 G2: GRACE + SUSPEND ESCALATION. Clearing the latches is not
            // enough — in 204938 recovery re-set alignmentEngageReverse within ~1 s
            // of every release and the player never actually got control. First
            // fire: latch a passive grace window (mode machine forced to
            // LaneKeeping, no brake arming, no input disables). Second fire within
            // the refire window: the situation re-trapped the player — suspend the
            // assist entirely until they toggle the setting or sustain driving
            // speed (resume handling lives in onTick).
            long fnow = ModClock.Ticks; // pause-proof: pairs with InWatchdogGrace
            bool secondFire = assistGraceUntilTicks > 0
                && fnow < assistGraceUntilTicks + WATCHDOG_REFIRE_WINDOW_TICKS;
            // iter-34 HIGH-4: never fully suspend a WEDGED car. A blind player
            // cannot self-free a pinned vehicle; suspending is abandonment (07-03:
            // 19 s unaided, player hit a parked car during it). Stay in grace
            // instead — the stuck-arm escalation cancels grace and keeps the
            // recovery machinery (the thing that CAN free the car) alive.
            bool wedgedNow = playerVeh.Speed < 1f
                && (preReleaseMode == DriveMode.RecoveringToRoad
                    || VehicleStoppedForLastMs(1f, WEDGE_DAMAGE_STUCK_MS));
            if (secondFire && wedgedNow)
            {
                assistGraceUntilTicks = fnow + WATCHDOG_GRACE_TICKS;
                Speech.Info("Still assisting. Backing you out.");
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT suspend-skip:"
                        + " reason=wedged preMode=" + preReleaseMode
                        + " speed=" + playerVeh.Speed.ToString("F2"));
            }
            else if (secondFire)
            {
                assistSuspended = true;
                assistSuspendedSinceTicks = fnow; // iter-23 K4: auto-resume clock
                assistGraceUntilTicks = 0;
                assistResumeSpeedOkSinceTicks = 0;
                Speech.Critical("Drive assist suspended.");
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT assist-suspend:"
                        + " speed=" + playerVeh.Speed.ToString("F2")
                        + " pos=(" + playerVeh.Position.X.ToString("F1") + ","
                        + playerVeh.Position.Y.ToString("F1") + ")");
            }
            else
            {
                assistGraceUntilTicks = fnow + WATCHDOG_GRACE_TICKS;
                Speech.Info("Assist released. You have control.");
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT watchdog-grace:"
                        + " graceMs=" + (WATCHDOG_GRACE_TICKS / 10000));
            }
            if (driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT watchdog-release:"
                    + " heldMs=" + (WATCHDOG_HOLD_TICKS / 10000)
                    + " speed=" + playerVeh.Speed.ToString("F2")
                    + " pos=(" + playerVeh.Position.X.ToString("F1") + ","
                    + playerVeh.Position.Y.ToString("F1") + ")"
                    + " suspended=" + assistSuspended);
        }

        /// <summary>
        /// Calculates and CACHES steering/braking values. Does NOT apply inputs directly.
        /// Inputs must be applied every tick via ApplyCachedSteeringInputs().
        /// </summary>
        /// <param name="steerTTC">Time to collision for steering (includes side threats)</param>
        /// <param name="brakeTTC">Time to collision for braking (ONLY ahead threats)</param>
        /// <param name="brakeDistance">Distance to the closest braking threat</param>
        /// <param name="hasSteerThreat">Whether there's a steering threat (any direction)</param>
        /// <param name="hasBrakeThreat">Whether there's a braking threat (ahead only)</param>
        /// <param name="needsHandbrakeTurn">Whether a handbrake turn should be applied</param>
        /// <param name="handbrakeSteerDir">Direction for handbrake turn (-1=left, 1=right)</param>
        private void ApplySteeringAssist(Vehicle playerVeh, float steerTTC, float brakeTTC, float brakeDistance, int avoidDir, bool isFullMode, float steerThreshold, float brakeThreshold, bool hasSteerThreat, bool hasBrakeThreat, bool needsHandbrakeTurn = false, float handbrakeSteerDir = 0f)
        {
            float smoothFactor = Math.Min(1.0f, STEER_SMOOTHING_RATE * deltaTime);
            float targetSteer = 0f;
            float brakeMag = 0f;
            float handbrakeMag = 0f;

            // STEERING: Responds to threats from ANY direction (uses steerTTC)
            if (hasSteerThreat)
            {
                // NPC AI-inspired lateral offset avoidance: compute proportional steering
                // based on actual clearance deficit rather than binary left/right
                float lateralAvoid = 0f;
                float obstDist = closestThreatPosition != GTA.Math.Vector3.Zero
                    ? (closestThreatPosition - playerVeh.Position).Length() // iter-18 D3
                    : 15f;
                if (closestThreatPosition != GTA.Math.Vector3.Zero)
                {
                    lateralAvoid = CalculateLateralAvoidance(playerVeh, closestThreatPosition,
                        threatType, obstDist);
                }

                // Fall back to binary direction if lateral avoidance returns zero
                // (e.g., obstacle is from raycast with no clear position)
                if (Math.Abs(lateralAvoid) < 0.05f && avoidDir != 0)
                {
                    lateralAvoid = avoidDir * 0.5f; // Reduced fallback magnitude
                }

                float steerUrgency = Math.Max(0f, 1f - (steerTTC / steerThreshold));
                float maxSteer = isFullMode ? 1.0f : 0.75f;
                // Linear urgency (not squared) for smoother response curve
                targetSteer = lateralAvoid * steerUrgency * maxSteer;

                // STATIC OBSTACLES (rails/walls): snap to target with no smoothing
                // lag — rails are stationary so the target is stable, and the user
                // reported side collisions because the smoothed avoid took too long
                // to ramp up. Moving threats keep the smoothing to avoid jitter.
                if (threatType == "obstacle")
                {
                    smoothedSteerCorrection = targetSteer;
                }
                else
                {
                    smoothedSteerCorrection += (targetSteer - smoothedSteerCorrection) * smoothFactor;
                }
            }
            else
            {
                // No steer threat - decay obstacle avoidance
                smoothedSteerCorrection *= (1f - smoothFactor);
            }

            // BRAKING: ONLY responds to threats AHEAD (uses brakeTTC, separate from steering)
            // This is the KEY fix - side obstacles no longer cause braking!
            if (hasBrakeThreat)
            {
                float brakeUrgency = Math.Max(0f, 1f - (brakeTTC / brakeThreshold));
                // Iter-11 Patch K: speed-blended brake magnitude. The
                // squared-urgency curve is the right comfort shape at city
                // speed (gentle taper, low-urgency threats barely register)
                // but it's catastrophic at highway speed — urgency=0.4 squared
                // is only 0.16 brake, exactly the F6786 (-143.6 health)
                // catastrophic-impact pattern. Blend squared (low speed) into
                // linear (highway) so urgency=0.4 becomes 0.4 brake at >=20 m/s.
                float pSpeed = playerVeh.Speed;
                float speedBlend = Math.Min(1f, Math.Max(0f, (pSpeed - 8f) / 12f));
                float squaredMag = brakeUrgency * brakeUrgency;
                float linearMag = brakeUrgency;
                brakeMag = squaredMag * (1f - speedBlend) + linearMag * speedBlend;
            }
            // No else needed - brakeMag stays at 0 if no brake threat

            // HANDBRAKE TURN ASSISTANCE (Full mode only)
            if (needsHandbrakeTurn && isFullMode)
            {
                // Apply handbrake with corresponding steering for a controlled drift turn
                handbrakeMag = 0.8f; // Strong but not full handbrake

                // Boost steering in the direction of the handbrake turn
                float handbrakeSteerBoost = handbrakeSteerDir * 1.0f; // Full steering in turn direction
                smoothedSteerCorrection = smoothedSteerCorrection * 0.3f + handbrakeSteerBoost * 0.7f;

                // Light braking during handbrake turn
                brakeMag = Math.Max(brakeMag, 0.3f);
            }
            else
            {
                // Decay handbrake when not needed
                handbrakeMag = cachedHandbrakeMagnitude * (1f - smoothFactor * 2f);
            }

            // ROAD FOLLOWING: Apply road / alignment guidance.
            // Alignment and recovery modes use higher authority and faster
            // smoothing so the car actually rotates / pursues the recovery node
            // instead of nudging gently like normal lane-keeping.
            if (isOnValidRoad)
            {
                float roadStrength;
                float roadSmoothFactor;
                if (currentDriveMode != DriveMode.LaneKeeping)
                {
                    roadStrength = isFullMode ? 1.0f : 0.75f;
                    roadSmoothFactor = Math.Min(1.0f, STEER_SMOOTHING_RATE * 1.5f * deltaTime);
                    // Dampen obstacle avoidance during alignment so it can't fight
                    // the alignment steer (e.g. swerving away from a nearby wall
                    // while we're trying to U-turn out of trouble) — UNLESS a
                    // static obstacle (rail/wall) is an active threat, in which
                    // case avoidance must stay full strength so the car does not
                    // brush the rail while recovering.
                    if (!(hasSteerThreat && threatType == "obstacle"))
                        smoothedSteerCorrection *= 0.4f;
                }
                else
                {
                    // Tighter lane discipline in Full mode (was 0.65). User reported
                    // gradual drift off the road over time; 0.9 keeps the car planted
                    // in lane on long freeway stretches. Assist mode raised from
                    // 0.35 -> 0.6: at 0.35 the lane-keep correction was too weak to
                    // counter a developing skew (see fix A in the debug analysis).
                    roadStrength = isFullMode ? 0.9f : 0.6f;
                    // Speed the smoothing up as the heading error grows so the
                    // correction tracks Stanley's demand instead of lagging ~0.4 s.
                    // Gentle 0.5x rate on straights; up to 1.5x once skewed >=30 deg.
                    float skewMag = Math.Min(1f, Math.Abs(roadHeadingDelta) / 30f);
                    roadSmoothFactor = Math.Min(1.0f,
                        STEER_SMOOTHING_RATE * (0.5f + skewMag) * deltaTime);
                }
                float targetRoadSteer = roadSteerCorrection * roadStrength;
                smoothedRoadCorrection += (targetRoadSteer - smoothedRoadCorrection) * roadSmoothFactor;
            }
            else
            {
                // No valid road - decay road correction
                smoothedRoadCorrection *= (1f - smoothFactor);
            }

            // NPC AI-inspired CORNERING DAMPING: when actively following a road curve,
            // reduce obstacle avoidance aggression to prevent fighting the road following
            // (from fCorneringBrakeMultiplier / fCorneringSteerMultiplier concepts)
            if (isOnValidRoad && Math.Abs(roadSteerCorrection) > 0.3f)
            {
                float corneringDamping = 1.0f - Math.Min(0.4f, Math.Abs(roadSteerCorrection) * 0.5f);
                smoothedSteerCorrection *= corneringDamping;
            }

            // COMBINE (v3): road following is the BASE; obstacle avoidance is a
            // bounded additive correction. Previously the combine logic blended the
            // two by tier — under heavy raycast input that surfaced the "rail
            // attraction" failure mode (the obstacle layer dominated, then steered
            // off the rail INTO the rail). Now path-node lane-center wins by default,
            // and only an imminent threat with no adjacent latch can override it.
            float threatUrgency = hasSteerThreat ? Math.Max(0f, Math.Min(1f, 1f - (steerTTC / steerThreshold))) : 0f;
            // RAIL LANE-CONFLICT: closest steer threat is a STATIC obstacle and
            // the avoid direction is opposite the lane-keep pull. This is the
            // "drifting into the rail while lane-keep pulls toward it" pattern.
            // When detected, lift the avoid cap so the swerve actually wins.
            bool railLaneConflict = hasSteerThreat
                && threatType == "obstacle"
                && Math.Sign(smoothedSteerCorrection) != 0
                && Math.Sign(smoothedRoadCorrection) != 0
                && Math.Sign(smoothedSteerCorrection) != Math.Sign(smoothedRoadCorrection);
            // iter-33 B1: LANE-RETURN PRIORITY. railLaneConflict was built for the
            // ON-road rail-attraction case; when the car is already far OFF the
            // lane line it inverts into a deadlock — 07-02 F3588-F3737 sat 9-12 m
            // off Joshua Road for minutes with Stanley demanding +0.93 back while
            // a static roadside prop kept the swerve winning the combine in the
            // opposite direction (combinedSteer=-0.08). If the opposing-sign
            // conflict persists with a large lateral error at governed speed and
            // the threat is NOT imminent, the road pull must win: drop the
            // conflict override and pin the avoid contribution to a small cap.
            bool laneReturnConflict = railLaneConflict
                && Math.Abs(lastLaneLateralError) > LANE_RETURN_LAT_M
                && playerVeh.Speed < LANE_RETURN_MAX_SPEED
                && threatUrgency < 0.85f;
            laneReturnConflictMs = laneReturnConflict
                ? laneReturnConflictMs + deltaTime * 1000f : 0f;
            bool laneReturnPriority = laneReturnConflictMs > LANE_RETURN_SUSTAIN_MS;
            if (laneReturnPriority != laneReturnPriorityWasActive
                && driveLogger != null && driveLogger.IsRunning)
            {
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lane-return-priority:"
                    + " active=" + laneReturnPriority
                    + " lat=" + lastLaneLateralError.ToString("F1")
                    + " roadCorr=" + smoothedRoadCorrection.ToString("F2")
                    + " avoid=" + smoothedSteerCorrection.ToString("F2")
                    + " speed=" + playerVeh.Speed.ToString("F1"));
            }
            laneReturnPriorityWasActive = laneReturnPriority;
            if (laneReturnPriority) railLaneConflict = false;
            float combinedSteer;
            // iter-39 Stage 1C: remember how much of the combined command is the
            // ROAD/lane-keep term. The per-frame urgency rescale in
            // ApplyCachedSteeringInputs used to multiply the WHOLE command by an
            // unrelated threat's TTC, so a pedestrian three seconds away deleted
            // lane-keeping. Measured on 07-28 (first session with liveSteer logged):
            // of 643 frames commanding |steer| > 0.3, 126 were never written at all
            // — mean commanded 0.485, mean urgency 0.001 — and 71 more lost over
            // half their magnitude. Keeping this split lets the rescale touch only
            // the avoidance residual.
            float roadSteerPart = 0f;
            if (isOnValidRoad)
            {
                float baseSteer = smoothedRoadCorrection;
                // Cap the avoidance contribution so it can never fully reverse the
                // lane-keep — UNLESS a rail-lane conflict is active, in which case
                // let the swerve go to ±1.0 and halve the road pull. Under iter-33
                // lane-return priority the cap tightens further so the road pull
                // (±0.9) always dominates a static-prop swerve.
                float avoidCap = railLaneConflict ? 1.0f
                    : laneReturnPriority ? LANE_RETURN_AVOID_CAP : 0.6f;
                float avoid = Math.Max(-avoidCap, Math.Min(avoidCap, smoothedSteerCorrection));

                // Bypass the additive combine when the threat is imminent OR we
                // detected a rail-conflict — but still respect adjacent-vehicle
                // suppression so we don't swerve into another car.
                bool canFullyOverride = (threatUrgency > 0.85f || railLaneConflict)
                    && !(avoid > 0 && adjacentLatchedRight)
                    && !(avoid < 0 && adjacentLatchedLeft);
                if (canFullyOverride)
                {
                    combinedSteer = smoothedSteerCorrection;
                }
                else
                {
                    float roadWeight = railLaneConflict ? 0.5f : 1.0f;
                    combinedSteer = baseSteer * roadWeight + avoid;
                    roadSteerPart = baseSteer * roadWeight;
                }
            }
            else
            {
                // No valid road — obstacle avoidance is all we have, but still
                // honor the adjacent-vehicle suppression.
                float avoid = smoothedSteerCorrection;
                if (avoid > 0 && adjacentLatchedRight) avoid = 0f;
                if (avoid < 0 && adjacentLatchedLeft) avoid = 0f;
                combinedSteer = hasSteerThreat ? avoid : avoid * 0.5f;
            }

            combinedSteer = Math.Max(-1f, Math.Min(1f, combinedSteer));

            // STEERING RATE LIMIT — history-aware slew to dampen the
            // "avoidance jolt" cluster from the failure audit.
            // Three rates (per second, deltaTime-scaled so frame-rate-independent):
            //   normal       — gentle, used when there is no urgent threat.
            //   emergency    — fast enough to reach ~0.8 in ~200 ms (avoids
            //                  the F11613 case where a slow clamp steered
            //                  INTO an obstacle) but no longer a single-frame
            //                  slam (audit C1: drivers felt the jolt and
            //                  marked it as a lane-keep failure).
            //   railconflict — keeps the prior single-frame priority for
            //                  rail-mounted vehicles where flip-around is
            //                  the only escape.
            // Fatigue damping: if history shows we've already been swinging
            // hard in the last ~200 ms, pull the slew down. Repeated big
            // swings ARE the oscillation pattern.
            const float STEER_SLEW_NORMAL_PER_SEC       = MAX_STEER_RATE * 3f;
            const float STEER_SLEW_EMERGENCY_PER_SEC    = 4.0f;
            const float STEER_SLEW_RAILCONFLICT_PER_SEC = 6.0f;

            bool emergencySwerve = threatUrgency > 0.85f;
            float slewPerSec =
                railLaneConflict ? STEER_SLEW_RAILCONFLICT_PER_SEC :
                emergencySwerve  ? STEER_SLEW_EMERGENCY_PER_SEC    :
                                   STEER_SLEW_NORMAL_PER_SEC;
            if (MaxAbsSteerCmdInLastMs(HISTORY_WINDOW_MS) > 0.6f)
                slewPerSec *= 0.6f;

            float maxSteerDelta = slewPerSec * deltaTime;
            float steerDelta = combinedSteer - previousFrameSteer;
            bool steerRateClamped = false;
            // Persistent-skew escalation: if we've been pinned >50 deg off-axis
            // for >2 s, comfort no longer matters. Let the saturated correction
            // execute in one frame so the car can actually un-skew.
            if (Math.Abs(steerDelta) > maxSteerDelta && !bypassSteerRateClampThisFrame)
            {
                combinedSteer = previousFrameSteer + Math.Sign(steerDelta) * maxSteerDelta;
                steerRateClamped = true;
            }
            previousFrameSteer = combinedSteer;

            // Emergency stop - ONLY for brake threats (ahead), not side threats
            // Also require the obstacle to be close enough that braking makes sense
            if (hasBrakeThreat && brakeTTC < 0.5f && brakeDistance < 15f)
            {
                brakeMag = 1.0f;
            }

            // Cache values for per-tick application - use combined steering
            cachedSteerCorrection = combinedSteer;
            // iter-39 Stage 1C: clamp the remembered road part into the same range
            // the combined command was clamped to, so the residual below is sane.
            cachedRoadSteerPart = Math.Max(-1f, Math.Min(1f, roadSteerPart));
            cachedBrakeMagnitude = brakeMag;
            cachedAvoidDirection = avoidDir;
            cachedHandbrakeMagnitude = handbrakeMag;
            // Track if system is braking - used to block player throttle in full mode
            cachedIsBraking = (brakeMag > 0.1f || handbrakeMag > 0.1f);

            // iter-35 L5: thin fully-idle lines (no threat, no output — 694 of 3,978
            // on 07-03) to every 30th; any threat or output logs every scan as before.
            // iter-36 P2-1: UNCHANGED outputs are as uninformative as zero outputs —
            // 15,625 apply-assist lines (~5 MB of the 87 MB log) were mostly a pinned
            // car re-printing byte-identical values 30x/s. Also idle when every
            // output is within 0.005 of the last WRITTEN line and the threat flags
            // match; the 1-in-30 keep-alive still records the held values.
            bool applyAssistIdle = (!hasSteerThreat && !hasBrakeThreat
                && brakeMag < 0.005f && handbrakeMag < 0.005f
                && Math.Abs(combinedSteer) < 0.005f)
                || (Math.Abs(combinedSteer - lastApplyAssistSteerWritten) < 0.005f
                    && Math.Abs(brakeMag - lastApplyAssistBrakeWritten) < 0.005f
                    && Math.Abs(handbrakeMag - lastApplyAssistHbWritten) < 0.005f
                    && hasSteerThreat == lastApplyAssistSteerThreatWritten
                    && hasBrakeThreat == lastApplyAssistBrakeThreatWritten);
            if (applyAssistIdle) applyAssistIdleSkipped++;
            else applyAssistIdleSkipped = 0;
            bool applyAssistWrite = driveLogger != null && driveLogger.IsRunning
                && (!applyAssistIdle || applyAssistIdleSkipped % 30 == 1);
            if (applyAssistWrite)
            {
                lastApplyAssistSteerWritten = combinedSteer;
                lastApplyAssistBrakeWritten = brakeMag;
                lastApplyAssistHbWritten = handbrakeMag;
                lastApplyAssistSteerThreatWritten = hasSteerThreat;
                lastApplyAssistBrakeThreatWritten = hasBrakeThreat;
            }
            if (applyAssistWrite)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT apply-assist:"
                    + (applyAssistIdle && applyAssistIdleSkipped > 1
                        ? " idleSkipped=" + (applyAssistIdleSkipped - 1) : "")
                    + " steerTTC=" + FmtF(steerTTC) + " brakeTTC=" + FmtF(brakeTTC)
                    // iter-41 Stage 0.10: raw ToString on the no-threat sentinel
                    // printed float.MaxValue as 39 digits on nearly every line, and
                    // apply-assist is 10,086 lines = 91.7% of events.log (3.21 MB of
                    // 3.50 MB). The neighbouring brakeTTC already used FmtF.
                    + " brakeDist=" + FmtF(brakeDistance)
                    + " aReq=" + lastBrakeAReq.ToString("F2")
                    + " tCpa=" + (lastBrakeTcpa >= 0f ? lastBrakeTcpa.ToString("F2") : "-")
                    + " cpaMiss=" + (lastBrakeCpaMiss >= 0f ? lastBrakeCpaMiss.ToString("F2") : "-")
                    + " gapBumper=" + (lastBrakeGapBumper >= 0f ? lastBrakeGapBumper.ToString("F1") : "-")
                    + " hasSteerThreat=" + hasSteerThreat + " hasBrakeThreat=" + hasBrakeThreat
                    + " avoidDir=" + avoidDir + " railConflict=" + railLaneConflict
                    + " combinedSteer=" + combinedSteer.ToString("F3")
                    + " rateClamped=" + steerRateClamped
                    + " brakeMag=" + brakeMag.ToString("F3")
                    + " handbrakeMag=" + handbrakeMag.ToString("F3")
                    + " mode=" + currentDriveMode + " fullMode=" + isFullMode);

            // Audio/speech feedback (only for threats, not lane keeping)
            bool hasThreat = hasSteerThreat || hasBrakeThreat;
            if ((hasThreat || needsHandbrakeTurn) && DateTime.Now.Ticks - lastThreatCueTicks > 20000000)
            {
                lastAssistAnnounceTicks = DateTime.Now.Ticks;

                float steerUrgency = Math.Max(0f, 1f - (steerTTC / steerThreshold));
                outSteerAssist.Stop();
                steerAssistBeep.Frequency = 400 + (int)(steerUrgency * 600);
                var sample = steerAssistBeep.Take(TimeSpan.FromSeconds(0.08));
                outSteerAssist.Init(sample);
                outSteerAssist.Play();

                if (handbrakeMag > 0.5f)
                {
                    string turnDir = handbrakeSteerDir > 0 ? "right" : "left";
                    Speech.Info("Handbrake turn " + turnDir);
                }
                // iter-19 G6: SEVERITY-GATED speech. The old gate (brakeMag>0.5 OR
                // |steer|>0.3) spoke "Braking, obstacle ahead" ~1x/s during normal
                // cruising — routine cornering corrections are +/-0.3-0.9 and far
                // mild threats produce brief brake taps. Tiers: severe "Braking"
                // needs real physics (aReq >= 3.5 m/s^2 or TTC < 1 s, the iter-18
                // telemetry threshold that correlates with genuine braking); mild
                // gets a calm "Slowing"; steering callouts need |steer| > 0.5.
                // First control-path consumer of lastBrakeAReq — speech-only by
                // design, staging toward the planned aReq brake arbiter.
                // "Hard braking!" / "Emergency brake!" critical tier unchanged.
                else if (brakeMag > 0.5f
                         && (lastBrakeAReq >= SPEECH_AREQ_SEVERE || brakeTTC < 1.0f)
                         && DateTime.Now.Ticks - lastBrakeSpeechTicks > 50000000) // 5 s
                {
                    lastBrakeSpeechTicks = DateTime.Now.Ticks;
                    Speech.Info("Braking, " + threatType + " " + threatDirection);
                }
                else if (brakeMag > 0.3f && lastBrakeAReq >= SPEECH_AREQ_MILD
                         && DateTime.Now.Ticks - lastSlowSpeechTicks > 100000000) // 10 s
                {
                    lastSlowSpeechTicks = DateTime.Now.Ticks;
                    Speech.Info(threatType == "vehicle" ? "Slowing for traffic" : "Slowing");
                }
                else if (Math.Abs(smoothedSteerCorrection) > 0.5f && hasSteerThreat
                         && DateTime.Now.Ticks - lastSteerSpeechTicks > 80000000) // 8 s
                {
                    lastSteerSpeechTicks = DateTime.Now.Ticks;
                    Speech.Info("Steering, " + threatType + " " + threatDirection);
                }
            }
        }

        /// <summary>
        /// Applies cached steering/braking inputs. MUST be called every tick for inputs to work!
        /// GTA V's SET_CONTROL_NORMAL only applies for a single frame.
        /// </summary>
        /// <summary>Adaptive cruise control. Runs once per detection scan; updates
        /// accThrottleOut / accBrakeOut which ApplyCachedSteeringInputs applies
        /// every tick. PID-controls headway behind the nav-assist lead vehicle.
        /// Comfort-level only — emergency braking stays with the threat path.</summary>
        private void ComputeACC(Vehicle veh, bool isFullMode)
        {
            bool haveLead = navAssistVehicleCenter != null && navAssistVehicleCenter.Exists();
            // W2.2: the ACC lead is the nav-assist CENTER bin, a +/-60 deg cone. A
            // car-follower must not adopt a vehicle 60 deg off-axis as its lead;
            // require it in the (narrow) brake cone so ACC only regulates a real
            // ahead-obstruction.
            bool accStandstillRelease = getSetting("accStandstillRelease") == 1;
            // Only reject an off-corridor lead at LOW SPEED, where an ACC pin happens
            // and a real lead is directly ahead (lateral ~0). At following speed the
            // +/-60 deg bin is kept so a lead on a curve still regulates headway
            // (IsInBrakeCone is a tight ~1.5 m corridor — too tight for long range).
            if (haveLead && accStandstillRelease && veh.Speed < 3f
                && !IsInBrakeCone(veh, navAssistVehicleCenter.Position))
                haveLead = false;
            if (!isFullMode || getSetting("adaptiveCruise") != 1 || !haveLead)
            {
                accIntegral = 0f;
                accPrevError = 0f;
                accPrevTicks = 0;
                accThrottleOut = 0f;
                accBrakeOut = 0f;
                lastAccLeadHandle = 0;
                accStandstillSinceTicks = 0;
                return;
            }

            long now = DateTime.Now.Ticks;
            int leadHandle = navAssistVehicleCenter.Handle;
            // New lead vehicle — reset PID state to avoid a throttle spike on handoff.
            if (leadHandle != lastAccLeadHandle)
            {
                accIntegral = 0f;
                accPrevError = 0f;
                accPrevTicks = 0;
                lastAccLeadHandle = leadHandle;
            }

            float speed = veh.Speed;
            float desiredGap = Math.Max(ACC_MIN_GAP_M, speed * ACC_TIME_GAP);
            float error = navAssistDistCenter - desiredGap; // +ve = too far, accelerate

            float dt = accPrevTicks == 0 ? 0.05f : (now - accPrevTicks) / 10000000f;
            if (dt < 0.016f) dt = 0.016f;
            else if (dt > 0.2f) dt = 0.2f;

            accIntegral += error * dt;
            if (accIntegral > ACC_I_CLAMP) accIntegral = ACC_I_CLAMP;
            else if (accIntegral < -ACC_I_CLAMP) accIntegral = -ACC_I_CLAMP;
            float deriv = (error - accPrevError) / dt;
            float u = ACC_KP * error + ACC_KI * accIntegral + ACC_KD * deriv;
            accPrevError = error;
            accPrevTicks = now;

            if (u >= 0f)
            {
                accThrottleOut = Math.Min(1f, u);
                accBrakeOut = 0f;
            }
            else
            {
                accThrottleOut = 0f;
                accBrakeOut = Math.Min(1f, -u);
            }

            // Speed cap: never accelerate past the configured cruise speed.
            if (speed >= autodriveSpeed) accThrottleOut = 0f;

            // ---- iter-43 B2: honour a latched standstill release ----
            // Cleared by the lead genuinely moving off, or by the player lifting —
            // either of which means the situation the latch was covering is over.
            // Never suppresses a real threat brake: brakeArmed/emergencyBrakeActive
            // are independent of accBrakeOut.
            if (accReleaseLatched)
            {
                Vehicle accLead = navAssistVehicleCenter;
                bool leadMovedOff = accLead != null && accLead.Exists()
                    && accLead.Speed > ACC_RELEASE_MOVED_SPEED;
                float stillAsking = Math.Max(
                    Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71),
                    Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 71));
                // Own speed clears it too: this latch exists to break a STANDSTILL
                // limit cycle, so once the car is genuinely rolling the situation it
                // covers is over. Without this a driver who simply keeps the pedal
                // down after escaping would carry the latch onto the highway and
                // silently lose ACC's comfort braking for the rest of the drive.
                if (leadMovedOff || stillAsking <= 0.05f
                    || speed > ACC_RELEASE_MOVED_SPEED)
                {
                    accReleaseLatched = false;
                }
                else
                {
                    accBrakeOut = 0f;
                    accIntegral = 0f;
                    accPrevError = 0f;
                }
            }

            // W2.2: STANDSTILL RELEASE. At a standstill the gap can never grow, so
            // ComputeACC would hold accBrakeOut forever, which pins the car and (via
            // throttleLockoutActive downstream) kills the pedal while an NPC grinds
            // it -> both iter-35 deaths. Yield the comfort brake the instant the
            // player asks to move, or after a bounded hold. This does NOT disable a
            // real threat brake: brakeArmed/emergencyBrakeActive are independent of
            // accBrakeOut, so a genuine imminent contact still holds.
            if (accStandstillRelease && speed < STUCK_SPEED_THRESHOLD && accBrakeOut > 0.01f)
            {
                float playerGo = Math.Max(
                    Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71),
                    Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 71));
                if (accStandstillSinceTicks == 0) accStandstillSinceTicks = now;
                // Release on player intent always; release on timeout ONLY when
                // corroborated by fresh damage, so a benign red-light/traffic hold
                // (no intent, no damage) keeps its comfort brake and cannot drift.
                bool damageFresh = DamageActiveRecently(now, STUCK_OFFROAD_TICKS);
                // ---- iter-41 Stage 1b accStandstillV2 ----
                // The timeout path was doubly dead. (1) damageFresh is stamped only
                // by a >=2.0 single-frame drop, and this build bleeds ~1.0 per frame,
                // so it was false all session. (2) The hold clock is zeroed in the
                // else-branch below whenever speed rises past STUCK_SPEED_THRESHOLD
                // (0.7 m/s) — but the release's OWN creep tops out around that speed,
                // so release -> creep -> clock reset -> re-brake -> release, ~1 Hz
                // forever. Max heldMs across the whole 07-28 session was 149 ms
                // against a 2000 ms timeout: it could never have fired.
                //
                // Require a REAL move (not the release's own creep) before the clock
                // resets, and replace the damage corroboration with a positive
                // "nothing is actually in the way" test.
                bool accV2 = getSetting("accStandstillV2") == 1;
                if (accV2) GateReach("accStandstillV2");
                // Same liveness test ApplyCachedSteeringInputs uses; that one is a
                // local in another method, so recompute it rather than widen scope.
                bool accLiveBrakeThreat = cachedBrakeThreatPos != GTA.Math.Vector3.Zero
                    && (now - cachedBrakeThreatStamp) < ThreatCacheValidTicksForSpeed(speed);
                bool pathActuallyClear = !accLiveBrakeThreat && !emergencyBrakeActive
                    && navAssistDistCenter < 900f            // never on the nocast sentinel
                    && navAssistDistCenter > ACC_RELEASE_MIN_CLEAR_M;
                bool heldTooLong = (now - accStandstillSinceTicks > ACC_STANDSTILL_MAX_TICKS)
                    && (accV2 ? pathActuallyClear : damageFresh);
                if (accV2 && heldTooLong) GateFire("accStandstillV2");
                if (playerGo > 0.25f || heldTooLong)
                {
                    if (driveLogger != null && driveLogger.IsRunning
                        && now - lastAccReleaseLogTicks > 10000000L)
                    {
                        lastAccReleaseLogTicks = now;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT acc-release:"
                            + " reason=" + (playerGo > 0.25f ? "player" : "timeout")
                            + " leadGap=" + navAssistDistCenter.ToString("F1")
                            + " heldMs=" + ((now - accStandstillSinceTicks) / 10000)
                            + " leadClear=" + pathActuallyClear
                            + " playerGo=" + playerGo.ToString("F2"));
                    }
                    accBrakeOut = 0f;
                    accIntegral = 0f;   // don't let it immediately re-wind
                    accPrevError = 0f;
                    // ---- iter-43 B2: LATCH THE RELEASE ----
                    // Zeroing accBrakeOut lasts exactly one frame; ComputeACC
                    // recomputes it on the next tick and re-brakes, because a
                    // stationary lead inside the gap makes the error permanently
                    // negative. On 07-31 that produced a release/re-hold cycle at
                    // ~1 Hz for 41.5 s while the player held full throttle and the
                    // gap sat at a constant 5.2-5.4 m. Once the player has
                    // overridden at a standstill, stay released until the lead
                    // actually moves or the player lifts off.
                    if (accV2 && playerGo > 0.25f) accReleaseLatched = true;
                }
            }
            else
            {
                // iter-41 Stage 1b: only a genuine move clears the hold clock. The
                // release's own creep sits right at STUCK_SPEED_THRESHOLD, so the
                // unconditional reset let the release erase its own evidence and the
                // timeout could never mature.
                if (getSetting("accStandstillV2") == 1 && veh != null)
                {
                    if (veh.Speed >= ACC_RELEASE_MOVED_SPEED)
                    {
                        if (accMoveSinceTicks == 0) accMoveSinceTicks = now;
                        if (now - accMoveSinceTicks >= ACC_RELEASE_MOVED_TICKS)
                            accStandstillSinceTicks = 0;
                    }
                    else accMoveSinceTicks = 0;
                }
                else accStandstillSinceTicks = 0;
            }
        }

        private void ApplyCachedSteeringInputs(Vehicle playerVeh)
        {
            // _SET_CONTROL_NORMAL: 0xE8A25867FBA3B05E
            // Control IDs: 59=Steer, 71=Accelerate, 72=Brake, 76=Handbrake

            long nowStamp = DateTime.Now.Ticks;
            driveAssistFrameTicks = nowStamp; // stable reference for all history queries this frame
            controlWriteLog.Length = 0; // iter-39 L1: start this frame's control-write trace
            // iter-41 Stage 0.1: close out the PREVIOUS frame's throttle-hold state
            // before clearing it — by this point every disable-71 site of that frame
            // has run, so the ledger sees a complete picture.
            thrHoldSitesPrevFrame = thrHoldSitesThisFrame;
            UpdateThrottleHoldLedger(nowStamp, playerVeh);
            UpdateImmobileUnderThrottle(nowStamp, playerVeh); // iter-41 Stage 0.7
            thrHoldSitesThisFrame = 0;
            // iter-39: read once — consulted by the brake ramp, the demand caps and
            // the control-disable block further down, which must all agree.
            bool actuationV2 = getSetting("actuationV2") == 1;
            // iter-46 1-1: actuationV2 is read on EVERY frame and is the reason this
            // build's aPeak is 12.51 m/s2 — yet it censused eval:0/fire:0 all session
            // on both 07-31 and 08-01, because no GateReach call existed. That single
            // observation is the proof that "SILENT — never reached" was an
            // instrumentation artifact and not a behavioural verdict, and it is why
            // no gate could be deleted on the old table.
            if (actuationV2) GateReach("actuationV2");
            // iter-40 group flags — read once per frame, same rationale as above.
            // Each is independently revertible in-game so a single bad group can be
            // isolated from a session's results without a rebuild.
            bool reverseV2 = getSetting("reverseV2") == 1;
            bool graceArbitrationV2 = getSetting("graceArbitrationV2") == 1;

            // ---- iter-19 G1: SCAN-STALENESS DEAD-MAN ----
            // If the detection scan has not COMPLETED recently, every scan-owned
            // request below is untrustworthy (215409: curveBrakeRequest=0.476 held
            // the brake + throttle lock for 8+ s after the last scan). Zero them,
            // let rampedBrakeInput decay through the normal down-ramp, and skip all
            // input disables this frame so the player is never locked out by a dead
            // pipeline. Normal cadence is 30-50 ms; 600 ms = 12+ missed scans.
            // While stopped at a light with ACC the alive-gate keeps the scan
            // running, so this cannot fire in legitimate stops.
            bool scanStale = lastScanCompletedTicks > 0
                && (ModClock.Ticks - lastScanCompletedTicks) > SCAN_STALE_TICKS; // ModClock pair
            if (scanStale)
            {
                curveBrakeRequest = 0f;
                recoveryBrakeRequest = 0f;
                cachedBrakeMagnitude = 0f;
                cachedBrakeThreatPos = GTA.Math.Vector3.Zero; // kills hasLiveBrakeThreat below
                cachedSteerThreatPos = GTA.Math.Vector3.Zero;
                cachedSteerCorrection = 0f;
                cachedHandbrakeMagnitude = 0f;
                emergencyBrakeActive = false;
                brakeArmed = false;
                alignmentEngageReverse = false;
                accThrottleOut = 0f;
                accBrakeOut = 0f;
                if (driveLogger != null && driveLogger.IsRunning
                    && nowStamp - lastScanStaleLogTicks > 20000000) // 2 s throttle
                {
                    lastScanStaleLogTicks = nowStamp;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT scan-stale-release:"
                        + " ageMs=" + ((ModClock.Ticks - lastScanCompletedTicks) / 10000)
                        + " rampedBrake=" + rampedBrakeInput.ToString("F2"));
                }
            }
            // iter-19 G2: grace flag for this frame (watchdog released the assist;
            // the player is sovereign until it expires or stuck-arm cancels it).
            bool graceActive = InWatchdogGrace();

            // Fire any deferred rumble pulses (e.g. the second half of a
            // right-side double pulse) that have come due since last tick.
            DrainRumbleQueue();

            // REVERSE-AWARE BRAKING: GTA control 72 (VEH_BRAKE) only brakes a
            // car moving FORWARD — on a car rolling backward it is the reverse
            // throttle and ACCELERATES the backward motion. When the car is
            // reversing and this is NOT a commanded reverse maneuver, every
            // brake request must instead arrest the backward roll via control
            // 71 (accelerate) + the direction-agnostic handbrake (76).
            bool brakingAReversingCar = isReversing && !alignmentEngageReverse;

            // ---- PER-FRAME BRAKE RECOMPUTE ----
            // If we have a recent brake threat, recompute its TTC against the LIVE
            // vehicle speed/position. This is what the user asked for: "really inform
            // the drive assist with the current MPH speed and apply adjustments every
            // frame." Between full ProcessSteeringAssist scans (~50 ms cadence), the
            // player's speed can change dramatically — without this recompute, the
            // brake input would lag a full detection cycle.
            float liveBrakeTarget = cachedBrakeMagnitude;
            float liveTtc = float.MaxValue;
            // Iter-11 Patch J: speed-scaled cache validity — at highway speed
            // a 250 ms-old threat pos is 4-6 m off, exactly the F2894 (-102.6
            // health) error magnitude.
            long brakeCacheValidTicks = ThreatCacheValidTicksForSpeed(playerVeh.Speed);
            bool hasLiveBrakeThreat = cachedBrakeThreatPos != GTA.Math.Vector3.Zero
                && (nowStamp - cachedBrakeThreatStamp) < brakeCacheValidTicks;
            if (hasLiveBrakeThreat)
            {
                liveTtc = CalculateTTC(playerVeh, cachedBrakeThreatPos, cachedBrakeThreatVel);
                // Map TTC → brake magnitude: <0.4s = full, <1.5s = ramped, >1.5s = none.
                if (liveTtc < 0.4f)
                    liveBrakeTarget = 1.0f;
                else if (liveTtc < 1.5f)
                    liveBrakeTarget = 1.0f - ((liveTtc - 0.4f) / 1.1f);
                else
                    liveBrakeTarget = 0f;
            }

            // ---- BRAKE HYSTERESIS (arm/release) ----
            // Once armed, stay armed until TTC clears comfortably above the release
            // threshold — prevents single-frame brake taps when TTC oscillates.
            // Arm-TTC scales with speed: fixed 0.8s gave only 24 m of arming
            // distance at 30 m/s, which can't beat reaction + stopping.
            //   v=8  -> 0.8s / 1.6s   (city, matches old behavior)
            //   v=20 -> 1.1s / 2.2s
            //   v=30 -> 1.35s / 2.7s
            //   v>=56 -> 2.0s / 4.0s  (capped)
            float liveSpeed = playerVeh.Speed;
            float armTtc = Math.Min(2.0f, Math.Max(BRAKE_ARM_TTC, 0.025f * liveSpeed + 0.6f));
            float releaseTtc = armTtc * 2.0f;
            if (hasLiveBrakeThreat && liveTtc <= armTtc) brakeArmed = true;
            // iter-16 FIX 1: release the arm when the car is essentially stopped and the
            // threat is NOT imminent. CalculateTTC fabricates an artificial TTC of
            // distance/3 for a stopped car facing a static obstacle <5 m; at rest that
            // lands in the hysteresis DEAD-BAND (armTtc~0.8 < ttc < releaseTtc~1.6), so
            // brakeArmed never released and a partial brake (0.19@3.9 m, 0.54@2.7 m) was
            // held forever, locking the blind player's throttle (185543 #6-8, 232604 #1).
            // A stopped car has no kinetic energy to manage; releasing is safe because the
            // instant the player accelerates (Speed>1) CalculateTTC switches to the live
            // closing-speed path and re-arms before any real impact, and emergencyBrake
            // still overrides below for genuinely imminent (<0.4 s) threats.
            else if (!hasLiveBrakeThreat || liveTtc >= releaseTtc
                     || (liveSpeed < STOPPED_RELEASE_SPEED && liveTtc > armTtc))
                brakeArmed = false;

            // iter-19 G2: during watchdog grace the player is sovereign — no brake
            // arming unless the threat is genuinely imminent (<0.4 s live TTC). A
            // real emergency still brakes (via SetControlNormal below), but never
            // via input disables (gated by inputDisablesAllowed).
            // iter-24 U1: EXCEPTION — a close obstacle at crawl speed re-arms the
            // threat brake even during grace, so the assist stops nudging peds in a
            // dense crowd (06-12 #12-15). Conservative: <8 m/s and within 6 m only.
            bool graceLowSpeedClose = hasLiveBrakeThreat
                && liveSpeed < GRACE_LOWSPEED_MS
                && (cachedBrakeThreatPos - playerVeh.Position).Length() < GRACE_LOWSPEED_BRAKE_DIST;
            if (graceActive && graceLowSpeedClose)
            {
                brakeArmed = true;
                if (driveLogger != null && driveLogger.IsRunning
                    && DateTime.Now.Ticks - lastGraceBrakeLogTicks > 10000000L)
                {
                    lastGraceBrakeLogTicks = DateTime.Now.Ticks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT grace-brake-allow:"
                        + " dist=" + (cachedBrakeThreatPos - playerVeh.Position).Length().ToString("F1")
                        + " speed=" + liveSpeed.ToString("F1")
                        + " ttc=" + liveTtc.ToString("F2"));
                }
            }
            else if (graceActive && !(liveTtc > 0f && liveTtc < 0.4f)) brakeArmed = false;

            // Emergency latch overrides hysteresis.
            if (emergencyBrakeActive) { brakeArmed = true; liveBrakeTarget = 1.0f; }

            // ---- PRE-IMPACT WARNING BEEP ----
            // Saw-wave middle-C that ramps with TTC. Plays in the window before the
            // brake actually engages so the user can react (or brace).
            // iter-35 P1(c): the old cachedHandbrakeMagnitude<0.1 clause muted the beep
            // during the assist's OWN handbrake turns — both 07-03 plow collisions
            // (#4/#8) reached the wall in silence. Only a deliberate pivot escape
            // suppresses the warning now.
            // iter-35 P4: warn window opens with the speed-scaled arm TTC (x1.6) so a
            // highway threat starts beeping ~2 s out; TTC above BRAKE_WARN_TTC_MAX
            // clamps to the gentle band inside PlayBrakeWarning.
            float warnTtcMax = Math.Max(BRAKE_WARN_TTC_MAX, armTtc * 1.6f);
            bool warningOk = hasLiveBrakeThreat
                && liveTtc < warnTtcMax
                && liveTtc > 0f
                && !pivotEscapeActive
                && steeringAssistActive;
            if (warningOk) PlayBrakeWarning(liveTtc);
            else FlushBeepEpisode();

            // Disarmed = no autobrake (gates failed). Hard zero the target so the
            // ramp decays even if cachedBrakeMagnitude was set by a stale scan.
            if (!brakeArmed && !emergencyBrakeActive) liveBrakeTarget = 0f;

            // iter-25 M7: remember when the assist last threat-braked. The auto-creep
            // only arms after a CLEARED-HAZARD stop (this stamp is recent), never at a
            // red light / deliberate park (which never set brakeArmed/emergencyBrake).
            if (brakeArmed || emergencyBrakeActive) lastAssistBrakeTicks = DateTime.Now.Ticks;

            // ---- RECOVERY BRAKING ----
            // Recovery braking is NOT threat-gated — the car must slow to make a
            // tight realignment turn feasible. Applied after the disarm zero so
            // the threat-brake gates can't cancel it. Still goes through the ramp.
            if (recoveryBrakeRequest > liveBrakeTarget) liveBrakeTarget = recoveryBrakeRequest;

            // ---- CURVE BRAKING ----
            // Pre-emptive slow-down before a sharp bend (Full mode only). Like
            // recovery braking it is not threat-gated; it rides the same ramp.
            if (cachedIsFullMode && curveBrakeRequest > liveBrakeTarget)
                liveBrakeTarget = curveBrakeRequest;

            // ---- iter-16 FIX 6: EXTREME-SKEW EMERGENCY BRAKE ----
            // A car sideways at speed has lost the road/bend and will plow forward into
            // whatever is ahead (185543 -33.3: 8 m/s at -130 deg skew into a prop, the
            // recovery brake engaging only ~0.1 s before impact). Unlike the
            // CURVE_BRAKE_MAX-capped skew floor in ComputeCurveBrake, this is an
            // EMERGENCY: full, uncapped brake to kill speed BEFORE recovery formally
            // engages, turning a forward plow into a stop the car can pivot out of at
            // low speed. Gated above normal cornering skew and pivot speed; not applied
            // to a COMMANDED reverse (the U-turn is intentionally skewed).
            if (cachedIsFullMode
                && !graceActive // iter-19 G2: player sovereign during grace
                && !alignmentEngageReverse
                && Math.Abs(roadHeadingDelta) > SKEW_EMERGENCY_ANGLE
                && playerVeh.Speed > SKEW_EMERGENCY_SPEED)
            {
                liveBrakeTarget = 1.0f;
            }

            // ---- iter-30 P3: OFF-ROAD RE-ACCELERATION CAP ----
            // After a high-speed off-road crash (iter-29 #3) recovery exited to LaneKeeping
            // and the car re-accelerated 3 -> 24 m/s while still off-road and skewed,
            // driving into a 2nd impact (-158 bh). Cap speed while genuinely off-road AND in
            // a loss-of-control state (took body damage in the last ~3 s OR badly skewed) so
            // the car sheds speed toward a controllable crawl instead of building speed with
            // no road under it. The corroboration keeps normal rural-dirt cruising (aligned,
            // undamaged) untouched. Released the instant the off-road timer clears.
            if (cachedIsFullMode && !graceActive && !alignmentEngageReverse
                && offRoadStartTicks > 0
                && playerVeh.Speed > OFFROAD_REACCEL_MAX_SPEED)
            {
                long p3Now = DateTime.Now.Ticks;
                bool p3RecentCrash = lastBodyDropTicks > 0 && (p3Now - lastBodyDropTicks) < STUCK_OFFROAD_TICKS;
                bool p3Skewed = Math.Abs(roadHeadingDelta) > 30f;
                if (p3RecentCrash || p3Skewed)
                {
                    float p3Need = Math.Min(1.0f, 0.4f + (playerVeh.Speed - OFFROAD_REACCEL_MAX_SPEED) / 10f);
                    if (p3Need > liveBrakeTarget) liveBrakeTarget = p3Need;
                }
            }

            // ---- iter-34 LOW-7: OFF-ROAD BRAKE FLOOR ----
            // A car scraping along 24 m off the road at 5-6 m/s ran brake=0.00 all
            // the way (07-03 incidents A/D). Unlike P3 above (a high-speed cap with
            // crash/skew corroboration) this is a gentle floor at any off-road speed
            // above a crawl, skipped during intentional maneuvers so it can't fight
            // a handbrake turn or a commanded reverse.
            // ---- iter-41 Stage 6a offroadBrakeV2 ----
            // This floor exists for exactly the 07-28 scrape (4.0 s off-road at
            // 7-18 m/s, 15 body points) and never fired, because offRoadStartTicks is
            // stamped from ROAD-NODE DISTANCE (CheckRoadTeleport, > ~10 m from a
            // node), not from whether the car is on a road SURFACE. At |lat| 6.5 the
            // car was still within 10 m of a node, so the stamp stayed 0 while the
            // car ground along the shoulder. Arm from ground truth as well.
            //
            // ModClock deliberately: this pairs with offRoadStartTicks, which
            // CheckRoadTeleport stamps from ModClock. Mixing wall clock here is the
            // exact bug class the project forbids.
            bool offroadBrakeV2 = getSetting("offroadBrakeV2") == 1;
            bool offRoadFloorArmed = offRoadStartTicks > 0;
            if (offroadBrakeV2 && cachedIsFullMode && playerVeh != null)
            {
                GateReach("offroadBrakeV2");
                // The |lat| conjunct is what keeps dirt roads out: iter-23 proved
                // IS_POINT_ON_ROAD reads False on Sandy Shores surfaces, but there the
                // graph still sees the road, the polyline snaps to it and |lat| stays
                // small. A genuine departure has both.
                bool surfaceOff = !IsPositionOnRoad(playerVeh.Position)
                    && Math.Abs(lastLaneLateralError) > LANE_DEPART_LAT_M;
                // iter-49 A4: a tunnel is not a field. IS_POINT_ON_ROAD reads
                // False under a lot of covered road, and the polyline snapping to
                // the surface street overhead supplies the large |lat| that
                // completes the conjunct — so the pair that is supposed to mean
                // "genuinely departed" both fire inside a tunnel at speed. The
                // engine flags that case explicitly; trust it over the inference.
                if (surfaceOff && getSetting("nodeHazardV2") == 1 && hazTunnel)
                {
                    surfaceOff = false;
                    if (driveLogger != null && driveLogger.IsRunning
                        && ModClock.Ticks - lastTunnelVetoLogTicks > 50000000L)
                    {
                        lastTunnelVetoLogTicks = ModClock.Ticks;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT offroad-tunnel-veto:"
                            + " lat=" + lastLaneLateralError.ToString("F1")
                            + " spd=" + playerVeh.Speed.ToString("F1")
                            + " pos=" + FmtV(playerVeh.Position));
                    }
                }
                if (surfaceOff)
                {
                    if (offRoadFloorArmSinceTicks == 0)
                        offRoadFloorArmSinceTicks = ModClock.Ticks;
                    else if (ModClock.Ticks - offRoadFloorArmSinceTicks > OFFROAD_FLOOR_ARM_TICKS)
                        offRoadFloorArmed = true;
                }
                else offRoadFloorArmSinceTicks = 0;
            }
            else offRoadFloorArmSinceTicks = 0;

            // 6b: below LANE_DEPART_MIN_SPEED (8 m/s) the departure brake is silent,
            // which is where the worst |lat| of the 07-28 scrape sat (6.6-7.2 m/s).
            // Lower the floor ONLY while the ground-truth arm is live, so ordinary
            // low-speed manoeuvring and parking are untouched.
            float offroadFloorMinSpeed =
                (offroadBrakeV2 && offRoadFloorArmSinceTicks != 0)
                    ? LANE_DEPART_MIN_SPEED_OFFROAD : OFFROAD_BRAKE_FLOOR_MIN_SPEED;

            if (cachedIsFullMode && !graceActive && !alignmentEngageReverse
                && offRoadFloorArmed
                && playerVeh.Speed > offroadFloorMinSpeed
                && cachedHandbrakeMagnitude < 0.1f
                && liveBrakeTarget < OFFROAD_BRAKE_FLOOR)
            {
                liveBrakeTarget = OFFROAD_BRAKE_FLOOR;
                // iter-46 1-6: hoisted OUT of the 2 s log throttle below. `fire` must
                // count the ACTION (the brake floor being applied), not the log lines
                // that survived a rate limit — the throttled version made
                // offroadBrakeV2's fire count incomparable to its per-frame reach,
                // and under-reported it by whatever the throttle happened to drop.
                if (offroadBrakeV2) GateFire("offroadBrakeV2");
                if (offroadBrakeV2 && driveLogger != null && driveLogger.IsRunning
                    && ModClock.Ticks - lastOffroadFloorLogTicks > 20000000L)
                {
                    lastOffroadFloorLogTicks = ModClock.Ticks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT offroad-floor:"
                        + " why=" + (offRoadStartTicks > 0 ? "node" : "native")
                        + " lat=" + lastLaneLateralError.ToString("F1")
                        + " spd=" + playerVeh.Speed.ToString("F1")
                        + " sustainedMs=" + (offRoadFloorArmSinceTicks != 0
                            ? ((ModClock.Ticks - offRoadFloorArmSinceTicks) / 10000L) : 0L)
                        + " nativeOnRoad=" + IsPositionOnRoad(playerVeh.Position));
                    SnapshotFailure("OFFROAD-FLOOR", null);
                }
            }

            // ---- iter-22 J3: WATER-AHEAD EMERGENCY BRAKE ----
            // Uncapped full brake while water is detected ahead at speed. Brake
            // only — no auto-swerve. Detection set per-scan in ProcessSteeringAssist.
            if (cachedIsFullMode && waterAheadDetected
                && !graceActive && !alignmentEngageReverse
                && playerVeh.Speed > 4f)
            {
                liveBrakeTarget = 1.0f;
            }

            // ---- ACC BRAKING ----
            // Gentle comfort braking to hold headway. accBrakeOut is non-zero
            // only when ComputeACC is active, so no extra gating is needed
            // beyond avoiding conflict with handbrake turns / reverse recovery.
            if (accBrakeOut > liveBrakeTarget && !alignmentEngageReverse
                && cachedHandbrakeMagnitude < 0.1f)
                liveBrakeTarget = accBrakeOut;

            // ---- POST-TELEPORT BRAKE HOLD (iter-9 Patch C) ----
            // ResetForTeleport sets postTeleportBrakeHoldUntilTicks to a
            // 500 ms-from-now timestamp. While the hold is active we floor
            // liveBrakeTarget at POST_TELEPORT_BRAKE_FLOOR (0.4). This stops
            // the car from immediately closing on a fresh obstacle at the new
            // location while the next 1-2 scans rebuild threat data after a
            // CheckRoadTeleport jump. Has no effect outside the hold window.
            if (postTeleportBrakeHoldUntilTicks > 0
                && ModClock.Ticks < postTeleportBrakeHoldUntilTicks // ModClock pair (set in ResetForTeleport)
                && liveBrakeTarget < POST_TELEPORT_BRAKE_FLOOR)
                liveBrakeTarget = POST_TELEPORT_BRAKE_FLOOR;

            // ---- iter-25 M1: DON'T BRAKE A COMMANDED REVERSE ----
            // A Layer-2 / pivot reverse escape backs the car AWAY from a forward
            // obstacle. The forward-threat / emergency / recovery / curve brakes all
            // oppose it: 06-18 F5641 held rampedBrake=1.0 emergencyBrake=True while
            // the car was reversing at 2.9 m/s from a 5.5 m forward obstacle, bleeding
            // the reverse to a stop and deadlocking the Sandy Shores wedge. Rear
            // obstacles during a reverse are handled by the reverse-veto below, never
            // by braking — so while a reverse is commanded, suppress the brake target.
            // (The skew-emergency / water / ACC paths above are already
            // !alignmentEngageReverse-gated; this also covers the threat + Patch-Z
            // emergency latch that were not.)
            if (alignmentEngageReverse)
                liveBrakeTarget = 0f;

            // ---- BRAKE RAMP ----
            // The brake control input lerps toward the target rather than snapping.
            // This is the "no more jerky brake" fix. With BRAKE_RAMP_RATE = 5.0/sec,
            // a 0 → 1 transition takes ~200 ms, which feels firm but physical.
            // Iter-11 Patch M: asymmetric urgent-up path. When the brake
            // target jumps ahead of the ramped value by >0.3 AND the car is
            // moving fast enough that 200 ms ramp latency means meters of
            // unbraked closing distance, use BRAKE_RAMP_RATE_URGENT (12/sec)
            // for that frame's UP-ramp only. Down-ramp stays at the comfort
            // rate so brake release doesn't lurch.
            // ---- iter-39 Stage 1D: NO-THREAT DECAY ----
            // The ramp-down held a full brake long after the reason for it was gone:
            // the `ramped` owner accounted for 36.3% of all heavy (>= 0.5) brake
            // demand on 07-23. With the brake channel dead that was invisible; with
            // actuationV2 it is a car that keeps braking at nothing. If nothing is
            // currently asking for a brake, drive the target to zero rather than
            // letting the previous request coast down.
            if (actuationV2 && liveBrakeTarget < 0.05f && rampedBrakeInput > 0.05f
                && !hasLiveBrakeThreat && !emergencyBrakeActive && !brakeArmed)
            {
                if (brakeNoThreatSinceTicks == 0) brakeNoThreatSinceTicks = nowStamp;
                else if (nowStamp - brakeNoThreatSinceTicks > BRAKE_NO_THREAT_DECAY_TICKS)
                    liveBrakeTarget = 0f;
            }
            else brakeNoThreatSinceTicks = 0;

            float effRampUpRate = BRAKE_RAMP_RATE;
            if (liveBrakeTarget - rampedBrakeInput > 0.3f && playerVeh.Speed > 10f)
                effRampUpRate = BRAKE_RAMP_RATE_URGENT;
            // iter-39 Stage 1D: jerk limit. BRAKE_RAMP_RATE_URGENT is 12/sec — an
            // 83 ms 0 -> 1 slam. That was harmless while the command went nowhere;
            // delivered for real to a driver who cannot see it coming, it is a
            // safety and nausea problem. Cap the rise so full brake takes >= 150 ms.
            if (actuationV2 && effRampUpRate > BRAKE_MAX_RISE_PER_SEC)
                effRampUpRate = BRAKE_MAX_RISE_PER_SEC;
            float rampStepUp = effRampUpRate * Math.Max(deltaTime, 0.016f);
            float rampStepDown = BRAKE_RAMP_RATE * Math.Max(deltaTime, 0.016f);
            if (liveBrakeTarget > rampedBrakeInput)
                rampedBrakeInput = Math.Min(liveBrakeTarget, rampedBrakeInput + rampStepUp);
            else
                rampedBrakeInput = Math.Max(liveBrakeTarget, rampedBrakeInput - rampStepDown);

            // ---- iter-39 Stage 1B: BRAKE-EPISODE MEASUREMENT ----
            // The one number that decides whether Stage 1A worked. Deceleration is
            // measured from the speed the vehicle actually had, NOT from decelMs2 —
            // that field is a model output, and a model cannot falsify itself. Before
            // the fix this reads ~1.2-1.7 m/s2 at every commanded magnitude (coasting
            // drag); a working brake channel should show a clear dose-response and
            // >= 4.5 m/s2 near full command.
            {
                float epSpeed = playerVeh.Speed;
                long epNow = ModClock.Ticks;
                if (!brakeEpiActive)
                {
                    if (rampedBrakeInput >= 0.3f && epSpeed > 5f && !playerVeh.IsInAir)
                    {
                        brakeEpiActive = true;
                        brakeEpiStartTicks = epNow;
                        brakeEpiV0 = epSpeed;
                        brakeEpiPeakCmd = rampedBrakeInput;
                        brakeEpiFrames = 0;
                        // iter-41 Stage 0.5
                        brakeEpiPeakTicks = 0;
                        brakeEpiAtPeakMs = 0;
                        brakeEpiPeakV0 = epSpeed;
                        brakeEpiPeakVEnd = epSpeed;
                        brakeEpiThrMax = 0f;
                    }
                }
                else
                {
                    brakeEpiFrames++;
                    if (rampedBrakeInput > brakeEpiPeakCmd)
                    {
                        brakeEpiPeakCmd = rampedBrakeInput;
                        // A new peak restarts the at-peak measurement window.
                        brakeEpiPeakTicks = 0;
                        brakeEpiAtPeakMs = 0;
                    }
                    if (lastPlayerThrottleRaw > brakeEpiThrMax)
                        brakeEpiThrMax = lastPlayerThrottleRaw;
                    // iter-41 Stage 0.5: measure deceleration over the AT-PEAK span
                    // only. aAch divides dv by the whole episode, ramp-up and
                    // ramp-down included, so buckets of different length are not
                    // comparable — on 07-28 the >=0.9 bucket's episodes ran 2.3x
                    // longer than the mid bucket and "inverted" purely from that,
                    // while mean dv was monotonic. aPeak is duration-independent.
                    if (rampedBrakeInput >= 0.9f * brakeEpiPeakCmd)
                    {
                        if (brakeEpiPeakTicks == 0)
                        {
                            brakeEpiPeakTicks = epNow;
                            brakeEpiPeakV0 = epSpeed;
                        }
                        brakeEpiPeakVEnd = epSpeed;
                        brakeEpiAtPeakMs = (epNow - brakeEpiPeakTicks) / 10000L;
                    }
                    long epMs = (epNow - brakeEpiStartTicks) / 10000L;
                    bool cmdDrop = rampedBrakeInput < 0.1f;
                    bool stopped = epSpeed < 1f;
                    if (cmdDrop || stopped || epMs > 4000L)
                    {
                        if (epMs >= 200L && driveLogger != null && driveLogger.IsRunning)
                        {
                            float dv = brakeEpiV0 - epSpeed;
                            float aAch = dv / (epMs / 1000f);
                            float aPeak = brakeEpiAtPeakMs >= 100L
                                ? (brakeEpiPeakV0 - brakeEpiPeakVEnd) / (brakeEpiAtPeakMs / 1000f)
                                : float.NaN;
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT brake-episode:"
                                + " v0=" + brakeEpiV0.ToString("F2")
                                + " vEnd=" + epSpeed.ToString("F2")
                                + " dv=" + dv.ToString("F2")
                                + " aAch=" + aAch.ToString("F2")
                                + (float.IsNaN(aPeak) ? "" : " aPeak=" + aPeak.ToString("F2"))
                                + " msAtPeak=" + brakeEpiAtPeakMs
                                + " endReason=" + (cmdDrop ? "cmd-drop" : stopped ? "stopped" : "cap")
                                + " playerThrMax=" + brakeEpiThrMax.ToString("F2")
                                + " owner=" + ComputeBrakeOwner()
                                + (aAch < 0f ? " note=accelerated" : "")
                                + " peakCmd=" + brakeEpiPeakCmd.ToString("F2")
                                + " ms=" + epMs
                                + " epMs=" + epMs
                                + " frames=" + brakeEpiFrames
                                + " actuationV2=" + (actuationV2 ? 1 : 0)
                                + " physicsAssist=" + (getSetting("brakePhysicsAssist") == 1 ? 1 : 0)
                                + " ctrlB=" + Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 72).ToString("F2")
                                + " ctrlBd=" + Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 72).ToString("F2")
                                + " wheelsDown=" + Function.Call<bool>(Hash.IS_VEHICLE_ON_ALL_WHEELS, playerVeh)
                                + " grace=" + graceActive);
                        }
                        brakeEpiActive = false;
                    }
                }
            }

            // ---- iter-16 FIX 2: BLIND-PLAYER LOCKOUT WATCHDOG ----
            // If the assist has held the car essentially stopped for >4 s with no real
            // motion, force-release and hand control back. Gates on the assist actually
            // HOLDING the car against something (emergency latch / armed threat brake /
            // reverse / handbrake) — a plain red-light or ACC traffic stop has none of
            // these (brakeArmed is threat-only, never set by ACC), so the watchdog never
            // fires there and never shoves the blind player forward into traffic.
            // ---- iter-39 Stage 3: the watchdog must not cancel the escape ----
            // The composite below used to include `currentDriveMode ==
            // RecoveringToRoad` and `recoveryBrakeRequest > 0.05`, which made BEING
            // IN RECOVERY the very thing that armed the watchdog that then cancelled
            // the recovery. On 07-23 it fired 3 ms after stuck-layer 2 armed,
            // force-cancelled the recovery and granted 7 s of grace with no control
            // disables at all; the player's throttle took the car 4.3 -> 21.8 m/s
            // off-road into a wall for -163.5 body / -349.9 engine, the most
            // expensive single event in the session. It fired again 26 ms after
            // pivot-begin. The watchdog exists to catch the assist holding the car
            // against a HAZARD, not executing a MANEUVER.
            bool watchdogV2 = getSetting("watchdogV2") == 1;
            bool maneuverRunning = alignmentEngageReverse || pivotEscapeActive
                || stuckAutodriveEngaged || stuckLayer > 0
                || currentDriveMode == DriveMode.RecoveringToRoad;
            // iter-40: LATCH FIRST. This assignment used to sit BELOW the
            // maneuverTooYoung computation, so on the first frame of any maneuver
            // maneuverStartedTicks was still 0, the `> 0` term was false, and the
            // too-young guard was disabled on exactly the frame it exists to cover.
            // An already-mature watchdog hold therefore fired on the maneuver's own
            // first frame: 07-28 F20456 carries stuck-locus, stuck-arm, pivot-begin,
            // watchdog-grace AND watchdog-release all on one frame, then granted 7 s
            // of ungoverned throttle that ended in marker #5.
            if (maneuverRunning)
            {
                if (maneuverStartedTicks == 0) maneuverStartedTicks = ModClock.Ticks;
            }
            else maneuverStartedTicks = 0;
            // A maneuver that only just started cannot have "held" anything yet.
            bool maneuverTooYoung = watchdogV2 && maneuverRunning
                && maneuverStartedTicks > 0
                && ModClock.Ticks - maneuverStartedTicks < WATCHDOG_MANEUVER_GRACE_TICKS;
            bool assistHoldingStopped = cachedIsFullMode
                && !graceActive // iter-19 G2: latches are cleared during grace; don't re-accumulate
                && !maneuverTooYoung
                && playerVeh.Speed < WATCHDOG_CRAWL_SPEED
                && (emergencyBrakeActive
                    || brakeArmed
                    || alignmentEngageReverse
                    || cachedHandbrakeMagnitude > 0.1f
                    || (!watchdogV2 && recoveryBrakeRequest > 0.05f)    // iter-17: recovery-brake limbo
                    || curveBrakeRequest > 0.3f                        // iter-19 G1: 215409 — a curve-brake hold was watchdog-invisible
                    || (!watchdogV2 && currentDriveMode == DriveMode.RecoveringToRoad)); // iter-17: recovery slow-crawl
            if (assistHoldingStopped)
            {
                long wnow = ModClock.Ticks; // pause-proof: watchdog hold must not see pause gaps as "held that long"
                if (watchdogHoldSinceTicks == 0)
                {
                    watchdogHoldSinceTicks = wnow;
                    watchdogHoldAnchorPos = playerVeh.Position;
                }
                else if (PlanarDist(playerVeh.Position, watchdogHoldAnchorPos) > WATCHDOG_FREED_M)
                {
                    watchdogHoldSinceTicks = wnow;            // car moved — the hold ended
                    watchdogHoldAnchorPos = playerVeh.Position;
                }
                else if (wnow - watchdogHoldSinceTicks > WATCHDOG_HOLD_TICKS)
                {
                    ForceReleaseAssistHold(playerVeh);
                    liveBrakeTarget = 0f;                     // so brakeIntervening clears this frame too
                    watchdogHoldSinceTicks = 0;
                    // iter-39 Stage 3: arm the post-release speed governor.
                    if (watchdogV2)
                    {
                        watchdogReleaseSinceTicks = ModClock.Ticks;
                        watchdogReleaseAnchor = playerVeh.Position;
                    }
                }
            }
            else
            {
                watchdogHoldSinceTicks = 0;
            }

            // ---- MAJOR-INTERVENTION INPUT REFUSAL (Full mode only) ----
            // When the mod is actively braking, in recovery/alignment, or running a
            // handbrake/reverse/stuck-recovery maneuver, the player's raw control
            // reads must not reach the game — otherwise continued throttle/brake/
            // steer fight the mod's _SET_CONTROL_NORMAL writes below.
            //
            // iter-39: the belief that used to be documented here — "DISABLE must be
            // called BEFORE the mod's own SetControlNormal writes, so subsequent
            // writes correctly override the disabled state" — is FALSE, and it cost
            // this project roughly two dozen iterations. Ordering is irrelevant;
            // disabled-ness is what matters. A write to a disabled action is
            // accepted, returns success, shows up on the DISABLED read channel, and
            // never reaches vehicle physics. See Stage 1A below.
            //
            // The composite deliberately does NOT trigger on steer correction
            // magnitude alone — smoothedRoadCorrection is routinely ±0.5-0.9 in
            // normal curved-road cruising, and using it as a trigger caps speed
            // at ~5 mph (driveassist-2026-05-25-115625 frames 100-2451 show this
            // exactly: stable 1.9-2.2 m/s with mode=LaneKeeping and no brake).
            // The genuine "intervention" signals below are sufficient.
            // Three intervention layers, each disabling only the controls
            // that would actually fight the mod:
            //   brakeIntervening: mod is braking or armed — lock throttle so
            //                     player can't override; lock brake so player
            //                     can't lift it during the emergency.
            //   totalTakeover:    handbrake turn / reverse U-turn / stuck
            //                     autodrive — mod owns everything.
            //   inRecoveryMode:   currentDriveMode != LaneKeeping but no
            //                     active braking. Lock steering (mod is
            //                     pursuing a recovery target) but ALLOW
            //                     throttle and brake. Iteration-5 didn't
            //                     gate throttle on drive mode at all; iter-6
            //                     did and capped median speed at 2.6 m/s vs
            //                     iter-5's 8.8 (cross-log trend in
            //                     driveassist-2026-05-25-121415 audit).
            //                     Recovery forward-crawl writes 0.5 throttle;
            //                     letting the player add their own throttle
            //                     on top lets the car actually progress
            //                     toward the recovery target.
            // iter-41 Stage 0.1: mirror the FINAL value (the off-road floor and the
            // curve/junction chain all mutate it after declaration) so the ledger,
            // which runs a frame later, names the same term this decision used.
            lastLiveBrakeTarget = liveBrakeTarget;
            // iter-41 Stage 3a: name the two halves separately. THREAT intervention
            // is a real hazard the driver cannot see; SOFT intervention is comfort or
            // a lane-model hint. They are not the same claim on the driver's pedal,
            // and throttleLockoutActive below consumes the same booleans so the two
            // predicates can no longer disagree (which is what made the FRAME line
            // print applied=1.00 on frames where the pedal was already gone).
            bool brakeThreatIntervening = emergencyBrakeActive || brakeArmed;
            bool brakeSoftIntervening = rampedBrakeInput > 0.05f || liveBrakeTarget > 0.05f;
            bool brakeIntervening = cachedIsFullMode
                && (brakeThreatIntervening || brakeSoftIntervening);
            bool totalTakeover = cachedIsFullMode && (
                cachedHandbrakeMagnitude > 0.1f
                || alignmentEngageReverse
                || stuckAutodriveEngaged);
            bool inRecoveryMode = cachedIsFullMode && currentDriveMode != DriveMode.LaneKeeping;

            // iter-19 G1+G2: master gate on ALL input disables. While the scan is
            // stale (dead pipeline) or a watchdog grace is active (player sovereign)
            // the mod may still WRITE controls but may never take the player's away.
            bool inputDisablesAllowed = !scanStale && !graceActive;

            // ---- iter-39 Stage 1A: NEVER DISABLE A CONTROL YOU ALSO WRITE ----
            // SET_CONTROL_VALUE_NEXT_FRAME fails when the action param itself is
            // disabled. Disabling 59/72/76 above and then writing them below meant
            // the DISABLE half landed (the player's input was removed) and the WRITE
            // half went nowhere — so the mod removed the driver's control and put
            // nothing in its place. Measured on 07-28 with the Stage 0 split
            // readback: at commanded brake >= 0.9 the ENABLED channel that vehicle
            // physics reads was 0.000 on every one of 948 frames, while the DISABLED
            // channel held 0.962, and the native returned success (ctrlRet 72:1).
            // Deceleration was flat at ~1.6 m/s2 from 0.05 to 1.0 commanded brake:
            // pure coasting drag. This is why 24 iterations of brake/steer gain
            // tuning produced no trend movement.
            //
            // Throttle (71) is the ONLY disable that keeps working, because it
            // writes 0 — an outcome indistinguishable from the disable itself. It
            // stays exactly as it was.
            bool brakePhysicsAssist = getSetting("brakePhysicsAssist") == 1;

            // Steering: any time the mod is owning the wheel.
            if (!actuationV2 && inputDisablesAllowed && (brakeIntervening || totalTakeover || inRecoveryMode))
                Function.Call(Hash.DISABLE_CONTROL_ACTION, 0, 59, true); // VEH_MOVE_LEFT_RIGHT

            // Brake / handbrake: only when the mod is actively braking.
            if (!actuationV2 && inputDisablesAllowed && (brakeIntervening || totalTakeover))
            {
                Function.Call(Hash.DISABLE_CONTROL_ACTION, 0, 72, true); // VEH_BRAKE
                Function.Call(Hash.DISABLE_CONTROL_ACTION, 0, 76, true); // VEH_HANDBRAKE
            }

            // Throttle: when actively braking or total-takeover. Plain recovery
            // mode does NOT lock throttle — the player should be able to add
            // forward power on top of the recovery forward-crawl. On a
            // reversing car, control 71 IS the brake (the existing throttle-
            // lockout block honors this), so skip the disable there.
            // ---- iter-41 Stage 3b throttleAuthorityV2: STOP CONFISCATING WITHOUT CAUSE ----
            // The mod zeroed the enabled throttle channel on 35.6% of the 07-28
            // session, 8,738 of those frames while the car was moving faster than
            // 5 m/s. Most of it is CORRECT — it is braking on those frames, and
            // handing throttle to a floored blind driver mid-brake is the stalemate
            // iter-40 measured as zero net deceleration.
            //
            // So this does not "give the pedal back". It releases only when a comfort
            // or lane-model-hint brake is the sole reason, the path is measured (never
            // the nocast sentinel) and open, no threat is live, and only for a bounded
            // window — after which the hold is re-imposed and re-spoken. The observed
            // owner=lanedepart at rampedBrake=0.35 and 8.5 m/s is the target case: the
            // lane model is a hint the code itself documents as routinely 7 m wrong.
            bool thrAuthorityV2 = getSetting("throttleAuthorityV2") == 1;
            bool releaseThrottle = false;
            if (thrAuthorityV2 && (brakeIntervening || totalTakeover))
            {
                GateReach("throttleAuthorityV2");
                string owner = ComputeBrakeOwner();
                bool softOwner = owner == "lanedepart" || owner == "curve"
                    || owner == "speedzone" || owner == "junction" || owner == "acc";
                long heldMs = thrHoldSinceTicks != 0
                    ? (nowStamp - thrHoldSinceTicks) / 10000L : 0L;
                releaseThrottle =
                    !brakeThreatIntervening
                    && softOwner
                    && rampedBrakeInput < THR_RELEASE_MAX_CMD
                    && !(hasLiveBrakeThreat && liveTtc > 0f && liveTtc < THR_RELEASE_MIN_TTC)
                    && navAssistDistCenter < 900f          // never release on nocast
                    && navAssistDistCenter > THR_RELEASE_MIN_CLEAR_M
                    && !assistSuspended && !inRecoveryMode && !totalTakeover
                    && heldMs < THR_RELEASE_MAX_MS;
                if (releaseThrottle)
                {
                    GateFire("throttleAuthorityV2");
                    // 3c: arbitration outside watchdog grace. graceArbitrationV2's
                    // block is gated on graceActive, and ZERO grace windows opened on
                    // 07-28 — the player-vs-mod conflict it was written for happened
                    // constantly outside grace and went unarbitrated. If we are
                    // yielding the pedal, stop burning brake against it too.
                    float arbRampedWas = rampedBrakeInput;   // log the value we yielded, not 0
                    liveBrakeTarget = 0f;
                    rampedBrakeInput = 0f;
                    if (driveLogger != null && driveLogger.IsRunning
                        && nowStamp - lastThrArbLogTicks > 10000000L)
                    {
                        lastThrArbLogTicks = nowStamp;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT throttle-arbitration:"
                            + " resolved=release-both"
                            + " playerThr=" + lastPlayerThrottleRaw.ToString("F2")
                            + " ramped=" + arbRampedWas.ToString("F2")
                            + " owner=" + owner
                            + " ttc=" + FmtF(liveTtc)
                            + " navC=" + FmtF(navAssistDistCenter));
                    }
                }
            }
            if (inputDisablesAllowed && (brakeIntervening || totalTakeover)
                && !brakingAReversingCar && !releaseThrottle)
                HoldThrottle(THR_SITE_MAIN);  // VEH_ACCELERATE

            // ---- iter-40 recoverySuspendV2: POST-HANDOVER THROTTLE HOLD ----
            // Set when the assist gave up with an obstacle inside GIVEUP_HAZARD_CLEAR_M.
            // Suspension stops us STEERING the car; it must not also hand a floored
            // pedal to a driver who cannot see the wall we just failed to escape.
            // Deliberately outside the assistSuspended gate — this is the one thing
            // that must survive the suspension. Bounded by GIVEUP_THROTTLE_HOLD_TICKS
            // and released early once the path in front actually clears.
            if (giveupThrottleHoldUntilTicks != 0)
            {
                if (ModClock.Ticks > giveupThrottleHoldUntilTicks
                    || navAssistDistCenter > GIVEUP_HAZARD_CLEAR_M * 2f)
                {
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT giveup-hold-end:"
                            + " fwdClear=" + (navAssistDistCenter < 900f
                                ? navAssistDistCenter.ToString("F1") : "none")
                            + " armedAt=" + giveupHazardDist.ToString("F1")
                            + " spd=" + playerVeh.Speed.ToString("F1"));
                    giveupThrottleHoldUntilTicks = 0;
                }
                else
                {
                    HoldThrottle(THR_SITE_GIVEUP);
                    WriteControlValue(71, 0f);
                }
            }

            // ---- iter-40 graceArbitrationV2: STOP FIGHTING THE DRIVER ----
            // During watchdog grace inputDisablesAllowed is false, so the throttle
            // lockout above is skipped — but the mod keeps commanding brake. Full mod
            // brake against a floored player pedal cancels exactly: 07-28 F12017
            // logged peakCmd=1.00 held for 949 ms with dv=-0.06, i.e. ZERO net
            // deceleration. All three worst grace episodes of the session were frames
            // where the player was on the throttle, and every one sat in the run-up to
            // a marker.
            //
            // Grace means the player is sovereign, so resolve the conflict instead of
            // sustaining it. If the threat is genuinely imminent, safety wins and the
            // throttle is capped anyway (a blind driver cannot see what we can). If it
            // is not, the mod yields the brake rather than silently burning the pedal
            // against it.
            if (graceArbitrationV2 && graceActive && cachedIsFullMode)
            {
                // iter-46 1-1: reach = a grace ARBITRATION was actually evaluated
                // (unit=episode), not merely that the setting was read. 07-31 logged
                // three EVENT grace-arbitration lines while the census reported
                // eval:0/fire:0 for this gate — the contradiction that proved the
                // census was uninstrumented rather than the gate quiet.
                GateReach("graceArbitrationV2");
                float gracePlayerThr = Math.Max(
                    Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71),
                    Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 71));
                bool modWantsBrake = rampedBrakeInput > 0.05f || liveBrakeTarget > 0.05f;
                if (gracePlayerThr > GRACE_PLAYER_THROTTLE_MIN && modWantsBrake)
                {
                    GateFire("graceArbitrationV2");
                    bool imminent = emergencyBrakeActive
                        || (hasLiveBrakeThreat && liveTtc > 0f && liveTtc < GRACE_IMMINENT_TTC);
                    if (imminent)
                    {
                        // Safety overrides sovereignty. Cap the pedal so the brake we
                        // are commanding can actually do something, and say why —
                        // silence here is what let the car accelerate into the wall.
                        HoldThrottle(THR_SITE_GRACE);
                        WriteControlValue(71, 0f);
                        if (DateTime.Now.Ticks - lastGraceArbAnnounceTicks > 30000000L)
                        {
                            lastGraceArbAnnounceTicks = DateTime.Now.Ticks;
                            Speech.Critical("Braking. Obstacle ahead.");
                        }
                    }
                    else
                    {
                        // Not imminent — the driver has asked to move and we have no
                        // strong reason to refuse. Yield the brake instead of stalemate.
                        liveBrakeTarget = 0f;
                        rampedBrakeInput = 0f;
                    }
                    if (driveLogger != null && driveLogger.IsRunning
                        && DateTime.Now.Ticks - lastGraceArbLogTicks > 10000000L)
                    {
                        lastGraceArbLogTicks = DateTime.Now.Ticks;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT grace-arbitration:"
                            + " resolved=" + (imminent ? "cap-throttle" : "yield-brake")
                            + " playerThr=" + gracePlayerThr.ToString("F2")
                            + " ramped=" + rampedBrakeInput.ToString("F2")
                            + " ttc=" + liveTtc.ToString("F2")
                            + " emerg=" + emergencyBrakeActive
                            + " spd=" + playerVeh.Speed.ToString("F1")
                            + " trueSpd=" + trueSpeed.ToString("F1"));
                    }
                }
            }

            // ---- iter-39 Stage 3: POST-WATCHDOG-RELEASE SPEED GOVERNOR ----
            // A watchdog release hands the car back to the driver. It must hand back
            // STEERING, not SPEED: on 07-23 the release granted a blanket grace with
            // no disables at all and a blind player already holding the throttle went
            // 4.3 -> 21.8 m/s in 1.5 s, off-road, into a wall. Keep the throttle
            // capped until the car has actually got somewhere — bounded by both
            // distance moved and wall-clock, so it can never strand the driver.
            // Uses control 71, the one lockout proven to work.
            if (watchdogReleaseSinceTicks != 0)
            {
                long grNow = ModClock.Ticks;
                float movedM = PlanarDist(playerVeh.Position, watchdogReleaseAnchor);
                // iter-40 graceArbitrationV2: the governor must not expire before the
                // grace it is protecting. On 07-28 the release granted graceMs=7000 but
                // the governor ended at F20564 after heldMs=1788 because the car had
                // moved 10.1 m — leaving ~5 s of grace with a completely free pedal.
                // The car then accelerated into a Coach bus (marker #5). While grace is
                // still running the driver is sovereign over STEERING, not over speed.
                bool graceStillRunning = graceArbitrationV2 && graceActive;
                if (!graceStillRunning
                    && (grNow - watchdogReleaseSinceTicks > WATCHDOG_RELEASE_GOVERN_TICKS
                        || movedM > WATCHDOG_RELEASE_GOVERN_M))
                {
                    long heldMs = (grNow - watchdogReleaseSinceTicks) / 10000;
                    watchdogReleaseSinceTicks = 0;
                    if (driveLogger != null && driveLogger.IsRunning)
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT watchdog-govern-end:"
                            + " heldMs=" + heldMs
                            + " movedM=" + movedM.ToString("F1")
                            + " spd=" + playerVeh.Speed.ToString("F1"));
                }
                else if (playerVeh.Speed > WATCHDOG_RELEASE_SPEED_CAP)
                {
                    HoldThrottle(THR_SITE_WATCHDOG);
                    WriteControlValue(71, 0f);
                }
            }

            // ---- iter-13 Patch W: TAKEOVER UX CUE ----
            // totalTakeover = the assist is actively driving (reverse U-turn,
            // pivot reverse bite, handbrake turn, stuck autodrive) and has locked
            // the throttle. A blind player otherwise feels only a dead pedal with
            // no explanation (the Fort Zancudo "wouldn't let me control the
            // throttle" complaint). Announce on the transition only (latched),
            // with a distinct double-pulse rumble, and announce the hand-back on
            // release. Routine braking keeps its own "Hard braking!" cue.
            // iter-19 G4: DEBOUNCED takeover announcements. The raw state must hold
            // for TAKEOVER_STABLE_TICKS before it is treated as real (a 3-frame
            // reverse pulse stays silent, log-only), and spoken pairs are at least
            // TAKEOVER_PAIR_COOLDOWN_TICKS apart. A pulsing takeover therefore
            // reads as ONE continuous takeover: one spoken pair total, instead of
            // the 204938 session's ~21 announcements in 17 s.
            bool throttleTakenNow = totalTakeover && !brakingAReversingCar;
            if (throttleTakenNow != takeoverDebouncedState)
            {
                if (takeoverPendingSinceTicks == 0)
                {
                    takeoverPendingSinceTicks = nowStamp;
                }
                else if (nowStamp - takeoverPendingSinceTicks > TAKEOVER_STABLE_TICKS)
                {
                    takeoverDebouncedState = throttleTakenNow;
                    takeoverPendingSinceTicks = 0;
                    if (takeoverDebouncedState)
                    {
                        string takeoverKind = stuckAutodriveEngaged ? "autodrive"
                            : pivotEscapeActive ? "pivot"
                            : alignmentEngageReverse ? "reverse" : "maneuver";
                        bool cooled = nowStamp - lastTakeoverAnnounceTicks > TAKEOVER_PAIR_COOLDOWN_TICKS;
                        takeoverPairSuppressed = !cooled;
                        if (cooled)
                        {
                            lastTakeoverAnnounceTicks = nowStamp;
                            Speech.Info("Assist driving. Hands off throttle.");
                            TriggerRumble(0.5f, 120, true); // double pulse = distinct from threat rumble
                        }
                        if (driveLogger != null && driveLogger.IsRunning)
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT takeover:"
                                + " kind=" + takeoverKind + " throttleLocked=true"
                                + " spoken=" + cooled);
                    }
                    else
                    {
                        // Suppressed ON keeps its OFF silent too — no orphan
                        // "You have throttle" without a preceding takeover cue.
                        if (!takeoverPairSuppressed)
                            Speech.Info("You have throttle.");
                        if (driveLogger != null && driveLogger.IsRunning)
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT takeover-release:"
                                + " throttleLocked=false"
                                + " spoken=" + !takeoverPairSuppressed);
                    }
                }
            }
            else if (takeoverPendingSinceTicks != 0)
            {
                // Raw state bounced back inside the stability window — a silent
                // pulse. iter-35 L5: accumulate into a burst instead of one line per
                // pulse (07-03: 200 lines, 82 of them in a single 7.5 s abort loop);
                // the burst also carries the kind the single pulses never had (B7).
                long pulseMs = (nowStamp - takeoverPendingSinceTicks) / 10000;
                if (pulseBurstN == 0) pulseBurstFirstTicks = nowStamp;
                pulseBurstN++;
                pulseBurstLastTicks = nowStamp;
                if (pulseMs < pulseBurstMinMs) pulseBurstMinMs = pulseMs;
                if (pulseMs > pulseBurstMaxMs) pulseBurstMaxMs = pulseMs;
                pulseBurstKind = stuckAutodriveEngaged ? "autodrive"
                    : pivotEscapeActive ? "pivot"
                    : alignmentEngageReverse ? "reverse" : "maneuver";
                takeoverPendingSinceTicks = 0;
            }
            // iter-35 L5: flush the pulse burst after 1 s of quiet.
            if (pulseBurstN > 0 && nowStamp - pulseBurstLastTicks > 10000000L)
            {
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT takeover-pulse-burst:"
                        + " n=" + pulseBurstN
                        + " spanMs=" + ((pulseBurstLastTicks - pulseBurstFirstTicks) / 10000)
                        + " minMs=" + pulseBurstMinMs
                        + " maxMs=" + pulseBurstMaxMs
                        + " kind=" + pulseBurstKind);
                pulseBurstN = 0;
                pulseBurstMinMs = long.MaxValue;
                pulseBurstMaxMs = 0;
            }

            // ---- PER-FRAME STEER URGENCY RECOMPUTE ----
            // Re-scale the cached steering correction by live steer-threat urgency.
            // If the threat became less imminent (speed dropped, or threat moved
            // away), urgency falls and we steer less — preventing over-correction
            // between detection cycles.
            float liveSteer = cachedSteerCorrection;
            lastLiveUrgency = 1f; // iter-39 L6: 1.0 = no rescale applied this frame
            // Iter-11 Patch J: same speed-scaled validity for the steer cache —
            // a steer threat 250 ms old at 25 m/s is 6 m off-axis and the
            // pure-pursuit steer would chase a phantom.
            if (cachedSteerThreatPos != GTA.Math.Vector3.Zero
                && (nowStamp - cachedSteerThreatStamp) < ThreatCacheValidTicksForSpeed(playerVeh.Speed))
            {
                float liveSteerTtc = CalculateTTC(playerVeh, cachedSteerThreatPos, cachedSteerThreatVel);
                float steerThr = cachedIsFullMode ? STEER_THRESHOLD_FULL : STEER_THRESHOLD_ASSIST;
                float liveUrgency = Math.Max(0f, Math.Min(1f, 1f - (liveSteerTtc / steerThr)));
                lastLiveUrgency = liveUrgency; // iter-39 L6
                // Blend live urgency with cached direction: keep the side decision
                // from the last scan but rescale magnitude by current urgency.
                if (Math.Abs(cachedSteerCorrection) > 0.05f)
                {
                    if (actuationV2)
                    {
                        // iter-39 Stage 1C: scale ONLY the avoidance residual. The
                        // road/lane-keep term keeps full authority — a distant
                        // pedestrian's TTC has nothing to say about whether the car
                        // should stay on its lane line. The old form multiplied the
                        // whole command, which on 07-28 zeroed 126 of 643 strong
                        // steer commands outright (urgency 0.001) and halved 71 more.
                        float road = cachedRoadSteerPart;
                        float avoidResidual = cachedSteerCorrection - road;
                        liveSteer = Math.Max(-1f, Math.Min(1f,
                            road + avoidResidual * liveUrgency));
                    }
                    else
                    {
                        float sign = Math.Sign(cachedSteerCorrection);
                        liveSteer = sign * Math.Abs(cachedSteerCorrection) * liveUrgency;
                    }
                }
            }

            // ---- APPLY STEERING ----
            // iter-39 L6: record what was ACTUALLY written to control 59. Twelve
            // iterations tuned steering gains against a command the log never
            // showed: the FRAME line carried steerCmd/smoothedSteer, but the value
            // that reaches the wheel is liveSteer (cachedSteerCorrection rescaled by
            // an unrelated threat's urgency), and the write is skipped entirely
            // below 0.05. lastSteerWritten=False with a large steerCmd is the
            // signature of lane-keep being deleted by the urgency rescale.
            // iter-39 Stage 1C: in full mode the mod owns the wheel, so a small
            // command is still a command — dropping the write below 0.05 left the
            // wheel wherever the player last had it. Keep the deadband only in
            // assistive mode, where the write is an additive nudge on top of the
            // player's own steering and a tiny nudge is genuinely noise.
            float steerWriteFloor = (actuationV2 && cachedIsFullMode) ? 0.0f : 0.05f;
            lastLiveSteer = liveSteer;
            lastSteerWritten = Math.Abs(liveSteer) > steerWriteFloor;
            if (Math.Abs(liveSteer) > steerWriteFloor)
            {
                if (cachedIsFullMode)
                {
                    WriteControlValue(59, liveSteer);
                }
                else
                {
                    float playerSteer = Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 59);
                    float blended = Math.Max(-1f, Math.Min(1f, playerSteer + liveSteer * 1.05f));
                    lastLiveSteer = blended;
                    WriteControlValue(59, blended);
                }
            }

            // ---- iter-49 C5 (steerBiasV2): a second, non-control steering path ----
            // Everything above goes through control 59. That channel is the one the
            // mod spent 24 iterations discovering it was binning its own writes
            // into, and even post-actuationV2 there is no independent way to steer.
            // SET_VEHICLE_STEER_BIAS is written straight onto the vehicle — drunk.c
            // uses it to swerve a car with no control involvement whatsoever.
            //
            // ---- iter-51: THE SIGN. This channel was inverted for its whole first
            // session, which is exactly why turning it on made the car worse. ----
            // SET_VEHICLE_STEER_BIAS (0x42A8EC77D5150CBE) is documented in the
            // natives DB shipped beside this repo as:
            //     -1.0 = full RIGHT lock, 0.0 = centred, 1.0 = full LEFT lock
            // The mod's control-59 convention is the OPPOSITE: left is NEGATIVE
            // (see the obstacle-side test at the "rightSide = liveSteer < -0.05f"
            // site, and pivotTurnSign > 0 == TA_HANDBRAKE_TURN_RIGHT). Passing
            // liveSteer through unchanged therefore biased the rack the wrong way
            // on every frame the gate was on.
            //
            // It is worse than a fighting second channel: the same doc says the
            // native LOCKS the steering to the requested angle while it is being
            // called each tick, so control 59 stops mattering entirely. An inverted
            // bias is not a nudge against lane-keep, it is lane-keep in reverse.
            // Negate here, at the single write site, so the rest of the mod keeps
            // one convention (left = negative) end to end.
            //
            // Whether it does anything at all on a PLAYER-driven car is still
            // unverified, so this stays measurement-shaped: write the bias, then
            // record it beside the achieved steering angle the actuationFeedbackV2
            // readback already collects. If achSteer does not move with it, the
            // channel is dead on a player vehicle and we will know from one session
            // instead of from a theory.
            if (steerBiasV2Cached && cachedIsFullMode
                && playerVeh != null && playerVeh.Exists())
            {
                GateReach("steerBiasV2");
                try
                {
                    Function.Call(Hash.SET_VEHICLE_STEER_BIAS, playerVeh, -lastLiveSteer);
                    GateFire("steerBiasV2");
                    lastSteerBiasWritten = -lastLiveSteer;
                    if (driveLogger != null && driveLogger.IsRunning
                        && Math.Abs(lastLiveSteer) > 0.05f
                        && nowStamp - lastSteerBiasLogTicks > 5000000L)
                    {
                        lastSteerBiasLogTicks = nowStamp;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT steer-bias:"
                            // `cmd` is the mod's own convention (left = negative);
                            // `bias` is what the native actually received. They are
                            // negations of each other by design — a log that showed
                            // only one of them is how the inversion survived a whole
                            // session unnoticed.
                            + " cmd=" + lastLiveSteer.ToString("F3")
                            + " bias=" + lastSteerBiasWritten.ToString("F3")
                            + " ctrl59=" + (lastSteerWritten ? lastLiveSteer.ToString("F3") : "skipped")
                            // The achieved-state readback. achValid=False means the
                            // comparison cannot be made, which is itself the answer
                            // to report rather than a 0.00 to average in.
                            //
                            // achPrev, not ach: SampleVehicleFeedback runs LATER in
                            // the same tick than this write site, so the readback
                            // available here describes the frame before. Naming it
                            // honestly is the difference between "the bias did
                            // nothing" and "we compared against the wrong frame".
                            + " achValid=" + achValid
                            + " achSteerNormPrev=" + achSteerNorm.ToString("F3")
                            + " spd=" + playerVeh.Speed.ToString("F1"));
                    }
                }
                catch { GateVeto("steerBiasV2"); }
            }

            // ---- THROTTLE LOCKOUT (Full mode, the moment a brake is requested) ----
            // The previous threshold (rampedBrakeInput > 0.3) gave the player ~100 ms
            // window where they could fight the brake with throttle and cause the
            // collision anyway. Lock throttle as SOON AS the brake-arm gate triggers,
            // or any ramped brake input exists, or an emergency brake is latched.
            // When braking a reversing car, control 71 IS the brake — the
            // lockout must not zero it.
            // iter-31: the player's raw throttle intent, read BEFORE any disable below
            // (a disabled control reads 0 via GET_CONTROL_NORMAL, so also sample the
            // disabled channel). Used to (a) let the driver override an ACC comfort limit
            // and (b) detect the player fighting a genuine safety hold.
            float playerThrottleRaw = Math.Max(
                Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71),
                Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 71));
            lastPlayerThrottleRaw = playerThrottleRaw;
            // iter-41 Stage 0.2: THE LOG WAS LYING. This line used to assign
            // unconditionally, but the main confiscation site above runs EARLIER in
            // the same frame and uses a wider predicate than throttleLockoutActive
            // below (it also counts liveBrakeTarget). On 07-28 that printed
            // applied=1.00 on 133 frames of the terminal window where the pedal had
            // already been taken. Only claim the pedal is applied if nothing held it.
            lastAppliedThrottle = thrHoldSitesThisFrame == 0 ? playerThrottleRaw : 0f;

            bool throttleLockoutActive = cachedIsFullMode
                && inputDisablesAllowed // iter-19 G1+G2: never lock the pedal from a stale scan or during grace
                && !brakingAReversingCar
                && (brakeArmed || emergencyBrakeActive || rampedBrakeInput > 0.05f);
            if (throttleLockoutActive)
            {
                HoldThrottle(THR_SITE_LOCKOUT);
                WriteControlValue(71, 0f);
                lastAppliedThrottle = 0f;

                // iter-31: tell a blind player WHY flooring the pedal does nothing — but
                // only for a genuine blocked-ahead hazard with NO lateral escape (both
                // sides walled). If a lane is open they can steer around, so stay silent.
                // A low 60 Hz sawtooth (distinct from the brake beep) + speech, debounced.
                bool noSteerAround = navAssistDistLeft < 4f && navAssistDistRight < 4f;
                if (playerThrottleRaw > 0.5f && noSteerAround
                    && nowStamp - lastBlockedCueTicks > 20000000) // 2 s debounce
                {
                    lastBlockedCueTicks = nowStamp;
                    PlayBlockedCue();
                    Speech.Info("Hazard ahead. Cannot proceed.");
                }
                // iter-33 B3: the other silent lockout — LANE-DEPART braking. On
                // 07-02 the pedal was dead + brake 0.74-1.0 for minutes with no
                // explanation (the cue above needs both sides walled). Tell the
                // driver the brake is the assist holding them off the road line,
                // with the return direction. Shares the B2 cue timer so the two
                // off-line messages never stack.
                else if (playerThrottleRaw > 0.5f
                    && laneDepartStreak >= LANE_DEPART_FRAMES
                    && Math.Abs(lastLaneLateralError) > LANE_DEPART_LAT_M
                    && nowStamp - lastOffLineCueTicks > 80000000) // 8 s
                {
                    lastOffLineCueTicks = nowStamp;
                    Speech.Info(lastLaneLateralError > 0
                        ? "Braking. Off the road line. Steer right."
                        : "Braking. Off the road line. Steer left.");
                }
            }

            // ---- ADAPTIVE CRUISE CONTROL THROTTLE ----
            // Apply ACC's throttle only when nothing else owns the pedal: no
            // threat lockout, no reverse recovery, no handbrake turn, no curve
            // brake. accThrottleOut is non-zero only when ACC is active.
            if (accThrottleOut > 0.01f && !throttleLockoutActive && !brakingAReversingCar
                && !alignmentEngageReverse && cachedHandbrakeMagnitude < 0.1f
                && curveBrakeRequest < 0.05f)
            {
                // iter-31: yield to the driver — the player can always ask for MORE than
                // ACC's comfort-follow throttle, so flooring the pedal accelerates/passes
                // instead of being silently overwritten (the 7-mph freeway-crawl bug).
                // Hands-off (playerThrottleRaw ~0) => ACC's output is unchanged.
                float appliedThrottle = Math.Max(accThrottleOut, playerThrottleRaw);
                WriteControlValue(71, appliedThrottle);
                lastAppliedThrottle = appliedThrottle;
            }

            // ---- APPLY BRAKING (ramped) ----
            if (rampedBrakeInput > 0.05f)
            {
                if (brakingAReversingCar)
                {
                    // Car is rolling backward unintentionally: press accelerate
                    // (forward) + handbrake to stop it. Control 72 here would
                    // only deepen the reverse.
                    WriteControlValue(71, rampedBrakeInput);
                    WriteControlValue(76, Math.Min(1f, rampedBrakeInput));
                }
                else
                {
                    // iter-39 Stage 1A: control 72 is no longer disabled, so the
                    // player's own brake is live again. Take the max rather than
                    // overwriting: the driver can always add brake, never remove
                    // the mod's. (The old disable was justified as "lock brake so
                    // the player can't lift it during the emergency" — but since
                    // the mod rewrites 72 every frame anyway, and a blind driver
                    // pressing harder is never the failure mode, max() gives the
                    // same protection without killing the write.)
                    float cmd = rampedBrakeInput;
                    if (actuationV2)
                    {
                        float playerBrake = Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 72);
                        if (playerBrake > cmd) cmd = playerBrake;
                    }
                    WriteControlValue(72, cmd);
                    // iter-39 Stage 1B: optional physics-side assist. OFF by default —
                    // only needed if the un-disabled control channel still
                    // under-delivers. Vehicle.BrakePower is the same memory field
                    // ikt's Manual Transmission drives on a player-controlled car.
                    if (actuationV2 && brakePhysicsAssist && playerVeh != null && playerVeh.Exists())
                    {
                        try { playerVeh.BrakePower = Math.Max(playerVeh.BrakePower, cmd); }
                        catch { /* memory layout differs on some builds — control path stands alone */ }
                    }
                }
            }

            // ---- RECOVERY FORWARD CRAWL (Full mode) ----
            // Full mode has no propulsion of its own. After an unintended
            // reverse is arrested (or any time a recovery/alignment mode leaves
            // the car stopped), nudge it forward so it pursues the recovery
            // target instead of sitting dead. Gated hard: no brake request, no
            // live brake threat, not reversing, not a commanded reverse.
            if (cachedIsFullMode
                && currentDriveMode != DriveMode.LaneKeeping
                && !isReversing && !brakingAReversingCar && !alignmentEngageReverse
                && rampedBrakeInput < 0.05f && cachedHandbrakeMagnitude < 0.1f
                && !hasLiveBrakeThreat
                && playerVeh.Speed < 4f)
            {
                // iter-13 Patch W: let the player add throttle on top of the
                // crawl (max, not override) so they can speed an escape/pivot
                // forward bite instead of fighting a fixed 0.5. Throttle is not
                // locked in this branch (totalTakeover is false here), so the
                // player's read is live.
                float playerThrottle = Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71);
                // iter-33 B4: clearance-scaled crawl. 07-02 #9 pivoted among props
                // at ~3.5 m clearance with the fixed 0.5 bite and nudged one at
                // 2 m/s (-27 bh). Taper the crawl floor 0.5 -> 0.25 as forward
                // clearance closes 6 m -> 2 m; the player can still add pedal.
                float crawlFloor = 0.5f;
                if (navAssistDistCenter < 6f)
                    crawlFloor = 0.25f + 0.25f
                        * Math.Max(0f, Math.Min(1f, (navAssistDistCenter - 2f) / 4f));
                float crawl = Math.Max(crawlFloor, playerThrottle);
                WriteControlValue(71, crawl);
            }

            // ---- iter-25 M7: CLEAR-TO-PROCEED CUE + GENTLE AUTO-CREEP ----
            // Resume motion after a CLEARED hazard so a blind player isn't stranded on a
            // clear road (06-18 sat 26 s after a ped cleared, brake released, no throttle).
            // Plain LaneKeeping only; arms only when the assist was recently threat-braking
            // (a real cleared-hazard stop — a red light / park never sets brakeArmed) and
            // the path ahead is now clear. Latched so a coast-to-stop within the creep
            // doesn't re-announce; player throttle/brake or a new threat yields instantly.
            // Throttle is NOT locked here, so the player overrides freely.
            if (getSetting("autoResumeCreep") == 1)
            {
                long mNow = DateTime.Now.Ticks;
                float creepPlayerThrottle = Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71);
                float creepPlayerBrake = Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 72);
                // ---- iter-41 Stage 1a creepClearV2: NOCAST IS NOT "CLEAR" ----
                // navAssistDistCenter uses 999 as the "no cast data" sentinel, and
                // 999 > 10 passes this gate. On 07-28, 16 of 18 auto-creep and 8 of 9
                // announce-creep-resume events carried navC=999.0 — the mod crept on
                // UNKNOWN clearance and told a blind driver "Clear to proceed."
                // The codebase already distinguishes the two elsewhere (the `nocast`
                // label on the beep-band line); this gate simply never did.
                bool creepClearV2 = getSetting("creepClearV2") == 1;
                bool creepNoCast = navAssistDistCenter >= 900f;
                if (creepClearV2) GateReach("creepClearV2");
                bool clearAhead = navAssistDistCenter > CREEP_CLEAR_M
                    && (!creepClearV2 || !creepNoCast)
                    && !hasLiveBrakeThreat && !emergencyBrakeActive;
                // iter-46 1-4: this WAS `GateFire` on creepNoCast — i.e. it counted the
                // gate BLOCKING a creep. The census then read
                // `creepClearV2 | 8587 | 1909 | ACTIVE`, which any reader takes as
                // "the creep ran 1909 times" when it means the exact opposite: the
                // gate refused 1909 times. A veto is not a fire.
                if (creepClearV2 && creepNoCast) GateVeto("creepClearV2");
                bool creepContext = cachedIsFullMode
                    && currentDriveMode == DriveMode.LaneKeeping
                    && !isReversing && !brakingAReversingCar && !alignmentEngageReverse
                    && rampedBrakeInput < 0.05f && cachedHandbrakeMagnitude < 0.1f
                    && clearAhead && creepPlayerBrake < 0.1f;
                // iter-31: reset the announce latch once the car has genuinely driven on
                // (past creep speed) so the NEXT cleared-hazard stop can cue again. During
                // the spam case the car is stuck < CREEP_RESUME_MAX, so this never fires
                // there and the latch stays set — killing the repeat.
                if (playerVeh.Speed > CREEP_SPEED + 1f)
                    autoCreepAnnouncedThisStop = false;

                if (!creepContext || creepPlayerThrottle > 0.1f)
                {
                    // Player driving/braking, or no longer safe to creep — yield.
                    autoCreepActive = false;
                    // Only a genuine player takeover resets the latch so the next stop can
                    // re-cue once. A transient threat that merely flickers creepContext must
                    // NOT reset it (that flicker was the "Clear to proceed" spam).
                    if (creepPlayerThrottle > 0.1f || creepPlayerBrake > 0.1f)
                        autoCreepAnnouncedThisStop = false;
                }
                else
                {
                    bool recentlyAssistBraked = lastAssistBrakeTicks != 0
                        && mNow - lastAssistBrakeTicks < CREEP_AFTER_BRAKE_TICKS;
                    if (!autoCreepActive && playerVeh.Speed < CREEP_RESUME_MAX && recentlyAssistBraked)
                    {
                        autoCreepActive = true;
                        // iter-31: once per stop, and never within the cooldown.
                        if (!autoCreepAnnouncedThisStop
                            && mNow - lastCreepAnnounceTicks > CREEP_ANNOUNCE_COOLDOWN_TICKS)
                        {
                            autoCreepAnnouncedThisStop = true;
                            lastCreepAnnounceTicks = mNow;
                            Speech.Info("Clear to proceed.");
                            if (driveLogger != null && driveLogger.IsRunning)
                                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT announce-creep-resume:"
                                    + " navCsrc=" + (creepNoCast ? "nocast" : "cast")
                                    + " speed=" + playerVeh.Speed.ToString("F1")
                                    + " navC=" + navAssistDistCenter.ToString("F1")
                                    + " brakeAgoMs=" + ((mNow - lastAssistBrakeTicks) / 10000).ToString("F0"));
                        }
                    }
                    if (autoCreepActive && playerVeh.Speed < CREEP_SPEED)
                    {
                        // iter-46 1-4: the real fire — the gate permitted a creep and
                        // the throttle was actually written.
                        if (creepClearV2) GateFire("creepClearV2");
                        WriteControlValue(71, CREEP_THROTTLE);
                        if (driveLogger != null && driveLogger.IsRunning
                            && mNow - lastAutoCreepLogTicks > 10000000)
                        {
                            lastAutoCreepLogTicks = mNow;
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT auto-creep:"
                                + " navCsrc=" + (creepNoCast ? "nocast" : "cast")
                                + " navC=" + navAssistDistCenter.ToString("F1")
                                + " speed=" + playerVeh.Speed.ToString("F1"));
                        }
                    }
                }
            }
            else
            {
                autoCreepActive = false;
            }

            // ---- HANDBRAKE FOR CORRECTIVE TURNS (Full only) ----
            // iter-35 P1(b): a live brake threat under 1.0 s TTC overrides the
            // corrective handbrake. Locked rears plowed at ~1-1.5 m/s² under
            // brakeCmd=1.0 in both 07-03 wall strikes (#4/#8); rolling wheels
            // brake >=3x harder, and the foot brake below needs traction to work.
            if (cachedHandbrakeMagnitude > 0.1f && hasLiveBrakeThreat
                && liveTtc > 0f && liveTtc < 1.0f)
            {
                if (driveLogger != null && driveLogger.IsRunning
                    && DateTime.Now.Ticks - lastHandbrakeReleaseLogTicks > 10000000L)
                {
                    lastHandbrakeReleaseLogTicks = DateTime.Now.Ticks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT handbrake-release:"
                        + " reason=threat ttc=" + liveTtc.ToString("F2")
                        + " hb=" + cachedHandbrakeMagnitude.ToString("F2")
                        + " spd=" + playerVeh.Speed.ToString("F1"));
                }
                cachedHandbrakeMagnitude = 0f;
            }
            if (cachedHandbrakeMagnitude > 0.1f && cachedIsFullMode)
            {
                WriteControlValue(76, cachedHandbrakeMagnitude);
                HoldThrottle(THR_SITE_HANDBRAKE);
                WriteControlValue(71, 0f);
            }

            // ---- REVERSE U-TURN (alignment recovery) ----
            // GetAlignmentRecoverySteer sets alignmentEngageReverse when the car
            // is faced the wrong way at low speed.
            // iter-35 P2(b): during a declared abort-deadlock, refuse the reverse
            // outright (no handbrake arrest) so the forward-crawl and stuck ladder
            // can pursue an escape. Without this the planner re-commands reverse
            // every frame and the abort re-arrests it — 07-03 thrashed takeover
            // state at 14-17 ms intervals (~150 pulses) while the car sat pinned.
            if (alignmentEngageReverse
                && DateTime.Now.Ticks < reverseAbortDeadlockUntilTicks)
                alignmentEngageReverse = false;
            if (alignmentEngageReverse)
            {
                if (cachedIsFullMode)
                {
                    // Full mode: set forward speed directly to a small negative
                    // value to back the car up — control 72 alone would just
                    // brake. Once moving backward the (sign-inverted) alignment
                    // steering rotates the nose.
                    HoldThrottle(THR_SITE_REVERSE);
                    WriteControlValue(71, 0f);
                    // iter-16 FIX 5: rear-path veto — never back into an obstacle behind.
                    // iter-20 H5: navAssistDistBehind measures from the vehicle
                    // CENTER, so the old fixed 3 m threshold left ~1 m of real
                    // clearance behind a sedan's rear bumper (less for long
                    // vehicles). Make the threshold bumper-true by adding the
                    // model's half-length.
                    // iter-25 M2: a wedge escape must inch backward even with limited
                    // rear room. The normal bumper-true 3 m clearance (~5.4 m from
                    // CENTER for a sports car) vetoed the ONLY escape from the 06-18
                    // Sandy Shores wedge (reverse-veto fired at rearDist 5.1 m). While
                    // stuck-recovery is actively driving the reverse, require only ~1 m
                    // of bumper clearance; keep the conservative 3 m for a normal
                    // alignment U-turn (where there is no wedge urgency).
                    bool wedgeRecovery = stuckLayer >= 2 || pivotEscapeActive
                        || currentDriveMode == DriveMode.RecoveringToRoad;
                    // iter-43 A3: was clamped at 4.0 m, so the reverse clearance
                    // model believed a 9.9 m flatbed (half-length ~4.95 m) was
                    // ~1 m shorter than it is and reversed into things.
                    float rearHalfLen = GetVehicleHalfLengthForClearance(playerVeh);
                    float rearClearNeeded = (wedgeRecovery ? REVERSE_REAR_MIN_CLEAR_STUCK : REVERSE_REAR_MIN_CLEAR)
                        + rearHalfLen;
                    // iter-34 CRIT-1/2: reverse-emergency — the reverse must be able to
                    // STOP, not merely stop re-issuing -3. See constants block.
                    long revNow = DateTime.Now.Ticks;
                    // iter-36 B1: anchor the reverse session (>1 s gap = new session,
                    // matching the veto-streak pattern below).
                    if (revNow - reverseEngagedLastTicks > 10000000L)
                        reverseEngagedSinceTicks = revNow;
                    reverseEngagedLastTicks = revNow;
                    // iter-36 B4: a STATIONARY rear vehicle is a standoff, not a
                    // threat — the full entity margin let a parked car at ~4 m of
                    // real gap block every escape (090210 F950 deadlock). For a
                    // rear vehicle at <0.5 m/s the abort floor drops to just above
                    // the hard stop; moving vehicles and ALL peds keep the full
                    // margin (never relax toward a pedestrian).
                    bool rearVehStationary = getSetting("reverseRearV2") == 1
                        && navAssistTypeBehind == "vehicle"
                        && navAssistVehicleBehind != null && navAssistVehicleBehind.Exists()
                        && navAssistVehicleBehind.Velocity.Length() < 0.5f;
                    float rearAbortDist = rearVehStationary
                        ? REVERSE_REAR_HARD_STOP + rearHalfLen + 0.5f
                        : rearClearNeeded + REVERSE_ENTITY_ABORT_MARGIN;
                    bool rearEntityClose = (navAssistTypeBehind == "vehicle" || navAssistTypeBehind == "ped")
                        && navAssistDistBehind < rearAbortDist;
                    // iter-36 B1: only damage NEWLY incurred while reversing (300 ms
                    // settle past the session anchor) vetoes the reverse — backing
                    // into something new. Damage that predates the reverse is the
                    // wedge we are escaping FROM; the old unconditional veto made
                    // reverse escape impossible during an active grind.
                    // iter-40 reverseV2: the 300 ms settle was a damage BUDGET. At the
                    // 07-28 rate of ~85 engine points per frame it authorised ~1500
                    // health before a reverse could be aborted for grinding. With the
                    // velocity injection gone a commanded reverse cannot self-inflict,
                    // so any damage at all while reversing means we are backing into
                    // something real: abort on the first damaged frame.
                    bool grindingNow = lastBodyDropTicks > 0
                        && (revNow - lastBodyDropTicks) < WEDGE_DAMAGE_RECENT_TICKS
                        && lastBodyDropTicks > reverseEngagedSinceTicks + (reverseV2 ? 0L : 3000000L);
                    // iter-40 reverseV2: cachedBrakeThreatPos is the FORWARD brake-threat
                    // cache. The old test only asked "is it behind the nose plane?", with
                    // no distance and no freshness bound — so a threat 30 m back vetoed
                    // the reverse exactly as hard as one at 0.5 m. During an AligningHeading
                    // pivot the car rotates through 90-180 degrees, which silently converts
                    // every stale FORWARD threat into a permanent reverse veto. On 07-28
                    // this fired three times (F8792/F9199/F19135), each with rearDist=999.0
                    // rearType=none rearEnt=0 — nothing behind the car at all — and it
                    // aborted escapes BEFORE any damage existed.
                    // Require the threat to be genuinely close to the REAR bumper and
                    // freshly observed.
                    bool emergencyBehind;
                    if (reverseV2)
                    {
                        // iter-46 1-1: unit=episode — a reverse decision, not a frame.
                        // 07-31 logged 9 reverse-abort and 64 recovery-reverse-out
                        // events with own=reverse on 1773 frames while this gate
                        // censused eval:0/fire:0.
                        GateReach("reverseV2");
                        emergencyBehind = false;
                        if (emergencyBrakeActive && cachedBrakeThreatPos != GTA.Math.Vector3.Zero)
                        {
                            GateFire("reverseV2");
                            GTA.Math.Vector3 toThreat = cachedBrakeThreatPos - playerVeh.Position;
                            bool behind = GTA.Math.Vector3.Dot(toThreat, playerVeh.ForwardVector) < 0f;
                            // Distance from the rear bumper, not from the vehicle centre.
                            float rearGap = toThreat.Length() - rearHalfLen;
                            // cachedBrakeThreatStamp is stamped from DateTime.Now
                            // (see the scan block); revNow is the same clock. Do not
                            // substitute ModClock here — mixing the two on one
                            // variable is how earlier iterations produced silently
                            // wrong ages.
                            bool fresh = cachedBrakeThreatStamp > 0
                                && (revNow - cachedBrakeThreatStamp) < REVERSE_EMERG_THREAT_MAX_AGE_TICKS;
                            emergencyBehind = behind && fresh
                                && rearGap < REVERSE_REAR_HARD_STOP + rearHalfLen;
                        }
                    }
                    else
                    {
                        emergencyBehind = emergencyBrakeActive
                            && cachedBrakeThreatPos != GTA.Math.Vector3.Zero
                            && GTA.Math.Vector3.Dot(cachedBrakeThreatPos - playerVeh.Position,
                                                    playerVeh.ForwardVector) < 0f;
                    }
                    bool rearHardStop = navAssistDistBehind < REVERSE_REAR_HARD_STOP + rearHalfLen;
                    // iter-35 P2(a): at crawl, a rear ENTITY outside the hard floor no
                    // longer aborts — it inch-backs instead. The entity margin
                    // (rearClearNeeded + 3.0 ≈ 3-3.5 m of real bumper gap) let a parked
                    // vehicle 5.3 m behind permanently block every wedge escape on
                    // 07-03 (6 aborts at spd=0; session ended still wedged). A moving
                    // car keeps the full margin — a rear entity at speed is a real
                    // threat; a stationary standoff at 0 m/s is not.
                    // iter-36 B4: SIGNED speed gate. Vehicle.Speed is a magnitude, so
                    // the old <1.0 gate was disqualified by the inch-back's own
                    // -1.2 m/s creep — the abort/inch oscillation behind the 090210
                    // F950 abort-deadlock. Only a reverse already faster than the
                    // inch speed exits the branch; the hard floor stays the stop.
                    bool inchBack = rearEntityClose && !rearHardStop
                        && !grindingNow && !emergencyBehind
                        && GTA.Math.Vector3.Dot(playerVeh.Velocity, playerVeh.ForwardVector) > -1.5f;
                    bool reverseEmergency = rearHardStop
                        || (rearEntityClose && !inchBack) || grindingNow || emergencyBehind;
                    if (reverseEmergency)
                    {
                        // iter-35 P2(b): count abort-standoff seconds; ≥4 in a 10 s
                        // window at a standstill = deadlock. Unlike prop-deadlock-
                        // forward this is pin-type-agnostic (07-03's pins were
                        // vehicles, which the staticPin gate below can never match).
                        if (revNow - lastReverseAbortCountTicks > 10000000L)
                        {
                            lastReverseAbortCountTicks = revNow;
                            if (revNow - reverseAbortWindowStartTicks > 100000000L)
                            {
                                reverseAbortWindowStartTicks = revNow;
                                reverseAbortCount = 0;
                            }
                            reverseAbortCount++;
                            if (reverseAbortCount >= 4 && playerVeh.Speed < 0.5f)
                            {
                                reverseAbortDeadlockUntilTicks = revNow + 50000000L; // 5 s
                                reverseAbortCount = 0;
                                if (driveLogger != null && driveLogger.IsRunning)
                                    // iter-36 P1-3: snapshot the option space at
                                    // declaration — iter-35's deadlock dissolved into
                                    // 40 s of dead air with no trace of what the hold
                                    // was supposed to enable.
                                    driveLogger.Write("[F" + driveLogFrameCount
                                        + "] EVENT abort-deadlock:"
                                        + " rearDist=" + navAssistDistBehind.ToString("F1")
                                        + " rearType=" + navAssistTypeBehind
                                        + " holdMs=5000"
                                        + " aborts=" + 4
                                        + " windowMs=10000"
                                        + " navL=" + (navAssistDistLeft < 900f
                                            ? navAssistDistLeft.ToString("F1") : "none")
                                        + " navC=" + (navAssistDistCenter < 900f
                                            ? navAssistDistCenter.ToString("F1") : "none")
                                        + " navR=" + (navAssistDistRight < 900f
                                            ? navAssistDistRight.ToString("F1") : "none")
                                        + " layer=" + stuckLayer
                                        + " mode=" + currentDriveMode
                                        + " locusCumMs=" + (stuckLocusCumTicks / 10000));
                            }
                        }
                        // Arrest the reverse: full handbrake (76 works in either
                        // direction); control 71 is already disabled+zeroed above.
                        WriteControlValue(76, 1.0f);
                        // Release the reverse for this frame so the recovery planner
                        // and forward-crawl can re-plan instead of re-wedging; the
                        // state machine may re-command it next frame, where these
                        // gates re-apply.
                        alignmentEngageReverse = false;
                        if (driveLogger != null && driveLogger.IsRunning
                            && revNow - lastReverseAbortLogTicks > 10000000)
                        {
                            lastReverseAbortLogTicks = revNow;
                            // iter-36 P1-2: name the trigger + the thresholds in
                            // force + the rear entity, so a real wall and a phantom
                            // slope/scan-churn abort are distinguishable in-log.
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT reverse-abort:"
                                + " rearDist=" + navAssistDistBehind.ToString("F1")
                                + " rearType=" + navAssistTypeBehind
                                + " trig=" + (rearHardStop ? "hardStop"
                                    : rearEntityClose ? "entity"
                                    : grindingNow ? "grind" : "emerg")
                                + " clearNeeded=" + rearClearNeeded.ToString("F1")
                                + " hardFloor=" + (REVERSE_REAR_HARD_STOP + rearHalfLen).ToString("F1")
                                + " abortDist=" + rearAbortDist.ToString("F1")
                                + " rearEnt=" + (navAssistVehicleBehind != null
                                    && navAssistVehicleBehind.Exists()
                                    ? navAssistVehicleBehind.Handle : 0)
                                + " rearStationary=" + rearVehStationary
                                + " scanAgeMs=" + (lastScanCompletedTicks > 0
                                    ? (ModClock.Ticks - lastScanCompletedTicks) / 10000 : -1)
                                + " grinding=" + grindingNow
                                + " emergBehind=" + emergencyBehind
                                + " spd=" + playerVeh.Speed.ToString("F1"));
                        }
                        if (revNow - lastReverseBlockedTicks > 30000000)
                        {
                            Speech.Critical("Stopping. Blocked behind.");
                            lastReverseBlockedTicks = revNow;
                            lastAssistAnnounceTicks = revNow;
                        }
                    }
                    else if (inchBack)
                    {
                        // iter-35 P2(a): creep backward; the hard floor above remains
                        // the only stop inside this branch, re-checked every frame.
                        // iter-40 reverseV2: COMMAND the creep, do not inject it.
                        // See the -3 site below for the full rationale.
                        if (reverseV2)
                            WriteControlValue(72, REVERSE_INCH_BRAKE_CMD);
                        else
                            playerVeh.ForwardSpeed = -1.2f;
                        reverseVetoStreakStartTicks = 0;
                        if (driveLogger != null && driveLogger.IsRunning
                            && revNow - lastInchBackLogTicks > 10000000L)
                        {
                            lastInchBackLogTicks = revNow;
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT inch-back:"
                                + " rearDist=" + navAssistDistBehind.ToString("F1")
                                + " rearType=" + navAssistTypeBehind
                                + " hardFloor=" + (REVERSE_REAR_HARD_STOP + rearHalfLen).ToString("F1")
                                + " signedSpd=" + GTA.Math.Vector3.Dot(playerVeh.Velocity, playerVeh.ForwardVector).ToString("F1")
                                + " rearStationary=" + rearVehStationary);
                        }
                    }
                    // iter-40 reverseV2 (the single most expensive defect of the
                    // 07-28 session): `ForwardSpeed = -3f` is a VELOCITY INJECTION,
                    // not a command. Against a car that is pinned or wedged the
                    // physics solver cannot move it, so it resolves the injected
                    // 3 m/s as a contact impulse — every frame. At 07-28 F19282-85
                    // the car moved 0.008 m TOTAL while engine health fell ~85 per
                    // frame (1000 -> 921 -> 854 -> 768 -> 691 -> 604): 467.5 damage
                    // in 67 ms, entirely self-inflicted, while stationary. That is
                    // 57% of the whole session's damage.
                    //
                    // Two further consequences of the same line:
                    //  - Vehicle.Speed reads back the INJECTED value (exactly 3.00),
                    //    so `Speed < 3f` below was self-referential and every speed
                    //    field in the log was fabricated during a reverse. The gate
                    //    now uses trueSpeed (planar displacement, see the tick).
                    //  - The grind classifier was defeated by the same fake 3.00 m/s,
                    //    which is why the session's worst event was not marked as a
                    //    grind.
                    //
                    // Control 72 at a standstill IS the reverse in GTA V (brake and
                    // reverse share the control); the recovery path below already
                    // relies on exactly that. A commanded reverse cannot generate a
                    // contact impulse — if the car cannot move, nothing happens,
                    // which is the correct behaviour when wedged.
                    else if ((reverseV2 ? trueSpeed : playerVeh.Speed) < 3f
                             && navAssistDistBehind >= rearClearNeeded)
                    {
                        if (reverseV2)
                            WriteControlValue(72, 1.0f);
                        else
                            playerVeh.ForwardSpeed = -3f;
                        reverseVetoStreakStartTicks = 0; // reverse is running; no standoff
                    }
                    else if (navAssistDistBehind < rearClearNeeded)
                    {
                        if (revNow - lastReverseVetoLogTicks > 10000000
                            && driveLogger != null && driveLogger.IsRunning)
                        {
                            lastReverseVetoLogTicks = revNow;
                            driveLogger.Write("[F" + driveLogFrameCount
                                + "] EVENT reverse-veto: rearDist="
                                + navAssistDistBehind.ToString("F1")
                                + " stuck=" + wedgeRecovery);
                        }
                        // iter-34 HIGH-5: track the veto standoff. A streak only
                        // counts while it is continuously maintained (>1 s gap =
                        // a fresh standoff, not a stale timer from a past wedge).
                        if (revNow - reverseVetoStreakLastTicks > 10000000L)
                            reverseVetoStreakStartTicks = revNow;
                        if (reverseVetoStreakStartTicks == 0)
                            reverseVetoStreakStartTicks = revNow;
                        reverseVetoStreakLastTicks = revNow;
                        bool staticPin = threatType == "obstacle"
                            || closestBrakeObstacleType == "obstacle";
                        if (revNow - reverseVetoStreakStartTicks > PROP_DEADLOCK_VETO_TICKS
                            && staticPin && !laneReturnPriorityWasActive)
                        {
                            // Release the reverse: the recovery stays engaged and
                            // the forward-crawl (gated on mode != LaneKeeping and
                            // !alignmentEngageReverse) pulls toward the lane-return
                            // target instead of re-arming the same blocked reverse.
                            alignmentEngageReverse = false;
                            if (driveLogger != null && driveLogger.IsRunning
                                && revNow - lastPropDeadlockLogTicks > 10000000)
                            {
                                lastPropDeadlockLogTicks = revNow;
                                driveLogger.Write("[F" + driveLogFrameCount
                                    + "] EVENT prop-deadlock-forward:"
                                    + " vetoMs=" + ((revNow - reverseVetoStreakStartTicks) / 10000)
                                    + " rearDist=" + navAssistDistBehind.ToString("F1")
                                    + " threat=" + threatType
                                    + " brakeType=" + closestBrakeObstacleType);
                            }
                        }
                    }
                }
                else
                {
                    // Assist mode: can't override velocity without yanking the
                    // car away from the player. Hold the brake/reverse control
                    // instead — once the car stops this backs it up, which is
                    // what the reverse U-turn needs.
                    // iter-31: cap the commanded reverse so recovery crawls out at
                    // ~3 m/s instead of charging backward into scenery (the reverse-grind
                    // class). Past the cap, release so the car coasts rather than accelerates.
                    if (playerVeh.Speed < 3.0f)
                        WriteControlValue(72, 1.0f);
                }
            }

            // ---- IMMINENT-COLLISION HANDBRAKE BACKUP ----
            // When the ramped brake is at max, also tap the handbrake for max stop
            // power. NO velocity-multiplication anymore — the game's actual brake
            // physics handle the deceleration curve, which is what produces a
            // realistic feel instead of teleporting the speed down.
            // iter-40 brakeDeadzoneV2: this block bypasses its own documented fix.
            // The iter-35 P1(b) release above drops cachedHandbrakeMagnitude under a
            // live threat precisely because "locked rears plowed at ~1-1.5 m/s2 under
            // brakeCmd=1.0 ... rolling wheels brake >=3x harder" — but THIS block
            // writes control 76 directly, so that release never covered it. It fired
            // on 93% of the 07-28 frames with rampedBrake>=0.95 above 5 m/s, and
            // incident 01 achieved only 1.87 m/s2 at full brake with wheelsDown=False.
            //
            // A locked rear axle only helps once the wheels are loaded. If the car is
            // airborne or a wheel is off the ground, the handbrake costs steering
            // authority and buys no stopping power.
            bool hbWheelsOk = true;
            if (getSetting("brakeDeadzoneV2") == 1)
            {
                try
                {
                    hbWheelsOk = !playerVeh.IsInAir
                        && Function.Call<bool>(Hash.IS_VEHICLE_ON_ALL_WHEELS, playerVeh);
                }
                catch { hbWheelsOk = true; }
            }
            // ---- iter-41 Stage 7 handbrakeBandV2 (A/B ONLY) ----
            // The handbrake fires EXCLUSIVELY in the top brake band: 511 frames had
            // ctrlHb=1 on 07-28 and every one was at rampedBrake=1.000. The mod's own
            // iter-35 note says locked rears plow at ~1-1.5 m/s2 while rolling wheels
            // brake >=3x harder — and the single peakCmd=0.95 episode scored the
            // band's BEST result. That is n=1, so this is deliberately a toggle to be
            // A/B'd in one drive against brake-episode aPeak, not a settled fix.
            bool hbBandV2 = getSetting("handbrakeBandV2") == 1;
            if (hbBandV2) GateReach("handbrakeBandV2");
            bool hbTrigger = hbBandV2
                ? (emergencyBrakeActive && playerVeh.Speed > 8f)
                : rampedBrakeInput >= 0.95f;
            if (hbTrigger && !alignmentEngageReverse && hbWheelsOk) // iter-25 M1: don't handbrake a commanded reverse
            {
                if (hbBandV2) GateFire("handbrakeBandV2");
                WriteControlValue(76, 1.0f);
                // Don't zero control 71 when it is being used as the
                // reverse-arrest brake (see brakingAReversingCar above).
                if (!brakingAReversingCar)
                    WriteControlValue(71, 0f);

                // iter-41 Stage 2a: own debounce channel. This cue lost EVERY race
                // against the 2 s threat announcer at the shared timestamp, so
                // "Hard braking!" was spoken ZERO times in 9.6 driving minutes
                // despite 511 frames of maximum braking.
                if (cachedIsFullMode)
                {
                    if (DateTime.Now.Ticks - lastHardBrakeAnnounceTicks > 30000000)
                    {
                        Speech.Critical("Hard braking!");
                        lastHardBrakeAnnounceTicks = DateTime.Now.Ticks;
                        lastAssistAnnounceTicks = DateTime.Now.Ticks;
                    }
                    else if (driveLogger != null && driveLogger.IsRunning
                             && DateTime.Now.Ticks - lastCueSuppressLogTicks > 10000000L)
                    {
                        lastCueSuppressLogTicks = DateTime.Now.Ticks;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT cue-suppressed:"
                            + " site=hardbrake"
                            + " wantedMs=" + ((DateTime.Now.Ticks - lastHardBrakeAnnounceTicks) / 10000L)
                            + " channel=hardBrake");
                    }
                }
            }

            // ---- iter-34 CRIT-3: DAMAGE-WHILE-WEDGED HANDBRAKE ----
            // Stopped-and-grinding overrides whatever the planner is doing: pin the
            // car with the direction-agnostic handbrake and cut throttle so it stops
            // sanding itself against the obstacle while the (now fast-tracked)
            // recovery escalation picks an escape.
            if (cachedIsFullMode && DamageWhileWedged(playerVeh.Speed))
            {
                // iter-36 B1: the pin only holds while NO escape maneuver is
                // running. In iter-35 it fired 7x at layer=0 rev=False through both
                // vehicle deaths — holding the car against the grinder while waiting
                // for an escalation whose arm gates could never pass. It now (a)
                // yields the instant any recovery engages, and (b) sets
                // cachedHandbrakeMagnitude so the threatBrakePin arm gate sees the
                // hold (the raw control-76 write was invisible to assistBrakeHold).
                bool escapeRunning = stuckLayer > 0 || alignmentEngageReverse || pivotEscapeActive;
                if (!escapeRunning)
                {
                    WriteControlValue(76, 1.0f);
                    if (!brakingAReversingCar)
                        WriteControlValue(71, 0f);
                    cachedHandbrakeMagnitude = 1f;
                }
                else if (cachedHandbrakeMagnitude > 0.1f)
                {
                    cachedHandbrakeMagnitude = 0f; // release the pin for the escape
                }
                long wdNow = DateTime.Now.Ticks;
                if (driveLogger != null && driveLogger.IsRunning
                    && wdNow - lastWedgeDamageLogTicks > 10000000)
                {
                    lastWedgeDamageLogTicks = wdNow;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT wedge-damage:"
                        + " bh=" + playerVeh.BodyHealth.ToString("F0")
                        + " eh=" + playerVeh.EngineHealth.ToString("F0")
                        + " mode=" + currentDriveMode
                        + " layer=" + stuckLayer
                        + " rev=" + alignmentEngageReverse
                        + " pinned=" + !escapeRunning
                        // W4.2: which brake authority is holding the car while it is
                        // ground — the R1 diagnosis. own=acc with brakeArmed=False =
                        // the ACC pin (should now be broken by W2.2's release).
                        + " accBrk=" + accBrakeOut.ToString("F2")
                        + " brakeArmed=" + brakeArmed
                        + " emerg=" + emergencyBrakeActive
                        + " ramped=" + rampedBrakeInput.ToString("F2")
                        + " contact=" + NearestContactLabel());
                    SnapshotFailure("WEDGE-DAMAGE", null);
                }
                if (wdNow - lastWedgeDamageCueTicks > 100000000L)
                {
                    lastWedgeDamageCueTicks = wdNow;
                    Speech.Critical(escapeRunning
                        ? "Stuck and taking damage. Backing out."
                        : "Stuck and taking damage.");
                }
            }

            // ---- HAPTIC RUMBLE (advisory feedback; both modes) ----
            // Each source latches so it rumbles once on threat onset, not every
            // tick. Brake-threat outranks lane-edge drift if both fire together.
            bool brakeRumbleNow = hasLiveBrakeThreat && liveTtc > 0f && liveTtc < 1.5f;
            if (brakeRumbleNow && !rumbleBrakeArmed)
            {
                float intensity = 0.3f + 0.7f * (1f - liveTtc / 1.5f);
                // Steering left (negative) means the obstacle is on the right —
                // signal that with a double pulse.
                bool rightSide = liveSteer < -0.05f;
                TriggerRumble(intensity, 90, rightSide);
            }
            if (brakeRumbleNow) rumbleBrakeArmed = true; else rumbleBrakeArmed = false;

            bool edgeRumbleNow = Math.Abs(lastLaneLateralError) > LANE_EDGE_RUMBLE_M;
            if (edgeRumbleNow && !rumbleEdgeArmed && !brakeRumbleNow)
                TriggerRumble(0.25f, 200);
            if (edgeRumbleNow) rumbleEdgeArmed = true; else rumbleEdgeArmed = false;
        }

        /// <summary>
        /// Pre-impact warning beep. Sawtooth at middle C; gain rises and inter-beep
        /// interval shrinks as TTC drops. The user requested this so they can act
        /// before the autobrake fires — a predictable cue, not a surprise slam.
        /// </summary>
        private void PlayBrakeWarning(float ttc)
        {
            // Normalize TTC into [0,1] where 1 = imminent.
            float t = (BRAKE_WARN_TTC_MAX - ttc) / Math.Max(0.001f, BRAKE_WARN_TTC_MAX - BRAKE_WARN_TTC_MIN);
            if (t < 0f) t = 0f; if (t > 1f) t = 1f;

            // Interval shrinks from 350 ms (gentle warning) to 60 ms (immediate).
            long intervalTicks = (long)((350.0 - (350.0 - 60.0) * t) * 10000.0);
            long now = DateTime.Now.Ticks;
            if (now - lastBrakeWarnTicks < intervalTicks) return;
            lastBrakeWarnTicks = now;

            // iter-35 L2: band bookkeeping on every beep actually played.
            int band = t < 0.5f ? 0 : t < 0.85f ? 1 : 2;
            if (beepBandCurrent < 0) { beepEpisodeStartTicks = now; beepBandPeak = -1; beepCount = 0; }
            beepCount++;
            if (band > beepBandPeak) beepBandPeak = band;
            if (band != beepBandCurrent && driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT beep-band:"
                    + " band=" + BeepBandName(band)
                    + " ttc=" + ttc.ToString("F2")
                    + " intervalMs=" + (intervalTicks / 10000L));
            beepBandCurrent = band;

            // Gain rises from 0.05 → 0.30 across the same range.
            brakeWarnTone.Gain = 0.05 + 0.25 * t;
            double durationMs = Math.Min(120.0, (intervalTicks / 10000.0) - 20.0);
            if (durationMs < 30.0) durationMs = 30.0;

            try
            {
                outBrakeWarn.Stop();
                var sample = brakeWarnTone.Take(TimeSpan.FromMilliseconds(durationMs));
                outBrakeWarn.Init(sample);
                outBrakeWarn.Play();
            }
            catch { /* audio device contention is non-fatal */ }
        }

        /// <summary>
        /// iter-35 L2: close the beep episode once the warning has been quiet >1 s and
        /// emit the summary. Called every tick the warn gate is closed; cheap no-op
        /// when no episode is open.
        /// </summary>
        private void FlushBeepEpisode()
        {
            if (beepBandCurrent < 0) return;
            if (DateTime.Now.Ticks - lastBrakeWarnTicks < 10000000L) return; // 1 s quiet
            if (driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT beep-end:"
                    + " n=" + beepCount
                    + " peakBand=" + BeepBandName(beepBandPeak)
                    + " durMs=" + ((lastBrakeWarnTicks - beepEpisodeStartTicks) / 10000L));
            beepBandCurrent = -1;
        }

        private static string BeepBandName(int b)
        {
            return b >= 2 ? "max" : b == 1 ? "urgent" : "gentle";
        }

        /// <summary>
        /// iter-31: single low 60 Hz sawtooth pulse played when ACC / the safety hold is
        /// keeping the car stopped for a genuine blocked-ahead hazard and the player is
        /// flooring the pedal to go. Deliberately lower-pitched than the brake-warn beep so
        /// it reads as "blocked, can't proceed" rather than "brake now". Caller debounces.
        /// </summary>
        private void PlayBlockedCue()
        {
            try
            {
                outAccBlock.Stop();
                var sample = accBlockTone.Take(TimeSpan.FromMilliseconds(200.0));
                outAccBlock.Init(sample);
                outAccBlock.Play();
            }
            catch { /* audio device contention is non-fatal */ }
        }

        // ============================================
        // HAPTIC RUMBLE FEEDBACK (Drive Assist)
        // ============================================
        // SET_PAD_RUMBLE has no left/right motor selector, so obstacle side is
        // conveyed by pulse pattern: left = a single short pulse, right = a
        // double pulse, road edge = a single long low buzz. Purely additive
        // feedback — degrades silently if the native is unavailable.
        private long lastRumbleTicks = 0;
        // Pending deferred pulses: each entry is { fireAtTicks, intensityBytes, durationMs }.
        private readonly List<long[]> rumbleQueue = new List<long[]>();

        private void FireRumble(int intensityBytes, int durationMs)
        {
            try
            {
                // SET_PAD_RUMBLE: 0x14D29BB12D47F68C (padIndex, durationMs, intensity)
                Function.Call((Hash)0x14D29BB12D47F68C, 0, durationMs, intensityBytes);
            }
            catch { /* native unavailable — silently degrade to no rumble */ }
        }

        /// <summary>Fires a controller rumble pulse, gated on the hapticFeedback
        /// setting and an active gamepad. When doublePulse is set a second pulse
        /// is queued ~150 ms later (used to signal an obstacle on the right).</summary>
        private void TriggerRumble(float intensity01, int durationMs, bool doublePulse = false)
        {
            if (getSetting("hapticFeedback") != 1) return;
            if (Game.LastInputMethod != InputMethod.GamePad) return;
            long now = DateTime.Now.Ticks;
            if (now - lastRumbleTicks < 1200000) return; // 120 ms min gap, no machine-gunning
            lastRumbleTicks = now;
            int bytes = (int)(Math.Max(0f, Math.Min(1f, intensity01)) * 255f);
            FireRumble(bytes, durationMs);
            if (doublePulse)
                rumbleQueue.Add(new long[] { now + 1500000, bytes, durationMs }); // +150 ms
        }

        /// <summary>Drains queued deferred rumble pulses. Called every tick.</summary>
        private void DrainRumbleQueue()
        {
            if (rumbleQueue.Count == 0) return;
            long now = DateTime.Now.Ticks;
            for (int i = rumbleQueue.Count - 1; i >= 0; i--)
            {
                if (now >= rumbleQueue[i][0])
                {
                    FireRumble((int)rumbleQueue[i][1], (int)rumbleQueue[i][2]);
                    rumbleQueue.RemoveAt(i);
                }
            }
        }

        /// <summary>
        /// Speaks the current setting value with proper handling for multi-value settings
        /// </summary>
        // One formatter for a setting's spoken "Name: value" line. speakMenu and
        // SpeakCurrentSetting had drifted: multi-value settings (steeringAssist,
        // navAssistVerbosity, navAssistFootRange) announced a BLANK value when
        // arriving on them via menu entry, because speakMenu only knew Off/On.
        private string FormatSettingValue(Setting s)
        {
            if (s.id == "detectionRadius")
            {
                int radiusIndex = s.value;
                if (radiusIndex < 0 || radiusIndex >= detectionRadiusOptions.Length)
                    radiusIndex = 1;
                return "Detection Radius: " + (int)detectionRadiusOptions[radiusIndex] + " meters";
            }
            if (s.id == "steeringAssist")
                return "Steering Assist Mode: " + (s.value == 0 ? "Off" : (s.value == 1 ? "Assistive" : "Full"));
            if (s.id == "navAssistVerbosity")
                return "Navigation Assist Detail: " + NavVerbosityName(s.value);
            if (s.id == "navAssistFootRange")
            {
                int idx = s.value;
                if (idx < 0 || idx >= navFootRangeOptions.Length) idx = 1;
                return "On-Foot Detection Range: " + (int)navFootRangeOptions[idx] + " meters";
            }
            // iter-44 — without these the two multi-value unrest settings announce
            // a blank value when arrived at via menu entry (the bug documented above).
            if (s.id == "unrestScope")
                return "Civil Unrest Scope: " + UnrestScopeName(s.value);
            if (s.id == "unrestNarration")
                return "Civil Unrest Commentary: " + UnrestNarrationName(s.value);
            // iter-48 — same contract for the five new multi-value gates.
            if (s.id == "unrestEscalation")
                return "Civil Unrest escalation: " + UnrestEscalationName(s.value);
            if (s.id == "unrestPace")
                return "Civil Unrest pace: " + UnrestPaceName(s.value);
            if (s.id == "unrestBrutality")
                return "Civil Unrest fight intensity: " + UnrestBrutalityName(s.value);
            if (s.id == "unrestAmbience")
                return "Civil Unrest riot ambience: " + UnrestAmbienceName(s.value);
            if (s.id == "unrestTraffic")
                return "Civil Unrest aggressive traffic: " + UnrestTrafficName(s.value);
            if (s.id == "unrestPolice")
                return "Civil Unrest police response: " + UnrestPoliceName(s.value);
            return s.displayName + (s.value == 0 ? "Off" : "On");
        }

        private void SpeakCurrentSetting()
        {
            Speech.Ambient(FormatSettingValue(settingsMenu[settingsMenuIndex]));
        }

