        /// <summary>
        /// iter-51: unrest lines now carry their own clock.
        ///
        /// driveLogFrameCount only advances inside the drive-assist FRAME logger,
        /// which runs only while the player is in a vehicle. A riot is fought on
        /// foot, so on 08-11 all 1,663 unrest lines were stamped with the same
        /// frozen "[F31198]" and could not be ordered in time at all — the whole
        /// "how long did stage 0 take?" question was unanswerable from a 44 MB log.
        ///
        /// riotT= is seconds of ModClock since the riot started (monotonic and
        /// pause-proof), which is also the exact clock UNREST_STAGE_AT is measured
        /// against, so a stage boundary in the log lines up with the ladder.
        ///
        /// It is spliced in as the FIRST PAYLOAD FIELD, not before the EVENT token:
        /// triage-log.py anchors on "^[F<n>] EVENT <name>:" and anything inserted
        /// ahead of EVENT would silently drop every unrest line out of the digest.
        /// </summary>
        private void UnrestLog(string msg)
        {
            try
            {
                if (driveLogger == null || !driveLogger.IsRunning) return;
                string t = unrestActive && unrestStartTicks > 0
                    ? ((ModClock.Ticks - unrestStartTicks) / 10000000.0).ToString("F1")
                    : "-";
                int colon = msg.IndexOf(':');
                string stamped = colon >= 0
                    ? msg.Substring(0, colon + 1) + " riotT=" + t + msg.Substring(colon + 1)
                    : msg + ": riotT=" + t;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT " + stamped);
            }
            catch { }
        }

        /// <summary>
        /// Key-throttled speech for the iter-48 escalation events. Info/Ambient also
        /// respect the same 4 s channel-quiet rule UnrestSitRep uses, so escalation
        /// commentary never lands on top of a line the player is still hearing.
        /// Critical never yields — a firefight, a fire or a gun IS the thing that
        /// must interrupt, and those lines fire even at narration verbosity Off
        /// (the same precedent as "Someone near you has a gun").
        /// </summary>
        private void UnrestSpeak(string key, string text, SpeechPriority prio, long minGapWall)
        {
            try
            {
                long now = DateTime.Now.Ticks;
                long last;
                if (unrestSpokenTicks.TryGetValue(key, out last))
                {
                    // minGap 0 means "once per riot" — the key is never re-armed.
                    if (minGapWall <= 0L) return;
                    if (now - last < minGapWall) return;
                }
                if (prio != SpeechPriority.Critical
                    && now - Speech.LastEmittedWallTicks < UNREST_SPEECH_QUIET_TICKS) return;
                unrestSpokenTicks[key] = now;
                Speech.Request(text, prio);
            }
            catch { }
        }

        /// <summary>
        /// "12 meters north east" for a world position, using the mod's existing
        /// counterclockwise-convention bearing pair.
        /// </summary>
        private string UnrestBearing(GTA.Math.Vector3 pos)
        {
            try
            {
                GTA.Math.Vector3 p = Game.Player.Character.Position;
                int d = (int)p.DistanceTo(pos);
                return d + " meters " + getDir(calculate_x_y_angle(p.X, p.Y, pos.X, pos.Y, 0));
            }
            catch { return "nearby"; }
        }

        /// <summary>
        /// True for Unarmed and for everything Civil Unrest itself hands out. Anything
        /// else on a rioter was picked up from the world — most dangerously a cop's
        /// Carbine Rifle — and is confiscated on the profile slice.
        /// </summary>
        private static bool IsAllowedUnrestWeapon(int weaponHash)
        {
            if (unrestAllowedWeapons == null)
            {
                HashSet<int> s = new HashSet<int>();
                s.Add(unchecked((int)WeaponHash.Unarmed));
                for (int i = 0; i < UNREST_FIREARMS.Length; i++)
                    s.Add(unchecked((int)UNREST_FIREARMS[i]));
                for (int i = 0; i < UNREST_MELEE.Length; i++)
                    s.Add(unchecked((int)UNREST_MELEE[i]));
                // The cop street-stop hands out a stun gun and a pistol; neither must
                // trip confiscation if a rioter somehow ends up holding one.
                s.Add(unchecked((int)WeaponHash.StunGun));
                unrestAllowedWeapons = s;
            }
            return unrestAllowedWeapons.Contains(weaponHash);
        }

        // ---- ePedType classification (see GetPedTypeName for the full map) ----
        private static bool IsUnrestCivilianType(int t)
        {
            return t == 4 || t == 5 || t == 19 || t == 22 || t == 23 || t == 24;
        }
        private static bool IsUnrestGangType(int t) { return t >= 7 && t <= 18; }
        private static bool IsUnrestCopType(int t) { return t == 6 || t == 27 || t == 29; }

        // iter-51: the recruit-rejection census.
        //
        // On 08-11 `recruited` sat at 0-3 for a whole ten-minute riot and there was
        // no way to tell "the scan found two people" from "it found forty and
        // IsPersistent rejected all of them" — IsEligibleForUnrest returned a bare
        // bool and nothing logged how many candidates the scan even produced. That
        // is the single most expensive missing log line in this subsystem, so every
        // rejection now names itself. Counters are since-last-emit, not lifetime.
        private int urScanReturned, urRejDup, urRejDead, urRejPlayer, urRejPersistent,
                    urRejInVehicle, urRejBodyguard, urRejType, urRejScope, urAccepted;
        private long unrestScanLogTicks = 0;
        private const long UNREST_SCAN_LOG_INTERVAL = 50000000L;   // 5 s

        private bool IsEligibleForUnrest(Ped p, out int pedType)
        {
            pedType = -1;
            if (p == null || !p.Exists() || p.IsDead) { urRejDead++; return false; }
            if (p.Handle == Game.Player.Character.Handle) { urRejPlayer++; return false; }
            // IsPersistent catches mission peds and anything another script (or this
            // one — bodyguards, flight pilots) owns. Never touch those.
            //
            // iter-51: kept as a reject, but now COUNTED. This install runs several
            // other ped-owning scripts, and if they are marking the neighbourhood
            // persistent then this single line is the whole riot bug — which is a
            // claim the log has to be able to make or refute.
            if (p.IsPersistent) { urRejPersistent++; return false; }
            // Recruiting drivers turns the riot into traffic chaos that cannot be
            // narrated to someone who can't see it.
            if (p.IsInVehicle()) { urRejInVehicle++; return false; }
            foreach (Ped g in bodyguards)
                if (g != null && g.Exists() && g.Handle == p.Handle) { urRejBodyguard++; return false; }

            pedType = Function.Call<int>(Hash.GET_PED_TYPE, p);
            int scope = getSetting("unrestScope");
            if (IsUnrestCivilianType(pedType)) { urAccepted++; return true; }
            if (IsUnrestGangType(pedType))
            {
                if (scope == 1 || scope == 3) { urAccepted++; return true; }
                urRejScope++; return false;
            }
            if (IsUnrestCopType(pedType))
            {
                if (!(scope == 2 || scope == 3)) { urRejScope++; return false; }
                // Never pull police in while they have business with the player —
                // that is how dispatch desyncs and how riot kills start starring you.
                if (Game.Player.WantedLevel > 0) { urRejScope++; return false; }
                urAccepted++; return true;
            }
            urRejType++;
            return false;   // player, paramedic, firefighter, special, mission, animal
        }

        /// <summary>
        /// iter-51: emit the recruit-rejection census and reset it. Called from the
        /// unrest tick regardless of roster size — a riot with an empty roster is
        /// exactly the case this line exists to explain.
        /// </summary>
        private void LogUnrestScanCensus(long nowWall, int stage, int roster)
        {
            if (nowWall - unrestScanLogTicks < UNREST_SCAN_LOG_INTERVAL) return;
            unrestScanLogTicks = nowWall;
            UnrestLog("unrest-scan: returned=" + urScanReturned
                + " dup=" + urRejDup
                + " dead=" + urRejDead
                + " player=" + urRejPlayer
                + " persistent=" + urRejPersistent
                + " inVehicle=" + urRejInVehicle
                + " bodyguard=" + urRejBodyguard
                + " wrongType=" + urRejType
                + " scopeVeto=" + urRejScope
                + " eligible=" + urAccepted
                + " roster=" + roster
                + " radius=" + UNREST_STAGE_RADIUS[stage].ToString("F0")
                + " stage=" + stage);
            urScanReturned = urRejDup = urRejDead = urRejPlayer = urRejPersistent = 0;
            urRejInVehicle = urRejBodyguard = urRejType = urRejScope = urAccepted = 0;
        }

        private void EnsureUnrestGroups()
        {
            if (unrestGroupsCreated) return;
            for (int i = 0; i < 3; i++)
            {
                // ADD_RELATIONSHIP_GROUP is idempotent: re-calling with an existing
                // name hands back the existing hash, so a script reload is safe.
                OutputArgument outHash = new OutputArgument();
                Function.Call(Hash.ADD_RELATIONSHIP_GROUP, UNREST_GROUP_NAMES[i], outHash);
                unrestFactionHash[i] = outHash.GetResult<int>();
            }
            // iter-48: the engine's own built-in groups. Vanilla re_arrests.c sets
            // its criminal group to Dislike joaat("COP") exactly this way, and
            // re_armybase.c uses joaat("army") for the military. Resolved here
            // rather than in a static initialiser so the hash is computed inside a
            // live game session, like SweepOrphanedUnrestGroups already does.
            unrestCopGroupHash = unchecked((int)Game.GenerateHash("COP"));
            unrestArmyGroupHash = unchecked((int)Game.GenerateHash("ARMY"));
            unrestGroupsCreated = true;
        }

        /// <summary>
        /// Re-asserts faction -> player Respect in BOTH directions. Relationships are
        /// directional, so each pair needs two calls. This is the whole player-safety
        /// story: it lives on the group, so it covers every current and future member.
        /// </summary>
        private void AssertUnrestPlayerSafety()
        {
            if (!unrestGroupsCreated) return;
            int pg = Function.Call<int>(Hash.GET_PED_RELATIONSHIP_GROUP_HASH, Game.Player.Character);
            unrestPlayerGroupCached = pg;
            for (int i = 0; i < 3; i++)
            {
                // Respect (1), not Neutral — Neutral lets bodyguards open fire on
                // rioters, starting a fight the player never asked for and cannot
                // see. Guards still return fire when actually shot.
                Function.Call(Hash.SET_RELATIONSHIP_BETWEEN_GROUPS, 1, unrestFactionHash[i], pg);
                Function.Call(Hash.SET_RELATIONSHIP_BETWEEN_GROUPS, 1, pg, unrestFactionHash[i]);
            }
            unrestRelAssertTicks = ModClock.Ticks;
        }

        private void SetUnrestInterFactionRelationship(int rel)
        {
            if (!unrestGroupsCreated) return;
            for (int a = 0; a < 3; a++)
                for (int b = 0; b < 3; b++)
                    if (a != b)
                        Function.Call(Hash.SET_RELATIONSHIP_BETWEEN_GROUPS, rel,
                            unrestFactionHash[a], unrestFactionHash[b]);
        }

        private void StartCivilUnrest()
        {
            EnsureUnrestGroups();
            unrestActive = true;
            unrestStage = -1;
            unrestAnnouncedStage = -1;
            unrestStartTicks = ModClock.Ticks;
            unrestPeds.Clear();
            unrestHandles.Clear();
            unrestScanBuf = null;
            unrestScanCursor = 0;
            unrestScanTicks = 0;
            unrestProfileCursor = 0;
            unrestRegisterCursor = 0;
            unrestCompactCursor = 0;
            unrestCasualties = 0;
            unrestNextFaction = 0;
            unrestFirstGunAnnounced = false;
            unrestSafetyViolations = 0;
            unrestSafetyWindowTicks = 0;
            unrestStatFighting = 0;
            unrestStatArmed = 0;
            unrestStatNearestDist = 9999f;
            unrestStatNearestDir = "";
            unrestAccFighting = 0;
            unrestAccArmed = 0;
            unrestAccNearestDist = 9999f;
            unrestAccNearestDir = "";
            unrestLastRepFighting = -1;
            unrestLastRepDown = -1;
            unrestLastRepBucket = -1;
            unrestLastRepCops = false;
            unrestLastRepTraffic = false;

            // ---- iter-48 state ----
            unrestHeat = 0f;
            unrestHeatTicks = unrestStartTicks;
            unrestHeatAdvanceTicks = 0;
            unrestAccCombatEntries = 0;
            unrestStatCombatEntries = 0;
            unrestHeatEngagements = 0;
            unrestHeatPlayerShots = 0;
            // iter-51 teardown rows for the new heat inputs.
            unrestHeatPending = 0f;
            unrestHeatFires = 0;
            unrestHeatAlarms = 0;
            unrestHeatDispatches = 0;
            unrestHeatCasualtiesSeen = 0;
            unrestHeatStage = 0;
            unrestTimeStage = 0;
            unrestAchievedStage = -1;
            unrestPlayerWasShooting = false;
            unrestFrameActive = false;
            unrestFramePedDensity = 1f;
            unrestFrameVehDensity = 1f;
            unrestFrameScenarioZero = false;
            unrestVehScanBuf = null;
            unrestVehScanCursor = 0;
            unrestVehScanTicks = 0;
            unrestDriverCursor = 0;
            unrestTrafficArmed = false;
            unrestTrafficEffective = 0;
            unrestBarkCursor = 0;
            unrestLastBarkTicks = 0;
            unrestBarkLogCounter = 0;
            unrestLastAlarmTicks = 0;
            unrestLastFireTicks = 0;
            unrestCopRelApplied = 0;
            unrestArmyRelApplied = 0;
            unrestIncidentId = 0;
            unrestIncidentTicks = 0;
            unrestLastCopStopTicks = 0;
            unrestCopStopCount = 0;
            unrestStatCopsEngaged = 0;
            unrestFirstCasualtyAnnounced = false;
            unrestSpokenTicks.Clear();
            // Rosters are cleared rather than restored: a Start with live drivers or
            // an open cop stop can only happen after a Stop, which already restored
            // them, so anything still here is stale bookkeeping.
            unrestDrivers.Clear();
            unrestDriverHandles.Clear();
            unrestAlarmedVehs.Clear();
            unrestAlarmedHandles.Clear();
            unrestFireIds.Clear();
            unrestCopStop = null;
            unrestPoliceScanTicks = 0;
            unrestDispatchForced = false;

            AssertUnrestPlayerSafety();
            UnrestLog("unrest-start: scope=" + getSetting("unrestScope")
                + " melee=" + getSetting("unrestMelee")
                + " firearms=" + getSetting("unrestFirearms")
                + " escalation=" + getSetting("unrestEscalation")
                + " brutality=" + getSetting("unrestBrutality")
                + " ambience=" + getSetting("unrestAmbience")
                + " traffic=" + getSetting("unrestTraffic")
                + " police=" + getSetting("unrestPolice")
                + " fires=" + getSetting("unrestFires")
                // iter-51: pace changes every stage timestamp in the session, so a
                // log without it cannot be compared to any other log.
                + " pace=" + getSetting("unrestPace")
                + " paceScale=" + UnrestPaceScale().ToString("F2"));
        }

        private void RestoreUnrestPed(RiotPed rec)
        {
            if (rec == null) return;
            // iter-51 teardown row: an instigator carries a KEEP_TASK and a
            // non-temporary-event block that nothing else here would clear. Leaving
            // either behind strands an ambient ped permanently deaf and permanently
            // holding a combat task — the exact class of leak the iter-48 note below
            // was written about.
            rec.instigating = false;
            rec.instigateTargetHandle = 0;
            Ped p = rec.ped;
            if (p == null || !p.Exists() || p.Handle != rec.handle) return;
            try
            {
                Function.Call(Hash.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, p, false);
                Function.Call(Hash.SET_PED_KEEP_TASK, p, false);
                int def = rec.defaultGroup != 0
                    ? rec.defaultGroup
                    : Function.Call<int>(Hash.GET_PED_RELATIONSHIP_GROUP_DEFAULT_HASH, p);
                Function.Call(Hash.SET_PED_RELATIONSHIP_GROUP_HASH, p, def);

                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 5, false);   // AlwaysFight
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 13, false);  // Aggressive
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 46, false);  // FightArmedWhenUnarmed
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 50, false);  // CanCharge
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 58, false);  // DisableFleeFromCombat
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 63, true);   // FleesFromInvincible
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 0, false);   // CanUseCover
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 12, false);  // BlindFireInCover
                // iter-48: everything ApplyUnrestStageProfile / TryArmUnrestPed wrote
                // that this method used to leak. Without these, every ex-rioter within
                // the recruit radius stayed permanently hyper-alert after the riot
                // ended — ambient peds reacting to things they should not, with no
                // explanation a blind player could possibly get.
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 27, false);  // PerfectAccuracy
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 49, false);  // EnemyAccuracyScaling
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 21, false);  // CanChaseTargetOnFoot
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 28, false);  // CanUseFrustratedAdvance
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 31, true);   // MaintainMinDistanceToTarget
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 42, false);  // CanFlank
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 43, false);  // SwitchToAdvanceIfCantFindCover
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 54, true);   // AlwaysEquipBestWeapon
                Function.Call(Hash.SET_PED_COMBAT_RANGE, p, 1);               // CR_Medium
                Function.Call(Hash.SET_PED_TARGET_LOSS_RESPONSE, p, 0);       // TLR_ExitTask
                Function.Call(Hash.SET_PED_SEEING_RANGE, p, 30f);
                Function.Call(Hash.SET_PED_HEARING_RANGE, p, 50f);
                Function.Call(Hash.SET_PED_SHOOT_RATE, p, 100);
                Function.Call(Hash.SET_PED_MOVE_RATE_OVERRIDE, p, 1f);
                Function.Call(Hash.SET_PED_PATH_CAN_USE_CLIMBOVERS, p, false);
                if (rec.origAccuracy >= 0)
                    Function.Call(Hash.SET_PED_ACCURACY, p, rec.origAccuracy);
                Function.Call(Hash.SET_PED_CONFIG_FLAG, p, 150, true);        // CowerInsteadOfFlee
                if (IsUnrestCivilianType(rec.pedType))
                    Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 17, true); // AlwaysFlee
                Function.Call(Hash.SET_PED_FLEE_ATTRIBUTES, p, 0, false);
                Function.Call(Hash.SET_PED_ALERTNESS, p, 0);
                Function.Call(Hash.SET_PED_COMBAT_MOVEMENT, p, 1);
                Function.Call(Hash.SET_PED_COMBAT_ABILITY, p, 0);
                Function.Call(Hash.SET_PED_CONFIG_FLAG, p, 42, false);

                // Armed civilians still wandering the city after the riot ends is
                // exactly the kind of unexplained lethal danger a blind player
                // cannot anticipate. Take back what we handed out.
                if (rec.hasWeapon)
                {
                    try { p.Weapons.Remove(rec.givenWeapon); } catch { }
                }

                Function.Call(Hash.CLEAR_PED_TASKS, p);
                p.MarkAsNoLongerNeeded();   // never delete peds
            }
            catch { }
        }

        // ===================================================================
        // TEARDOWN — every piece of global state this feature touches, and where
        // it is undone. onAborted funnels through here, so anything added to this
        // method is covered by the abort path for free.
        //
        //   groups / player Respect ....... below, unchanged since iter-44
        //   per-ped attrs + accuracy ...... RestoreUnrestPed
        //   faction -> COP / ARMY ......... ClearUnrestCopRelationships
        //   retasked drivers .............. RestoreAllUnrestDrivers
        //   in-flight cop stop ............ ResolveCopStop
        //   car alarms .................... ClearUnrestAlarms
        //   script fires .................. ClearUnrestFires
        //   dispatch incident ............. ClearUnrestIncident
        //   SWAT/army dispatch services ... RestoreUnrestDispatch
        //   density multipliers ........... unrestFrameActive = false (self-healing:
        //                                   _THIS_FRAME natives revert next frame,
        //                                   which is exactly why they were chosen
        //                                   over ADD_POP_MULTIPLIER_AREA)
        //
        // Anything NOT recoverable after a hard SHVDN reload that skips onAborted is
        // handled as far as possible by SweepOrphanedUnrestGroups; the residuals it
        // cannot fix (original accuracy, handed-out weapons, FireIds, incident id)
        // are documented there.
        // ===================================================================
        private void StopCivilUnrest(string reason)
        {
            bool wasActive = unrestActive;
            int involved = unrestPeds.Count;
            int drivers = unrestDrivers.Count;
            int alarms = unrestAlarmedVehs.Count;
            int fires = unrestFireIds.Count;
            bool hadGroups = unrestGroupsCreated;
            unrestActive = false;

            // Order matters: hand every ped back its own group BEFORE the groups
            // are removed, or the restore targets a hash that no longer exists.
            for (int i = 0; i < unrestPeds.Count; i++) RestoreUnrestPed(unrestPeds[i]);
            unrestPeds.Clear();
            unrestHandles.Clear();

            // iter-48 subsystems, all before the group removal for the same reason.
            if (unrestCopStop != null) ResolveCopStop("stop");
            RestoreAllUnrestDrivers();
            ClearUnrestAlarms();
            ClearUnrestFires();
            ClearUnrestIncident();
            RestoreUnrestDispatch();
            ClearUnrestCopRelationships();
            unrestFrameActive = false;
            unrestFramePedDensity = 1f;
            unrestFrameVehDensity = 1f;
            unrestFrameScenarioZero = false;

            if (unrestGroupsCreated)
            {
                try
                {
                    for (int a = 0; a < 3; a++)
                        for (int b = 0; b < 3; b++)
                            if (a != b)
                                Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 5,
                                    unrestFactionHash[a], unrestFactionHash[b]);
                    if (unrestPlayerGroupCached != 0)
                    {
                        for (int i = 0; i < 3; i++)
                        {
                            Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 1,
                                unrestFactionHash[i], unrestPlayerGroupCached);
                            Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 1,
                                unrestPlayerGroupCached, unrestFactionHash[i]);
                        }
                    }
                    for (int i = 0; i < 3; i++)
                        Function.Call(Hash.REMOVE_RELATIONSHIP_GROUP, unrestFactionHash[i]);
                }
                catch { }
                unrestGroupsCreated = false;
            }

            unrestStage = -1;
            unrestAnnouncedStage = -1;
            unrestScanBuf = null;
            unrestScanCursor = 0;
            unrestProfileCursor = 0;
            unrestRegisterCursor = 0;
            unrestCompactCursor = 0;
            // iter-51 teardown rows (the table above this method lists one per
            // sub-feature; these are the new ones).
            unrestScenarioCursor = 0;
            unrestScenarioPulls = 0;
            unrestInstigators = 0;
            unrestInstigateTotal = 0;
            unrestInstigateTicks = 0;
            urScanReturned = urRejDup = urRejDead = urRejPlayer = urRejPersistent = 0;
            urRejInVehicle = urRejBodyguard = urRejType = urRejScope = urAccepted = 0;
            unrestStatFighting = 0;
            unrestStatArmed = 0;
            unrestStatNearestDist = 9999f;
            unrestStatNearestDir = "";
            unrestStatCopsEngaged = 0;
            unrestVehScanBuf = null;
            unrestVehScanCursor = 0;
            unrestDriverCursor = 0;
            unrestBarkCursor = 0;
            unrestTrafficArmed = false;
            unrestTrafficEffective = 0;

            UnrestLog("unrest-stop: reason=" + reason + " involved=" + involved
                + " casualties=" + unrestCasualties
                + " drivers=" + drivers + " alarms=" + alarms + " fires=" + fires
                + " copStops=" + unrestCopStopCount
                + " copsRelCleared=" + (hadGroups ? 1 : 0)
                + " heat=" + ((int)unrestHeat) + " peakStage=" + unrestAchievedStage);

            if (wasActive && reason != "abort")
            {
                Speech.Info("Civil unrest ended. " + involved + " were involved, at least "
                    + unrestCasualties + " went down.");
            }
        }

        /// <summary>
        /// One-shot recovery for a hard SHVDN reload that skipped Aborted, which would
        /// otherwise strand peds in GTA11Y_RIOT_* with mutual Hate and no owner.
        /// </summary>
        private void SweepOrphanedUnrestGroups()
        {
            unrestOrphanSweepDone = true;
            try
            {
                // A relationship group's hash IS the joaat of its name, so existence
                // can be tested WITHOUT calling ADD_RELATIONSHIP_GROUP first —
                // which would create the group and make the test trivially true.
                bool anyExisted = false;
                int[] hashes3 = new int[3];
                for (int i = 0; i < 3; i++)
                {
                    hashes3[i] = unchecked((int)Game.GenerateHash(UNREST_GROUP_NAMES[i]));
                    if (Function.Call<bool>(Hash.DOES_RELATIONSHIP_GROUP_EXIST, hashes3[i]))
                        anyExisted = true;
                }
                // Nothing survived a previous run: no orphans possible, nothing to do.
                if (!anyExisted) return;

                for (int a = 0; a < 3; a++)
                    for (int b = 0; b < 3; b++)
                        if (a != b)
                            Function.Call(Hash.SET_RELATIONSHIP_BETWEEN_GROUPS, 3, hashes3[a], hashes3[b]);

                int pg = Function.Call<int>(Hash.GET_PED_RELATIONSHIP_GROUP_HASH, Game.Player.Character);
                for (int i = 0; i < 3; i++)
                {
                    Function.Call(Hash.SET_RELATIONSHIP_BETWEEN_GROUPS, 1, hashes3[i], pg);
                    Function.Call(Hash.SET_RELATIONSHIP_BETWEEN_GROUPS, 1, pg, hashes3[i]);
                }

                // iter-48: the faction -> COP / ARMY edges unrestPolice may have set.
                // These outlive the riot exactly like the inter-faction ones do, and
                // an orphaned Hate toward the police is a permanent city-wide gunfight.
                int copG = unchecked((int)Game.GenerateHash("COP"));
                int armyG = unchecked((int)Game.GenerateHash("ARMY"));
                for (int i = 0; i < 3; i++)
                {
                    Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 4, hashes3[i], copG);
                    Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 5, hashes3[i], copG);
                    Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 4, hashes3[i], armyG);
                    Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 5, hashes3[i], armyG);
                }

                int restored = 0;
                Ped[] near = World.GetNearbyPeds(Game.Player.Character.Position, 100f);
                foreach (Ped p in near)
                {
                    if (p == null || !p.Exists()) continue;
                    int g = Function.Call<int>(Hash.GET_PED_RELATIONSHIP_GROUP_HASH, p);
                    if (g != hashes3[0] && g != hashes3[1] && g != hashes3[2]) continue;
                    int def = Function.Call<int>(Hash.GET_PED_RELATIONSHIP_GROUP_DEFAULT_HASH, p);
                    Function.Call(Hash.SET_PED_RELATIONSHIP_GROUP_HASH, p, def);
                    Function.Call(Hash.SET_PED_CONFIG_FLAG, p, 42, false);
                    Function.Call(Hash.SET_PED_CONFIG_FLAG, p, 150, true);
                    // The sweep cannot know a ped's original accuracy or what weapon it
                    // was handed — those residuals are documented and unavoidable — but
                    // perception and combat range are absolute values, so they can be.
                    Function.Call(Hash.SET_PED_COMBAT_RANGE, p, 1);
                    Function.Call(Hash.SET_PED_SEEING_RANGE, p, 30f);
                    Function.Call(Hash.SET_PED_HEARING_RANGE, p, 50f);
                    Function.Call(Hash.SET_PED_MOVE_RATE_OVERRIDE, p, 1f);
                    Function.Call(Hash.SET_PED_SHOOT_RATE, p, 100);
                    Function.Call(Hash.SET_PED_ALERTNESS, p, 0);
                    Function.Call(Hash.CLEAR_PED_TASKS, p);
                    p.MarkAsNoLongerNeeded();
                    restored++;
                }
                for (int i = 0; i < 3; i++)
                    Function.Call(Hash.REMOVE_RELATIONSHIP_GROUP, hashes3[i]);

                // iter-48: the only genuinely dangerous residue a hard reload can leave
                // is a driver with steers-around-peds cleared — a car that will run the
                // player down forever. Forcing both flags back to true is idempotent and
                // true IS the vanilla default, so this is safe even on a clean start.
                int driversHealed = 0;
                try
                {
                    foreach (Vehicle v in World.GetNearbyVehicles(Game.Player.Character.Position, 80f))
                    {
                        if (v == null || !v.Exists()) continue;
                        Ped d = v.Driver;
                        if (d == null || !d.Exists() || d.IsDead) continue;
                        if (d.Handle == Game.Player.Character.Handle) continue;
                        Function.Call(Hash.SET_PED_STEERS_AROUND_PEDS, d, true);
                        Function.Call(Hash.SET_PED_STEERS_AROUND_VEHICLES, d, true);
                        driversHealed++;
                    }
                }
                catch { }

                UnrestLog("unrest-orphan-sweep: restored=" + restored
                    + " driversHealed=" + driversHealed);
            }
            catch { }
        }

        private void ApplyUnrestStageProfile(RiotPed rec, int stage)
        {
            Ped p = rec.ped;
            if (p == null || !p.Exists() || p.IsDead) return;
            rec.profiledStage = stage;

            // A ped with BlockPermanentEvents ignores the world entirely and will
            // never react to a hate relationship. This is the single most likely
            // cause of "the riot never starts" — keep both false, always.
            p.BlockPermanentEvents = false;
            p.AlwaysKeepTask = false;
            Function.Call(Hash.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, p, false);

            Function.Call(Hash.SET_PED_ALERTNESS, p, stage <= 0 ? 1 : (stage == 1 ? 2 : 3));
            if (stage <= 0) return;

            int brutal = unrestBrutalityCached;

            // Stage 1 — agitation: they will stand their ground and advance.
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 5, true);    // AlwaysFight
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 17, false);  // AlwaysFlee off
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 58, true);   // DisableFleeFromCombat
            Function.Call(Hash.SET_PED_FLEE_ATTRIBUTES, p, 0, false);
            Function.Call(Hash.SET_PED_COMBAT_ABILITY, p, 1);             // Average
            Function.Call(Hash.SET_PED_COMBAT_MOVEMENT, p, 2);            // WillAdvance
            if (stage == 1) return;

            // Stage 2 — unrest: aggressive, will engage armed peds unarmed, sees far.
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 13, true);   // Aggressive
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 46, true);   // FightArmedWhenUnarmed
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 50, true);   // CanCharge
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 63, false);  // FleesFromInvincible off
            Function.Call(Hash.SET_PED_SEEING_RANGE, p, 60f);
            Function.Call(Hash.SET_PED_HEARING_RANGE, p, 80f);

            if (brutal >= 1)
            {
                // Vanilla's own ambient brawl (re_gangfight) runs 100 m perception and
                // lets peds chase; ours hung back because nothing told them to close.
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 21, true);   // CanChaseTargetOnFoot
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 31, false);  // MaintainMinDistanceToTarget
                Function.Call(Hash.SET_PED_PATH_CAN_USE_CLIMBOVERS, p, true); // don't stall on a fence
            }
            if (stage == 2) return;

            // Stage 3+ — full riot.
            Function.Call(Hash.SET_PED_COMBAT_ABILITY, p, 2);             // Professional
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 0, true);    // CanUseCover

            if (brutal <= 0)
            {
                // Unchanged iter-44 behaviour, kept verbatim so brutality 0 is a true
                // baseline to measure the other tiers against.
                Function.Call(Hash.SET_PED_COMBAT_RANGE, p, 1);               // CR_Medium
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 12, true);   // BlindFireInCover
                return;
            }

            // CR_Near is THE change that turns a standoff into a brawl: re_gangfight.c
            // uses 0 for its melee variant and 1 only for the gun variant, and our
            // stage 3 was using 1. It is also the safer value here — a fight that
            // collapses into a tight knot is one localised sound source the nav
            // scanner can report, instead of combatants spread across a street.
            Function.Call(Hash.SET_PED_COMBAT_RANGE, p, 0);               // CR_Near
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 43, true);   // SwitchToAdvanceIfCantFindCover
            // Counter-intuitive but deliberate: "more brutal" must mean closer and more
            // committed, NOT more rounds in the air. Blind fire from cover is unaimed
            // spray, precisely the class that kills a player who cannot see the shooter.
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 12, false);  // BlindFireInCover OFF
            Function.Call(Hash.SET_COMBAT_FLOAT, p, 0, 0f);               // BlindFireChance 0

            if (brutal < 2) return;

            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 42, true);   // CanFlank
            Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 28, true);   // CanUseFrustratedAdvance
            Function.Call(Hash.SET_PED_TARGET_LOSS_RESPONSE, p, 2);       // TLR_SearchForTarget
            Function.Call(Hash.SET_PED_SHOOT_RATE, p,
                UNREST_SHOOT_RATE[stage < UNREST_SHOOT_RATE.Length ? stage : UNREST_SHOOT_RATE.Length - 1]);
        }

        private void RecruitUnrestPed(Ped p, int pedType)
        {
            RiotPed rec = new RiotPed();
            rec.ped = p;
            rec.handle = p.Handle;
            rec.pedType = pedType;
            // Capture the default BEFORE the overwrite — afterwards it is gone.
            rec.defaultGroup = Function.Call<int>(Hash.GET_PED_RELATIONSHIP_GROUP_DEFAULT_HASH, p);
            // Same reasoning for accuracy: TryArmUnrestPed pins it to 15 and there is
            // no way back to the model's own value once that happens.
            try { rec.origAccuracy = Function.Call<int>(Hash.GET_PED_ACCURACY, p); }
            catch { rec.origAccuracy = -1; }
            rec.faction = unrestNextFaction;
            unrestNextFaction = (unrestNextFaction + 1) % 3;

            Function.Call(Hash.SET_PED_RELATIONSHIP_GROUP_HASH, p, unrestFactionHash[rec.faction]);
            // Riot deaths must not put stars on the player.
            Function.Call(Hash.SET_PED_CONFIG_FLAG, p, 42, true);   // DontInfluenceWantedLevel
            Function.Call(Hash.SET_PED_CONFIG_FLAG, p, 150, false); // CowerInsteadOfFlee off
            Function.Call(Hash.SET_PED_AS_ENEMY, p, false);

            ApplyUnrestStageProfile(rec, unrestStage);

            unrestPeds.Add(rec);
            unrestHandles.Add(rec.handle);
        }

        private void TryArmUnrestPed(RiotPed rec, int tier, int pct, bool melee, bool guns)
        {
            if (rec.hasWeapon) return;
            if (rec.armTierRolled >= tier) return;
            // Burn no tier while both handout toggles are off, so flipping one on
            // mid-riot takes effect immediately instead of after the next tier.
            if (!melee && !guns) return;
            // Stamp the tier FIRST and unconditionally. Without this the roll
            // repeats every slice and 5% compounds to a certainty within seconds.
            rec.armTierRolled = tier;
            if (random.Next(100) >= pct) return;

            bool giveMelee;
            if (melee && guns) giveMelee = random.Next(100) < UNREST_MELEE_SHARE_PCT;
            else giveMelee = melee;

            Ped p = rec.ped;
            if (p == null || !p.Exists() || p.IsDead) return;

            if (giveMelee)
            {
                rec.givenWeapon = UNREST_MELEE[random.Next(UNREST_MELEE.Length)];
                p.Weapons.Give(rec.givenWeapon, 1, true, true);
            }
            else
            {
                rec.givenWeapon = UNREST_FIREARMS[random.Next(UNREST_FIREARMS.Length)];
                p.Weapons.Give(rec.givenWeapon, 24 + random.Next(37), true, true);
                // Deliberately terrible marksmanship, so stray rounds near a player
                // who cannot see the shooter are rare.
                Function.Call(Hash.SET_PED_ACCURACY, p, 15);
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 27, false); // PerfectAccuracy off
                Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, p, 49, true);  // EnemyAccuracyScaling

                if (!unrestFirstGunAnnounced)
                {
                    try
                    {
                        if (p.Position.DistanceTo(Game.Player.Character.Position) < 40f)
                        {
                            unrestFirstGunAnnounced = true;
                            Speech.Critical("Someone near you has a gun.");
                        }
                    }
                    catch { }
                }
            }
            rec.hasWeapon = true;
        }

        // ===================================================================
        // iter-48: AGGRESSIVE TRAFFIC
        //
        // A roster entirely separate from unrestPeds. IsEligibleForUnrest still
        // rejects anyone in a vehicle for the reason stated there, so no ped is
        // ever on both lists and the riot is never narrated as traffic chaos.
        // ===================================================================

        private bool IsEligibleUnrestDriver(Vehicle v, out Ped driver)
        {
            driver = null;
            if (v == null || !v.Exists() || v.IsDead) return false;
            // Emergency and military vehicles belong to the police feature, not this one.
            if (v.ClassType == VehicleClass.Emergency || v.ClassType == VehicleClass.Military)
                return false;
            Ped pc = Game.Player.Character;
            if (pc != null && pc.CurrentVehicle != null && pc.CurrentVehicle.Handle == v.Handle)
                return false;
            Ped d = v.GetPedOnSeat(VehicleSeat.Driver);
            if (d == null || !d.Exists() || d.IsDead) return false;
            if (pc != null && d.Handle == pc.Handle) return false;
            if (d.IsPersistent) return false;                 // mission ped or another script's
            if (unrestHandles.Contains(d.Handle)) return false;  // never double-manage a rioter
            if (unrestDriverHandles.Contains(d.Handle)) return false;
            foreach (Ped g in bodyguards)
                if (g != null && g.Exists() && g.Handle == d.Handle) return false;
            int pt = Function.Call<int>(Hash.GET_PED_TYPE, d);
            if (IsUnrestCopType(pt)) return false;
            if (pt == 20 || pt == 21) return false;           // paramedic, firefighter
            driver = d;
            return true;
        }

        /// <summary>
        /// Apply the stage's driving profile. Level 2 (Reckless) is the only thing in
        /// Civil Unrest that can kill an on-foot player outright, so it carries three
        /// independent guards: a hard requirement on Navigation Assist (whose on-foot
        /// time-to-collision alert is the ONLY warning a blind pedestrian gets), a
        /// no-arm bubble around the player, and an eject pass in the compaction slice.
        /// </summary>
        private void ArmUnrestDriver(RiotDriver d, int stage, int level, long nowMod)
        {
            Ped p = d.driver;
            Vehicle v = d.veh;
            if (p == null || !p.Exists() || p.IsDead) return;
            if (v == null || !v.Exists()) return;

            float dist = 9999f;
            bool playerOnFoot = false;
            try
            {
                Ped pc = Game.Player.Character;
                dist = v.Position.DistanceTo(pc.Position);
                playerOnFoot = !pc.IsInVehicle();
            }
            catch { }

            Function.Call(Hash.SET_DRIVER_AGGRESSIVENESS, p, UNREST_DRIVER_AGGR[stage]);
            Function.Call(Hash.SET_DRIVER_ABILITY, p, UNREST_DRIVER_ABIL[stage]);

            int style = UNREST_DRIVE_STYLE_AGGRESSIVE;
            bool wantSteersOff = level >= 2 && stage >= 3
                                 && !(playerOnFoot && dist < UNREST_DRIVER_SAFE_RADIUS);
            if (wantSteersOff)
            {
                style = UNREST_DRIVE_STYLE_RECKLESS;
                Function.Call(Hash.SET_PED_STEERS_AROUND_PEDS, p, false);
                d.steersOff = true;
                // Only at the very top, and never while the player is driving with
                // steering assist on: riot traffic must not pollute the drive-assist
                // damage signal, which is this project's primary quality metric.
                if (stage >= 4 && !(!playerOnFoot && getSetting("steeringAssist") > 0))
                    Function.Call(Hash.SET_PED_STEERS_AROUND_VEHICLES, p, false);
            }
            else if (d.steersOff)
            {
                Function.Call(Hash.SET_PED_STEERS_AROUND_PEDS, p, true);
                Function.Call(Hash.SET_PED_STEERS_AROUND_VEHICLES, p, true);
                d.steersOff = false;
            }

            if (nowMod - d.taskTicks >= UNREST_DRIVER_RETASK_TICKS)
            {
                d.taskTicks = nowMod;
                Function.Call(Hash.TASK_VEHICLE_DRIVE_WANDER, p, v, UNREST_DRIVER_SPEED[stage], style);
                // Free, fully diegetic directional audio for an on-foot player: a horn
                // is the one traffic cue that arrives before the car does.
                if (playerOnFoot && dist < 40f && random.Next(100) < 20)
                    Function.Call(Hash.START_VEHICLE_HORN, v, 500, 0, false);
            }
            d.appliedStage = stage;
        }

        private void RestoreUnrestDriver(RiotDriver d)
        {
            if (d == null) return;
            try
            {
                Ped p = d.driver;
                if (p == null || !p.Exists() || p.Handle != d.driverHandle) return;
                Function.Call(Hash.SET_DRIVER_AGGRESSIVENESS, p, 0.5f);
                Function.Call(Hash.SET_DRIVER_ABILITY, p, 0.5f);
                Function.Call(Hash.SET_PED_STEERS_AROUND_PEDS, p, true);
                Function.Call(Hash.SET_PED_STEERS_AROUND_VEHICLES, p, true);
                d.steersOff = false;
                Function.Call(Hash.CLEAR_PED_TASKS, p);
                Vehicle v = d.veh;
                if (v != null && v.Exists() && v.Handle == d.vehHandle)
                {
                    // Hand the car back to traffic rather than leaving it parked in a
                    // live lane with no task, which is its own hazard.
                    Function.Call(Hash.TASK_VEHICLE_DRIVE_WANDER, p, v, 12f, UNREST_DRIVE_STYLE_NORMAL);
                    v.MarkAsNoLongerNeeded();
                }
                p.MarkAsNoLongerNeeded();   // never delete
            }
            catch { }
        }

        private void RestoreAllUnrestDrivers()
        {
            for (int i = 0; i < unrestDrivers.Count; i++) RestoreUnrestDriver(unrestDrivers[i]);
            unrestDrivers.Clear();
            unrestDriverHandles.Clear();
            unrestTrafficArmed = false;
        }

        /// <summary>
        /// The one allocating vehicle scan, shared by aggressive traffic and car
        /// alarms so GetNearbyVehicles runs once per 3 s no matter which of the two
        /// is enabled. Budgeted exactly like the ped recruit slice above.
        /// </summary>
        private void TickUnrestVehicleScan(long nowWall, long nowMod, int stage)
        {
            bool wantDrivers = unrestTrafficEffective >= 1 && stage >= 2
                               && unrestDrivers.Count < UNREST_MAX_DRIVERS;
            bool wantAlarms = unrestAmbienceCached >= 2 && stage >= 2
                              && unrestAlarmedVehs.Count < UNREST_ALARM_MAX
                              && nowWall - unrestLastAlarmTicks >= UNREST_ALARM_GAP[stage];
            if (!wantDrivers && !wantAlarms) return;

            if (nowWall - unrestVehScanTicks > UNREST_VEH_SCAN_INTERVAL_TICKS)
            {
                unrestVehScanTicks = nowWall;
                try
                {
                    unrestVehScanBuf = World.GetNearbyVehicles(
                        Game.Player.Character.Position, UNREST_DRIVER_SCAN_RADIUS);
                }
                catch { unrestVehScanBuf = null; }
                unrestVehScanCursor = 0;
            }
            if (unrestVehScanBuf == null) return;

            GTA.Math.Vector3 pPos = Game.Player.Character.Position;
            int done = 0;
            while (unrestVehScanCursor < unrestVehScanBuf.Length && done < UNREST_VEH_SCAN_BUDGET)
            {
                Vehicle v = unrestVehScanBuf[unrestVehScanCursor++];
                done++;
                // The buffer is up to 3 s stale and handles get reused.
                if (v == null || !v.Exists()) continue;

                if (wantDrivers && unrestDrivers.Count < UNREST_MAX_DRIVERS)
                {
                    Ped drv;
                    if (IsEligibleUnrestDriver(v, out drv))
                    {
                        RiotDriver d = new RiotDriver();
                        d.driver = drv;
                        d.veh = v;
                        d.driverHandle = drv.Handle;
                        d.vehHandle = v.Handle;
                        d.taskTicks = 0;
                        unrestDrivers.Add(d);
                        unrestDriverHandles.Add(d.driverHandle);
                        unrestTrafficArmed = true;
                        UnrestLog("unrest-driver: act=arm handle=" + d.driverHandle
                            + " veh=" + d.vehHandle
                            + " dist=" + ((int)v.Position.DistanceTo(pPos)) + " why=scan");
                        continue;
                    }
                }

                if (wantAlarms && nowWall - unrestLastAlarmTicks >= UNREST_ALARM_GAP[stage]
                    && unrestAlarmedVehs.Count < UNREST_ALARM_MAX)
                {
                    if (v.GetPedOnSeat(VehicleSeat.Driver) != null) continue;
                    if (unrestAlarmedHandles.Contains(v.Handle)) continue;
                    float ad = v.Position.DistanceTo(pPos);
                    // An alarm on top of the player masks the nav pulse train.
                    if (ad < UNREST_ALARM_MIN_DIST || ad > UNREST_ALARM_MAX_DIST) continue;
                    Function.Call(Hash.SET_VEHICLE_ALARM, v, true);
                    Function.Call(Hash.START_VEHICLE_ALARM, v);
                    unrestAlarmedVehs.Add(v);
                    unrestAlarmedHandles.Add(v.Handle);
                    unrestLastAlarmTicks = nowWall;
                    // iter-51: a street full of alarms is the riot escalating.
                    unrestHeatPending += UNREST_HEAT_PER_ALARM;
                    unrestHeatAlarms++;
                    UnrestLog("unrest-alarm: veh=" + v.Handle + " dist=" + ((int)ad)
                        + " n=" + unrestAlarmedVehs.Count);
                }
            }
        }

        /// <summary>
        /// Arm / refresh / eject the driver roster, budgeted. The eject pass is the
        /// last line of defence for an on-foot player: any riot car that gets inside
        /// UNREST_DRIVER_EJECT_RADIUS is handed straight back to normal driving.
        /// </summary>
        private void TickUnrestDrivers(long nowMod, int stage)
        {
            if (unrestDrivers.Count == 0) return;
            int level = unrestTrafficEffective;
            GTA.Math.Vector3 pPos;
            bool playerOnFoot;
            try
            {
                Ped pc = Game.Player.Character;
                pPos = pc.Position;
                playerOnFoot = !pc.IsInVehicle();
            }
            catch { return; }

            for (int n = 0; n < UNREST_DRIVER_BUDGET && unrestDrivers.Count > 0; n++)
            {
                if (unrestDriverCursor >= unrestDrivers.Count) unrestDriverCursor = 0;
                RiotDriver d = unrestDrivers[unrestDriverCursor];
                Ped p = d.driver;
                Vehicle v = d.veh;

                bool gone = p == null || !p.Exists() || p.Handle != d.driverHandle || p.IsDead
                            || v == null || !v.Exists() || v.Handle != d.vehHandle;
                if (gone)
                {
                    // Restore anyway: the car being destroyed does not mean the DRIVER
                    // died with it, and a survivor left with steers-around-peds cleared
                    // is exactly the residue that runs the player down later.
                    // RestoreUnrestDriver revalidates both handles itself, so this is a
                    // no-op when the ped really is gone.
                    RestoreUnrestDriver(d);
                    unrestDriverHandles.Remove(d.driverHandle);
                    unrestDrivers.RemoveAt(unrestDriverCursor);
                    continue;
                }
                // The driver got out, or a rioter climbed in: either way it is no
                // longer ours to steer.
                Ped seated = v.GetPedOnSeat(VehicleSeat.Driver);
                bool leftSeat = seated == null || seated.Handle != d.driverHandle;
                if (leftSeat || level <= 0 || stage < 2)
                {
                    RestoreUnrestDriver(d);
                    unrestDriverHandles.Remove(d.driverHandle);
                    unrestDrivers.RemoveAt(unrestDriverCursor);
                    UnrestLog("unrest-driver: act=release handle=" + d.driverHandle
                        + " veh=" + d.vehHandle
                        + " why=" + (leftSeat ? "left-seat" : "gate-off"));
                    continue;
                }

                float dist = v.Position.DistanceTo(pPos);
                if (playerOnFoot && dist < UNREST_DRIVER_EJECT_RADIUS)
                {
                    RestoreUnrestDriver(d);
                    unrestDriverHandles.Remove(d.driverHandle);
                    unrestDrivers.RemoveAt(unrestDriverCursor);
                    UnrestLog("unrest-driver: act=eject handle=" + d.driverHandle
                        + " veh=" + d.vehHandle + " dist=" + ((int)dist)
                        + " why=player-proximity");
                    continue;
                }

                if (d.appliedStage != stage || nowMod - d.taskTicks >= UNREST_DRIVER_RETASK_TICKS)
                    ArmUnrestDriver(d, stage, level, nowMod);
                unrestDriverCursor++;
            }
        }

        // ===================================================================
        // iter-48: RIOT AMBIENCE — barks, alarms, fires
        // ===================================================================

        /// <summary>
        /// Engine ped barks. This is the highest-value item in the whole overhaul for
        /// a blind player: the crowd literally sounds like a riot and it costs zero
        /// TTS bandwidth. Arbitration with the screen reader is ONE-WAY — barks yield
        /// to speech, speech never waits for a bark.
        /// </summary>
        private void TickUnrestBarks(long nowWall, int stage)
        {
            if (unrestAmbienceCached < 1 || stage < 1) return;
            if (nowWall - unrestLastBarkTicks < UNREST_BARK_GAP[stage]) return;
            // Never talk over the reader.
            if (nowWall - Speech.LastEmittedWallTicks < UNREST_BARK_QUIET_TICKS) return;

            GTA.Math.Vector3 pPos;
            try { pPos = Game.Player.Character.Position; } catch { return; }

            string[] pool = stage >= 3 ? UNREST_BARKS_C
                          : (stage == 2 ? UNREST_BARKS_B : UNREST_BARKS_A);

            for (int n = 0; n < UNREST_BARK_BUDGET && unrestPeds.Count > 0; n++)
            {
                if (unrestBarkCursor >= unrestPeds.Count) unrestBarkCursor = 0;
                RiotPed rec = unrestPeds[unrestBarkCursor++];
                Ped p = rec.ped;
                if (p == null || !p.Exists() || p.IsDead) continue;
                if (nowWall - rec.lastBarkTicks < UNREST_BARK_PED_COOLDOWN) continue;
                float d = p.Position.DistanceTo(pPos);
                if (d > UNREST_BARK_MAX_DIST) continue;
                // A shout at arm's length masks the nav-assist pulse train entirely.
                if (stage >= 3 && d < UNREST_BARK_MIN_DIST_LOUD) continue;

                // Terrified bystanders under shouting aggressors is what a riot
                // actually sounds like — and it is the only cue that tells a blind
                // player the crowd contains victims, not just combatants.
                bool scared = stage >= 2 && !p.IsInCombat && IsUnrestCivilianType(rec.pedType);
                string[] use = scared ? UNREST_BARKS_FEAR : pool;
                string name = use[random.Next(use.Length)];

                // Third arg is a speech PARAM, not a voice name — passing a voice
                // name here yields silence. Matches re_gangfight.c.
                Function.Call(Hash.PLAY_PED_AMBIENT_SPEECH_NATIVE, p, name,
                    stage >= 3 ? "SPEECH_PARAMS_FORCE_SHOUTED" : "SPEECH_PARAMS_FORCE", 1);

                rec.lastBarkTicks = nowWall;
                unrestLastBarkTicks = nowWall;
                // Sampled: at a 300 ms gap this would be ~200 lines a minute.
                if ((++unrestBarkLogCounter % 10) == 0)
                    UnrestLog("unrest-bark: name=" + name + " stage=" + stage
                        + " dist=" + ((int)d) + " ped=" + rec.handle);
                return;   // one bark per slice, whatever the budget found
            }
        }

        private void ClearUnrestAlarms()
        {
            for (int i = 0; i < unrestAlarmedVehs.Count; i++)
            {
                try
                {
                    Vehicle v = unrestAlarmedVehs[i];
                    if (v != null && v.Exists())
                    {
                        Function.Call(Hash.SET_VEHICLE_ALARM, v, false);
                        v.MarkAsNoLongerNeeded();
                    }
                }
                catch { }
            }
            unrestAlarmedVehs.Clear();
            unrestAlarmedHandles.Clear();
        }

        private void ClearUnrestFires()
        {
            for (int i = 0; i < unrestFireIds.Count; i++)
            {
                try { Function.Call(Hash.REMOVE_SCRIPT_FIRE, unrestFireIds[i]); }
                catch { }
            }
            unrestFireIds.Clear();
        }

        /// <summary>
        /// Street fires. Double-gated (unrestFires AND unrestAmbience == 2) and stage 4
        /// only, because a blind player who simply walks forward into one burns to
        /// death with no warning — and because FireIds are process-local, so a hard
        /// SHVDN reload strands them with no recovery path. Every fire is announced
        /// Critical with a bearing at ANY narration verbosity, including Off.
        /// </summary>
        private void TickUnrestFires(long nowMod, int stage)
        {
            if (stage < 4 || unrestAmbienceCached < 2) return;
            if (getSetting("unrestFires") != 1) return;
            if (unrestFireIds.Count >= UNREST_FIRE_MAX) return;
            if (unrestLastFireTicks != 0 && nowMod - unrestLastFireTicks < UNREST_FIRE_GAP) return;

            try
            {
                GTA.Math.Vector3 pPos = Game.Player.Character.Position;
                double ang = random.NextDouble() * Math.PI * 2.0;
                float rad = UNREST_FIRE_MIN_DIST + 5f
                            + (float)random.NextDouble() * (UNREST_FIRE_MAX_DIST - UNREST_FIRE_MIN_DIST - 5f);
                GTA.Math.Vector3 want = new GTA.Math.Vector3(
                    pPos.X + (float)Math.Cos(ang) * rad,
                    pPos.Y + (float)Math.Sin(ang) * rad,
                    pPos.Z);
                GTA.Math.Vector3 spot = World.GetNextPositionOnStreet(want);
                if (spot == GTA.Math.Vector3.Zero) spot = want;
                float gz = World.GetGroundHeight(spot);
                if (gz > 0f) spot.Z = gz;

                // Re-check AFTER the street snap: the snap can pull the point toward us.
                float dist = spot.DistanceTo(pPos);
                if (dist < UNREST_FIRE_MIN_DIST)
                {
                    unrestLastFireTicks = nowMod;   // burn the slot, try again in 45 s
                    UnrestLog("unrest-fire: act=veto dist=" + ((int)dist) + " why=too-close");
                    return;
                }

                int fid = Function.Call<int>(Hash.START_SCRIPT_FIRE, spot.X, spot.Y, spot.Z, 8, false);
                unrestLastFireTicks = nowMod;
                if (fid == 0) { UnrestLog("unrest-fire: act=fail dist=" + ((int)dist)); return; }
                unrestFireIds.Add(fid);
                // iter-51: arson is the loudest escalation signal the model has.
                unrestHeatPending += UNREST_HEAT_PER_FIRE;
                unrestHeatFires++;
                UnrestLog("unrest-fire: act=start id=" + fid + " dist=" + ((int)dist));
                Speech.Critical("Fire, " + UnrestBearing(spot) + ".");
            }
            catch { }
        }

        // ===================================================================
        // iter-48: POLICE RESPONSE
        //
        // Level 1 is pure relationship work — no cop is recruited and no cop is
        // tasked, so "angry police" comes out of the same emergent mechanism the
        // rest of the feature uses. Levels 2 and 4 delegate to the game's own
        // dispatch system. Level 3 is the ONE place this feature commands a ped it
        // does not own, because "police stopping people" has no emergent form.
        // ===================================================================

        /// <summary>
        /// faction -> COP. Vanilla re_arrests.c does exactly this
        /// (SET_RELATIONSHIP_BETWEEN_GROUPS(4, crim, joaat("COP")) with no reverse
        /// edge), and one direction is enough for a rioter that attacks a cop to get
        /// a response through the normal AI path.
        ///
        /// iter-51: the REVERSE edge is now added too, but only at the top of the
        /// ladder. On 08-11 copsEngaged read 0 for the entire session — responders
        /// arrived and had nothing to do, because no cop was ever hostile to anyone
        /// and no rioter ever initiated. The original warning here is still true and
        /// is why this is fenced so tightly: COP -> faction makes every cop in the
        /// world treat riot-group members as shoot-on-sight. That is acceptable ONLY
        /// at stage 3+ with the police level explicitly at Dispatch or above, it is
        /// scoped to the three riot groups this mod created and to nothing else, and
        /// ClearUnrestCopRelationships tears both directions down.
        ///
        /// It deliberately does NOT touch the player: AssertUnrestPlayerSafety keeps
        /// faction <-> player at Respect in both directions, re-asserted every second.
        /// </summary>
        private void SetUnrestCopRelationship(int rel, bool reverse)
        {
            if (!unrestGroupsCreated || unrestCopGroupHash == 0) return;
            for (int i = 0; i < 3; i++)
            {
                Function.Call(Hash.SET_RELATIONSHIP_BETWEEN_GROUPS, rel,
                    unrestFactionHash[i], unrestCopGroupHash);
                if (reverse)
                    Function.Call(Hash.SET_RELATIONSHIP_BETWEEN_GROUPS, rel,
                        unrestCopGroupHash, unrestFactionHash[i]);
                else
                    // Leaving a stale reverse edge behind when the ladder steps back
                    // down would be the city-wide gunfight the comment above warns
                    // about, with nothing left to explain it.
                    Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, rel,
                        unrestCopGroupHash, unrestFactionHash[i]);
            }
            unrestCopRelApplied = rel;
            unrestCopRelReverse = reverse;
        }

        private void SetUnrestArmyRelationship(int rel)
        {
            if (!unrestGroupsCreated || unrestArmyGroupHash == 0) return;
            for (int i = 0; i < 3; i++)
                Function.Call(Hash.SET_RELATIONSHIP_BETWEEN_GROUPS, rel,
                    unrestFactionHash[i], unrestArmyGroupHash);
            unrestArmyRelApplied = rel;
        }

        private void ClearUnrestCopRelationships()
        {
            if (!unrestGroupsCreated) return;
            try
            {
                for (int i = 0; i < 3; i++)
                {
                    if (unrestCopGroupHash != 0)
                    {
                        Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 4,
                            unrestFactionHash[i], unrestCopGroupHash);
                        Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 5,
                            unrestFactionHash[i], unrestCopGroupHash);
                        // iter-51: both directions. The reverse edge is the one that
                        // must never survive a teardown.
                        Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 4,
                            unrestCopGroupHash, unrestFactionHash[i]);
                        Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 5,
                            unrestCopGroupHash, unrestFactionHash[i]);
                    }
                    if (unrestArmyGroupHash != 0)
                    {
                        Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 4,
                            unrestFactionHash[i], unrestArmyGroupHash);
                        Function.Call(Hash.CLEAR_RELATIONSHIP_BETWEEN_GROUPS, 5,
                            unrestFactionHash[i], unrestArmyGroupHash);
                    }
                }
            }
            catch { }
            unrestCopRelApplied = 0;
            unrestCopRelReverse = false;
            unrestArmyRelApplied = 0;
        }

        private void ClearUnrestIncident()
        {
            if (unrestIncidentId == 0) return;
            try
            {
                if (Function.Call<bool>(Hash.IS_INCIDENT_VALID, unrestIncidentId))
                    Function.Call(Hash.DELETE_INCIDENT, unrestIncidentId);
                UnrestLog("unrest-police: act=incident-delete id=" + unrestIncidentId);
            }
            catch { }
            unrestIncidentId = 0;
            unrestIncidentTicks = 0;
            unrestIncidentAnchor = GTA.Math.Vector3.Zero;
        }

        private void RestoreUnrestDispatch()
        {
            if (!unrestDispatchForced) return;
            try
            {
                // true IS the vanilla default for every service, so this is idempotent
                // and safe to run even if we never actually forced them.
                Function.Call(Hash.ENABLE_DISPATCH_SERVICE, UNREST_DISPATCH_SWAT, true);
                Function.Call(Hash.ENABLE_DISPATCH_SERVICE, UNREST_DISPATCH_ARMY, true);
            }
            catch { }
            unrestDispatchForced = false;
        }

        /// <summary>
        /// iter-51: the anchor a dispatch incident is created at, and the reason the
        /// police stopped going in circles.
        ///
        /// This used to roll a fresh random bearing on EVERY create. Combined with a
        /// fixed 60 s delete-and-recreate, that meant responders drove toward a point,
        /// and the moment they were close the incident was deleted and a new one
        /// appeared somewhere else 30-50 m away. The 08-11 log is ten cycles of
        /// exactly that (dist=36,40,45,30,36,39,38,31,41,34) — units circling a block
        /// forever, which is precisely what the player reported hearing.
        ///
        /// Now the anchor is the RIOT's centroid, computed once and reused. Responders
        /// converge on where the riot actually is, and stay there. It still resolves
        /// to a point 30-50 m off the player when the roster is empty, because sirens
        /// converging onto the player is both unsafe and a worse spatial cue.
        /// </summary>
        private GTA.Math.Vector3 UnrestIncidentAnchor()
        {
            GTA.Math.Vector3 pPos = Game.Player.Character.Position;
            int n = 0;
            float sx = 0f, sy = 0f, sz = 0f;
            for (int i = 0; i < unrestPeds.Count; i++)
            {
                RiotPed rec = unrestPeds[i];
                if (rec.ped == null || !rec.ped.Exists() || rec.ped.IsDead) continue;
                GTA.Math.Vector3 q = rec.ped.Position;
                sx += q.X; sy += q.Y; sz += q.Z; n++;
            }
            if (n > 0)
            {
                GTA.Math.Vector3 c = new GTA.Math.Vector3(sx / n, sy / n, sz / n);
                // A centroid that lands on top of the player is the one case where
                // the old offset behaviour was right — push it out so responders do
                // not drive at them.
                if (c.DistanceTo(pPos) >= UNREST_ANCHOR_MIN_OFFSET) return c;
            }
            double ang = random.NextDouble() * Math.PI * 2.0;
            float rad = 30f + (float)random.NextDouble() * 20f;
            return new GTA.Math.Vector3(
                pPos.X + (float)Math.Cos(ang) * rad,
                pPos.Y + (float)Math.Sin(ang) * rad,
                pPos.Z);
        }

        private void CreateUnrestIncident(int service, int units, long nowMod)
        {
            try
            {
                GTA.Math.Vector3 pPos = Game.Player.Character.Position;
                GTA.Math.Vector3 at = UnrestIncidentAnchor();
                float rad = at.DistanceTo(pPos);
                OutputArgument outId = new OutputArgument();
                bool ok = Function.Call<bool>(Hash.CREATE_INCIDENT,
                    service, at.X, at.Y, at.Z, units, 3f, outId, 0, 0);
                int id = ok ? outId.GetResult<int>() : 0;
                if (ok && id != 0)
                {
                    unrestIncidentId = id;
                    unrestIncidentTicks = nowMod;
                    unrestIncidentAnchor = at;
                    // iter-51: police arriving is escalation the heat model could
                    // not previously see.
                    unrestHeatPending += UNREST_HEAT_PER_DISPATCH;
                    unrestHeatDispatches++;
                }
                // iter-51: stage and level on the line. Without them the all-service=7
                // result on 08-11 could not be checked against the SWAT/army roll that
                // is supposed to happen at level 4 / stage 4.
                UnrestLog("unrest-police: act=incident-create service=" + service
                    + " units=" + units + " id=" + id + " ok=" + (ok ? 1 : 0)
                    + " dist=" + ((int)rad)
                    + " stage=" + unrestStage
                    + " level=" + unrestPoliceCached
                    + " anchor=" + (unrestPeds.Count > 0 ? "centroid" : "offset")
                    + " roster=" + unrestPeds.Count);
                if (ok && unrestNarrationCached >= 1)
                {
                    string line = service == UNREST_DISPATCH_SWAT || service == UNREST_DISPATCH_ARMY
                        ? "Heavy police units are moving in."
                        : "Police are being called in.";
                    if (unrestNarrationCached >= 2) line += " " + UnrestBearing(at) + ".";
                    UnrestSpeak("dispatch", line, SpeechPriority.Informational, UNREST_INCIDENT_REFRESH);
                }
            }
            catch { }
        }

        private void ResolveCopStop(string why)
        {
            CopStop s = unrestCopStop;
            unrestCopStop = null;
            if (s == null) return;
            try
            {
                Ped c = s.cop;
                if (c != null && c.Exists() && c.Handle == s.copHandle)
                {
                    if (s.setKeepTask) Function.Call(Hash.SET_PED_KEEP_TASK, c, false);
                    // false is the ambient default for DontInfluenceWantedLevel; leaving
                    // it set would silently exempt this cop from the wanted system for
                    // the rest of its life.
                    Function.Call(Hash.SET_PED_CONFIG_FLAG, c, 42, false);
                    if (s.copOrigAccuracy >= 0)
                        Function.Call(Hash.SET_PED_ACCURACY, c, s.copOrigAccuracy);
                    if (s.gaveStunGun)
                    {
                        try { c.Weapons.Remove(WeaponHash.StunGun); } catch { }
                    }
                    Function.Call(Hash.CLEAR_PED_TASKS, c);
                    c.MarkAsNoLongerNeeded();
                }
            }
            catch { }
            UnrestLog("unrest-copstop: act=resolve outcome="
                + (s.outcome == 0 ? "arrest" : (s.outcome == 1 ? "taze" : "shoot"))
                + " cop=" + s.copHandle + " target=" + s.targetHandle + " why=" + why);
        }

        /// <summary>
        /// Police response tick. One allocating ped scan every 2 s, which also feeds
        /// the "cops are shooting near you" warning — that line fires at ANY narration
        /// verbosity, because gunfire a blind player cannot locate is the single most
        /// dangerous thing this feature can produce.
        /// </summary>
        private void TickUnrestPolice(long nowWall, long nowMod, int stage)
        {
            int level = unrestPoliceCached;

            // ---- hostility, with the wanted-level interlock ----
            // ReleaseUnrestCops only covers cops in the ROSTER; level 1 recruits none,
            // so without this branch a player at 2 stars would be standing inside a
            // rioter-versus-police firefight with cops that are chasing them.
            bool wanted = Game.Player.WantedLevel > 0;
            if (wanted)
            {
                if (unrestCopRelApplied != 0 || unrestArmyRelApplied != 0)
                {
                    ClearUnrestCopRelationships();
                    if (unrestCopStop != null) ResolveCopStop("wanted");
                    UnrestLog("unrest-police: act=hostile-off why=wanted wanted="
                        + Game.Player.WantedLevel);
                    if (unrestNarrationCached >= 1)
                        UnrestSpeak("cop-hostility", "The crowd has backed off the police.",
                            SpeechPriority.Informational, 150000000L);
                }
            }
            else if (level >= 1 && stage >= 2)
            {
                int want = stage >= 3 ? 5 : 4;      // Hate : Dislike
                // iter-51: the reverse (COP -> faction) edge, gated harder than the
                // forward one. Stage 3+ AND police at Dispatch or above — i.e. the
                // player has explicitly asked for police involvement and the riot has
                // escalated past a crowd. Below that the old one-way behaviour is
                // unchanged. This is what makes copsEngaged able to leave 0.
                bool wantReverse = stage >= 3 && level >= 2;
                if (unrestCopRelApplied != want || unrestCopRelReverse != wantReverse)
                {
                    SetUnrestCopRelationship(want, wantReverse);
                    UnrestLog("unrest-police: act=hostile-on rel=" + want
                        + " reverse=" + (wantReverse ? 1 : 0)
                        + " stage=" + stage + " level=" + level);
                    if (unrestNarrationCached >= 1)
                        UnrestSpeak("cop-hostility", "The crowd is going after the police again.",
                            SpeechPriority.Informational, 150000000L);
                    // A blind player has no way to see that the police have just
                    // become willing to open fire on the crowd around them. Say it.
                    if (wantReverse)
                        UnrestSpeak("cop-hostile-both",
                            "Police are now treating the crowd as hostile. Expect gunfire.",
                            SpeechPriority.Critical, 300000000L);
                }
                if (level >= 4 && stage >= 4 && unrestArmyRelApplied != 5)
                    SetUnrestArmyRelationship(5);
            }

            // Gate turned off mid-riot: undo everything level 1-4 owns right now
            // rather than waiting for StopCivilUnrest. An orphaned Hate toward the
            // police is a city-wide gunfight the player never asked for.
            if (level <= 0 || stage < 2)
            {
                if (unrestCopRelApplied != 0 || unrestArmyRelApplied != 0)
                {
                    ClearUnrestCopRelationships();
                    UnrestLog("unrest-police: act=hostile-off why=gate-off");
                }
                if (unrestCopStop != null) ResolveCopStop("gate-off");
                ClearUnrestIncident();
                RestoreUnrestDispatch();
                return;
            }
            // Partial gate-down: each level's own state is released as it is left.
            // RestoreUnrestDispatch no-ops unless we actually forced the services.
            if (level < 2) ClearUnrestIncident();
            if (level < 4) RestoreUnrestDispatch();
            if (level < 3 && unrestCopStop != null) ResolveCopStop("gate-off");

            // ---- dispatch incidents (level >= 2, stage >= 3) ----
            if (level >= 2 && stage >= 3 && !wanted)
            {
                // iter-51: the 60 s timer is GONE from this condition.
                //
                // An incident is now recreated for exactly two reasons: there is no
                // incident, or the engine dropped the one we had. A live incident
                // whose responders are still en route is left alone — the old fixed
                // refresh was tearing down a working dispatch every minute and
                // sending the units somewhere new, which is the "going in circles"
                // the player heard. The third trigger is a riot that has genuinely
                // MOVED: if the crowd's centroid has drifted more than
                // UNREST_ANCHOR_MOVE_M from where the incident was placed, the
                // incident is now pointing at an empty street and re-anchoring is
                // the correct response rather than churn.
                bool moved = unrestIncidentId != 0
                             && UnrestIncidentAnchor().DistanceTo(unrestIncidentAnchor) > UNREST_ANCHOR_MOVE_M;
                bool stale = unrestIncidentId == 0
                             || moved
                             || !Function.Call<bool>(Hash.IS_INCIDENT_VALID, unrestIncidentId);
                if (stale)
                {
                    if (moved) UnrestLog("unrest-police: act=incident-reanchor id=" + unrestIncidentId);
                    ClearUnrestIncident();
                    int service = UNREST_DISPATCH_POLICE;
                    int units = 2;
                    if (level >= 4 && stage >= 4)
                    {
                        // SWAT and army are normally gated to high wanted levels, so the
                        // service has to be re-enabled first. Whether CREATE_INCIDENT
                        // then actually spawns anything at zero stars is UNVERIFIED —
                        // that is what the ok= field in the log is for.
                        if (!unrestDispatchForced)
                        {
                            Function.Call(Hash.ENABLE_DISPATCH_SERVICE, UNREST_DISPATCH_SWAT, true);
                            Function.Call(Hash.ENABLE_DISPATCH_SERVICE, UNREST_DISPATCH_ARMY, true);
                            unrestDispatchForced = true;
                        }
                        int roll = random.Next(3);
                        service = roll == 0 ? UNREST_DISPATCH_SWAT
                                : (roll == 1 ? UNREST_DISPATCH_ARMY : UNREST_DISPATCH_POLICE);
                    }
                    else if (stage >= 4 && random.Next(2) == 0)
                    {
                        service = UNREST_DISPATCH_AMBULANCE;   // riot casualties draw EMS
                    }
                    CreateUnrestIncident(service, units, nowMod);
                }
            }

            // ---- resolve an in-flight street stop ----
            if (unrestCopStop != null)
            {
                CopStop s = unrestCopStop;
                bool dead = s.cop == null || !s.cop.Exists() || s.cop.Handle != s.copHandle
                            || s.cop.IsDead
                            || s.target == null || !s.target.Exists()
                            || s.target.Handle != s.targetHandle || s.target.IsDead;
                if (dead) ResolveCopStop("ended");
                else if (nowMod - s.startTicks > UNREST_COPSTOP_TTL) ResolveCopStop("ttl");
                // iter-51: was a bare `return`, which skipped the scan below — and
                // the scan is the ONLY thing that assigns unrestStatCopsEngaged. A
                // street stop therefore froze copsEngaged at whatever it happened to
                // be, for as long as the stop lasted, which is exactly the window in
                // which police involvement is most worth reporting. Fall through to
                // the scan; the wantStop flag below already prevents a second stop.
            }

            // ---- periodic cop scan: firefight warning + street-stop candidate ----
            // iter-51: `unrestCopStop != null` is now part of this flag rather than
            // an early return above, so the firefight warning and copsEngaged keep
            // updating while a stop is in flight.
            bool wantStop = level >= 3 && !wanted && unrestCopStop == null
                            && nowMod - unrestLastCopStopTicks >= UNREST_COPSTOP_GAP;
            if (nowWall - unrestPoliceScanTicks < UNREST_POLICE_SCAN_INTERVAL_TICKS) return;
            unrestPoliceScanTicks = nowWall;

            Ped player = Game.Player.Character;
            if (player == null || !player.Exists()) return;
            GTA.Math.Vector3 pPos = player.Position;

            Ped bestCop = null;
            float bestCopDist = 9999f;
            int copsFighting = 0;
            Ped nearestFightingCop = null;
            float nearestFightingDist = 9999f;

            Ped[] near;
            try { near = World.GetNearbyPeds(pPos, UNREST_COPSTOP_COP_RADIUS); }
            catch { return; }

            foreach (Ped c in near)
            {
                if (c == null || !c.Exists() || c.IsDead) continue;
                if (c.Handle == player.Handle) continue;
                if (unrestHandles.Contains(c.Handle)) continue;
                int pt = Function.Call<int>(Hash.GET_PED_TYPE, c);
                if (!IsUnrestCopType(pt)) continue;
                float cd = c.Position.DistanceTo(pPos);

                if (c.IsInCombat)
                {
                    copsFighting++;
                    if (cd < nearestFightingDist) { nearestFightingDist = cd; nearestFightingCop = c; }
                    continue;   // a cop already fighting is not a street-stop candidate
                }
                if (!wantStop) continue;
                if (c.IsPersistent) continue;
                if (c.IsInCombatAgainst(player)) continue;
                if (cd < UNREST_COPSTOP_MIN_PLAYER_DIST) continue;
                // iter-51: a dispatched responder ARRIVES IN A CAR, so rejecting
                // every in-vehicle cop rejected every cop the dispatch system had
                // just sent — which is why zero street stops happened on 08-11
                // despite police being set to its highest level for the whole riot.
                // Ask a slow/stopped one to get out and pick it up on the next scan
                // (2 s later) through the normal on-foot path. Never yanks a cop out
                // of a moving car: that is a crash the player cannot see coming.
                if (c.IsInVehicle())
                {
                    try
                    {
                        Vehicle cv = c.CurrentVehicle;
                        if (cv != null && cv.Exists() && cv.Speed < 1.5f)
                        {
                            Function.Call(Hash.TASK_LEAVE_VEHICLE, c, cv, 0);
                            UnrestLog("unrest-copstop: act=deboard cop=" + c.Handle
                                + " veh=" + cv.Handle + " dist=" + ((int)cd));
                        }
                    }
                    catch { }
                    continue;
                }
                if (cd < bestCopDist) { bestCopDist = cd; bestCop = c; }
            }

            unrestStatCopsEngaged = copsFighting;
            if (nearestFightingCop != null && nearestFightingDist < 50f)
            {
                UnrestLog("unrest-firefight: cops=" + copsFighting
                    + " dist=" + ((int)nearestFightingDist)
                    + " wanted=" + Game.Player.WantedLevel);
                // Ungated by verbosity, exactly like "Someone near you has a gun".
                UnrestSpeak("cop-firefight",
                    "Police are shooting, " + UnrestBearing(nearestFightingCop.Position) + ".",
                    SpeechPriority.Critical, 100000000L);
            }

            if (bestCop == null) return;
            TryStartCopStop(bestCop, nowMod, stage);
        }

        /// <summary>
        /// The one authorised exception to the no-orders rule inside the police
        /// feature. Rolls the outcome up front, weighted by stage: at stage 2 this is
        /// lawful policing, by stage 4 the police are mostly beating and shooting
        /// people. The target is always a ROSTER rioter, which is Respect toward the
        /// player by construction, so a stop can never be aimed at the player.
        /// </summary>
        private void TryStartCopStop(Ped cop, long nowMod, int stage)
        {
            RiotPed targetRec = null;
            float bestDist = UNREST_COPSTOP_TARGET_RADIUS;
            GTA.Math.Vector3 cPos = cop.Position;
            for (int i = 0; i < unrestPeds.Count; i++)
            {
                RiotPed rec = unrestPeds[i];
                Ped t = rec.ped;
                if (t == null || !t.Exists() || t.IsDead || t.Handle != rec.handle) continue;
                if (t.IsInVehicle()) continue;
                float d = t.Position.DistanceTo(cPos);
                if (d < bestDist) { bestDist = d; targetRec = rec; }
            }
            if (targetRec == null) return;

            unrestLastCopStopTicks = nowMod;
            Ped target = targetRec.ped;

            int roll = random.Next(100);
            int outcome = roll < UNREST_COPSTOP_ARREST_PCT[stage] ? 0
                        : (roll < UNREST_COPSTOP_TAZE_PCT[stage] ? 1 : 2);

            CopStop s = new CopStop();
            s.cop = cop;
            s.target = target;
            s.copHandle = cop.Handle;
            s.targetHandle = target.Handle;
            s.startTicks = nowMod;
            s.outcome = outcome;

            try
            {
                // An ambient cop drops a scripted task almost immediately without this.
                Function.Call(Hash.SET_PED_KEEP_TASK, cop, true);
                s.setKeepTask = true;
                Function.Call(Hash.SET_PED_CONFIG_FLAG, cop, 42, true);  // DontInfluenceWantedLevel

                if (outcome == 0)
                {
                    Function.Call(Hash.TASK_ARREST_PED, cop, target);
                    if (unrestNarrationCached >= 1)
                        UnrestSpeak("copstop", "Police are stopping someone, "
                            + UnrestBearing(cPos) + ".",
                            SpeechPriority.Informational, UNREST_COPSTOP_GAP);
                }
                else if (outcome == 1)
                {
                    if (!cop.Weapons.HasWeapon(WeaponHash.StunGun))
                    {
                        cop.Weapons.Give(WeaponHash.StunGun, 20, true, true);
                        s.gaveStunGun = true;
                    }
                    Function.Call(Hash.SET_CURRENT_PED_WEAPON, cop, (uint)WeaponHash.StunGun, true);
                    Function.Call(Hash.TASK_SHOOT_AT_ENTITY, cop, target, 2500,
                        Game.GenerateHash("FIRING_PATTERN_SINGLE_SHOT"));
                    if (unrestNarrationCached >= 1)
                        UnrestSpeak("copstop", "Police are tasing someone, "
                            + UnrestBearing(cPos) + ".",
                            SpeechPriority.Informational, UNREST_COPSTOP_GAP);
                }
                else
                {
                    // Force the pistol: a cop that spawned with a Carbine Rifle would
                    // otherwise spray automatic fire down a street the player cannot see.
                    try { s.copOrigAccuracy = Function.Call<int>(Hash.GET_PED_ACCURACY, cop); }
                    catch { s.copOrigAccuracy = -1; }
                    if (!cop.Weapons.HasWeapon(WeaponHash.Pistol))
                        cop.Weapons.Give(WeaponHash.Pistol, 30, true, true);
                    Function.Call(Hash.SET_CURRENT_PED_WEAPON, cop, (uint)WeaponHash.Pistol, true);
                    Function.Call(Hash.SET_PED_ACCURACY, cop, 40);
                    Function.Call(Hash.TASK_SHOOT_AT_ENTITY, cop, target, 3000,
                        Game.GenerateHash("FIRING_PATTERN_BURST_FIRE_PISTOL"));
                    // Gunfire near a blind player is ALWAYS announced.
                    UnrestSpeak("copstop-shoot", "Police are shooting someone, "
                        + UnrestBearing(cPos) + ".",
                        SpeechPriority.Critical, UNREST_COPSTOP_GAP);
                }
            }
            catch { }

            unrestCopStop = s;
            unrestCopStopCount++;
            UnrestLog("unrest-copstop: act=start outcome="
                + (outcome == 0 ? "arrest" : (outcome == 1 ? "taze" : "shoot"))
                + " cop=" + s.copHandle + " target=" + s.targetHandle
                + " dist=" + ((int)bestDist) + " stage=" + stage
                + " wanted=" + Game.Player.WantedLevel);
        }

        /// <summary>
        /// iter-51: how fast the stage ladder runs. Multiplies ELAPSED time, so a
        /// scale above 1 reaches each boundary sooner:
        ///   0 Relaxed  x0.67  ->  0:00 / 1:30 / 4:30 / 9:00 / 15:00
        ///   1 Normal   x1.00  ->  the original 0:00 / 1:00 / 3:00 / 6:00 / 10:00
        ///   2 Fast     x2.50  ->  0:00 / 0:24 / 1:12 / 2:24 / 4:00
        ///
        /// Applied to elapsed rather than to UNREST_STAGE_AT so the ladder constants
        /// stay the single documented source of the boundaries, and so changing the
        /// setting mid-riot re-evaluates immediately without rebuilding a table.
        /// The stage latch upstream is monotonic, so a mid-riot slow-down can never
        /// walk a stage back.
        /// </summary>
        private float UnrestPaceScale()
        {
            switch (getSetting("unrestPace"))
            {
                case 0: return 0.67f;
                case 2: return 2.5f;
                default: return 1f;
            }
        }

        private void ReleaseUnrestCops()
        {
            int released = 0;
            for (int i = unrestPeds.Count - 1; i >= 0; i--)
            {
                if (!IsUnrestCopType(unrestPeds[i].pedType)) continue;
                RestoreUnrestPed(unrestPeds[i]);
                unrestHandles.Remove(unrestPeds[i].handle);
                unrestPeds.RemoveAt(i);
                released++;
            }
            if (released > 0)
            {
                UnrestLog("unrest-cop-release: n=" + released);
                Speech.Info("Police are responding to you. They have left the riot.");
            }
        }

        private void UnrestSitRep(long nowWall)
        {
            int verbosity = getSetting("unrestNarration");
            if (verbosity <= 0) return;

            long cadence = verbosity >= 2 ? 120000000L : 200000000L;   // 12 s / 20 s
            // Nav-assist owns the audio channel while the player is driving.
            try
            {
                Ped pc = Game.Player.Character;
                if (pc != null && pc.IsInVehicle() && pc.CurrentVehicle != null
                    && pc.CurrentVehicle.Speed > 5f && getSetting("steeringAssist") > 0)
                    cadence = 300000000L;   // 30 s
            }
            catch { }
            if (cadence < UNREST_SITREP_FLOOR_TICKS) cadence = UNREST_SITREP_FLOOR_TICKS;
            if (nowWall - unrestLastSitRepTicks < cadence) return;
            // Never talk over whatever just spoke.
            if (nowWall - Speech.LastEmittedWallTicks < UNREST_SPEECH_QUIET_TICKS) return;

            int bucket = unrestStatNearestDist < 10f ? 0
                : (unrestStatNearestDist < 25f ? 1 : (unrestStatNearestDist < 50f ? 2 : 3));
            // iter-48: two more dimensions in the change tuple so a state FLIP is
            // reportable, without loosening the "don't loop the identical line" rule.
            bool copsNow = unrestStatCopsEngaged > 0;
            bool trafficNow = unrestTrafficArmed;
            // Change-only: otherwise this loops the identical line forever.
            if (unrestLastRepFighting >= 0
                && Math.Abs(unrestStatFighting - unrestLastRepFighting) < 2
                && unrestCasualties == unrestLastRepDown
                && bucket == unrestLastRepBucket
                && copsNow == unrestLastRepCops
                && trafficNow == unrestLastRepTraffic) return;

            unrestLastSitRepTicks = nowWall;
            unrestLastRepFighting = unrestStatFighting;
            unrestLastRepDown = unrestCasualties;
            unrestLastRepBucket = bucket;
            unrestLastRepCops = copsNow;
            unrestLastRepTraffic = trafficNow;

            string msg = "Riot: " + unrestStatFighting + " fighting, " + unrestCasualties + " down";
            if (verbosity >= 2) msg += ", " + unrestStatArmed + " armed";
            if (verbosity >= 2 && copsNow) msg += ", police engaged";
            if (verbosity >= 2 && trafficNow) msg += ", traffic hostile";
            msg += ".";
            bool driving = false;
            try
            {
                Ped pc = Game.Player.Character;
                driving = pc != null && pc.IsInVehicle() && pc.CurrentVehicle != null
                          && pc.CurrentVehicle.Speed > 5f;
            }
            catch { }
            if (!driving && unrestStatNearestDist < 9000f)
                msg += " Nearest fight " + (int)unrestStatNearestDist + " meters " + unrestStatNearestDir + ".";

            if (unrestStatNearestDist < 10f) Speech.Info(msg);
            else Speech.Ambient(msg);
        }

        private void TickCivilUnrest()
        {
            if (!unrestOrphanSweepDone && !Game.IsLoading && !unrestActive)
                SweepOrphanedUnrestGroups();
            if (!unrestActive || Game.IsLoading) return;

            long nowWall = DateTime.Now.Ticks;
            if (nowWall - unrestTickTicks < UNREST_TICK_INTERVAL_TICKS) return;
            unrestTickTicks = nowWall;

            long nowMod = ModClock.Ticks;
            Ped player = Game.Player.Character;
            if (player == null || !player.Exists()) return;

            // ---- per-tick setting cache ----
            // getSetting is an O(n) scan; every slice below reads these instead.
            unrestBrutalityCached = getSetting("unrestBrutality");
            unrestAmbienceCached = getSetting("unrestAmbience");
            unrestTrafficCached = getSetting("unrestTraffic");
            unrestPoliceCached = getSetting("unrestPolice");
            unrestNarrationCached = getSetting("unrestNarration");
            bool dynamicEscalation = getSetting("unrestEscalation") == 1;

            // ---- heat ----
            // Computed and logged ALWAYS; consumed only when unrestEscalation == 1.
            // Dark-launched on purpose: one session proves the signal is sane before
            // it is allowed to move a stage boundary.
            float dtSec = (float)((nowMod - unrestHeatTicks) / 10000000.0);
            if (dtSec < 0f) dtSec = 0f;
            unrestHeatTicks = nowMod;
            int newCasualties = unrestCasualties - unrestHeatCasualtiesSeen;
            if (newCasualties > 0)
            {
                unrestHeat += UNREST_HEAT_PER_CASUALTY * newCasualties;
                unrestHeatCasualtiesSeen = unrestCasualties;
                if (!unrestFirstCasualtyAnnounced && unrestNarrationCached >= 1)
                {
                    unrestFirstCasualtyAnnounced = true;
                    UnrestSpeak("first-casualty", "Someone just went down.",
                        SpeechPriority.Informational, 0L);
                }
            }
            if (unrestStatCombatEntries > 0)
            {
                unrestHeat += UNREST_HEAT_PER_ENGAGEMENT * unrestStatCombatEntries;
                unrestHeatEngagements += unrestStatCombatEntries;
                unrestStatCombatEntries = 0;
            }
            bool shootingNow = false;
            try { shootingNow = Function.Call<bool>(Hash.IS_PED_SHOOTING, player); }
            catch { }
            if (shootingNow && !unrestPlayerWasShooting)
            {
                unrestHeat += UNREST_HEAT_PER_PLAYER_SHOT;
                unrestHeatPlayerShots++;
            }
            unrestPlayerWasShooting = shootingNow;
            // iter-51: fires, alarms and dispatches, banked by their own event sites.
            if (unrestHeatPending > 0f)
            {
                unrestHeat += unrestHeatPending;
                unrestHeatPending = 0f;
            }
            unrestHeat -= UNREST_HEAT_DECAY_PER_SEC * dtSec;
            if (unrestHeat < 0f) unrestHeat = 0f;
            else if (unrestHeat > 100f) unrestHeat = 100f;
            unrestHeatStage = unrestHeat >= UNREST_HEAT_STAGE2 ? 2
                            : (unrestHeat >= UNREST_HEAT_STAGE1 ? 1 : 0);

            // ---- stage advance ----
            // iter-51: unrestPace scales the ladder.
            //
            // The ladder is 0:00 / 1:00 / 3:00 / 6:00 / 10:00 and NOTHING could
            // change it: unrestEscalation is purely additive (heat stage is ADDED to
            // the time stage), so even Dynamic could not make the clock run faster,
            // and with heat unreachable it never added anything either. Ten minutes
            // to a citywide riot with nothing visibly happening is exactly the "took
            // a while for anything at all to happen" the player reported.
            long elapsed = (long)((nowMod - unrestStartTicks) * UnrestPaceScale());
            int timeStage = 0;
            for (int i = UNREST_STAGE_AT.Length - 1; i >= 0; i--)
                if (elapsed >= UNREST_STAGE_AT[i]) { timeStage = i; break; }
            unrestTimeStage = timeStage;

            int want = timeStage + (dynamicEscalation ? unrestHeatStage : 0);
            if (want > UNREST_STAGE_MAX) want = UNREST_STAGE_MAX;
            bool byHeat = want > timeStage;
            if (byHeat && nowMod - unrestHeatAdvanceTicks < UNREST_HEAT_ADVANCE_GAP)
            {
                want = timeStage;
                byHeat = false;
            }
            if (byHeat) unrestHeatAdvanceTicks = nowMod;
            // MONOTONIC BY CONSTRUCTION: heat only ever accelerates. A blind player
            // who has been told "full riot" must never then be told it calmed down
            // while people are still fighting a few metres away.
            int stage = want < unrestAchievedStage ? unrestAchievedStage : want;
            unrestAchievedStage = stage;

            if (stage != unrestStage)
            {
                unrestStage = stage;
                // Group-level, so 6 directed calls once per boundary — not per tick.
                SetUnrestInterFactionRelationship(stage >= 2 ? 5 : 4);   // Hate : Dislike
                AssertUnrestPlayerSafety();
                // Force every recruit to be re-profiled, drained by budget below so
                // a stage transition never hitches the frame.
                for (int i = 0; i < unrestPeds.Count; i++) unrestPeds[i].profiledStage = -1;
                unrestProfileCursor = 0;
                UnrestLog("unrest-stage: stage=" + stage + " peds=" + unrestPeds.Count
                    + " why=" + (byHeat ? "heat" : "time")
                    + " timeStage=" + timeStage + " heat=" + ((int)unrestHeat));
                if (byHeat && unrestNarrationCached >= 2)
                    UnrestSpeak("heat-accel", "This is escalating fast.",
                        SpeechPriority.Informational, 300000000L);
                if (stage != unrestAnnouncedStage)
                {
                    unrestAnnouncedStage = stage;
                    switch (stage)
                    {
                        case 0: Speech.Info("Civil unrest starting. Tension is building around you."); break;
                        case 1: Speech.Info("The crowd is turning. Arguments breaking out nearby."); break;
                        case 2: Speech.Info("Fighting has broken out. Riot in progress."); break;
                        case 3: Speech.Info("Full riot. It is dangerous here."); break;
                        default: Speech.Info("Citywide riot. The police are losing control."); break;
                    }
                }
            }

            // ---- player safety re-assert (>=1 s, or immediately on group change) ----
            int pgNow = Function.Call<int>(Hash.GET_PED_RELATIONSHIP_GROUP_HASH, player);
            if (pgNow != unrestPlayerGroupCached || nowMod - unrestRelAssertTicks > 10000000L)
                AssertUnrestPlayerSafety();

            // ---- cop interlock ----
            if (Game.Player.WantedLevel > 0) ReleaseUnrestCops();

            // ---- traffic level, after the nav-assist clamp ----
            // Level 2 clears steers-around-peds, and the on-foot time-to-collision
            // alert is the ONLY warning a blind pedestrian gets that a car is coming.
            // Without it, refuse and say so rather than silently doing something
            // lethal.
            int trafficLvl = unrestTrafficCached;
            bool trafficClamped = false;
            if (trafficLvl >= 2)
            {
                bool navOk = getSetting("navigationAssist") == 1
                             && getSetting("navAssistVerbosity") != 0;
                if (!navOk)
                {
                    trafficLvl = 1;
                    trafficClamped = true;
                    UnrestSpeak("traffic-clamp",
                        "Reckless traffic needs Navigation Assist turned on.",
                        SpeechPriority.Informational, 0L);
                }
            }
            if (trafficLvl != unrestTrafficEffective
                || nowWall - unrestLastTrafficLogTicks > 100000000L)
            {
                // Only once traffic can actually be armed — the roster does not touch a
                // driver below stage 2, so saying it earlier would be a lie.
                if (trafficLvl >= 1 && stage >= 2 && unrestNarrationCached >= 1)
                    UnrestSpeak("traffic-on",
                        "Traffic is getting dangerous. Cars are not stopping.",
                        SpeechPriority.Informational, 0L);
                unrestLastTrafficLogTicks = nowWall;
                UnrestLog("unrest-traffic: level=" + unrestTrafficCached
                    + " effective=" + trafficLvl + " stage=" + stage
                    + " drivers=" + unrestDrivers.Count
                    + " clamped=" + (trafficClamped ? 1 : 0));
            }
            unrestTrafficEffective = trafficLvl;

            // ---- per-frame density cache (see TickCivilUnrestFrame) ----
            bool wantFrame = unrestAmbienceCached >= 1 && stage >= 2;
            float newPedDensity = wantFrame ? UNREST_PED_DENSITY[stage] : 1f;
            float newVehDensity = wantFrame && trafficLvl >= 1 ? UNREST_VEH_DENSITY[stage] : 1f;
            // iter-51: NEVER zero scenario peds again.
            //
            // This used to be `wantFrame && stage >= 3`, which starved the recruiter
            // of the exact population it recruits from, at the exact moment the riot
            // was supposed to be escalating. SET_SCENARIO_PED_DENSITY_MULTIPLIER
            // suppresses standing/sitting/leaning ambient peds — the ones who are
            // on foot and stationary, i.e. every easy recruit. The 08-11 log tracks
            // it one-for-one: scenario=1 at stage 2 -> roster 3; scenario=0 at
            // stage 3 -> roster 1; stage 4 -> roster 0.
            //
            // The original intent (idle sunbathers look wrong mid-riot) is now
            // served properly by the scenario-EXIT pass below, which takes those
            // peds out of their scenario and into the crowd instead of preventing
            // them from existing. Kept as a field rather than deleted so the
            // per-frame writer and the density event keep one shape.
            bool newScenarioZero = false;
            if (wantFrame != unrestFrameActive
                || Math.Abs(newPedDensity - unrestFramePedDensity) > 0.001f
                || Math.Abs(newVehDensity - unrestFrameVehDensity) > 0.001f
                || newScenarioZero != unrestFrameScenarioZero)
            {
                UnrestLog("unrest-density: ped=" + newPedDensity.ToString("F2")
                    + " veh=" + newVehDensity.ToString("F2")
                    + " scenario=" + (newScenarioZero ? "0" : "1") + " stage=" + stage);
            }
            unrestFrameActive = wantFrame;
            unrestFramePedDensity = newPedDensity;
            unrestFrameVehDensity = newVehDensity;
            unrestFrameScenarioZero = newScenarioZero;

            // ---- traffic, ambience-vehicles, police, fires ----
            // These run BEFORE the roster-empty early return: aggressive traffic and
            // dispatch do not need a single recruit to be meaningful, and the police
            // hostility teardown must keep running even when the roster empties out.
            TickUnrestVehicleScan(nowWall, nowMod, stage);
            TickUnrestDrivers(nowMod, stage);
            TickUnrestPolice(nowWall, nowMod, stage);
            TickUnrestFires(nowMod, stage);

            // ---- scan refresh (allocating; strictly rate-limited) ----
            if (nowWall - unrestScanTicks > UNREST_SCAN_INTERVAL_TICKS && unrestPeds.Count < UNREST_MAX_PEDS)
            {
                unrestScanTicks = nowWall;
                try { unrestScanBuf = World.GetNearbyPeds(player.Position, UNREST_STAGE_RADIUS[stage]); }
                catch { unrestScanBuf = null; }
                unrestScanCursor = 0;
                // iter-51: the denominator of the whole recruit census. Without it
                // an empty roster is unattributable.
                urScanReturned += unrestScanBuf != null ? unrestScanBuf.Length : 0;
            }

            // ---- recruit, budgeted ----
            if (unrestScanBuf != null)
            {
                int done = 0;
                while (unrestScanCursor < unrestScanBuf.Length
                       && done < UNREST_RECRUIT_BUDGET
                       && unrestPeds.Count < UNREST_MAX_PEDS)
                {
                    Ped cand = unrestScanBuf[unrestScanCursor++];
                    done++;
                    // The buffer is up to 1.5 s stale and handles get reused.
                    if (cand == null || !cand.Exists() || cand.IsDead) { urRejDead++; continue; }
                    if (unrestHandles.Contains(cand.Handle)) { urRejDup++; continue; }
                    int pt;
                    if (!IsEligibleForUnrest(cand, out pt)) continue;
                    RecruitUnrestPed(cand, pt);
                }
            }

            int tier = 1 + (int)((nowMod - unrestStartTicks) / UNREST_ARM_TIER_TICKS);
            int pct = Math.Min(UNREST_ARM_MAX_PCT, UNREST_ARM_BASE_PCT + UNREST_ARM_STEP_PCT * (tier - 1));
            // iter-51: emit BEFORE the roster-empty early return. An empty roster is
            // precisely the state this census exists to explain, and putting it after
            // the return is how the subsystem stayed undiagnosable for a whole session.
            LogUnrestScanCensus(nowWall, stage, unrestPeds.Count);
            if (unrestPeds.Count == 0)
            {
                // iter-51: the published stats describe a roster that no longer
                // exists. Zero them here or unrest-combat keeps reporting the last
                // nonzero inCombat/armed forever, and the sitrep speaks it aloud.
                unrestStatFighting = 0;
                unrestStatArmed = 0;
                unrestStatNearestDist = 9999f;   // the subsystem's "no fight" sentinel
                UnrestHeartbeatLog(nowWall, tier, pct);
                return;
            }

            // ---- profile + arm + confiscate, budgeted ----
            bool melee = getSetting("unrestMelee") == 1;
            bool guns = getSetting("unrestFirearms") == 1;
            bool confiscate = unrestPoliceCached >= 1;
            for (int n = 0; n < UNREST_PROFILE_BUDGET && unrestPeds.Count > 0; n++)
            {
                if (unrestProfileCursor >= unrestPeds.Count) unrestProfileCursor = 0;
                RiotPed rec = unrestPeds[unrestProfileCursor++];
                if (rec.ped == null || !rec.ped.Exists() || rec.ped.IsDead) continue;
                if (rec.profiledStage != unrestStage)
                {
                    // iter-51: the stage profile rewrites BlockPermanentEvents and
                    // AlwaysKeepTask to false, which is precisely what makes an
                    // instigator's order stick. Re-profiling therefore cancels the
                    // order — say so in the log rather than leaving a dangling
                    // `instigating` flag the retire pass would later call "refused".
                    if (rec.instigating) EndUnrestInstigation(rec, "reprofiled");
                    ApplyUnrestStageProfile(rec, unrestStage);
                }
                if (unrestStage >= 1) TryArmUnrestPed(rec, tier, pct, melee, guns);

                // Once police are in the fight a rioter can pick a Carbine Rifle off a
                // dead cop, which silently breaks the "nothing automatic or long-range,
                // ever" rule the weapon pools are built around. Take it back.
                if (confiscate)
                {
                    try
                    {
                        Function.Call(Hash.SET_PED_COMBAT_ATTRIBUTES, rec.ped, 54, false);
                        int cur = Function.Call<int>(Hash.GET_SELECTED_PED_WEAPON, rec.ped);
                        if (cur != 0 && !IsAllowedUnrestWeapon(cur))
                        {
                            rec.ped.Weapons.Remove((WeaponHash)cur);
                            UnrestLog("unrest-weapon-confiscate: ped=" + rec.handle
                                + " weapon=" + cur + " stage=" + unrestStage);
                        }
                    }
                    catch { }
                }
            }

            // ---- iter-51: pull recruits out of ambient scenarios, budgeted ----
            //
            // A recruited ped who is leaning on a wall, smoking, or sitting on a
            // bench stays in that scenario forever: it is a non-temporary event and
            // the riot profile explicitly UN-blocks those, so the scenario keeps
            // winning. That ped counts toward `recruited` and contributes nothing.
            //
            // This replaces the old scenario-density zeroing, which "solved" the
            // same cosmetic problem by preventing those peds from existing — and
            // took the recruit pool with it. Taking them out of the scenario and
            // handing them a wander task puts them in the crowd instead.
            //
            // Normal exit below stage 3 (an animated stand-up, which reads as a
            // crowd gathering), panic exit at stage 3+ (abrupt, which reads as a
            // crowd scattering into a riot). One shot per ped, small budget.
            if (unrestStage >= 2)
            {
                bool panic = unrestStage >= 3;
                int pulled = 0;
                for (int n = 0; n < unrestPeds.Count && pulled < UNREST_SCENARIO_EXIT_BUDGET; n++)
                {
                    if (unrestScenarioCursor >= unrestPeds.Count) unrestScenarioCursor = 0;
                    RiotPed rec = unrestPeds[unrestScenarioCursor++];
                    if (rec.scenarioPulled) continue;
                    if (rec.ped == null || !rec.ped.Exists() || rec.ped.IsDead) continue;
                    try
                    {
                        if (!Function.Call<bool>(Hash.IS_PED_USING_ANY_SCENARIO, rec.ped))
                        {
                            // Not in one — nothing to pull it out of. Mark it done so
                            // the cursor does not keep paying for the native call.
                            rec.scenarioPulled = true;
                            continue;
                        }
                        if (panic)
                            Function.Call(Hash.SET_PED_PANIC_EXIT_SCENARIO, rec.ped, 0, 0, 0);
                        else
                            Function.Call(Hash.SET_PED_SHOULD_PLAY_NORMAL_SCENARIO_EXIT, rec.ped);
                        // Give it somewhere to be once the exit clip finishes,
                        // otherwise the engine is free to put it straight back.
                        Function.Call(Hash.TASK_WANDER_STANDARD, rec.ped, 10f, 10);
                        rec.scenarioPulled = true;
                        pulled++;
                        unrestScenarioPulls++;
                        UnrestLog("unrest-scenario-exit: ped=" + rec.handle
                            + " mode=" + (panic ? "panic" : "normal")
                            + " stage=" + unrestStage + " total=" + unrestScenarioPulls);
                    }
                    catch { rec.scenarioPulled = true; }
                }
            }

            // ---- register hated targets, budgeted ----
            // THE "don't command the fight" hook: this hands a ped the list of
            // people it already hates and lets its own AI decide what to do.
            if (unrestStage >= 1)
            {
                float hatedRadius = UNREST_HATED_RADIUS[unrestStage];
                // SET_PED_MOVE_RATE_OVERRIDE's own doc says "needs to be looped", so it
                // rides this slice rather than the one-shot profile slice.
                bool fastCrowd = unrestBrutalityCached >= 1 && unrestStage >= 3;
                float moveRate = UNREST_MOVE_RATE[unrestStage];
                for (int n = 0; n < UNREST_REGISTER_BUDGET && unrestPeds.Count > 0; n++)
                {
                    if (unrestRegisterCursor >= unrestPeds.Count) unrestRegisterCursor = 0;
                    RiotPed rec = unrestPeds[unrestRegisterCursor++];
                    if (rec.ped == null || !rec.ped.Exists() || rec.ped.IsDead) continue;
                    Function.Call(Hash.REGISTER_HATED_TARGETS_AROUND_PED, rec.ped, hatedRadius);
                    if (fastCrowd)
                        Function.Call(Hash.SET_PED_MOVE_RATE_OVERRIDE, rec.ped, moveRate);
                }
            }

            // ---- compaction + stats + safety watchdog, budgeted ----
            bool watchdog = getSetting("unrestSafetyWatchdog") == 1;
            GTA.Math.Vector3 pPos = player.Position;
            for (int n = 0; n < UNREST_COMPACT_BUDGET && unrestPeds.Count > 0; n++)
            {
                if (unrestCompactCursor >= unrestPeds.Count)
                {
                    // Wrapped: publish the accumulated stats and start a new pass.
                    unrestStatFighting = unrestAccFighting;
                    unrestStatArmed = unrestAccArmed;
                    unrestStatNearestDist = unrestAccNearestDist;
                    unrestStatNearestDir = unrestAccNearestDir;
                    // Engagements are EVENTS, not a snapshot: hand the batch over and
                    // zero the accumulator. The heat model consumes (and re-zeroes)
                    // unrestStatCombatEntries on its next tick, so nothing is
                    // double-counted and nothing is lost between passes.
                    unrestStatCombatEntries += unrestAccCombatEntries;
                    unrestAccCombatEntries = 0;
                    unrestAccFighting = 0;
                    unrestAccArmed = 0;
                    unrestAccNearestDist = 9999f;
                    unrestAccNearestDir = "";
                    unrestCompactCursor = 0;
                }
                RiotPed rec = unrestPeds[unrestCompactCursor];
                Ped p = rec.ped;
                if (p == null || !p.Exists() || p.Handle != rec.handle)
                {
                    unrestHandles.Remove(rec.handle);
                    unrestPeds.RemoveAt(unrestCompactCursor);
                    continue;
                }
                if (p.IsDead)
                {
                    unrestCasualties++;
                    unrestHandles.Remove(rec.handle);
                    unrestPeds.RemoveAt(unrestCompactCursor);
                    continue;
                }

                // Defence in depth: the group-level Respect should make this
                // impossible, but a blind player cannot see a rioter turn on them.
                if (watchdog && p.IsInCombatAgainst(player))
                {
                    RestoreUnrestPed(rec);
                    unrestHandles.Remove(rec.handle);
                    unrestPeds.RemoveAt(unrestCompactCursor);
                    if (nowMod - unrestSafetyWindowTicks > 100000000L)   // 10 s window
                    {
                        unrestSafetyWindowTicks = nowMod;
                        unrestSafetyViolations = 0;
                    }
                    unrestSafetyViolations++;
                    UnrestLog("unrest-safety: violations=" + unrestSafetyViolations);
                    Speech.Critical("A rioter turned on you.");
                    if (unrestSafetyViolations > 3)
                    {
                        Speech.Critical("Civil unrest shut down: rioters were targeting you.");
                        StopCivilUnrest("safety");
                        return;
                    }
                    continue;
                }

                bool nowCombat = p.IsInCombat;
                // Rising edge only — a ped that stays in combat for a minute is one
                // engagement, not 240 of them.
                if (nowCombat && !rec.wasInCombat) unrestAccCombatEntries++;
                rec.wasInCombat = nowCombat;

                if (nowCombat) unrestAccFighting++;
                if (rec.hasWeapon) unrestAccArmed++;
                float d = p.Position.DistanceTo(pPos);
                if (nowCombat && d < unrestAccNearestDist)
                {
                    unrestAccNearestDist = d;
                    unrestAccNearestDir = getDir(calculate_x_y_angle(pPos.X, pPos.Y,
                        p.Position.X, p.Position.Y, 0));
                }
                unrestCompactCursor++;
            }

            // ---- iter-51: instigators (runs AFTER the stat slice, which is what
            // tells it whether a fight is already underway) ----
            TickUnrestInstigators(nowMod, unrestStage);

            // ---- crowd barks ----
            TickUnrestBarks(nowWall, unrestStage);

            UnrestHeartbeatLog(nowWall, tier, pct);
            UnrestSitRep(nowWall);
        }

        /// <summary>
        /// iter-51: the narrow, bounded exception to "never TELL a rioter to fight".
        ///
        /// Contract, in full:
        ///   * stage 2+ only (below that the roster has no combat profile at all);
        ///   * at most UNREST_INSTIGATOR_MAX live orders;
        ///   * NO new orders while anything in the roster is already fighting — the
        ///     point is to start a chain reaction, not to keep puppeteering it;
        ///   * each instigator gets a DISTINCT target;
        ///   * an instigator is never another instigator's target, so the two orders
        ///     cannot collapse into a single scripted duel;
        ///   * targets are hated by construction (different faction), so the order
        ///     agrees with the relationship graph instead of overriding it.
        ///
        /// The R* pattern from re_gangfight.c is copied deliberately: the combat task
        /// alone does not stick, it needs SET_PED_KEEP_TASK and a temporary
        /// SET_BLOCKING_OF_NON_TEMPORARY_EVENTS(true) or the ped's ambient AI walks
        /// away from the order within a second. That block is reverted the moment the
        /// order ends, because the rest of the roster depends on being event-driven.
        /// </summary>
        private void TickUnrestInstigators(long nowMod, int stage)
        {
            if (stage < 2 || unrestPeds.Count < 2) return;
            if (nowMod - unrestInstigateEvalTicks < UNREST_INSTIGATE_TICK) return;
            unrestInstigateEvalTicks = nowMod;

            // ---- retire finished orders ----
            int live = 0;
            for (int i = 0; i < unrestPeds.Count; i++)
            {
                RiotPed rec = unrestPeds[i];
                if (!rec.instigating) continue;
                string end = null;
                if (rec.ped == null || !rec.ped.Exists() || rec.ped.IsDead) end = "dead";
                else if (!rec.ped.IsInCombat && nowMod - rec.instigateTicks > UNREST_INSTIGATE_SETTLE)
                    end = "refused";
                if (end == null) { live++; continue; }
                EndUnrestInstigation(rec, end);
            }
            unrestInstigators = live;

            // ---- the gate the user asked for: only re-seed at zero ----
            if (live > 0 || unrestStatFighting > 0) return;
            if (nowMod - unrestInstigateTicks < UNREST_INSTIGATE_COOLDOWN) return;

            // ---- pick instigators: armed first, then anyone ----
            var chosen = new List<RiotPed>();
            for (int pass = 0; pass < 2 && chosen.Count < UNREST_INSTIGATOR_MAX; pass++)
            {
                bool wantArmed = pass == 0;
                for (int i = 0; i < unrestPeds.Count && chosen.Count < UNREST_INSTIGATOR_MAX; i++)
                {
                    RiotPed rec = unrestPeds[i];
                    if (rec.instigating || chosen.Contains(rec)) continue;
                    if (rec.hasWeapon != wantArmed) continue;
                    if (rec.ped == null || !rec.ped.Exists() || rec.ped.IsDead) continue;
                    if (rec.ped.IsInVehicle()) continue;
                    chosen.Add(rec);
                }
            }
            if (chosen.Count == 0) return;

            // ---- assign one distinct hated target each ----
            var usedTargets = new HashSet<int>();
            int issued = 0;
            foreach (RiotPed rec in chosen)
            {
                RiotPed target = null;
                float best = UNREST_INSTIGATE_RADIUS;
                GTA.Math.Vector3 from = rec.ped.Position;
                for (int j = 0; j < unrestPeds.Count; j++)
                {
                    RiotPed cand = unrestPeds[j];
                    if (cand == rec) continue;
                    // Never each other, and never a target twice.
                    if (chosen.Contains(cand)) continue;
                    if (usedTargets.Contains(cand.handle)) continue;
                    // Hated by construction. Same-faction is a friend and ordering
                    // that fight would contradict the relationship graph.
                    if (cand.faction == rec.faction) continue;
                    if (cand.ped == null || !cand.ped.Exists() || cand.ped.IsDead) continue;
                    if (cand.ped.IsInVehicle()) continue;
                    float d = cand.ped.Position.DistanceTo(from);
                    if (d < best) { best = d; target = cand; }
                }
                if (target == null) continue;
                if (!BeginUnrestInstigation(rec, target, best, nowMod)) continue;
                usedTargets.Add(target.handle);
                issued++;
            }

            if (issued > 0)
            {
                unrestInstigateTicks = nowMod;
                unrestInstigators = issued;
                // The riot escalating off its own violence is the whole point of the
                // heat model; an order that starts a fight is exactly the signal it
                // was missing. Counted as an engagement so a chain reaction can push
                // the stage up instead of the clock doing all the work.
                unrestStatCombatEntries += issued;
            }
        }

        /// <summary>iter-51: issue one combat order. Returns false if the engine
        /// refused any part of it, so the caller does not book a target as used.</summary>
        private bool BeginUnrestInstigation(RiotPed rec, RiotPed target, float dist, long nowMod)
        {
            try
            {
                // KEEP_TASK + blocking is the difference between an order and a
                // suggestion — without them the ped's ambient AI drops the combat
                // task on the next event and inCombat never rises.
                Function.Call(Hash.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, rec.ped, true);
                Function.Call(Hash.TASK_COMBAT_PED, rec.ped, target.ped, 0, 16);
                Function.Call(Hash.SET_PED_KEEP_TASK, rec.ped, true);
            }
            catch
            {
                try { Function.Call(Hash.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, rec.ped, false); }
                catch { }
                return false;
            }
            rec.instigating = true;
            rec.instigateTargetHandle = target.handle;
            rec.instigateTicks = nowMod;
            unrestInstigateTotal++;
            UnrestLog("unrest-instigate: ped=" + rec.handle
                + " target=" + target.handle
                + " faction=" + rec.faction
                + " targetFaction=" + target.faction
                + " dist=" + dist.ToString("F0")
                + " armed=" + (rec.hasWeapon ? 1 : 0)
                + " stage=" + unrestStage
                + " total=" + unrestInstigateTotal);
            return true;
        }

        /// <summary>iter-51: retire a combat order and hand the ped back to its own
        /// AI. Restoring the event block is mandatory — a roster ped that stays
        /// blocked is deaf to gunfire, which is the opposite of a rioter.</summary>
        private void EndUnrestInstigation(RiotPed rec, string reason)
        {
            rec.instigating = false;
            rec.instigateTargetHandle = 0;
            try
            {
                if (rec.ped != null && rec.ped.Exists() && !rec.ped.IsDead)
                {
                    Function.Call(Hash.SET_BLOCKING_OF_NON_TEMPORARY_EVENTS, rec.ped, false);
                    Function.Call(Hash.SET_PED_KEEP_TASK, rec.ped, false);
                }
            }
            catch { }
            UnrestLog("unrest-instigate-end: ped=" + rec.handle + " reason=" + reason);
        }

        /// <summary>
        /// The 1 Hz instrumentation pair. `unrest-combat` answers "does the riot
        /// actually start?"; `unrest-heat` is the dark-launch record that decides
        /// whether the heat signal is trustworthy enough to drive escalation.
        /// The `wanted=` field is the specific evidence for the open question of
        /// whether config flag 42 covers crimes committed BY a flagged rioter
        /// against a cop — do not assume it does, read it out of a session.
        /// </summary>
        private void UnrestHeartbeatLog(long nowWall, int tier, int pct)
        {
            if (nowWall - unrestLastCombatLogTicks <= 10000000L) return;
            unrestLastCombatLogTicks = nowWall;
            UnrestLog("unrest-combat: stage=" + unrestStage + " recruited=" + unrestPeds.Count
                + " inCombat=" + unrestStatFighting + " armed=" + unrestStatArmed
                + " down=" + unrestCasualties + " tier=" + tier + " pct=" + pct
                + " wanted=" + Game.Player.WantedLevel
                + " heat=" + ((int)unrestHeat)
                + " drivers=" + unrestDrivers.Count
                + " copsEngaged=" + unrestStatCopsEngaged
                // iter-51: the three numbers that make an inCombat=0 line
                // self-explaining. instigators = orders live now; instigTotal =
                // orders ever issued (0 means the seeding never ran, which is a
                // different bug from orders that never took); scenPulls = peds
                // taken out of an ambient scenario so they could join at all.
                + " instigators=" + unrestInstigators
                + " instigTotal=" + unrestInstigateTotal
                + " scenPulls=" + unrestScenarioPulls);
            UnrestLog("unrest-heat: stage=" + unrestStage + " timeStage=" + unrestTimeStage
                + " heatStage=" + unrestHeatStage + " heat=" + unrestHeat.ToString("F1")
                + " casualties=" + unrestCasualties
                + " engagements=" + unrestHeatEngagements
                + " playerShots=" + unrestHeatPlayerShots
                // iter-51: the three new inputs, so a heat curve can be attributed
                // rather than guessed at, plus the decay actually in force.
                + " fires=" + unrestHeatFires
                + " alarms=" + unrestHeatAlarms
                + " dispatches=" + unrestHeatDispatches
                + " decay=" + UNREST_HEAT_DECAY_PER_SEC.ToString("F1")
                + " dynamic=" + (getSetting("unrestEscalation") == 1 ? 1 : 0));
        }

        /// <summary>
        /// Per-FRAME half of Civil Unrest. It exists only because the population
        /// multipliers are _THIS_FRAME natives: the engine resets them every frame,
        /// so a value written from the 4 Hz TickCivilUnrest body would be live for
        /// one frame in fifteen and do nothing observable.
        ///
        /// Reads ONLY fields the 4 Hz tick cached — no getSetting (an O(n) scan of
        /// ~110 settings), no entity work, no allocation, three native calls worst
        /// case. It is also the whole teardown story for population density: stop
        /// calling these and the engine reverts on the very next frame, which is why
        /// they were chosen over ADD_POP_MULTIPLIER_AREA, whose area id is
        /// process-local and unrecoverable after a hard reload.
        /// </summary>
        private void TickCivilUnrestFrame()
        {
            if (!unrestFrameActive || Game.IsLoading) return;
            Function.Call(Hash.SET_PED_DENSITY_MULTIPLIER_THIS_FRAME, unrestFramePedDensity);
            if (unrestFrameScenarioZero)
                Function.Call(Hash.SET_SCENARIO_PED_DENSITY_MULTIPLIER_THIS_FRAME, 0f, 0f);
            if (unrestFrameVehDensity > 1.001f)
                Function.Call(Hash.SET_VEHICLE_DENSITY_MULTIPLIER_THIS_FRAME, unrestFrameVehDensity);
        }
        #endregion

        #region INTOXICATION (iter-45)
        // ===================================================================
        // CONSUMABLES + INTOXICATION
        //
        // Every state here maps 1:1 onto a state the ENGINE actually has. GTA V
        // exposes exactly THREE drunk stages, and the two independent axes agree:
        //   audio       audSpecialEffectMode DrunkStage01/02/03  (5/6/7)
        //   locomotion  move_m@drunk@ slightlydrunk/moderatedrunk/verydrunk
        // MOVE_M@DRUNK@MODERATEDRUNK_HEAD_UP is a VARIANT of stage 2, not a fourth
        // stage. iter-44 shipped five levels over an abstract 0-100 point meter and
        // had to pad the gap with that variant; any honest audio table gave it away
        // by mapping two levels onto DrunkStage03. DO NOT ADD A STAGE.
        //
        // Cannabis has ONE engine state (kSpecialEffectModeStoned) and no stoned
        // locomotion family at all, so it gets one. It never has its own stumble
        // ladder — it feeds IntoxImpairment() at half weight so mixing escalates.
        //
        // Blackout is this mod's own overlay, NOT a stage: it trips on sustained
        // time at stage 3 and lives in its own flag.
        //
        // Doses are standard drinks and metabolism is 1 drink per GAME hour, which
        // at GTA V's 30:1 time scale is 1 drink per 2 real minutes. Constants say
        // whether they are derived or tuned; keep that up.
        //
        // The whole visual layer is unobservable to this mod's users. It is
        // therefore quarantined in ApplyIntoxVisuals(), gated on intoxVisuals, and
        // NOTHING audible or mechanical is allowed to depend on a visual
        // succeeding. Conversely every stage change, every refusal and every loss
        // of control is spoken — an unannounced impairment is a bug, not a feature.
        // ===================================================================


        private float intoxDrinks = 0f;             // standard drinks of alcohol
        private float intoxHits = 0f;               // cannabis hits
        private int intoxStage = 0;                 // 0-3, one per engine drunk stage
        private bool intoxBlackout = false;         // overlay, NOT a stage
        private long intoxStage3SinceTicks = 0;     // ModClock
        private long intoxLastTickTicks = 0;        // ModClock ONLY
        private long intoxLastReminderTicks = 0;    // ModClock
        private int intoxConsuming = -1;
        private long intoxConsumeEndTicks = 0;      // ModClock
        private long intoxConsumeHardTicks = 0;     // ModClock
        private long intoxLastConsumeTicks = 0;     // ModClock
        private bool intoxConsumeScenario = false;
        private bool intoxConsumeInVehicle = false;  // where the consume STARTED
        private string intoxClipsetApplied = null;
        private string intoxClipsetWanted = null;
        private long intoxClipsetRequestedTicks = 0;   // ModClock
        private bool intoxClipsetFailed = false;
        private int intoxAppliedToHandle = 0;
        private bool intoxVisualsApplied = false;
        private int intoxAudioMode = 0;             // last mode written; change-only logging
        private int intoxSuppressLoggedStage = -1;  // vanilla-only suppression, logged on change
        private int intoxVanillaDrinks = 0;         // drink count for the vanilla bridge
        private bool intoxVanillaFailed = false;    // fingerprint rejected; never retry blind
        // Consumption animation + prop
        private bool intoxAnimPending = false;
        private long intoxAnimRequestedTicks = 0;   // ModClock
        private string intoxAnimDict = null;        // dict actually playing (for STOP_ANIM_TASK)
        private string intoxAnimClip = null;
        private Prop intoxProp = null;
        private Prop intoxProp2 = null;              // lighter / bottle / cap
        private bool intoxPropAttached = false;      // per-consume, for one-line reporting
        private long intoxAnimStartedTicks = 0;      // ModClock
        private bool intoxAnimVerified = false;
        private string intoxBankName = null;
        private bool intoxBankLoaded = false;
        private int intoxSyncScene = -1;
        // ---- iter-51: the outro leg ----------------------------------------
        // A consume is now two scenes: the enter clip, then (when the row has one)
        // the exit clip. intoxSyncScene points at whichever is CURRENT, so every
        // phase test, the release watchdog and the teardown keep working unchanged;
        // these three fields only exist so the tick can tell which leg it is in and
        // so the outro has its own wall-clock backstop.
        private bool intoxOutroActive = false;
        private int  intoxOutroScene = -1;
        private long intoxOutroEndTicks = 0;         // ModClock
        private int intoxLastSyncScene = -1;         // survives teardown, for the watchdog
        private long intoxReleaseVerifyTicks = 0;    // ModClock
        // iter-47. The consume used to be timed from the MENU PRESS against a
        // hand-picked Ms, which is why animations were cut off mid-move while the
        // mod announced them finished: the clock included the anim dict's whole
        // streaming window, and the Ms guesses were far shorter than the real
        // safehouse clips (bong_FRA runs many times the 5000 ms it was given).
        // Now the clock starts when the animation actually starts and its length
        // comes from GET_ANIM_DURATION, exactly as vanilla runs these on scene
        // PHASE rather than on a timer.
        private long intoxConsumeStartTicks = 0;     // ModClock, when the ANIM began
        private int intoxConsumePlanMs = 0;          // planned length, measured not guessed
        private bool intoxSceneConfirmed = false;    // scene was seen running at least once
        private string intoxAudioSceneName = null;   // audio scene started, for teardown
        private bool intoxWeaponStashed = false;
        private WeaponHash intoxPrevWeapon = WeaponHash.Unarmed;
        private long intoxStateLogTicks = 0;         // ModClock, heartbeat
        private bool intoxVanillaWasActive = false;  // vanilla-only, for the sober line
        // Driving
        private bool intoxAssistSuspend = false;
        private long intoxAssistSuspendSinceTicks = 0;  // ModClock, telemetry only
        private float intoxSteerTarget = 0f;
        private float intoxSteerCurrent = 0f;
        private long intoxSteerNextTicks = 0;       // ModClock
        private long intoxStutterUntilTicks = 0;    // ModClock
        private bool intoxCompensateSaid = false;
        private bool intoxBlackoutDriving = false;
        private long intoxBlackoutNagTicks = 0;     // ModClock
        private long intoxRagdollTicks = 0;         // ModClock
        private bool intoxPassedOutSaid = false;

        /// <summary>
        /// One consumable. A row per item rather than a dozen parallel arrays: at
        /// this length a misaligned array would silently pair the wrong prop or bank
        /// with the wrong drink, and nothing would catch it until an in-game session.
        /// </summary>
        private sealed class Consumable
        {
            public readonly string Action;    // menu wording, imperative
            public readonly string Name;      // short name for logs and status
            public readonly float Drinks;     // standard drinks of alcohol
            public readonly float Hits;       // cannabis-equivalent hits
            // MINIMUM consume duration, not the duration. The real length comes from
            // GET_ANIM_DURATION on the clip below; this is only the floor, for clips
            // that are shorter than the dose should take (the idle/"loop" rows) and
            // for the fallback paths where no clip length can be measured. Treating
            // these hand-picked numbers as the duration is what cut the safehouse
            // animations off partway through.
            public readonly int Ms;
            public readonly bool Smoke;       // scenario fallback picks smoking
            public readonly bool CarOk;       // usable while in a vehicle
            public readonly string Prop;      // model, or null for none
            public readonly string Dict;      // anim dictionary
            public readonly string Clip;      // player clip
            public readonly string PropClip;  // prop clip in the same dict, or null
            public readonly string Bank;      // AMBIENT audio bank, or null
            // Second prop. The safehouse scenes are three-handed: player, the thing
            // being consumed, and the thing that opens or lights it — a lighter for
            // the bong, the bottle a glass is poured from, the cap off a beer. The
            // lighting and opening sounds live on THIS half, so a bong with no
            // lighter is both visually and audibly unlit.
            public readonly string Prop2;
            public readonly string Prop2Clip;

            // ---- iter-51: the OUTRO ------------------------------------------
            // Until now a consume ended by abandoning the enter clip at 95% and
            // calling CLEAR_PED_TASKS, so the player never put the bottle down, never
            // stood up, never lowered the glass — the animation just stopped. The
            // vanilla scripts do have outros, and they pick them BY DRUNKENNESS: a
            // sober Michael sets his tumbler down neatly, a very drunk one fumbles it.
            //
            // Both arrays are indexed by the mod's intoxStage (0 sober, 1 slightly,
            // 2 moderately, 3 very drunk) and may be:
            //   null       - this row has no outro; end the way it always did
            //   length 1   - one clip for every stage
            //   length 4   - the full vanilla per-stage set
            // ExitClipFor() below does the clamping, so a short array is legal.
            public readonly string[] Exit;       // player outro clips
            public readonly string[] ExitProp;   // matching prop outro clips
            public readonly string ExitProp2;    // second prop, stage-independent

            public Consumable(string action, string name, float drinks, float hits, int ms,
                bool smoke, bool carOk, string prop, string dict, string clip,
                string propClip, string bank, string prop2 = null, string prop2Clip = null,
                string[] exit = null, string[] exitProp = null, string exitProp2 = null)
            {
                Action = action; Name = name; Drinks = drinks; Hits = hits; Ms = ms;
                Smoke = smoke; CarOk = carOk; Prop = prop; Dict = dict; Clip = clip;
                PropClip = propClip; Bank = bank; Prop2 = prop2; Prop2Clip = prop2Clip;
                Exit = exit; ExitProp = exitProp; ExitProp2 = exitProp2;
            }

            /// <summary>Outro clip for an intoxication stage, or null. Clamps rather
            /// than throwing so a row may carry one clip instead of four.</summary>
            public static string Pick(string[] set, int stage)
            {
                if (set == null || set.Length == 0) return null;
                if (stage < 0) stage = 0;
                if (stage >= set.Length) stage = set.Length - 1;
                return set[stage];
            }
        }

        // THE CATALOGUE.
        //
        // Rows 0-12 are transcribed from the decompiled safehouse activity scripts
        // (ob_bong / ob_franklin_beer / ob_franklin_wine / ob_wheatgrass / ob_sofa_*
        // / ob_huffing_gas / ob_mr_raspberry_jam), which share one table keyed on the
        // prop model. Prop, dict, clips and bank are all verbatim — these are the
        // rows most likely to work.
        //
        // Row 13-14 (nightclub) and 17+ (food and soft drinks) are NOT from a script:
        // GTA V single-player has no eating mechanic outside the vending machine, so
        // those rows drive assets that exist but are never sequenced in SP. Their
        // dict/clip pairs are inferred and there is no ambient bank for any of them,
        // so expect animation without foley. intox-anim-playing reports which land.
        //
        // Doses: beer 1 standard drink, whiskey tumbler 2, wine 1.5. Smokes feed the
        // cannabis meter. Gas is a solvent but rides that meter because
        // kSpecialEffectModeStoned is the closest thing the engine models. Food and
        // soft drinks dose nothing and say so in the menu.
        //
        // iter-51: the `exit` / `exitProp` arrays are transcribed from the SAME
        // shared safehouse template, func_2 (prop outro) and func_6 (player outro),
        // both keyed on the prop model and then on the drunkenness index. Vanilla's
        // index is {-1 sober, 1 slightly, 2 moderately, 0 very drunk}, which is
        // re-ordered here into the mod's own intoxStage order 0/1/2/3 — read the
        // arrays as sober, slightly, moderately, very.
        // Every food row shares one dictionary, whose three clips are
        // _enter / (loop) / _exit_. The mod plays the loop, so this is the outro all
        // twelve of them were missing — the player used to stop mid-bite.
        private static readonly string[] EAT_EXIT = { "mp_player_int_eat_exit_burger" };

        private static readonly Consumable[] CONSUMABLES = {
            //             action                        name              drink hit   ms  smk  car   prop                    dict                       clip                            propClip                        bank
            new Consumable("Drink Franklin's beer.",      "beer",           1.0f, 0f, 6000, false, true,  "prop_cs_beer_bot_01",  "safe@franklin@ig_9",      "enter",                        "enter_bottle",                 "SAFEHOUSE_FRANKLIN_DRINK_BEER",    null, null,
                new[] { "exit_1", "exit_3", "exit_2", "exit_4" },
                new[] { "exit_1_bottle", "exit_3_bottle", "exit_2_bottle", "exit_4_bottle" }),
            new Consumable("Drink Trevor's beer.",        "beer",           1.0f, 0f, 6000, false, true,  "prop_radio_01",        "safe@trevor@ig_5",        "enter",                        "enter_beer",                   "SAFEHOUSE_TREVOR_DRINK_BEER",      "prop_bottle_cap_01",   "enter_cap",
                new[] { "exit_sober", "exit_slightly_drunk", "exit_moderately_drunk", "exit_very_drunk" },
                new[] { "exit_2_beer", "exit_1_beer", "exit_2_beer", "exit_1_beer" }),
            new Consumable("Drink Michael's beer.",       "beer",           1.0f, 0f, 6000, false, true,  "prop_radio_01",        "safe@michael@ig_5",       "enter_michael",                "enter_bottle",                 "SAFEHOUSE_MICHAEL_DRINK_BEER",     "prop_bottle_cap_01",   "enter_cap",
                new[] { "exit_1_michael", "exit_3_michael", "exit_2_michael", "exit_4_michael" },
                new[] { "exit_2_bottle", "exit_1_bottle", "exit_2_bottle", "exit_1_bottle" }),
            // Second prop is p_whiskey_bottle_s, not prop_cs_whiskey_bottle: that
