            new Consumable("Drink Michael's whiskey.",    "whiskey",        2.0f, 0f, 4000, false, true,  "p_tumbler_02_s1",      "safe@michael@ig_1",       "enter",                        "enter_glass",                  "SAFEHOUSE_MICHAEL_DRINK_WHISKEY",  "p_whiskey_bottle_s",   "enter_bot",
                new[] { "exit_sober", "exit_slightly_drunk", "exit_moderately_drunk", "exit_drunk" },
                new[] { "exit_sober_glass", "exit_drunk_glass", "exit_sober_glass", "exit_drunk_glass" }),
            // Trevor's shot glass is the one row whose outros are UPPERCASE in the
            // script. Clip lookup is case-insensitive in practice, but they are kept
            // verbatim so a future diff against the corpus is exact.
            new Consumable("Drink Trevor's whiskey.",     "whiskey",        2.0f, 0f, 4000, false, true,  "p_tumbler_cs2_s_trev", "safe@trevor@ig_6",        "enter_trevor",                 "enter_shotglass",              "SAFEHOUSE_TREVOR_DRINK_WHISKEY",   "p_whiskey_bottle_s",   "enter_bottle",
