        // Stage climb thresholds in drink-equivalents: ONE beer is Tipsy, the
        // engine's first real drunk stage. Fall thresholds sit 0.5 drinks lower
        // (see IntoxStageFor) so a decaying meter cannot flutter across a boundary
        // and re-announce. Four entries because there are four states, sober
        // included — there is no fifth.
        private static readonly float[] INTOX_STAGE_AT = { 0f, 1f, 3f, 6f };
        private static readonly string[] INTOX_CLIPSET = {
            null,
            "move_m@drunk@slightlydrunk",
            "move_m@drunk@moderatedrunk",
            "move_m@drunk@verydrunk" };
        // audSpecialEffectMode. The enum documents DrunkStage01/02/03 as 5/6/7, and
        // iter-45 used them — but the SHIPPED GAME NEVER DOES. Across the whole of
        // drunk.c and drunk_controller.c this native is called with exactly two
        // values: 2 (on) and 0 (off). Even the *drunk* controller writes 2, which
        // the enum calls "Stoned". 5/6/7 are declared but unmapped, so writing them
        // is a silent no-op — that is why the reverb only ever appeared after a
        // bong hit, the one case that took the cannabis branch and wrote 2.
        // There is ONE audio mode. Intensity has to come from the timecycle and
        // camera shake, which already scale per stage.
        private const int INTOX_AUDIO_ON = 2;
        // TASK_SYNCHRONIZED_SCENE flags, verbatim from the vanilla consumable
        // scripts: SYNCED_SCENE_USE_PHYSICS (1) | SYNCED_SCENE_DONT_INTERRUPT (4).
        private const int INTOX_SCENE_FLAGS = 5;
        // Vanilla runs its consumable scenes to phase 0.95 and then tears them down;
        // the last 5% is blend-out. Same number here so the animation is judged
        // finished by the ENGINE's own progress through the clip, never by a clock.
        private const float INTOX_SCENE_DONE_PHASE = 0.95f;
        // Cannabis has no stumble ladder of its own, but mixing must still escalate.
        private const float INTOX_CANNABIS_WEIGHT = 0.5f;

        // Name tables, deliberately data not code: none of these can be verified
        // without an in-game session, and a wrong name is a silent no-op. If one
        // turns out wrong it is a one-line fix here, not a code change.
        // Verbatim from the decompiled scripts, replacing iter-45's guesses
        // ("spectator5" / "drug_wobbly"): ob_drinking_shots.c writes "DRUNK" into
        // the drunk-controller's timecycle global, and the sofa script's func_31
        // returns "STONED" for the smoking effect.
        private const string INTOX_TCMOD_DRUNK = "DRUNK";
        private const string INTOX_TCMOD_HIGH = "STONED";
        private const string INTOX_POSTFX_HIGH = "DrugsMichaelAliensFight";
        // Transcribed from the decompiled safehouse-activity script
        // ob_mr_raspberry_jam.c — the script behind Franklin's bong, Michael's
        // whiskey and the rest. Prop model, anim dict, player clip, prop clip and
        // audio bank all come out of that script's switch statements keyed on the
        // prop model, so these are transcriptions, not guesses.
        //
        // The BANK is the piece that was missing. It is an AMBIENT bank, requested
        // with REQUEST_AMBIENT_AUDIO_BANK. iter-45b requested a SCRIPT audio bank —
        // a different pool entirely — which is why the foley stayed silent even
        // with the animation confirmed playing and the prop confirmed in hand.
        // PH_R_HAND: the prop-attach bone, not the skeleton hand bone.
        private const int INTOX_BONE_PH_R_HAND = 28422;

        // 1 standard drink per GAME hour = 1 drink per 2 real minutes at GTA V's
        // 30:1 time scale. ModClock (real, pause-proof) is the clock, NOT the game
        // clock, which jumps on sleep and mission transitions.
        private const float INTOX_DECAY_DRINKS = 0.5f;   // per real minute, derived
        private const float INTOX_DECAY_HITS = 0.75f;    // per real minute, game feel
        private const float INTOX_BLACKOUT_DECAY_MULT = 3f;
        // Blackout trips on SUSTAINED stage 3, so drinking fast cannot skip past it.
        // Emergent calibration, which is the point of using real units: stage 3
        // climbs at 6.0 and falls at 5.5, so exactly 6.0 drinks decays back out in
        // 60 s and never blacks out. It takes roughly 7 drinks to stay under long
        // enough. That number falls out of the model rather than being picked.
        private const long INTOX_BLACKOUT_AFTER = 900000000L;   // 90 s at stage 3

        /// <summary>
        /// Menu label. Carries the dose so a blind player can tell the items apart
        /// by effect rather than by name alone — "Trevor's whiskey" and "Franklin's
        /// beer" are otherwise indistinguishable until after you have drunk one.
        /// </summary>
        private string GetConsumeMenuText(int index)
        {
            if (index < 0 || index >= CONSUMABLES.Length) return "";
            string s = CONSUMABLES[index].Action;
            float d = CONSUMABLES[index].Drinks;
            float h = CONSUMABLES[index].Hits;
            if (d > 0f) s += " " + d.ToString("0.#") + (d == 1f ? " drink." : " drinks.");
            else if (h > 0f) s += " " + h.ToString("0.#") + (h == 1f ? " hit." : " hits.");
            else s += " No effect.";
            return s;
        }

        /// <summary>
        /// The AUDIO SCENE that has to be active for a safehouse consumable to be
        /// audible. This was the missing half of the foley, and it is the reason
        /// loading the ambient bank alone changed nothing: an ambient bank makes the
        /// sounds RESIDENT, the audio scene is what routes and unmutes them. Every
        /// vanilla consumable script starts one before the sequence and stops it
        /// after (ob_franklin_beer.c: START_AUDIO_SCENE("FRANKLIN_SAFEHOUSE_ACTIVITIES_SCENE")
        /// immediately before the synchronized scene; ob_bong.c hands the same name
        /// to the drunk controller to start on its behalf).
        ///
        /// Derived from the bank name rather than stored per row: the scene is a
        /// property of WHOSE safehouse the activity belongs to, which the bank name
        /// already encodes, so a new row cannot forget to set it. Returns null for
        /// the non-safehouse rows (vending machine, nightclub, food) — those have no
        /// scene, and starting one for them would be a guess.
        /// </summary>
        private static string ConsumeAudioScene(string bank)
        {
            if (bank == null) return null;
            if (bank.StartsWith("SAFEHOUSE_FRANKLIN")) return "FRANKLIN_SAFEHOUSE_ACTIVITIES_SCENE";
            if (bank.StartsWith("SAFEHOUSE_MICHAEL")) return "MICHAEL_SAFEHOUSE_ACTIVITIES_SCENE";
            if (bank.StartsWith("SAFEHOUSE_TREVOR")) return "TREVOR_SAFEHOUSE_ACTIVITIES_SCENE";
            return null;
        }

        /// <summary>
        /// Starts the consumable's audio scene. START_AUDIO_SCENE returns a BOOL, so
        /// unlike a sound name this one failure mode is observable — log it.
        /// </summary>
        private void StartConsumeAudioScene(int kind)
        {
            StopConsumeAudioScene();
            string scene = ConsumeAudioScene(CONSUMABLES[kind].Bank);
            if (scene == null) return;
            bool ok = false, already = false;
            try
            {
                already = Function.Call<bool>(Hash.IS_AUDIO_SCENE_ACTIVE, scene);
                ok = already || Function.Call<bool>(Hash.START_AUDIO_SCENE, scene);
            }
            catch { }
            // Only remember it for teardown if WE started it. Standing inside a
            // safehouse the game may already be running this scene for its own
            // activity props, and stopping someone else's audio scene is exactly the
            // kind of damage a mod should never do on the way out.
            intoxAudioSceneName = (ok && !already) ? scene : null;
            IntoxLog("intox-audioscene: name=" + scene + " ok=" + (ok ? 1 : 0)
                + " already=" + (already ? 1 : 0));
        }

        private void StopConsumeAudioScene()
        {
            if (intoxAudioSceneName == null) return;
            try
            {
                if (Function.Call<bool>(Hash.IS_AUDIO_SCENE_ACTIVE, intoxAudioSceneName))
                    Function.Call(Hash.STOP_AUDIO_SCENE, intoxAudioSceneName);
            }
            catch { }
            intoxAudioSceneName = null;
        }

        // ===================================================================
        // VANILLA DRUNKENNESS BRIDGE (intoxVanillaOnly)
        //
        // Drives the GAME's own drunk_controller by writing the same script globals
        // its consumable scripts write, so one drink produces exactly the vanilla
        // effect ladder — camera shake escalating per drink, DRUNK timecycle from
        // the 2nd, audio submix, blackout — with none of this mod's drinks-per-hour
        // metabolism model layered on top.
        //
        // Recipe transcribed from func_299 in stripclub_drinking.c (the Vanilla
        // Unicorn bar) and func_37 in the safehouse activity scripts.
        //
        // THESE INDICES ARE BUILD-SPECIFIC. That is the whole risk: a wrong index
        // writes into unrelated script state. Every entry point therefore checks
        // the block is allocated AND reads the master flag back, and latches
        // intoxVanillaFailed on any mismatch so it fails closed, once, loudly —
        // never a silent scribble over another script's variables.
        // ===================================================================
        private const int VG_DRUNK_ENABLE = 46112;
        private const int VG_DRUNK_CAM = 46113;
        private const int VG_DRUNK_UNTIL = 46114;   // GET_GAME_TIMER deadline
        private const int VG_DRUNK_SPAN = 46115;
        private const int VG_DRUNK_BLUR = 46116;
        private const int VG_DRUNK_SHAKE_CUR = 46117;
        private const int VG_DRUNK_SHAKE_TGT = 46118;
        private const int VG_DRUNK_TC_ON = 46120;
        private const int VG_DRUNK_TC_NAME = 46121;
        private const int INTOX_VANILLA_SPAN_MS = 30000;   // vanilla default span

        /// <summary>
        /// One drink, the vanilla way. Returns false if the globals could not be
        /// verified, in which case the caller falls back to this mod's own model
        /// rather than pretending something happened.
        /// </summary>
        private bool TriggerVanillaDrunk(int kind)
        {
            if (intoxVanillaFailed) return false;
            try
            {
                if (GlobalVariable.Get(VG_DRUNK_ENABLE).MemoryAddress == IntPtr.Zero
                    || GlobalVariable.Get(VG_DRUNK_TC_NAME).MemoryAddress == IntPtr.Zero)
                {
                    intoxVanillaFailed = true;
                    IntoxLog("intox-vanilla-fail: globals not allocated (build mismatch?)");
                    Speech.Critical("The game's drunkenness system is not reachable in this build.");
                    return false;
                }

                intoxVanillaDrinks++;
                // func_300()/func_38(): consumed-count / 10, floored 0.1, capped 1.
                float shake = intoxVanillaDrinks / 10f;
                if (shake < 0.1f) shake = 0.1f;
                if (shake > 1f) shake = 1f;

                int now = Function.Call<int>(Hash.GET_GAME_TIMER);
                bool already = GlobalVariable.Get(VG_DRUNK_ENABLE).Read<int>() != 0;
                int until = GlobalVariable.Get(VG_DRUNK_UNTIL).Read<int>();

                if (already && until > now)
                {
                    // Repeat drink while still drunk: EXTEND, exactly as the vanilla
                    // scripts do (Global_46114 += duration). More drinks keeps you
                    // drunk longer; depth comes from the shake/timecycle below.
                    GlobalVariable.Get(VG_DRUNK_UNTIL).Write<int>(until + INTOX_VANILLA_SPAN_MS);
                }
                else
                {
                    try { Function.Call(Hash.SHAKE_GAMEPLAY_CAM, "DRUNK_SHAKE", shake); } catch { }
                    GlobalVariable.Get(VG_DRUNK_CAM).Write<int>(0);
                    GlobalVariable.Get(VG_DRUNK_ENABLE).Write<int>(1);
                    GlobalVariable.Get(VG_DRUNK_UNTIL).Write<int>(now + INTOX_VANILLA_SPAN_MS);
                    GlobalVariable.Get(VG_DRUNK_SPAN).Write<int>(INTOX_VANILLA_SPAN_MS);
                    GlobalVariable.Get(VG_DRUNK_BLUR).Write<float>(0.3f);
                }
                GlobalVariable.Get(VG_DRUNK_SHAKE_TGT).Write<float>(shake);
                GlobalVariable.Get(VG_DRUNK_SHAKE_CUR).Write<float>(shake);

                // stripclub_drinking.c: the timecycle starts at the SECOND drink.
                if (intoxVanillaDrinks >= 2)
                {
                    GlobalVariable.Get(VG_DRUNK_TC_ON).Write<float>(0.25f);
                    GlobalVariable.Get(VG_DRUNK_TC_NAME).WriteString(
                        CONSUMABLES[kind].Hits > 0f ? INTOX_TCMOD_HIGH : INTOX_TCMOD_DRUNK, 16);
                }

                bool ok = GlobalVariable.Get(VG_DRUNK_ENABLE).Read<int>() == 1;
                if (!ok)
                {
                    intoxVanillaFailed = true;
                    IntoxLog("intox-vanilla-fail: master flag did not read back");
                    return false;
                }
                EnsureDrunkController();
                IntoxLog("intox-vanilla: drink=" + intoxVanillaDrinks
                    + " shake=" + shake.ToString("0.##")
                    + " untilMs=" + (GlobalVariable.Get(VG_DRUNK_UNTIL).Read<int>() - now)
                    + " tc=" + (intoxVanillaDrinks >= 2 ? 1 : 0));
                return true;
            }
            catch (Exception ex)
            {
                intoxVanillaFailed = true;
                IntoxLog("intox-vanilla-fail: " + ex.Message);
                return false;
            }
        }

        /// <summary>
        /// drunk_controller terminates its own thread when nobody is drunk, so
        /// setting the globals is not enough — the thread has to exist to read them.
        /// </summary>
        private void EnsureDrunkController()
        {
            try
            {
                int running = Function.Call<int>(
                    Hash.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH,
                    Game.GenerateHash("drunk_controller"));
                if (running > 0) return;
                Function.Call(Hash.REQUEST_SCRIPT, "drunk_controller");
                if (Function.Call<bool>(Hash.HAS_SCRIPT_LOADED, "drunk_controller"))
                {
                    Function.Call(Hash.START_NEW_SCRIPT, "drunk_controller", 1424);
                    Function.Call(Hash.SET_SCRIPT_AS_NO_LONGER_NEEDED, "drunk_controller");
                    IntoxLog("intox-vanilla: started drunk_controller");
                }
                else
                {
                    IntoxLog("intox-vanilla: drunk_controller not loaded yet");
                }
            }
            catch { }
        }

        private void ClearVanillaDrunk()
        {
            intoxVanillaDrinks = 0;
            if (intoxVanillaFailed) return;
            try
            {
                if (GlobalVariable.Get(VG_DRUNK_ENABLE).MemoryAddress == IntPtr.Zero) return;
                // Let the controller run its own teardown rather than yanking the
                // effects out from under it: clearing the deadline is how vanilla
                // ends a drunk session.
                GlobalVariable.Get(VG_DRUNK_UNTIL).Write<int>(
                    Function.Call<int>(Hash.GET_GAME_TIMER));
            }
            catch { }
        }

        private string IntoxStageName(int v)
        {
            switch (v)
            {
                case 1: return "Tipsy";
                case 2: return "Drunk";
                case 3: return "Very drunk";
                default: return "Sober";
            }
        }

        /// <summary>
        /// Total impairment in drink-equivalents. Cannabis contributes at half
        /// weight: it has no stumble ladder of its own (the engine has no stoned
        /// locomotion family), but mixing it with alcohol must still escalate.
        /// </summary>
        private float IntoxImpairment()
        {
            return intoxDrinks + INTOX_CANNABIS_WEIGHT * intoxHits;
        }

        private int IntoxStageFor(float impairment, int current)
        {
            int lvl = current;
            while (lvl < 3 && impairment >= INTOX_STAGE_AT[lvl + 1]) lvl++;
            while (lvl > 0 && impairment < INTOX_STAGE_AT[lvl] - 0.5f) lvl--;
            return lvl;
        }

        private void IntoxLog(string msg)
        {
            try
            {
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT " + msg);
            }
            catch { }
        }

        /// <summary>
        /// Single owner of the long-lived drive-assist stand-down. Deliberately NOT
        /// assistSuspended: that latch is a COOLDOWN with three auto-resume paths
        /// (toggle, 5 s timeout, sustained speed) and would hand the assist back to a
        /// driver who is still too drunk to use it within five seconds.
        /// </summary>
        private void SetIntoxAssistSuspend(bool on, string why)
        {
            if (intoxAssistSuspend == on) return;
            intoxAssistSuspend = on;
            intoxAssistSuspendSinceTicks = on ? ModClock.Ticks : 0;
            IntoxLog("intox-assist: on=" + (on ? 1 : 0) + " why=" + why);
            if (on) Speech.Critical("You are too drunk to drive. Drive assist is off.");
            else Speech.Info("Drive assist available again.");
        }

        /// <summary>
        /// True when cannabis is the dominant contributor to the current state.
        /// Compared in drink-equivalents so the two meters are on one scale.
        /// </summary>
        private bool IntoxCannabisDominant()
        {
            return INTOX_CANNABIS_WEIGHT * intoxHits > intoxDrinks;
        }

        /// <summary>
        /// Continuous intensity, 0.1..1.0, matching vanilla's func_38() in the
        /// safehouse activity script: consumed-count / 10, floored and capped.
        ///
        /// This is where "it gets worse the more you drink" actually lives. The
        /// audio submix is binary (mode 2 or nothing), so it contributes NONE of
        /// the escalation — vanilla escalates the camera shake, timecycle strength
        /// and motion blur CONTINUOUSLY per drink, and only the movement clipset
        /// moves in discrete steps. Scaling these off the stage index the way
        /// iter-45 did gives three jumps where vanilla gives a smooth ramp.
        /// </summary>
        private float IntoxIntensity()
        {
            float a = IntoxImpairment() / 10f;
            if (a < 0.1f) a = 0.1f;
            if (a > 1f) a = 1f;
            return a;
        }

        private void ApplyIntoxVisuals(Ped player, int stage)
        {
            if (getSetting("intoxVisuals") != 1)
            {
                if (intoxVisualsApplied) ClearIntoxVisuals();
                return;
            }
            try
            {
                bool highDominant = IntoxCannabisDominant();
                if (stage <= 0) { ClearIntoxVisuals(); return; }

                float intensity = IntoxIntensity();
                Function.Call(Hash.SET_TIMECYCLE_MODIFIER,
                    highDominant ? INTOX_TCMOD_HIGH : INTOX_TCMOD_DRUNK);
                Function.Call(Hash.SET_TIMECYCLE_MODIFIER_STRENGTH, intensity);
                // SET_GAMEPLAY_CAM_SHAKE_AMPLITUDE only scales a shake that is
                // ALREADY running, so on its own it did nothing: the single
                // SHAKE_GAMEPLAY_CAM fired on a stage change expires, and from then
                // on every amplitude write went to a shake that no longer existed.
                // drunk_controller.c re-arms it exactly this way, every frame.
                if (!Function.Call<bool>(Hash.IS_GAMEPLAY_CAM_SHAKING))
                    Function.Call(Hash.SHAKE_GAMEPLAY_CAM, "DRUNK_SHAKE", intensity);
                Function.Call(Hash.SET_GAMEPLAY_CAM_SHAKE_AMPLITUDE, intensity);
                if (stage >= 2)
                {
                    Function.Call(Hash.SET_PED_MOTION_BLUR, player, true);
                    if (highDominant)
                        Function.Call(Hash.SET_GAMEPLAY_CAM_MOTION_BLUR_SCALING_THIS_UPDATE, intensity);
                }
                if (stage >= 3 && highDominant)
                {
                    Function.Call(Hash.ENABLE_CLOWN_BLOOD_VFX, true);
                    if (!Function.Call<bool>(Hash.ANIMPOSTFX_IS_RUNNING, INTOX_POSTFX_HIGH))
                        Function.Call(Hash.ANIMPOSTFX_PLAY, INTOX_POSTFX_HIGH, 0, true);
                }
                intoxVisualsApplied = true;
            }
            catch { }
        }

        /// <summary>
        /// Stands this mod's whole presentation layer down, for vanilla-only mode.
        /// Idempotent and cheap enough to call every frame.
        /// </summary>
        private void ClearIntoxPresentation(Ped player)
        {
            if (intoxClipsetApplied != null)
            {
                try { Function.Call(Hash.RESET_PED_MOVEMENT_CLIPSET, player, 0f); } catch { }
                intoxClipsetApplied = null;
                intoxClipsetWanted = null;
                intoxClipsetRequestedTicks = 0;
            }
            if (intoxVisualsApplied) ClearIntoxVisuals();
            // ApplyIntoxAudio is a per-frame override, so simply not writing it IS
            // the handoff — there is nothing to undo beyond forgetting the mode.
            if (intoxAudioMode != 0)
            {
                IntoxLog("intox-audio: mode=0 stage=" + intoxStage + " why=vanilla-only");
                intoxAudioMode = 0;
            }
        }

        private void ClearIntoxVisuals()
        {
            try
            {
                Function.Call(Hash.CLEAR_TIMECYCLE_MODIFIER);
                Function.Call(Hash.STOP_GAMEPLAY_CAM_SHAKING, true);
                Function.Call(Hash.ENABLE_CLOWN_BLOOD_VFX, false);
                Function.Call(Hash.ANIMPOSTFX_STOP, INTOX_POSTFX_HIGH);
                Ped p = Game.Player.Character;
                if (p != null && p.Exists()) Function.Call(Hash.SET_PED_MOTION_BLUR, p, false);
            }
            catch { }
            intoxVisualsApplied = false;
        }

        /// <summary>
        /// The vanilla drunk/stoned audio treatment — the reverb, the muffling and
        /// the slurred dialogue. iter-44 promised "slurred audio" and never called
        /// this native at all, which is why the effects were inaudible.
        ///
        /// SET_AUDIO_SPECIAL_EFFECT_MODE is a PER-FRAME override, not a latch: it
        /// applies for exactly one frame, so this must run every tick or the filter
        /// silently never engages. Corollary: teardown is free — stop calling it and
        /// the engine reverts next frame, so ResetIntoxication needs no counterpart.
        /// </summary>
        private void ApplyIntoxAudio(Ped player, int stage)
        {
            int mode = 0;
            string why = "on";
            // Keyed off the STAGE, never off a raw meter threshold. iter-45's first
            // cut gated on intoxDrinks >= 1.0, which left a dead band: the stage
            // falls at impairment 0.5 but the meter gate needed 1.0, so anything
            // between the two announced "Tipsy" and then played SILENCE. The
            // 2026-08-01 log caught it as "intox-audio: mode=0 stage=1" mid-drive.
            // Invariant: stage > 0 ALWAYS produces a nonzero mode.
            if (getSetting("intoxAudio") != 1) why = "off";
            else if (stage <= 0) why = "sober";
            else mode = INTOX_AUDIO_ON;   // one mode; see INTOX_AUDIO_ON

            if (mode != 0)
            {
                try
                {
                    // The engine owns the override in these states and writing over
                    // it breaks them: mode 1 underwater, mode 3 in the pause menu
                    // (which the menu reader depends on hearing cleanly).
                    if (player.IsSwimming || player.IsInWater) { mode = 0; why = "water"; }
                    else if (Function.Call<bool>(Hash.IS_PAUSE_MENU_ACTIVE)) { mode = 0; why = "pause"; }
                }
                catch { }
            }

            if (mode != intoxAudioMode)
            {
                // clipset= is here deliberately. The script layer only ever writes
                // mode 2 or 0, yet vanilla audibly escalates — so the DrunkStage
                // ladder must be driven engine-side, and the only per-stage drunk
                // state a script controls is the movement clipset, which maps 1:1
                // onto DrunkStage01/02/03. If escalation tracks this field, that is
                // the mechanism; if it does not, the theory is wrong.
                IntoxLog("intox-audio: mode=" + mode + " stage=" + stage + " why=" + why
                    + " drinks=" + intoxDrinks.ToString("0.##")
                    + " hits=" + intoxHits.ToString("0.##")
                    + " clipset=" + (intoxClipsetApplied ?? "none")
                    + " clipsetFail=" + (intoxClipsetFailed ? 1 : 0));
                intoxAudioMode = mode;
            }
            // NEVER write mode 0. This is a per-frame override the engine competes
            // for, so writing Normal every frame would stomp its own Underwater /
            // PauseMenu / SlowMotion modes. Not writing is how you hand it back.
            if (mode == 0) return;

            try
            {
                // audSpecialEffectMode: 0 Normal, 1 Underwater, 2 Stoned,
                // 3 PauseMenu, 4 SlowMotion, 5/6/7 DrunkStage01/02/03. The shipped
                // game writes only 2 and 0 — drunk_controller.c writes 2 per frame
                // for ALCOHOL as well, so there is exactly one mode to write and no
                // per-stage ladder to select here.
                Function.Call(Hash.SET_AUDIO_SPECIAL_EFFECT_MODE, mode);
            }
            catch { }
        }

        /// <summary>
        /// Periodic state line while intoxicated. Every other intox event is
        /// change-only, and that left the two fields that matter unobservable:
        /// intox-audio carried clipset= but fires on the same frame the stage
        /// changes — the one frame the clipset provably CANNOT be applied yet,
        /// because REQUEST_ANIM_SET has not streamed. Every log so far therefore
        /// read "clipset=none", which says nothing about whether it ever landed.
        /// This is also the only line that proves the per-frame audio override is
        /// still being written minutes into a session rather than having silently
        /// stopped.
        /// </summary>
        private void TickIntoxStateLog(long now, bool vanillaOnly)
        {
            if (intoxStage <= 0 && !intoxBlackout) { intoxStateLogTicks = 0; return; }
            if (intoxStateLogTicks != 0 && now - intoxStateLogTicks < 100000000L) return;   // 10 s
            intoxStateLogTicks = now;
            IntoxLog("intox-state: stage=" + intoxStage
                + " impair=" + IntoxImpairment().ToString("0.##")
                + " drinks=" + intoxDrinks.ToString("0.##")
                + " hits=" + intoxHits.ToString("0.##")
                + " mode=" + intoxAudioMode
                + " clipset=" + (intoxClipsetApplied ?? "none")
                + " clipsetFail=" + (intoxClipsetFailed ? 1 : 0)
                + " blackout=" + (intoxBlackout ? 1 : 0)
                + " vanillaOnly=" + (vanillaOnly ? 1 : 0));
        }

        private void ApplyIntoxClipset(Ped player, int stage)
        {
            string want = INTOX_CLIPSET[stage];
            if (want == null)
            {
                if (intoxClipsetApplied != null)
                {
                    try { Function.Call(Hash.RESET_PED_MOVEMENT_CLIPSET, player, 0f); } catch { }
                    intoxClipsetApplied = null;
                }
                intoxClipsetWanted = null;
                intoxClipsetRequestedTicks = 0;
                return;
            }
            if (want != intoxClipsetWanted)
            {
                intoxClipsetWanted = want;
                intoxClipsetRequestedTicks = 0;
                intoxClipsetFailed = false;   // a new stage gets a fresh attempt
            }
            if (intoxClipsetFailed || intoxClipsetApplied == want) return;
            try
            {
                Function.Call(Hash.REQUEST_ANIM_SET, want);
                if (intoxClipsetRequestedTicks == 0) intoxClipsetRequestedTicks = ModClock.Ticks;
                if (Function.Call<bool>(Hash.HAS_ANIM_SET_LOADED, want))
                {
                    Function.Call(Hash.SET_PED_MOVEMENT_CLIPSET, player, want, 1.0f);
                    intoxClipsetApplied = want;
                    intoxClipsetRequestedTicks = 0;
                }
                else if (ModClock.Ticks - intoxClipsetRequestedTicks > 30000000L)   // 3 s
                {
                    // Logged, never spoken: a streaming failure is not the player's
                    // problem and the state machine is unaffected by it.
                    intoxClipsetFailed = true;
                    IntoxLog("intox-clipset-fail: set=" + want);
                }
            }
            catch { }
        }

        private void AnnounceIntoxStage(int from, int to)
        {
            if (to > from)
            {
                switch (to)
                {
                    case 1: Speech.Info("Tipsy."); break;
                    case 2: Speech.Info("Drunk. Your driving is impaired."); break;
                    default: Speech.Critical("Very drunk. Drive assist is off."); break;
                }
            }
            else if (to == 0) Speech.Info("Sober again.");
            else Speech.Info(IntoxStageName(to) + ".");
        }

        private void ResetIntoxication(string reason)
        {
            intoxDrinks = 0f;
            intoxHits = 0f;
            intoxStage = 0;
            intoxBlackout = false;
            intoxStage3SinceTicks = 0;
            intoxConsuming = -1;
            intoxConsumeScenario = false;
            intoxConsumeStartTicks = 0;
            intoxBlackoutDriving = false;
            intoxCompensateSaid = false;
            intoxPassedOutSaid = false;
            intoxVanillaWasActive = false;
            intoxStateLogTicks = 0;
            StopConsumeAnim();
            ClearConsumeProp();
            ReleaseConsumeBank();
            StopConsumeAudioScene();
            RestoreConsumeWeapon();
            ClearVanillaDrunk();
            SetIntoxAssistSuspend(false, reason);
            try
            {
                Ped p = Game.Player.Character;
                if (p != null && p.Exists())
                {
                    Function.Call(Hash.RESET_PED_MOVEMENT_CLIPSET, p, 0f);
                    Function.Call(Hash.SET_PED_IS_DRUNK, p, false);
                    Function.Call(Hash.SET_PED_CONFIG_FLAG, p, 100, false);
                }
                // A ONE-SHOT 0 on teardown, which is what vanilla's own teardown
                // does. Only a PER-FRAME 0 is forbidden — that would fight the
                // engine for its Underwater / PauseMenu / SlowMotion modes.
                if (intoxAudioMode != 0)
                    Function.Call(Hash.SET_AUDIO_SPECIAL_EFFECT_MODE, 0);
            }
            catch { }
            intoxAudioMode = 0;
            intoxClipsetApplied = null;
            intoxClipsetWanted = null;
            intoxClipsetFailed = false;
            intoxClipsetRequestedTicks = 0;
            ClearIntoxVisuals();
        }

        /// <summary>
        /// Deletes the held consumable prop. A bottle welded to the player's hand is
        /// unrecoverable and completely invisible to this mod's users, so this is
        /// called from EVERY exit path: both FinishConsume outcomes, the consume
        /// hard-timeout, ResetIntoxication, and (via that) the abort handler.
        /// </summary>
        private void ClearConsumeProp()
        {
            try
            {
                if (intoxProp != null && intoxProp.Exists()) intoxProp.Delete();
            }
            catch { }
            intoxProp = null;
            ClearConsumeProp2();
        }

        private void ClearConsumeProp2()
        {
            try
            {
                if (intoxProp2 != null && intoxProp2.Exists()) intoxProp2.Delete();
            }
            catch { }
            intoxProp2 = null;
        }

        /// <summary>
        /// Puts the weapon back. Vanilla forces weapon_unarmed for the whole
        /// sequence — a drawn weapon occupies the same hand the prop attaches to,
        /// and the safehouse clips were authored unarmed.
        /// </summary>
        private void RestoreConsumeWeapon()
        {
            if (!intoxWeaponStashed) return;
            intoxWeaponStashed = false;
            try
            {
                Ped pc = Game.Player.Character;
                if (pc != null && pc.Exists() && intoxPrevWeapon != WeaponHash.Unarmed)
                    Function.Call(Hash.SET_CURRENT_PED_WEAPON, pc, (uint)intoxPrevWeapon, true);
            }
            catch { }
            intoxPrevWeapon = WeaponHash.Unarmed;
        }

        private void StopConsumeAnim()
        {
            try
            {
                Ped pc = Game.Player.Character;
                if (pc != null && pc.Exists())
                {
                    if (intoxSyncScene >= 0)
                    {
                        // STOP_ANIM_TASK only ends a TASK_PLAY_ANIM. A synchronized
                        // scene ignores it completely — which is exactly what left
                        // the player locked in the animation while the mod happily
                        // announced the consume had finished. Only CLEAR_PED_TASKS
                        // ends a scene task.
                        intoxLastSyncScene = intoxSyncScene;
                        intoxReleaseVerifyTicks = ModClock.Ticks + 7000000L;   // 700 ms
                        // Run the scene out to its end first, the way vanilla aborts
                        // one, so the ped leaves from the clip's final pose instead
                        // of being yanked out of whatever frame it was on.
                        try
                        {
                            if (Function.Call<bool>(Hash.IS_SYNCHRONIZED_SCENE_RUNNING, intoxSyncScene))
                                Function.Call(Hash.SET_SYNCHRONIZED_SCENE_PHASE, intoxSyncScene, 1f);
                        }
                        catch { }
                        Function.Call(Hash.CLEAR_PED_TASKS, pc);
                    }
                    else if (intoxAnimDict != null)
                    {
                        Function.Call(Hash.STOP_ANIM_TASK, pc, intoxAnimDict, intoxAnimClip, -4f);
                    }
                }
            }
            catch { }
            intoxAnimDict = null;
            intoxAnimClip = null;
            intoxAnimPending = false;
            intoxAnimRequestedTicks = 0;
            // The scene handle is fire-and-forget: dropping the reference is enough,
            // the engine reaps it once no entity is bound. Clearing the player's
            // task above is what actually ends it.
            intoxSyncScene = -1;
            intoxSceneConfirmed = false;
            // iter-51: the outro leg is part of the same task and the CLEAR_PED_TASKS
            // above ends it too, so this only drops the bookkeeping. Leaving
            // intoxOutroActive set would make the next consume's tick believe it was
            // already in its outro and finish the moment the enter clip started.
            intoxOutroActive = false;
            intoxOutroScene = -1;
            intoxOutroEndTicks = 0;
        }

        /// <summary>
        /// Polls the AMBIENT audio bank the vanilla safehouse sequence loads. Banks
        /// stream asynchronously, so a single-frame false is not a failure — this
        /// polls for the duration of the consume and reports the outcome once.
        /// ok=0 means that bank name is wrong or unavailable, which is the one thing
        /// that keeps the foley silent even when the animation is confirmed playing.
        /// </summary>
        private void TickConsumeBank()
        {
            if (intoxBankName == null || intoxBankLoaded) return;
            bool ok = false;
            // REQUEST_AMBIENT_AUDIO_BANK = 0xFE02FFBED8CA9D99. p2 is always -1.
            try { ok = Function.Call<bool>(Hash.REQUEST_AMBIENT_AUDIO_BANK, intoxBankName, false, -1); }
            catch { }
            if (ok)
            {
                intoxBankLoaded = true;
                IntoxLog("intox-bank: name=" + intoxBankName + " ok=1");
            }
        }

        private void ReleaseConsumeBank()
        {
            if (intoxBankName == null) return;
            if (!intoxBankLoaded) IntoxLog("intox-bank: name=" + intoxBankName + " ok=0");
            // RELEASE_AMBIENT_AUDIO_BANK takes no name — it releases the script's
            // ambient bank slot, exactly as ob_mr_raspberry_jam.c does on teardown.
            try { Function.Call(Hash.RELEASE_AMBIENT_AUDIO_BANK); } catch { }
            intoxBankName = null;
            intoxBankLoaded = false;
        }

        /// <summary>
        /// iter-51: does this clip exist in this (already-streamed) dictionary?
        ///
        /// GET_ANIM_DURATION returns 0 for a name that is not in the dict, which is
        /// the only cheap way to tell a real clip from a typo before playing it.
        /// Every clip in the catalogue was checked against the game's own animation
        /// dump when it was written, but the check stays in the runtime path because
        /// a missing outro must degrade to "no outro" rather than to a player frozen
        /// mid-consume waiting for a scene that will never reach phase 0.95.
        /// Returns the duration in ms, or 0.
        /// </summary>
        private int ConsumeClipMs(string dict, string clip)
        {
            if (dict == null || clip == null) return 0;
            try
            {
                float secs = Function.Call<float>(Hash.GET_ANIM_DURATION, dict, clip);
                if (secs > 0f && secs < 120f) return (int)(secs * 1000f);
            }
            catch { }
            return 0;
        }

        /// <summary>
        /// iter-51: play the outro, if this row has one.
        ///
        /// The enter clip has just reached phase 0.95. Vanilla follows it with a
        /// second synchronized scene carrying the exit clips — the player sets the
        /// glass down, stubs the cigar out, stands up — and picks WHICH exit by how
        /// drunk the character is. Both halves are reproduced here.
        ///
        /// Returns false when there is nothing to play (no outro in the table, the
        /// clip is not really in the dict, the consume happened in a vehicle where
        /// there is no scene to chain from, or the scene refused). In every one of
        /// those cases the caller finishes exactly the way it did before iter-51, so
        /// a bad row costs the outro and nothing else.
        /// </summary>
        private bool TryStartConsumeOutro(Ped player, int kind, string enterWhy)
        {
            if (intoxOutroActive) return false;
            if (kind < 0 || kind >= CONSUMABLES.Length) return false;
            // No scene to chain from: the in-vehicle path and the scenario fallback
            // both play a plain anim, and a synchronized scene would fight the
            // driving task it is layered over.
            if (intoxSyncScene < 0 || intoxConsumeInVehicle) return false;
            if (player == null || !player.Exists()) return false;

            Consumable c = CONSUMABLES[kind];
            string clip = Consumable.Pick(c.Exit, intoxStage);
            if (clip == null) return false;

            int outroMs = ConsumeClipMs(c.Dict, clip);
            if (outroMs <= 0)
            {
                IntoxLog("intox-clip-missing: kind=" + kind + " dict=" + c.Dict
                    + " clip=" + clip + " role=exit stage=" + intoxStage);
                return false;
            }

            string propClip = Consumable.Pick(c.ExitProp, intoxStage);
            int propAnimOk = -1, prop2AnimOk = -1;
            bool synced = false;
            try
            {
                GTA.Math.Vector3 p = player.Position;
                intoxOutroScene = Function.Call<int>(Hash.CREATE_SYNCHRONIZED_SCENE,
                    p.X, p.Y, p.Z, 0f, 0f, player.Heading, 2);
                Function.Call(Hash.SET_SYNCHRONIZED_SCENE_LOOPED, intoxOutroScene, false);
                Function.Call(Hash.SET_SYNCHRONIZED_SCENE_HOLD_LAST_FRAME, intoxOutroScene, false);
                Function.Call(Hash.TASK_SYNCHRONIZED_SCENE, player, intoxOutroScene,
                    c.Dict, clip, 4f, -2f, INTOX_SCENE_FLAGS, 0, 1000f, 0);
                if (intoxProp != null && intoxProp.Exists() && propClip != null
                    && ConsumeClipMs(c.Dict, propClip) > 0)
                {
                    propAnimOk = Function.Call<bool>(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, intoxProp,
                        intoxOutroScene, propClip, c.Dict, 4f, -2f, 0, 1000f) ? 1 : 0;
                }
                if (intoxProp2 != null && intoxProp2.Exists() && c.ExitProp2 != null
                    && ConsumeClipMs(c.Dict, c.ExitProp2) > 0)
                {
                    prop2AnimOk = Function.Call<bool>(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, intoxProp2,
                        intoxOutroScene, c.ExitProp2, c.Dict, 4f, -2f, 0, 1000f) ? 1 : 0;
                }
                synced = Function.Call<bool>(Hash.IS_SYNCHRONIZED_SCENE_RUNNING, intoxOutroScene);
            }
            catch { synced = false; }

            if (!synced)
            {
                intoxOutroScene = -1;
                IntoxLog("intox-exit: kind=" + kind + " clip=" + clip + " ok=0 why=scene-refused");
                return false;
            }

            // The enter scene is finished with. Hand the phase questions in the tick
            // over to the outro scene, and push BOTH wall-clock backstops out past
            // the outro so the timer cannot cut it off partway — the same mistake
            // the hand-picked table durations used to make on the enter clip.
            intoxSyncScene = intoxOutroScene;
            intoxSceneConfirmed = false;
            intoxOutroActive = true;
            intoxAnimClip = clip;
            long now = ModClock.Ticks;
            intoxOutroEndTicks = now + (outroMs + 1500) * 10000L;
            if (intoxConsumeEndTicks < intoxOutroEndTicks) intoxConsumeEndTicks = intoxOutroEndTicks;
            if (intoxConsumeHardTicks < intoxOutroEndTicks + 30000000L)
                intoxConsumeHardTicks = intoxOutroEndTicks + 30000000L;

            IntoxLog("intox-exit: kind=" + kind + " clip=" + clip
                + " propClip=" + (propClip ?? "-")
                + " stage=" + intoxStage + " animMs=" + outroMs
                + " propAnim=" + propAnimOk + " prop2Anim=" + prop2AnimOk
                + " after=" + enterWhy + " ok=1");
            return true;
        }

        /// <summary>
        /// HAS_ANIM_DICT_LOADED only proves the DICT streamed — a wrong CLIP name
        /// inside a real dict makes TASK_PLAY_ANIM a silent no-op that looks
        /// identical in the log. This settles it.
        /// </summary>
        private void TickConsumeAnimVerify(Ped player)
        {
            if (intoxAnimVerified || intoxAnimDict == null) return;
            if (ModClock.Ticks - intoxAnimStartedTicks < 5000000L) return;   // 500 ms
            intoxAnimVerified = true;
            bool playing = false;
            bool sceneRunning = false;
            try
            {
                playing = Function.Call<bool>(Hash.IS_ENTITY_PLAYING_ANIM,
                    player, intoxAnimDict, intoxAnimClip, 3);
                if (intoxSyncScene >= 0)
                    sceneRunning = Function.Call<bool>(Hash.IS_SYNCHRONIZED_SCENE_RUNNING, intoxSyncScene);
            }
            catch { }
            IntoxLog("intox-anim-playing: dict=" + intoxAnimDict
                + " clip=" + intoxAnimClip + " playing=" + (playing ? 1 : 0)
                + " scene=" + (sceneRunning ? 1 : 0));
        }

        /// <summary>
        /// Starts the consumption animation once its dict has streamed in. The foley
        /// you hear at a safehouse or in the club rides on the animation's embedded
        /// audio events, which is why this drives a real anim rather than the ambient
        /// scenario iter-44 used — that produced no reliable sound, and nothing at
        /// all in a vehicle. Both dict spellings are probed; if neither streams it
        /// degrades to that scenario, and the winning path is always logged.
        /// </summary>
        private void TickConsumeAnim(Ped player)
        {
            if (!intoxAnimPending || intoxConsuming < 0) return;
            int kind = intoxConsuming;
            // Where the consume STARTED, not where the player is now: a mid-consume
            // vehicle transition is already an interrupt, and re-sampling here would
            // let a dict be requested for one body state and played in the other.
            bool inVehicle = intoxConsumeInVehicle;

            string dict = CONSUMABLES[kind].Dict;
            bool loaded = false;
            try
            {
                Function.Call(Hash.REQUEST_ANIM_DICT, dict);
                loaded = Function.Call<bool>(Hash.HAS_ANIM_DICT_LOADED, dict);
            }
            catch { }

            // Wait for the PROP MODELS as well, not just the dict. The props are not
            // decoration: the bottle-open and bong-bubble foley rides on the prop
            // clips, and once the scene has started TickConsumeProp deliberately
            // refuses to touch a prop the scene owns — so a model that was still
            // streaming at scene-start was lost for the whole consume, silently.
            // 2026-08-09 caught exactly that: the first bong of the session logged
            // prop2=0 and the two after it, with the model now resident, logged
            // prop2=1. Vanilla chains the same way (its own start gate requires the
            // dict AND the assets AND the bank before it will begin).
            bool propsReady = ConsumePropsReady(kind);
            bool timedOut = ModClock.Ticks - intoxAnimRequestedTicks > 30000000L;   // 3 s

            if (!loaded)
            {
                if (!timedOut) return;
                intoxAnimPending = false;
                IntoxLog("intox-anim-fail: kind=" + kind + " veh=" + (inVehicle ? 1 : 0)
                    + " dict=" + dict);
                if (!inVehicle) StartConsumeScenario(player, kind);
                return;
            }
            // Dict is in but a prop is not: keep waiting until the same deadline,
            // then start anyway. A late prop costs foley; no animation at all costs
            // the whole interaction.
            if (!propsReady && !timedOut) return;

            intoxAnimPending = false;
            string clip = CONSUMABLES[kind].Clip;
            AttachConsumeProp(player, kind);

            // On foot, reproduce the safehouse sequence exactly: a synchronized
            // scene carrying the player clip AND the prop clip from the same dict.
            // The prop half is not cosmetic — the bottle-open and bong-bubble foley
            // lives on the PROP animation, so TASK_PLAY_ANIM alone cannot produce it.
            bool synced = false;
            int propAnimOk = -1, prop2AnimOk = -1;
            if (!inVehicle)
            {
                try
                {
                    player.Task.ClearAll();
                    GTA.Math.Vector3 p = player.Position;
                    intoxSyncScene = Function.Call<int>(Hash.CREATE_SYNCHRONIZED_SCENE,
                        p.X, p.Y, p.Z, 0f, 0f, player.Heading, 2);
                    // A scene that loops or holds its last frame never gives the
                    // player back. Both off, explicitly, before anyone is bound.
                    Function.Call(Hash.SET_SYNCHRONIZED_SCENE_LOOPED, intoxSyncScene, false);
                    Function.Call(Hash.SET_SYNCHRONIZED_SCENE_HOLD_LAST_FRAME, intoxSyncScene, false);
                    // Blend 4f and flags 5 are vanilla's, verbatim. Flags were 0,
                    // which drops both SYNCED_SCENE_USE_PHYSICS (1) and
                    // SYNCED_SCENE_DONT_INTERRUPT (4) — the second is what stops an
                    // ambient event nudging the player out of the scene partway
                    // through, which reads as an animation that stopped early.
                    Function.Call(Hash.TASK_SYNCHRONIZED_SCENE, player, intoxSyncScene,
                        dict, clip, 4f, -2f, INTOX_SCENE_FLAGS, 0, 1000f, 0);
                    if (intoxProp != null && intoxProp.Exists() && CONSUMABLES[kind].PropClip != null)
                    {
                        // Hand-attachment and a synchronized scene fight over the
                        // prop's transform; the scene owns it from here.
                        try { Function.Call(Hash.DETACH_ENTITY, intoxProp, true, true); } catch { }
                        // The BOOL return was being discarded. This is the call that
                        // carries the drink/smoke foley, so its failure is the single
                        // most valuable thing in this whole block to know about.
                        propAnimOk = Function.Call<bool>(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, intoxProp,
                            intoxSyncScene, CONSUMABLES[kind].PropClip, dict, 4f, -2f, 0, 1000f) ? 1 : 0;
                    }
                    // The lighter / bottle / cap. Third participant in the same
                    // scene, and the half that carries the striking and opening
                    // sounds — vanilla plays all three together or none of them.
                    if (intoxProp2 != null && intoxProp2.Exists() && CONSUMABLES[kind].Prop2Clip != null)
                    {
                        prop2AnimOk = Function.Call<bool>(Hash.PLAY_SYNCHRONIZED_ENTITY_ANIM, intoxProp2,
                            intoxSyncScene, CONSUMABLES[kind].Prop2Clip, dict, 4f, -2f, 0, 1000f) ? 1 : 0;
                    }
                    synced = Function.Call<bool>(Hash.IS_SYNCHRONIZED_SCENE_RUNNING, intoxSyncScene);
                }
                catch { }
            }

            // How long the clip ACTUALLY is. GET_ANIM_DURATION returns seconds and
            // needs the dict resident, which it is by here. This replaces the
            // hand-picked Ms as the length of the consume — those constants were
            // guesses, and every one of them was shorter than the safehouse clip it
            // was supposed to cover, so the sequence was being cut off partway
            // through while the mod announced it finished. The table value survives
            // as a FLOOR so a short or unmeasurable clip still doses at a sane pace.
            int animMs = ConsumeClipMs(dict, clip);
            // iter-51: a zero here means the DICT streamed but the CLIP is not in it
            // — a typo, or a name from the wrong game build. That used to be
            // invisible: the consume ran on the table's guessed duration with the
            // player doing nothing, and the only hint was intox-anim-playing
            // reporting playing=0 half a second later. Name it at the source.
            if (animMs <= 0)
                IntoxLog("intox-clip-missing: kind=" + kind + " dict=" + dict
                    + " clip=" + clip + " role=enter stage=" + intoxStage);
            int planMs = Math.Max(CONSUMABLES[kind].Ms, animMs);

            if (!synced)
            {
                // In a vehicle, or if the scene refused: plain anim. In-car uses
                // UPPERBODY|SECONDARY (48) and NO ClearAll so it layers over the
                // driving task instead of cancelling it.
                intoxSyncScene = -1;
                // Nothing drives the second prop without a scene, and it was never
                // hand-attached, so it would hang in mid-air. Bin it.
                ClearConsumeProp2();
                try
                {
                    // Duration -1, not Ms: -1 plays the clip to its natural end.
                    // Passing Ms told the engine to truncate the animation at the
                    // guessed length, so even the in-car path could not finish a
                    // clip that ran longer. This function still owns when the
                    // consume ends — it just no longer amputates the animation.
                    //
                    // AF_LOOPING (1) only when the consume outlasts the clip, which
                    // is the idle/"loop" rows: those clips are a fraction of a second
                    // long and without this the player's hands stop moving seconds
                    // before the item is reported eaten. Never on a clip long enough
                    // to cover the consume, where looping would restart it instead
                    // of letting it end.
                    int flags = inVehicle ? 48 : 0;
                    if (animMs > 0 && planMs > animMs + 500) flags |= 1;
                    Function.Call(Hash.TASK_PLAY_ANIM, player, dict, clip,
                        4f, -4f, -1, flags,
                        0f, false, false, false);
                }
                catch { }
            }

            intoxAnimDict = dict;
            intoxAnimClip = clip;
            intoxAnimStartedTicks = ModClock.Ticks;
            intoxAnimVerified = false;
            intoxSceneConfirmed = false;

            // THE clock for the consume, started here — when the animation actually
            // begins — and not in ConsumeItem. It used to start at the menu press,
            // so everything the dict spent streaming (up to 3 s) was billed to the
            // animation's own playing time.
            intoxConsumePlanMs = planMs;
            intoxConsumeStartTicks = ModClock.Ticks;
            intoxConsumeEndTicks = intoxConsumeStartTicks + intoxConsumePlanMs * 10000L;
            intoxConsumeHardTicks = intoxConsumeEndTicks + 30000000L;   // +3 s

            IntoxLog("intox-anim: kind=" + kind + " veh=" + (inVehicle ? 1 : 0)
                + " dict=" + dict + " clip=" + clip + " synced=" + (synced ? 1 : 0)
                + " prop=" + (intoxProp != null ? 1 : 0)
                + " prop2=" + (intoxProp2 != null ? 1 : 0)
                + " propAnim=" + propAnimOk + " prop2Anim=" + prop2AnimOk
                + " animMs=" + animMs + " tableMs=" + CONSUMABLES[kind].Ms
                + " planMs=" + intoxConsumePlanMs
                + " waitMs=" + (int)((ModClock.Ticks - intoxAnimRequestedTicks) / 10000L));
        }

        private void StartConsumeScenario(Ped player, int kind)
        {
            try
            {
                player.Task.ClearAll();
                // WORLD_HUMAN_SMOKING_POT covers both joint and bong: there is no
                // vanilla bong scenario outside the prop in Franklin's house, and
                // the bong's distinguishing feature is its dose, not its animation.
                string scenario = CONSUMABLES[kind].Smoke
                    ? "WORLD_HUMAN_SMOKING_POT" : "WORLD_HUMAN_DRINKING";
                Function.Call(Hash.TASK_START_SCENARIO_IN_PLACE, player, scenario, 0, true);
                intoxConsumeScenario = true;
            }
            catch { }
        }

        /// <summary>
        /// Retries the prop attach for as long as the consume runs — the model may
        /// still be streaming when the animation starts. Purely cosmetic, so it
        /// never gates or delays the animation, which is what carries the sound.
        /// </summary>
        private void TickConsumeProp(Ped player)
        {
            // Never while a synchronized scene is driving the prop — the scene owns
            // its transform, and re-attaching to the hand would fight it.
            if (intoxConsuming < 0 || intoxProp != null || intoxAnimPending) return;
            if (intoxSyncScene >= 0) return;
            if (intoxAnimDict == null && !intoxConsumeScenario) return;
            AttachConsumeProp(player, intoxConsuming);
            // Same reason as the !synced path: with no scene to drive it, the
            // second prop has nothing holding it up.
            ClearConsumeProp2();
        }

        /// <summary>
        /// Puts the item in the player's hand. Silent on failure by design: it is
        /// called every frame of the consume, so a not-yet-streamed model must not
        /// log. FinishConsume reports the outcome once instead.
        /// </summary>
        private void AttachConsumeProp(Ped player, int kind)
        {
            ClearConsumeProp();
            Consumable c = CONSUMABLES[kind];
            if (c.Prop == null) return;
            try
            {
                intoxProp = CreateHeldProp(player, c.Prop, true);
                if (intoxProp == null) return;
                intoxPropAttached = true;
                // The second prop is never hand-attached: it only exists to be
                // driven by the synchronized scene, which owns its transform. If the
                // scene does not start, TickConsumeAnim deletes it again rather than
                // leave a lighter floating at the player's feet.
                if (c.Prop2 != null) intoxProp2 = CreateHeldProp(player, c.Prop2, false);
            }
            catch { ClearConsumeProp(); }
        }

        /// <summary>
        /// True once every model this consumable needs is resident, so the
        /// synchronized scene can bind all of its participants at once. Requests
        /// anything still missing on the way past — this is polled, never blocking.
        /// </summary>
        private bool ConsumePropsReady(int kind)
        {
            Consumable c = CONSUMABLES[kind];
            bool ready = true;
            try
            {
                if (c.Prop != null)
                {
                    Model m = new Model(c.Prop);
                    if (!m.IsLoaded) { m.Request(); ready = false; }
                }
                if (c.Prop2 != null)
                {
                    Model m2 = new Model(c.Prop2);
                    if (!m2.IsLoaded) { m2.Request(); ready = false; }
                }
            }
            catch { return true; }   // never let a model probe stall the animation
            return ready;
        }

        /// <summary>
        /// Creates one prop, optionally attached to the right-hand prop bone.
        /// Silent on a not-yet-streamed model: this runs every frame of the consume,
        /// so failure must not log. FinishConsume reports the outcome once instead.
        /// </summary>
        private Prop CreateHeldProp(Ped player, string model, bool attach)
        {
            try
            {
                Model m = new Model(model);
                if (!m.IsLoaded)
                {
                    // Non-blocking: never Request(timeout) from inside a tick.
                    m.Request();
                    return null;
                }
                Prop p = World.CreateProp(m, player.Position, false, false);
                m.MarkAsNoLongerNeeded();
                if (p == null || !p.Exists()) return null;
                if (attach)
                {
                    int bone = Function.Call<int>(Hash.GET_PED_BONE_INDEX, player, INTOX_BONE_PH_R_HAND);
                    Function.Call(Hash.ATTACH_ENTITY_TO_ENTITY, p, player, bone,
                        0f, 0f, 0f, 0f, 0f, 0f, false, false, false, false, 2, true);
                }
                return p;
            }
            catch { return null; }
        }

        private void ConsumeItem(int kind)
        {
            if (getSetting("intoxEnabled") != 1)
            {
                Speech.Ambient("Drinking and smoking effects are turned off in settings.");
                return;
            }
            Ped player = Game.Player.Character;
            if (player == null || !player.Exists()) return;

            // Every refusal is spoken. Silence in response to a menu selection is
            // indistinguishable from a broken mod when you cannot see the screen.
            //
            // Re-selecting mid-consume CANCELS instead of refusing. Now that a
            // consume runs for the animation's real length rather than a 4-6 s
            // guess, some of them are genuinely long, and a synchronized scene
            // blocks the sprint/movement interrupts that used to be the only way
            // out — so without this the player would have no way to stop one.
            // Deliberately the same key that started it: no new binding to learn.
            if (intoxConsuming >= 0)
            {
                // ...but not in the first 1.5 s. A blind player who double-taps the
                // activate key must not have their drink cancelled by the second
                // tap; past that window a re-press is unambiguously deliberate.
                if (ModClock.Ticks - intoxLastConsumeTicks < 15000000L)
                { Speech.Ambient("Still finishing that."); return; }
                FinishConsume(true, "cancel");
                Speech.Ambient("Stopped.");
                return;
            }
            if (intoxBlackout) { Speech.Ambient("You are blacked out."); return; }
            if (ModClock.Ticks - intoxLastConsumeTicks < 30000000L)   // 3 s
            { Speech.Ambient("Give it a second."); return; }

            bool inVehicle = false;
            try { inVehicle = player.IsInVehicle(); } catch { }
            try
            {
                if (player.IsInCombat || player.IsRagdoll || player.IsSwimming
                    || player.IsInAir || player.IsClimbing)
                { Speech.Ambient("Not right now."); return; }
            }
            catch { }
            if (!CONSUMABLES[kind].CarOk && inVehicle)
            { Speech.Ambient("You can't do that in a car."); return; }

            intoxConsuming = kind;
            intoxLastConsumeTicks = ModClock.Ticks;
            // PROVISIONAL only. TickConsumeAnim overwrites both the moment the
            // animation actually starts, with the clip's measured length; these
            // values exist so a consume whose animation never starts at all still
            // completes instead of hanging. The 3 s is the anim-streaming deadline,
            // so the floor is "streaming window + the table's own duration".
            intoxConsumePlanMs = CONSUMABLES[kind].Ms;
            intoxConsumeStartTicks = ModClock.Ticks;
            intoxConsumeEndTicks = ModClock.Ticks + (3000 + intoxConsumePlanMs) * 10000L;
            // Hard force-clear: a scenario captures movement, and an unannounced,
            // unrecoverable loss of movement is a bug for this audience.
            intoxConsumeHardTicks = intoxConsumeEndTicks + 30000000L;   // +3 s
            intoxConsumeScenario = false;
            intoxConsumeInVehicle = inVehicle;
            intoxSceneConfirmed = false;

            // Unarmed for the duration, the way vanilla plays these. A drawn weapon
            // occupies the same right hand the prop attaches to, so the bottle ends
            // up inside the gun and the clip fights the weapon's grip pose.
            if (!inVehicle)
            {
                try
                {
                    intoxPrevWeapon = player.Weapons.Current.Hash;
                    if (intoxPrevWeapon != WeaponHash.Unarmed)
                    {
                        Function.Call(Hash.SET_CURRENT_PED_WEAPON, player, (uint)WeaponHash.Unarmed, true);
                        intoxWeaponStashed = true;
                    }
                }
                catch { intoxWeaponStashed = false; }
            }

            // REQUEST_ANIM_DICT is async, so the anim cannot start here. Kick the
            // request off and let TickIntoxication start it the frame it lands —
            // the same request/poll/timeout shape ApplyIntoxClipset already uses.
            StopConsumeAnim();
            ClearConsumeProp();
            intoxAnimPending = true;
            intoxAnimRequestedTicks = ModClock.Ticks;
            intoxPropAttached = false;
            intoxAnimVerified = false;
            try { Function.Call(Hash.REQUEST_ANIM_DICT, CONSUMABLES[kind].Dict); } catch { }
            // The ambient audio bank must be resident BEFORE the anim's audio events
            // fire, so it is requested here, in the same frame as the dict.
            ReleaseConsumeBank();
            intoxBankName = CONSUMABLES[kind].Bank;
            if (intoxBankName != null)
            {
                try { Function.Call(Hash.REQUEST_AMBIENT_AUDIO_BANK, intoxBankName, false, -1); } catch { }
            }
            // ...and the AUDIO SCENE, which is the other half and the one that was
            // missing entirely. The bank makes the sounds resident; the scene is
            // what routes them to the mix. Loading a bank with no scene active is
            // why 2026-08-09 logged bank ok=1, scene running and the animation
            // confirmed playing, and still produced no drinking or smoking sound.
            StartConsumeAudioScene(kind);
            // Kick the prop model off now so it has the anim's streaming window to
            // arrive; TickConsumeProp retries the attach and never waits on it.
            if (CONSUMABLES[kind].Prop != null)
            {
                try { new Model(CONSUMABLES[kind].Prop).Request(); } catch { }
            }

            Speech.Info(CONSUMABLES[kind].Action);
        }

        /// <summary>
        /// Milliseconds the ANIMATION has been running, or the whole consume if it
        /// never started. On foot the drive-assist frame counter does not advance,
        /// so every intox event stamps [F0] and the log carries no other clock —
        /// without this the 2026-08-09 session could not be timed at all, which is
        /// why "the animation gets cut off" had to be reasoned out from the
        /// constants instead of read off the log.
        /// </summary>
        private int IntoxConsumeElapsedMs()
        {
            if (intoxConsumeStartTicks == 0) return 0;
            return (int)((ModClock.Ticks - intoxConsumeStartTicks) / 10000L);
        }

        private void FinishConsume(bool interrupted, string why = "timer")
        {
            int kind = intoxConsuming;
            intoxConsuming = -1;
            if (kind < 0) return;

            int elapsed = IntoxConsumeElapsedMs();
            int phasePct = -1;
            try
            {
                if (intoxSyncScene >= 0)
                    phasePct = (int)(Function.Call<float>(Hash.GET_SYNCHRONIZED_SCENE_PHASE, intoxSyncScene) * 100f);
            }
            catch { }
            IntoxLog("intox-done: kind=" + kind + " why=" + why
                + " interrupted=" + (interrupted ? 1 : 0)
                + " ms=" + elapsed + " planMs=" + intoxConsumePlanMs
                + " phase=" + phasePct
                + " anim=" + (intoxAnimDict != null ? 1 : 0));

            StopConsumeAnim();
            ClearConsumeProp();
            ReleaseConsumeBank();
            StopConsumeAudioScene();
            RestoreConsumeWeapon();
            intoxConsumeStartTicks = 0;
            if (intoxConsumeScenario)
            {
                // Only clear if still on foot. The commonest interruption is
                // climbing into a car, and clearing tasks then cancels the entry
                // animation — leaving the player standing next to a door they
                // thought they were getting into, with no idea why.
                try
                {
                    Ped pc = Game.Player.Character;
                    if (pc != null && pc.Exists() && !pc.IsInVehicle())
                        Function.Call(Hash.CLEAR_PED_TASKS, pc);
                }
                catch { }
                intoxConsumeScenario = false;
            }
            float share = interrupted ? 0.5f : 1f;

            // Vanilla mode: hand the drink to the game's own drunk system instead of
            // this mod's meters. Deliberately NO partial dose on interrupt — vanilla
            // has no concept of half a drink, and the whole point of this mode is to
            // stop superimposing our model. Falls through to our own model only if
            // the bridge could not be verified.
            if (getSetting("intoxVanillaOnly") == 1 && (CONSUMABLES[kind].Drinks > 0f || CONSUMABLES[kind].Hits > 0f))
            {
                if (TriggerVanillaDrunk(kind))
                {
                    IntoxLog("intox-dose: kind=" + kind + " interrupted=" + (interrupted ? 1 : 0)
                        + " prop=" + (intoxPropAttached ? 1 : 0) + " vanilla=1");
                    // "cancel" is the player's own re-selection, and ConsumeItem
                    // already speaks "Stopped." for it — saying "Interrupted." here
                    // too would report their deliberate action back at them twice.
                    if (interrupted) { if (why != "cancel") Speech.Info("Interrupted."); }
                    else Speech.Info(CONSUMABLES[kind].Name + " finished. "
                        + intoxVanillaDrinks + (intoxVanillaDrinks == 1 ? " drink." : " drinks."));
                    return;
                }
                Speech.Info("Falling back to this mod's own drunkenness.");
            }

            intoxDrinks = Math.Min(20f, intoxDrinks + CONSUMABLES[kind].Drinks * share);
            intoxHits = Math.Min(20f, intoxHits + CONSUMABLES[kind].Hits * share);
            IntoxLog("intox-dose: kind=" + kind + " interrupted=" + (interrupted ? 1 : 0)
                + " prop=" + (intoxPropAttached ? 1 : 0)
                + " drinks=" + intoxDrinks.ToString("0.##")
                + " hits=" + intoxHits.ToString("0.##"));
            if (interrupted) { if (why != "cancel") Speech.Info("Interrupted."); }
            else Speech.Info(CONSUMABLES[kind].Name + " finished.");
        }

        private void TickIntoxication()
        {
            Ped player = Game.Player.Character;
            if (player == null || !player.Exists()) return;

            // Dead-man: the suspend latch must be self-healing. It is the one thing
            // standing between a blind driver and no navigation assistance.
            if (intoxAssistSuspend && intoxStage < 3) SetIntoxAssistSuspend(false, "deadman");

            // ---- release watchdog ----
            // Losing control with no way to get it back is the worst failure this
            // feature can produce, and iter-45f shipped exactly that. Never assume
            // the teardown worked: verify, and escalate if it did not. Deliberately
            // ABOVE the intoxEnabled gate — switching the feature off mid-consume
            // must not strand the player inside a scene.
            if (intoxReleaseVerifyTicks != 0 && ModClock.Ticks >= intoxReleaseVerifyTicks)
            {
                intoxReleaseVerifyTicks = 0;
                bool stillRunning = false;
                try
                {
                    if (intoxLastSyncScene >= 0)
                        stillRunning = Function.Call<bool>(Hash.IS_SYNCHRONIZED_SCENE_RUNNING, intoxLastSyncScene);
                }
                catch { }
                if (stillRunning)
                {
                    IntoxLog("intox-anim-stuck: scene=" + intoxLastSyncScene);
                    try { Function.Call(Hash.CLEAR_PED_TASKS_IMMEDIATELY, player); } catch { }
                    Speech.Critical("That animation stuck. Releasing you.");
                }
                intoxLastSyncScene = -1;
            }

            if (getSetting("intoxEnabled") != 1)
            {
                if (intoxStage != 0 || intoxDrinks > 0f || intoxHits > 0f) ResetIntoxication("disabled");
                return;
            }

            // Vanilla-only mode: consumption still runs (that is what produces the
            // safehouse foley), but this mod applies no drunkenness presentation of
            // its own, leaving the field to the game's own drunk_controller.
            bool vanillaOnly = getSetting("intoxVanillaOnly") == 1;

            long now = ModClock.Ticks;
            float dt = intoxLastTickTicks > 0 ? (now - intoxLastTickTicks) / 10000000f : 0f;
            intoxLastTickTicks = now;
            if (dt > 0.5f) dt = 0.5f;
            if (dt < 0f) dt = 0f;

            // ---- consume timer ----
            if (intoxConsuming >= 0)
            {
                TickConsumeBank();
                TickConsumeAnim(player);
                TickConsumeAnimVerify(player);
                TickConsumeProp(player);
                bool interrupted = false;
                try
                {
                    // Crossing in or out of a vehicle always breaks the consume: the
                    // vehicle-entry task cancels an on-foot animation, and an in-car
                    // secondary anim has nothing to layer over once you are out.
                    if (player.IsInVehicle() != intoxConsumeInVehicle) interrupted = true;
                    else if (player.IsRagdoll || player.IsInCombat) interrupted = true;
                    else if (!intoxConsumeInVehicle && player.IsSprinting) interrupted = true;
                }
                catch { }

                // The ENGINE decides when the animation is finished, not a clock.
                // A synchronized scene reports its own progress, so ask it — this is
                // exactly how the vanilla consumable scripts sequence these (run
                // until phase 0.95, then tear down). The wall clock below survives
                // only as a backstop for the paths that have no phase to read.
                bool animDone = false;
                string why = "timer";
                if (intoxSyncScene >= 0)
                {
                    try
                    {
                        bool running = Function.Call<bool>(Hash.IS_SYNCHRONIZED_SCENE_RUNNING, intoxSyncScene);
                        if (running)
                        {
                            intoxSceneConfirmed = true;
                            if (Function.Call<float>(Hash.GET_SYNCHRONIZED_SCENE_PHASE, intoxSyncScene)
                                >= INTOX_SCENE_DONE_PHASE)
                            { animDone = true; why = "phase"; }
                        }
                        else if (intoxSceneConfirmed)
                        {
                            // Ran, then stopped on its own — the clip ended, or
                            // something outside this mod took the player out of it.
                            // Either way the animation is over and pretending
                            // otherwise would hold the consume open for nothing.
                            animDone = true; why = "scene-end";
                        }
                    }
                    catch { }
                }

                // ---- iter-51: the OUTRO ----
                // If an outro is already running, the questions above are about the
                // OUTRO's scene, not the enter clip's — animDone here means the
                // outro finished, which is the real end of the consume.
                if (intoxOutroActive)
                {
                    if (interrupted) FinishConsume(true, "interrupt");
                    else if (animDone) FinishConsume(false, "outro-" + why);
                    else if (now >= intoxOutroEndTicks) FinishConsume(false, "outro-timer");
                }
                else if (interrupted) FinishConsume(true, "interrupt");
                else if (animDone)
                {
                    // The enter clip reached 0.95. Before iter-51 this was the end:
                    // the scene was snapped to phase 1 and the ped task-cleared, so
                    // the player never put the bottle down or stood back up. Try the
                    // outro; only finish immediately if there is not one to play.
                    if (!TryStartConsumeOutro(player, intoxConsuming, why))
                        FinishConsume(false, why);
                }
                else if (now >= intoxConsumeEndTicks) FinishConsume(false, "timer");
                else if (now >= intoxConsumeHardTicks) FinishConsume(false, "hard");
            }

            // ---- decay ----
            float mult = intoxBlackout ? INTOX_BLACKOUT_DECAY_MULT : 1f;
            if (intoxDrinks > 0f) intoxDrinks = Math.Max(0f, intoxDrinks - INTOX_DECAY_DRINKS * mult * dt / 60f);
            if (intoxHits > 0f) intoxHits = Math.Max(0f, intoxHits - INTOX_DECAY_HITS * mult * dt / 60f);

            // ---- stage ----
            int newStage = IntoxStageFor(IntoxImpairment(), intoxStage);
            if (newStage != intoxStage)
            {
                int from = intoxStage;
                intoxStage = newStage;
                intoxClipsetFailed = false;
                IntoxLog("intox-stage: from=" + from + " to=" + newStage
                    + " drinks=" + intoxDrinks.ToString("0.##")
                    + " hits=" + intoxHits.ToString("0.##"));
                AnnounceIntoxStage(from, newStage);
                // No SHAKE_GAMEPLAY_CAM kick here any more: ApplyIntoxVisuals arms
                // and scales it every frame, so a one-shot on the stage boundary
                // only fought the continuous ramp it now owns.
                if (newStage < 2) intoxCompensateSaid = false;
            }

            // ---- blackout overlay ----
            // Not a stage: the engine has no fourth drunk state. Trips only on
            // SUSTAINED stage 3, so a fast drinker cannot skip straight past Very
            // Drunk into it — the timer restarts the moment the stage falls back.
            if (intoxStage >= 3 && !vanillaOnly)
            {
                if (intoxStage3SinceTicks == 0) intoxStage3SinceTicks = now;
                if (!intoxBlackout && now - intoxStage3SinceTicks >= INTOX_BLACKOUT_AFTER)
                {
                    intoxBlackout = true;
                    IntoxLog("intox-blackout: on drinks=" + intoxDrinks.ToString("0.##"));
                    Speech.Critical("Blacking out.");
                }
            }
            else
            {
                intoxStage3SinceTicks = 0;
                if (intoxBlackout)
                {
                    intoxBlackout = false;
                    intoxPassedOutSaid = false;
                    IntoxLog("intox-blackout: off");
                    // Announced HERE rather than left to TickIntoxDriving: that
                    // function early-returns once the stage falls below 2, which
                    // would swallow the recovery line on a fast decay.
                    if (intoxBlackoutDriving)
                    {
                        intoxBlackoutDriving = false;
                        Speech.Critical("You are coming round. You have the wheel back.");
                    }
                    else Speech.Info("Coming round.");
                }
            }

            // ---- character-switch guard ----
            if (intoxAppliedToHandle != player.Handle)
            {
                intoxAppliedToHandle = player.Handle;
                intoxClipsetApplied = null;
                intoxClipsetWanted = null;
                intoxClipsetFailed = false;
            }

            // ---- effects ----
            try
            {
                Function.Call(Hash.SET_PED_IS_DRUNK, player, intoxStage > 0);
                Function.Call(Hash.SET_PED_CONFIG_FLAG, player, 100, intoxStage > 0);
            }
            catch { }

            if (vanillaOnly)
            {
                // Make the suppression VISIBLE. Applying nothing in silence is
                // indistinguishable from a broken feature — which is exactly how it
                // read on 2026-08-01: this setting was on, and a session of "the
                // reverb doesn't work at all" was really "the mod was told not to".
                // Our meters must not keep ticking underneath the vanilla system —
                // that is the "superimposed metabolism" this mode exists to remove.
                // The game owns the whole state now; we only report it.
                intoxDrinks = 0f;
                intoxHits = 0f;
                if (intoxSuppressLoggedStage != intoxVanillaDrinks)
                {
                    intoxSuppressLoggedStage = intoxVanillaDrinks;
                    int untilMs = 0;
                    try
                    {
                        if (!intoxVanillaFailed
                            && GlobalVariable.Get(VG_DRUNK_ENABLE).MemoryAddress != IntPtr.Zero)
                            untilMs = GlobalVariable.Get(VG_DRUNK_UNTIL).Read<int>()
                                      - Function.Call<int>(Hash.GET_GAME_TIMER);
                    }
                    catch { }
                    IntoxLog("intox-vanilla-active: drinks=" + intoxVanillaDrinks
                        + " remainMs=" + untilMs);
                }
                // Presentation goes back to the game. Everything this mod imposes —
                // clipset, timecycle, post-FX, camera shake, the audio override —
                // stands down, and anything already applied is cleared so it cannot
                // stick across the toggle.
                //
                // The meters are zeroed above, so there are no stage transitions to
                // announce in this mode and the comment that used to sit here
                // claiming "the METERS keep running" contradicted the code six lines
                // above it. Announcements are still owed to a blind player though,
                // so they come off the VANILLA state instead: FinishConsume speaks
                // the running drink count, and the end of the game's own drunk
                // window is spoken here. Without this, vanilla-only mode sobered up
                // in complete silence.
                ClearIntoxPresentation(player);
                bool vanillaActive = false;
                try
                {
                    if (!intoxVanillaFailed
                        && GlobalVariable.Get(VG_DRUNK_ENABLE).MemoryAddress != IntPtr.Zero)
                        vanillaActive = GlobalVariable.Get(VG_DRUNK_ENABLE).Read<int>() != 0
                            && GlobalVariable.Get(VG_DRUNK_UNTIL).Read<int>()
                               > Function.Call<int>(Hash.GET_GAME_TIMER);
                }
                catch { }
                if (intoxVanillaWasActive && !vanillaActive)
                {
                    intoxVanillaDrinks = 0;
                    IntoxLog("intox-vanilla: ended");
                    Speech.Info("Sober again.");
                }
                intoxVanillaWasActive = vanillaActive;
            }
            else
            {
                intoxSuppressLoggedStage = -1;
                intoxVanillaWasActive = false;
                ApplyIntoxClipset(player, intoxStage);
                ApplyIntoxVisuals(player, intoxStage);
                ApplyIntoxAudio(player, intoxStage);
            }

            TickIntoxStateLog(now, vanillaOnly);

            // ---- suspend drive assist from stage 3 ----
            if (getSetting("intoxDriveImpair") == 1 && !vanillaOnly)
            {
                if (intoxStage >= 3 && !intoxAssistSuspend) SetIntoxAssistSuspend(true, "stage" + intoxStage);
            }
            else if (intoxAssistSuspend) SetIntoxAssistSuspend(false, "gate-off");

            // ---- standing reminder while badly impaired ----
            if (intoxStage >= 3 && now - intoxLastReminderTicks > 600000000L)   // 60 s
            {
                intoxLastReminderTicks = now;
                Speech.Ambient(IntoxStageName(intoxStage) + ". Still.");
            }

            // ---- on-foot blackout ----
            if (intoxBlackout)
            {
                bool inVeh = false;
                try { inVeh = player.IsInVehicle(); } catch { }
                if (!inVeh)
                {
                    bool inWater = false;
                    try { inWater = player.IsSwimming || player.IsInWater || player.IsInAir; } catch { }
                    if (inWater)
                    {
                        // Ragdolling a blind player in water drowns them with no
                        // audible cue. Warn instead; never take their control away.
                        if (now - intoxBlackoutNagTicks > 50000000L)
                        {
                            intoxBlackoutNagTicks = now;
                            Speech.Critical("You are in the water and blacking out. Get out.");
                        }
                    }
                    else
                    {
                        if (!intoxPassedOutSaid)
                        {
                            intoxPassedOutSaid = true;
                            Speech.Critical("You passed out.");
                        }
                        if (now - intoxRagdollTicks > 40000000L)   // re-arm every 4 s
                        {
                            intoxRagdollTicks = now;
                            try { Function.Call(Hash.SET_PED_TO_RAGDOLL, player, 4000, 5000, 0, true, true, false); } catch { }
                        }
                    }
                }
            }
        }

        /// <summary>
        /// Control actuation for intoxicated driving. Runs AFTER the drive-assist
        /// block so nothing can silently overwrite these writes, and every write goes
        /// through WriteControlValue so it lands in the log's ctrlRet ledger.
        /// </summary>
        private void TickIntoxDriving()
        {
            if ((intoxStage < 2 && !intoxBlackout) || getSetting("intoxDriveImpair") != 1)
            { intoxBlackoutDriving = false; return; }
            // iter-51: this gate had a full implementation and NO GateReach call, so
            // the census reported it "QUIET — no-GateReach-call-site" forever and the
            // digest could not distinguish it from a gate that was never written.
            // Reach = the impaired-driving tick actually ran; fire is on the control
            // writes below, where the impairment becomes real.
            GateReach("intoxDriveImpair");
            Ped player = Game.Player.Character;
            if (player == null || !player.Exists()) { intoxBlackoutDriving = false; return; }

            Vehicle veh = null;
            try { if (player.IsInVehicle()) veh = player.CurrentVehicle; } catch { }
            if (veh == null || !veh.Exists()) { intoxBlackoutDriving = false; return; }
            // If the butler (or anyone else) is driving, the player's state is irrelevant.
            try { if (veh.Driver != player) { intoxBlackoutDriving = false; return; } } catch { }

            long now = ModClock.Ticks;

            // ---- blackout: dead-driver injection ----
            if (intoxBlackout && getSetting("intoxBlackoutDrive") == 1)
            {
                // iter-51: same story as intoxDriveImpair — a fully implemented gate
                // with no census call site, so it read QUIET whether it was working
                // or not. Reach here (blackout reached the driving hook), fire on the
                // control writes below (the dead driver actually took the wheel).
                GateReach("intoxBlackoutDrive");
                if (isAutodriving)
                {
                    if (!intoxBlackoutDriving)
                    {
                        intoxBlackoutDriving = true;
                        Speech.Critical("Auto-drive is driving. You blacked out as a passenger.");
                    }
                    return;
                }
                if (!intoxBlackoutDriving)
                {
                    intoxBlackoutDriving = true;
                    intoxBlackoutNagTicks = now;
                    IntoxLog("intox-blackout: start speed=" + (int)veh.Speed);
                    Speech.Critical("Blacking out. You are losing control of the vehicle.");
                }
                else if (now - intoxBlackoutNagTicks > 50000000L)   // 5 s
                {
                    intoxBlackoutNagTicks = now;
                    Speech.Critical("Still blacked out. Hold on.");
                }

                // Belt and braces. Control 71 is disabled by HoldThrottle, and a
                // write to a disabled control is a SILENT no-op (see the iter-39
                // Stage 1A block). intoxAssistSuspend should have closed the gate
                // that reaches HoldThrottle at all, so a nonzero mask here means a
                // regression re-introduced a disable site — make it visible.
                if (thrHoldSitesThisFrame != 0)
                    IntoxLog("intox-blackout-contested: thrHoldSites=" + thrHoldSitesThisFrame);

                WriteControlValue(71, 1.0f);
                if (now >= intoxSteerNextTicks)
                {
                    intoxSteerTarget = (float)(random.NextDouble() * 1.7 - 0.85);
                    intoxSteerNextTicks = now + 5000000L;   // 500 ms
                }
                // Exponential approach, ~0.3 s transitions: a slumped driver lurching,
                // not vibration. Per-frame randomness just reads as a rumble.
                intoxSteerCurrent += (intoxSteerTarget - intoxSteerCurrent) * Math.Min(1f, deltaTime * 3.0f);
                WriteControlValue(59, intoxSteerCurrent);
                GateFire("intoxBlackoutDrive");
                // Never 72/76 — an unconscious driver is not braking.
                return;
            }

            if (intoxBlackoutDriving)
            {
                intoxBlackoutDriving = false;
                Speech.Critical("You are coming round. You have the wheel back.");
            }

            // ---- stages 2/3: wander ----
            bool assistSteering = getSetting("steeringAssist") > 0 && !assistSuspended
                                  && !intoxAssistSuspend && steeringAssistActive;
            if (intoxStage == 2 && assistSteering)
            {
                // The assist's entire job is keeping a blind player on the road. A
                // feature that quietly cancels it is worse than useless, so at stage
                // 2 the drift yields rather than fighting it.
                if (!intoxCompensateSaid)
                {
                    intoxCompensateSaid = true;
                    Speech.Info("Drive assist is compensating for you.");
                }
                // iter-51: yielding to the assist IS the gate doing its job, so it
                // counts as a veto rather than silence. Without this the census
                // cannot tell "stage 2 with assist on" from "never reached".
                GateVeto("intoxDriveImpair");
                return;
            }

            float amp = intoxStage >= 3 ? 0.30f : 0.12f;
            long interval = intoxStage >= 3 ? 7000000L : 9000000L;   // 700 / 900 ms
            if (now >= intoxSteerNextTicks)
            {
                intoxSteerTarget = (float)((random.NextDouble() * 2.0 - 1.0) * amp);
                intoxSteerNextTicks = now + interval;
            }
            intoxSteerCurrent += (intoxSteerTarget - intoxSteerCurrent) * Math.Min(1f, deltaTime * 3.0f);
            float playerSteer = 0f;
            try { playerSteer = Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 59); } catch { }
            WriteControlValue(59, Math.Max(-1f, Math.Min(1f, playerSteer + intoxSteerCurrent)));
            GateFire("intoxDriveImpair");

            if (intoxStage >= 3)
            {
                if (now < intoxStutterUntilTicks) WriteControlValue(71, 0f);
                else if (random.NextDouble() < 0.15 * Math.Max(0.016f, deltaTime))
                    intoxStutterUntilTicks = now + 3000000L;   // 300 ms
            }
        }
        #endregion

        #region MENU/PHONE PROBE (menulog spike)
        // ===================================================================
        // MENU/PHONE INTROSPECTION PROBE — "menulog" spike (2026-07-15).
        // Validates that GTA V's pause menu and iFruit phone expose enough
        // state through natives to build a real spoken menu reader:
        //   pause menu — selection natives (undocumented, raw hashes)
        //   phone      — script-thread checks + scaleform GET_CURRENT_SELECTION
        // Everything is logged to menulog-*.log (MenuLogger) and compact raw
        // values are spoken live so a blind tester hears whether the probes
        // track key presses. Spike only: no label mapping, no script-global
        // reads. Toggled by the menuDebugLog setting.
        // ===================================================================

        // Prefix every menulog line with the probe frame counter, mirroring
        // the drive log's [F<n>] convention.
        private void MLog(string line)
        {
            menuLogger.Write("[F" + menuLogFrameCount + "] " + line);
        }

        // Queue a live announcement. Trailing-edge coalescer: latest text wins;
        // MDrainSpeech emits at most one menulog utterance per 250 ms so fast
        // arrowing speaks the first and the final selection instead of queueing
        // every intermediate row. The log keeps full fidelity regardless.
        private void MSpeak(string text)
        {
            // When the Menu Reader is on, it owns the voice — the probe's raw
            // diagnostic values would double-speak over the reader's labels.
            // The log keeps full fidelity through the EVENT lines either way.
            if (mrReaderEnabled) return;
            mlPendingSpeech = text;
        }

        private void MDrainSpeech()
        {
            if (mlPendingSpeech == null) return;
            DateTime now = DateTime.Now;
            if ((now - mlLastSpokeAt).TotalMilliseconds < 250) return;
            string text = mlPendingSpeech;
            mlPendingSpeech = null;
            mlLastSpokeAt = now;
            Speech.Ambient(text);
            MLog("EVENT speak: text=\"" + text + "\"");
        }

        // Fresh-session reset so a re-enabled probe re-logs current state
        // instead of suppressing it as "unchanged". The movie handle is kept —
        // release policy lives in StopPhoneProbe.
        private void ResetMenuProbeState()
        {
            mlPauseActive = false; mlPauseState = int.MinValue;
            mlLastMenuID = int.MinValue; mlSelUniqueID = int.MinValue;
            mlSelData0 = int.MinValue; mlSelData1 = int.MinValue; mlSelData2 = int.MinValue;
            mlPhoneOpen = false; mlPhoneRow = int.MinValue; mlAppMask = 0;
            mlSf = SfProbeState.Off; mlSfReturnHandle = 0; mlSfConsecTimeouts = 0;
            mlPauseErrors = 0; mlPhoneErrors = 0;
            mlPendingSpeech = null;
            mlLastHeartbeat = DateTime.MinValue;
            mlLastAppPoll = DateTime.MinValue;
        }

        // Dispatched from onTick after the nav cluster, before Speech.Drain.
        // NOT gated on Game.IsPaused — the pause probe depends on onTick
        // continuing to fire while the pause menu is up.
        // Shared frontend tick: computes the per-tick FrontendSnap and runs the
        // phone core for BOTH consumers (menulog probe + menu reader). Runs
        // before TickMenuProbe/TickMenuReader in the onTick dispatch.
        private void TickFrontendShared()
        {
            mrReaderEnabled = getSetting("pauseMenuReader") == 1;
            bool logOn = getSetting("menuDebugLog") == 1;
            mrSnapValid = false;
            if (!mrReaderEnabled && !logOn)
            {
                for (int i = 0; i < mrCtrlHeld.Length; i++) mrCtrlHeld[i] = false;
                // v1.2 (fix 9): no stale profile edges across a toggle-off —
                // a later re-enable must not attribute unrelated drift to a
                // phantom "menu close".
                mlSharedPauseWasActive = false;
                mrCommitSummary = null;
                mrKeyInputBits = 0;
                return;
            }
            CaptureFrontendState();

            // Phone machinery (open/close, app scripts, scaleform row) feeds
            // both the log and the reader. Its own 20-error fuse.
            if (mlPhoneErrors < 20)
            {
                try { TickPhoneCore(); }
                catch (Exception ex)
                {
                    mlPhoneErrors++;
                    MLog("EVENT probe-error: probe=phone n=" + mlPhoneErrors
                        + " msg=" + (ex.Message ?? "").Replace(' ', '_'));
                    if (mlPhoneErrors >= 20) MLog("EVENT probe-disabled: probe=phone");
                }
            }

            // Profile-setting value tracking (baseline on open, live diffs,
            // commit-on-close summary) — shared so it works reader-only.
            // v1.2: 20-error fuse like the other probes.
            if (mlProfileErrors < 20)
            {
                try { TickProfileShared(); }
                catch (Exception ex)
                {
                    mlProfileErrors++;
                    MLog("EVENT probe-error: probe=profile n=" + mlProfileErrors
                        + " msg=" + (ex.Message ?? "").Replace(' ', '_'));
                    if (mlProfileErrors >= 20) MLog("EVENT probe-disabled: probe=profile");
                }
            }
        }

        // Value tracking on the shared snapshot's open/close edges. Spike3
        // proved values live in the profile store (audio ids hold real values)
        // but changes mostly COMMIT ON MENU CLOSE (profile-commit-diff id=220
        // observed) — so: baseline at open, opportunistic live diffs while
        // open, authoritative diff at close (summary spoken by the reader).
        private void TickProfileShared()
        {
            if (!mrSnapValid) return;
            bool active = mrSnap.Active;
            if (active && !mlSharedPauseWasActive)
            {
                ScanProfileSettings(false);
                mlLastProfileScan = DateTime.Now;
                if (mlProfileOpenSnap == null) mlProfileOpenSnap = new int[1024];
                Array.Copy(mlProfileSnap, mlProfileOpenSnap, mlProfileSnap.Length);
            }
            else if (!active && mlSharedPauseWasActive)
            {
                if (mlProfileOpenSnap != null && mlProfileSnap != null)
                {
                    ScanProfileSettings(false);
                    int changes = 0, named = 0;
                    StringBuilder summary = new StringBuilder();
                    for (int id = 0; id <= 1023; id++)
                    {
                        if (mlProfileSnap[id] == mlProfileOpenSnap[id]) continue;
                        MLog("EVENT profile-commit-diff: id=" + id
                            + " old=" + mlProfileOpenSnap[id] + " new=" + mlProfileSnap[id]);
                        changes++;
                        // B5: never speak a raw "setting <n>" placeholder. Name a
                        // change only when it resolves to a real name; unnamed
                        // ones fold into the "N more changes" tail so the count
                        // stays honest. (v1.2 spoke "setting 220 to 1" aloud.)
                        string name;
                        if (named < 3 && MenuLabelDb.TryProfileName(id, out name)
                            && name != null && !name.StartsWith("setting "))
                        {
                            if (summary.Length > 0) summary.Append(", ");
                            // words, not enums — "Output to Headphones".
                            summary.Append(name).Append(" to ").Append(ProfileValueText(id, mlProfileSnap[id]));
                            named++;
                        }
                    }
                    int unnamed = changes - named;
                    if (changes > 0 && mrReaderEnabled)
                    {
                        if (named == 0)
                            mrCommitSummary = "Changed " + changes + (changes == 1 ? " setting." : " settings.");
                        else
                        {
                            if (unnamed > 0)
                                summary.Append(", and ").Append(unnamed)
                                       .Append(unnamed == 1 ? " more change" : " more changes");
                            mrCommitSummary = "Changed: " + summary + ".";
                        }
                    }
                }
                mlProfileSnapValid = false;
            }
            mlSharedPauseWasActive = active;
            if (!active) return;

            // v1.2 (fix 9): nav-triggered rescans are throttled to >=300 ms and
            // skipped at tab level (no value can change there) — held-arrow
            // auto-repeat was issuing ~6 full 1024-native scans per second.
            bool navValuePress = (mrSnap.InputEvents & (MR_IN_LEFT | MR_IN_RIGHT | MR_IN_ACCEPT)) != 0
                && !mrAtTabLevel;
            // v1.5: stamp the L/R press itself. ACCEPT is deliberately excluded —
            // it activates a row rather than changing a value, and binding a pref
            // to whatever an activation commits is exactly the kind of confident
            // wrong answer this reader is built to avoid.
            if ((mrSnap.InputEvents & (MR_IN_LEFT | MR_IN_RIGHT)) != 0 && !mrAtTabLevel)
                mrLastLrAt = DateTime.Now;
            double sinceScan = (DateTime.Now - mlLastProfileScan).TotalMilliseconds;
            if ((navValuePress && sinceScan >= 300) || sinceScan >= 1000)
            {
                mlLastProfileScan = DateTime.Now;
                ScanProfileSettings(true);
                ReaderBindAndSpeakValue();
            }
            // v1.3 (D3): removed the 1 Hz value-probe dump (ids 290-330). Across
            // two full sessions it produced ~9% of the log volume and zero
            // information — every value change commits on close, captured by the
            // profile-commit-diff path above. The commit diff is the value channel.
        }

        /// <summary>A1 + A2. Runs right after a profile rescan while the pause menu
        /// is open. Two jobs, in order:
        ///
        ///   1. LEARN. If a Left/Right press landed on a focused pref row inside
        ///      MR_BIND_WINDOW_MS and EXACTLY ONE profile id moved, that id is the
        ///      row's value and gets bound. Anything ambiguous is logged and
        ///      dropped — the log line still lets tools/bind-profile-ids.py settle
        ///      it offline, which is strictly better than guessing here.
        ///   2. SPEAK. Announce the row's new value. Before v1.5 a value change was
        ///      completely silent: the selection natives do not move on Left/Right,
        ///      so the reader had nothing to react to and the user got one summary
        ///      line when the whole menu closed. That made the settings menu
        ///      navigable but not operable without sight.</summary>
        private void ReaderBindAndSpeakValue()
        {
            if (!mrReaderEnabled || mrAtTabLevel) return;
            if (mrFocusedPref == null) return;
            if ((DateTime.Now - mrLastLrAt).TotalMilliseconds > MR_BIND_WINDOW_MS) return;

            int id;
            bool known = TryProfileIdFor(mrFocusedPref, out id);

            if (!known && mrChangedIds.Count > 0 && getSetting("menuReaderBindLearn") == 1)
            {
                if (mrChangedIds.Count == 1)
                {
                    id = mrChangedIds[0];
                    MenuBindDb.Bind(mrFocusedPref, id);
                    known = true;
                    MLog("EVENT reader-bind: pref=" + mrFocusedPref + " id=" + id
                        + " new=" + mlProfileSnap[id] + " pane=" + mrFocusedPane
                        + " total=" + MenuBindDb.Count);
                }
                else
                {
                    MLog("EVENT reader-bind-ambiguous: pref=" + mrFocusedPref
                        + " pane=" + mrFocusedPane
                        + " ids=" + string.Join(",", mrChangedIds));
                }
            }

            if (!known || getSetting("menuReaderValueLive") != 1) return;
            // Only speak when THIS row's id is one of the ones that just moved.
            // A rescan fires on any L/R, including on a row whose value the game
            // clamped and did not change; announcing the unchanged value then
            // would tell the user the press worked when it did not.
            if (!mrChangedIds.Contains(id)) return;
            string label = mrFocusedLabel ?? mrFocusedPref;
            MrSpeak(label + ", " + ProfileValueText(mlProfileSnap[id], mrFocusedOptionType), "value");
        }

        /// <summary>Profile-setting id for a pref: the shipped pin always wins, a
        /// learned binding only ever fills a gap. Keeps a bad learning recoverable
        /// by regenerating the JSON rather than by deleting a user file.</summary>
        private bool TryProfileIdFor(string pref, out int id)
        {
            if (MenuLabelDb.TryProfileIdForPref(pref, out id)) return true;
            return MenuBindDb.TryGet(pref, out id);
        }

        // Single caller of the frontend natives. The two one-frame natives are
        // CONSUME-ON-READ — if the probe and reader each polled them, one would
        // steal the other's events. Nothing outside this method may call them.
        private void CaptureFrontendState()
        {
            mrSnap = new FrontendSnap();
            mrSnap.Active = Function.Call<bool>(Hash.IS_PAUSE_MENU_ACTIVE);
            mrSnap.State = Function.Call<int>(Hash.GET_PAUSE_MENU_STATE);

            // Esc-hijack: while no menu is up, disable the Esc pause control
            // every frame so the game's own (script-suspending) pause never
            // races the KeyDown handler that opens the frontend unpaused.
            // Control 199 (INPUT_FRONTEND_PAUSE, the P key) stays enabled — P
            // still opens the normal paused menu. Once a menu is up, Esc
            // behaves natively so backing out / closing is untouched.
            if (!mrSnap.Active && !keys_disabled)
                Function.Call(Hash.DISABLE_CONTROL_ACTION, 0, 200, true); // INPUT_FRONTEND_PAUSE_ALTERNATE (Esc)

            // Esc-open hold-off: keep CANCEL disabled while the opening Esc press
            // is still down (+150 ms after release, floored at open+350 ms) so the
            // menu doesn't self-close; fresh Esc presses after the grace behave
            // natively.
            //
            // v1.4: this MUST run whether or not the menu reports active yet.
            // v1.3 nested it inside `if (mrSnap.Active)`, but ACTIVATE_FRONTEND_MENU
            // takes ~6 frames to flip IS_PAUSE_MENU_ACTIVE (2026-07-20 log: F152
            // frontend-open -> F158 pause-open) and Esc is still physically held
            // across that window, so the frontend ate it as INPUT_FRONTEND_CANCEL
            // and closed the menu one frame after opening it — 3 of 15 opens.
            bool escSuppressing = false;
            if (mrEscHoldoff)
            {
                if (DateTime.Now >= mrEscHoldoffEnd)
                {
                    mrEscHoldoff = false;
                    mrEscHoldoffEnd = DateTime.MaxValue;
                    if (mrEscSuppressFrames > 0)
                    {
                        MLog("EVENT esc-holdoff: released frames=" + mrEscSuppressFrames
                            + " cancelsEaten=" + mrEscSuppressedCancels);
                        mrEscSuppressFrames = 0;
                        mrEscSuppressedCancels = 0;
                    }
                }
                else
                {
                    Function.Call(Hash.DISABLE_CONTROL_ACTION, 0, 202, true); // INPUT_FRONTEND_CANCEL
                    Function.Call(Hash.DISABLE_CONTROL_ACTION, 2, 202, true);
                    escSuppressing = true;
                    mrEscSuppressFrames++;
                }
            }

            if (mrSnap.Active)
            {
                mrSnap.NavPulse = Function.Call<bool>((Hash)0x2E22FEFA0100275E);      // one-frame: highlight moved (ONLY caller)
                mrSnap.ActivatePulse = Function.Call<bool>((Hash)0xF284AC67940C6812); // one-frame: item activated (ONLY caller)

                OutputArgument outMenu = new OutputArgument();
                OutputArgument outItem = new OutputArgument();
                Function.Call((Hash)0x36C1451A88A09630, outMenu, outItem); // _GET_PAUSE_MENU_SELECTION
                mrSnap.LastMenuId = outMenu.GetResult<int>();
                mrSnap.LastUniqueId = outItem.GetResult<int>();

                OutputArgument outD0 = new OutputArgument();
                OutputArgument outD1 = new OutputArgument();
                OutputArgument outD2 = new OutputArgument();
                Function.Call((Hash)0x7E17BE53E1AAABAF, outD0, outD1, outD2); // _GET_PAUSE_MENU_SELECTION_DATA
                mrSnap.D0 = outD0.GetResult<int>();
                mrSnap.D1 = outD1.GetResult<int>();
                mrSnap.D2 = outD2.GetResult<int>();

                // v1.2: two input sources — OS key events (primary; the nav
                // control natives are dead in this frontend) + the native edge
                // detector (secondary; catches gamepad). Union feeds consumers;
                // the split is logged so sessions prove which source fires.
                mrSnap.InputEventsKey = mrKeyInputBits;
                mrSnap.InputEventsCtl = MenuInputTick();
                mrSnap.InputEvents = mrSnap.InputEventsKey | mrSnap.InputEventsCtl;
                // v1.4: MenuInputTick reads IS_DISABLED_CONTROL_PRESSED too, so the
                // still-held opening Esc surfaced as a cancel EVENT (src=ctl) even
                // once the control was disabled for the game. Mask it while the
                // hold-off is armed or the reader acts on a keypress the frontend
                // never saw.
                if (escSuppressing && (mrSnap.InputEvents & MR_IN_CANCEL) != 0)
                {
                    mrEscSuppressedCancels++;
                    mrSnap.InputEventsKey &= ~MR_IN_CANCEL;
                    mrSnap.InputEventsCtl &= ~MR_IN_CANCEL;
                    mrSnap.InputEvents &= ~MR_IN_CANCEL;
                }
                if ((mrSnap.InputEvents & MR_IN_CANCEL) != 0) mrLastCancelAt = DateTime.Now;
            }
            else
            {
                for (int i = 0; i < mrCtrlHeld.Length; i++) mrCtrlHeld[i] = false;
            }
            mrKeyInputBits = 0;
            mrSnapValid = true;
        }

        // Frontend input edge detector. IS_CONTROL_JUST_PRESSED missed presses
        // and never fired on key-repeat (spike3 logs: navs with no key logged),
        // so we track held state ourselves and synthesize press + auto-repeat
        // events. Repeat cadence tuned during calibration.
        private int MenuInputTick()
        {
            int events = 0;
            DateTime now = DateTime.Now;
            for (int i = 0; i < ML_FRONTEND_CONTROLS.Length; i++)
            {
                int ctrl = ML_FRONTEND_CONTROLS[i];
                bool held = Function.Call<bool>(Hash.IS_CONTROL_PRESSED, 2, ctrl)
                    || Function.Call<bool>(Hash.IS_DISABLED_CONTROL_PRESSED, 2, ctrl);
                if (held && !mrCtrlHeld[i])
                {
                    events |= 1 << i;
                    mrCtrlNextRepeat[i] = now.AddMilliseconds(400);
                }
                else if (held && now >= mrCtrlNextRepeat[i])
                {
                    events |= 1 << i;
                    mrCtrlNextRepeat[i] = now.AddMilliseconds(160);
                }
                mrCtrlHeld[i] = held;
            }
            return events;
        }

        private void TickMenuProbe()
        {
            bool enabled = getSetting("menuDebugLog") == 1;
            if (enabled && !menuLogWasEnabled)
            {
                menuLogger.Start();
                if (menuLogger.IsRunning)
                {
                    menuLogFrameCount = 0;
                    ResetMenuProbeState();
                    MLog("EVENT menulog-version: reader1.5");
                    Speech.Info("Menu debug logging started");
                }
            }
            else if (!enabled && menuLogWasEnabled)
            {
                StopPhoneProbe();
                MLog("EVENT menulog-stop:");
                menuLogger.Stop();
                Speech.Info("Menu debug logging stopped");
            }
            menuLogWasEnabled = enabled;
            if (!menuLogger.IsRunning) return;
            menuLogFrameCount++;

            // Each sub-probe has its own catch + 20-error fuse so one flaky
            // native can neither spam the log nor take down the other probe.
            // The dispatch-level ReportSubsystemError stays as outer backstop.
            if (mlPauseErrors < 20)
            {
                try { TickPauseProbe(); }
                catch (Exception ex)
                {
                    mlPauseErrors++;
                    MLog("EVENT probe-error: probe=pause n=" + mlPauseErrors
                        + " msg=" + (ex.Message ?? "").Replace(' ', '_'));
                    if (mlPauseErrors >= 20) MLog("EVENT probe-disabled: probe=pause");
                }
            }
            // (Phone core now runs from TickFrontendShared so the reader gets
            // phone state even when logging is off.)

            // Liveness heartbeat: proves the probe ran even when nothing
            // changed (disambiguates "natives frozen" from "probe dead").
            double hbMs = (mlPauseActive || mlPhoneOpen) ? 1000 : 5000;
            DateTime hbNow = DateTime.Now;
            if ((hbNow - mlLastHeartbeat).TotalMilliseconds >= hbMs)
            {
                mlLastHeartbeat = hbNow;
                // cur= is the live (d1,d2) the reader labels from; menu=/item= are
                // the one-nav-stale 0x36C1 pair (see pause-sel). pane= makes the
                // honesty gate's view visible on every heartbeat.
                MLog("FRAME t=" + hbNow.ToString("HH:mm:ss.fff")
                    + " paused=" + (mlPauseActive ? 1 : 0) + " state=" + mlPauseState
                    + " cur=" + mlSelData1 + "/" + mlSelData2 + " pane=" + mrCurrentPane
                    + " menu=" + mlLastMenuID + " item=" + mlSelUniqueID
                    + " phone=" + (mlPhoneOpen ? 1 : 0) + " row=" + mlPhoneRow
                    + " sf=" + mlSf + " apps=0x" + mlAppMask.ToString("X"));
            }

            MDrainSpeech();
        }

        // Pause-menu probe: open/close edges, screen-state changes, highlighted
        // item, and the two one-frame nav/activate signals.
        private void TickPauseProbe()
        {
            // LOGGING only — reader speech lives in TickMenuReader. Consumes
            // the shared FrontendSnap; never calls the frontend natives itself
            // (the one-frame natives are consume-on-read, single-caller rule).
            if (!mrSnapValid) return;
            bool active = mrSnap.Active;
            int state = mrSnap.State;

            if (active != mlPauseActive)
            {
                mlPauseActive = active;
                if (active)
                {
                    MLog("EVENT pause-open: state=" + state);
                    MSpeak("pause state " + state);
                }
                else
                {
                    MLog("EVENT pause-close:");
                    MSpeak("pause closed");
                }
                // (Profile baseline / commit-on-close diff moved to
                // TickProfileShared so it also runs reader-only.)
            }
            if (state != mlPauseState)
            {
                MLog("EVENT pause-state: state=" + state + " prev=" + mlPauseState);
                mlPauseState = state;
            }
            if (!active) return;

            if (mrSnap.NavPulse) MLog("EVENT pause-nav:");
            if (mrSnap.ActivatePulse) MLog("EVENT pause-activate:");

            // Input events from the shared edge detector (press + auto-repeat).
            // Log the source split (key = OS KeyDown hook, ctl = native poll) so
            // sessions can attribute anomalies like the Esc-cancel self-close.
            for (int i = 0; i < ML_FRONTEND_CONTROL_NAMES.Length; i++)
                if ((mrSnap.InputEvents & (1 << i)) != 0)
                {
                    bool k = (mrSnap.InputEventsKey & (1 << i)) != 0;
                    bool c = (mrSnap.InputEventsCtl & (1 << i)) != 0;
                    MLog("EVENT input: ctrl=" + ML_FRONTEND_CONTROL_NAMES[i]
                        + " src=" + (k && c ? "both" : k ? "key" : "ctl"));
                }
            // (Profile rescans + value-probe line moved to TickProfileShared.)

            int menuId = mrSnap.LastMenuId;
            int itemId = mrSnap.LastUniqueId;
            int d0 = mrSnap.D0;
            int d1 = mrSnap.D1;
            int d2 = mrSnap.D2;

            if (menuId != mlLastMenuID || itemId != mlSelUniqueID
                || d0 != mlSelData0 || d1 != mlSelData1 || d2 != mlSelData2)
            {
                // Spike3: speak the CURRENT highlight — per the cfx research,
                // d1=selectedItemMenuId and d2=selectedItemUniqueId are live,
                // while the 0x36C1 pair is the LAST item and lags one move
                // behind (spike2 log confirmed: each event's d1 equals the
                // next event's menu=).
                if (d1 != mlSelData1 || d2 != mlSelData2)
                    MSpeak("menu " + d1 + ", item " + d2);
                mlLastMenuID = menuId; mlSelUniqueID = itemId;
                mlSelData0 = d0; mlSelData1 = d1; mlSelData2 = d2;
                // v1.4: lead with the CURRENT pair. menu=/item= are the 0x36C1
                // values, which lag one nav behind the (d1,d2) the reader actually
                // labels from — reading them as "the selection" sent triage down a
                // blind alley on the 2026-07-20 logs. cur= is the truth; the rest
                // stays for continuity with older logs.
                MLog("EVENT pause-sel: cur=" + d1 + "/" + d2
                    + " prevMenu=" + menuId + " prevItem=" + itemId
                    + " d0=" + d0 + " d1=" + d1 + " d2=" + d2);
            }
        }

        // Spike3: snapshot/diff the profile-setting table (ids 0-800). GTA
        // stores the console-style settings pages (Audio/Display/Gameplay) as
        // profile settings, so this makes slider/toggle changes audible even
        // though the pause-menu selection uniqueID never moves on left/right.
        // PC-only pages (Graphics, Key Bindings) live elsewhere and stay
        // silent by design. ~800 calls per scan, only while the menu is open.
        private void ScanProfileSettings(bool logDiffs)
        {
            if (mlProfileSnap == null) mlProfileSnap = new int[1024];
            string spoken = null;
            // v1.5: the changed set is published for every scan, not only the
            // logging ones — A1 binds off it and A2 speaks off it, and both must
            // work with menuDebugLog off.
            mrChangedIds.Clear();
            for (int id = 0; id <= 1023; id++)
            {
                int v = Function.Call<int>(Hash.GET_PROFILE_SETTING, id);
                if (mlProfileSnapValid && v != mlProfileSnap[id])
                {
                    if (mrChangedIds.Count < 16) mrChangedIds.Add(id);
                    if (logDiffs)
                    {
                        MLog("EVENT profile-change: id=" + id + " old=" + mlProfileSnap[id] + " new=" + v);
                        if (spoken == null)
                        {
                            string name;
                            if (!MenuLabelDb.TryProfileName(id, out name)) name = "setting " + id;
                            spoken = name + ", " + ProfileValueText(id, v);
                        }
                    }
                }
                mlProfileSnap[id] = v;
            }
            mlProfileSnapValid = true;
            if (spoken != null)
            {
                // Reader owns the voice when on; the probe's raw channel
                // otherwise (MSpeak self-mutes if the reader is enabled).
                if (mrReaderEnabled) MrSpeak(spoken);
                else MSpeak(spoken);
            }
        }

        // Phone core: open/close via the cellphone_flashhand thread count,
        // per-app script-thread poll, and the GET_CURRENT_SELECTION scaleform
        // round-trip state machine. Runs from TickFrontendShared whenever the
        // menulog OR the reader is enabled; MLog no-ops when the log is off.
        private void TickPhoneCore()
        {
            if (mlAppNames == null)
            {
                mlFlashhandHash = Game.GenerateHash("cellphone_flashhand");
                // Candidate phone-app script names — the spike exists to confirm
                // which are real; wrong names harmlessly report <=0.
                mlAppNames = new string[] {
                    "appcontacts", "appcamera", "appsettings", "apptext", "appsms",
                    "apptextmessage", "appemail", "appinternet", "appmedia",
                    "apporganiser", "apptrackify", "appsidetask", "appchecklist", "appzit" };
                mlAppHashes = new int[mlAppNames.Length];
                for (int i = 0; i < mlAppNames.Length; i++)
                    mlAppHashes[i] = Game.GenerateHash(mlAppNames[i]);
            }

            DateTime now = DateTime.Now;
            // Native semantics are numRefs-1, so >0 means a live thread.
            int flashCount = Function.Call<int>(Hash.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH, mlFlashhandHash);
            bool open = flashCount > 0;

            if (open && !mlPhoneOpen)
            {
                mlPhoneOpen = true;
                string pedName;
                string movie = PhoneMovieForCurrentPed(out pedName);
                MLog("EVENT phone-open: movie=" + movie + " ped=" + pedName + " flashCount=" + flashCount);
                MSpeak("phone open, " + movie.Replace("cellphone_", ""));

                if (movie == mlPhoneMovie && mlPhoneMovieHandle != 0
                    && Function.Call<bool>(Hash.HAS_SCALEFORM_MOVIE_LOADED, mlPhoneMovieHandle))
                {
                    // Same movie as last episode and still loaded — reuse the
                    // handle rather than churning REQUEST refcounts.
                    mlSfNextIssueAt = now;
                    mlSf = SfProbeState.ReadyToIssue;
                }
                else
                {
                    if (mlPhoneMovieHandle != 0 && movie != mlPhoneMovie)
                        // Conservative policy never releases mid-session; a
                        // protagonist switch strands the old ref. Bounded (max
                        // 3 movies per session) and visible in the log.
                        MLog("EVENT sf-leaked: handle=" + mlPhoneMovieHandle + " why=movie-changed");
                    mlPhoneMovie = movie;
                    mlPhoneMovieHandle = Function.Call<int>(Hash.REQUEST_SCALEFORM_MOVIE, movie);
                    mlSfMovieRequestedAt = now;
                    mlSf = SfProbeState.AwaitMovieLoad;
                }
                mlSfConsecTimeouts = 0;
            }
            else if (!open && mlPhoneOpen)
            {
                mlPhoneOpen = false;
                MLog("EVENT phone-close:");
                MSpeak("phone closed");
                // Abandon any outstanding return handle; keep the movie handle
                // (release policy lives in StopPhoneProbe). The Disabled fuse is
                // per phone episode, so the next open retries fresh.
                mlSfReturnHandle = 0;
                mlSf = SfProbeState.Off;
                mlPhoneRow = int.MinValue;
                mlAppMask = 0;
            }

            if (!mlPhoneOpen) return;

            // Per-app script-thread poll at 250 ms.
            if ((now - mlLastAppPoll).TotalMilliseconds >= 250)
            {
                mlLastAppPoll = now;
                uint mask = 0;
                int[] counts = new int[mlAppHashes.Length];
                for (int i = 0; i < mlAppHashes.Length; i++)
                {
                    counts[i] = Function.Call<int>(Hash.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH, mlAppHashes[i]);
                    if (counts[i] > 0) mask |= 1u << i;
                }
                if (mask != mlAppMask)
                {
                    StringBuilder on = new StringBuilder();
                    StringBuilder off = new StringBuilder();
                    string firstGained = null;
                    for (int i = 0; i < mlAppNames.Length; i++)
                    {
                        bool isOn = (mask & (1u << i)) != 0;
                        bool wasOn = (mlAppMask & (1u << i)) != 0;
                        if (isOn)
                        {
                            if (on.Length > 0) on.Append(',');
                            on.Append(mlAppNames[i]).Append(':').Append(counts[i]);
                            if (!wasOn && firstGained == null) firstGained = mlAppNames[i];
                        }
                        else if (wasOn)
                        {
                            if (off.Length > 0) off.Append(',');
                            off.Append(mlAppNames[i]);
                        }
                    }
                    MLog("EVENT phone-app: on=" + (on.Length > 0 ? on.ToString() : "none")
                        + " off=" + (off.Length > 0 ? off.ToString() : "none"));
                    if (firstGained != null) MSpeak("app " + firstGained);
                    mlAppMask = mask;
                }
            }

            // GET_CURRENT_SELECTION round-trip state machine. Invariant: a
            // single return handle, issued only from ReadyToIssue, zeroed on
            // every AwaitReturn exit — a stuck handle can't wedge the machine.
            switch (mlSf)
            {
                case SfProbeState.AwaitMovieLoad:
                    if (Function.Call<bool>(Hash.HAS_SCALEFORM_MOVIE_LOADED, mlPhoneMovieHandle))
                    {
                        MLog("EVENT phone-movie: name=" + mlPhoneMovie + " handle=" + mlPhoneMovieHandle
                            + " loadMs=" + (int)(now - mlSfMovieRequestedAt).TotalMilliseconds);
                        mlSfNextIssueAt = now;
                        mlSf = SfProbeState.ReadyToIssue;
                    }
                    else if ((now - mlSfMovieRequestedAt).TotalMilliseconds > 2000)
                    {
                        MLog("EVENT sf-disabled: why=movie-load-timeout");
                        mlSf = SfProbeState.Disabled;
                    }
                    break;

                case SfProbeState.ReadyToIssue:
                    if (now >= mlSfNextIssueAt)
                    {
                        Function.Call(Hash.BEGIN_SCALEFORM_MOVIE_METHOD, mlPhoneMovieHandle, "GET_CURRENT_SELECTION");
                        mlSfReturnHandle = Function.Call<int>(Hash.END_SCALEFORM_MOVIE_METHOD_RETURN_VALUE);
                        mlSfIssuedAt = now;
                        mlSf = SfProbeState.AwaitReturn;
                    }
                    break;

                case SfProbeState.AwaitReturn:
                    if (Function.Call<bool>(Hash.IS_SCALEFORM_MOVIE_METHOD_RETURN_VALUE_READY, mlSfReturnHandle))
                    {
                        int row = Function.Call<int>(Hash.GET_SCALEFORM_MOVIE_METHOD_RETURN_VALUE_INT, mlSfReturnHandle);
                        int latencyMs = (int)(now - mlSfIssuedAt).TotalMilliseconds;
                        mlSfReturnHandle = 0;
                        mlSfConsecTimeouts = 0;
                        mlSfNextIssueAt = now.AddMilliseconds(200);
                        mlSf = SfProbeState.ReadyToIssue;
                        if (row != mlPhoneRow)
                        {
                            MLog("EVENT phone-row: row=" + row + " prev=" + mlPhoneRow + " latencyMs=" + latencyMs);
                            MSpeak("phone row " + row);
                            mlPhoneRow = row;
                        }
                    }
                    else if ((now - mlSfIssuedAt).TotalMilliseconds > 1000)
                    {
                        mlSfConsecTimeouts++;
                        MLog("EVENT sf-timeout: retHandle=" + mlSfReturnHandle + " consec=" + mlSfConsecTimeouts);
                        mlSfReturnHandle = 0; // abandon; the game recycles return-value slots
                        if (mlSfConsecTimeouts >= 5)
                        {
                            MLog("EVENT sf-disabled: why=return-timeouts");
                            mlSf = SfProbeState.Disabled;
                        }
                        else
                        {
                            mlSfNextIssueAt = now.AddMilliseconds(500);
                            mlSf = SfProbeState.ReadyToIssue;
                        }
                    }
                    break;
            }
        }

        // Movie-ref release on probe stop (setting toggled off). Conservative:
        // releasing the game's live phone movie under a blind user is a far
        // worse failure than leaking a few hundred KB until script reload, so
        // release only when the phone is confirmed closed; otherwise leak+log.
        private void StopPhoneProbe()
        {
            try
            {
                // Called on menulog stop. If the READER still needs the phone
                // core, leave the machinery and the movie ref alone — the ref
                // is released only when no consumer remains (or leaks, bounded,
                // at script reload).
                if (mrReaderEnabled) return;
                mlSfReturnHandle = 0;
                mlSf = SfProbeState.Off;
                if (mlPhoneMovieHandle != 0)
                {
                    int flashCount = mlFlashhandHash != 0
                        ? Function.Call<int>(Hash.GET_NUMBER_OF_THREADS_RUNNING_THE_SCRIPT_WITH_THIS_HASH, mlFlashhandHash)
                        : 0;
                    if (flashCount <= 0)
                    {
                        Function.Call(Hash.SET_SCALEFORM_MOVIE_AS_NO_LONGER_NEEDED, new OutputArgument(mlPhoneMovieHandle));
                        MLog("EVENT sf-released: handle=" + mlPhoneMovieHandle);
                    }
                    else
                    {
                        MLog("EVENT sf-leaked: handle=" + mlPhoneMovieHandle + " why=phone-open-at-stop");
                    }
                    mlPhoneMovieHandle = 0;
                    mlPhoneMovie = null;
                }
                mlPhoneOpen = false;
                mlPhoneRow = int.MinValue;
                mlAppMask = 0;
            }
            catch { }
        }

        // Each protagonist carries a different phone brand, and each brand is
        // its own scaleform movie. Unknown peds (MP models, animals) fall back
        // to ifruit with the model hash logged so the mismatch is visible.
        /// <summary>Character index the phone's script globals are keyed by, per
        /// cellphone_controller.c (0 Michael, 1 Franklin, 2 Trevor, 3 multiplayer).
        /// Derived from the ped rather than read out of Global_21649 — we already
        /// identify the ped to pick the phone movie, and one less unpinned global
        /// is one less thing that can be wrong on a build we cannot version-check.
        /// </summary>
        private int PhoneCharIndex()
        {
            try
            {
                PedHash h = (PedHash)Game.Player.Character.Model.Hash;
                if (h == PedHash.Michael) return 0;
                if (h == PedHash.Franklin) return 1;
                if (h == PedHash.Trevor) return 2;
                return 3;
            }
            catch { return -1; }
        }

        private string PhoneMovieForCurrentPed(out string pedName)
        {
            try
            {
                PedHash h = (PedHash)Game.Player.Character.Model.Hash;
                if (h == PedHash.Michael) { pedName = "Michael"; return "cellphone_ifruit"; }
                if (h == PedHash.Franklin) { pedName = "Franklin"; return "cellphone_badger"; }
                if (h == PedHash.Trevor) { pedName = "Trevor"; return "cellphone_facade"; }
                pedName = "other:0x" + ((uint)Game.Player.Character.Model.Hash).ToString("X8");
                return "cellphone_ifruit";
            }
            catch
            {
                pedName = "unknown";
                return "cellphone_ifruit";
            }
        }
        #endregion

        #region MENU READER v1
        // ===================================================================
        // MENU READER v1 — spoken pause menu + phone (2026-07-18).
        // Consumes the shared FrontendSnap (pause menu) and the phone core's
        // fields (mlPhoneOpen/mlPhoneRow/mlAppMask); labels come from
        // MenuLabelDb (gta11y-menulabels.json: game XML + eMenuScreen enum,
        // GXT-localized, calibration-refined). Gated by pauseMenuReader
        // (default ON). The menulog probe stays independent; when both are
        // on the reader owns the voice and the probe just logs.
        // ===================================================================

        // Reader-local trailing-edge coalescer, independent of the probe's:
        // fast arrowing speaks the first and final selection only.
        private string mrPendingSrc = "row";
        private void MrSpeak(string text, string src = "row")
        {
            mrPendingSpeech = text;
            mrPendingSrc = src;
        }

        private void MrDrainSpeech()
        {
            if (mrPendingSpeech == null) return;
            DateTime now = DateTime.Now;
            if ((now - mrLastSpokeAt).TotalMilliseconds < 250) return;
            string text = mrPendingSpeech;
            string src = mrPendingSrc;
            mrPendingSpeech = null;
            mrLastSpokeAt = now;
            // v1.2 (fix 7): Info tier = interrupts current speech and is never
            // dropped by a same-tick Critical (Critical speaks first, this
            // follows) — screen-reader-standard menu behavior. Ambient was
            // both droppable and non-interrupting.
            Speech.Info(text);
            MLog("EVENT reader-speak: src=" + src + " text=\"" + text + "\"");
        }

        // Chokepoint for the reader's non-coalesced announcements (open/close/
        // summaries) so EVERY spoken line reaches the log.
        private void MrAnnounce(string text, string src)
        {
            Speech.Info(text);
            MLog("EVENT reader-speak: src=" + src + " text=\"" + text + "\"");
        }

        // v1.2 label chain. Row identity model (validated 2026-07-18):
        //   pref rows:   (51, eMenuPref value) -> rows table
        //   hash rows:   d1 = joaat MenuUniqueIdHash -> screenItems table
        //   link rows:   d1 = target screen id       -> menus table
        // Honesty gate: an assumed pref row is spoken only when its owning
        // pane matches the tracked current pane — a wrong label is worse for a
        // blind user than an honest "unknown setting". Returns null when the
        // selection must not be spoken at all.
        private string ReaderRowText(int menuId, int uniqueId)
        {
            mrRowCue = false;
            // v1.5: the focused-row identity is republished on every resolution and
            // cleared by default, so a row with no pref (a category link, a trigger
            // row, an unmapped uid) can never leave the previous row's pref standing
            // for the binder to attribute a value change to.
            mrFocusedPref = null;
            mrFocusedOptionType = null;
            mrFocusedLabel = null;
            if (menuId == -1) return null; // pure activation transient, never focused
            // v1.3 (B3): a focused row whose menu id is an internal sentinel used
            // to be dropped silently — the user heard nothing. Announce it and
            // harvest it instead (the settings-category INCEPT_TRIGGER row).
            if (MenuLabelDb.IsInternal(menuId))
            {
                // v1.4: an INCEPT row carries its TARGET SCREEN in d2, not a pref
                // uid — pausemenu.xml item 4 of MENU_UNIQUE_ID_SETTINGS is
                // KEYMAP / MENU_OPTION_ACTION_INCEPT / PM_PANE_KEYS, and
                // commands_hud.lua puts KEYMAP at 148, which is exactly the
                // (d1=131, d2=148) pair the log showed. So resolve d2 as a screen.
                // That row is 3rd in every Settings visit and spoke "unknown item".
                string inceptLabel;
                if (MenuLabelDb.TryMenuLabel(uniqueId, out inceptLabel))
                {
                    MLog("EVENT reader-incept: menu=" + menuId + " target=" + uniqueId);
                    return inceptLabel;
                }
                MLog("EVENT reader-internal: menu=" + menuId + " item=" + uniqueId
                    + " pane=" + mrCurrentPane);
                return "unknown item";
            }

            string label;
            int pane;
            if (MenuLabelDb.TryHashedItem(menuId, out label, out pane))
            {
                if (pane != 0 && pane != mrCurrentPane)
                {
                    mrCurrentPane = pane;
                    mrPaneKeysUntrusted = false;
                    MLog("EVENT reader-pane: pane=" + pane + " via=hashedItem");
                }
                return label; // clean label, no suffix, no harvest
            }

            if (menuId == 51)
            {
                MenuLabelDb.RowEntry row;
                var res = MenuLabelDb.TryRowLabel(51, uniqueId, out label, out row);
                if (res == MenuLabelDb.LabelResult.Ok)
                {
                    // v1.3 trust model. "confirmed" (observed uid) and "verified"
                    // rows are safe even without a tracked pane. Everything else
                    // is spoken only inside its own pane; a wrong pane is the
                    // classic mis-key signature -> "unknown setting". Cue the row
                    // when the key isn't fully trustworthy (unpinned 47-120 band,
                    // a pane distrusted by the ordinal gate, or — the v1.2 hole,
                    // now inverted — an unknown pane).
                    bool safeId = row.status == "verified" || row.keyConfidence == "confirmed";
                    bool paneKnown = mrCurrentPane != 0;
                    bool paneMatch = row.screenMenuId.HasValue && row.screenMenuId.Value == mrCurrentPane;

                    if (!safeId && paneKnown && !paneMatch)
                    {
                        MLog("EVENT reader-pane-mismatch: item=" + uniqueId
                            + " rowPane=" + row.screenMenuId + " currentPane=" + mrCurrentPane);
                        return "unknown setting";
                    }

                    if (!safeId && (row.keyConfidence == "unpinned" || mrPaneKeysUntrusted || !paneKnown))
                    {
                        mrRowCue = true;
                        MLog("EVENT reader-cue: item=" + uniqueId + " conf=" + (row.keyConfidence ?? "derived")
                            + " paneKnown=" + (paneKnown ? 1 : 0) + " distrust=" + (mrPaneKeysUntrusted ? 1 : 0));
                    }

                    // v1.5: publish the focused row so the profile rescan can bind
                    // its pref to an id (A1) and speak its new value (A2). Only for
                    // a row we actually trust — binding off an unverified name would
                    // write a wrong pref into a file that outlives the session.
                    if (row.pref != null && !mrRowCue)
                    {
                        mrFocusedPref = row.pref;
                        mrFocusedOptionType = row.optionType;
                        mrFocusedLabel = label;
                        mrFocusedPane = mrCurrentPane;
                    }

                    // Append the committed value. Never for a key we don't fully
                    // trust: an unverified name paired with a confident value is the
                    // worst of both. Composed into one string at the end so the A3
                    // position cue lands AFTER the value ("Music Volume, 9 of 10,
                    // 2 of 17") rather than between the row and its setting.
                    string rowText = label;
                    int pid;
                    if (row.pref != null && !mrRowCue)
                    {
                        // Profile store. v1.4 suppressed this whenever the row had
                        // been arrowed (mrRowLrCount == 0) because the snapshot only
                        // committed on close and would have read stale. v1.5 rescans
                        // within 300 ms of every L/R, so the snapshot IS live and the
                        // suppression now only hides a correct answer.
                        string xv;
                        if (mlProfileSnap != null && mlProfileSnapValid
                            && TryProfileIdFor(row.pref, out pid))
                        {
                            string pv = ProfileValueText(mlProfileSnap[pid], row.optionType);
                            MLog("EVENT reader-value: pref=" + row.pref + " id=" + pid
                                + " src=profile text=\"" + pv + "\"");
                            rowText = label + ", " + pv;
                        }
                        // A4: a handful of rows are neither profile settings nor
                        // settings.xml keys, but the game will answer for them
                        // directly (radio station, measurement system).
                        else if (TryNativeValueText(row.pref, out xv))
                        {
                            MLog("EVENT reader-value: pref=" + row.pref + " src=native text=\"" + xv + "\"");
                            rowText = label + ", " + xv;
                        }
                        // v1.4: Graphics/Advanced Graphics/video rows are NOT profile
                        // settings, so they had no value at all. settings.xml has them.
                        // Unlike the profile store this file is only rewritten when
                        // the menu CLOSES, so after an L/R it really is stale — keep
                        // the suppression here and say so in the log.
                        else if (SettingsXmlDb.TryValueText(row.pref, row.optionType, out xv))
                        {
                            if (mrRowLrCount > 0)
                                MLog("EVENT reader-value-nolive: pref=" + row.pref
                                    + " src=settingsxml lr=" + mrRowLrCount);
                            else
                            {
                                MLog("EVENT reader-value: pref=" + row.pref + " src=settingsxml text=\"" + xv + "\"");
                                rowText = label + ", " + xv;
                            }
                        }
                        else
                        {
                            MLog("EVENT settingsxml-unmapped: pref=" + row.pref
                                + " optionType=" + row.optionType + " pane=" + mrCurrentPane);
                        }
                    }
                    return rowText + ReaderPositionSuffix(row);
                }
                // v1.4: pane= is what offline pinning needs — an unmapped uid is
                // only actionable once you know which pane it was focused in.
                MLog((res == MenuLabelDb.LabelResult.GxtFailed
                        ? "EVENT reader-gxt-fail: menu=51 item=" : "EVENT reader-unmapped: menu=51 item=")
                    + uniqueId + " pane=" + mrCurrentPane);
                return "unknown setting";
            }

            if (MenuLabelDb.TryMenuLabel(menuId, out label))
                return label; // category/link rows: label alone, no id suffix

            MLog("EVENT reader-unmapped: menu=" + menuId + " item=" + uniqueId
                + " pane=" + mrCurrentPane);
            return "unknown setting";
        }

        /// <summary>A3: ", 2 of 17" for a settings row, or "" when we cannot say it
        /// honestly. A sighted player reads their position off the scrollbar; before
        /// v1.5 a blind one had no way to know whether a list had three rows left or
        /// thirty, which turns "find the setting I want" into arrowing until the
        /// names repeat.
        ///
        /// Both inputs must come from a real traversal, which is why this stays
        /// silent until a calibration session has walked the pane. The table cannot
        /// supply either one: it lists 17 Audio rows where the build shows 11, and
        /// its `ord` counts pref rows only, skipping the hashed trigger rows
        /// (Restore Defaults and friends) that sit in the same visible list. A
        /// position is only as trustworthy as its total, and "2 of 17" in a list of
        /// eleven is exactly the kind of confident wrong answer this reader exists
        /// to not give. `EVENT reader-position-nodata` names the panes still
        /// waiting on data, once each per menu visit.</summary>
        private string ReaderPositionSuffix(MenuLabelDb.RowEntry row)
        {
            if (getSetting("menuReaderPosition") != 1) return "";
            if (row == null || !row.ord.HasValue || mrCurrentPane == 0) return "";
            int total; string src;
            if (!MenuLabelDb.TryPaneRowCount(mrCurrentPane, out total, out src))
            {
                if (mrPositionNoDataLogged.Add(mrCurrentPane))
                    MLog("EVENT reader-position-nodata: pane=" + mrCurrentPane
                        + " derived=" + MenuLabelDb.DerivedPaneRowCount(mrCurrentPane)
                        + " -- walk this pane fully, then align-panes.py --write");
                return "";
            }
            int pos = row.ord.Value + 1;
            if (pos > total)
            {
                MLog("EVENT reader-position-overflow: pane=" + mrCurrentPane
                    + " ord=" + row.ord.Value + " n=" + total + " src=" + src);
                return "";
            }
            MLog("EVENT reader-position: pane=" + mrCurrentPane
                + " ord=" + row.ord.Value + " n=" + total + " src=" + src);
            return ", " + pos + " of " + total;
        }

        /// <summary>A4: rows the game will answer for directly. Small on purpose —
        /// every entry here is a native whose meaning is unambiguous, because the
        /// whole point of the provider chain is that a row says nothing rather than
        /// something wrong. Fail-closed like every other link in the chain.</summary>
        private bool TryNativeValueText(string pref, out string text)
        {
            text = null;
            if (pref == null) return false;
            try
            {
                if (pref == "PREF_RADIO_STATION")
                {
                    // The player's current station. OFF is a real, selectable value
                    // here, and the native returns the empty string for it.
                    string s = Function.Call<string>(Hash.GET_PLAYER_RADIO_STATION_NAME);
                    if (string.IsNullOrEmpty(s))
                    {
                        text = "off";
                        return true;
                    }
                    // The native yields the internal name (RADIO_01_CLASS_ROCK);
                    // the GXT for it is what the menu itself displays.
                    text = MenuLabelDb.ResolveGxt(s) ?? s.Replace('_', ' ');
                    return true;
                }
                if (pref == "PREF_MEASUREMENT_SYSTEM")
                {
                    text = Function.Call<bool>(Hash.SHOULD_USE_METRIC_MEASUREMENTS) ? "metric" : "imperial";
                    return true;
                }
            }
            catch { }
            return false;
        }

        // Activation earcon: same replay pattern the interactable scanner uses.
        private void PlayReaderEarcon()
        {
            try
            {
                if (interactSound == null || outInteract == null) return;
                outInteract.Stop();
                interactSound.Position = 0;
                outInteract.Init(interactSound);
                outInteract.Play();
            }
            catch { }
        }

        private void TickMenuReader()
        {
            if (!mrReaderEnabled)
            {
                // v1.2 (fix 9): full state reset so nothing stale survives a
                // toggle-off (stale pending speech / commit summaries spoke
                // minutes later in v1.1's design review).
                menuReaderMenuOpen = false;
                mrMenuOpen = false;
                mrPhoneWasOpen = false;
                mrPendingSpeech = null;
                mrCommitSummary = null;
                mrReaderWasEnabled = false;
                mrPaneChain.Clear();
                mrPaneChainPane = 0;
                // v1.5: a held open line must not survive a toggle-off either —
                // same reasoning as mrPendingSpeech above.
                mrPendingOpenText = null;
                mrOpenSettleAt = DateTime.MinValue;
                mrOpenAnnounced = false;
                return;
            }
            if (!mrSnapValid) return;

            // ---- pause menu open/close edges ----
            if (mrSnap.Active && !mrMenuOpen)
            {
                mrMenuOpen = true;
                mrOpenAt = DateTime.Now;
                mrLastD1 = int.MinValue;
                mrLastD2 = int.MinValue;
                mrCandD1 = int.MinValue; mrCandD2 = int.MinValue; mrCandStable = false;
                mrCurrentPane = 0;
                mrAcceptPending = false;
                mrPositionNoDataLogged.Clear(); // one reminder per pane per visit
                MenuLabelDb.RetryFailedGxt(); // fix 9: transient GXT misses get one retry per open
                // v1.4: GTA rewrites settings.xml when the pause menu closes, so a
                // per-open re-read is exactly in step with the values on screen.
                SettingsXmlDb.Reload();
                MLog("EVENT labeldb-version: status=" + MenuLabelDb.LoadStatus
                    + " overrides=" + MenuLabelDb.OverridesApplied
                    + " settingsXml=" + SettingsXmlDb.LoadStatus
                    + " binds=" + MenuBindDb.LoadStatus);
                // A5: compose the open line now (tab state is seeded here) but
                // hold it until the frontend proves it is staying open.
                mrOpenAnnounced = false;
                mrOpenSettleAt = mrOpenAt.AddMilliseconds(MR_OPEN_SETTLE_MS);
                if (!mrReaderWasEnabled && mrReaderEnabled)
                {
                    // Reader enabled while a menu is ALREADY up: tab identity
                    // unknown — don't pretend we're on Map.
                    mrTabIndex = -1;
                    mrAtTabLevel = false;
                    mrPendingOpenText = "Menu reader on.";
                }
                else
                {
                    // SP pause always opens on the Map tab — seed the tracker.
                    mrTabIndex = 0;
                    mrAtTabLevel = true;
                    mrLastInputWasTabArrow = false;
                    mrPendingOpenText = "Pause menu. " + MenuLabelDb.TabName(0) + " tab.";
                }
            }
            else if (!mrSnap.Active && mrMenuOpen)
            {
                mrMenuOpen = false;
                menuReaderMenuOpen = false;
                mrPendingSpeech = null; // drop stale row chatter
                FlushRowVisit();
                FlushPaneChain(); // D6: emit the last pane's traversal on close
                // A5: an open that never settled was never announced, so there is
                // nothing to close from the user's point of view. Log it — a rising
                // flicker rate is the signature of the Esc-hijack regressing.
                if (mrOpenAnnounced)
                {
                    MrAnnounce("Menu closed", "info");
                }
                else
                {
                    MLog("EVENT reader-open-flicker: aliveMs="
                        + (int)(DateTime.Now - mrOpenAt).TotalMilliseconds
                        + " state=" + mrSnap.State);
                }
                mrPendingOpenText = null;
                mrOpenSettleAt = DateTime.MinValue;
                mrOpenAnnounced = false;
                mrFocusedPref = null;
                mrFocusedOptionType = null;
                mrFocusedLabel = null;
                // v1.5: persist anything learned this visit. Close is the right
                // moment — a settings walk yields a dozen bindings and this is the
                // one point where the player is provably not driving.
                MenuBindDb.Save(MLog);
                // settings changes mostly commit on close — announce the
                // summary TickProfileShared collected this tick, if any. This is
                // NOT gated on the open having settled: a real commit means the
                // user did change something and must hear it either way.
                if (mrCommitSummary != null)
                {
                    MrAnnounce(mrCommitSummary, "summary");
                    mrCommitSummary = null;
                }
            }
            mrReaderWasEnabled = true;

            // A5: the held open line fires once the menu has stayed up.
            if (mrPendingOpenText != null && mrSnap.Active && DateTime.Now >= mrOpenSettleAt)
            {
                MrAnnounce(mrPendingOpenText, "info");
                mrPendingOpenText = null;
                mrOpenAnnounced = true;
            }

            if (mrMenuOpen)
            {
                // Suppression flag for the mod's own gameplay audio: true only
                // for OUR unpaused menu. The P-menu really pauses, so ticks
                // stop there anyway; Game.IsPaused covers its transition frames.
                menuReaderMenuOpen = !Game.IsPaused;
                ReaderPauseTick();
            }

            ReaderPhoneTick();
            MrDrainSpeech();
        }

        // Row-visit calibration record: emitted when the highlight leaves a
        // row (or the menu closes). Pairs with close-time profile-commit-diffs
        // offline to bind uid <-> profile id <-> label.
        private void FlushRowVisit()
        {
            if (mrRowEnterAt == DateTime.MinValue || mrLastD1 == int.MinValue) return;
            int dwell = (int)(DateTime.Now - mrRowEnterAt).TotalMilliseconds;
            if (dwell > 150)
                MLog("EVENT row-visit: menu=" + mrLastD1 + " item=" + mrLastD2
                    + " dwellMs=" + dwell + " lr=" + mrRowLrCount);
            mrRowEnterAt = DateTime.MinValue;
            mrRowLrCount = 0;
        }

        // D6: emit the accumulated pref-row traversal for one pane so the offline
        // aligner (tools/align-panes.py) can pin the 63 unpinned uids by matching
        // the observed order against pausemenu.xml's row order.
        private void FlushPaneChain()
        {
            if (mrPaneChain.Count > 0 && mrPaneChainPane != 0)
                MLog("EVENT pane-chain: pane=" + mrPaneChainPane
                    + " chain=" + string.Join(",", mrPaneChain));
            mrPaneChain.Clear();
            mrPaneChainPane = 0;
        }

        private void ReaderPauseTick()
        {
            DateTime now = DateTime.Now;

            // Shadow tab tracker: tab identity is NOT exposed by any native
            // (~70% of tab moves are silent), so count left/right at tab level,
            // seeded at Map on open, and let the 3 leaking tabs resync us.
            bool tabArrow = false;
            if (mrAtTabLevel)
            {
                int dir = 0;
                if ((mrSnap.InputEvents & MR_IN_LEFT) != 0) dir--;
                if ((mrSnap.InputEvents & MR_IN_RIGHT) != 0) dir++;
                if (dir != 0 && mrTabIndex >= 0)
                {
                    int n = MenuLabelDb.TabCount;
                    mrTabIndex = ((mrTabIndex + dir) % n + n) % n;
                    MrSpeak(MenuLabelDb.TabName(mrTabIndex) + " tab", "tab");
                    tabArrow = true;
                }
            }
            if (tabArrow)
            {
                mrLastInputWasTabArrow = true;
                mrTabArrowAt = now;
            }
            else if ((mrSnap.InputEvents & (MR_IN_UP | MR_IN_DOWN | MR_IN_ACCEPT | MR_IN_CANCEL)) != 0)
            {
                mrLastInputWasTabArrow = false;
            }
            // v1.2: the arrow flag expires — it must not linger into content
            // panes where category rows share the (leakId, 0) signature.
            if (mrLastInputWasTabArrow && (now - mrTabArrowAt).TotalMilliseconds > 1000)
                mrLastInputWasTabArrow = false;

            // v1.2 row-visit stats: count L/R presses on the focused row.
            if ((mrSnap.InputEvents & (MR_IN_LEFT | MR_IN_RIGHT)) != 0 && !mrAtTabLevel)
                mrRowLrCount++;

            // v1.2 accept feedback diagnostics.
            if ((mrSnap.InputEvents & MR_IN_ACCEPT) != 0)
            {
                mrAcceptPending = true;
                mrAcceptAt = now;
            }
            if (mrSnap.ActivatePulse)
            {
                mrAcceptPending = false;
                PlayReaderEarcon();
                MLog("EVENT reader-earcon: kind=activate");
                // Category activation: the highlighted category's menuId (last
                // stable d1, a settings-pane screen id) becomes the current
                // pane for the honesty gate.
                // v1.4: NOT when activating from the tab strip. Opening the
                // SETTINGS tab activates with mrLastD1 = 24, the tab's leak
                // anchor, which seeded the pane as Controls while the user was
                // actually standing in the category list (screen 6).
                if (mrLastD1 > 0 && mrLastD1 != 51 && mrLastD1 != mrCurrentPane && !mrAtTabLevel)
                {
                    string paneLabel;
                    if (MenuLabelDb.TryMenuLabel(mrLastD1, out paneLabel))
                    {
                        mrCurrentPane = mrLastD1;
                        mrPaneKeysUntrusted = false; // fresh pane, keys trusted until proven otherwise
                        MLog("EVENT reader-pane: pane=" + mrCurrentPane + " via=activate");
                    }
                }
            }
            else if (mrAcceptPending && (now - mrAcceptAt).TotalMilliseconds > 250)
            {
                mrAcceptPending = false;
                MLog("EVENT accept-noop:");
            }

            // v1.2 stability gate: a (d1,d2) pair must survive two consecutive
            // ticks before it is spoken — kills fused mid-transition id pairs
            // like "Incept Trigger, item 148".
            int d1 = mrSnap.D1, d2 = mrSnap.D2;
            if (d1 == mrLastD1 && d2 == mrLastD2) return;
            if (d1 != mrCandD1 || d2 != mrCandD2)
            {
                mrCandD1 = d1;
                mrCandD2 = d2;
                mrCandStable = false;
                return; // first sighting — wait one tick
            }
            if (!mrCandStable) mrCandStable = true;

            // Transition/internal suppression (fix 4): all d1==-1 selections
            // are activation transients; internal ids never speak.
            if (d1 == -1)
            {
                FlushRowVisit();
                mrLastD1 = d1;
                mrLastD2 = d2;
                return;
            }

            // Leak resync (v1.2, two paths): arrow-armed within 1 s, OR the
            // flagless path — leak arriving while we still believe we're at
            // tab level (heals mouse clicks that generate no key events).
            int leakTab;
            bool isLeak = d2 == 0 && MenuLabelDb.TryTabForLeakId(d1, out leakTab);
            // v1.4: a (leakId, 0) selection is ambiguous — it is BOTH the tab strip
            // resting on that tab and the first row of that tab's content list.
            // v1.3 always took it as a tab move and returned silently, so pressing
            // Down from the tab strip into the list spoke NOTHING: in the 2026-07-20
            // log, Settings->Down (to "Controls") and Game->Down were both silent,
            // then the user pressed Up 20 more times into a menu they could not
            // hear. A vertical keypress this tick disambiguates it as a descent.
            bool leakDescent = isLeak && mrAtTabLevel && !tabArrow
                               && (mrSnap.InputEvents & (MR_IN_UP | MR_IN_DOWN)) != 0;
            if (isLeak && (mrLastInputWasTabArrow || mrAtTabLevel) && !leakDescent)
            {
                MenuLabelDb.TryTabForLeakId(d1, out leakTab);
                if (leakTab != mrTabIndex)
                {
                    MLog("EVENT reader-tab-resync: shadow=" + mrTabIndex + " actual=" + leakTab);
                    mrTabIndex = leakTab;
                    MrSpeak(MenuLabelDb.TabName(mrTabIndex) + " tab", "tab");
                }
                mrAtTabLevel = true;
                mrCurrentPane = 0;
                mrPaneKeysUntrusted = false;
                FlushRowVisit();
                mrLastD1 = d1;
                mrLastD2 = d2;
                return;
            }
            if (leakDescent)
            {
                // Keep the shadow tab tracker honest (the leak id still names the
                // tab), then fall through so the newly focused row is spoken.
                MenuLabelDb.TryTabForLeakId(d1, out leakTab);
                if (leakTab != mrTabIndex)
                {
                    MLog("EVENT reader-tab-resync: shadow=" + mrTabIndex + " actual=" + leakTab);
                    mrTabIndex = leakTab;
                }
                MLog("EVENT reader-tab-descend: tab=" + mrTabIndex + " row=" + d1);
            }

            // B1: the menu-close sentinel (LastMenuId == -1000, arriving as
            // d1=0 d2=-1) is NOT a tab move — swallow it so it neither resets the
            // pane nor speaks a phantom tab on the way out.
            if (mrSnap.LastMenuId == -1000)
            {
                FlushRowVisit();
                mrLastD1 = d1;
                mrLastD2 = d2;
                return;
            }

            // B2 ordinal-monotonicity: inside a known pane, Down must raise the
            // visible ordinal and Up must lower it. A small wrong-direction move
            // (magnitude 1-2, so not a top<->bottom wrap) means this pane's row
            // keys don't match visible order -> distrust the whole pane, so every
            // row in it speaks with the unverified cue. Defends against the next
            // enum renumber (this is how the +4 shift produced confident lies).
            if (d1 == 51 && mrLastD1 == 51 && mrCurrentPane != 0 && !mrPaneKeysUntrusted)
            {
                int upDown = (mrSnap.InputEvents & MR_IN_UP) != 0 ? -1
                           : (mrSnap.InputEvents & MR_IN_DOWN) != 0 ? 1 : 0;
                MenuLabelDb.RowEntry pr, cr;
                if (upDown != 0
                    && MenuLabelDb.TryGetRow(51, mrLastD2, out pr) && pr.ord.HasValue
                    && MenuLabelDb.TryGetRow(51, d2, out cr) && cr.ord.HasValue
                    && pr.screenMenuId == mrCurrentPane && cr.screenMenuId == mrCurrentPane)
                {
                    int delta = cr.ord.Value - pr.ord.Value;
                    bool violation = (upDown > 0 && delta < 0 && delta > -3)
                                  || (upDown < 0 && delta > 0 && delta < 3);
                    if (violation)
                    {
                        mrPaneKeysUntrusted = true;
                        MLog("EVENT reader-ordinal-violation: pane=" + mrCurrentPane
                            + " a=" + mrLastD2 + " aOrd=" + pr.ord.Value
                            + " b=" + d2 + " bOrd=" + cr.ord.Value + " dir=" + upDown);
                    }
                }
            }

            FlushRowVisit();
            // B1: tab-level = a headerless selection (d2==-1) on the tab strip
            // (Map=0) or the Settings category list (6). The old test (d1==0)
            // only matched Map, so backing out of any other tab (d1=6) left the
            // reader in row mode and tab arrows spoke row names. (Predicate still
            // pending in-session confirmation for the Brief/Game tab strips.)
            bool atTabNow = (d2 == -1) && (d1 == 0 || d1 == 6);
            if (atTabNow)
            {
                mrAtTabLevel = true;
                mrCurrentPane = 0;
                mrPaneKeysUntrusted = false;
                MLog("EVENT reader-tablevel: d1=" + d1);
                // Backed out to the tab bar — re-anchor (but not right after
                // open, where it would double the open announcement).
                if (mrLastD1 != int.MinValue && (now - mrOpenAt).TotalMilliseconds > 1500 && mrTabIndex >= 0)
                    MrSpeak(MenuLabelDb.TabName(mrTabIndex) + " tab", "tab");
            }
            else
            {
                mrAtTabLevel = false;
                if (d2 < 0)
                {
                    // Back-out to a screen header — speak the screen alone.
                    string screenLabel;
                    if (MenuLabelDb.TryMenuLabel(d1, out screenLabel))
                        MrSpeak(screenLabel, "row");
                }
                else
                {
                    string text = ReaderRowText(d1, d2);
                    // A2: unverified rows (unpinned band / distrusted pane) speak
                    // a spoken cue so the user knows the name may be wrong.
                    if (text != null) MrSpeak((mrRowCue ? "unverified, " : "") + text, "row");
                    // D6: accumulate the traversal (mrCurrentPane may be updated
                    // inside ReaderRowText, so read it after). v1.5 records hashed
                    // trigger rows too — they occupy visible positions, so a chain
                    // without them describes a shorter list than the one the user
                    // is arrowing through.
                    if (mrCurrentPane != 0 && (d1 == 51 || MenuLabelDb.IsHashedItem(d1)))
                    {
                        if (mrCurrentPane != mrPaneChainPane) { FlushPaneChain(); mrPaneChainPane = mrCurrentPane; }
                        string token = d1 == 51 ? d2.ToString() : "h" + d1;
                        if (mrPaneChain.Count == 0 || mrPaneChain[mrPaneChain.Count - 1] != token)
                            mrPaneChain.Add(token);
                    }
                }
                mrRowEnterAt = now;
                mrRowLrCount = 0;
            }
            mrLastD1 = d1;
            mrLastD2 = d2;
        }

        // True when a specific phone app script is currently running (bit set in
        // the app mask). Used to branch in-app selection reading (e.g. Contacts).
        private bool PhoneAppRunning(string name)
        {
            if (mlAppNames == null) return false;
            for (int i = 0; i < mlAppNames.Length; i++)
                if ((mlAppMask & (1u << i)) != 0 && mlAppNames[i] == name) return true;
            return false;
        }

        private void ReaderPhoneTick()
        {
            // v1.2 overlap guard: phone + pause menu simultaneously (v1.1 log:
            // burst of interleaved announcements). Pause reader owns the voice;
            // phone edges keep tracking silently.
            bool overlap = mlPhoneOpen && mrSnap.Active;
            if (overlap && !mrOverlapLogged)
            {
                MLog("EVENT frontend-overlap:");
                mrOverlapLogged = true;
            }
            else if (!overlap)
            {
                mrOverlapLogged = false;
            }

            if (mlPhoneOpen && !mrPhoneWasOpen)
            {
                mrPhoneWasOpen = true;
                mrPhoneLastRow = int.MinValue;
                mrPhoneLastAppMask = 0;
                mrPhoneStableHomeRow = int.MinValue;
                mrPhoneRowStableAt = DateTime.MinValue;
                mrPhoneApp = null;
                mrPhoneBackToHome = false;
                mrPhoneForceRowAt = DateTime.MinValue;
                string brand = mlPhoneMovie == "cellphone_badger" ? "Badger"
                    : mlPhoneMovie == "cellphone_facade" ? "Facade" : "iFruit";
                if (!overlap) MrAnnounce(brand + " phone", "phone");
                // Arm the one-shot CELL_* dump on the first phone open of a
                // logged session (mrGxtDumpNext starts at -1 and is set to -1
                // again when finished, so this fires exactly once).
                if (menuLogWasEnabled && mrGxtDumpNext == -1 && !mrGxtDumpDone)
                {
                    mrGxtDumpNext = 0;
                    mrGxtDumpDone = true;
                }
            }
            else if (!mlPhoneOpen && mrPhoneWasOpen)
            {
                mrPhoneWasOpen = false;
                mrPendingSpeech = null;
                // v1.4: gate this like every other phone utterance. Open/app/row
                // were all !overlap-guarded but the close was not, so it spoke
                // over the pause reader (2026-07-20 log F8318).
                if (!overlap) MrAnnounce("Phone closed", "phone");
            }
            if (!mrPhoneWasOpen) return;

            // v1.2 stable home row: the last row that held >=250 ms with no app
            // open. Immune to the app-launch selection-reset race that poisoned
            // the slot-corrected diagnostic (audit finding).
            DateTime pnow = DateTime.Now;
            if (mlAppMask == 0 && mlPhoneRow != int.MinValue
                && mrPhoneRowStableAt != DateTime.MinValue
                && (pnow - mrPhoneRowStableAt).TotalMilliseconds >= 250)
                mrPhoneStableHomeRow = mlPhoneRow;

            if (mlAppMask != mrPhoneLastAppMask && mlAppNames != null)
            {
                uint gained = mlAppMask & ~mrPhoneLastAppMask;
                if (gained != 0)
                {
                    for (int i = 0; i < mlAppNames.Length; i++)
                    {
                        if ((gained & (1u << i)) == 0) continue;
                        string friendly = MenuLabelDb.PhoneAppLabel(mlAppNames[i]);
                        if (!overlap) MrSpeak((friendly ?? mlAppNames[i]) + " app", "phone");
                        mrPhoneApp = mlAppNames[i];
                        // v1.4: make sure the first IN-APP row gets announced. It
                        // was only forced on the app-CLOSE edge, so entering an app
                        // from home row N onto in-app row N stayed silent.
                        //
                        // Deliberately NOT `mrPhoneLastRow = int.MinValue`: the
                        // scaleform poll is ~200 ms behind, so mlPhoneRow is still
                        // the HOME row for a few frames after the app opens and
                        // that would announce the old row as an in-app one (the
                        // exact mirror of the B4 bug). Instead keep suppressing,
                        // and arm a short timer that speaks the row if it turns out
                        // to be identical to the one we came from.
                        mrPhoneForceRowAt = pnow.AddMilliseconds(400);
                        // C1: Contacts opened — locate the char-sheet globals once
                        // (fail-closed) and dump diagnostics (no-op unless logging).
                        if (mlAppNames[i] == "appcontacts")
                        {
                            PhoneGlobals.Detect();
                            PhoneGlobals.Dump(MLog);
                            MLog("EVENT phone-contacts: globalsOk=" + (PhoneGlobals.Ok ? 1 : 0));
                        }
                        // v1.5: the Texts/Email store sweep is GONE. It ran four
                        // sessions and only ever rediscovered the char sheet — the
                        // apps read their senders out of it, and their list rows go
                        // through the shared row-label array PhoneRowText reads.
                        //
                        // B3: locate that array's page for the app that just opened.
                        // Per app, not per phone-open: the page moves with the app,
                        // so one probed at the home grid would be stale immediately.
                        // Runs whenever menulog is on even with the gate OFF —
                        // collecting the evidence is what lets the gate be flipped
                        // on with confidence instead of hopefully.
                        if (getSetting("phoneRowTextV2") == 1 || menuLogWasEnabled)
                            PhoneRowText.Probe(PhoneCharIndex(), mlAppNames[i], MLog);
                        // Slot ground truth vs the table — using the STABLE
                        // home row; known mission overrides are not "errors".
                        if (MenuLabelDb.IsKnownSlotOverride(mlPhoneMovie, mrPhoneStableHomeRow, mlAppNames[i]))
                        {
                            MLog("EVENT phone-slot-override: row=" + mrPhoneStableHomeRow
                                + " script=" + mlAppNames[i]);
                        }
                        else
                        {
                            string expected = MenuLabelDb.PhoneHomeScript(mlPhoneMovie, mrPhoneStableHomeRow);
                            if (expected != null
                                && !string.Equals(expected, mlAppNames[i], StringComparison.OrdinalIgnoreCase))
                                MLog("EVENT phone-slot-corrected: row=" + mrPhoneStableHomeRow
                                    + " expected=" + expected + " actual=" + mlAppNames[i]);
                        }
                        break;
                    }
                }
                else if (mlAppMask == 0)
                {
                    // B4: app closed, back on the home grid. mlPhoneRow is still
                    // the last IN-APP row here (stale), so speaking it named the
                    // wrong tile ("Texts" after exiting Contacts). Force the next
                    // real phone-row change to re-announce the true home tile.
                    mrPhoneLastRow = int.MinValue;
                    // v1.5: the row-label page belonged to the app that just
                    // closed. Drop it rather than let the home grid read rows out
                    // of a dead app's list.
                    PhoneRowText.Reset();
                    // v1.4: mark the return to the grid so the tile announcement
                    // can carry it. A separate "Contacts closed" utterance would
                    // just be interrupted by the tile name a tick later (or
                    // swallowed by the coalescer); folding it into one line —
                    // "Home, Contacts" — says both in the time of one.
                    mrPhoneBackToHome = true;
                    mrPhoneApp = null;
                }
                mrPhoneLastAppMask = mlAppMask;
            }

            PhoneGlobals.Tick(MLog);
            GxtDumpTick();

            // The armed timer fires only if the row never changed after entering an
            // app (identical home and in-app index); any real move clears it below.
            bool forceRow = mrPhoneForceRowAt != DateTime.MinValue && pnow >= mrPhoneForceRowAt
                            && mlAppMask != 0 && mlPhoneRow != int.MinValue;
            if (forceRow) mrPhoneForceRowAt = DateTime.MinValue;

            if ((mlPhoneRow != mrPhoneLastRow || forceRow) && mlPhoneRow != int.MinValue)
            {
                if (mlPhoneRow != mrPhoneLastRow) mrPhoneForceRowAt = DateTime.MinValue;
                mrPhoneRowStableAt = pnow; // stable-row clock restarts on movement
                if (mlAppMask == 0)
                {
                    // B5: prefer the game's own home grid when we can read it. The
                    // grid is DYNAMIC by mission context — which is exactly what
                    // every phone-slot-corrected event in the logs reports — so a
                    // live read beats the shipped table, and it is the only way to
                    // know a tile is greyed out. The phone signals that with a
                    // transparent icon (CELL_36 spells the convention out) and says
                    // nothing, so before v1.5 a blind user could only discover an
                    // unavailable app by pressing Accept and hearing nothing happen.
                    string lbl = null;
                    bool tileAvailable = true;
                    bool liveGrid = false;
                    if (getSetting("phoneRowTextV2") == 1)
                        liveGrid = PhoneRowText.TryHomeTile(mlPhoneRow, out lbl, out tileAvailable);
                    if (!liveGrid)
                        tileAvailable = true;   // static table cannot know — never claim locked
                    if (lbl == null)
                    {
                        // An unavailable slot carries no live label, so name it from
                        // the static table: "Quick Save, unavailable" is useful,
                        // "row 5, unavailable" is not.
                        lbl = MenuLabelDb.PhoneHomeLabel(mlPhoneMovie, mlPhoneRow);
                        if (lbl == null && tileAvailable)
                            MLog("EVENT reader-unmapped-phone: movie=" + mlPhoneMovie + " row=" + mlPhoneRow
                                + " live=" + (liveGrid ? 1 : 0));
                    }
                    string tile = lbl ?? (tileAvailable ? "row " + mlPhoneRow : "empty");
                    if (!tileAvailable && lbl != null)
                        tile = tile + ", " + (MenuLabelDb.ResolveGxt("CELL_34") ?? "unavailable");
                    if (mrPhoneBackToHome)
                    {
                        tile = "Home, " + tile;
                        mrPhoneBackToHome = false;
                    }
                    if (!overlap) MrSpeak(tile, "phone");
                }
                else
                {
                    string text = PhoneAppRowText(mlPhoneRow);
                    if (!overlap) MrSpeak(text, "phone");
                }
                mrPhoneLastRow = mlPhoneRow;
            }
        }

        // One-shot dump of the game's CELL_* string table, spread across frames so
        // it never hitches. This is a data-acquisition tool, not a feature: the
        // phone app row tables (phoneAppRows) need real GXT keys, and there is no
        // offline source for them the way pausemenu.xml serves the pause menu.
        // Runs only while menuDebugLog is on, at most once per session.
        private void GxtDumpTick()
        {
            if (mrGxtDumpNext < 0 || !menuLogWasEnabled) return;
            int budget = 40;
            while (budget-- > 0 && mrGxtDumpNext < MR_GXT_DUMP_MAX)
            {
                string key = "CELL_" + mrGxtDumpNext;
                try
                {
                    string txt = Game.GetLocalizedString(key);
                    // Skip the misses: GTA returns the key itself or NULL for an
                    // undefined label, and those are just noise in the log.
                    if (!string.IsNullOrEmpty(txt) && txt != "NULL" && txt != key)
                        MLog("EVENT gxt-dump: key=" + key + " text=\"" + txt + "\"");
                }
                catch { }
                mrGxtDumpNext++;
            }
            if (mrGxtDumpNext >= MR_GXT_DUMP_MAX)
            {
                MLog("EVENT gxt-dump: done scanned=" + MR_GXT_DUMP_MAX);
                mrGxtDumpNext = -1;
            }
        }

        // Label for a row INSIDE a phone app. Resolution order, each step
        // fail-closed to the next:
        //   1. static table  - apps whose row list never changes (Phone Settings,
        //      Internet, Checklist...), data-driven via phoneAppRows.
        //   2. globals       - dynamic content; only Contacts is pinned so far.
        //   3. "row N"       - honest fallback. NEVER guess an in-app label.
        // Every unresolved row is harvested: v1.3 logged reader-unmapped-phone on
        // the home grid ONLY, so in-app rows produced no calibration signal at all
        // and there was nothing in the log to build a table from.
        private string PhoneAppRowText(int row)
        {
            string script = mrPhoneApp;
            if (script != null)
            {
                string stat = MenuLabelDb.PhoneAppRowLabel(script, row);
                if (stat != null) return stat;
            }
            // iter-51: CONTACTS FIRST.
            //
            // v1.5 put PhoneRowText above this on the reasoning that the live row
            // array is "the text actually on screen". That premise only holds when
            // the probe picked the app's own page, and on 08-11 it picked a global
            // ringtone/wallpaper table for all four apps — so a confident wrong
            // answer shadowed a channel that was working perfectly
            // (phone-contacts globalsOk=1, csBase/rowMapBase/stride all pinned,
            // distrusted=0). The char sheet is authoritative for contacts by
            // construction: it is where the game keeps the contact names. It goes
            // first for appcontacts, and PhoneRowText keeps the rest.
            if (PhoneAppRunning("appcontacts") && PhoneGlobals.Ok)
            {
                string cname;
                if (PhoneGlobals.TryContactName(row, out cname, MLog)) return cname;
            }
            // The live row-label array every other phone app writes to. Gated — it
            // reads script globals whose page offset this build has not confirmed —
            // and PhoneRowText.Ok is now false whenever the probe could not find a
            // page that actually belongs to the open app.
            if (getSetting("phoneRowTextV2") == 1 && PhoneRowText.Ok)
            {
                string live;
                if (PhoneRowText.TryRowLabel(PhoneCharIndex(), row, out live)) return live;
            }
            MLog("EVENT reader-unmapped-phone: script=" + (script ?? "?")
                + " row=" + row + " hasTable=" + (MenuLabelDb.HasPhoneAppRows(script) ? 1 : 0)
                + " globalsOk=" + (PhoneGlobals.Ok ? 1 : 0));
            return "row " + row;
        }

        // Spoken form of a committed profile value: option lists resolve to
        // their localized word ("Headphones"), sliders to "N of 10", toggles
        // to on/off; raw number otherwise.
        private string ProfileValueText(int id, int value)
        {
            MenuLabelDb.ProfilePref pp;
            if (MenuLabelDb.TryProfilePref(id, out pp) && pp != null && pp.optionType != null)
                return ProfileValueText(value, pp.optionType);
            return value.ToString();
        }

        /// <summary>v1.5 overload keyed on the optionType directly rather than on a
        /// profilePrefs entry. The ROW already carries its optionType in
        /// gta11y-menulabels.json, so a freshly learned binding speaks in words
        /// ("Headphones", "9 of 10", "on") on the very first press — the id-keyed
        /// path could only ever say a bare number until someone hand-added a
        /// profilePrefs entry for it.</summary>
        private string ProfileValueText(int value, string optionType)
        {
            if (optionType != null)
            {
                if (optionType == "MENU_OPTION_SLIDER") return value + " of 10";
                string word;
                if (MenuLabelDb.TryOptionValueLabel(optionType, value, out word)) return word;
                if (optionType == "MENU_OPTION_DISPLAY_ON_OFF") return value != 0 ? "on" : "off";
            }
            return value.ToString();
        }
        #endregion

        #region WORLD DIRECTORY (iter-52)
        // Collectibles and places harvested from Rockstar's own scripts (WorldDataDb).
        // This is content that is purely visual in vanilla: 50 letter scraps and 50
        // spaceship parts with no in-game hint of where they are, 12 underwater loot
        // caches, and 63 Strangers & Freaks meeting points that are a blip on a map a
        // blind player cannot read. Nothing here is queryable from a native.

        private int worldMenuIndex = 0;

        /// <summary>A row in the World Directory. Summary rows carry text only; target
        /// rows carry a position you can be routed to.</summary>
        private struct DirEntry
        {
            public string Label;              // spoken text, minus the distance suffix
            public bool IsTarget;
            public GTA.Math.Vector3 Pos;
            public string Set;                // collectible set, or null for places
            public int Index;                 // collectible index, or -1
        }

        private readonly List<DirEntry> worldDirectory = new List<DirEntry>();

        // How many target rows the list shows. A blind user arrows this one row at a
        // time, so an uncapped 300-row list is unusable — but the cap is always spoken
        // (see the summary row), never silent.
        private const int WORLD_DIR_MAX_TARGETS = 20;

        // --- tracked target + audio homing ---------------------------------
        private bool trackedTargetActive = false;
        private GTA.Math.Vector3 trackedTargetPos;
        private string trackedTargetName = "";
        private long trackedTargetNextPulseTicks = 0;
        private long trackedTargetLastSpokeTicks = 0;
        private const float TRACKED_ARRIVE_M = 12f;

        // ===================================================================
        // Packed-stat calibration
        // ===================================================================
        // Collected-state for the hidden-package sets lives in GET_PACKED_STAT_BOOL_CODE
        // bits. The base index is not a literal in the script — it comes from a struct
        // field set up by a shared collectible framework — so rather than guess it we
        // read a window of packed bits once and find the base whose 50-bit popcount
        // matches STAT_GET_INT(num_hidden_packages_N), which the script itself uses for
        // the same purpose.
        //
        // If no base matches, or more than one does, calibration FAILS CLOSED: every
        // collectible is listed and the user is told once that the collected filter is
        // unavailable. Silently guessing would tell somebody they had already found
        // something they had not, and send them nowhere.
        private const int PACKED_SCAN_BITS = 8192;
        private const int PACKED_SCAN_PER_TICK = 256;   // ~32 ticks to sweep the window
        private bool[] packedBits = null;
        private int packedScanCursor = 0;
        private bool packedScanComplete = false;
        private readonly Dictionary<string, int> packedBaseFor = new Dictionary<string, int>();
        private readonly HashSet<string> packedBaseFailed = new HashSet<string>();
        private bool packedCalibrationSpoken = false;

        /// <summary>Reads the packed-bit window a slice at a time. Cheap per tick and
        /// only runs while a feature that needs it is on.</summary>
        private void TickPackedStatScan()
        {
            if (packedScanComplete) return;
            if (packedBits == null) packedBits = new bool[PACKED_SCAN_BITS];
            int end = Math.Min(PACKED_SCAN_BITS, packedScanCursor + PACKED_SCAN_PER_TICK);
            for (int i = packedScanCursor; i < end; i++)
            {
                try { packedBits[i] = Function.Call<bool>(Hash.GET_PACKED_STAT_BOOL_CODE, i, -1); }
                catch { packedBits[i] = false; }
            }
            packedScanCursor = end;
            if (packedScanCursor >= PACKED_SCAN_BITS)
            {
                packedScanComplete = true;
                CalibratePackedBases();
            }
        }

        private void CalibratePackedBases()
        {
            foreach (string set in WorldDataDb.CollectibleSets)
            {
                var indices = WorldDataDb.IndicesIn(set);
                if (indices.Count == 0) continue;
                string statSet = null;
                foreach (var c in WorldDataDb.RowsIn(set)) { statSet = c.statSet; break; }
                if (string.IsNullOrEmpty(statSet)) continue;

                int collected;
                try
                {
                    var arg = new OutputArgument();
                    Function.Call(Hash.STAT_GET_INT, Game.GenerateHash(statSet), arg, -1);
                    collected = arg.GetResult<int>();
                }
                catch { continue; }

                int n = indices.Count;
                // 0 and n are unusable: an all-zero or all-one window is not unique, so
                // there is nothing to calibrate against. That is fine — at 0 nothing is
                // filtered out anyway, and at n the count readout already says "all
                // found", so neither case needs the per-item bits.
                if (collected <= 0 || collected >= n)
                {
                    packedBaseFor[set] = collected >= n ? -2 : -1;   // -1 none, -2 all
                    continue;
                }

                int match = -1, matches = 0;
                for (int b = 0; b + n <= PACKED_SCAN_BITS; b++)
                {
                    int pop = 0;
                    for (int k = 0; k < n; k++) if (packedBits[b + k]) pop++;
                    if (pop != collected) continue;
                    matches++;
                    if (matches > 1) break;
                    match = b;
                }
                if (matches == 1) packedBaseFor[set] = match;
                else packedBaseFailed.Add(set);

                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT packed-calibrate:"
                        + " set=" + set + " stat=" + statSet + " collected=" + collected
                        + "/" + n + " matches=" + matches + " base=" + match);
            }
        }

        /// <summary>True when collectible `index` of `set` is already collected. Returns
        /// false whenever calibration did not produce a unique answer, so an uncertain
        /// DB shows you everything rather than hiding something you still need.</summary>
        private bool IsCollectibleCollected(string set, int index)
        {
            int b;
            if (!packedBaseFor.TryGetValue(set, out b)) return false;
            if (b == -1) return false;    // nothing collected yet
            if (b == -2) return true;     // all collected
            int bit = b + index;
            if (packedBits == null || bit < 0 || bit >= PACKED_SCAN_BITS) return false;
            return packedBits[bit];
        }

        private int CollectedCount(string statSet)
        {
            if (string.IsNullOrEmpty(statSet)) return -1;
            try
            {
                var arg = new OutputArgument();
                Function.Call(Hash.STAT_GET_INT, Game.GenerateHash(statSet), arg, -1);
                return arg.GetResult<int>();
            }
            catch { return -1; }
        }

        // ===================================================================
        // Directory build + menu text
        // ===================================================================

        private static string PrettySetName(string set)
        {
            switch (set)
            {
                case "letterscraps":      return "letter scraps";
                case "spaceshipparts":    return "spaceship parts";
                case "underwaterpickups": return "underwater caches";
                default:                  return set;
            }
        }

        /// <summary>Rebuilds the directory from the player's current position. Cheap
        /// enough to run on every menu entry (a few hundred distance computations), and
        /// running it on entry is what makes "nearest" mean nearest right now.</summary>
        private void RebuildWorldDirectory()
        {
            worldDirectory.Clear();

            if (!WorldDataDb.IsLoaded)
            {
                worldDirectory.Add(new DirEntry
                {
                    Label = "World data not loaded (" + WorldDataDb.LoadStatus
                          + "). Run build-worlddata and redeploy with data files.",
                    IsTarget = false, Index = -1
                });
                worldMenuIndex = 0;
                return;
            }

            GTA.Math.Vector3 me = Game.Player.Character.Position;
            bool wantCollectibles = getSetting("collectibleNav") == 1;
            bool wantPlaces = getSetting("placesDirectory") == 1;

            var targets = new List<DirEntry>();
            int suppressedCollected = 0;

            if (wantCollectibles)
            {
                foreach (string set in WorldDataDb.CollectibleSets)
                {
                    string pretty = PrettySetName(set);
                    var indices = WorldDataDb.IndicesIn(set);
                    string statSet = null;
                    foreach (var c in WorldDataDb.RowsIn(set)) { statSet = c.statSet; break; }

                    int found = CollectedCount(statSet);
                    string summary = found >= 0
                        ? pretty + ": " + found + " of " + indices.Count + " found"
                        : pretty + ": " + indices.Count + " locations";
                    if (packedBaseFailed.Contains(set))
                        summary += ", cannot tell which ones remain";
                    worldDirectory.Add(new DirEntry { Label = summary, IsTarget = false, Index = -1 });

                    foreach (int idx in indices)
                    {
                        if (IsCollectibleCollected(set, idx)) { suppressedCollected++; continue; }
                        GTA.Math.Vector3 p; float d;
                        if (!WorldDataDb.TryNearestVariant(set, idx, me, out p, out d)) continue;
                        targets.Add(new DirEntry
                        {
                            Label = pretty + " " + (idx + 1),
                            IsTarget = true, Pos = p, Set = set, Index = idx
                        });
                    }
                }

                // Counts the game tracks but gives no coordinates for — the geometry is
                // engine-side, so these can be reported but never navigated to. Saying
                // so is better than leaving a blind player hunting for a menu entry
                // that does not exist.
                int bridges = CollectedCount("sp_under_the_bridge_count");
                int knives = CollectedCount("sp_knife_flights_count");
                if (bridges >= 0 || knives >= 0)
                    worldDirectory.Add(new DirEntry
                    {
                        Label = "Stunt progress: " + (bridges >= 0 ? bridges : 0)
                              + " bridges flown under, " + (knives >= 0 ? knives : 0)
                              + " knife flights. No locations available for these.",
                        IsTarget = false, Index = -1
                    });
            }

            if (wantPlaces)
            {
                int n = 0;
                foreach (var p in WorldDataDb.Places)
                {
                    if (p == null) continue;
                    n++;
                    targets.Add(new DirEntry
                    {
                        Label = SpacedIdentifier(p.name ?? p.id),
                        IsTarget = true, Pos = p.Position, Set = null, Index = -1
                    });
                }
                worldDirectory.Add(new DirEntry
                {
                    Label = "Strangers and Freaks: " + n + " meeting points",
                    IsTarget = false, Index = -1
                });
            }

            if (!wantCollectibles && !wantPlaces)
            {
                worldDirectory.Add(new DirEntry
                {
                    Label = "Nothing enabled. Turn on Find collectibles or Find places in Settings.",
                    IsTarget = false, Index = -1
                });
                worldMenuIndex = 0;
                return;
            }

            // Say once, not every time the menu is opened, that the collected filter
            // could not be calibrated — otherwise the caveat becomes noise and stops
            // being heard. The per-set summary row still carries it every time.
            if (!packedCalibrationSpoken && packedScanComplete && packedBaseFailed.Count > 0)
            {
                packedCalibrationSpoken = true;
                Speech.Info("Note: cannot tell which collectibles you already have, "
                    + "so all of them are listed. ");
            }

            targets.Sort((a, b) => Dist2D(me, a.Pos).CompareTo(Dist2D(me, b.Pos)));

            int shown = Math.Min(WORLD_DIR_MAX_TARGETS, targets.Count);
            if (targets.Count > shown)
                worldDirectory.Add(new DirEntry
                {
                    Label = "Showing the nearest " + shown + " of " + targets.Count
                          + ". Walk or drive to reveal others.",
                    IsTarget = false, Index = -1
                });
            if (suppressedCollected > 0)
                worldDirectory.Add(new DirEntry
                {
                    Label = suppressedCollected + " already collected, hidden from this list.",
                    IsTarget = false, Index = -1
                });

            for (int i = 0; i < shown; i++) worldDirectory.Add(targets[i]);

            if (worldMenuIndex >= worldDirectory.Count) worldMenuIndex = 0;
        }

        /// <summary>"Barry3A" -> "Barry 3 A" so a screen reader does not run the digits
        /// into the name. Script ids are the only names Rockstar gives these.</summary>
        private static string SpacedIdentifier(string s)
        {
            if (string.IsNullOrEmpty(s)) return s;
            var sb = new System.Text.StringBuilder(s.Length + 6);
            for (int i = 0; i < s.Length; i++)
            {
                char c = s[i];
                if (i > 0 && (char.IsDigit(c) != char.IsDigit(s[i - 1])
                              || (char.IsUpper(c) && !char.IsUpper(s[i - 1]))))
                    sb.Append(' ');
                sb.Append(c == '_' ? ' ' : c);
            }
            return sb.ToString();
        }

        private string GetWorldMenuText(int index)
        {
            if (worldDirectory.Count == 0) RebuildWorldDirectory();
            if (index < 0 || index >= worldDirectory.Count) return "Empty. ";
            DirEntry e = worldDirectory[index];
            if (!e.IsTarget) return e.Label;

            GTA.Math.Vector3 me = Game.Player.Character.Position;
            float d = Dist2D(me, e.Pos);
            string dir = getDir(GetAngleOfLineBetweenTwoPoints(me, e.Pos));
            string tracking = (trackedTargetActive && trackedTargetName == e.Label)
                ? ", tracking" : "";
            return e.Label + ", " + ((int)d) + " metres " + dir + tracking + ". ";
        }

        private void HandleWorldMenuSelect(int index)
        {
            if (index < 0 || index >= worldDirectory.Count) return;
            DirEntry e = worldDirectory[index];
            if (!e.IsTarget)
            {
                // Selecting a summary row re-sorts from where you are standing now.
                RebuildWorldDirectory();
                Speech.Info("List refreshed. ");
                return;
            }

            if (trackedTargetActive && trackedTargetName == e.Label)
            {
                StopTrackedTarget("Tracking stopped. ");
                return;
            }

            trackedTargetActive = true;
            trackedTargetPos = e.Pos;
            trackedTargetName = e.Label;
            trackedTargetNextPulseTicks = 0;
            trackedTargetLastSpokeTicks = 0;

            try
            {
                Function.Call(Hash.SET_NEW_WAYPOINT, e.Pos.X, e.Pos.Y);
            }
            catch { /* waypoint is a convenience; homing works without it */ }

            GTA.Math.Vector3 me = Game.Player.Character.Position;
            Speech.Info("Tracking " + e.Label + ", " + ((int)Dist2D(me, e.Pos))
                + " metres " + getDir(GetAngleOfLineBetweenTwoPoints(me, e.Pos))
                + ". Waypoint set. ");
        }

        private void StopTrackedTarget(string say)
        {
            trackedTargetActive = false;
            trackedTargetName = "";
            if (!string.IsNullOrEmpty(say)) Speech.Info(say);
        }

        // ===================================================================
        // Audio homing
        // ===================================================================

        /// <summary>Pulses a tone toward the tracked target: pan follows its bearing
        /// relative to where you are facing, and the repeat rate rises as you close.
        /// Reuses the nav-assist emitter so it sits in the same mental model as the
        /// obstacle sonar — one more thing in the soundscape, not a new language.
        /// A distinct 880 Hz square keeps it clear of the obstacle timbres (440 ped,
        /// 620/480 vehicle, 330 wall, 1320 low).</summary>
        private void TickTargetHoming()
        {
            if (!trackedTargetActive) return;
            if (getSetting("collectibleNav") != 1 && getSetting("placesDirectory") != 1)
            {
                StopTrackedTarget(null);
                return;
            }

            Ped player = Game.Player.Character;
            GTA.Math.Vector3 me = player.Position;
            float dist = Dist2D(me, trackedTargetPos);

            if (dist <= TRACKED_ARRIVE_M)
            {
                EmitNavBeepRaw(1, 1200f, 0.16f, 0f, SignalGeneratorType.Sin, 0.12f);
                StopTrackedTarget("Arrived at " + trackedTargetName + ". ");
                return;
            }

            long now = ModClock.Ticks;
            if (now < trackedTargetNextPulseTicks) return;

            // Same distance-to-cadence shape the obstacle sonar uses: far is sparse,
            // near is urgent. Clamped so a 2 km target does not go silent for a minute.
            long gapMs;
            if (dist > 400f)      gapMs = 2500;
            else if (dist > 200f) gapMs = 1600;
            else if (dist > 100f) gapMs = 1000;
            else if (dist > 50f)  gapMs = 650;
            else if (dist > 25f)  gapMs = 400;
            else                  gapMs = 220;
            trackedTargetNextPulseTicks = now + gapMs * 10000L;

            // Pan by bearing relative to facing, so turning your body sweeps the tone
            // across the stereo field and centring it means you are pointed at it.
            double rel = fixHeading(GetAngleOfLineBetweenTwoPoints(me, trackedTargetPos)
                                    - player.Heading);
            float pan = (float)Math.Sin(rel * Math.PI / 180.0);
            if (pan > 1f) pan = 1f; else if (pan < -1f) pan = -1f;
            int zone = pan < -0.33f ? 0 : (pan > 0.33f ? 2 : 1);
            // Behind you the tone drops an octave — pan alone cannot express front/back.
            bool behind = Math.Abs(rel) > 90f;
            float freq = behind ? 440f : 880f;

            EmitNavBeepRaw(zone, freq, 0.11f, pan, SignalGeneratorType.Square, 0.07f);

            // A periodic spoken fix, because a pulse tells you direction but not how far.
            if (now - trackedTargetLastSpokeTicks > 150000000L)   // 15 s
            {
                trackedTargetLastSpokeTicks = now;
                Speech.Ambient(trackedTargetName + ", " + ((int)dist) + " metres "
                    + getDir(GetAngleOfLineBetweenTwoPoints(me, trackedTargetPos)) + ". ");
            }
        }
        #endregion

        #region RESTRICTED AREAS + INTERACTION CATALOGUE (iter-52)
        // Two passive readouts, no menu. Both are pure information: neither writes a
        // control, spawns anything or changes game state.

        // --- restricted areas ----------------------------------------------
        // The angled boxes from restrictedareas.c. Walk or drive into one and the game
        // hands you a wanted level with no warning a blind player can perceive — the
        // only vanilla cue is a red overlay on a map they cannot see.
        private readonly List<WorldDataDb.Area> restrictedCandidates = new List<WorldDataDb.Area>();
        // 0 = outside, 1 = inside the approach margin, 2 = inside the area itself.
        private readonly Dictionary<string, int> restrictedState = new Dictionary<string, int>();
        private long restrictedNextCheckTicks = 0;
        private const long RESTRICTED_CHECK_MS = 250;      // 4 Hz is plenty at road speed
        private const float RESTRICTED_WARN_MARGIN_M = 120f;

        private void TickRestrictedAreas()
        {
            if (getSettingCachedRestrictedArea != 1) return;
            if (!WorldDataDb.IsLoaded) return;

            long now = ModClock.Ticks;
            if (now < restrictedNextCheckTicks) return;
            restrictedNextCheckTicks = now + RESTRICTED_CHECK_MS * 10000L;

            Ped player = Game.Player.Character;
            GTA.Math.Vector3 p = player.Position;

            WorldDataDb.CandidateAreas(p, RESTRICTED_WARN_MARGIN_M, restrictedCandidates);

            foreach (var area in WorldDataDb.Areas)
            {
                if (area == null || area.id == null) continue;

                int want = 0;
                if (restrictedCandidates.Contains(area))
                {
                    // Inside the bounding box + margin. Now pay for the real test.
                    want = PointInArea(p, area, 0f) ? 2 : 1;
                }

                int had;
                if (!restrictedState.TryGetValue(area.id, out had)) had = 0;
                if (want == had) continue;
                restrictedState[area.id] = want;

                string name = WorldDataDb.AreaDisplayName(area);
                if (string.IsNullOrEmpty(name))
                {
                    // The harvester could not identify this group, so speak the game's
                    // own zone name rather than inventing one. "Restricted area near
                    // Elysian Island" is honest; a wrong landmark name is not.
                    string zone = World.GetZoneDisplayName(p);
                    name = string.IsNullOrEmpty(zone)
                        ? "a restricted area" : "a restricted area near " + zone;
                }

                if (want == 2)
                    Speech.Critical("Entering " + name + ". Trespassing here will get you wanted. ");
                else if (want == 1 && had == 0)
                    Speech.Info("Approaching " + name + ". ");
                else if (want == 0)
                    Speech.Info("Clear of " + name + ". ");

                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT restricted-area:"
                        + " id=" + area.id + " state=" + had + "->" + want
                        + " pos=" + FmtV(p));
            }
        }

        /// <summary>True when the point is inside any of the area's angled boxes.
        /// `grow` widens each box, used for the approach margin.</summary>
        private bool PointInArea(GTA.Math.Vector3 p, WorldDataDb.Area area, float grow)
        {
            if (area.boxes == null) return false;
            foreach (var b in area.boxes)
            {
                if (b == null || b.a == null || b.b == null) continue;
                if (b.a.Length < 3 || b.b.Length < 3) continue;
                bool hit;
                try
                {
                    hit = Function.Call<bool>(Hash.IS_POINT_IN_ANGLED_AREA,
                        p.X, p.Y, p.Z,
                        b.a[0], b.a[1], b.a[2],
                        b.b[0], b.b[1], b.b[2],
                        b.width + grow, false, true);
                }
                catch { hit = false; }
                if (hit) return true;
            }
            return false;
        }

        // --- interaction catalogue ------------------------------------------
        // What a world object is FOR. The mod's existing object scan (NumPad 8) names
        // props out of hashes.txt, so a vending machine reads as "prop vend soda 01".
        // The ob_* scripts say what each one actually does.

        private long interactionNextCheckTicks = 0;
        private const long INTERACTION_CHECK_MS = 900;
        private const float INTERACTION_NEAR_M = 4.5f;
        private int lastInteractionSpokenHash = 0;
        private long lastInteractionSpokenTicks = 0;

        /// <summary>" that you can play music on" for a catalogued model, else "".
        /// Appended to the object scan so a scanned prop says what it is good for.</summary>
        private string InteractionSuffix(int modelHash)
        {
            if (getSetting("interactionCatalogue") != 1) return "";
            var it = WorldDataDb.InteractionFor(modelHash);
            if (it == null) return "";
            return string.IsNullOrEmpty(it.verb) ? "" : " (" + it.verb + ")";
        }

        /// <summary>Announces a catalogued object you have walked up to. Rate-limited
        /// per model so standing at a vending machine does not repeat forever, and
        /// silent while the speech channel is busy so it never talks over a warning.</summary>
        private void TickInteractionCatalogue()
        {
            if (getSettingCachedInteraction != 1) return;
            if (!WorldDataDb.IsLoaded) return;

            long now = ModClock.Ticks;
            if (now < interactionNextCheckTicks) return;
            interactionNextCheckTicks = now + INTERACTION_CHECK_MS * 10000L;

            Ped player = Game.Player.Character;
            if (player.IsInVehicle()) return;   // none of these are usable from a car

            GTA.Math.Vector3 me = player.Position;
            Prop[] props = World.GetNearbyProps(me, INTERACTION_NEAR_M);
            if (props == null) return;

            WorldDataDb.Interaction best = null;
            float bestDist = float.MaxValue;
            foreach (Prop prop in props)
            {
                if (prop == null || !prop.Exists()) continue;
                int hash = unchecked((int)prop.Model.NativeValue);
                var it = WorldDataDb.InteractionFor(hash);
                if (it == null) continue;
                float d = World.GetDistance(me, prop.Position);
                if (d < bestDist) { bestDist = d; best = it; }
            }

            if (best == null)
            {
                // Left the object; allow it to be announced again next time.
                if (now - lastInteractionSpokenTicks > 30000000L) lastInteractionSpokenHash = 0;
                return;
            }

            if (best.hash == lastInteractionSpokenHash
                && now - lastInteractionSpokenTicks < 200000000L)  // 20 s
                return;

            lastInteractionSpokenHash = best.hash;
            lastInteractionSpokenTicks = now;
            Speech.Ambient(best.kind + " nearby, " + ((int)bestDist) + " metres. You can "
                + best.verb + ". ");
        }
        #endregion

        #region EVENTS AND SERVICES (iter-52)
        // Random-event awareness + 911 dispatch. Menu 10.
        //
        // What the corpus established while building this, because it constrains the
        // design and should not be re-litigated:
        //   * Random-event scripts are NOT launched by START_NEW_SCRIPT. The engine's
        //     world-point brain system launches them and passes the world point in a
        //     script-parameter struct (re_arrests.c reads ScriptParam_0.f_1 as its
        //     scene coordinate). event_controller.c contains no coordinates and no
        //     brain registration, so there is no script-side table of the 33 locations
        //     to harvest — the world points live in map data.
        //   * That makes force-starting an event an ABI guess (see StartRandomEvent).
        //     Announcing and suppressing need none of that and are exact.

        private int eventsMenuIndex = 0;

        // Global_112911 holds the active random-event id, -1 when none. Read-only here.
        private const int GLOBAL_ACTIVE_RANDOM_EVENT = 112911;

        private bool blockRandomEvents = false;
        private int lastAnnouncedEventId = int.MinValue;
        private long lastEventAnnounceTicks = 0;
        private int activeDispatchIncident = -1;
        private string activeDispatchName = null;
        private long activeDispatchTicks = 0;
        private const long DISPATCH_TIMEOUT_MS = 120000;   // 2 min, then the incident is dropped

        // Fixed rows before the per-event list.
        private const int EVENTS_ROW_STATUS = 0;
        private const int EVENTS_ROW_BLOCK = 1;
        private const int EVENTS_ROW_POLICE = 2;
        private const int EVENTS_ROW_AMBULANCE = 3;
        private const int EVENTS_ROW_FIRE = 4;
        private const int EVENTS_ROW_CANCEL = 5;
        private const int EVENTS_FIXED_ROWS = 6;

        private int EventsMenuCount() { return EVENTS_FIXED_ROWS; }

        /// <summary>Active random-event id, or int.MinValue when it cannot be read.
        /// GlobalVariable.Get throws for an index with no allocated block, which is a
        /// normal state early in a session, not an error worth reporting.</summary>
        private int ActiveRandomEventId()
        {
            try { return GlobalVariable.Get(GLOBAL_ACTIVE_RANDOM_EVENT).Read<int>(); }
            catch { return int.MinValue; }
        }

        private string RandomEventDisplayName(int id)
        {
            var e = WorldDataDb.RandomEventById(id);
            if (e == null) return "event " + id;
            string gxt = MenuLabelDb.ResolveGxt(e.gxt);
            if (!string.IsNullOrEmpty(gxt)) return gxt;
            return SpacedIdentifier(e.script.StartsWith("re_") ? e.script.Substring(3) : e.script);
        }

        private string GetEventsMenuText(int index)
        {
            switch (index)
            {
                case EVENTS_ROW_STATUS:
                {
                    int id = ActiveRandomEventId();
                    if (id == int.MinValue) return "Active random event: cannot read. ";
                    if (id < 0) return "Active random event: none. ";
                    return "Active random event: " + RandomEventDisplayName(id) + ". ";
                }
                case EVENTS_ROW_BLOCK:
                    return "Block random events: " + (blockRandomEvents ? "on" : "off") + ". ";
                case EVENTS_ROW_POLICE:    return "Call the police. ";
                case EVENTS_ROW_AMBULANCE: return "Call an ambulance. ";
                case EVENTS_ROW_FIRE:      return "Call the fire brigade. ";
                case EVENTS_ROW_CANCEL:
                    return activeDispatchIncident >= 0
                        ? "Cancel the call to " + activeDispatchName + ". "
                        : "Cancel emergency call (nothing active). ";
            }
            return "Empty. ";
        }

        private void HandleEventsMenuSelect(int index)
        {
            switch (index)
            {
                case EVENTS_ROW_STATUS:
                    Speech.Info(GetEventsMenuText(EVENTS_ROW_STATUS));
                    return;

                case EVENTS_ROW_BLOCK:
                    if (getSetting("randomEventAlerts") != 1)
                    {
                        Speech.Info("Turn on Announce random events in Settings first. ");
                        return;
                    }
                    blockRandomEvents = !blockRandomEvents;
                    Speech.Info("Random events " + (blockRandomEvents ? "blocked" : "allowed") + ". ");
                    return;

                case EVENTS_ROW_POLICE:    CallEmergencyService("police"); return;
                case EVENTS_ROW_AMBULANCE: CallEmergencyService("ambulance"); return;
                case EVENTS_ROW_FIRE:      CallEmergencyService("fire"); return;
                case EVENTS_ROW_CANCEL:    CancelDispatch(true); return;
            }
        }

        // ===================================================================
        // 911 dispatch
        // ===================================================================
        // Straight out of emergencycall.c: CREATE_INCIDENT with the game's own service
        // ids and unit counts, sited on a road node near the player so the responders
        // have somewhere to arrive. This is the phone's 911 flow without the phone UI,
        // which is several nested Scaleform screens deep.

        private void CallEmergencyService(string id)
        {
            if (getSetting("emergencyDispatch") != 1)
            {
                Speech.Info("Emergency calls are turned off in Settings. ");
                return;
            }
            var svc = WorldDataDb.DispatchById(id);
            if (svc == null) { Speech.Info("That service is not available. "); return; }

            if (activeDispatchIncident >= 0)
            {
                Speech.Info("A call to " + activeDispatchName + " is already active. "
                    + "Cancel it first. ");
                return;
            }

            GTA.Math.Vector3 me = Game.Player.Character.Position;
            GTA.Math.Vector3 at = me;

            // Put the incident on a road node when there is one — emergencycall.c does
            // the same, because responders that spawn off-road never arrive.
            try
            {
                var outPos = new OutputArgument();
                var outHead = new OutputArgument();
                if (Function.Call<bool>(Hash.GET_NTH_CLOSEST_VEHICLE_NODE_WITH_HEADING,
                        me.X, me.Y, me.Z, 1, outPos, outHead, 1, 3.0f, 0))
                    at = outPos.GetResult<GTA.Math.Vector3>();
            }
            catch { /* fall back to the player's own position */ }

            int incident = -1;
            try
            {
                var outIncident = new OutputArgument();
                Function.Call(Hash.CREATE_INCIDENT, svc.service, at.X, at.Y, at.Z,
                    svc.units, svc.radius, outIncident);
                incident = outIncident.GetResult<int>();
            }
            catch (Exception ex)
            {
                ReportSubsystemError("dispatch", ex);
                Speech.Info("The call did not go through. ");
                return;
            }

            bool valid = false;
            try { valid = Function.Call<bool>(Hash.IS_INCIDENT_VALID, incident); } catch { }
            if (!valid)
            {
                Speech.Info("The call did not go through. ");
                return;
            }

            activeDispatchIncident = incident;
            activeDispatchName = svc.name;
            activeDispatchTicks = ModClock.Ticks;
            Speech.Info(svc.name + " called, " + svc.units + " units on the way. ");

            if (driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT dispatch-call:"
                    + " svc=" + svc.id + " id=" + incident + " units=" + svc.units
                    + " at=" + FmtV(at));
        }

        /// <summary>Deletes the live incident. Called by the menu, by the timeout, and
        /// from onAborted — a leaked incident keeps dispatch units spawning after the
        /// mod is gone, which the player then cannot cancel at all.</summary>
        private void CancelDispatch(bool speak)
        {
            if (activeDispatchIncident < 0)
            {
                if (speak) Speech.Info("No emergency call is active. ");
                return;
            }
            try { Function.Call(Hash.DELETE_INCIDENT, activeDispatchIncident); } catch { }
            if (speak) Speech.Info(activeDispatchName + " call cancelled. ");
            if (driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT dispatch-cancel:"
                    + " id=" + activeDispatchIncident + " svc=" + activeDispatchName);
            activeDispatchIncident = -1;
            activeDispatchName = null;
        }

        // ===================================================================
        // Why there is no "start this random event" command
        // ===================================================================
        // It was planned, investigated, and deliberately not shipped. The engine's
        // world-point brain system launches re_* scripts and hands each one its scene
        // coordinate in a script-parameter struct (re_arrests.c reads it as
        // ScriptParam_0.f_1, then range-checks it and terminates if it is wrong).
        //
        // START_NEW_SCRIPT cannot pass that struct, and START_NEW_SCRIPT_WITH_ARGS
        // needs a pinned array SHVDN will not marshal without unsafe code — for an
        // arg layout that is a guess in the first place. event_controller.c holds no
        // coordinates and no brain registration, so there is no script-side table of
        // the 33 world points to work from either; they live in map data.
        //
        // The reachable outcome was therefore 33 menu rows that all report "did not
        // start", which costs a blind user 33 arrow presses to discover. Announcing
        // events and suppressing them need none of that and are exact, so that is what
        // this region does.

        // ===================================================================
        // Tick
        // ===================================================================

        private void TickEventsAndServices()
        {
            // Suppression has to be re-asserted every frame — the native is
            // *_THIS_FRAME. This is the only per-frame write in the whole region.
            if (blockRandomEvents && getSetting("randomEventAlerts") == 1)
            {
                try { Function.Call(Hash.SUPRESS_RANDOM_EVENT_THIS_FRAME); } catch { }
            }

            if (activeDispatchIncident >= 0
                && ModClock.Ticks - activeDispatchTicks > DISPATCH_TIMEOUT_MS * 10000L)
            {
                // Time-box it so a call that never resolves cannot block the next one
                // forever. Announced, because a silent cancellation would look like the
                // menu row simply stopped working.
                Speech.Ambient("The " + activeDispatchName + " call has expired. ");
                CancelDispatch(false);
            }

            if (getSetting("randomEventAlerts") != 1) return;

            int id = ActiveRandomEventId();
            if (id == int.MinValue) return;
            if (id == lastAnnouncedEventId) return;

            long now = ModClock.Ticks;
            // 10 s floor so an event flickering in and out cannot chatter.
            if (now - lastEventAnnounceTicks < 100000000L) return;
            lastEventAnnounceTicks = now;

            int previous = lastAnnouncedEventId;
            lastAnnouncedEventId = id;
            if (id < 0)
            {
                if (previous > 0) Speech.Ambient("Random event over. ");
                return;
            }

            Speech.Info("Random event nearby: " + RandomEventDisplayName(id) + ". ");
            if (driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT random-event-active:"
                    + " id=" + id + " name=" + RandomEventDisplayName(id).Replace(' ', '_'));
        }
        #endregion

        // ===================================================================
        // DRIVE ASSIST DEBUG LOGGING
        // ===================================================================

        // Compact Vector3 formatter for log lines.
        private static string FmtV(GTA.Math.Vector3 v)
        {
            return "(" + v.X.ToString("F1") + "," + v.Y.ToString("F1") + "," + v.Z.ToString("F1") + ")";
        }

        // Float formatter that renders the "no threat" sentinels (999 / MaxValue) as "none".
        private static string FmtF(float f)
        {
            if (f >= 999f || f == float.MaxValue) return "none";
            return f.ToString("F2");
        }

        // Per-frame structured telemetry for the whole drive-assist feature. Reads
        // existing state fields and emits one FRAME block via the background logger.
        // Called from onTick only while driveAssistDebugLog is on and a driving
        // system is active. veh is null when the player is on foot (auto-walk).
        private void LogDriveAssistFrame(Vehicle veh)
        {
            try
            {
                Ped player = Game.Player.Character;
                GTA.Math.Vector3 pos = veh != null ? veh.Position : player.Position;
                float heading = veh != null ? veh.Heading : player.Heading;
                float speed = veh != null ? veh.Speed : player.Velocity.Length();

                // Deltas vs. the previous logged frame.
                float dPlanar = 0f, dHeading = 0f, dZ = 0f;
                if (driveLogFrameCount > 0)
                {
                    float ddx = pos.X - lastLoggedPos.X;
                    float ddy = pos.Y - lastLoggedPos.Y;
                    dPlanar = (float)Math.Sqrt(ddx * ddx + ddy * ddy);
                    dHeading = heading - lastLoggedHeading;
                    while (dHeading > 180f) dHeading -= 360f;
                    while (dHeading < -180f) dHeading += 360f;
                    dZ = pos.Z - lastLoggedZ;
                }
                bool bigZ = driveLogFrameCount > 0 && Math.Abs(dZ) > DRIVE_LOG_BIG_Z_THRESHOLD;

                long nowTicks = DateTime.Now.Ticks;

                // iter-35 clock-line: once per real second, in-game clock + fps.
                if (nowTicks - driveLogClockLastTicks >= 10000000L)
                {
                    TimeSpan gameT = World.CurrentTimeOfDay;
                    int fpsLastSec = driveLogClockLastTicks > 0
                        ? (int)Math.Round((driveLogFrameCount - driveLogClockLastFrame)
                            / ((nowTicks - driveLogClockLastTicks) / 10000000.0))
                        : 0;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT clock:"
                        + " game=" + gameT.Hours.ToString("00") + ":" + gameT.Minutes.ToString("00")
                        + " real=" + DateTime.Now.ToString("HH:mm:ss")
                        + " fps=" + fpsLastSec
                        + " frames=" + driveLogFrameCount);
                    driveLogClockLastTicks = nowTicks;
                    driveLogClockLastFrame = driveLogFrameCount;
                    // iter-41 Stage 0.3: cumulative, never reset, so a log truncated
                    // by a crash still carries totals. 30 s cadence.
                    if (nowTicks - lastGateCensusTicks >= 300000000L)
                    {
                        lastGateCensusTicks = nowTicks;
                        WriteGateCensus();
                    }
                }
                // iter-41 Stage 0.14: poll for in-game gate flips at ~2 Hz. Cheap
                // (23 lookups) and precise enough to place an epoch boundary, while
                // per-frame polling would cost ~97k string compares/second.
                if (driveLogFrameCount % 30 == 0)
                    CheckGateToggles();

                // iter-36 P2-2: FRAME thinning while parked. A stationary car wrote
                // byte-identical 11-line blocks at 60 Hz for minutes — most of the
                // 87 MB/20 min log. Drop to 10 Hz while truly parked; full rate
                // resumes instantly on motion and for 3 s after any damage or
                // marker (the sweep and ±3 s excerpts keep full resolution where
                // it matters). Frame counter still increments so [Fn] stays a real
                // frame index; timestamps carry the analysis (fps is derived from
                // the clock line, not FRAME density).
                bool frameParked = speed < 0.2f && dPlanar < 0.01f
                    && Math.Abs(dHeading) < 0.05f;
                bool frameHot =
                    (lastBodyDropTicks > 0 && nowTicks - lastBodyDropTicks < 30000000L)
                    || (autoCollisionLastTicks > 0 && ModClock.Ticks - autoCollisionLastTicks < 30000000L) // ModClock pair
                    // iter-41 Stage 0.7: the old "hot" test keyed on DAMAGE only, so
                    // it thinned the log exactly during a zero-damage stall — the
                    // dominant failure mode of a clean session. A pedal held against
                    // a driver who is asking to move is always worth full rate.
                    || thrHoldSitesThisFrame != 0
                    || immobileUnderThrottleActive;
                if (frameParked && !frameHot
                    && nowTicks - lastParkedFrameWriteTicks < 1000000L) // 10 Hz floor
                {
                    lastLoggedPos = pos;
                    lastLoggedHeading = heading;
                    lastLoggedZ = pos.Z;
                    lastLoggedSpeed = speed;
                    driveLogFrameCount++;
                    return;
                }
                lastParkedFrameWriteTicks = nowTicks;

                // iter-31: guard the uninitialized sentinel — before the first scan
                // steeringAssistTicks is 0, which printed scanAgeMs=63918480000000.
                // iter-39 L4: report from lastScanCompletedTicks, NOT steeringAssistTicks.
                // steeringAssistTicks is the scan CADENCE timer, and iter-34 HIGH-4
                // re-stamps it every tick while the assist is suspended — which is
                // exactly when the scan is NOT running and every cached perception
                // value is frozen. scanAgeMs therefore read 0.00 at the two 07-23
                // markers whose lane model was 2.6 s and 4.4 s stale. A freshness
                // field driven by a cadence timer reports the opposite of the truth
                // in the one state where it matters.
                float steerScanAgeMs = lastScanCompletedTicks > 0
                    ? (ModClock.Ticks - lastScanCompletedTicks) / 10000f : -1f;
                // iter-39 L4: how long actuation has been withheld. Pair this with
                // scanAgeMs to tell "suspended and blind" from "suspended but seeing".
                float suspendedMs = (assistSuspended && assistSuspendedSinceTicks > 0)
                    ? (ModClock.Ticks - assistSuspendedSinceTicks) / 10000f : -1f;
                float brakeThreatAgeMs = cachedBrakeThreatStamp > 0
                    ? (nowTicks - cachedBrakeThreatStamp) / 10000f : -1f;
                float brakeThreatDist = cachedBrakeThreatStamp > 0
                    ? pos.DistanceTo(cachedBrakeThreatPos) : -1f;

                // iter-27 L1: applied-control readback + effectiveness. Lets the next
                // log distinguish "brake commanded but ineffective" (airborne / another
                // owner / no traction) from "brake never commanded" — 014616 #1/#2 held
                // rampedBrake=1.0 with ~zero deceleration and nothing explained why.
                // iter-28 L: teleport-guard (dPlanar<5) + clamp ±30 m/s² — the raw
                // delta hit ±255 on respawns/hitches and made the field untrustworthy.
                float decelMs2 = (driveLogFrameCount > 0 && deltaTime > 0.001f && dPlanar < 5f)
                    ? Math.Max(-30f, Math.Min(30f, (lastLoggedSpeed - speed) / deltaTime)) : 0f;
                lastDecelMs2 = decelMs2; // iter-30: surface deceleration on the failClass snapshot
                // iter-32: junction/speedzone floors flow through curveBrakeRequest
                // (ComputeCurveBrake max-chain); attribute ownership to them when
                // they are the term holding the floor up, so `owner=` is truthful.
                string brakeOwner = BrakeOwnerName();
                bool wheelsOnGround = veh != null
                    && Function.Call<bool>(Hash.IS_VEHICLE_ON_ALL_WHEELS, veh);
                // iter-27 L3: native road ground truth (the mod's onValidRoad disagrees
                // with the native on rural/dirt surfaces — see iter-25 M4). Reused in
                // the road line, the lookback ring, and the off-road flag diagnosis.
                bool nativeOnRoad = veh != null && IsPositionOnRoad(pos);
                // iter-39 L1: NEVER max these two channels. The iter-33 comment here
                // read "the enabled-channel read returns 0 exactly while the mod
                // disables a control to intervene (the one time the value matters) —
                // ctrlB=0.00 under full commanded brake was a recurring red herring"
                // and hid the value behind Math.Max with the disabled channel.
                // That was not a red herring: it was the actuation bug reporting
                // itself. SET_CONTROL_VALUE_NEXT_FRAME fails when the action param
                // is disabled, so DISABLE_CONTROL_ACTION(0,72) + write(72) = no
                // brake at all. Masking the enabled channel is what kept that
                // invisible for ~24 iterations. Log both channels, always.
                //   ctrlB/ctrlT/ctrlHb  = ENABLED channel (what vehicle physics reads)
                //   ctrlBd/ctrlTd/ctrlHbd = DISABLED channel (what the mod wrote into
                //                           a disabled control, i.e. went nowhere)
                float ctrlBrake72 = Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 72);
                float ctrlBrake72Dis = Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 72);
                float ctrlThrottle71 = Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71);
                float ctrlThrottle71Dis = Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 71);
                // iter-28 L: handbrake is control 76, not 72 — without this, owner=handbrake
                // with ctrlB=0.00 reads as a contradiction (024041 off-road grinds).
                float ctrlHandbrake76 = Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 76);
                float ctrlHandbrake76Dis = Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 76);

                StringBuilder sb = new StringBuilder(1200);
                sb.AppendLine("FRAME " + driveLogFrameCount
                    + " t=" + DateTime.Now.ToString("HH:mm:ss.fff")
                    + " dt=" + deltaTime.ToString("F4"));
                // iter-36 P2-2: aircraft=/boat= dropped from the per-frame line —
                // constant per vehicle; the vehicle-swap event carries the model.
                sb.AppendLine("  veh: " + (veh != null ? "" : "ON-FOOT")
                    + " pos=(" + pos.X.ToString("F2") + "," + pos.Y.ToString("F2") + "," + pos.Z.ToString("F2") + ")"
                    + " heading=" + heading.ToString("F1")
                    + " speed=" + speed.ToString("F2") + "m/s/" + (speed * 2.23694f).ToString("F1") + "mph"
                    + " reversing=" + isReversing
                    // iter-20 H6: per-frame health so offline analysis can localize
                    // every impact (snapshots alone proved far too sparse).
                    + (veh != null
                        ? " bh=" + veh.BodyHealth.ToString("F0")
                          + " eh=" + veh.EngineHealth.ToString("F0")
                        : ""));
                sb.AppendLine("  delta: planar=" + dPlanar.ToString("F3") + "m"
                    + " heading=" + dHeading.ToString("F2") + "deg"
                    + " z=" + dZ.ToString("F3") + "m" + (bigZ ? "  <<BIG_Z_CHANGE>>" : ""));
                // iter-34 BS-3: resolve the v2 attributes once, feed both the road
                // line and the coverage counters.
                string v2FrameStreet = lastPathStartNodeIdx >= 0
                    ? NodeGraph.GetStreetName(lastPathStartNodeIdx) : "";
                int v2FrameExt = lastPathStartNodeIdx >= 0
                    ? (int)NodeGraph.GetExtFlags(lastPathStartNodeIdx) : 0;
                int v2FrameSpdCat = lastPathStartNodeIdx >= 0
                    ? NodeGraph.GetSpeedCategory(lastPathStartNodeIdx) : -1;
                v2CovTotal++;
                if (lastPathStartNodeIdx >= 0) v2CovNode++;
                if (v2FrameStreet.Length > 0) { v2CovStreet++; v2StreetGapCur = 0; }
                else { v2StreetGapCur++; if (v2StreetGapCur > v2StreetGapMax) v2StreetGapMax = v2StreetGapCur; }
                if (v2FrameExt != 0) v2CovExt++;
                if (v2FrameSpdCat >= 0) v2CovSpd++;
                // iter-36 P1-4: 1 Hz cached native street fallback for the FRAME
                // field — only 7,740 of 67,454 v2 nodes carry a name, so whole
                // named-city minutes read street=- (maxStreetGapFrames=2509 in
                // 07-04). Applied AFTER the v2 coverage counters so they keep
                // measuring the v2 graph, not the fallback. Space-stripped token.
                string frameStreetOut = v2FrameStreet;
                if (frameStreetOut.Length == 0)
                {
                    if (nowTicks - cachedNativeStreetStamp > 10000000L)
                    {
                        cachedNativeStreetStamp = nowTicks;
                        try { cachedNativeStreet = (World.GetStreetName(pos) ?? "").Replace(" ", ""); }
                        catch { cachedNativeStreet = ""; }
                    }
                    frameStreetOut = cachedNativeStreet;
                }
                sb.AppendLine("  road: onValidRoad=" + isOnValidRoad
                    + " nativeOnRoad=" + nativeOnRoad           // iter-27 L3: native ground truth
                    + " lat=" + lastLaneLateralError.ToString("F2") // iter-27 L3: lateral offset, all modes
                    + " latAgeMs=" + (lastLaneLateralErrorTicks > 0 ? (nowTicks - lastLaneLateralErrorTicks) / 10000 : -999) // iter-29 C1: >scan-interval = stale/frozen; iter-33: -999 = never measured (was -1, ambiguous with a tiny age)
                    + " headingDelta=" + roadHeadingDelta.ToString("F1")
                    // iter-39 L7 budget: lastValidRoadDist printed 999.0 on 24031 of
                    // 24031 frames on 07-23 — a field whose only value is its own
                    // sentinel, at ~0.55 MB/session. Emit it only when it is real,
                    // which is also the only time it means anything.
                    + (lastValidRoadDistance < 900f
                        ? " lastValidRoadDist=" + lastValidRoadDistance.ToString("F1") : "")
                    + " skewed=" + vehicleIsSkewed + " skewAngle=" + vehicleSkewAngle.ToString("F1")
                    + " offRoadDurMs=" + (offRoadStartTicks > 0
                        ? ((ModClock.Ticks - offRoadStartTicks) / 10000f).ToString("F0") : "0") // ModClock pair
                    // iter-32: v2 road-graph context at the nearest node
                    + " node=" + lastPathStartNodeIdx
                    + " street=" + frameStreetOut
                    + " ext=" + v2FrameExt.ToString("X")
                    + " spdCat=" + v2FrameSpdCat
                    + " extraW=" + lastLaneWidthExtraM
                    + " wrongWay=" + wrongWayActive
                    + (wrongWayStartTicks > 0
                        ? "/" + ((nowTicks - wrongWayStartTicks) / 10000L) + "ms" : "")
                    // iter-42 B1: MEASURED carriageway, alongside the modelled
                    // extraW above it — the whole point is that the two are
                    // comparable on one line. Omitted entirely when the native
                    // refused, so an absent field means "no reading", never 0.
                    + (roadEdgeValid
                        ? " edgeL=" + roadEdgeLeftM.ToString("F1")
                          + " edgeR=" + roadEdgeRightM.ToString("F1")
                          + " roadW=" + roadWidthMeasM.ToString("F1") : "")
                    // iter-42 B2: grade in DEGREES so it is directly comparable to
                    // the A3 wheel-plane pitch — agreement between two independent
                    // derivations is the acceptance test for both.
                    + (groundNormValid
                        ? " gradeDeg=" + groundGradeDeg.ToString("F1")
                          + " camberDeg=" + groundCamberDeg.ToString("F1") : "")
                    + (groundAheadValid
                        ? " gradeAheadDeg=" + groundGradeAheadDeg.ToString("F1") : ""));
                // iter-36 P2-2: p1/p2 dropped — p0 + point count suffices at frame
                // rate; the full polyline shape is in the poly-offset events.
                sb.AppendLine("  path: points=" + pathPolyline.Count
                    + " fromGps=" + pathPolylineFromGps
                    + " p0=" + (pathPolyline.Count > 0 ? FmtV(pathPolyline[0]) : "-")
                    // iter-32 R5: restriction-filter hits on the graph walk this
                    // scan; "cf" = counterfactual (setting off, plain walk used).
                    // iter-33: "(v1)" suffix = no restriction data loaded, so the
                    // count is structurally 0 whichever mode — don't read it as
                    // "restrictions checked and none applied" (07-02 confusion).
                    + " walkRestrict=" + lastWalkRestrictedCount
                    + "/" + (getSetting("restrictionAwareWalk") == 1 ? "on" : "cf")
                    + (NodeGraph.SchemaVersion < 2 ? "(v1)" : "")
                    // iter-34 BS-5: did the counterfactual restricted walk actually
                    // END somewhere different from the plain walk this scan?
                    + " div=" + (lastWalkCfDiverged ? 1 : 0));
                // iter-34 BS-3/BS-4: coverage + detector-liveness heartbeats (~30 s).
                if (lastV2HeartbeatTicks == 0) lastV2HeartbeatTicks = nowTicks;
                else if (nowTicks - lastV2HeartbeatTicks > 300000000L)
                {
                    lastV2HeartbeatTicks = nowTicks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT v2-coverage:"
                        + " frames=" + v2CovTotal
                        + " node=" + v2CovNode
                        + " street=" + v2CovStreet
                        + " maxStreetGapFrames=" + v2StreetGapMax // iter-35 L6 (B6)
                        + " ext=" + v2CovExt
                        + " spdCat=" + v2CovSpd);
                    // ---- iter-43 G4: NAVIGATION STATE ----
                    // Nothing in the 07-31 log carried waypoint or mission-tracking
                    // state anywhere: a grep for it over all 266.7 MB returns zero
                    // lines. The only evidence the tester had tracked a marker at
                    // all was an incidental speech line. Every consumer of
                    // cachedWaypointPos was therefore undebuggable.
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT nav-state:"
                        + " wpActive=" + hasActiveWaypoint
                        + " wpTracking=" + waypointTrackingActive
                        + " missionTracking=" + missionTrackingActive
                        + " gpsRoute=" + HasGpsRoute()
                        + " wpPos=" + FmtV(cachedWaypointPos)
                        + " wpDist=" + (cachedWaypointPos != GTA.Math.Vector3.Zero
                            ? PlanarDist(pos, cachedWaypointPos).ToString("F0") : "-"));
                    float nearestJunc = -1f, nearestSignalized = -1f;
                    if (JunctionDb.IsLoaded && veh != null)
                    {
                        for (int ji = 0; ji < JunctionDb.JunctionCount; ji++)
                        {
                            GTA.Math.Vector3 jc = JunctionDb.GetJunctionCenter(ji);
                            float jdx = jc.X - pos.X, jdy = jc.Y - pos.Y;
                            float jd = (float)Math.Sqrt(jdx * jdx + jdy * jdy);
                            if (nearestJunc < 0f || jd < nearestJunc) nearestJunc = jd;
                            if (JunctionDb.IsSignalized(ji)
                                && (nearestSignalized < 0f || jd < nearestSignalized))
                                nearestSignalized = jd;
                        }
                    }
                    // iter-35: nearest TrafficLight-flagged graph node — the new
                    // fallback arming source — so "armedFrames=0" stays provable.
                    float nearestLightNode = -1f;
                    if (NodeGraph.IsLoaded && veh != null)
                    {
                        int lni = NodeGraph.FindNearestNode(pos, 300f,
                            NodeGraph.NodeFlags.TrafficLight,
                            NodeGraph.NodeFlags.None, NodeGraph.ExtFlags.None);
                        if (lni >= 0)
                        {
                            GTA.Math.Vector3 lnp = NodeGraph.GetPosition(lni);
                            float lndx = lnp.X - pos.X, lndy = lnp.Y - pos.Y;
                            nearestLightNode = (float)Math.Sqrt(lndx * lndx + lndy * lndy);
                        }
                    }
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT junction-eval:"
                        + " evals=" + jEvalCount
                        + " armedFrames=" + jArmedFrames
                        + " nearestJuncDist=" + nearestJunc.ToString("F0")
                        + " nearestSignalizedDist=" + nearestSignalized.ToString("F0")
                        + " nearestLightNodeDist=" + nearestLightNode.ToString("F0"));
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT wrongway-eval:"
                        + " evals=" + wwEvalCount
                        + " nodeHit=" + wwNodeHitCount
                        + " exempt=" + wwExemptCount
                        + " violFrames=" + wwViolFrames);
                    v2CovTotal = 0; v2CovNode = 0; v2CovStreet = 0; v2CovExt = 0; v2CovSpd = 0;
                    v2StreetGapMax = 0; // gap streak may span windows; only the max resets
                    jEvalCount = 0; jArmedFrames = 0;
                    wwEvalCount = 0; wwNodeHitCount = 0; wwExemptCount = 0; wwViolFrames = 0;
                }
                // iter-42 C2: the engine's own routing answer, emitted even when
                // neither static source armed — that gap IS the finding, and a line
                // that only appears when the static data already worked could never
                // show it. Kept off the armed line so both can be present.
                if (genDirValid && !junctionArmed)
                    sb.AppendLine("  junction: armed=false src=gen"
                        + " genDir=" + genDirCode
                        + " genDist=" + genDistToJunction.ToString("F1")
                        + " jBrakeWouldBe=" + junctionBrakeWouldBe.ToString("F2"));
                // iter-32 R3: junction line, only when armed or recently near one
                if (junctionArmed)
                    sb.AppendLine("  junction: armed=true"
                        + " src=" + (junctionFromNode ? "node" : "db") // iter-35
                        + " jIdx=" + (junctionFromNode ? -1 : junctionEntrance.JunctionIdx)
                        + " dist=" + junctionDistM.ToString("F1")
                        + (junctionFromNode
                            ? " ni=" + junctionNodeIdx
                            : " phases=" + JunctionDb.GetPhaseCount(junctionEntrance.JunctionIdx)
                              + " lights=" + JunctionDb.GetLightCount(junctionEntrance.JunctionIdx)
                              + " entrPhase=" + junctionEntrance.Phase
                              + " la=" + (junctionEntrance.LeftLaneAheadOnly ? 1 : 0)
                              + " rl=" + (junctionEntrance.RightLaneRightOnly ? 1 : 0)
                              + " rr=" + (junctionEntrance.RightOnRed ? 1 : 0))
                        + " jBrake=" + junctionBrakeRequest.ToString("F2")
                        + " jBrakeWouldBe=" + junctionBrakeWouldBe.ToString("F2")
                        + " szBrake=" + speedZoneBrakeRequest.ToString("F2")
                        + " szWouldBe=" + speedZoneBrakeWouldBe.ToString("F2")
                        // iter-42 C2 cross-check: both distances on one line.
                        + (genDirValid
                            ? " genDir=" + genDirCode
                              + " genDist=" + genDistToJunction.ToString("F1") : ""));
                sb.AppendLine("  mode: drive=" + currentDriveMode
                    + " laneKeepFailStreak=" + laneKeepFailureStreak
                    + " alignReverse=" + alignmentEngageReverse
                    + " hasRecoveryTarget=" + hasRecoveryTarget
                    + " recoveryPos=" + FmtV(recoveryTargetPos)
                    + " recoveryHeading=" + recoveryTargetHeading.ToString("F1")
                    + " recoveryDist=" + recoveryTargetDistance.ToString("F1"));
                sb.AppendLine("  threat: steerTTC=" + FmtF(threatTimeToCollision)
                    + " dir=" + threatDirection + " type=" + threatType
                    + " closestThreatPos=" + FmtV(closestThreatPosition)
                    + " brakeObstacle=" + closestBrakeObstacleType
                    + " brakeThreatDist=" + brakeThreatDist.ToString("F1")
                    + " brakeThreatAgeMs=" + brakeThreatAgeMs.ToString("F0")
                    + " adjLatchL=" + adjacentLatchedLeft + " adjLatchR=" + adjacentLatchedRight);
                // iter-36 P2-3: type tokens as SEPARATE kv keys (a /suffix on the
                // numeric value would break the triage fnum_of parser). "Hazard
                // ahead. Cannot proceed." x33 in iter-35 was undiagnosable because
                // navC never said WHAT was 3.4 m ahead.
                sb.AppendLine("  navDist: L=" + FmtF(navAssistDistLeft)
                    + " C=" + FmtF(navAssistDistCenter)
                    + " R=" + FmtF(navAssistDistRight)
                    + " B=" + FmtF(navAssistDistBehind)
                    + " Lt=" + navAssistTypeLeft
                    + " Ct=" + navAssistTypeCenter
                    + " Rt=" + navAssistTypeRight
                    + " Bt=" + navAssistTypeBehind);
                // iter-36 P2-2: dropped prevFrameSteer (== last frame's steerCmd)
                // and lastRoadCorr (== roadCorrection one scan back) — pure
                // duplicates at frame rate, ~10% of FRAME bytes with the other
                // trims, funding the new event fields.
                sb.AppendLine("  decision: steerCmd=" + cachedSteerCorrection.ToString("F3")
                    + " smoothedSteer=" + smoothedSteerCorrection.ToString("F3")
                    + " roadCorrection=" + roadSteerCorrection.ToString("F3")
                    + " smoothedRoadCorr=" + smoothedRoadCorrection.ToString("F3")
                    + " avoidDir=" + cachedAvoidDirection
                    // iter-39 L6: what actually reached control 59 this frame.
                    + " liveSteer=" + lastLiveSteer.ToString("F3")
                    + " liveUrgency=" + lastLiveUrgency.ToString("F2")
                    + " steerWritten=" + lastSteerWritten
                    // iter-51: the SECOND steering channel, on the same line as the
                    // first. lastSteerBiasWritten was assigned since iter-49 and read
                    // by nothing, so the only record of this channel was a 0.5 Hz
                    // EVENT — which is how an inverted sign survived a whole session.
                    // Emitted only while the gate is on, so an off session pays
                    // nothing. Expect steerBias == -liveSteer.
                    + (steerBiasV2Cached ? " steerBias=" + lastSteerBiasWritten.ToString("F3") : "")
                    // iter-39 L6: the avoidance term is supposed to be in [-1,1];
                    // the handbrake steer boost can push it past 1 (07-23 hit 1.489).
                    + (Math.Abs(smoothedSteerCorrection) > 1.001f ? " steerOverRange=true" : "")
                    // iter-42 A1: what the STEERING actually did, against what was
                    // commanded on the same line. steerAch is normalised to the
                    // vehicle's own steering lock so it is directly comparable to
                    // liveSteer; steerAchDeg is the raw reading, kept for one
                    // validation session to settle units and sign convention.
                    + (achValid
                        ? " steerAch=" + achSteerNorm.ToString("F3")
                          + " steerAchDeg=" + achSteerDeg.ToString("F1")
                        : ""));
                sb.AppendLine("  brake: brakeCmd=" + cachedBrakeMagnitude.ToString("F3")
                    + " rampedBrake=" + rampedBrakeInput.ToString("F3")
                    + " handbrake=" + cachedHandbrakeMagnitude.ToString("F3")
                    + " isBraking=" + cachedIsBraking
                    + " emergencyBrake=" + emergencyBrakeActive
                    + " fullMode=" + cachedIsFullMode
                    + " assistActive=" + steeringAssistActive
                    + " scanAgeMs=" + steerScanAgeMs.ToString("F0")
                    + " suspendedMs=" + suspendedMs.ToString("F0") // iter-39 L4
                    + " grace=" + InWatchdogGrace()
                    + " suspended=" + assistSuspended
                    + " owner=" + brakeOwner                    // iter-27 L1: which subsystem owns the brake
                    // iter-41 Stage 0.2: WHICH disable-71 site took the pedal this
                    // frame. ctrlT=0.00 + ctrlTd=1.00 shows THAT the pedal was taken;
                    // this names WHO took it, which no artifact could answer before.
                    + " thrSites=" + ThrHoldSiteNames(thrHoldSitesThisFrame)
                    + " liveTarget=" + lastLiveBrakeTarget.ToString("F2")
                    + " brakeArmed=" + brakeArmed
                    + " decelMs2=" + decelMs2.ToString("F1")     // iter-27 L1: actual deceleration (effect, not command)
                    + " wheelsDown=" + wheelsOnGround            // iter-27 L1: airborne/curb-balanced => brake can't bite
                    + " ctrlB=" + ctrlBrake72.ToString("F2")     // iter-27 L1: applied brake control readback
                    + " ctrlT=" + ctrlThrottle71.ToString("F2")
                    + " ctrlHb=" + ctrlHandbrake76.ToString("F2") // iter-28 L: handbrake control (76)
                    // iter-39 L1: the disabled-channel twins. ctrlB=0.00 with
                    // ctrlBd=1.00 is the signature of a write into a disabled
                    // control — commanded, accepted by the control table, and
                    // never seen by vehicle physics.
                    + " ctrlBd=" + ctrlBrake72Dis.ToString("F2")
                    + " ctrlTd=" + ctrlThrottle71Dis.ToString("F2")
                    + " ctrlHbd=" + ctrlHandbrake76Dis.ToString("F2")
                    // iter-39 L1: return value of the mod's own writes this frame
                    // (SET_CONTROL_VALUE_NEXT_FRAME returns BOOL). ret=0 means the
                    // engine rejected the write outright.
                    + " ctrlRet=" + (controlWriteLog.Length > 0 ? controlWriteLog.ToString() : "-")
                    // iter-42 A1: physics-side pedal state. ctrlB is what the control
                    // table accepted; brakeAch is what the vehicle is actually doing
                    // with it. ctrlB high + brakeAch ~0 is the actuation-nullified
                    // signature, now visible on the same line rather than inferable.
                    + (achValid
                        ? " brakeAch=" + achBrake.ToString("F2")
                          + " thrAch=" + achThrottle.ToString("F2")
                        : ""));

                // iter-42 A3: per-wheel state. CONDITIONAL — raw logs already run
                // 80+ MB and iter-39 L7 deleted a field for printing a sentinel on
                // 24031 of 24031 frames; four wheels every frame would be that
                // mistake at 4x. Emit only when something is off (a wheel is up, the
                // wheels disagree with the car's speed, a tyre is damaged) plus a
                // 1 Hz heartbeat so an ABSENT block is unambiguously "all normal"
                // rather than "feature not running".
                if (whlValid)
                {
                    int fullMask = (1 << whlCount) - 1;
                    bool wheelAbnormal = whlContactMask != fullMask
                        || Math.Abs(whlSlip) > WHEEL_SLIP_REPORT_MS
                        || whlAnyBurst;
                    bool wheelHeartbeat = nowTicks - lastWheelHeartbeatTicks >= 10000000L;
                    if (wheelAbnormal || wheelHeartbeat)
                    {
                        if (wheelHeartbeat) lastWheelHeartbeatTicks = nowTicks;
                        System.Text.StringBuilder wm = new System.Text.StringBuilder(whlCount);
                        for (int i = 0; i < whlCount; i++)
                            wm.Append((whlContactMask & (1 << i)) != 0 ? '1' : '0');
                        sb.AppendLine("  wheels: contact=" + wm.ToString()
                            + " slip=" + whlSlip.ToString("F2")
                            // Name the failure mode rather than leaving it to be
                            // re-derived from the sign at analysis time.
                            + (whlSlip > WHEEL_SLIP_REPORT_MS ? " mode=spin"
                               : whlSlip < -WHEEL_SLIP_REPORT_MS ? " mode=lockup" : "")
                            + (whlPlaneValid
                                ? " pitch=" + whlPitchDeg.ToString("F1")
                                  + " camber=" + whlCamberDeg.ToString("F1") : "")
                            + (whlAnyBurst ? " burst=true" : "")
                            + (whlMinTyre >= 0f && whlMinTyre < 1000f
                                ? " minTyre=" + whlMinTyre.ToString("F0") : "")
                            + (wheelAbnormal ? "" : " hb=1"));
                    }
                }
                // iter-31: throttle path — the mod's APPLIED throttle vs the player's raw
                // intent (ctrlT is a pre-override readback) plus ACC state, so an ACC pin
                // that overrides the pedal is visible instead of looking like "stuck".
                sb.AppendLine("  throttle: applied=" + lastAppliedThrottle.ToString("F2")
                    + " playerRaw=" + lastPlayerThrottleRaw.ToString("F2")
                    + " accThr=" + accThrottleOut.ToString("F2")
                    + " accBrk=" + accBrakeOut.ToString("F2")
                    + " accLead=" + (navAssistVehicleCenter != null && navAssistVehicleCenter.Exists())
                    + " leadGap=" + navAssistDistCenter.ToString("F1")
                    + " cruiseSpd=" + autodriveSpeed.ToString("F1"));
                if (isAutodriving)
                {
                    float destDist = autodriveWanderMode ? -1f : pos.DistanceTo(autodriveDestination);
                    sb.AppendLine("  autodrive: active=true wander=" + autodriveWanderMode
                        + " dest=" + FmtV(autodriveDestination)
                        + " destDist=" + destDist.ToString("F1")
                        + " speed=" + autodriveSpeed.ToString("F2") + "m/s/"
                        + (autodriveSpeed * 2.23694f).ToString("F1") + "mph");
                }

                driveLogger.Write(sb.ToString().TrimEnd());

                // iter-28 L: per-frame lat node-snap detector. StabilizePolyline's hold
                // is throttled/conditional, so off-road snaps were invisible (024041 #8
                // jumped lat -2.2 -> -20.9 in one frame). Ungated; ~0.5 s throttle.
                if (driveLogFrameCount > 0
                    && Math.Abs(lastLaneLateralError - lastLoggedLat) > LAT_SNAP_DELTA_M
                    && dPlanar < 1f
                    && nowTicks - lastLatSnapLogTicks > 5000000)
                {
                    lastLatSnapLogTicks = nowTicks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lat-snap:"
                        + " from=" + lastLoggedLat.ToString("F1")
                        + " to=" + lastLaneLateralError.ToString("F1")
                        + " dPlanar=" + dPlanar.ToString("F2")
                        + " onRoad=" + nativeOnRoad);
                }
                lastLoggedLat = lastLaneLateralError;

                // iter-32 R7: off-road-risk early warning (log-only). Lateral
                // offset exceeds the road's estimated half-width (lanes x
                // LANE_WIDTH_M plus the link's extra/shoulder width, ADDITIVE
                // margin only) while the native still reports on-road — fires
                // before IsPositionOnRoad flips, giving the log the earliest
                // drift marker. 5 s throttle.
                int laneCount32 = lastLaneOffsetFwd + lastLaneOffsetBwd;
                if (laneCount32 > 0 && nativeOnRoad
                    && Math.Abs(lastLaneLateralError) >
                        (laneCount32 * LANE_WIDTH_M * 0.5f + lastLaneWidthExtraM + 1.5f)
                    && nowTicks - lastOffroadRiskLogTicks > 50000000L)
                {
                    lastOffroadRiskLogTicks = nowTicks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT offroad-risk:"
                        + " lat=" + lastLaneLateralError.ToString("F1")
                        + " lanes=" + laneCount32
                        + " extraW=" + lastLaneWidthExtraM
                        + " halfW=" + (laneCount32 * LANE_WIDTH_M * 0.5f + lastLaneWidthExtraM).ToString("F1")
                        + " spd=" + speed.ToString("F1")
                        // iter-34 BS-6: road context inline — the 07-03 lat=47.2
                        // false fire needed the FRAME block to diagnose.
                        + " onRoad=" + isOnValidRoad
                        + " nativeOnRoad=" + nativeOnRoad
                        + " node=" + lastPathStartNodeIdx
                        + " latAgeMs=" + (lastLaneLateralErrorTicks > 0
                            ? (nowTicks - lastLaneLateralErrorTicks) / 10000 : -999)
                        + " skew=" + vehicleSkewAngle.ToString("F1"));
                }

                // iter-29 C6: wedge-duration stopwatch (arm on speed<1, any road state) so the
                // WEDGE failClass reports wedgeMs even when stuckLayer never armed (it read 0/dead).
                if (speed < 1f) { if (lowSpeedAnyStartTicks == 0) lowSpeedAnyStartTicks = nowTicks; }
                else lowSpeedAnyStartTicks = 0;

                // iter-27 L2: push this frame's scalars into the pre-trigger ring.
                driveScalarRing[driveScalarRingCount % DRIVE_RING_SIZE] = new DriveScalar
                {
                    ticks = nowTicks,
                    frame = (int)driveLogFrameCount,
                    speed = speed,
                    bh = veh != null ? veh.BodyHealth : 0f,
                    eh = veh != null ? veh.EngineHealth : 0f,
                    skew = vehicleSkewAngle,
                    lat = lastLaneLateralError,
                    onRoad = nativeOnRoad,
                    mode = currentDriveMode.ToString(),
                    owner = brakeOwner,
                    // iter-39 L6: was smoothedSteerCorrection — the OBSTACLE-AVOIDANCE
                    // term only — while the FRAME line prints cachedSteerCorrection
                    // under the same name steerCmd. Two different quantities, one
                    // name: the lookback ring said steer=0.01 at 07-23 marker #11
                    // while the wheel was getting ~0.81. Store the same quantity the
                    // FRAME line calls steerCmd.
                    steerCmd = cachedSteerCorrection,
                    brakeCmd = rampedBrakeInput,
                    decelMs2 = decelMs2,
                    wheelsDown = veh != null && !veh.IsInAir
                };
                driveScalarRingCount++;
                // iter-27 L2: heartbeat so the recent-decisions ring can't go stale
                // (014616 #10: its newest entry was ~70 s old). ~2 s cadence.
                if (nowTicks - lastHeartbeatTicks > 20000000L)
                {
                    lastHeartbeatTicks = nowTicks;
                    RecordDriveDecision("tick spd=" + speed.ToString("F1")
                        + " bh=" + (veh != null ? veh.BodyHealth.ToString("F0") : "-")
                        + " skew=" + vehicleSkewAngle.ToString("F1")
                        + " mode=" + currentDriveMode + " own=" + brakeOwner);
                }

                lastLoggedPos = pos;
                lastLoggedHeading = heading;
                lastLoggedZ = pos.Z;
                lastLoggedSpeed = speed;
                driveLogFrameCount++;
            }
            catch { }
        }

        // Iter-9 Patch C: reset all location-specific drive-assist state.
        // Called from:
        //   - the planar-jump branch in ProcessSteeringAssist (covers player
        //     long-range teleports and any other code path that warps the
        //     vehicle without touching the handle)
        //   - CheckRoadTeleport's 3 fire sites (covers the mod-initiated
        //     teleports whose short jumps the planar-jump gate misses)
        // Also schedules a 500 ms post-teleport brake hold so the car doesn't
        // continue closing on whatever's at the new location while the next
        // 1-2 scans rebuild a fresh threat picture.
        private void ResetForTeleport(string source)
        {
            cachedBrakeThreatPos = GTA.Math.Vector3.Zero;
            cachedBrakeThreatVel = GTA.Math.Vector3.Zero;
            cachedBrakeThreatStamp = 0;
            cachedBrakeThreatFirstSeenStamp = 0;
            cachedSteerThreatPos = GTA.Math.Vector3.Zero;
            cachedSteerThreatVel = GTA.Math.Vector3.Zero;
            cachedSteerThreatStamp = 0;
            emergencyBrakeActive = false;
            wasObstacleInBrakeZone = false;
            criticalZoneArmFrames = 0;
            brakeArmed = false;
            rampedBrakeInput = 0f;
            cachedBrakeMagnitude = 0f;
            cachedSteerCorrection = 0f;
            smoothedSteerCorrection = 0f;
            smoothedRoadCorrection = 0f;
            lastRoadCorrection = 0f;
            cachedAvoidDirection = 0;
            lastNonZeroAvoidDir = 0;
            lastNonZeroAvoidDirTicks = 0;
            proposedAvoidDirection = 0;
            avoidDirHoldFrames = 0;
            // Iter-11 Patch I: reset distance history on teleport so the
            // post-teleport rising-distance check isn't fooled by the jump.
            cachedBrakeDistHistoryValid = false;
            cachedBrakeDistIdx = 0;
            // Iter-12 Patch Q: post-teleport position is on a road by
            // construction (TeleportToNearestRoad puts us on the nearest
            // valid node). Clear the off-named-street tracking so we don't
            // immediately re-trigger the off-road override at the new spot.
            offNamedStreetSinceTicks = 0;
            offNamedStreetLogged = false;
            // Path polyline rebuilds on the next BuildPathPolyline call;
            // clearing it here prevents Stanley from steering toward an OLD
            // road node before the rebuild runs.
            pathPolyline.Clear();
            hasRecoveryTarget = false;
            recoveryTargetPos = GTA.Math.Vector3.Zero;
            recoveryTargetHeading = 0f;
            recoveryTargetDistance = 999f;
            // A 30 deg post-teleport heading diff vs a stale road tangent
            // isn't a real skew, so don't carry the streak across.
            skewFailureStreak = 0;
            laneKeepFailureStreak = 0;
            // New location: drop the lane-change hysteresis history so the first
            // LaneCenterFromNode at the new road doesn't bias toward the old lane
            // index (vehicle-change already resets this; teleport now matches).
            lastLaneIndex = int.MinValue;
            // Schedule the post-teleport brake hold.
            postTeleportBrakeHoldUntilTicks = ModClock.Ticks + POST_TELEPORT_BRAKE_HOLD_TICKS; // ModClock pair (read in ApplyCachedSteeringInputs)
            // iter-20 H2: warm-up window — keep scans alive at the new location
            // even while stationary, so a blind player arrives with a fresh
            // threat picture instead of 2.5 s-stale data (224937 flag #6).
            teleportWarmUntilTicks = DateTime.Now.Ticks + TELEPORT_WARM_TICKS;
            prevStanleyLatErrorTicks = 0; // iter-21 I2: teleport invalidates damping history
            // iter-20 H6: a teleport must never bridge a health delta.
            autoCollisionLastHealth = -1f;
            autoCollisionLastBodyHealth = -1f;
            autoCollisionLastEngineHealth = -1f;
            // Update the position cache so the planar-jump check doesn't
            // re-fire next scan from the same data.
            string tpStreet = "";
            try
            {
                Vehicle v = Game.Player.Character != null && Game.Player.Character.IsInVehicle()
                    ? Game.Player.Character.CurrentVehicle : null;
                if (v != null)
                {
                    lastDriveAssistVehiclePos = v.Position;
                    // iter-20 H2: one spoken arrival cue with street + road type.
                    tpStreet = World.GetStreetName(v.Position);
                    string tpRoadType = MapDb.GetRoadTypeAt(v.Position);
                    Speech.Info(string.IsNullOrEmpty(tpStreet)
                        ? "Arrived at new location."
                        : "Arrived: " + tpStreet
                          + (tpRoadType != "unknown" ? ", " + tpRoadType : ""));
                }
            }
            catch { }
            if (driveLogger != null && driveLogger.IsRunning)
                driveLogger.Write("[F" + driveLogFrameCount
                    + "] EVENT teleport-reset: source=" + source
                    + " street=" + tpStreet);
            RecordDriveDecision("teleport-reset: source=" + source);
        }

        // Pushes one discrete drive-assist decision onto the ring buffer. Kept
        // cheap so it can be called from the per-tick decision paths. The F1
        // failure snapshot reads the last 5 back out.
        private void RecordDriveDecision(string decision)
        {
            try
            {
                driveDecisionLog[driveDecisionLogCount % driveDecisionLog.Length] =
                    "[F" + driveLogFrameCount + " " + DateTime.Now.ToString("HH:mm:ss")
                    + "] " + decision;
                driveDecisionLogCount++;
            }
            catch { }
        }

        // Writes a "player-indicated failure" snapshot to the drive-assist log.
        // Triggered by F1 so a play-tester can independently mark a failure
        // moment; the block captures everything needed to diagnose it later.
        private void LogPlayerIndicatedFailure()
        {
            if (driveLogger == null || !driveLogger.IsRunning)
            {
                Speech.Info("Failure marker needs drive assist debug logging turned on.");
                return;
            }
            if (LogCollisionSnapshot("PLAYER-INDICATED-FAILURE", null))
                Speech.Info("Failure marked in drive assist log.");
            else
                Speech.Info("Failure marker error.");
        }

        // Shared snapshot writer used by the F1 player marker (Patch F) and by
        // auto-collision detection (Patch G). The tag distinguishes them in
        // the log so post-hoc analysis can either merge or separate the two
        // populations. Extra is a one-line annotation appended to the marker
        // header (auto-collision uses it to record healthDelta=...). Returns
        // true on success.
        // iter-39 L3: peak speed over the last <windowTicks> from the pre-trigger ring.
        // veh.Speed AT marker time is a POST-impact reading — the collision has already
        // stopped the car. 07-23 marker #7 ran five frames at 24.6-24.8 m/s and then
        // logged impactSpeed=1.5, which also dropped it through the classifier's
        // speed ladder into the low-speed catch-all and mislabelled a 55 mph head-on
        // wall strike as LATERAL-OFFROAD. The ring is already populated every frame.
        // ===================================================================
        // iter-52 E1: snapshot every failure, not just two of them
        // ===================================================================
        // LogCollisionSnapshot had exactly two call sites — AUTO-COLLISION and
        // PLAYER-INDICATED-FAILURE. Every EVENT engine-stuck, stuck-layer, wedge-damage
        // and damage-tally fired with no snapshot at all, which is why triage-log.py
        // needs an unmarked-damage sweep: the pipeline reconstructs what the
        // instrumentation never recorded. This wrapper closes that gap.
        //
        // Rate-limited two ways, because a stuck ladder can re-fire at 60 Hz:
        //   1. per-tag cooldown, and
        //   2. suppression while the vehicle has not moved since that tag's last
        //      snapshot — a wedge that is still a wedge is the same wedge.
        // Suppressed counts are logged, never silently dropped.
        private readonly Dictionary<string, long> snapshotTagLastTicks = new Dictionary<string, long>();
        private readonly Dictionary<string, GTA.Math.Vector3> snapshotTagLastPos
            = new Dictionary<string, GTA.Math.Vector3>();
        private readonly Dictionary<string, int> snapshotTagSuppressed = new Dictionary<string, int>();
        private const long SNAPSHOT_TAG_COOLDOWN_MS = 8000;
        private const float SNAPSHOT_MOVED_M = 6f;

        // ===================================================================
        // iter-52 E4: image preroll ring
        // ===================================================================
        // A JPEG ring is unaffordable — it would mean encoding every frame. Instead
        // hold a few RAW downscaled frames in memory and only encode them when a
        // failure actually fires. Grabs are ARMED, not continuous: the ring only runs
        // when the same signals that arm stuck detection say a failure is plausible,
        // so clean driving never pays the once-per-second GDI blit.
        private const int PREROLL_FRAMES = 4;              // t-3s .. t0 at 1 Hz
        private const long PREROLL_INTERVAL_MS = 1000;
        private const long PREROLL_DISARM_MS = 15000;      // hold armed this long after the trigger clears
        private readonly System.Drawing.Bitmap[] prerollRing = new System.Drawing.Bitmap[PREROLL_FRAMES];
        private int prerollHead = 0;
        private int prerollCount = 0;
        private long prerollNextGrabTicks = 0;
        private long prerollArmedUntilTicks = 0;

        /// <summary>True when a failure looks plausible right now: the stuck ladder is
        /// engaged, the low-speed timer is running, or the assist is in a recovery mode.
        /// Exactly the conditions the stuck detector itself arms on.</summary>
        private bool PrerollShouldArm()
        {
            if (stuckLayer >= 1) return true;
            if (lowSpeedAnyStartTicks > 0) return true;
            if (currentDriveMode != DriveMode.LaneKeeping) return true;
            return false;
        }

        private void TickSnapshotPreroll()
        {
            if (getSetting("snapshotPreroll") != 1 || getSetting("snapshotImage") != 1) return;
            if (snapshotWriter == null || !snapshotWriter.IsRunning) return;
            if (!Game.Player.Character.IsInVehicle()) return;

            long now = ModClock.Ticks;
            if (PrerollShouldArm()) prerollArmedUntilTicks = now + PREROLL_DISARM_MS * 10000L;
            if (now > prerollArmedUntilTicks)
            {
                ClearPrerollRing();
                return;
            }
            if (now < prerollNextGrabTicks) return;
            prerollNextGrabTicks = now + PREROLL_INTERVAL_MS * 10000L;

            try
            {
                var bmp = SnapshotWriter.GrabScreen();
                if (bmp == null) return;
                if (prerollRing[prerollHead] != null) prerollRing[prerollHead].Dispose();
                prerollRing[prerollHead] = bmp;
                prerollHead = (prerollHead + 1) % PREROLL_FRAMES;
                if (prerollCount < PREROLL_FRAMES) prerollCount++;
            }
            catch { /* a failed grab must never take the game down */ }
        }

        private void ClearPrerollRing()
        {
            if (prerollCount == 0) return;
            for (int i = 0; i < PREROLL_FRAMES; i++)
            {
                if (prerollRing[i] == null) continue;
                try { prerollRing[i].Dispose(); } catch { }
                prerollRing[i] = null;
            }
            prerollHead = 0;
            prerollCount = 0;
        }

        /// <summary>Hands the buffered frames to the writer, oldest first, named -pre3
        /// .. -pre1 so they sort next to the failure frame. Ownership of each bitmap
        /// passes to the writer, so the ring is emptied rather than disposed here.</summary>
        private void FlushPrerollFor(int seq, string tag)
        {
            if (prerollCount == 0 || snapshotWriter == null) return;
            for (int k = prerollCount; k >= 1; k--)
            {
                int idx = ((prerollHead - k) % PREROLL_FRAMES + PREROLL_FRAMES) % PREROLL_FRAMES;
                var bmp = prerollRing[idx];
                if (bmp == null) continue;
                prerollRing[idx] = null;
                snapshotWriter.Enqueue(seq, tag, "-pre" + k, bmp);
            }
            prerollHead = 0;
            prerollCount = 0;
        }

        private void SnapshotFailure(string tag, string extra)
        {
            if (getSetting("snapshotAllFailures") != 1) return;
            if (driveLogger == null || !driveLogger.IsRunning) return;

            long now = ModClock.Ticks;
            Ped player = Game.Player.Character;
            GTA.Math.Vector3 pos = player.IsInVehicle()
                ? player.CurrentVehicle.Position : player.Position;

            long last;
            if (snapshotTagLastTicks.TryGetValue(tag, out last))
            {
                bool cool = now - last < SNAPSHOT_TAG_COOLDOWN_MS * 10000L;
                GTA.Math.Vector3 lastPos;
                bool stationary = snapshotTagLastPos.TryGetValue(tag, out lastPos)
                                  && Dist2D(pos, lastPos) < SNAPSHOT_MOVED_M;
                if (cool || stationary)
                {
                    int n;
                    snapshotTagSuppressed.TryGetValue(tag, out n);
                    snapshotTagSuppressed[tag] = n + 1;
                    return;
                }
            }

            snapshotTagLastTicks[tag] = now;
            snapshotTagLastPos[tag] = pos;

            int suppressed;
            if (snapshotTagSuppressed.TryGetValue(tag, out suppressed) && suppressed > 0)
            {
                snapshotTagSuppressed[tag] = 0;
                extra = (extra ?? "") + " suppressedSinceLast=" + suppressed;
            }

            LogCollisionSnapshot(tag, extra);
        }

        private float PeakRingSpeedWithin(long windowTicks)
        {
            long cutoff = DateTime.Now.Ticks - windowTicks;
            int n = driveScalarRingCount < DRIVE_RING_SIZE ? driveScalarRingCount : DRIVE_RING_SIZE;
            float peak = 0f;
            for (int i = 0; i < n; i++)
            {
                int idx = (driveScalarRingCount - n + i) % DRIVE_RING_SIZE;
                if (driveScalarRing[idx].ticks >= cutoff && driveScalarRing[idx].speed > peak)
                    peak = driveScalarRing[idx].speed;
            }
            return peak;
        }

        private bool LogCollisionSnapshot(string tag, string extra)
        {
            try
            {
                if (driveLogger == null || !driveLogger.IsRunning) return false;

                Ped player = Game.Player.Character;
                Vehicle veh = player.IsInVehicle() ? player.CurrentVehicle : null;
                GTA.Math.Vector3 pos = veh != null ? veh.Position : player.Position;
                collisionMarkerSeq++;
                long now = DateTime.Now.Ticks;

                // iter-36 P0-1: compute the failure classifier BEFORE the header so
                // the marker line itself is self-classifying. In iter-35, 33 of 47
                // failure-table rows were all dashes because the P-marker header
                // carried zero kv fields while the snapshot body had the answers.
                float fcSpeed = veh != null ? veh.Speed : 0f;
                // iter-39 L3: classify on the PRE-impact peak, not the post-impact
                // reading. fcSpeed stays as the instantaneous value for the spd= field.
                float fcSpeedPeak = Math.Max(fcSpeed, PeakRingSpeedWithin(3000000L)); // 300 ms
                float fcSkew = vehicleSkewAngle;
                float fcLat = lastLaneLateralError;
                bool laneOffOn = getSetting("laneOffsetPolyline") == 1;
                bool fcInRecovery = currentDriveMode != DriveMode.LaneKeeping
                    || pivotEscapeActive || stuckLayer >= 1 || alignmentEngageReverse;
                long recentWedgeMs = (stuckLayer >= 1 && stuckLayerSinceTicks > 0)
                    ? (now - stuckLayerSinceTicks) / 10000 : -1;
                bool fcJunction = veh != null && NodeGraph.IsLoaded
                    && NodeGraph.FindNearestNode(pos, JUNCTION_SNAP_RADIUS,
                        NodeGraph.NodeFlags.Junction, NodeGraph.NodeFlags.None) >= 0;
                bool fcNativeOnRoad = veh != null && IsPositionOnRoad(pos);
                long lowOffRoadMs = lowSpeedOffRoadStartTicks > 0
                    ? (now - lowSpeedOffRoadStartTicks) / 10000 : -1;
                long wedgeMs = lowSpeedAnyStartTicks > 0
                    ? (now - lowSpeedAnyStartTicks) / 10000 : -1;
                float fcDecel = lastDecelMs2;
                bool fcWheelsDown = veh != null && !veh.IsInAir;
                long offRoadDurMs = offRoadStartTicks > 0 ? (ModClock.Ticks - offRoadStartTicks) / 10000 : -1; // ModClock pair
                long latAgeMs = lastLaneLateralErrorTicks > 0 ? (now - lastLaneLateralErrorTicks) / 10000 : -1;
                // iter-39 L4: age of the perception this classification would rest on.
                // Two 07-23 markers were classified off a lane model 2.6 s and 4.4 s
                // old (the assist was suspended, so nothing was being recomputed) while
                // the header's own scanAgeMs claimed 0. Committing to a failure class
                // computed from frozen inputs is worse than admitting we don't know:
                // marker #2's LATERAL-OFFROAD came from |lat|>8 on a 2652 ms stale lat.
                long scanAgeMsSnap = lastScanCompletedTicks > 0
                    ? (ModClock.Ticks - lastScanCompletedTicks) / 10000 : -1;
                long perceptAgeMs = Math.Max(latAgeMs, scanAgeMsSnap);

                string failClass;
                // iter-40 L5: split the stale class by CAUSE. Both 07-28 stale markers
                // (#4 stale2816ms, #6 stale681ms) were suspensions — perception was
                // switched off on purpose, and their perceptAgeMs matched suspendedMs
                // to within 1 ms. Labelling that "UNKNOWN-STALE" reads to an analyst as
                // a broken perception pipeline and sends the whole investigation the
                // wrong way. Reserve UNKNOWN-STALE for stale perception while the
                // assist is actually RUNNING, which is the real defect.
                if (veh == null)
                    failClass = "OTHER";
                // iter-46 0b-6: the dead-vehicle latch (:6696) makes the assist
                // block at :6705 skip entirely, so lastScanCompletedTicks freezes
                // — but assistSuspended stays FALSE and InWatchdogGrace() stays
                // false, so a destroyed hull fell through to UNKNOWN-STALE, whose
                // own comment reserves it for "stale perception while the assist
                // is actually RUNNING". 07-31 marker #18 was classified
                // UNKNOWN-STALE!stale14258ms with the digest's assist column
                // reading ON, 14 s after EVENT assist-dead-vehicle. That is the
                // classifier asserting the opposite of the truth, and it cost
                // real analysis time. Test it BEFORE the suspended/grace tests.
                else if (deadVehicleHandle != 0)
                    failClass = "DEAD-VEHICLE";
                // iter-46 0b-6: the intoxication stand-down is a PARALLEL latch to
                // assistSuspended (:27325), so it was invisible here too.
                else if (intoxAssistSuspend)
                    failClass = "INTOX-STANDDOWN";
                else if (perceptAgeMs > 500 && assistSuspended)
                    failClass = "SUSPENDED";
                else if (perceptAgeMs > 500 && InWatchdogGrace())
                    failClass = "PLAYER-GRACE";
                else if (perceptAgeMs > 500)
                    failClass = "UNKNOWN-STALE";
                else if (fcSpeedPeak < 3f && (fcInRecovery || laneKeepFailureStreak >= 12
                    || cachedHandbrakeMagnitude > 0.1f))
                    failClass = "WEDGE";
                else if (fcSpeedPeak > 15f && curveBrakeRequest > 0.05f)
                    failClass = "OVERSHOOT";
                else if (Math.Abs(fcSkew) > 60f && fcSpeedPeak > 5f && fcJunction)
                    failClass = "JUNCTION-PHANTOM";
                else if (Math.Abs(fcLat) > 8f || (!fcNativeOnRoad && fcSpeedPeak < 5f))
                    failClass = "LATERAL-OFFROAD";
                else if (fcSpeedPeak > 5f && Math.Abs(fcLat) > 2.5f && !fcInRecovery && fcNativeOnRoad)
                    failClass = "LANE-OFFSET";
                else
                    failClass = "OTHER";

                // Street as a SPACE-FREE token (triage kv regex is key=(\S*)): the
                // compact v2 name first, native name with spaces stripped as the
                // fallback (v2 street coverage is structurally sparse — 7,740 of
                // 67,454 nodes).
                string hdrStreet = "";
                if (NodeGraph.IsLoaded && NodeGraph.SchemaVersion >= 2 && lastPathStartNodeIdx >= 0)
                    hdrStreet = NodeGraph.GetStreetName(lastPathStartNodeIdx);
                if (string.IsNullOrEmpty(hdrStreet))
                {
                    try { hdrStreet = (World.GetStreetName(pos) ?? "").Replace(" ", ""); }
                    catch { hdrStreet = ""; }
                }
                if (string.IsNullOrEmpty(hdrStreet)) hdrStreet = "-";

                string hdrKv = "failClass=" + failClass
                    + " mode=" + currentDriveMode
                    + " layer=" + stuckLayer
                    + " spd=" + fcSpeed.ToString("F1")
                    + " peakSpd300=" + fcSpeedPeak.ToString("F1") // iter-39 L3: pre-impact peak; spd= is post-impact
                    + " lat=" + fcLat.ToString("F2")
                    + " latAgeMs=" + latAgeMs
                    + " perceptAgeMs=" + perceptAgeMs // iter-39 L4
                    + " skew=" + fcSkew.ToString("F1")
                    + " street=" + hdrStreet
                    + " bh=" + (veh != null ? veh.BodyHealth.ToString("F0") : "-")
                    + " eh=" + (veh != null ? veh.EngineHealth.ToString("F0") : "-")
                    + " navC=" + (navAssistDistCenter < 900f
                        ? navAssistDistCenter.ToString("F1") : "none")
                    + " wedgeMs=" + wedgeMs
                    // iter-40 L4: WAS THE ASSIST EVEN DRIVING? Half the 07-28 markers
                    // occurred with the assist suspended or in watchdog grace, and not
                    // one artifact an agent reads could show it — the fields existed
                    // only on the FRAME line, which the digest and the compact incident
                    // excerpts do not carry. Without this a marker taken while the human
                    // had the car is indistinguishable from an assist failure, which
                    // corrupts both the failure table and the rate trend.
                    + " suspended=" + assistSuspended
                    + " suspendedMs=" + (assistSuspended && assistSuspendedSinceTicks > 0
                        ? ((ModClock.Ticks - assistSuspendedSinceTicks) / 10000).ToString() : "-") // ModClock pair
                    + " grace=" + InWatchdogGrace()
                    // iter-46 0b-6: two authority states that were invisible in the
                    // header, so the digest's `assist` column reported ON for both.
                    // vehDead freezes the whole assist block (:6705) without setting
                    // assistSuspended; intoxSusp is a deliberately PARALLEL latch
                    // (:27325) so it never touches assistSuspended either.
                    + " vehDead=" + (deadVehicleHandle != 0)
                    + " intoxSusp=" + intoxAssistSuspend
                    // iter-46 0b-5: carry the wanted level ON THE MARKER, so combat
                    // damage is segregated from a per-marker fact instead of from a
                    // reconstructed speech timeline. The marker is NOT suppressed —
                    // a crash during a chase is still a driving failure — it is
                    // reclassified, so triage can rank on drive-assist cost while
                    // the safety event stays visible.
                    + " wanted=" + Game.Player.WantedLevel
                    // iter-49 D: UNGATED. wanted= alone cannot separate "being shot
                    // at" from "has a star and is driving normally", which is why
                    // 932.1 of 07-31's 1552.0 marked-damage units were attributed to
                    // driving. These two say it outright.
                    + " bullet=" + underFireNow
                    + " proj=" + projectileNear
                    + " scanAgeMs=" + scanAgeMsSnap
                    + " wrongWay=" + wrongWayActive
                    // iter-40 L3: Vehicle.Speed is not a measurement while the mod
                    // injects velocity. Carry the displacement-derived value so a
                    // fabricated speed is detectable at the marker itself.
                    + " trueSpd=" + trueSpeed.ToString("F1")
                    + " locusCumMs=" + (stuckLocusCumTicks / 10000);

                StringBuilder sb = new StringBuilder(2800);
                sb.AppendLine("==================================================");
                sb.AppendLine("[F" + driveLogFrameCount + "] " + tag + " #" + collisionMarkerSeq
                    + (string.IsNullOrEmpty(extra) ? "" : "  " + extra)
                    + "  " + hdrKv
                    + "  t=" + DateTime.Now.ToString("HH:mm:ss.fff"));
                sb.AppendLine("==================================================");

                // 1. Exact vehicle coordinates.
                sb.AppendLine("  coords: (" + pos.X.ToString("F4") + ","
                    + pos.Y.ToString("F4") + "," + pos.Z.ToString("F4") + ")"
                    + (veh == null ? "  <ON-FOOT>" : ""));

                // 2. Nearest vehicles within 25 m. World.GetNearbyVehicles
                //    returns nearest-first; the player's own vehicle is skipped.
                sb.AppendLine("  nearby-vehicles (25m):");
                int vehShown = 0;
                foreach (Vehicle v in World.GetNearbyVehicles(pos, 25f))
                {
                    if (v == null || !v.Exists()) continue;
                    if (veh != null && v.Handle == veh.Handle) continue;
                    string vn = v.LocalizedName;
                    if (string.IsNullOrEmpty(vn) || vn == "NULL") vn = v.DisplayName;
                    sb.AppendLine("    - " + vn
                        + " dist=" + pos.DistanceTo(v.Position).ToString("F1") + "m"
                        + " pos=" + FmtV(v.Position)
                        + " speed=" + v.Speed.ToString("F1") + "m/s");
                    if (++vehShown >= 8) break;
                }
                if (vehShown == 0) sb.AppendLine("    (none)");

                // 3. Nearest detected obstacles within 25 m: peds and props,
                //    plus the assist's live directional shape-cast readings.
                sb.AppendLine("  nearby-obstacles (25m):");
                int obsShown = 0;
                foreach (Ped p in World.GetNearbyPeds(pos, 25f))
                {
                    if (p == null || !p.Exists()) continue;
                    if (p.Handle == player.Handle) continue;
                    sb.AppendLine("    - ped handle=" + p.Handle
                        + " dist=" + pos.DistanceTo(p.Position).ToString("F1") + "m"
                        + " pos=" + FmtV(p.Position));
                    if (++obsShown >= 6) break;
                }
                int propShown = 0;
                foreach (Prop pr in World.GetNearbyProps(pos, 25f))
                {
                    if (pr == null || !pr.Exists()) continue;
                    sb.AppendLine("    - prop model=" + pr.Model.Hash
                        + " dist=" + pos.DistanceTo(pr.Position).ToString("F1") + "m"
                        + " pos=" + FmtV(pr.Position));
                    if (++propShown >= 6) break;
                }
                if (obsShown == 0 && propShown == 0) sb.AppendLine("    (none)");
                sb.AppendLine("    shapecast: L=" + FmtF(navAssistDistLeft) + "/" + navAssistTypeLeft
                    + " C=" + FmtF(navAssistDistCenter) + "/" + navAssistTypeCenter
                    + " R=" + FmtF(navAssistDistRight) + "/" + navAssistTypeRight
                    + " B=" + FmtF(navAssistDistBehind) + "/" + navAssistTypeBehind);

                // 4. Nearest road node.
                OutputArgument nodeOut = new OutputArgument();
                OutputArgument nodeHd  = new OutputArgument();
                OutputArgument nodeLn  = new OutputArgument();
                // iter-49 A3: mirror the PATH flags, so the node this snapshot names
                // is the node the controller is actually steering against. A
                // diagnostic that queries a different node set than the code it is
                // diagnosing is worse than no diagnostic.
                bool nodeOk = Function.Call<bool>(Hash.GET_NTH_CLOSEST_VEHICLE_NODE_WITH_HEADING,
                    pos.X, pos.Y, pos.Z, 1, nodeOut, nodeHd, nodeLn,
                    NodeFlagsFor(NODEFLAGS_PATH), 3.0f, 0f);
                if (nodeOk)
                {
                    GTA.Math.Vector3 nodePos = nodeOut.GetResult<GTA.Math.Vector3>();
                    sb.AppendLine("  nearest-road-node: pos=" + FmtV(nodePos)
                        + " dist=" + pos.DistanceTo(nodePos).ToString("F1") + "m"
                        + " heading=" + nodeHd.GetResult<float>().ToString("F1"));
                }
                else
                {
                    sb.AppendLine("  nearest-road-node: (none found)");
                }

                // 5. Pitch and roll of the vehicle.
                if (veh != null)
                {
                    GTA.Math.Vector3 rot = veh.Rotation;
                    sb.AppendLine("  attitude: pitch=" + rot.X.ToString("F1")
                        + " roll=" + rot.Y.ToString("F1"));
                }
                else
                {
                    sb.AppendLine("  attitude: (on-foot)");
                }

                // 6. Whether the vehicle is in water.
                sb.AppendLine("  inWater: " + (veh != null ? veh.IsInWater : player.IsInWater));

                // 7. Vehicle health.
                if (veh != null)
                {
                    sb.AppendLine("  health: body=" + veh.BodyHealth.ToString("F0")
                        + " engine=" + veh.EngineHealth.ToString("F0")
                        + " overall=" + veh.HealthFloat.ToString("F0"));
                }
                else
                {
                    sb.AppendLine("  health: (on-foot) player=" + player.HealthFloat.ToString("F0"));
                }

                // 8. Cached threat dump (Iter-9 Patch F). If a marker shows
                //    obstacles nearby but no brake, this section tells us
                //    whether the threat was cached but didn't make it through
                //    the gates, vs. never cached at all.
                if (cachedBrakeThreatPos != GTA.Math.Vector3.Zero)
                {
                    long ageMs = cachedBrakeThreatStamp > 0
                        ? (now - cachedBrakeThreatStamp) / 10000 : -1;
                    long firstSeenMs = cachedBrakeThreatFirstSeenStamp > 0
                        ? (now - cachedBrakeThreatFirstSeenStamp) / 10000 : -1;
                    sb.AppendLine("  cached-brake-threat: pos=" + FmtV(cachedBrakeThreatPos)
                        + " ageMs=" + ageMs + " firstSeenMs=" + firstSeenMs
                        + " velMag=" + cachedBrakeThreatVel.Length().ToString("F1"));
                }
                else
                {
                    sb.AppendLine("  cached-brake-threat: (none)");
                }
                if (cachedSteerThreatPos != GTA.Math.Vector3.Zero)
                {
                    long sAgeMs = cachedSteerThreatStamp > 0
                        ? (now - cachedSteerThreatStamp) / 10000 : -1;
                    sb.AppendLine("  cached-steer-threat: pos=" + FmtV(cachedSteerThreatPos)
                        + " ageMs=" + sAgeMs
                        + " velMag=" + cachedSteerThreatVel.Length().ToString("F1"));
                }
                else
                {
                    sb.AppendLine("  cached-steer-threat: (none)");
                }

                // 9. Brake-pipeline detail (Iter-9 Patch F). Distinguishes
                //    "no brake fired" from "brake fired but blended down" etc.
                sb.AppendLine("  brake-detail: armed=" + brakeArmed
                    + " rampedBrake=" + rampedBrakeInput.ToString("F2")
                    + " cachedBrakeMag=" + cachedBrakeMagnitude.ToString("F2")
                    + " recoveryBrake=" + recoveryBrakeRequest.ToString("F2")
                    + " curveBrake=" + curveBrakeRequest.ToString("F2")
                    + " accBrake=" + accBrakeOut.ToString("F2")
                    + " emergency=" + emergencyBrakeActive
                    + " handbrake=" + cachedHandbrakeMagnitude.ToString("F2"));

                // 10. Lane / road / skew detail.
                long skewMs = persistentSkewStartTicks > 0
                    ? (ModClock.Ticks - persistentSkewStartTicks) / 10000 : 0; // ModClock pair (stamped from skewNow)
                sb.AppendLine("  road-detail: polylineCount=" + pathPolyline.Count
                    + " closestPolySeg=" + lastClosestPolySeg
                    + " skewMs=" + skewMs
                    + " skewStreak=" + skewFailureStreak
                    + " failStreak=" + laneKeepFailureStreak
                    + " roadCorrSmoothed=" + smoothedRoadCorrection.ToString("F2")
                    + " mode=" + currentDriveMode
                    // iter-33: v2 road context at the failure node — with v2 data
                    // loaded this names the street (every 07-02 snapshot would have
                    // read street=JoshR) and gives the speed category / extra width.
                    + (NodeGraph.IsLoaded && NodeGraph.SchemaVersion >= 2 && lastPathStartNodeIdx >= 0
                        ? " street=" + NodeGraph.GetStreetName(lastPathStartNodeIdx)
                          + " spdCat=" + NodeGraph.GetSpeedCategory(lastPathStartNodeIdx)
                          + " extraW=" + lastLaneWidthExtraM
                        : ""));

                // iter-26 B1: failure-class discriminator. Splits the persistent
                // low-speed WEDGE class (iter-25 M1-M7 territory) from a LANE-OFFSET
                // / centerline-tracking departure in one pass, so the next log can
                // attribute a failure without hand-reading coords. Live state only.
                // iter-36 P0-1: computation moved above the header (self-classifying
                // marker line); this section reuses those values verbatim.
                {
                    sb.AppendLine("  failClass: " + failClass
                        + " spd=" + fcSpeed.ToString("F1")
                        + " skew=" + fcSkew.ToString("F1")
                        + " skewAgeMs=" + (vehicleSkewStampTicks > 0 ? (DateTime.Now.Ticks - vehicleSkewStampTicks) / 10000 : -999) // iter-35 L6
                        + " lat=" + fcLat.ToString("F2")
                        + " stuckLayer=" + stuckLayer
                        + " recentWedgeMs=" + recentWedgeMs
                        + " inRecovery=" + fcInRecovery
                        + " junction=" + fcJunction
                        + " laneOffsetOn=" + laneOffOn
                        + " nativeOnRoad=" + fcNativeOnRoad
                        + " lowOffRoadMs=" + lowOffRoadMs
                        + " wedgeMs=" + wedgeMs
                        + " offsetWouldBe=" + lastLaneOffsetMag.ToString("F2")
                        + " decelMs2=" + fcDecel.ToString("F1")
                        + " wheelsDown=" + fcWheelsDown
                        + " rampedBrake=" + rampedBrakeInput.ToString("F2")
                        + " brakeArmed=" + brakeArmed
                        + " offRoadDurMs=" + offRoadDurMs
                        + " latAgeMs=" + latAgeMs
                        + " laneDepartStreak=" + laneDepartStreak
                        + " offFwd=" + lastLaneOffsetFwd
                        + " offBwd=" + lastLaneOffsetBwd
                        + " offJblend=" + lastLaneOffsetJBlend.ToString("F2"));
                }

                // 11. Vehicle-handling dump from the iter-8 registry (only
                //     meaningful when in a vehicle).
                if (veh != null)
                {
                    int gtaClass = Function.Call<int>(Hash.GET_VEHICLE_CLASS, veh);
                    VehicleAIHandlingInfo aiInfo = VehicleAIHandlingRegistry.GetForVehicle(veh);
                    sb.AppendLine("  vehicle-handling: gtaClass=" + gtaClass
                        + " aiHandling=" + (aiInfo != null ? aiInfo.Name : "(null)")
                        + " Min=" + (aiInfo != null ? aiInfo.MinBrakeDistance.ToString("F1") : "?")
                        + " Max=" + (aiInfo != null ? aiInfo.MaxBrakeDistance.ToString("F1") : "?")
                        + " MaxAt=" + (aiInfo != null ? aiInfo.MaxSpeedAtBrakeDistance.ToString("F1") : "?")
                        + " source=" + VehicleAIHandlingRegistry.LoadedFrom);
                }

                // 12. Most recent drive-assist decisions (newest last). Ring
                //     size was bumped 5 -> 30 in iter-9 Patch F.
                // iter-27 L2: pre-trigger lookback ring (~2 s of per-frame scalars),
                // so an F1 flag pressed AFTER the event still shows the run-up into
                // it. bhDropLast2s/ehDropLast2s make a flag with a recent hit
                // self-evident even when the instantaneous health reads recovered.
                {
                    long lbCutoff = now - 25000000L; // ~2.5 s in ticks
                    float lbMaxBh = veh != null ? veh.BodyHealth : 0f;
                    float lbMaxEh = veh != null ? veh.EngineHealth : 0f;
                    StringBuilder lb = new StringBuilder(1000);
                    int lbShown = 0;
                    // iter-35 L5: run-length collapse — a stationary car produces ~150
                    // byte-identical rows per snapshot (07-03 #2); repeats compress to
                    // one "... xN identical frames" line with zero information loss.
                    string lbPrevRow = null;
                    int lbRepeat = 0;
                    int lbCount = driveScalarRingCount < DRIVE_RING_SIZE ? driveScalarRingCount : DRIVE_RING_SIZE;
                    for (int i = 0; i < lbCount; i++)
                    {
                        int idx = (driveScalarRingCount - lbCount + i) % DRIVE_RING_SIZE;
                        DriveScalar e = driveScalarRing[idx];
                        if (e.ticks == 0 || e.ticks < lbCutoff) continue;
                        if (e.bh > lbMaxBh) lbMaxBh = e.bh;
                        if (e.eh > lbMaxEh) lbMaxEh = e.eh;
                        string lbRow = " s=" + e.speed.ToString("F1")
                            + " bh=" + e.bh.ToString("F0") + " eh=" + e.eh.ToString("F0")
                            + " skew=" + e.skew.ToString("F1") + " lat=" + e.lat.ToString("F2")
                            + " onRoad=" + e.onRoad + " mode=" + e.mode + " own=" + e.owner
                            + " steer=" + e.steerCmd.ToString("F2") + " brake=" + e.brakeCmd.ToString("F2")
                            + " decel=" + e.decelMs2.ToString("F1") + " whlDn=" + e.wheelsDown;
                        if (lbRow == lbPrevRow)
                        {
                            lbRepeat++;
                        }
                        else
                        {
                            if (lbRepeat > 0)
                                lb.AppendLine("    ... x" + lbRepeat + " identical frames");
                            lbRepeat = 0;
                            lb.AppendLine("    F" + e.frame + lbRow);
                            lbPrevRow = lbRow;
                        }
                        lbShown++;
                    }
                    if (lbRepeat > 0)
                        lb.AppendLine("    ... x" + lbRepeat + " identical frames");
                    float lbCurBh = veh != null ? veh.BodyHealth : 0f;
                    float lbCurEh = veh != null ? veh.EngineHealth : 0f;
                    sb.AppendLine("  lookback (~2s pre-trigger, oldest first): bhDropLast2s="
                        + (lbMaxBh - lbCurBh).ToString("F1")
                        + " ehDropLast2s=" + (lbMaxEh - lbCurEh).ToString("F1")
                        + " frames=" + lbShown);
                    if (lbShown > 0) sb.Append(lb.ToString());
                }
                sb.AppendLine("  recent-decisions (newest last):");
                int total = driveDecisionLogCount;
                if (total == 0)
                {
                    sb.AppendLine("    (none recorded)");
                }
                else
                {
                    int show = total < driveDecisionLog.Length ? total : driveDecisionLog.Length;
                    for (int i = show; i >= 1; i--)
                    {
                        int idx = (total - i) % driveDecisionLog.Length;
                        sb.AppendLine("    - " + driveDecisionLog[idx]);
                    }
                }

                // iter-52 E2: what the scalars cannot say. A 16-way ray fan, the
                // entities around the car and per-wheel ground contact — the difference
                // between "wedged on a kerb", "nose-in to a wall" and "boxed in by
                // traffic", which 24 iterations of numbers could not separate.
                if (getSetting("snapshotGeometry") == 1)
                {
                    try { AppendSceneGeometry(sb, veh, pos); }
                    catch (Exception gex)
                    {
                        sb.AppendLine("  geometry: FAILED " + MapDb.FmtLoadError(gex));
                    }
                }

                sb.AppendLine("==================================================");
                driveLogger.Write(sb.ToString().TrimEnd());

                // iter-52 E3: the frame itself. Queued to a background thread, so the
                // encode never lands on the script thread. collisionMarkerSeq is
                // already printed in the marker header, which is what joins the image
                // back to this snapshot with no extra bookkeeping.
                if (getSetting("snapshotImage") == 1 && snapshotWriter != null)
                {
                    // Preroll first so the run-up frames sort before the failure frame.
                    try { FlushPrerollFor(collisionMarkerSeq, tag); } catch { }
                    try { snapshotWriter.CaptureFor(collisionMarkerSeq, tag); } catch { }
                }
                return true;
            }
            catch
            {
                return false;
            }
        }

        /// <summary>Appends the scene around the vehicle to a failure snapshot: a
        /// 16-way swept-sphere fan at bumper height, a knee-height ring, the nearby
        /// entity table, per-wheel contact and road-node context.
        ///
        /// Sixteen casts in one frame is fine — this runs at a failure instant, not per
        /// frame. Every cast goes through CapsuleSweep, which is the single shape-test
        /// chokepoint and already handles the SHVDN OutputArgument refusal case and the
        /// non-unit-normal garbage guard.</summary>
        // Map + objects, matching the on-foot scanner at :6549. Vehicles and peds are
        // reported separately from the entity tables below, so including them here
        // would double-count the very thing the fan is meant to isolate: static
        // geometry the car is wedged against.
        private const IntersectFlags GEOM_FLAGS = IntersectFlags.Map | IntersectFlags.Objects;

        private void AppendSceneGeometry(System.Text.StringBuilder sb, Vehicle veh,
                                         GTA.Math.Vector3 pos)
        {
            sb.AppendLine("  --- scene geometry (iter-52) ---");

            Ped player = Game.Player.Character;
            float heading = veh != null ? veh.Heading : player.Heading;

            // Ray fan, in vehicle-relative bearings so the log reads the same whichever
            // way the car happens to be pointing.
            const int RAYS = 16;
            const float RAY_LEN = 12f;
            var fan = new System.Text.StringBuilder();
            for (int i = 0; i < RAYS; i++)
            {
                float relDeg = i * (360f / RAYS);
                double world = (heading + relDeg) * Math.PI / 180.0;
                var dir = new GTA.Math.Vector3(-(float)Math.Sin(world), (float)Math.Cos(world), 0f);
                var from = pos + new GTA.Math.Vector3(0, 0, 0.4f);

                GTA.Math.Vector3 hitPos, hitNorm;
                float d = CapsuleSweep(from, dir, RAY_LEN, 0.25f, GEOM_FLAGS,
                                       (Entity)veh ?? (Entity)player, out hitPos, out hitNorm);
                if (i > 0) fan.Append(' ');
                // -2 refusal and -1 miss are NOT the same thing and must stay
                // distinguishable: "the test did not run" would otherwise read as
                // "there is nothing there", which is how a wedge looks like open road.
                fan.Append((int)relDeg).Append(':')
                   .Append(d == -2f ? "refused" : d < 0f ? "clear" : d.ToString("F1"));
            }
            sb.AppendLine("  fan16: " + fan);

            // Knee height — the class of obstacle the bumper-height fan flies over and
            // that a car still grounds out on.
            var kneeFan = new System.Text.StringBuilder();
            for (int i = 0; i < 8; i++)
            {
                float relDeg = i * 45f;
                double world = (heading + relDeg) * Math.PI / 180.0;
                var dir = new GTA.Math.Vector3(-(float)Math.Sin(world), (float)Math.Cos(world), 0f);
                var from = pos + new GTA.Math.Vector3(0, 0, 0.15f);
                GTA.Math.Vector3 hitPos, hitNorm;
                float d = CapsuleSweep(from, dir, 6f, 0.12f, GEOM_FLAGS,
                                       (Entity)veh ?? (Entity)player, out hitPos, out hitNorm);
                if (i > 0) kneeFan.Append(' ');
                kneeFan.Append((int)relDeg).Append(':')
                       .Append(d == -2f ? "refused" : d < 0f ? "clear" : d.ToString("F1"));
            }
            sb.AppendLine("  fanKnee8: " + kneeFan);

            // Nearby entities, bearing relative to the vehicle's own heading.
            try
            {
                var nearby = World.GetNearbyVehicles(pos, 15f);
                int shown = 0;
                foreach (Vehicle v in nearby)
                {
                    if (v == null || !v.Exists()) continue;
                    if (veh != null && v.Handle == veh.Handle) continue;
                    if (shown++ >= 6) break;
                    double bearing = fixHeading(GetAngleOfLineBetweenTwoPoints(pos, v.Position) - heading);
                    sb.AppendLine("    veh: " + v.DisplayName
                        + " d=" + World.GetDistance(pos, v.Position).ToString("F1")
                        + " rel=" + ((int)bearing)
                        + " spd=" + v.Speed.ToString("F1")
                        + " relHead=" + ((int)fixHeading(v.Heading - heading)));
                }
                if (shown == 0) sb.AppendLine("    veh: (none within 15 m)");
            }
            catch { sb.AppendLine("    veh: (scan failed)"); }

            try
            {
                var peds = World.GetNearbyPeds(pos, 10f);
                int shown = 0;
                foreach (Ped p in peds)
                {
                    if (p == null || !p.Exists() || p.Handle == player.Handle) continue;
                    if (shown++ >= 4) break;
                    double bearing = fixHeading(GetAngleOfLineBetweenTwoPoints(pos, p.Position) - heading);
                    sb.AppendLine("    ped: d=" + World.GetDistance(pos, p.Position).ToString("F1")
                        + " rel=" + ((int)bearing) + " dead=" + p.IsDead);
                }
                if (shown == 0) sb.AppendLine("    ped: (none within 10 m)");
            }
            catch { sb.AppendLine("    ped: (scan failed)"); }

            if (veh != null)
            {
                try
                {
                    sb.AppendLine("  chassis: inAir=" + veh.IsInAir
                        + " upright=" + veh.IsUpright
                        + " onAllWheels=" + veh.IsOnAllWheels
                        + " roll=" + veh.Rotation.Y.ToString("F1")
                        + " pitch=" + veh.Rotation.X.ToString("F1")
                        + " health=" + veh.Health
                        + " bodyHealth=" + veh.BodyHealth.ToString("F0")
                        + " engineHealth=" + veh.EngineHealth.ToString("F0"));
                }
                catch { sb.AppendLine("  chassis: (read failed)"); }
            }

            // Ground clearance directly beneath, and the road model at the failure
            // point — "is there even road here" is the first question of every triage.
            try
            {
                float floorZ;
                bool haveFloor = TryGetApproxFloorZ(pos, out floorZ);
                sb.AppendLine("  ground: floorZ=" + (haveFloor ? floorZ.ToString("F2") : "n/a")
                    + " clearance=" + (haveFloor ? (pos.Z - floorZ).ToString("F2") : "n/a")
                    + " onRoad=" + IsPositionOnRoad(pos)
                    + " nodesLoaded=" + ArePathNodesLoadedAt(pos, "snapshotGeometry"));
            }
            catch { sb.AppendLine("  ground: (read failed)"); }
        }

        // ===================================================================
        // PATH-AWARE DRIVE ASSIST — implementations
        //
        // BuildPathPolyline is the single source of truth for "where should
        // the vehicle go in the next 5-80 m." Everything downstream (Stanley
        // steering, NPC corridor filtering) consumes the same `pathPolyline`
        // list. The path is recomputed once per detection tick to keep
        // ApplyCachedSteeringInputs cheap.
        // ===================================================================

        private bool HasGpsRoute()
        {
            // GET_GPS_BLIP_ROUTE_FOUND — true when the player has set a
            // waypoint AND the engine has finished computing a path to it.
            try { return Function.Call<bool>((Hash)HASH_GET_GPS_BLIP_ROUTE_FOUND); }
            catch { return false; }
        }

        private bool TrySampleGpsRoute(float distAhead, out GTA.Math.Vector3 outPos)
        {
            // GET_POS_ALONG_GPS_TYPE_ROUTE(out Vector3, BOOL startAtPlayer,
            //                              float dist, int slotType)
            // slotType 0 = Waypoint route. Returns false past route end.
            outPos = GTA.Math.Vector3.Zero;
            try
            {
                OutputArgument outArg = new OutputArgument();
                bool ok = Function.Call<bool>((Hash)HASH_GET_POS_ALONG_GPS_ROUTE,
                    outArg, false, distAhead, 0);
                if (!ok) return false;
                outPos = outArg.GetResult<GTA.Math.Vector3>();
                // Sometimes returns origin when route ends; sanity-check.
                if (outPos.LengthSquared() < 1f) return false;
                return true;
            }
            catch { return false; }
        }

        // =====================================================================
        // ROLLING-HISTORY BUFFER — see field declaration block for rationale.
        // All "ForLastMs" predicates return false when the buffer doesn't yet
        // span the requested window. First ~200 ms after session start or a
        // vehicle change therefore falls back to legacy behavior rather than
        // mis-firing on confident-looking sustained-evidence assertions.
        // =====================================================================
        private bool TryGetSnapshot(int framesBack, out DriveAssistSnapshot s)
        {
            if (framesBack < 0 || framesBack >= historyCount)
            {
                s = default(DriveAssistSnapshot);
                return false;
            }
            int idx = historyHead - 1 - framesBack;
            while (idx < 0) idx += HISTORY_CAPACITY;
            s = history[idx];
            return true;
        }

        private bool HistorySpansAtLeastMs(int ms)
        {
            if (historyCount < 2) return false;
            DriveAssistSnapshot newest, oldest;
            if (!TryGetSnapshot(0, out newest)) return false;
            if (!TryGetSnapshot(historyCount - 1, out oldest)) return false;
            long spanMs = (newest.TimestampTicks - oldest.TimestampTicks) / 10000;
            return spanMs >= ms;
        }

        // All "InLastMs" predicates fail-safe to false unless the buffer has
        // enough span to make the claim. Polled, not subscribed — cheap given
        // the buffer is at most 32 entries.
        private bool WasOnValidRoadForLastMs(int ms)
        {
            if (!HistorySpansAtLeastMs(ms)) return false;
            long nowTicks = driveAssistFrameTicks != 0 ? driveAssistFrameTicks : DateTime.Now.Ticks;
            long cutoffTicks = nowTicks - (long)ms * 10000;
            for (int i = 0; i < historyCount; i++)
            {
                DriveAssistSnapshot s;
                if (!TryGetSnapshot(i, out s)) return false;
                if (s.TimestampTicks < cutoffTicks) break;
                if (!s.IsOnValidRoad) return false;
            }
            return true;
        }

        private bool AnyLaneKeepOkRawInLastMs(int ms)
        {
            if (!HistorySpansAtLeastMs(ms)) return false;
            long nowTicks = driveAssistFrameTicks != 0 ? driveAssistFrameTicks : DateTime.Now.Ticks;
            long cutoffTicks = nowTicks - (long)ms * 10000;
            for (int i = 0; i < historyCount; i++)
            {
                DriveAssistSnapshot s;
                if (!TryGetSnapshot(i, out s)) return false;
                if (s.TimestampTicks < cutoffTicks) break;
                if (s.LaneKeepOkRaw) return true;
            }
            return false;
        }

        // Fraction of snapshots in the last `ms` window that report LaneKeepOkRaw.
        // Used by the sustained-failure gate so a single noisy OK frame doesn't
        // veto recovery for the whole confirm window.
        private float FractionLaneKeepOkInLastMs(int ms)
        {
            if (!HistorySpansAtLeastMs(ms)) return 0f;
            long nowTicks = driveAssistFrameTicks != 0 ? driveAssistFrameTicks : DateTime.Now.Ticks;
            long cutoffTicks = nowTicks - (long)ms * 10000;
            int okCount = 0;
            int total = 0;
            for (int i = 0; i < historyCount; i++)
            {
                DriveAssistSnapshot s;
                if (!TryGetSnapshot(i, out s)) break;
                if (s.TimestampTicks < cutoffTicks) break;
                total++;
                if (s.LaneKeepOkRaw) okCount++;
            }
            if (total == 0) return 0f;
            return (float)okCount / (float)total;
        }

        private float MaxAbsSteerCmdInLastMs(int ms)
        {
            float maxAbs = 0f;
            long nowTicks = driveAssistFrameTicks != 0 ? driveAssistFrameTicks : DateTime.Now.Ticks;
            long cutoffTicks = nowTicks - (long)ms * 10000;
            for (int i = 0; i < historyCount; i++)
            {
                DriveAssistSnapshot s;
                if (!TryGetSnapshot(i, out s)) break;
                if (s.TimestampTicks < cutoffTicks) break;
                float a = Math.Abs(s.CachedSteerCorrection);
                if (a > maxAbs) maxAbs = a;
            }
            return maxAbs;
        }

        // iter-34 BS-2: nearest shapecast contact as a compact label ("C/vehicle@3.8")
        // for grind-episode telemetry — identifies WHAT the car is grinding against.
        private string NearestContactLabel()
        {
            float best = 999f; string label = "none";
            if (navAssistTypeCenter != "none" && navAssistDistCenter < best)
            { best = navAssistDistCenter; label = "C/" + navAssistTypeCenter + "@" + navAssistDistCenter.ToString("F1"); }
            if (navAssistTypeLeft != "none" && navAssistDistLeft < best)
            { best = navAssistDistLeft; label = "L/" + navAssistTypeLeft + "@" + navAssistDistLeft.ToString("F1"); }
            if (navAssistTypeRight != "none" && navAssistDistRight < best)
            { best = navAssistDistRight; label = "R/" + navAssistTypeRight + "@" + navAssistDistRight.ToString("F1"); }
            if (navAssistTypeBehind != "none" && navAssistDistBehind < best)
            { best = navAssistDistBehind; label = "B/" + navAssistTypeBehind + "@" + navAssistDistBehind.ToString("F1"); }
            return label;
        }

        // iter-36 P0: identify WHAT delivered the damage. iter-35's 980-point
        // Dorset kill hit and the death-#1 grinder left no attacker identity in
        // the log at all. Space-free token: handle:model:spd:bearing (or "none").
        // Clears the stored damager so the NEXT hit re-identifies.
        private string IdentifyAttacker(Vehicle playerVeh)
        {
            try
            {
                if (playerVeh == null || !playerVeh.Exists()) return "none";
                foreach (Vehicle v in World.GetNearbyVehicles(playerVeh.Position, 15f))
                {
                    if (v == null || !v.Exists() || v.Handle == playerVeh.Handle) continue;
                    if (!Function.Call<bool>(Hash.HAS_ENTITY_BEEN_DAMAGED_BY_ENTITY,
                            playerVeh, v, true))
                        continue;
                    GTA.Math.Vector3 to = v.Position - playerVeh.Position;
                    float fdot = GTA.Math.Vector3.Dot(playerVeh.ForwardVector, to);
                    float rdot = GTA.Math.Vector3.Dot(playerVeh.RightVector, to);
                    string bearing = Math.Abs(fdot) >= Math.Abs(rdot)
                        ? (fdot >= 0f ? "ahead" : "behind")
                        : (rdot >= 0f ? "right" : "left");
                    // CLEAR_ENTITY_LAST_DAMAGE_ENTITY (raw hash: not in every SHVDN
                    // 3.6 enum build; codebase precedent 0xE8A25867FBA3B05E).
                    Function.Call((Hash)0xA72CD9CA74A5ECBA, playerVeh);
                    return v.Handle + ":" + v.DisplayName + ":"
                        + v.Speed.ToString("F1") + ":" + bearing;
                }
            }
            catch { }
            return "none";
        }

        private bool VehicleStoppedForLastMs(float speedMs, int ms)
        {
            if (!HistorySpansAtLeastMs(ms)) return false;
            long nowTicks = driveAssistFrameTicks != 0 ? driveAssistFrameTicks : DateTime.Now.Ticks;
            long cutoffTicks = nowTicks - (long)ms * 10000;
            for (int i = 0; i < historyCount; i++)
            {
                DriveAssistSnapshot s;
                if (!TryGetSnapshot(i, out s)) return false;
                if (s.TimestampTicks < cutoffTicks) break;
                if (s.SpeedMs > speedMs) return false;
            }
            return true;
        }

        // Single canonical write site — called once per ProcessSteeringAssist
        // tick after all per-frame computation is final.
        private void PushDriveAssistSnapshot(Vehicle veh,
            float steerTTC, float brakeTTC,
            bool hasSteerThreat, bool hasBrakeThreat)
        {
            DriveAssistSnapshot s = new DriveAssistSnapshot();
            s.TimestampTicks = DateTime.Now.Ticks;
            s.FrameCount     = driveLogFrameCount;
            s.DeltaTimeSec   = deltaTime;

            if (veh != null)
            {
                s.SpeedMs   = veh.Speed;
                s.Position  = veh.Position;
                s.Heading   = veh.Heading;
            }

            // iter-13 Patch S2: break the self-fulfilling re-lock. The mode
            // block force-sets isOnValidRoad=true on every LaneKeeping re-entry
            // (so downstream steering has a guidance source during a blip), and
            // WasOnValidRoadForLastMs reads THIS field — so a car pinned 53 deg
            // skewed at 0 speed kept "confirming" it was on-road and re-locking
            // LaneKeeping every ~1.5 s (Sandy Shores trap). Record what is
            // physically true into the rolling history: a demonstrably skewed +
            // stopped car is NOT lane-keeping, so the return-to-LaneKeeping
            // confirm can no longer be satisfied while it sits there. Narrowly
            // conjoined (skew + near-stopped) so normal stop-and-go pointed down
            // the lane (skew ~ 0) still records on-road and returns promptly.
            bool physicallyOnLane = isOnValidRoad
                && !(Math.Abs(roadHeadingDelta) > LANEKEEP_SKEW_FAIL_ANGLE
                     && veh != null && veh.Speed < 1.0f);
            s.IsOnValidRoad       = physicallyOnLane;
            s.RoadHeadingDelta    = roadHeadingDelta;
            s.LaneLateralError    = lastLaneLateralError;
            s.ClosestPolySegIdx   = lastClosestPolySeg;
            s.PolylinePointCount  = pathPolyline != null ? pathPolyline.Count : 0;

            s.Mode                   = currentDriveMode;
            s.LaneKeepFailureStreak  = laneKeepFailureStreak;
            // LaneKeepOkRaw is the pre-hysteresis "are we on the road right
            // now" signal. Mode-transition gates that read the buffer must use
            // this raw signal, NOT the post-hysteresis decision, or they
            // become self-referential.
            s.LaneKeepOkRaw          = isOnValidRoad;

            s.CachedSteerCorrection    = cachedSteerCorrection;
            s.SmoothedSteerCorrection  = smoothedSteerCorrection;
            s.SmoothedRoadCorrection   = smoothedRoadCorrection;
            s.CachedAvoidDirection     = cachedAvoidDirection;
            s.CachedBrakeMagnitude     = cachedBrakeMagnitude;
            s.EmergencyBrakeActive     = emergencyBrakeActive;

            s.SteerTTC               = steerTTC;
            s.BrakeTTC               = brakeTTC;
            s.CachedBrakeThreatPos   = cachedBrakeThreatPos;
            s.CachedBrakeThreatStamp = cachedBrakeThreatStamp;
            s.HasSteerThreat         = hasSteerThreat;
            s.HasBrakeThreat         = hasBrakeThreat;

            s.NavDistCenter = navAssistDistCenter;
            s.NavDistLeft   = navAssistDistLeft;
            s.NavDistRight  = navAssistDistRight;
            s.NavDistBehind = navAssistDistBehind;

            history[historyHead] = s;
            historyHead = (historyHead + 1) % HISTORY_CAPACITY;
            if (historyCount < HISTORY_CAPACITY) historyCount++;
        }

        /// <summary>Composes pathPolyline ahead of the vehicle. Sets
        /// pathPolylineFromGps. Polyline is empty if no source is available
        /// (truly off-road and node dump missing) — callers must handle
        /// that case.</summary>
        private void BuildPathPolyline(Vehicle veh)
        {
            BuildPathPolylineRaw(veh);
            StabilizePolyline(veh);
            BuildSteerPolyline(veh);   // iter-26 B1: derive the lane-centered steering copy
        }

        // iter-26 B1: build steerPolyline — a per-vertex copy of the stabilized
        // pathPolyline pushed RIGHT toward the lane center. Offset magnitude is
        // derived from the NodeGraph's per-link lane counts (no native): an
        // undivided two-way road (bwdLanes>0, oncoming shares this carriageway so
        // the node line is the road CENTER) gets a half-lane right offset; a
        // divided carriageway (bwdLanes==0 — GTA already runs those per-roadway)
        // gets none; the offset blends to 0 near a Junction node. When the
        // laneOffsetPolyline setting is OFF the copy is identical to the raw
        // polyline (dark-launch) but the offset is still COMPUTED so the
        // poly-offset calibration line and the failClass discriminator are live.
        private void BuildSteerPolyline(Vehicle veh)
        {
            steerPolyline.Clear();
            lastLaneOffsetMag = 0f;
            lastLaneOffsetFwd = 0;
            lastLaneOffsetBwd = 0;
            lastLaneOffsetJBlend = 1f;
            lastLaneWidthExtraM = 0;

            int n = pathPolyline.Count;
            if (n < 2) { steerPolyline.AddRange(pathPolyline); return; }

            bool apply = getSetting("laneOffsetPolyline") == 1;
            bool haveGraph = NodeGraph.IsLoaded;

            for (int i = 0; i < n; i++)
            {
                GTA.Math.Vector3 p = pathPolyline[i];
                // Local tangent: forward segment for all but the last vertex.
                GTA.Math.Vector3 a = (i < n - 1) ? pathPolyline[i]     : pathPolyline[i - 1];
                GTA.Math.Vector3 b = (i < n - 1) ? pathPolyline[i + 1] : pathPolyline[i];
                float tx = b.X - a.X, ty = b.Y - a.Y;
                float tlen = (float)Math.Sqrt(tx * tx + ty * ty);
                if (tlen < 0.01f) { steerPolyline.Add(p); continue; }
                tx /= tlen; ty /= tlen;
                // Right-perpendicular in XY: right(tx,ty) = (ty, -tx). A tangent
                // heading north (0,1) maps to (1,0) = east = the driver's right.
                float rx = ty, ry = -tx;

                float offMag = 0f;
                int fwd = 0, bwd = 0;
                float jblend = 1f;
                if (haveGraph)
                {
                    int nodeIdx = NodeGraph.FindNearestNode(p, LANE_OFFSET_NODE_SEARCH_M);
                    if (nodeIdx >= 0)
                    {
                        // Read the lane split of the outgoing link best aligned
                        // with the tangent — that's the roadway we're on here.
                        GTA.Math.Vector3 np = NodeGraph.GetPosition(nodeIdx);
                        int lc = NodeGraph.GetLinkCount(nodeIdx);
                        float bestDot = -2f;
                        int extraW = 0;
                        for (int j = 0; j < lc; j++)
                        {
                            int tgt, lf, lb, wm;
                            NodeGraph.LinkFlags lfl;
                            NodeGraph.GetLinkEx(nodeIdx, j, out tgt, out lf, out lb, out wm, out lfl);
                            GTA.Math.Vector3 tp = NodeGraph.GetPosition(tgt);
                            float dxn = tp.X - np.X, dyn = tp.Y - np.Y;
                            float dl = (float)Math.Sqrt(dxn * dxn + dyn * dyn);
                            if (dl < 0.01f) continue;
                            float dot = (dxn / dl) * tx + (dyn / dl) * ty;
                            if (dot > bestDot) { bestDot = dot; fwd = lf; bwd = lb; extraW = wm; }
                        }
                        // iter-32: stash the segment-0 link's extra/shoulder width
                        // for the offroad-risk threshold (additive margin only —
                        // the width study showed it is NOT total road width).
                        if (i == 0) lastLaneWidthExtraM = extraW;
                        // iter-30 signed per-side bias: hold the forward-lane side of an
                        // undivided (shared-centreline) road. The sign is DATA-DRIVEN from
                        // the lane split — forward lanes sit on the driver's side of the
                        // centreline (right, in GTA V's right-hand traffic), so bias toward
                        // them by half a lane to sit in the innermost forward lane. Requires
                        // BOTH directions present (fwd>0 && bwd>0); a divided carriageway
                        // (bwd==0) already runs per-roadway and gets no bias.
                        //
                        // iter-49 B2 (laneWidthV2): two corrections, both from
                        // taxiservice.c's own drop-off maths.
                        //  1. LANE_WIDTH_M is 5.3 m. R* uses 4.2 m per lane. Ours has
                        //     been 26% too wide since iter-30, so the "half lane"
                        //     bias has really been 2.65 m of a 4.2 m lane — most of
                        //     a full lane, which on a narrow street is the
                        //     difference between the inside lane and the kerb.
                        //  2. The one-way/two-way decision comes from the SHIPPED
                        //     graph. The engine will answer it live, and only the
                        //     live answer knows about roadworks, tunnels, and the
                        //     places the offline dump is simply wrong.
                        // NOT imported: taxiservice's full 4.2*lanes magnitude and
                        // its +0.9*width / -0.7 corrections. Those walk a point all
                        // the way to the KERB, which is a different job from biasing
                        // a centreline by half a lane — they belong to pullOverAssist
                        // and are applied there, not here.
                        bool laneW = getSetting("laneWidthV2") == 1;
                        if (laneW) GateReach("laneWidthV2");
                        float laneWidth = laneW ? VANILLA_LANE_WIDTH_M : LANE_WIDTH_M;
                        int biasFwd = fwd, biasBwd = bwd;
                        if (laneW && i == 0 && roadFactsValid)
                        {
                            // Live counts only for the car's own segment: the road
                            // facts are sampled at the vehicle, and applying them to
                            // a vertex 60 m up the road would be a guess wearing a
                            // measurement's clothes.
                            biasFwd = rfLanesFwd; biasBwd = rfLanesBwd;
                        }
                        else if (laneW && i == 0)
                        {
                            // GATE DEPENDENCY, made loud rather than silent: half of
                            // this gate is "take the lane split from the engine", and
                            // that half needs roadFactsV2 sampling. With it off, only
                            // the 4.2-vs-5.3 recalibration is live and the split still
                            // comes from the shipped graph — a materially different
                            // experiment. A session that does not know which of the
                            // two it ran cannot promote or retire the gate.
                            if (driveLogger != null && driveLogger.IsRunning
                                && DateTime.Now.Ticks - lastLaneWidthDegradedTicks > 300000000L)
                            {
                                lastLaneWidthDegradedTicks = DateTime.Now.Ticks;
                                driveLogger.Write("[F" + driveLogFrameCount
                                    + "] EVENT lane-width-degraded:"
                                    + " why=" + (getSetting("roadFactsV2") == 1
                                        ? "road-facts-refused" : "roadFactsV2-off")
                                    + " usingGraphFwd=" + fwd + " usingGraphBwd=" + bwd);
                            }
                        }
                        if (biasBwd > 0 && biasFwd > 0)
                        {
                            offMag = laneWidth * 0.5f;
                            if (laneW) GateFire("laneWidthV2");
                        }
                    }
                    // Junction blend: ramp the offset to 0 within the blend radius
                    // of a junction node (0 at the node, full at the edge).
                    int jn = NodeGraph.FindNearestNode(p, LANE_OFFSET_JUNCTION_BLEND_M,
                        NodeGraph.NodeFlags.Junction, NodeGraph.NodeFlags.None);
                    if (jn >= 0)
                    {
                        GTA.Math.Vector3 jp = NodeGraph.GetPosition(jn);
                        float jdx = jp.X - p.X, jdy = jp.Y - p.Y;
                        float jd = (float)Math.Sqrt(jdx * jdx + jdy * jdy);
                        jblend = Math.Max(0f, Math.Min(1f, jd / LANE_OFFSET_JUNCTION_BLEND_M));
                        offMag *= jblend;
                    }
                }

                // Stash the near-segment values (the car sits on segment 0) for the
                // poly-offset calibration line + the failClass offsetWouldBe field.
                if (i == 0)
                {
                    lastLaneOffsetMag = offMag;
                    lastLaneOffsetFwd = fwd;
                    lastLaneOffsetBwd = bwd;
                    lastLaneOffsetJBlend = jblend;
                }

                if (apply && offMag > 0f)
                {
                    GTA.Math.Vector3 offPt = new GTA.Math.Vector3(p.X + rx * offMag, p.Y + ry * offMag, p.Z);
                    // iter-30: never shove the guidance off the road surface at the car's own
                    // segment. A blind fixed offset on a narrow lane pushed the steer target
                    // past the road edge and dragged the car off (LATERAL-OFFROAD drift). Back
                    // off to half, then to the raw centreline point, rather than off-road.
                    if (i == 0 && haveGraph && !IsPositionOnRoad(offPt))
                    {
                        GTA.Math.Vector3 halfPt = new GTA.Math.Vector3(
                            p.X + rx * offMag * 0.5f, p.Y + ry * offMag * 0.5f, p.Z);
                        offPt = IsPositionOnRoad(halfPt) ? halfPt : p;
                    }
                    steerPolyline.Add(offPt);
                }
                else
                    steerPolyline.Add(p);
            }
        }

        // ====================================================================
        // iter-32: road-graph enrichment detectors (paths.xml/junctions.xml)
        // ====================================================================

        // R3: signalized-junction approach. Scans the path polyline ahead for a
        // JunctionDb entrance we are approaching (entrance near a path vertex
        // AND the junction center lies roughly along our travel direction —
        // geometric gating, independent of the template's fOrientation whose
        // convention is unconfirmed). Detector always runs and logs; brake
        // floor + announcements only when the junctionAssist setting is on.
        // The brake is a slow-down governor toward JUNCTION_SLOW_SPEED at the
        // entrance, NOT a stop: light state is unknown, and a hard stop on
        // green would be its own hazard. fStoppingDistance is logged but
        // deliberately unused (sign convention unconfirmed offline).
        // ---- C2 (junctionDirectionsV2): the engine's own turn-by-turn ----
        // JunctionDb ships 82 signalized junctions map-wide and the iter-35 node
        // fallback covers only nodes flagged TrafficLight. GENERATE_DIRECTIONS_TO_COORD
        // answers "how far to the next junction, and which way does the route turn"
        // for the WHOLE map with no shipped data at all — but only while a GPS route
        // exists, so it complements the two static sources rather than replacing them.
        // Direction is logged as the RAW engine code: the documented value mapping is
        // inconsistent across references, so it is settled from a session, not guessed.
        private bool  genDirValid = false;
        private int   genDirCode = 0;
        private float genDistToJunction = -1f;
        private int   genLastSpokenCode = 0;
        private long  genLastSpokenTicks = 0;
        private float genLastSpokenDist = 0f;

        private void SampleEngineDirections(Vehicle veh)
        {
            genDirValid = false;
            genDistToJunction = -1f;
            if (veh == null || getSetting("junctionDirectionsV2") != 1) return;
            GateReach("junctionDirectionsV2");
            // ---- iter-43 G2: the precondition was too strict ----
            // This required GET_GPS_BLIP_ROUTE_FOUND, but GENERATE_DIRECTIONS_TO_COORD
            // takes an arbitrary destination coordinate and does not need a computed
            // GPS route at all. The mod's own turn-by-turn path already uses the
            // right predicate — (waypointTrackingActive || missionTrackingActive) —
            // and UpdateWaypointDirection fills cachedWaypointPos from EITHER a real
            // waypoint OR a tracked mission blip. On 07-31 the tester tracked a
            // mission marker (which calls SET_NEW_WAYPOINT) 685 frames after turning
            // this gate on and held it for ~11,800 frames, and the gate still
            // recorded eval 4069 / fire 0.
            bool haveTarget = cachedWaypointPos != GTA.Math.Vector3.Zero
                && (waypointTrackingActive || missionTrackingActive || HasGpsRoute());
            if (!haveTarget)
            {
                LogGenDirSkip(HasGpsRoute() ? "no-target" : "no-route", -1f);
                return;
            }
            try
            {
                OutputArgument oDir = new OutputArgument();
                OutputArgument oP5 = new OutputArgument();
                OutputArgument oDist = new OutputArgument();
                // GENERATE_DIRECTIONS_TO_COORD = 0xF90125F1F79ECDF8
                Function.Call<int>((Hash)0xF90125F1F79ECDF8,
                    cachedWaypointPos.X, cachedWaypointPos.Y, cachedWaypointPos.Z,
                    true, oDir, oP5, oDist);
                int dir = oDir.GetResult<int>();
                float dist = oDist.GetResult<float>();
                // A negative or absurd distance means the engine had no answer;
                // logging it as data would poison the C2 cross-check.
                if (dist < 0f || dist > 5000f)
                {
                    // iter-43 G3: this is also the signature of the SHVDN
                    // OutputArgument garbage-read that produced ~30% farHits on the
                    // shapecasts. Counting it separately is what distinguishes
                    // "the engine has no route" from "we cannot read the result".
                    LogGenDirSkip("bad-dist", dist);
                    return;
                }
                genDirCode = dir;
                genDistToJunction = dist;
                genDirValid = true;
                GateFire("junctionDirectionsV2");
            }
            catch { genDirValid = false; LogGenDirSkip("exception", -1f); }
        }

        private long lastGenDirSkipTicks = 0;
        private string lastGenDirSkipReason = null;

        /// <summary>
        /// iter-43 G1: name which precondition rejected the sample. SampleEngineDirections
        /// had four silent early returns, so "eval 4069 / fire 0" in the 07-31 gate
        /// census was undiagnosable from 266.7 MB of log. Rate-limited to ~1 Hz, and
        /// always emitted immediately when the reason CHANGES so a transition is
        /// never swallowed by the cooldown.
        /// </summary>
        private void LogGenDirSkip(string reason, float dist)
        {
            if (driveLogger == null || !driveLogger.IsRunning) return;
            long now = ModClock.Ticks;
            if (reason == lastGenDirSkipReason && now - lastGenDirSkipTicks < 10000000L) return;
            lastGenDirSkipTicks = now;
            lastGenDirSkipReason = reason;
            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT gen-dir-skip:"
                + " reason=" + reason
                + " dist=" + dist.ToString("F1")
                + " gpsRoute=" + HasGpsRoute()
                + " wpTracking=" + waypointTrackingActive
                + " missionTracking=" + missionTrackingActive
                + " wpPos=" + FmtV(cachedWaypointPos));
        }

        private long lastJunctionDisagreeTicks = 0;

        /// <summary>
        /// C3: turn-by-turn from the engine's own routing — map-wide, needing no
        /// shipped junction data. This is the accessibility payoff of C2: a blind
        /// driver gets "left turn in 80 metres" anywhere, not only inside the
        /// 82-junction footprint.
        /// </summary>
        private void SpeakEngineTurn(Vehicle veh)
        {
            if (!genDirValid || veh == null) return;
            if (getSetting("turnByTurnNavigation") != 1) return;
            // Only a real turn is worth speaking; codes outside this set are
            // "carry straight on", which would be constant chatter.
            string turn = genDirCode == 2 ? "Left turn"
                        : genDirCode == 3 ? "Right turn"
                        : null;
            if (turn == null) { genLastSpokenCode = 0; return; }
            if (genDistToJunction > 150f) return;

            // Wall clock throughout, NOT ModClock: this is compared against
            // junctionAnnounceTicks below, which is DateTime-based. Mixing the two
            // clocks on one comparison is a known way to get nonsense intervals.
            long now = DateTime.Now.Ticks;
            // Never stack on the junctionAssist announcement — a blind driver
            // getting "Traffic light ahead" and "Left turn in 80 metres" on top of
            // each other is worse than either alone.
            if (now - junctionAnnounceTicks < 40000000L) return; // 4 s
            // Re-announce only on a NEW turn, or once the car has closed
            // meaningfully on the same one. Shares the 8 s floor the other
            // drive cues use so speech never stacks on a brake cue.
            bool newTurn = genDirCode != genLastSpokenCode;
            bool closed = genLastSpokenDist - genDistToJunction > 60f;
            if (!newTurn && !closed) return;
            if (now - genLastSpokenTicks < 80000000L) return; // 8 s
            genLastSpokenCode = genDirCode;
            genLastSpokenTicks = now;
            genLastSpokenDist = genDistToJunction;
            Speech.Info(turn + " in " + ((int)Math.Round(genDistToJunction / 10f) * 10) + " metres.");
        }

        // ====================================================================
        // iter-49 A4 (nodeHazardV2): MAP-WIDE HAZARDS FROM THE ENGINE'S NODES
        // ====================================================================
        // Junction detection has two static sources: 82 hand-authored JunctionDb
        // templates, and 1,443 TrafficLight-flagged nodes in the shipped graph.
        // Both are exports of a particular game build, both cover a fraction of
        // the map, and neither knows what a give-way is. GET_VEHICLE_NODE_PROPERTIES
        // answers all of it live, everywhere, with nothing shipped.
        //
        // What this deliberately does NOT do is claim to know a light's COLOUR.
        // No script-visible native reports that, so a TRAFFIC_LIGHT flag still
        // arms the existing slow-down governor and never a stop — a hard stop on
        // green would be its own hazard, and telling a blind driver "red light"
        // on a guess is worse than saying nothing.
        private float hazTrafficLightDist = -1f;
        private GTA.Math.Vector3 hazTrafficLightPos = GTA.Math.Vector3.Zero;
        private float hazJunctionDist = -1f;
        private float hazGiveWayDist = -1f;
        private float hazDeadEndDist = -1f;
        private bool  hazHighway = false;
        private bool  hazTunnel = false;
        private int   hazFlagsUnion = 0;      // everything seen on the walk, for the log
        private float giveWayBrakeRequest = 0f;
        private float giveWayBrakeWouldBe = 0f;
        private long  giveWayAnnounceTicks = 0;
        private float giveWayAnnouncedAtDist = -1f;
        private long  deadEndAnnounceTicks = 0;
        private long  lastNodeHazardLogTicks = 0;
        private long  lastTunnelVetoLogTicks = 0;   // ModClock, pairs with offRoadFloorArmSinceTicks
        // Give way is a yield, not a signal: slow harder than a light but still
        // never a commanded stop, for the same reason.
        private const float GIVEWAY_SLOW_SPEED = 4.0f;

        /// <summary>
        /// iter-49 A4. Walks the upcoming path sampling the engine's node property
        /// flags, and records the distance to the first of each hazard kind. Always
        /// computes (so the log shows coverage even with the gate off); only the
        /// consumers below are gated.
        /// </summary>
        /// <summary>
        /// iter-49 B3. The Assistive-mode half of Pull Over: a decaying brake floor
        /// toward a crawl, live for 30 s after the request or until the car is
        /// stopped. Cancelled the moment the driver presses the throttle — a
        /// governor a blind driver cannot override is a trap, not an aid.
        /// </summary>
        private void UpdatePullOverGovernor(Vehicle veh)
        {
            pullOverBrakeRequest = 0f;
            if (veh == null || pullOverGovernorUntilTicks == 0) return;
            if (ModClock.Ticks > pullOverGovernorUntilTicks)
            {
                pullOverGovernorUntilTicks = 0;
                return;
            }
            float speed = veh.Speed;
            if (speed < PULLOVER_SLOW_SPEED)
            {
                pullOverGovernorUntilTicks = 0;
                Speech.Info("Stopped at the kerb.");
                return;
            }
            // Driver override: any real throttle press ends it, silently. Reads the
            // DISABLED normal too, so intent registers even while the pedal is held
            // by another part of the assist.
            float thr = Math.Max(
                Function.Call<float>(Hash.GET_CONTROL_NORMAL, 0, 71),
                Function.Call<float>(Hash.GET_DISABLED_CONTROL_NORMAL, 0, 71));
            if (thr > 0.3f)
            {
                pullOverGovernorUntilTicks = 0;
                if (driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount
                        + "] EVENT pullover-cancel: why=throttle thr=" + thr.ToString("F2"));
                return;
            }
            float dist = pullOverTarget != GTA.Math.Vector3.Zero
                ? Dist2D(veh.Position, pullOverTarget) : 20f;
            float reqDecel = (speed * speed - PULLOVER_SLOW_SPEED * PULLOVER_SLOW_SPEED)
                / (2f * Math.Max(4f, dist));
            pullOverBrakeRequest = Math.Min(CurveFloorCap(speed),
                Math.Max(0.20f, 0.20f + reqDecel / 8f * 0.5f));
        }

        private void UpdateNodeHazards(Vehicle veh)
        {
            hazTrafficLightDist = hazJunctionDist = -1f;
            hazTrafficLightPos = GTA.Math.Vector3.Zero;
            hazGiveWayDist = hazDeadEndDist = -1f;
            hazHighway = hazTunnel = false;
            hazFlagsUnion = 0;
            giveWayBrakeRequest = 0f;
            giveWayBrakeWouldBe = 0f;
            if (veh == null || pathPolyline.Count == 0) return;
            if (getSetting("nodeHazardV2") != 1 && getSetting("nodePropsV2") != 1) return;
            GTA.Math.Vector3 vehPos = veh.Position;
            if (!ArePathNodesLoadedAt(vehPos, "nodeHazards")) return;
            GateReach("nodeHazardV2");

            float speed = veh.Speed;
            float lookahead = Math.Max(60f, speed * 4f);
            // Sample sparsely: the walk costs one native per vertex and the scan
            // already carries a shapecast budget. Every ~10 m of path is enough
            // resolution for a governor that starts working 60 m out.
            float along = 0f, sinceSample = 999f;
            GTA.Math.Vector3 prev = vehPos;
            int segStart = Math.Max(0, Math.Min(lastClosestPolySeg, pathPolyline.Count - 1));
            for (int i = segStart; i < pathPolyline.Count && along < lookahead; i++)
            {
                GTA.Math.Vector3 p = pathPolyline[i];
                float dxs = p.X - prev.X, dys = p.Y - prev.Y;
                float seg = (float)Math.Sqrt(dxs * dxs + dys * dys);
                along += seg;
                sinceSample += seg;
                prev = p;
                if (sinceSample < 10f) continue;
                sinceSample = 0f;

                int d, f;
                if (!TryGetNodeProperties(p, out d, out f)) continue;
                hazFlagsUnion |= f;
                if (hazTrafficLightDist < 0f && (f & VNP_TRAFFIC_LIGHT) != 0)
                {
                    hazTrafficLightDist = along;
                    hazTrafficLightPos = p;
                }
                if (hazJunctionDist < 0f && (f & VNP_JUNCTION) != 0) hazJunctionDist = along;
                if (hazGiveWayDist < 0f && (f & VNP_GIVE_WAY) != 0) hazGiveWayDist = along;
                if (hazDeadEndDist < 0f && (f & VNP_LEADS_TO_DEAD_END) != 0) hazDeadEndDist = along;
            }
            // Highway/tunnel describe where the car IS, not what is coming, so they
            // come from the vehicle's own node rather than the walk.
            if (nodePropsValid)
            {
                hazHighway = (npFlags & VNP_HIGHWAY) != 0;
                hazTunnel = (npFlags & VNP_TUNNEL_OR_INTERIOR) != 0;
            }
            if (hazFlagsUnion != 0) GateFire("nodeHazardV2");

            bool enabled = getSetting("nodeHazardV2") == 1;

            // ---- GIVE WAY: its own governor floor, below the light's ----
            if (hazGiveWayDist > 1f && speed > GIVEWAY_SLOW_SPEED + 1f)
            {
                float reqDecel = (speed * speed - GIVEWAY_SLOW_SPEED * GIVEWAY_SLOW_SPEED)
                    / (2f * hazGiveWayDist);
                if (reqDecel > 1.5f)
                {
                    float b = Math.Min(CurveFloorCap(speed),
                        0.25f + (reqDecel - 1.5f) / 6f * 0.5f);
                    giveWayBrakeWouldBe = b;
                    if (enabled) giveWayBrakeRequest = b;
                }
            }

            long now = DateTime.Now.Ticks;
            // ---- ANNOUNCEMENTS ----
            // Both yield to the junction cue rather than stacking on it: a blind
            // driver getting "Traffic light ahead" and "Give way ahead" on top of
            // each other is worse than either alone (the SpeakEngineTurn rule).
            if (enabled && hazGiveWayDist > 0f && hazGiveWayDist < 50f
                && now - junctionAnnounceTicks > 40000000L
                && now - giveWayAnnounceTicks > 80000000L
                && (giveWayAnnouncedAtDist < 0f || giveWayAnnouncedAtDist - hazGiveWayDist > 60f))
            {
                giveWayAnnounceTicks = now;
                giveWayAnnouncedAtDist = hazGiveWayDist;
                Speech.Info("Give way ahead.");
            }
            if (hazGiveWayDist < 0f) giveWayAnnouncedAtDist = -1f;

            // A dead end matters more than it sounds: driving into one is how a
            // strand starts, and the recovery ladder then tries to escape from
            // inside it. Announce early and once.
            if (enabled && hazDeadEndDist > 0f && hazDeadEndDist < 80f && speed > 3f
                && now - junctionAnnounceTicks > 40000000L
                && now - deadEndAnnounceTicks > 200000000L) // 20 s
            {
                deadEndAnnounceTicks = now;
                Speech.Info("Dead end ahead, "
                    + ((int)Math.Round(hazDeadEndDist / 10f) * 10) + " metres.");
            }

            if (driveLogger != null && driveLogger.IsRunning
                && now - lastNodeHazardLogTicks > 10000000L
                && (hazFlagsUnion != 0 || hazHighway || hazTunnel))
            {
                lastNodeHazardLogTicks = now;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT node-hazard:"
                    + " union=" + NodePropNames(hazFlagsUnion)
                    + " tlDist=" + hazTrafficLightDist.ToString("F0")
                    + " jctDist=" + hazJunctionDist.ToString("F0")
                    + " giveWayDist=" + hazGiveWayDist.ToString("F0")
                    + " deadEndDist=" + hazDeadEndDist.ToString("F0")
                    + " highway=" + hazHighway
                    + " tunnel=" + hazTunnel
                    + " gwBrake=" + giveWayBrakeWouldBe.ToString("F2")
                    + " applied=" + enabled
                    // The two static sources, for the coverage comparison this
                    // whole gate exists to make.
                    + " dbArmed=" + (junctionArmed && !junctionFromNode)
                    + " nodeArmed=" + junctionFromNode
                    + " spd=" + speed.ToString("F1"));
            }
        }

        /// <summary>Dedup key for a props-armed junction: a 20 m position grid, so
        /// re-approaching the same light dedups but the next one along the street
        /// does not. Offset into a range neither the DB indices (>= 0) nor the node
        /// keys (about -200000 at worst) can reach.</summary>
        private static int PropsJunctionKey(GTA.Math.Vector3 p)
        {
            int gx = (int)Math.Floor(p.X / 20.0);
            int gy = (int)Math.Floor(p.Y / 20.0);
            int h = (gx * 73856093) ^ (gy * 19349663);
            return (int.MinValue / 2) + (h & 0x0FFFFFFF);
        }

        private void UpdateJunctionApproach(Vehicle veh)
        {
            junctionBrakeRequest = 0f;
            junctionBrakeWouldBe = 0f;
            SampleEngineDirections(veh);
            // C3 speech runs HERE, above the early return below, not in the
            // !junctionArmed branch. That return fires when the path polyline is
            // empty — which is precisely the no-static-data case C2/C3 exists to
            // cover — so announcing from further down would silence the backstop
            // exactly where it is the only source the driver has.
            SpeakEngineTurn(veh);
            bool wasArmed = junctionArmed;
            junctionArmed = false;
            junctionFromNode = false;
            junctionFromProps = false;
            junctionNodeIdx = -1;
            junctionDistM = -1f;
            // iter-35: NodeGraph traffic-light fallback works without JunctionDb.
            if (veh == null || pathPolyline.Count == 0
                || (!JunctionDb.IsLoaded && !NodeGraph.IsLoaded)) return;
            jEvalCount++; // iter-34 BS-4: detector-liveness counter

            GTA.Math.Vector3 vehPos = veh.Position;
            float speed = veh.Speed;
            // Travel direction: velocity when moving, forward vector otherwise.
            GTA.Math.Vector3 travel = veh.Velocity;
            if (travel.LengthSquared() < 1f) travel = veh.ForwardVector;
            float tl = (float)Math.Sqrt(travel.X * travel.X + travel.Y * travel.Y);
            if (tl < 0.01f) return;
            float tvx = travel.X / tl, tvy = travel.Y / tl;

            // Walk the polyline ahead of the car accumulating along-path
            // distance; test each vertex for a nearby junction entrance.
            float along = 0f;
            GTA.Math.Vector3 prev = vehPos;
            int segStart = Math.Max(0, Math.Min(lastClosestPolySeg, pathPolyline.Count - 1));
            float lookahead = Math.Max(60f, speed * 4f);
            for (int i = segStart; i < pathPolyline.Count && along < lookahead; i++)
            {
                if (!JunctionDb.IsLoaded) break; // iter-35: fall through to the node walk
                GTA.Math.Vector3 p = pathPolyline[i];
                float dxs = p.X - prev.X, dys = p.Y - prev.Y;
                along += (float)Math.Sqrt(dxs * dxs + dys * dys);
                prev = p;

                JunctionDb.EntranceInfo info;
                int e = JunctionDb.FindEntranceNear(p, 15f, out info);
                if (e < 0) continue;
                // Behind-us guard: entrance must sit ahead along travel.
                float ex = info.Pos.X - vehPos.X, ey = info.Pos.Y - vehPos.Y;
                if (ex * tvx + ey * tvy < 0f) continue;
                // Approach gate: junction center must lie roughly along our
                // travel direction FROM the entrance (we're entering through
                // it, not driving past on the cross street).
                GTA.Math.Vector3 jc = JunctionDb.GetJunctionCenter(info.JunctionIdx);
                float cx = jc.X - info.Pos.X, cy = jc.Y - info.Pos.Y;
                float cl = (float)Math.Sqrt(cx * cx + cy * cy);
                if (cl > 0.5f && (cx / cl) * tvx + (cy / cl) * tvy < 0.5f) continue; // >60 deg off
                if (!JunctionDb.IsSignalized(info.JunctionIdx)) continue;
                // Don't re-arm while already inside this junction's bbox.
                int insideJ;
                if (JunctionDb.TryGetJunctionContaining(vehPos, out insideJ)
                    && insideJ == info.JunctionIdx) continue;

                // Use the entrance's own distance rather than the vertex's.
                float entDist = (float)Math.Sqrt(ex * ex + ey * ey);
                jArmedFrames++; // iter-34 BS-4
                junctionArmed = true;
                junctionDistM = Math.Min(along, entDist);
                junctionEntrance = info;
                break;
            }

            // iter-35: GRAPH-FLAG FALLBACK. The hand-authored JunctionDb covers
            // only 82 signalized junctions map-wide — impossible to route a blind
            // tester through on demand. The base graph bakes NodeFlags.TrafficLight
            // on 1,443 nodes; any of them near the upcoming path arms the same
            // slow-down governor + announcement. The DB template still wins when
            // present (it carries per-entrance lane/phase detail this path lacks).
            if (!junctionArmed && NodeGraph.IsLoaded)
            {
                along = 0f;
                prev = vehPos;
                for (int i = segStart; i < pathPolyline.Count && along < lookahead; i++)
                {
                    GTA.Math.Vector3 p = pathPolyline[i];
                    float dxs = p.X - prev.X, dys = p.Y - prev.Y;
                    along += (float)Math.Sqrt(dxs * dxs + dys * dys);
                    prev = p;

                    int ni = NodeGraph.FindNearestNode(p, 12f,
                        NodeGraph.NodeFlags.TrafficLight,
                        NodeGraph.NodeFlags.None,
                        NodeGraph.ExtFlags.Disabled);
                    if (ni < 0) continue;
                    GTA.Math.Vector3 np = NodeGraph.GetPosition(ni);
                    float nx = np.X - vehPos.X, ny = np.Y - vehPos.Y;
                    if (nx * tvx + ny * tvy < 0f) continue; // behind us
                    float nDist = (float)Math.Sqrt(nx * nx + ny * ny);
                    if (nDist < 10f) continue; // already at/inside the junction
                    jArmedFrames++;
                    junctionArmed = true;
                    junctionFromNode = true;
                    junctionNodeIdx = ni;
                    junctionDistM = Math.Min(along, nDist);
                    break;
                }
            }

            // iter-49 A4: THIRD SOURCE — the engine's own TRAFFIC_LIGHT node flag,
            // walked by UpdateNodeHazards immediately before this method. Unlike
            // the two static sources this one has no footprint: it is available on
            // every signalized junction on the map, including the ones no export
            // ever covered. It arms LAST so a DB template (which carries per-
            // entrance lane detail) and then the shipped graph still win when they
            // have an opinion — this is a backstop, not a replacement.
            if (!junctionArmed && getSetting("nodeHazardV2") == 1
                && hazTrafficLightDist > 10f && hazTrafficLightDist < lookahead)
            {
                jArmedFrames++;
                junctionArmed = true;
                junctionFromNode = true;      // shares the node-armed announce key space
                junctionFromProps = true;
                junctionNodeIdx = -1;
                junctionDistM = hazTrafficLightDist;
            }

            if (!junctionArmed)
            {
                // C2 consumer 1 — COVERAGE BACKSTOP. Neither static source armed,
                // which off the 82-junction footprint is the normal case rather
                // than the exception. Compute what a junction brake WOULD be from
                // the engine's own distance-to-next-junction and log it only.
                // Promotion to a real junctionBrakeRequest waits on a session
                // showing genDist behaves — exactly how junctionAssist itself was
                // dark-launched. Note this is "a junction is coming", NOT "a
                // traffic light is coming": the two static sources detect signals,
                // this one does not, and conflating them would be a false promise.
                if (genDirValid && genDistToJunction > 1f
                    && speed > JUNCTION_SLOW_SPEED + 1f)
                {
                    float reqD = (speed * speed - JUNCTION_SLOW_SPEED * JUNCTION_SLOW_SPEED)
                        / (2f * genDistToJunction);
                    if (reqD > 1.5f)
                        junctionBrakeWouldBe = Math.Min(CurveFloorCap(speed),
                            0.25f + (reqD - 1.5f) / 6f * 0.5f);
                }
                // Reset the announcement latch once fully clear of the last
                // announced junction (so we can announce it again next visit).
                if (junctionAnnouncedIdx >= 0
                    && DateTime.Now.Ticks - junctionAnnounceTicks > 300000000L) // 30 s
                    junctionAnnouncedIdx = -1;
                return;
            }

            // C2 consumer 2 — CROSS-CHECK. Both sources have an opinion about the
            // distance to the next junction. Sustained disagreement is a shipped-
            // data quality signal (region-filtered export, wrong game version, a
            // map mod), which no artifact could surface before.
            if (genDirValid && junctionDistM > 0f
                && Math.Abs(genDistToJunction - junctionDistM) > 40f
                && driveLogger != null && driveLogger.IsRunning
                && DateTime.Now.Ticks - lastJunctionDisagreeTicks > 100000000L) // 10 s
            {
                lastJunctionDisagreeTicks = DateTime.Now.Ticks;
                driveLogger.Write("[F" + driveLogFrameCount
                    + "] EVENT junction-disagree:"
                    + " src=" + (junctionFromNode ? "node" : "db")
                    + " staticDist=" + junctionDistM.ToString("F1")
                    + " engineDist=" + genDistToJunction.ToString("F1")
                    + " genDir=" + genDirCode
                    + " pos=" + FmtV(vehPos));
            }

            bool enabled = getSetting("junctionAssist") == 1;

            // Slow-down governor toward JUNCTION_SLOW_SPEED at the entrance.
            if (speed > JUNCTION_SLOW_SPEED + 1f && junctionDistM > 1f)
            {
                float reqDecel = (speed * speed - JUNCTION_SLOW_SPEED * JUNCTION_SLOW_SPEED)
                    / (2f * junctionDistM);
                if (reqDecel > 1.5f) // below ~1.5 m/s^2 natural coasting handles it
                {
                    float b = Math.Min(CurveFloorCap(speed),
                        0.25f + (reqDecel - 1.5f) / 6f * 0.5f);
                    junctionBrakeWouldBe = b;
                    if (enabled) junctionBrakeRequest = b;
                }
            }

            // Announcement: once per junction, only when meaningfully close.
            // iter-35: node-armed junctions dedup on a negative node key so they
            // can't collide with DB junction indices.
            // iter-49 A4: the props source keys off the LIGHT's position, not the
            // car's, or the key would change every metre and re-announce the same
            // junction all the way up to it. Its key space sits far below the node
            // keys (which are -(idx+2)) so the two can never collide.
            int announceKey = junctionFromProps ? PropsJunctionKey(hazTrafficLightPos)
                : junctionFromNode ? -(junctionNodeIdx + 2)
                : junctionEntrance.JunctionIdx;
            if (enabled && junctionDistM < 60f && junctionAnnouncedIdx != announceKey)
            {
                junctionAnnouncedIdx = announceKey;
                junctionAnnounceTicks = DateTime.Now.Ticks;
                string msg = "Traffic light ahead.";
                if (!junctionFromNode)
                {
                    if (junctionEntrance.LeftLaneAheadOnly) msg += " Left lane is ahead only.";
                    if (junctionEntrance.RightLaneRightOnly) msg += " Right lane turns right only.";
                }
                Speech.Info(msg);
            }

            // EVENT on arm transition (1 s throttle).
            if (!wasArmed && driveLogger != null && driveLogger.IsRunning
                && DateTime.Now.Ticks - lastJunctionArmLogTicks > 10000000L)
            {
                lastJunctionArmLogTicks = DateTime.Now.Ticks;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT junction-arm:"
                    + " src=" + (junctionFromNode ? "node" : "db") // iter-35
                    + " jIdx=" + (junctionFromNode ? -1 : junctionEntrance.JunctionIdx)
                    + " dist=" + junctionDistM.ToString("F1")
                    + " spd=" + speed.ToString("F1")
                    + (junctionFromNode
                        ? " ni=" + junctionNodeIdx
                        : " phases=" + JunctionDb.GetPhaseCount(junctionEntrance.JunctionIdx)
                          + " lights=" + JunctionDb.GetLightCount(junctionEntrance.JunctionIdx)
                          + " entrPhase=" + junctionEntrance.Phase
                          + " stopDist=" + junctionEntrance.StopDist.ToString("F1")
                          + " orient=" + junctionEntrance.Orientation.ToString("F2")
                          + " rr=" + (junctionEntrance.RightOnRed ? 1 : 0)
                          + " la=" + (junctionEntrance.LeftLaneAheadOnly ? 1 : 0)
                          + " rl=" + (junctionEntrance.RightLaneRightOnly ? 1 : 0)
                          + " ni=" + junctionEntrance.NodeIdx)
                    + " brake=" + junctionBrakeWouldBe.ToString("F2")
                    + " applied=" + enabled);
            }
        }

        // R4: wrong-way detector. At the nearest non-Disabled graph node, find
        // the outgoing link best aligned with our travel velocity; if that
        // link carries ZERO forward lanes (one-way against us) sustained for
        // 1.5 s above 4 m/s, we are driving against traffic. Speech is gated
        // by the wrongWayAlert setting; the detector itself always runs so
        // false-positive rates can be measured from logs before enabling.
        // No steering/brake output by design — a false positive that yanks
        // controls is exactly the regression this rollout must avoid.
        private void UpdateWrongWayDetector(Vehicle veh)
        {
            bool violating = false;
            long now = DateTime.Now.Ticks;
            if (veh != null && NodeGraph.IsLoaded && !isReversing
                && veh.Speed > WRONG_WAY_MIN_SPEED)
            {
                GTA.Math.Vector3 vel = veh.Velocity;
                float vl = (float)Math.Sqrt(vel.X * vel.X + vel.Y * vel.Y);
                if (vl > 0.5f)
                {
                    wwEvalCount++; // iter-34 BS-4: detector-liveness counter
                    float tvx = vel.X / vl, tvy = vel.Y / vl;
                    GTA.Math.Vector3 vehPos = veh.Position;
                    int ni = NodeGraph.FindNearestNode(vehPos, 15f,
                        NodeGraph.NodeFlags.None, NodeGraph.NodeFlags.None,
                        NodeGraph.ExtFlags.Disabled);
                    if (ni >= 0
                        && Math.Abs(NodeGraph.GetPosition(ni).Z - vehPos.Z) <= PATH_NODE_MAX_Z_DELTA)
                    {
                        wwNodeHitCount++; // iter-34 BS-4
                        var ext = NodeGraph.GetExtFlags(ni);
                        // Slip lanes and GPS-both-ways nodes have legitimate
                        // against-the-grain geometry — never flag there. Also
                        // skip junction nodes: crossing traffic lanes while
                        // turning at an intersection is normal.
                        bool exempt = (ext & (NodeGraph.ExtFlags.SlipLane
                            | NodeGraph.ExtFlags.GpsBothWays)) != 0
                            || (NodeGraph.GetFlags(ni) & NodeGraph.NodeFlags.Junction) != 0;
                        if (exempt) wwExemptCount++; // iter-34 BS-4
                        if (!exempt)
                        {
                            GTA.Math.Vector3 np = NodeGraph.GetPosition(ni);
                            int lc = NodeGraph.GetLinkCount(ni);
                            float bestDot = -2f;
                            int bestFwd = -1;
                            for (int j = 0; j < lc; j++)
                            {
                                int tgt, lf, lb;
                                NodeGraph.GetLink(ni, j, out tgt, out lf, out lb);
                                GTA.Math.Vector3 tp = NodeGraph.GetPosition(tgt);
                                float dxn = tp.X - np.X, dyn = tp.Y - np.Y;
                                float dl = (float)Math.Sqrt(dxn * dxn + dyn * dyn);
                                if (dl < 0.01f) continue;
                                float dot = (dxn / dl) * tvx + (dyn / dl) * tvy;
                                if (dot > bestDot) { bestDot = dot; bestFwd = lf; }
                            }
                            // Strong alignment with a zero-forward-lane link =
                            // traveling a one-way in the forbidden direction.
                            violating = bestDot > 0.5f && bestFwd == 0;
                        }
                    }
                }
            }

            if (violating)
            {
                wwViolFrames++; // iter-34 BS-4
                if (wrongWayStartTicks == 0) wrongWayStartTicks = now;
                if (!wrongWayActive && now - wrongWayStartTicks > WRONG_WAY_SUSTAIN_TICKS)
                {
                    wrongWayActive = true;
                    if (driveLogger != null && driveLogger.IsRunning)
                    {
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT wrong-way-start:"
                            + " spd=" + (veh != null ? veh.Speed.ToString("F1") : "-")
                            + " pos=" + (veh != null ? FmtV(veh.Position) : "-")
                            + " alert=" + (getSetting("wrongWayAlert") == 1));
                        // iter-36 B6: wrong-way onsets near an armed junction get a
                        // dedicated breadcrumb — the 07-04 Dorset death chain began
                        // as a wrong-way turn through jIdx=73 that no event tied to
                        // the junction. Instrumentation only this iter; iter-37
                        // fixes turn selection from this data.
                        if (junctionArmed && veh != null)
                        {
                            float wwHeading = (float)(Math.Atan2(veh.ForwardVector.Y,
                                veh.ForwardVector.X) * 57.29578);
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT wrongway-junction:"
                                + " jIdx=" + (junctionFromNode ? -1 : junctionEntrance.JunctionIdx)
                                + " violFrames=" + wwViolFrames
                                + " heading=" + wwHeading.ToString("F1")
                                + " skew=" + roadHeadingDelta.ToString("F1")
                                + " lat=" + lastLaneLateralError.ToString("F1"));
                        }
                    }
                }
                if (wrongWayActive && getSetting("wrongWayAlert") == 1
                    && now - wrongWayLastSpeechTicks > 40000000L) // 4 s repeat
                {
                    wrongWayLastSpeechTicks = now;
                    Speech.Info("Wrong way.");
                }
            }
            else
            {
                if (wrongWayActive && driveLogger != null && driveLogger.IsRunning)
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT wrong-way-end:"
                        + " durMs=" + ((now - wrongWayStartTicks) / 10000L));
                wrongWayActive = false;
                wrongWayStartTicks = 0;
            }
        }

        // R5: speed-zone governor. The v2 graph carries the source Speed
        // category (0=slowest..3=fastest) on ~9k nodes. Scan the walked node
        // chain ahead; when an upcoming node's category caps below our speed,
        // shed toward that cap before reaching it. Computed every scan for
        // telemetry; the brake floor applies only when restrictionAwareWalk
        // is on. Uses pathNodeIndices (node ids captured by the SOURCE 2
        // graph walk), so it is inert on GPS-route and native-fallback paths.
        private void UpdateSpeedZoneGovernor(Vehicle veh)
        {
            speedZoneBrakeRequest = 0f;
            speedZoneBrakeWouldBe = 0f;
            if (veh == null || !NodeGraph.IsLoaded || pathNodeIndices.Count == 0
                || pathPolylineFromGps) return;
            float speed = veh.Speed;
            if (speed < LANE_END_SAFE_SPEED + 2f) return;

            float along = 0f;
            GTA.Math.Vector3 prev = veh.Position;
            for (int i = 0; i < pathNodeIndices.Count; i++)
            {
                int idx = pathNodeIndices[i];
                GTA.Math.Vector3 p = NodeGraph.GetPosition(idx);
                float dxs = p.X - prev.X, dys = p.Y - prev.Y;
                along += (float)Math.Sqrt(dxs * dxs + dys * dys);
                prev = p;

                int cat = NodeGraph.GetSpeedCategory(idx);
                if (cat < 0) continue;
                float cap = cat == 0 ? 9f : cat == 1 ? 15f : cat == 2 ? 25f : float.MaxValue;
                // iter-49 A4: the shipped speed categories are coarse, and category
                // 2 (25 m/s) covers both a suburban arterial and a freeway on-ramp.
                // The engine's HIGHWAY flag separates them, so a genuine highway no
                // longer gets governed down to a surface-street cap — being braked
                // to 56 mph in the fast lane is its own hazard.
                if (getSetting("nodeHazardV2") == 1 && hazHighway && cat >= 2)
                    cap = float.MaxValue;
                if (cap >= speed - 1f) continue;

                float reqDecel = (speed * speed - cap * cap) / (2f * Math.Max(1f, along));
                if (reqDecel <= 1.2f) continue;
                float b = Math.Min(CurveFloorCap(speed),
                    0.25f + (reqDecel - 1.2f) / 6f * 0.5f);
                speedZoneBrakeWouldBe = b;
                if (getSetting("restrictionAwareWalk") == 1) speedZoneBrakeRequest = b;
                if (driveLogger != null && driveLogger.IsRunning
                    && DateTime.Now.Ticks - lastSpeedZoneLogTicks > 10000000L)
                {
                    lastSpeedZoneLogTicks = DateTime.Now.Ticks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT speedzone-brake:"
                        + " cat=" + cat + " cap=" + cap.ToString("F0")
                        + " dist=" + along.ToString("F1")
                        + " spd=" + speed.ToString("F1")
                        + " brake=" + b.ToString("F2")
                        + " applied=" + (speedZoneBrakeRequest > 0f));
                }
                break;
            }
        }

        // ---- iter-51 (roadSpeedGovernorV2): a cap tied to the ROAD, not to a
        // walked node chain --------------------------------------------------
        //
        // The single most expensive drive-assist failure of 08-11 was 47 m/s
        // (106 mph) down East Joshua Road, a rural two-lane: the lane-depart
        // correction saturated at -0.69, the car left the road at 46 m/s and the
        // cascade cost 1,181 of the session's 1,292 health drawdown.
        //
        // UpdateSpeedZoneGovernor above cannot help there. It reads the SHIPPED
        // graph's speed categories off pathNodeIndices, so it is inert on GPS-route
        // and native-fallback paths, and it fired three times in ten minutes.
        // roadFactsV2 asks the ENGINE instead, at the car's own position: 469/469
        // samples answered with a 0.0% refusal rate, and its lane counts agreed
        // with the shipped graph on 463 of 466. That is the signal to govern on.
        //
        // Shares speedZoneBrakeRequest rather than adding a channel: same owner in
        // the brake arbitration, same driver-throttle override, and speedzone is
        // already the name for "the road says slow down". Only ever RAISES the
        // request, so the node-category governor still wins where it is stricter.
        private const float ROAD_GOV_CAP_TWO_LANE = 22f;   // ~49 mph rural two-lane
        private const float ROAD_GOV_CAP_MULTI    = 27f;   // ~60 mph arterial
        private const float ROAD_GOV_CAP_HIGHWAY  = 33f;   // ~74 mph freeway
        private const float ROAD_GOV_MARGIN       = 2f;    // m/s of slack before braking
        private long lastRoadGovLogTicks = 0;

        private void UpdateRoadClassGovernor(Vehicle veh)
        {
            if (veh == null) return;
            if (getSetting("roadSpeedGovernorV2") != 1) return;
            GateReach("roadSpeedGovernorV2");
            // No engine road facts this scan means no road class; governing on a
            // guess is exactly the failure mode the shipped-graph governor has.
            if (!roadFactsValid) return;

            float speed = veh.Speed;
            if (speed < ROAD_GOV_CAP_TWO_LANE) return;

            // Total carriageway. rfNodeLanes is the same query's lane count and is
            // used only when the directional split came back empty.
            int lanes = rfLanesFwd + rfLanesBwd;
            if (lanes <= 0) lanes = rfNodeLanes;
            float cap = hazHighway ? ROAD_GOV_CAP_HIGHWAY
                      : (lanes >= 4 ? ROAD_GOV_CAP_MULTI
                      : (lanes <= 2 ? ROAD_GOV_CAP_TWO_LANE : 25f));

            if (speed <= cap + ROAD_GOV_MARGIN) return;

            // Proportional, and capped by the same curve limiter the node governor
            // uses, so this can never out-brake the comfort envelope.
            float over = speed - cap;
            float b = Math.Min(CurveFloorCap(speed), 0.20f + over / 20f * 0.5f);
            bool applied = false;
            if (b > speedZoneBrakeWouldBe) speedZoneBrakeWouldBe = b;
            if (b > speedZoneBrakeRequest)
            {
                speedZoneBrakeRequest = b;
                applied = true;
                GateFire("roadSpeedGovernorV2");
            }

            if (driveLogger != null && driveLogger.IsRunning
                && DateTime.Now.Ticks - lastRoadGovLogTicks > 10000000L)
            {
                lastRoadGovLogTicks = DateTime.Now.Ticks;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT speed-governor:"
                    + " lanes=" + lanes
                    + " lanesFwd=" + rfLanesFwd + " lanesBwd=" + rfLanesBwd
                    + " highway=" + hazHighway
                    + " cap=" + cap.ToString("F0")
                    + " spd=" + speed.ToString("F1")
                    + " over=" + over.ToString("F1")
                    + " brake=" + b.ToString("F2")
                    + " applied=" + applied);
            }
        }

        // iter-23 K2: 2D distance from a point to the first segment of a polyline
        // (cheap plausibility probe — the snap-to-parallel-road artifact shows up
        // in the lead segment).
        private static float DistToFirstSeg2D(GTA.Math.Vector3 p, List<GTA.Math.Vector3> poly)
        {
            if (poly.Count < 2) return float.MaxValue;
            float ax = poly[0].X, ay = poly[0].Y;
            float bx = poly[1].X, by = poly[1].Y;
            float abx = bx - ax, aby = by - ay;
            float lenSq = abx * abx + aby * aby;
            float t = lenSq < 0.01f ? 0f
                : Math.Max(0f, Math.Min(1f, ((p.X - ax) * abx + (p.Y - ay) * aby) / lenSq));
            float cx = ax + abx * t, cy = ay + aby * t;
            float dx = p.X - cx, dy = p.Y - cy;
            return (float)Math.Sqrt(dx * dx + dy * dy);
        }

        /// <summary>Flip hysteresis: if the freshly-rebuilt polyline's lead
        /// direction flips hard versus the last good one, keep the previous
        /// polyline for a few scans. The node search momentarily snapping to a
        /// parallel/oncoming road produced 150-220 deg heading jumps in the
        /// debug log; a genuine turn changes the lead heading gradually and
        /// persists past the short hold window.</summary>
        private void StabilizePolyline(Vehicle veh)
        {
            // iter-36 B6: POLY-HOLD EXPIRY. A held/frozen model whose lat hasn't
            // been recomputed for 5 s while the car is moving is stale scaffolding,
            // not stability (WEclip: lat locked at -5.30/-9.08 for tens of seconds
            // while the car crept — every downstream consumer read fiction). Drop
            // the hold state and adopt the fresh polyline as-is.
            if (getSetting("laneStability") == 1 && veh != null
                && lastLaneLateralErrorTicks > 0
                && DateTime.Now.Ticks - lastLaneLateralErrorTicks > 50000000L
                && veh.Speed > 0.5f
                && (prevPathPolyline.Count > 0 || polylineHoldCount > 0))
            {
                if (driveLogger != null && driveLogger.IsRunning
                    && DateTime.Now.Ticks - lastPolyExpireLogTicks > 20000000L)
                {
                    lastPolyExpireLogTicks = DateTime.Now.Ticks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT poly-hold-expire:"
                        + " latAgeMs=" + ((DateTime.Now.Ticks - lastLaneLateralErrorTicks) / 10000)
                        + " holdCount=" + polylineHoldCount
                        + " spd=" + veh.Speed.ToString("F1"));
                }
                prevPathPolyline.Clear();
                polylineHoldCount = 0;
                polylineDistrustUntilTicks = 0;
                tangentFlipPending = false;
                prevPathPolyline.AddRange(pathPolyline);
                return;
            }
            if (pathPolyline.Count >= 2 && prevPathPolyline.Count >= 2
                && polylineHoldCount < POLYLINE_MAX_HOLD)
            {
                // iter-23 K2: LATERAL-JUMP HOLD. A fresh polyline >5 m from the
                // car while the previous one was tracking (<3 m) and the car is
                // physically on a road = the node search snapped to a parallel
                // road/trail (the 192838 phantom-eject source). Also honor the K1
                // distrust latch. Hold the previous polyline (same MAX_HOLD cap).
                if (veh != null)
                {
                    float freshDist = DistToFirstSeg2D(veh.Position, pathPolyline);
                    float prevDist = DistToFirstSeg2D(veh.Position, prevPathPolyline);
                    bool distrustActive = DateTime.Now.Ticks < polylineDistrustUntilTicks;
                    // iter-28 P2a: hold a big one-frame lateral jump even when OFF-road
                    // (was gated on IsPositionOnRoad, so off-road snaps like 024041 #8
                    // passed through unfiltered, lat -2.2 -> -20.9 in one frame). Also
                    // hold a deck-level Z jump (the path snapping to a road below — #8
                    // path Z=4.9 vs car Z=12.2).
                    float freshLeadZ = pathPolyline.Count > 0 ? pathPolyline[0].Z : veh.Position.Z;
                    bool zSnap = Math.Abs(freshLeadZ - veh.Position.Z) > POLYLINE_DECK_JUMP_M
                        && prevDist < 5f;
                    bool lateralSnap = freshDist > POLYLINE_LATERAL_JUMP_M && prevDist < 3f;
                    // ---- iter-40 roadModelV2: DRIFT GUARD ----
                    // The hold assumes the previous polyline is the better reference.
                    // That stops being true once the car is steadily moving AWAY from
                    // it: the hold then re-confirms a line the car has left, so the
                    // reported lateral error stops growing and no staleness detector
                    // can fire (latAgeMs stays ~9 ms because lat IS being recomputed —
                    // just against the wrong line). On 07-28 incident 01 that froze
                    // `lat` at -4.16 for ~25 m of travel while the car ran off the
                    // pavement, and cost 248.2.
                    // iter-41 Stage 0.11: the guard ran BEFORE the hold decision and
                    // had no hold precondition, so with no hold in effect
                    // prevPathPolyline IS pathPolyline and the "drift" it measured was
                    // a line against itself. All 8 firings on 07-28 read
                    // freshDist == prevDist exactly with holdCount=0 — i.e. it only
                    // ever fired in the one state where it means nothing, and its
                    // reset then cleared hold state that did not exist. The guard's
                    // own rationale ("the hold re-confirms a line the car has left")
                    // presupposes a hold.
                    if (getSetting("roadModelV2") == 1 && polylineHoldCount > 0)
                    {
                        GateReach("roadModelV2");
                        if (prevDist > polyHoldPrevDist + POLY_HOLD_DRIFT_EPS_M)
                            polyHoldDriftStreak++;
                        else if (prevDist < polyHoldPrevDist)
                            polyHoldDriftStreak = 0;
                        polyHoldPrevDist = prevDist;
                        if (polyHoldDriftStreak >= POLY_HOLD_DRIFT_STREAK)
                        {
                            // iter-46 1-6: hoisted OUT of the 1 s log throttle below,
                            // for the same reason as offroadBrakeV2 — the drift guard
                            // fires here whether or not a log line is emitted.
                            GateFire("roadModelV2");
                            if (driveLogger != null && driveLogger.IsRunning
                                && DateTime.Now.Ticks - lastPolyHoldLogTicks > 10000000)
                            {
                                lastPolyHoldLogTicks = DateTime.Now.Ticks;
                                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT poly-hold-drift:"
                                    + " freshDist=" + freshDist.ToString("F1")
                                    + " prevDist=" + prevDist.ToString("F1")
                                    + " streak=" + polyHoldDriftStreak
                                    + " holdCount=" + polylineHoldCount);
                            }
                            // Stop holding: accept the fresh polyline and reset, so the
                            // lateral error reflects where the car actually is.
                            polyHoldDriftStreak = 0;
                            polyHoldPrevDist = 0f;
                            polylineHoldCount = 0;
                            prevPathPolyline.Clear();
                            prevPathPolyline.AddRange(pathPolyline);
                            return;
                        }
                    }
                    if ((lateralSnap || zSnap || (distrustActive && prevDist < freshDist)))
                    {
                        pathPolyline.Clear();
                        pathPolyline.AddRange(prevPathPolyline);
                        polylineHoldCount++;
                        if (driveLogger != null && driveLogger.IsRunning
                            && DateTime.Now.Ticks - lastPolyHoldLogTicks > 10000000)
                        {
                            lastPolyHoldLogTicks = DateTime.Now.Ticks;
                            driveLogger.Write("[F" + driveLogFrameCount + "] EVENT poly-hold:"
                                + " reason=" + (zSnap ? "deck" : lateralSnap ? "lateral" : "distrust")
                                + " freshDist=" + freshDist.ToString("F1")
                                + " prevDist=" + prevDist.ToString("F1"));
                        }
                        return;
                    }
                }
                // Skip hysteresis after a teleport / large relocation — a far
                // p0 means a new area, not a node-snap flip.
                float p0dx = pathPolyline[0].X - prevPathPolyline[0].X;
                float p0dy = pathPolyline[0].Y - prevPathPolyline[0].Y;
                bool sameArea = (p0dx * p0dx + p0dy * p0dy) < (50f * 50f);

                float ax = pathPolyline[1].X - pathPolyline[0].X;
                float ay = pathPolyline[1].Y - pathPolyline[0].Y;
                float bx = prevPathPolyline[1].X - prevPathPolyline[0].X;
                float by = prevPathPolyline[1].Y - prevPathPolyline[0].Y;
                float dot = ax * bx + ay * by;
                float cross = ax * by - ay * bx;
                float diffDeg = (float)(Math.Atan2(cross, dot) * 57.29578);
                if (sameArea && Math.Abs(diffDeg) > POLYLINE_FLIP_ANGLE)
                {
                    pathPolyline.Clear();
                    pathPolyline.AddRange(prevPathPolyline);
                    polylineHoldCount++;
                    return;
                }
                // iter-36 B6: TANGENT HYSTERESIS. Medium flips (45° up to the
                // hard POLYLINE_FLIP_ANGLE) are the Rockford junction thrash —
                // the node search alternating arms scan-to-scan (skew +72.7 ->
                // -62.5 in one frame). Require the same proposal on two
                // consecutive scans before adopting; a genuine turn re-proposes
                // immediately and only pays one scan of latency.
                if (getSetting("laneStability") == 1
                    && sameArea && Math.Abs(diffDeg) > 45f)
                {
                    if (!tangentFlipPending)
                    {
                        tangentFlipPending = true;
                        pathPolyline.Clear();
                        pathPolyline.AddRange(prevPathPolyline);
                        polylineHoldCount++;
                        return;
                    }
                    tangentFlipPending = false; // second consecutive proposal — adopt
                }
                else
                {
                    tangentFlipPending = false;
                }
            }
            polylineHoldCount = 0;
            prevPathPolyline.Clear();
            prevPathPolyline.AddRange(pathPolyline);
        }

        private void BuildPathPolylineRaw(Vehicle veh)
        {
            pathPolyline.Clear();
            pathPolylineFromGps = false;
            pathNodeIndices.Clear();          // iter-32: node ids of the walked path (SOURCE 2 only)
            lastPathStartNodeIdx = -1;
            lastWalkRestrictedCount = 0;
            if (veh == null) return;

            GTA.Math.Vector3 vehPos = veh.Position;
            GTA.Math.Vector3 vehFwd = veh.ForwardVector;
            // Flatten — Stanley control runs on the XY plane.
            GTA.Math.Vector3 flatFwd = new GTA.Math.Vector3(vehFwd.X, vehFwd.Y, 0f);
            if (flatFwd.LengthSquared() < 0.0001f) return;
            flatFwd.Normalize();

            // SOURCE 1: GPS route. This is the AI's planned path — exactly
            // what NPC drivers would follow if you handed them the same
            // waypoint. Use it whenever available.
            if (HasGpsRoute())
            {
                GTA.Math.Vector3 prev = vehPos;
                for (float d = PATH_GPS_SAMPLE_MIN; d <= PATH_POLYLINE_MAX_LOOKAHEAD; d += PATH_GPS_SAMPLE_STEP)
                {
                    GTA.Math.Vector3 pt;
                    if (!TrySampleGpsRoute(d, out pt)) break;
                    // Skip near-duplicate consecutive samples.
                    GTA.Math.Vector3 delta = pt - prev;
                    if (delta.X * delta.X + delta.Y * delta.Y < 1f) continue;
                    pathPolyline.Add(pt);
                    prev = pt;
                }
                if (pathPolyline.Count >= 2)
                {
                    pathPolylineFromGps = true;
                    return;
                }
                pathPolyline.Clear();
            }

            // SOURCE 2: static node graph. WalkAlongDirection respects
            // ForwardLaneCount > 0 (one-way correctness) and picks the
            // straightest neighbour at each junction — i.e. "what the AI
            // driver would do here."
            if (NodeGraph.IsLoaded)
            {
                int startIdx = NodeGraph.FindNearestNode(vehPos, STATIC_NODE_SEARCH_RADIUS);
                lastPathStartNodeIdx = startIdx; // iter-32: FRAME road-line context
                if (startIdx >= 0)
                {
                    GTA.Math.Vector3 startPos = NodeGraph.GetPosition(startIdx);
                    // Z-GUARD: reject a start node stacked on a different deck.
                    if (Math.Abs(startPos.Z - vehPos.Z) <= PATH_NODE_MAX_Z_DELTA)
                    {
                        // iter-32 R5: restriction-aware walk behind its setting;
                        // when OFF, run the plain walk for real and the restricted
                        // walk as a counterfactual so the log shows how often the
                        // restrictions WOULD have changed the route (dark-launch).
                        bool honorRestrict = getSetting("restrictionAwareWalk") == 1;
                        var walkedIdx = new List<int>(PATH_POLYLINE_HOPS);
                        var walked = NodeGraph.WalkAlongDirection(startIdx, flatFwd,
                            PATH_POLYLINE_HOPS, honorRestrict, walkedIdx);
                        if (honorRestrict)
                        {
                            lastWalkRestrictedCount = NodeGraph.LastWalkRestrictedCount;
                            lastWalkCfDiverged = false; // live mode: no shadow walk to compare
                        }
                        else
                        {
                            // iter-34 BS-5: keep the walked node ids of the shadow
                            // (restricted) walk and record whether it actually ENDS
                            // on a different node than the plain walk — the count
                            // alone can't show route divergence.
                            var cfIdx = new List<int>(PATH_POLYLINE_HOPS);
                            NodeGraph.WalkAlongDirection(startIdx, flatFwd,
                                PATH_POLYLINE_HOPS, true, cfIdx);
                            lastWalkRestrictedCount = NodeGraph.LastWalkRestrictedCount;
                            lastWalkCfDiverged = cfIdx.Count != walkedIdx.Count
                                || (cfIdx.Count > 0 && walkedIdx.Count > 0
                                    && cfIdx[cfIdx.Count - 1] != walkedIdx[walkedIdx.Count - 1]);
                        }
                        pathPolyline.Add(startPos);
                        pathNodeIndices.Add(startIdx);
                        float prevZ = startPos.Z;
                        for (int i = 0; i < walked.Count; i++)
                        {
                            // Truncate the walk if it jumps decks mid-path.
                            if (Math.Abs(walked[i].Z - prevZ) > PATH_NODE_MAX_Z_DELTA) break;
                            pathPolyline.Add(walked[i]);
                            pathNodeIndices.Add(walkedIdx[i]);
                            prevZ = walked[i].Z;
                        }
                        if (pathPolyline.Count >= 2) return;
                        pathPolyline.Clear(); // too short after Z-truncation — fall through
                        pathNodeIndices.Clear();
                    }
                }
            }

            // SOURCE 3: live native (last resort). Step forward and ask the
            // game for nearest road nodes at successive distances. Worse
            // than the static graph (this is what the old impl did and it
            // jittered) but better than nothing if the dump is missing.
            // C1: on a streaming gap every probe below returns false at step 1 and
            // breaks immediately, leaving an empty polyline — which downstream is
            // read as a path collapse (a braking trigger) rather than as missing
            // data. Skip the source and let the EVENT carry the real reason.
            if (!ArePathNodesLoadedAt(vehPos, "polylineSource3")) return;
            GTA.Math.Vector3 lastSample = vehPos;
            for (int step = 1; step <= PATH_POLYLINE_HOPS; step++)
            {
                GTA.Math.Vector3 probe = vehPos + flatFwd * (step * 12f);
                OutputArgument outPos = new OutputArgument();
                OutputArgument outHd  = new OutputArgument();
                OutputArgument outLn  = new OutputArgument();
                // iter-49 A3: this is the steering reference. Passing 1 here opted
                // the lane model INTO driveways and disabled spurs, which is the
                // likeliest source of the parallel-arm snap the lat clamp masks.
                bool ok = Function.Call<bool>(Hash.GET_NTH_CLOSEST_VEHICLE_NODE_WITH_HEADING,
                    probe.X, probe.Y, probe.Z, 1, outPos, outHd, outLn,
                    NodeFlagsFor(NODEFLAGS_PATH), 3.0f, 0f);
                if (!ok) break;
                GTA.Math.Vector3 nodePos = outPos.GetResult<GTA.Math.Vector3>();
                // Z-GUARD: skip a node stacked on a different deck. iter-49 A3: when
                // the engine will tell us the floor height here, judge the deck
                // against THAT rather than against the previous sample — a genuine
                // climb up an on-ramp and a snap onto the freeway above look
                // identical to a bare 12 m window.
                float floorZ;
                if (TryGetApproxFloorZ(nodePos, out floorZ)
                    && Math.Abs(nodePos.Z - floorZ) > PATH_NODE_MAX_Z_DELTA) continue;
                if (Math.Abs(nodePos.Z - lastSample.Z) > PATH_NODE_MAX_Z_DELTA) continue;
                GTA.Math.Vector3 delta = nodePos - lastSample;
                if (delta.X * delta.X + delta.Y * delta.Y < 4f) continue; // dedupe
                pathPolyline.Add(nodePos);
                lastSample = nodePos;
            }
        }

        /// <summary>2D distance (XY only) from point to the polyline. Returns
        /// float.MaxValue if polyline is empty.</summary>
        private float DistanceToPolyline2D(GTA.Math.Vector3 point)
        {
            int count = pathPolyline.Count;
            if (count == 0) return float.MaxValue;
            if (count == 1)
            {
                float dx0 = point.X - pathPolyline[0].X;
                float dy0 = point.Y - pathPolyline[0].Y;
                return (float)Math.Sqrt(dx0 * dx0 + dy0 * dy0);
            }
            float bestDsq = float.MaxValue;
            for (int i = 0; i < count - 1; i++)
            {
                GTA.Math.Vector3 a = pathPolyline[i];
                GTA.Math.Vector3 b = pathPolyline[i + 1];
                float abx = b.X - a.X, aby = b.Y - a.Y;
                float lenSq = abx * abx + aby * aby;
                float cx, cy;
                if (lenSq < 0.01f) { cx = a.X; cy = a.Y; }
                else
                {
                    float apx = point.X - a.X, apy = point.Y - a.Y;
                    float t = (apx * abx + apy * aby) / lenSq;
                    if (t < 0f) t = 0f; else if (t > 1f) t = 1f;
                    cx = a.X + abx * t;
                    cy = a.Y + aby * t;
                }
                float dx = point.X - cx, dy = point.Y - cy;
                float dsq = dx * dx + dy * dy;
                if (dsq < bestDsq) bestDsq = dsq;
            }
            return (float)Math.Sqrt(bestDsq);
        }

        /// <summary>Is `point` close enough to the upcoming path that the
        /// drive assist should treat it as a threat to react to? When no
        /// polyline is available (truly off-road) returns true — better to
        /// over-react than to ignore NPCs entirely.</summary>
        private bool IsInPathCorridor(GTA.Math.Vector3 point, float corridorM)
        {
            if (pathPolyline.Count < 2) return true;
            return DistanceToPolyline2D(point) <= corridorM;
        }

        /// <summary>Stanley lane-keeping controller against the prebuilt
        /// pathPolyline. Returns a normalized steer input in [-1, 1] where
        /// +1 = full right. Also sets isOnValidRoad / roadHeadingDelta for
        /// the legacy state machine.</summary>
        private float ComputeStanleySteer(Vehicle veh)
        {
            lastLookaheadHeadingDelta = 0f; // iter-17 Fix 1: default benign; full path sets it below
            // iter-26 B1: steer against the lane-centered copy. It is a 1:1
            // per-vertex offset of pathPolyline (same Count/topology), so bestSeg /
            // lastClosestPolySeg stay valid indices into pathPolyline for the
            // curve-brake and the windowed failure gate (which intentionally keep
            // using the raw road geometry below). Falls back to raw if not built.
            List<GTA.Math.Vector3> poly = (steerPolyline != null && steerPolyline.Count >= 2)
                ? steerPolyline : pathPolyline;
            if (poly.Count < 2)
            {
                isOnValidRoad = false;
                roadHeadingDelta = 0f;
                prevStanleyLatErrorTicks = 0; // iter-21 I2: no path = no valid error history
                // iter-13 Patch V: the lane just ran out. If we were moving fast
                // when it vanished, stamp it so ComputeCurveBrake governs speed
                // down instead of letting the car coast off the end at speed.
                if (veh != null && veh.Speed > LANE_END_SAFE_SPEED)
                    laneCollapseAtSpeedTicks = DateTime.Now.Ticks;
                return 0f;
            }

            GTA.Math.Vector3 vehPos = veh.Position;
            GTA.Math.Vector3 vehFwd = veh.ForwardVector;
            GTA.Math.Vector3 vehRight = veh.RightVector;
            float speed = veh.Speed;

            GTA.Math.Vector3 flatFwd = new GTA.Math.Vector3(vehFwd.X, vehFwd.Y, 0f);
            if (flatFwd.LengthSquared() < 0.0001f)
            {
                isOnValidRoad = false; roadHeadingDelta = 0f; return 0f;
            }
            flatFwd.Normalize();
            GTA.Math.Vector3 flatRight = new GTA.Math.Vector3(vehRight.X, vehRight.Y, 0f);
            if (flatRight.LengthSquared() < 0.0001f)
            {
                isOnValidRoad = false; roadHeadingDelta = 0f; return 0f;
            }
            flatRight.Normalize();

            // Front axle position. iter-18 A4: derive the offset from the model's
            // real half-length (~0.6 x half-length lands near the front axle for
            // cars, buses, and bikes alike) instead of a fixed sedan wheelbase, so
            // Stanley's reference point is honest on long vehicles. Clamped, with
            // the legacy half-wheelbase fallback on degenerate model reads.
            float vehHalfLen = GetVehicleHalfDims(veh).Y;
            float frontAxleOffset = (vehHalfLen >= 1.0f && vehHalfLen <= 8.0f)
                ? Math.Min(3.0f, Math.Max(1.0f, vehHalfLen * 0.6f))
                : PURE_PURSUIT_WHEELBASE * 0.5f;
            GTA.Math.Vector3 frontAxle = vehPos + flatFwd * frontAxleOffset;

            // Find the closest polyline segment to the front axle.
            int bestSeg = 0;
            float bestDsq = float.MaxValue;
            float bestCx = poly[0].X, bestCy = poly[0].Y;
            for (int i = 0; i < poly.Count - 1; i++)
            {
                GTA.Math.Vector3 a = poly[i];
                GTA.Math.Vector3 b = poly[i + 1];
                float abx = b.X - a.X, aby = b.Y - a.Y;
                float lenSq = abx * abx + aby * aby;
                float cx, cy;
                if (lenSq < 0.01f) { cx = a.X; cy = a.Y; }
                else
                {
                    float apx = frontAxle.X - a.X, apy = frontAxle.Y - a.Y;
                    float t = (apx * abx + apy * aby) / lenSq;
                    if (t < 0f) t = 0f; else if (t > 1f) t = 1f;
                    cx = a.X + abx * t;
                    cy = a.Y + aby * t;
                }
                float dx = frontAxle.X - cx, dy = frontAxle.Y - cy;
                float dsq = dx * dx + dy * dy;
                if (dsq < bestDsq) { bestDsq = dsq; bestSeg = i; bestCx = cx; bestCy = cy; }
            }
            // Expose the closest segment for ComputeCurveBrake's lookahead.
            lastClosestPolySeg = bestSeg;

            // Segment tangent at the closest point. For the last segment we
            // already used [bestSeg, bestSeg+1].
            GTA.Math.Vector3 segA = poly[bestSeg];
            GTA.Math.Vector3 segB = poly[bestSeg + 1];
            float segDx = segB.X - segA.X, segDy = segB.Y - segA.Y;
            float segLen = (float)Math.Sqrt(segDx * segDx + segDy * segDy);
            if (segLen < 0.01f)
            {
                isOnValidRoad = false; roadHeadingDelta = 0f; return 0f;
            }
            segDx /= segLen; segDy /= segLen;

            // Heading error: signed angle from vehicle forward to segment
            // direction. Positive = segment is to the LEFT of vehicle forward,
            // meaning the vehicle is rotated to the right of the path tangent
            // and must steer left to align.
            float headingDot   = flatFwd.X * segDx + flatFwd.Y * segDy;
            float headingCross = flatFwd.X * segDy - flatFwd.Y * segDx;
            float headingError = (float)Math.Atan2(headingCross, headingDot);

            // Lateral error: signed distance from front axle to closest point.
            // Positive = path is to the RIGHT of the vehicle, so the vehicle
            // needs to steer right.
            float toCx = bestCx - frontAxle.X, toCy = bestCy - frontAxle.Y;
            float lateralError = flatRight.X * toCx + flatRight.Y * toCy;
            // iter-34 MED-6: distrust a physically impossible polyline lateral.
            // 07-03 F5183 fed lat=47.2 into offroad-risk while the NATIVE said the
            // car was on the road at 0.6 m/s (polyline snapped wrong / one Z-level
            // off). When the polyline contradicts the native at low speed, clamp
            // to the road's half-width so a blown lat can't drive governors,
            // offroad-risk, or recovery decisions. Native call only runs in the
            // rare contradiction-candidate case.
            // iter-49 B2: same recalibration as the polyline bias. This half-width
            // is what a "physically impossible" lateral is measured against, so an
            // over-wide lane constant made the distrust clamp too permissive — a
            // 4-lane road was credited with 10.6 m of half-carriageway instead of
            // 8.4 m, and blown lateral errors up to 2.2 m larger passed the test.
            // The live lane counts and the engine's own median gap replace the
            // shipped graph's counts and its shoulder-extra when they are fresh.
            bool latLaneW = getSetting("laneWidthV2") == 1;
            int latLanes = (latLaneW && roadFactsValid)
                ? rfLanesFwd + rfLanesBwd
                : lastLaneOffsetFwd + lastLaneOffsetBwd;
            float latLaneWidth = latLaneW ? VANILLA_LANE_WIDTH_M : LANE_WIDTH_M;
            float latMedian = (latLaneW && roadFactsValid && rfMedianWidth > 0f)
                ? rfMedianWidth : Math.Max(0, lastLaneWidthExtraM);
            float latHalfW = (latLanes > 0 ? latLanes : 2) * latLaneWidth * 0.5f
                + latMedian;
            if (speed < 3f && Math.Abs(lateralError) > latHalfW + LAT_DISTRUST_MARGIN
                && IsPositionOnRoad(vehPos))
            {
                float clamped = latHalfW * Math.Sign(lateralError);
                if (driveLogger != null && driveLogger.IsRunning
                    && DateTime.Now.Ticks - lastLatDistrustLogTicks > 20000000)
                {
                    lastLatDistrustLogTicks = DateTime.Now.Ticks;
                    driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lat-distrust:"
                        + " raw=" + lateralError.ToString("F1")
                        + " clamped=" + clamped.ToString("F1")
                        + " halfW=" + latHalfW.ToString("F1")
                        + " spd=" + speed.ToString("F1"));
                }
                lateralError = clamped;
            }
            // iter-36 B6: LAT-SNAP CLAMP. 07-04 Joshua Rd/Rockford: lat jumped
            // 5-12 m scan-to-scan while the car barely moved (node search snapping
            // to a parallel/oncoming arm) and the controller obediently chased
            // each flip into scenery. When the model teleports without the car
            // moving, hold the previous lat and run the cross-track term at 30%
            // authority until 3 consecutive scans agree with each other.
            if (getSetting("laneStability") == 1)
            {
                long lcNow = DateTime.Now.Ticks;
                bool lcPrevFresh = latClampPrevTicks > 0
                    && (lcNow - latClampPrevTicks) < 10000000L; // prev sample < 1 s old
                float lcDPlanar = lcPrevFresh ? PlanarDist(vehPos, latClampPrevPos) : 999f;
                float lcRawLat = lateralError;
                if (latClampActive)
                {
                    if (Math.Abs(lcRawLat - latClampPrevRaw) < 1.5f)
                        latClampConsistentFrames++;
                    else
                        latClampConsistentFrames = 0;
                    if (latClampConsistentFrames >= 3)
                        latClampActive = false; // model settled — accept it
                    else
                        lateralError = latClampHeldLat;
                }
                else if (lcPrevFresh && lcDPlanar < 2f
                    && Math.Abs(lcRawLat - latClampPrevRaw) > 5f)
                {
                    latClampActive = true;
                    latClampConsistentFrames = 0;
                    latClampHeldLat = latClampPrevRaw;
                    lateralError = latClampHeldLat;
                    if (driveLogger != null && driveLogger.IsRunning
                        && lcNow - lastLatClampLogTicks > 5000000)
                    {
                        lastLatClampLogTicks = lcNow;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT lat-snap-clamp:"
                            + " from=" + latClampPrevRaw.ToString("F1")
                            + " to=" + lcRawLat.ToString("F1")
                            + " dPlanar=" + lcDPlanar.ToString("F2")
                            + " held=" + latClampHeldLat.ToString("F1"));
                    }
                }
                latClampPrevRaw = lcRawLat;
                latClampPrevPos = vehPos;
                latClampPrevTicks = lcNow;
            }
            // Expose for the haptic layer's lane-edge drift detection.
            lastLaneLateralError = lateralError;
            // iter-29 C1: stamp freshness. When the polyline is short/held this method
            // early-returns without updating lastLaneLateralError, so the value (and the
            // lookback ring that copies it) FREEZES during the exact wedge windows it
            // should capture. latAgeMs on the FRAME line makes a stale value visible.
            lastLaneLateralErrorTicks = DateTime.Now.Ticks;

            // iter-18 B1 step 1: ~1 Hz polyline lateral-offset telemetry. The
            // negative of lateralError is where the CAR sits relative to the path.
            // If the distribution clusters ~half a carriageway to one side on
            // two-way streets, the polyline is a road CENTERLINE and the planned
            // lane-offset work (plan B1 step 2) knows its calibration magnitude.
            // src distinguishes GPS- vs node-graph-sourced polylines, which may
            // bias differently.
            if (speed > 3f && driveLogger != null && driveLogger.IsRunning
                && DateTime.Now.Ticks - lastPolyLatLogTicks > 10000000)
            {
                lastPolyLatLogTicks = DateTime.Now.Ticks;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT poly-lat:"
                    // iter-39 L6: this used to publish -lateralError under the name
                    // "lat" — the opposite sign to the road:/marker lat= that every
                    // other consumer reads (they disagreed in 115 of 116 paired
                    // samples on 07-23). Keep the car-relative value under its own
                    // name rather than overloading "lat". Two opposite-signed
                    // lateral values sharing one key is an invitation to a steer-
                    // direction sign bug, in a mod that tells blind drivers which
                    // way to steer.
                    + " lat=" + lateralError.ToString("F2")
                    + " carLat=" + (-lateralError).ToString("F2")
                    + " src=" + (pathPolylineFromGps ? "gps" : "node")
                    + " seg=" + bestSeg + "/" + (pathPolyline.Count - 1)
                    + " speed=" + speed.ToString("F1")
                    // iter-21 I2/I3: controller-term telemetry for the weave audit
                    // (values from the previous scan — the log site precedes the math).
                    + " eRate=" + lastStanleyERate.ToString("F2")
                    + " cross=" + lastStanleyCross.ToString("F3")
                    + " damp=" + lastStanleyDamp.ToString("F3")
                    + " ff=" + lastStanleyFf.ToString("F3"));
                // iter-26 B1: poly-offset calibration — the computed lane offset
                // (whether or not applied) paired with the actual car-vs-path
                // position (lat), so the dark-launch drive confirms magnitude and
                // sign per road type before the offset is enabled.
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT poly-offset:"
                    + " applied=" + (getSetting("laneOffsetPolyline") == 1)
                    + " offset=" + lastLaneOffsetMag.ToString("F2")
                    + " fwd=" + lastLaneOffsetFwd
                    + " bwd=" + lastLaneOffsetBwd
                    + " jblend=" + lastLaneOffsetJBlend.ToString("F2")
                    // iter-39 L6: this used to publish -lateralError under the name
                    // "lat" — the opposite sign to the road:/marker lat= that every
                    // other consumer reads (they disagreed in 115 of 116 paired
                    // samples on 07-23). Keep the car-relative value under its own
                    // name rather than overloading "lat". Two opposite-signed
                    // lateral values sharing one key is an invitation to a steer-
                    // direction sign bug, in a mod that tells blind drivers which
                    // way to steer.
                    + " lat=" + lateralError.ToString("F2")
                    + " carLat=" + (-lateralError).ToString("F2")
                    + " src=" + (pathPolylineFromGps ? "gps" : "node"));
            }

            // Stanley: δ = -ψ_e + atan2(k * e, v + ε).
            // Sign on ψ_e is negated because in our convention
            // "headingCross > 0" means the path heads LEFT of us, which
            // requires LEFT steering (= negative input).
            // iter-21 I1: the raw formula is what drove the 180513 countryside
            // weave — at 9-12 m/s with a 10+ m error it saturates to full lock
            // (snap-back + overshoot). Three changes: (a) the error fed to the
            // controller saturates at STANLEY_CTE_CAP_M (beyond 4 m the demand
            // stops growing — recovery handles genuine departures), (b) the gain
            // is speed-scheduled (full K only at >=20 m/s; 60% at crawl), and
            // (c) the cross-track term itself is capped at ~20 deg so the heading
            // term keeps authority for genuine skew.
            float eEff = Math.Sign(lateralError)
                * Math.Min(Math.Abs(lateralError), STANLEY_CTE_CAP_M);
            float kEff = STANLEY_K * (0.60f + 0.40f * Math.Min(speed / 20f, 1f));
            float crossTrack = (float)Math.Atan2(kEff * eEff, speed + STANLEY_SOFT);
            // iter-36 B6: while the lat-snap clamp is holding a distrusted model,
            // the cross-track term runs at reduced authority (heading term keeps
            // full authority — skew is measured off the same held tangent).
            if (latClampActive) crossTrack *= 0.3f;
            // ---- iter-51 (polyDistrustV2): the ENGINE says we are on a different
            // road than the polyline we are steering against ----
            //
            // roadFactsV2's cross-check 3 measures the distance from the engine's own
            // road edge to our lead segment. On 08-11 that read p50 = 6.0 m, p95 =
            // 33.1 m, max = 79.7 m — the shipped polyline was routinely on a
            // PARALLEL road. Incident 01, the session's only player-marked failure,
            // is that divergence in motion: lat swinging -1.7 -> -5.7 -> +4.5 -> -5.7
            // in five seconds with the street name flipping between two roads, and
            // the wheel being sawed left-right to chase it.
            //
            // The existing latClampActive catches a polyline that JUMPED. This
            // catches one that is steadily, quietly wrong — which the jump detector
            // cannot see, because a consistently wrong polyline never jumps.
            //
            // Fades the cross-track term only. The heading term is measured off the
            // same tangent and keeps full authority, so the car holds the road's
            // direction instead of chasing a lane position it cannot trust: heading
            // hold, not hands off.
            if (polyDistrustV2Cached && roadFactsValid && rfPolyDivergenceM > 0f)
            {
                GateReach("polyDistrustV2");
                if (rfPolyDivergenceM > POLY_DIVERGE_DISTRUST_M)
                {
                    // Linear fade to zero between the threshold and twice it, so a
                    // borderline reading does not flip lane-keeping on and off.
                    float t = (rfPolyDivergenceM - POLY_DIVERGE_DISTRUST_M) / POLY_DIVERGE_DISTRUST_M;
                    float scale = Math.Max(0f, 1f - Math.Min(1f, t));
                    crossTrack *= scale;
                    GateFire("polyDistrustV2");
                    if (driveLogger != null && driveLogger.IsRunning
                        && DateTime.Now.Ticks - lastPolyDivergeLogTicks > 10000000L)
                    {
                        lastPolyDivergeLogTicks = DateTime.Now.Ticks;
                        driveLogger.Write("[F" + driveLogFrameCount + "] EVENT poly-diverge:"
                            + " divergeM=" + rfPolyDivergenceM.ToString("F1")
                            + " lat=" + lateralError.ToString("F1")
                            + " scale=" + scale.ToString("F2")
                            + " spd=" + speed.ToString("F1"));
                    }
                }
            }
            // W2.3: FREEZE STEER AT STANDSTILL. Steering angle at ~0 forward speed
            // produces no lateral motion, only tyre scrub against whatever the car is
            // pinned on. At a standstill with a ~3 m lateral error the term saturates
            // to near-full lock (atan(0.9*3/2.0)=0.96 rad) and, with full throttle,
            // sands the car against the wall/NPC -> the dominant iter-35 death
            // signature (spd 0-1.5, mode=LaneKeeping, layer=0). Fade cross-track to
            // zero below ~3 m/s so the lane-keeper stops driving into the obstacle and
            // the recovery ladder can pivot/reverse instead. Also disables the iter-30
            // P4 widening below, which widens the lock exactly in this regime.
            bool steerFreezeAtStop = getSetting("steerFreezeAtStop") == 1;
            if (steerFreezeAtStop)
            {
                // iter-46 1-1: read unconditionally inside the Stanley path, so its
                // eval:0/fire:0 on both sessions was — like actuationV2's — proof of a
                // missing counter, not of an unreached gate. fire = the fade actually
                // reduced the cross-track term, which is the whole behaviour.
                GateReach("steerFreezeAtStop");
                float freezeScale = Math.Max(0f, Math.Min(1f, (speed - 1.0f) / 2.0f));
                if (freezeScale < 1f) GateFire("steerFreezeAtStop");
                crossTrack *= freezeScale;
            }
            // iter-30 P4: a slow car can safely use more steering angle to drag a large
            // lateral error back. The fixed 0.35 rad (~20 deg) cap left iter-29 #8/#9 unable
            // to correct a ~5 m offset at 5-6 m/s (Stanley saturated, yet the car stayed
            // "on road" so recovery never armed). Widen the cap toward ~0.62 rad (~35 deg)
            // as speed drops below 8 m/s when the (capped) error is large; unchanged at
            // cruising speed so the countryside weave (iter-21 I1) doesn't return.
            // W2.3: suppressed under steerFreezeAtStop — at a standstill this widening
            // is exactly the full-lock-into-the-wall mechanism, not a recovery aid.
            float crossMax = STANLEY_CROSS_MAX_RAD;
            if (!steerFreezeAtStop && speed < 8f && Math.Abs(eEff) > 3f)
                crossMax = STANLEY_CROSS_MAX_RAD + 0.27f * (1f - speed / 8f);
            if (crossTrack > crossMax) crossTrack = crossMax;
            else if (crossTrack < -crossMax) crossTrack = -crossMax;

            // iter-21 I2: lateral-rate DAMPING — the missing D term. PD convention:
            // the derivative term carries the SAME sign structure as the
            // proportional term (positive lateralError = path right of car =
            // steer right), so a car converging on the path (error shrinking)
            // automatically gets its correction eased before it overshoots.
            float dampTerm = 0f;
            float eRate = 0f;
            long stanleyNow = DateTime.Now.Ticks;
            if (prevStanleyLatErrorTicks > 0)
            {
                float dtSec = (stanleyNow - prevStanleyLatErrorTicks) / 10000000f;
                if (dtSec >= 0.02f && dtSec <= 0.5f)
                {
                    eRate = (lateralError - prevStanleyLatError) / dtSec;
                    dampTerm = STANLEY_KD * eRate / (speed + STANLEY_SOFT);
                    if (dampTerm > 0.25f) dampTerm = 0.25f;
                    else if (dampTerm < -0.25f) dampTerm = -0.25f;
                }
            }
            prevStanleyLatError = lateralError;
            prevStanleyLatErrorTicks = stanleyNow;

            // iter-21 I3: CURVATURE FEED-FORWARD — anticipate the bend instead of
            // chasing it (the drift-out phase of the weave at 22-28 m/s). Signed
            // Menger curvature through the closest segment's far vertex; left
            // bend (positive 2D cross) needs LEFT steer = negative rad, matching
            // the -headingError convention above.
            float ffTerm = 0f;
            if (bestSeg + 2 < pathPolyline.Count)
            {
                GTA.Math.Vector3 fa = pathPolyline[bestSeg];
                GTA.Math.Vector3 fb = pathPolyline[bestSeg + 1];
                GTA.Math.Vector3 fc = pathPolyline[bestSeg + 2];
                float abx = fb.X - fa.X, aby = fb.Y - fa.Y;
                float bcx = fc.X - fb.X, bcy = fc.Y - fb.Y;
                float lab = (float)Math.Sqrt(abx * abx + aby * aby);
                float lbc = (float)Math.Sqrt(bcx * bcx + bcy * bcy);
                float lacx = fc.X - fa.X, lacy = fc.Y - fa.Y;
                float lac = (float)Math.Sqrt(lacx * lacx + lacy * lacy);
                if (lab > 1f && lbc > 1f && lac > 1f)
                {
                    float crossZ = abx * bcy - aby * bcx;
                    float kappa = 2f * Math.Abs(crossZ) / (lab * lbc * lac);
                    // iter-43 A1: the wheelbase here sets how much steer the curve
                    // itself demands. It was a fixed 2.8 m "approximate sedan"
                    // value for every vehicle, so a long truck was fed roughly half
                    // the feedforward its own geometry requires and ran wide.
                    ffTerm = -Math.Sign(crossZ)
                        * (float)Math.Atan(GetVehicleWheelbase(veh) * kappa);
                    // iter-22 J2: PROXIMITY FADE — anticipating the path's curve
                    // is only meaningful when ON the path. In 184335 the ff term
                    // (+0.202) cancelled the return correction (-0.229) while the
                    // car was 4 m off-line at 24 m/s and it sailed into the Alamo
                    // Sea. Full ff when tracking tightly, zero beyond 3.5 m CTE.
                    ffTerm *= Math.Max(0f, 1f - Math.Abs(lateralError) / STANLEY_FF_FADE_M);
                    if (ffTerm > STANLEY_FF_MAX_RAD) ffTerm = STANLEY_FF_MAX_RAD;
                    else if (ffTerm < -STANLEY_FF_MAX_RAD) ffTerm = -STANLEY_FF_MAX_RAD;
                }
            }

            lastStanleyERate = eRate;
            lastStanleyCross = crossTrack;
            lastStanleyDamp = dampTerm;
            lastStanleyFf = ffTerm;

            float steerRad = -headingError + crossTrack + dampTerm + ffTerm;
            // iter-43 A2: clamp to what this vehicle's steering lock can actually
            // reach, never wider than the legacy cap.
            float maxRad = GetVehicleSteerLimitRad();
            if (steerRad > maxRad) steerRad = maxRad;
            else if (steerRad < -maxRad) steerRad = -maxRad;

            // Surface state for the rest of the state machine.
            isOnValidRoad = true;
            // Convert headingError (radians) to the degree convention used by
            // the existing code. Sign matches: positive headingError = path
            // heads left of vehicle = vehicle's heading is right of path's
            // heading = roadHeadingDelta should be NEGATIVE in the existing
            // convention (which measures node_heading - vehicle_heading).
            roadHeadingDelta = -headingError * 57.29578f;

            // ---- iter-17 FIX 1: WINDOWED-MINIMUM HEADING ERROR (failure metric only) ----
            // The control steer above is correct against the closest segment, but the
            // lane-keep FAILURE gate must not trip on a junction's short perpendicular GPS
            // dogleg. Walk the polyline forward from the closest point and keep the smallest
            // heading-error magnitude over a window that clears one full GPS sample step.
            // Each segment has a constant tangent, so one sample per segment is exact. A
            // junction dogleg is straddled (the real through-road wins the min); a genuinely
            // sideways car reads large at every sample and still fails the gate.
            {
                float bestSkewSigned = headingError;
                float bestSkewMag = Math.Abs(headingError);
                float walked = 0f;
                float curX = bestCx, curY = bestCy;
                for (int i = bestSeg; i < pathPolyline.Count - 1 && walked < LANEFAIL_LOOKAHEAD_MAX; i++)
                {
                    GTA.Math.Vector3 sa = pathPolyline[i];
                    GTA.Math.Vector3 sb = pathPolyline[i + 1];
                    float tdx = sb.X - sa.X, tdy = sb.Y - sa.Y;
                    float tlen = (float)Math.Sqrt(tdx * tdx + tdy * tdy);
                    if (tlen >= 0.01f)
                    {
                        tdx /= tlen; tdy /= tlen;
                        float dt2 = flatFwd.X * tdx + flatFwd.Y * tdy;
                        float cr2 = flatFwd.X * tdy - flatFwd.Y * tdx;
                        float he2 = (float)Math.Atan2(cr2, dt2);
                        if (Math.Abs(he2) < bestSkewMag) { bestSkewMag = Math.Abs(he2); bestSkewSigned = he2; }
                    }
                    // Advance arc-length by the segment length ahead of the current point
                    // (remaining length of bestSeg on the first pass, full length after).
                    float adx = sb.X - curX, ady = sb.Y - curY;
                    walked += (float)Math.Sqrt(adx * adx + ady * ady);
                    curX = sb.X; curY = sb.Y;
                }
                lastLookaheadHeadingDelta = -bestSkewSigned * 57.29578f;
            }

            return steerRad / maxRad;
        }

        /// <summary>Inspects the pathPolyline ahead of the closest segment for a
        /// sharp bend. If one is found and current speed exceeds the safe
        /// cornering speed for it, returns a brake request in [0, CURVE_BRAKE_MAX]
        /// sized to shed the excess speed before the turn; otherwise 0.</summary>
        // iter-24 L1: severity-scaled curve-brake cap. Comfort-capped at
        // CURVE_BRAKE_MAX for modest over-speed; ramps to full brake as the
        // car's speed exceeds the safe cornering speed for the bend.
        private float CurveBrakeCap(float speed, float vSafe)
        {
            float overspeed = speed / Math.Max(vSafe, 1f);
            if (overspeed <= CURVE_OVERSPEED_SOFT) return CURVE_BRAKE_MAX;
            if (overspeed >= CURVE_OVERSPEED_HARD) return CURVE_BRAKE_HARD_MAX;
            float t = (overspeed - CURVE_OVERSPEED_SOFT)
                    / (CURVE_OVERSPEED_HARD - CURVE_OVERSPEED_SOFT);
            return CURVE_BRAKE_MAX + t * (CURVE_BRAKE_HARD_MAX - CURVE_BRAKE_MAX);
        }

        // iter-24 L1: speed-scaled cap for the lane-end-governor floors (skew,
        // skew-rate, path run-out), which fire before a vSafe is known. A fast
        // car already skewing / running out of lane needs real brake authority.
        private float CurveFloorCap(float speed)
        {
            if (speed <= 18f) return CURVE_BRAKE_MAX;        // ~40 mph: comfort cap
            if (speed >= 36f) return CURVE_BRAKE_HARD_MAX;   // ~80 mph: full
            return CURVE_BRAKE_MAX
                 + (speed - 18f) / 18f * (CURVE_BRAKE_HARD_MAX - CURVE_BRAKE_MAX);
        }

        private float ComputeCurveBrake(Vehicle veh)
        {
            // Iter-10 Patch D: skew-aware brake floor. Independent of the
            // polyline-driven curve detection below, if the car is already
            // significantly skewed against the road tangent at meaningful
            // speed, the physics model has already lost the bend — fire some
            // brake regardless of what the meta vSafe says. Catches the
            // SPORTS_CAR case where meta vSafe @ 22° = 42 m/s and the existing
            // min(physics, meta) gate still lets the car oversteer
            // (driveassist-2026-05-25-231603 F2480: 29 m/s at 16.8° skew with
            // curveBrake=0). All early returns below propagate this floor.
            float skewBrakeFloor = 0f;
            {
                float skewMag = Math.Abs(roadHeadingDelta);
                if (skewMag > 15f && veh.Speed > 8f)
                {
                    skewBrakeFloor = 0.2f + Math.Min(0.4f, (skewMag - 15f) / 30f * 0.4f);
                    float skewCap = CurveFloorCap(veh.Speed); // iter-24 L1: high-speed skew may exceed 0.6
                    if (skewBrakeFloor > skewCap) skewBrakeFloor = skewCap;
                }
            }

            // iter-13 Patch V: LANE-END SPEED GOVERNOR. The absolute-skew floor
            // above only fires once the car is ALREADY misaligned. These three
            // terms brake BEFORE the car departs the lane at speed (the Fort
            // Zancudo failure: held a lane at 21 m/s, the lane ended, the car
            // shot off and collided). All terms only RAISE the floor (max), so
            // they can never reduce existing braking.
            long vNow = DateTime.Now.Ticks;
            float curSkewAbs = Math.Abs(roadHeadingDelta);
            // (1) SKEW-RATE: skew climbing fast at speed = the bend is getting
            //     away from us. React before the absolute angle is large.
            if (prevRoadHeadingDeltaTicks != 0 && veh.Speed > 8f)
            {
                float dtSec = (vNow - prevRoadHeadingDeltaTicks) / 10000000f;
                if (dtSec > 0.001f)
                {
                    float skewRate = (curSkewAbs - prevRoadHeadingDeltaAbs) / dtSec;
                    if (skewRate > 40f)
                    {
                        float rateBrake = Math.Min(CurveFloorCap(veh.Speed), 0.3f + skewRate / 200f); // iter-24 L1
                        if (rateBrake > skewBrakeFloor) skewBrakeFloor = rateBrake;
                    }
                }
            }
            prevRoadHeadingDeltaAbs = curSkewAbs;
            prevRoadHeadingDeltaTicks = vNow;
            // (2) POLYLINE COLLAPSE: the road just vanished underneath us at
            //     speed (ComputeStanleySteer stamped laneCollapseAtSpeedTicks).
            //     Apply a firm-but-comfortable floor for a short window instead
            //     of coasting off the end.
            if (laneCollapseAtSpeedTicks != 0
                && (vNow - laneCollapseAtSpeedTicks) < 5000000   // 500 ms window
                && veh.Speed > LANE_END_SAFE_SPEED)
            {
                if (0.5f > skewBrakeFloor) skewBrakeFloor = 0.5f;
            }
            // (3) PATH RUN-OUT: the closest segment is within ~2 of the polyline
            //     end and we're moving fast — shed speed toward a safe end-of-
            //     lane crawl before we reach the last point.
            if (pathPolyline.Count >= 2
                && lastClosestPolySeg >= pathPolyline.Count - 3
                && veh.Speed > LANE_END_SAFE_SPEED + 2f)
            {
                float over = (veh.Speed - LANE_END_SAFE_SPEED) / 12f;
                float runoutBrake = Math.Min(CurveFloorCap(veh.Speed), 0.3f + over); // iter-24 L1
                if (runoutBrake > skewBrakeFloor) skewBrakeFloor = runoutBrake;
            }
            // (4) iter-32 R3/R5: signalized-junction approach + speed-zone
            //     governors. Both computed in the scan tick, both already
            //     CurveFloorCap-capped and zero unless their settings are on.
            //     Only-raise, like every other term in this chain.
            if (junctionBrakeRequest > skewBrakeFloor) skewBrakeFloor = junctionBrakeRequest;
            if (speedZoneBrakeRequest > skewBrakeFloor) skewBrakeFloor = speedZoneBrakeRequest;
            // (4b) iter-49 A4: the give-way governor joins the same chain on the
            //      same terms — already capped, zero unless nodeHazardV2 is on,
            //      only-raise. A yield is not a stop, for the same reason a light
            //      is not: we cannot see whether the way is clear.
            if (giveWayBrakeRequest > skewBrakeFloor) skewBrakeFloor = giveWayBrakeRequest;
            // (4c) iter-49 B3: the Assistive-mode pull-over governor. Unlike every
            //      other term here this one is REQUESTED by the driver, so it is
            //      allowed to govern all the way down to a crawl — but it is still
            //      only a brake floor. The player keeps the wheel and can drive out
            //      of it at any time, which is the whole Assistive-mode contract.
            if (pullOverBrakeRequest > skewBrakeFloor) skewBrakeFloor = pullOverBrakeRequest;

            // ---- iter-30 P1: DEGENERATE-PATH CURVE GOVERNOR ----
            // The polyline turn-scan below needs >=3 points, but the path routinely
            // collapses to 1-2 points exactly at a node where the NEXT link defines a
            // sharp bend (iter-29 #1: 2pts -> 1pt at a ~95 deg bend, 33.5 m/s, no brake
            // -> airborne off-road, ~-269 bh across the cascade). When the polyline can't
            // see the bend, consult the in-memory NodeGraph at the lead point: the road
            // continues along the outgoing link best aligned with our travel direction,
            // and its deviation from straight-ahead IS the bend angle. Brake toward a
            // corner-safe speed before we reach it. Only RAISES the skew floor.
            if (pathPolyline.Count >= 1 && pathPolyline.Count < 3
                && veh.Speed > LANE_END_SAFE_SPEED + 1f && NodeGraph.IsLoaded)
            {
                GTA.Math.Vector3 leadPt = pathPolyline[pathPolyline.Count - 1];
                float gvx, gvy;
                if (pathPolyline.Count >= 2)
                { gvx = pathPolyline[1].X - pathPolyline[0].X; gvy = pathPolyline[1].Y - pathPolyline[0].Y; }
                else
                { float hRad = veh.Heading * 0.017453293f; gvx = -(float)Math.Sin(hRad); gvy = (float)Math.Cos(hRad); }
                float gvl = (float)Math.Sqrt(gvx * gvx + gvy * gvy);
                float distToNode = (leadPt - veh.Position).Length();
                float degTurn = 0f;
                if (gvl > 0.01f && distToNode > 1f)
                {
                    gvx /= gvl; gvy /= gvl;
                    int nIdx = NodeGraph.FindNearestNode(leadPt, JUNCTION_SNAP_RADIUS * 2f);
                    if (nIdx >= 0)
                    {
                        GTA.Math.Vector3 np = NodeGraph.GetPosition(nIdx);
                        int lc = NodeGraph.GetLinkCount(nIdx);
                        float bestDot = -2f;
                        // iter-32 R5: with restriction-aware routing on, a Disabled/
                        // no-nav neighbour is not a plausible road continuation.
                        bool skipDisabled = getSetting("restrictionAwareWalk") == 1;
                        for (int j = 0; j < lc; j++)
                        {
                            int tgt, lf, lb;
                            NodeGraph.GetLink(nIdx, j, out tgt, out lf, out lb);
                            if (skipDisabled && (NodeGraph.GetExtFlags(tgt)
                                & (NodeGraph.ExtFlags.Disabled | NodeGraph.ExtFlags.DontUseForNav)) != 0)
                                continue;
                            GTA.Math.Vector3 tp = NodeGraph.GetPosition(tgt);
                            float dxn = tp.X - np.X, dyn = tp.Y - np.Y;
                            float dl = (float)Math.Sqrt(dxn * dxn + dyn * dyn);
                            if (dl < 0.01f) continue;
                            float dn = (dxn / dl) * gvx + (dyn / dl) * gvy;
                            if (dn > bestDot) bestDot = dn; // the through-link (road continuation)
                        }
                        if (bestDot > -2f)
                        {
                            if (bestDot > 1f) bestDot = 1f; else if (bestDot < -1f) bestDot = -1f;
                            degTurn = (float)(Math.Acos(bestDot) * 57.29578);
                        }
                    }
                }
                if (degTurn >= CURVE_SHARP_ANGLE_DEG)
                {
                    float govLookahead = Math.Max(15f, veh.Speed * 2.2f);
                    if (distToNode < govLookahead)
                    {
                        float govSafe = degTurn >= 70f ? JUNCTION_SLOW_SPEED : LANE_END_SAFE_SPEED + 3f;
                        if (veh.Speed > govSafe)
                        {
                            float govOver = (veh.Speed - govSafe) / 12f;
                            float govFloor = Math.Min(CurveFloorCap(veh.Speed), 0.35f + 0.45f * govOver);
                            if (govFloor > skewBrakeFloor) skewBrakeFloor = govFloor;
                            if (driveLogger != null && driveLogger.IsRunning
                                && DateTime.Now.Ticks - lastCurveGovLogTicks > 10000000)
                            {
                                lastCurveGovLogTicks = DateTime.Now.Ticks;
                                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT curve-governor:"
                                    + " deg=" + degTurn.ToString("F0")
                                    + " distNode=" + distToNode.ToString("F1")
                                    + " spd=" + veh.Speed.ToString("F1")
                                    + " safe=" + govSafe.ToString("F1")
                                    + " brake=" + govFloor.ToString("F2"));
                            }
                        }
                    }
                }
            }

            if (pathPolyline.Count < 3) { curveBrakeStreak = 0; return skewBrakeFloor; }
            float speed = veh.Speed;
            if (speed < 4f) { curveBrakeStreak = 0; return skewBrakeFloor; }

            int start = lastClosestPolySeg;
            if (start < 0) start = 0;

            float maxTurnDeg = 0f;
            float distToTurn = 0f;
            float curveSegLen = 0f;
            float arc = 0f;
            GTA.Math.Vector3 bendVertex = pathPolyline[Math.Min(start, pathPolyline.Count - 1)];

            // iter-24 L2: scale the inspected point count with speed. A fixed 3
            // points (~36 m) let a 68 m/s car see a bend only ~0.5 s out — far too
            // late to shed 60 m/s. ~8 points (~96 m) at highway speed lets the L1
            // brake actually arrive in time; the distToTurn gate below still uses
            // the meta brake-lookahead so detection and braking distance agree.
            int lookaheadPts = Math.Min(8, CURVE_BRAKE_LOOKAHEAD_PTS + (int)(speed / 10f));

            for (int i = start; i < pathPolyline.Count - 2
                                && (i - start) < lookaheadPts; i++)
            {
                GTA.Math.Vector3 a = pathPolyline[i];
                GTA.Math.Vector3 b = pathPolyline[i + 1];
                GTA.Math.Vector3 c = pathPolyline[i + 2];
                float d1x = b.X - a.X, d1y = b.Y - a.Y;
                float d2x = c.X - b.X, d2y = c.Y - b.Y;
                float l1 = (float)Math.Sqrt(d1x * d1x + d1y * d1y);
                float l2 = (float)Math.Sqrt(d2x * d2x + d2y * d2y);
                if (l1 < 0.5f || l2 < 0.5f) { arc += l1; continue; }
                d1x /= l1; d1y /= l1; d2x /= l2; d2y /= l2;
                float dot = d1x * d2x + d1y * d2y;
                float cross = d1x * d2y - d1y * d2x;
                float turnDeg = Math.Abs((float)(Math.Atan2(cross, dot) * 57.29578));
                if (turnDeg > maxTurnDeg)
                {
                    maxTurnDeg = turnDeg;
                    distToTurn = arc + l1;          // arc length to vertex b (the bend)
                    curveSegLen = Math.Min(l1, l2);
                    bendVertex = b;                 // iter-24 L3: the turn vertex for junction lookup
                }
                arc += l1;
            }

            if (maxTurnDeg < CURVE_SHARP_ANGLE_DEG) { curveBrakeStreak = 0; return skewBrakeFloor; }

            // Turn radius from chord/angle: R ~= s / (2 sin(theta/2)).
            float turnRad = maxTurnDeg / 57.29578f;
            float sinHalf = (float)Math.Sin(turnRad / 2f);
            if (sinHalf < 0.01f) { curveBrakeStreak = 0; return skewBrakeFloor; }
            float R = curveSegLen / (2f * sinHalf);
            float vSafePhysics = (float)Math.Sqrt(CURVE_LATERAL_ACCEL_MAX * R);

            // META-INFORMED TARGET SPEED (iter-8). The physics-only vSafe
            // ignores vehicle class — a sports car and a truck see the same
            // limit at the same radius even though their grip differs. GTA V's
            // own AI uses an angle->speed table per vehicle handling class;
            // fold that in as a second upper bound and take the more
            // conservative of the two. min() keeps us safe even if the meta
            // table is generous at a given angle (physics still applies).
            var aiInfo = VehicleAIHandlingRegistry.GetForVehicle(veh);
            float vSafeMeta = aiInfo.MaxSpeedForAngle(maxTurnDeg);
            float vSafe = Math.Min(vSafePhysics, vSafeMeta);

            // ---- iter-24 L3: JUNCTION (INTERSECTION) GOVERNOR ----
            // Fuse the polyline turn with the shipped NodeGraph: if the bend
            // vertex sits on a junction node, treat it as an intersection —
            // announce it (Full mode) and slow to a junction-safe cornering
            // speed so the L1 cap gives the brake full authority. The two
            // 06-12 collisions were both 100-152 mph straight through a turning
            // junction. NodeGraph is in-memory; no per-frame native query.
            bool junctionAhead = false;
            if (NodeGraph.IsLoaded)
            {
                int jn = NodeGraph.FindNearestNode(bendVertex, JUNCTION_SNAP_RADIUS,
                    NodeGraph.NodeFlags.Junction, NodeGraph.NodeFlags.None);
                junctionAhead = jn >= 0;
            }
            if (junctionAhead && vSafe > JUNCTION_SLOW_SPEED)
                vSafe = JUNCTION_SLOW_SPEED;

            // Announce on approach (Full mode; Assisted mode already cues "Curve
            // ahead" in ProcessSteeringAssist). Throttled so a long junction
            // approach speaks once, not every scan.
            if (junctionAhead && cachedIsFullMode && speed > LANE_END_SAFE_SPEED
                && distToTurn > 0.5f
                && distToTurn < aiInfo.BrakeLookaheadForSpeed(speed) * 1.3f
                && DateTime.Now.Ticks - lastJunctionCueTicks > 40000000L) // ~4 s
            {
                lastJunctionCueTicks = DateTime.Now.Ticks;
                Speech.Info("Intersection ahead");
                TriggerRumble(0.35f, 150);
            }

            if (speed <= vSafe) { curveBrakeStreak = 0; return skewBrakeFloor; }
            // Only brake when the bend is close enough to matter. The lookahead
            // distance comes from the meta's class-aware brake-distance
            // triplet (MinBrakeDistance / MaxBrakeDistance /
            // MaxSpeedAtBrakeDistance) instead of the old class-agnostic
            // `speed * 3f`. Trucks (Max=120m) get longer lookahead than
            // sports cars (Max=120m but Min=8m). 1.3x margin so brake has
            // time to ramp up rather than firing at the last possible moment.
            float lookahead = aiInfo.BrakeLookaheadForSpeed(speed) * 1.3f;
            if (lookahead < 6f) lookahead = 6f;
            if (distToTurn < 0.5f || distToTurn > lookahead)
            {
                curveBrakeStreak = 0;
                return skewBrakeFloor;
            }

            // Persistence guard: require the same conclusion two scans running
            // so a single noisy polyline frame can't trigger a brake.
            // (Kept as a local streak instead of migrating to the rolling
            // history buffer — adding a curve-intent field to the snapshot
            // just for this one consumer would be exactly the kind of bloat
            // the buffer rationale calls out.)
            curveBrakeStreak++;
            if (curveBrakeStreak < 2) return skewBrakeFloor;

            float decel = (speed * speed - vSafe * vSafe) / (2f * Math.Max(distToTurn, 1f));
            float brake = decel / 6.0f;            // ~6 m/s^2 firm braking maps to 1.0
            if (brake < 0f) brake = 0f;
            // iter-24 L1: cap scales from the 0.6 comfort limit toward full brake
            // as over-speed for this bend grows (a turning junction's lowered
            // vSafe already forces near-full authority). Modest 10-15% over still
            // feels gentle; the -347/-202.7 blow-throughs now get real braking.
            float curveCap = CurveBrakeCap(speed, vSafe);
            if (brake > curveCap) brake = curveCap;
            // Iter-10 Patch D: skew floor wins if larger than the curve-
            // driven brake (the car is already misaligned, so brake harder
            // than the curve table alone would suggest).
            if (skewBrakeFloor > brake) brake = skewBrakeFloor;

            // iter-24 L3: telemetry for the junction governor (throttled ~1/s).
            if (junctionAhead && driveLogger != null && driveLogger.IsRunning
                && DateTime.Now.Ticks - lastJunctionSlowLogTicks > 10000000L)
            {
                lastJunctionSlowLogTicks = DateTime.Now.Ticks;
                driveLogger.Write("[F" + driveLogFrameCount + "] EVENT junction-slow:"
                    + " dist=" + distToTurn.ToString("F1")
                    + " turnDeg=" + maxTurnDeg.ToString("F1")
                    + " vSafe=" + vSafe.ToString("F1")
                    + " speed=" + speed.ToString("F1")
                    + " brake=" + brake.ToString("F2"));
            }
            return brake;
        }

    }
}
